enum {
    /* attention_decode_mixed_kernel stores raw-window scores plus visible
     * compressed scores in shared memory.  The host routes larger unmasked
     * decode calls to the online attention kernel so this fixed buffer never
     * becomes an out-of-bounds write at long context. */
    DS4_CUDA_ATTENTION_SCORE_CAP = 8192u,
    DS4_CUDA_ATTENTION_RAW_SCORE_CAP = 256u,
    DS4_CUDA_TOPK_MERGE_GROUP = 8u
};

struct ds4_gpu_tensor {
    void *ptr;
    uint64_t bytes;
    int owner;
};

struct cuda_moe_route_request {
    volatile uint32_t sequence;
    uint32_t layer_index;
    uint32_t miss_count;
    uint32_t route_count;
    uint64_t gate_offset;
    uint64_t up_offset;
    uint64_t down_offset;
    uint64_t gate_expert_bytes;
    uint64_t down_expert_bytes;
    int32_t selected[6];
    float weights[6];
    int32_t hit_slots[6];
    uint32_t miss_routes[6];
};

struct ds4_gpu_async_read {
    void *host;
    uint64_t bytes;
    uint64_t *pending_bytes;
    uint32_t slots;
    cudaStream_t stream;
    cudaEvent_t *ready;
    cudaEvent_t *done;
    int *pending;
};

enum cuda_spex_prefetch_state : uint8_t {
    CUDA_SPEX_PREFETCH_FREE = 0,
    CUDA_SPEX_PREFETCH_QUEUED = 1,
    CUDA_SPEX_PREFETCH_LOADING = 2,
    CUDA_SPEX_PREFETCH_READY = 3,
    CUDA_SPEX_PREFETCH_IN_USE = 4,
    CUDA_SPEX_PREFETCH_RETIRING = 5,
};

struct cuda_spex_prefetch_slot {
    ds4_gpu_spex_job job;
