    int discard;
};

struct ds4_gpu_spex_queue {
    os_file_t file;
    uint64_t model_size;
    uint64_t gate_expert_bytes;
    uint64_t down_expert_bytes;
    uint64_t epoch;
    uint32_t slots;
    uint32_t expert_cap;
    cuda_spex_prefetch_slot *slot;
    char *host_gate;
    char *host_up;
    char *host_down;
    char *device_gate;
    char *device_up;
    char *device_down;
    cudaStream_t upload_stream;
    os_mutex_t mutex;
    os_cond_t cond;
    os_thread_t thread;
    int mutex_ready;
    int cond_ready;
    int thread_started;
    int stop;
    int disabled;
    uint64_t submitted;
    uint64_t dropped;
    uint64_t loaded;
    uint64_t matched;
    uint64_t hits;
    uint64_t no_hits;
    uint64_t late;
    uint64_t canceled;
    uint64_t poisoned;
    uint64_t errors;
    uint64_t bytes_read;
    uint64_t bytes_used;
};

extern "C" void ds4_gpu_async_read_free(ds4_gpu_async_read *readback);
extern "C" void ds4_gpu_spex_queue_destroy(ds4_gpu_spex_queue *queue);

typedef struct {
    uint8_t scales[CUDA_QK_K / 16];
    uint8_t qs[CUDA_QK_K / 4];
    uint16_t d;
    uint16_t dmin;
} cuda_block_q2_K;

typedef struct {
    float d;
    int8_t qs[CUDA_QK_K];
    int16_t bsums[CUDA_QK_K / 16];
} cuda_block_q8_K;

typedef struct {
    uint16_t d;
    uint16_t qs[CUDA_QK_K / 8];
} cuda_block_iq2_xxs;

typedef struct {
    uint16_t d;
    uint8_t  qs[CUDA_QK_K / 8];
    uint16_t qh[CUDA_QK_K / 32];
} cuda_block_iq1_s;

typedef struct {
    uint16_t d;
    uint8_t  qs[128 / 8];
} cuda_block_q1_0;

static_assert(sizeof(cuda_block_iq1_s) == 50,
              "IQ1_S must be 50 bytes per 256 weights");
static_assert(sizeof(cuda_block_q1_0) == 18,
              "Q1_0 must be 18 bytes per 128 weights");

