static void cuda_log_full_model_alloc_failure(uint64_t model_size,
                                              cudaError_t err,
                                              const char *mode) {
    size_t free_b = 0, total_b = 0;
    cudaError_t mem_err = cudaMemGetInfo(&free_b, &total_b);
    fprintf(stderr,
            "ds4: CUDA full-model allocation failed in %s mode: %s\n",
            mode ? mode : "copy",
            cudaGetErrorString(err));
    if (mem_err == cudaSuccess) {
        fprintf(stderr,
                "ds4: CUDA model image is %.2f GiB; device memory free %.2f GiB / total %.2f GiB\n",
                (double)model_size / 1073741824.0,
                (double)free_b / 1073741824.0,
                (double)total_b / 1073741824.0);
    }
#ifdef _WIN32
    fprintf(stderr,
            "ds4: Windows CUDA currently requires copying the full model image "
            "to device memory before startup; system RAM cannot satisfy this allocation.\n");
#else
    fprintf(stderr,
            "ds4: Full-model CUDA copy requires enough device memory for the whole "
            "model image; unset copy/preload options to allow Linux mapping/cache fallbacks.\n");
#endif
}

struct cuda_model_range {
    const void *host_base;
    uint64_t offset;
    uint64_t bytes;
    char *device_ptr;
    void *registered_base;
    char *registered_device_base;
    uint64_t registered_bytes;
    int host_registered;
    int arena_allocated;
    int streamed;              /* 1 => device_ptr is an owning cudaMalloc, LRU-evictable */
    uint64_t last_used_tick;   /* LRU recency stamp (0 for non-streamed) */
    int pinned;                /* G7 keep-hot: 1 => non-expert (attn/norm/router) weight,
                                * evicted only as a last resort so it stays resident and
                                * isn't re-streamed every token (experts are unpinned). */
    int persistent_override;   /* Non-streamed replacement for a model span; wins over
                                * windows, exact ranges, and covering fd-cache ranges. */
};

