static uint64_t cuda_round_down(uint64_t v, uint64_t align) {
    if (align <= 1) return v;
    return (v / align) * align;
}

static uint64_t cuda_round_up(uint64_t v, uint64_t align) {
    if (align <= 1) return v;
    const uint64_t rem = v % align;
    return rem == 0 ? v : v + (align - rem);
}

static void *cuda_align_ptr(void *ptr, uint64_t align) {
    if (align <= 1) return ptr;
    uintptr_t p = (uintptr_t)ptr;
    uintptr_t a = (uintptr_t)align;
    return (void *)(((p + a - 1u) / a) * a);
}

static int cuda_model_stage_pool_alloc(uint64_t bytes) {
    if (g_model_stage_bytes >= bytes) return 1;
    if (g_model_stage_bytes != 0 && g_model_upload_stream) {
        cudaError_t err = cudaStreamSynchronize(g_model_upload_stream);
        if (err != cudaSuccess) {
            fprintf(stderr,
                    "ds4: CUDA model staging resize drain failed: %s\n",
                    cudaGetErrorString(err));
            (void)cudaGetLastError();
            return 0;
        }
    }
    for (size_t i = 0; i < 4; i++) {
#ifdef _WIN32
        if (g_moe_io_event[i]) {
            (void)CloseHandle(g_moe_io_event[i]);
            g_moe_io_event[i] = NULL;
        }
        memset(&g_moe_io_ov[i], 0, sizeof(g_moe_io_ov[i]));
        g_moe_io_stage_used[i] = 0;
#endif
        if (g_model_stage_event[i]) {
            (void)cudaEventDestroy(g_model_stage_event[i]);
            g_model_stage_event[i] = NULL;
        }
        if (g_model_stage_raw[i]) {
            (void)cudaFreeHost(g_model_stage_raw[i]);
            g_model_stage_raw[i] = NULL;
            g_model_stage[i] = NULL;
        }
    }
    g_model_stage_bytes = 0;
    if (!g_model_upload_stream) {
        cudaError_t err = cudaStreamCreateWithFlags(&g_model_upload_stream, cudaStreamNonBlocking);
        if (err != cudaSuccess) {
            fprintf(stderr, "ds4: CUDA model upload stream creation failed: %s\n", cudaGetErrorString(err));
            (void)cudaGetLastError();
            return 0;
        }
    }
    for (size_t i = 0; i < 4; i++) {
        cudaError_t err = cudaMallocHost(&g_model_stage_raw[i], (size_t)bytes);
        if (err != cudaSuccess) {
            fprintf(stderr, "ds4: CUDA pinned model staging allocation failed: %s\n", cudaGetErrorString(err));
            (void)cudaGetLastError();
            return 0;
        }
        g_model_stage[i] = cuda_align_ptr(g_model_stage_raw[i], g_model_direct_align);
        err = cudaEventCreateWithFlags(&g_model_stage_event[i], cudaEventDisableTiming);
        if (err != cudaSuccess) {
            fprintf(stderr, "ds4: CUDA model staging event creation failed: %s\n", cudaGetErrorString(err));
            (void)cudaGetLastError();
            return 0;
        }
    }
    g_model_stage_bytes = bytes;
    return 1;
}

static int cuda_pread_full(const os_file_t *file, void *buf, uint64_t bytes, uint64_t offset) {
    int64_t n = os_pread(file, buf, bytes, offset);
    return n >= 0 && (uint64_t)n == bytes;
}

static uint32_t cuda_nested_read_u32(const uint8_t *p) {
    return (uint32_t)p[0] |
           ((uint32_t)p[1] << 8) |
           ((uint32_t)p[2] << 16) |
           ((uint32_t)p[3] << 24);
}

static uint64_t cuda_nested_read_u64(const uint8_t *p) {
    return (uint64_t)cuda_nested_read_u32(p) |
           ((uint64_t)cuda_nested_read_u32(p + 4) << 32);
}

static int cuda_nested_mul_u64(uint64_t a, uint64_t b, uint64_t *out) {
    if (!out || (a != 0 && b > UINT64_MAX / a)) return 0;
    *out = a * b;
    return 1;
}

static uint32_t cuda_nested_crc32_continue(
        uint32_t crc, const uint8_t *data, size_t bytes) {
    crc = ~crc;
    for (size_t i = 0; i < bytes; i++) {
        crc ^= data[i];
        for (uint32_t bit = 0; bit < 8; bit++) {
            crc = (crc >> 1) ^ (0xedb88320u & (0u - (crc & 1u)));
        }
    }
    return ~crc;
}

static int cuda_nested_hex_matches(
        const char *name, const uint8_t expected[32]) {
    const char *text = getenv(name);
    if (!text || strlen(text) != 64u) {
        fprintf(stderr, "ds4: nested residual requires %s=<64 hex>\n", name);
        return 0;
    }
    for (uint32_t i = 0; i < 32u; i++) {
        unsigned int value = 0;
        if (sscanf(text + i * 2u, "%2x", &value) != 1 ||
            (uint8_t)value != expected[i]) {
            fprintf(stderr, "ds4: nested residual %s mismatch\n", name);
            return 0;
        }
    }
    return 1;
}

static void cuda_nested_extract_base_block(
        uint32_t source_type, const uint8_t *native, uint8_t *base) {
    if (source_type == 16u) {
        memcpy(base, native, 2u);
        for (uint32_t group = 0; group < 8u; group++) {
            memcpy(base + 2u + group * 4u,
                   native + 6u + group * 8u, 4u);
        }
        return;
    }
    memcpy(base, native, 16u);
    memcpy(base + 16u, native + 80u, 4u);
    memset(base + 20u, 0, 32u);
    const uint8_t *qs = native + 16u;
    for (uint32_t group = 0; group < 16u; group++) {
        const uint32_t within = group & 7u;
        const uint32_t qbase = (group >> 3u) * 32u +
            ((within & 1u) ? 16u : 0u);
        const uint32_t shift = (within >> 1u) * 2u;
        for (uint32_t lane = 0; lane < 16u; lane++) {
            const uint32_t linear = group * 16u + lane;
            const uint8_t msb = (uint8_t)((qs[qbase + lane] >>
                                           (shift + 1u)) & 1u);
            base[20u + (linear >> 3u)] |=
                (uint8_t)(msb << (linear & 7u));
        }
    }
}

static void cuda_nested_join_block(
        uint32_t source_type, const uint8_t *base,
        const uint8_t *residual, uint8_t *native) {
    if (source_type == 16u) {
        memcpy(native, base, 2u);
        for (uint32_t group = 0; group < 8u; group++) {
            memcpy(native + 2u + group * 8u,
                   residual + group * 4u, 4u);
            memcpy(native + 6u + group * 8u,
                   base + 2u + group * 4u, 4u);
        }
        return;
    }
    memcpy(native, base, 16u);
    memset(native + 16u, 0, 64u);
    memcpy(native + 80u, base + 16u, 4u);
    uint8_t *qs = native + 16u;
    const uint8_t *base_bits = base + 20u;
    for (uint32_t linear = 0; linear < 256u; linear++) {
        const uint32_t group = linear >> 4u;
        const uint32_t lane = linear & 15u;
        const uint32_t within = group & 7u;
        const uint32_t qbase = (group >> 3u) * 32u +
            ((within & 1u) ? 16u : 0u);
        const uint32_t shift = (within >> 1u) * 2u;
        const uint8_t msb =
            (uint8_t)((base_bits[linear >> 3u] >> (linear & 7u)) & 1u);
        const uint8_t lsb =
            (uint8_t)((residual[linear >> 3u] >> (linear & 7u)) & 1u);
        qs[qbase + lane] |= (uint8_t)(((msb << 1u) | lsb) << shift);
    }
}

__global__ static void cuda_nested_join_blocks_kernel(
        uint32_t source_type,
        const uint8_t *base,
        const uint8_t *residual,
        uint8_t *native,
        uint64_t blocks,
        uint32_t base_block_bytes,
        uint32_t residual_block_bytes,
        uint32_t native_block_bytes) {
    const uint64_t block = (uint64_t)blockIdx.x * blockDim.x + threadIdx.x;
    if (block >= blocks) return;
    const uint8_t *src_base = base + block * base_block_bytes;
    const uint8_t *src_residual = residual + block * residual_block_bytes;
    uint8_t *dst_native = native + block * native_block_bytes;
    if (source_type == 16u) {
        dst_native[0] = src_base[0];
        dst_native[1] = src_base[1];
        for (uint32_t group = 0; group < 8u; group++) {
            const uint32_t native_off = 2u + group * 8u;
            const uint32_t residual_off = group * 4u;
            const uint32_t base_off = 2u + group * 4u;
            for (uint32_t i = 0; i < 4u; i++) {
                dst_native[native_off + i] =
                    src_residual[residual_off + i];
                dst_native[native_off + 4u + i] =
                    src_base[base_off + i];
            }
        }
        return;
    }
    for (uint32_t i = 0; i < 16u; i++) dst_native[i] = src_base[i];
    for (uint32_t i = 0; i < 64u; i++) dst_native[16u + i] = 0u;
    for (uint32_t i = 0; i < 4u; i++) dst_native[80u + i] =
        src_base[16u + i];
    uint8_t *qs = dst_native + 16u;
    const uint8_t *base_bits = src_base + 20u;
    for (uint32_t linear = 0; linear < 256u; linear++) {
        const uint32_t group = linear >> 4u;
        const uint32_t lane = linear & 15u;
        const uint32_t within = group & 7u;
        const uint32_t qbase = (group >> 3u) * 32u +
            ((within & 1u) ? 16u : 0u);
        const uint32_t shift = (within >> 1u) * 2u;
        const uint8_t msb =
            (uint8_t)((base_bits[linear >> 3u] >> (linear & 7u)) & 1u);
        const uint8_t lsb =
            (uint8_t)((src_residual[linear >> 3u] >>
                       (linear & 7u)) & 1u);
        qs[qbase + lane] |= (uint8_t)(((msb << 1u) | lsb) << shift);
    }
}

static int cuda_nested_residual_env_flag(const char *name) {
    const char *value = getenv(name);
    if (!value || !value[0] || strcmp(value, "0") == 0) return 0;
    if (strcmp(value, "1") == 0) return 1;
    fprintf(stderr, "ds4: invalid %s=%s (expected 0 or 1)\n", name, value);
    return -1;
}

static uint64_t cuda_nested_residual_base_pinned_budget(void) {
    const char *value = getenv("DS4_NESTED_RESIDUAL_BASE_PINNED_GIB");
    if (!value || !value[0]) return UINT64_MAX;
    char *end = NULL;
    errno = 0;
    const double gib = strtod(value, &end);
    while (end && (*end == ' ' || *end == '\t')) end++;
    if (end == value || errno != 0 || !end || *end != '\0' ||
        !std::isfinite(gib) || gib < 0.0 || gib > 30.0) {
        fprintf(stderr,
                "ds4: invalid DS4_NESTED_RESIDUAL_BASE_PINNED_GIB=%s\n",
                value);
        return UINT64_MAX - 1u;
    }
    const long double bytes = (long double)gib * 1073741824.0L;
    if (bytes > (long double)UINT64_MAX) return UINT64_MAX - 1u;
    return (uint64_t)bytes;
}

static uint8_t *cuda_nested_residual_pageable_alloc(uint64_t bytes) {
    if (bytes == 0 || bytes > (uint64_t)SIZE_MAX) return NULL;
#ifdef _WIN32
    return (uint8_t *)VirtualAlloc(
        NULL, (SIZE_T)bytes, MEM_RESERVE | MEM_COMMIT, PAGE_READWRITE);
#else
    return (uint8_t *)malloc((size_t)bytes);
#endif
}

static void cuda_nested_residual_pageable_free(uint8_t *ptr) {
    if (!ptr) return;
#ifdef _WIN32
    (void)VirtualFree(ptr, 0, MEM_RELEASE);
#else
    free(ptr);
#endif
}

static void cuda_nested_residual_note_cache_invariant_failure(
        cuda_nested_residual_state &state) {
    state.residual_cache_invariant_failures++;
    if (state.cache_pageable) state.cache_pageable_invariant_failures++;
}

static const uint8_t *cuda_nested_residual_base_expert(
        cuda_nested_residual_state &state,
        uint32_t layer,
        uint32_t expert,
        uint8_t *pageable_out) {
    if (pageable_out) *pageable_out = 0;
    if (layer >= CUDA_NESTED_RESIDUAL_LAYER_COUNT ||
        expert >= CUDA_NESTED_RESIDUAL_EXPERT_COUNT) {
        return NULL;
    }
    const size_t index = (size_t)layer *
        CUDA_NESTED_RESIDUAL_EXPERT_COUNT + expert;
    if (index >= state.base_by_layer_expert.size() ||
        index >= state.base_storage_by_layer_expert.size() ||
        !state.base_by_layer_expert[index]) {
        return NULL;
    }
    if (pageable_out) {
        *pageable_out = state.base_storage_by_layer_expert[index];
    }
    return state.base_by_layer_expert[index];
}

static void cuda_nested_residual_clear(void) {
    cuda_nested_residual_state &state = g_nested_residual;
    if (state.active || state.failures != 0) {
        const uint32_t nested_residual_base_pinned_entries =
            state.base_pinned_entries;
        const uint32_t nested_residual_base_pageable_entries =
            state.base_pageable_entries;
        const uint64_t nested_residual_base_pinned_bytes =
            state.base_pinned_bytes;
        const uint64_t nested_residual_base_pageable_bytes =
            state.base_pageable_bytes;
        const uint64_t nested_residual_base_pinned_hits =
            state.base_pinned_hits;
        const uint64_t nested_residual_base_pageable_hits =
            state.base_pageable_hits;
        const uint64_t nested_residual_base_pinned_h2d_bytes =
            state.base_pinned_h2d_bytes;
        const uint64_t nested_residual_base_pageable_h2d_bytes =
            state.base_pageable_h2d_bytes;
        const uint32_t nested_residual_cache_pinned_entries =
            state.cache_pageable ? 0u : state.cache_count;
        const uint32_t nested_residual_cache_pageable_entries =
            state.cache_pageable ? state.cache_count : 0u;
        const uint64_t nested_residual_cache_pinned_bytes =
            state.cache_pageable ? 0u : state.cache_bytes;
        const uint64_t nested_residual_cache_pageable_bytes =
            state.cache_pageable ? state.cache_bytes : 0u;
        const uint64_t nested_residual_cache_pinned_hits =
            state.cache_pageable ? 0u : state.residual_cache_hits;
        const uint64_t nested_residual_cache_pageable_hits =
            state.cache_pageable ? state.residual_cache_hits : 0u;
        const uint64_t nested_residual_cache_pinned_h2d_bytes =
            state.cache_pageable ? 0u : state.residual_cache_h2d_bytes;
        const uint64_t nested_residual_cache_pageable_h2d_bytes =
            state.cache_pageable ? state.residual_cache_h2d_bytes : 0u;
        uint32_t nested_residual_cache_layer_slots_min =
            state.cache_capacity;
        uint32_t nested_residual_cache_layer_slots_max =
            state.cache_capacity;
        if (state.cache_layer_partitioned) {
            nested_residual_cache_layer_slots_min = UINT32_MAX;
            nested_residual_cache_layer_slots_max = 0;
            for (uint32_t layer = 0;
                 layer < CUDA_NESTED_RESIDUAL_LAYER_COUNT; layer++) {
                if (!state.layers[layer].ready) continue;
                nested_residual_cache_layer_slots_min = std::min(
                    nested_residual_cache_layer_slots_min,
                    state.cache_layer_capacity[layer]);
                nested_residual_cache_layer_slots_max = std::max(
                    nested_residual_cache_layer_slots_max,
                    state.cache_layer_capacity[layer]);
            }
        }
        const uint64_t summary_cache_hits = state.residual_cache_enabled
            ? state.residual_cache_hits : state.exact_cache_hits;
        const uint64_t summary_cache_misses = state.residual_cache_enabled
            ? state.residual_cache_misses : state.exact_cache_misses;
        fprintf(stderr,
                "ds4: [nested-residual] result=summary router=open "
                "router_calls=%llu "
                "cache_hits=%llu cache_misses=%llu residual_preads=%llu "
                "residual_bytes=%llu reconstructed=%llu mismatches=%llu "
                "h2d_bytes=%llu failures=%llu\n",
                (unsigned long long)state.router_open_calls,
                (unsigned long long)summary_cache_hits,
                (unsigned long long)summary_cache_misses,
                (unsigned long long)state.residual_preads,
                (unsigned long long)state.residual_bytes,
                (unsigned long long)state.reconstructed_experts,
                (unsigned long long)state.reconstruction_mismatches,
                (unsigned long long)state.h2d_bytes,
                (unsigned long long)state.failures);
        if (state.pageable_base_enabled) {
            fprintf(stderr,
                    "ds4: [nested-residual-base-storage] result=summary "
                    "pinned_entries=%u pinned_bytes=%llu pinned_hits=%llu "
                    "pinned_h2d_bytes=%llu pageable_entries=%u "
                    "pageable_bytes=%llu pageable_hits=%llu "
                    "pageable_h2d_bytes=%llu invariant_failures=%llu "
                    "mapped=0 router=open exact=1\n",
                    nested_residual_base_pinned_entries,
                    (unsigned long long)nested_residual_base_pinned_bytes,
                    (unsigned long long)nested_residual_base_pinned_hits,
                    (unsigned long long)
                        nested_residual_base_pinned_h2d_bytes,
                    nested_residual_base_pageable_entries,
                    (unsigned long long)nested_residual_base_pageable_bytes,
                    (unsigned long long)nested_residual_base_pageable_hits,
                    (unsigned long long)
                        nested_residual_base_pageable_h2d_bytes,
                    (unsigned long long)state.storage_invariant_failures);
        }
        if (state.cache_pageable) {
            fprintf(stderr,
                    "ds4: [nested-residual-cache-pageable] result=summary "
                    "pinned_entries=%u pinned_bytes=%llu pinned_hits=%llu "
                    "pinned_h2d_bytes=%llu pageable_entries=%u "
                    "pageable_bytes=%llu pageable_hits=%llu "
                    "pageable_h2d_bytes=%llu cached_join_calls=%llu "
                    "partitioned=%u layer_slots_min=%u layer_slots_max=%u "
                    "invariant_failures=%llu mapped=0 router=open exact=1\n",
                    nested_residual_cache_pinned_entries,
                    (unsigned long long)nested_residual_cache_pinned_bytes,
                    (unsigned long long)nested_residual_cache_pinned_hits,
                    (unsigned long long)
                        nested_residual_cache_pinned_h2d_bytes,
                    nested_residual_cache_pageable_entries,
                    (unsigned long long)nested_residual_cache_pageable_bytes,
                    (unsigned long long)nested_residual_cache_pageable_hits,
                    (unsigned long long)
                        nested_residual_cache_pageable_h2d_bytes,
                    (unsigned long long)
                        state.residual_cache_cached_join_calls,
                    (unsigned)state.cache_layer_partitioned,
                    nested_residual_cache_layer_slots_min,
                    nested_residual_cache_layer_slots_max,
                    (unsigned long long)
                        state.cache_pageable_invariant_failures);
        }
        if (cuda_nested_residual_gpu_cache_requested() ||
            state.gpu_route_calls != 0 || state.gpu_cache_failures != 0) {
            fprintf(stderr,
                    "ds4: [nested-residual-vram] result=summary "
                    "route_calls=%llu hits=%llu misses=%llu "
                    "host_fills=%llu host_bytes=%llu h2d_bytes=%llu "
                    "failures=%llu\n",
                    (unsigned long long)state.gpu_route_calls,
                    (unsigned long long)state.gpu_route_hits,
                    (unsigned long long)state.gpu_route_misses,
                    (unsigned long long)state.route_host_fills,
                    (unsigned long long)state.route_host_bytes,
                    (unsigned long long)state.route_h2d_bytes,
                    (unsigned long long)state.gpu_cache_failures);
        }
        if (state.gpu_join_requested_flag || state.gpu_join_requested ||
            state.gpu_join_observed || state.gpu_join_calls ||
            state.gpu_join_failures) {
            fprintf(stderr,
                    "ds4: [nested-residual-gpu-join] result=summary "
                    "gpu_join_requested=%llu gpu_join_observed=%llu "
                    "gpu_join_calls=%llu gpu_join_blocks=%llu "
                    "gpu_join_base_h2d_bytes=%llu "
                    "gpu_join_residual_h2d_bytes=%llu "
                    "gpu_join_native_h2d_bytes=%llu gpu_join_seconds=%.9f "
                    "gpu_join_verify_calls=%llu gpu_join_verify_bytes=%llu "
                    "gpu_join_verify_mismatches=%llu "
                    "gpu_join_verify_seconds=%.9f "
                    "gpu_join_wait_calls=%llu "
                    "gpu_join_wait_seconds=%.9f "
                    "gpu_join_failures=%llu "
                    "gpu_join_cpu_reconstruct_calls=%llu\n",
                    (unsigned long long)state.gpu_join_requested,
                    (unsigned long long)state.gpu_join_observed,
                    (unsigned long long)state.gpu_join_calls,
                    (unsigned long long)state.gpu_join_blocks,
                    (unsigned long long)state.gpu_join_base_h2d_bytes,
                    (unsigned long long)state.gpu_join_residual_h2d_bytes,
                    (unsigned long long)state.gpu_join_native_h2d_bytes,
                    state.gpu_join_seconds,
                    (unsigned long long)state.gpu_join_verify_calls,
                    (unsigned long long)state.gpu_join_verify_bytes,
                    (unsigned long long)state.gpu_join_verify_mismatches,
                    state.gpu_join_verify_seconds,
                    (unsigned long long)state.gpu_join_wait_calls,
                    state.gpu_join_wait_seconds,
                    (unsigned long long)state.gpu_join_failures,
                    (unsigned long long)state.gpu_join_cpu_reconstruct_calls);
        }
        if (state.residual_cache_requested_flag ||
            state.residual_cache_enabled ||
            state.residual_cache_hits || state.residual_cache_misses ||
            state.residual_cache_invariant_failures) {
            fprintf(stderr,
                    "ds4: [nested-residual-residual-cache] result=summary "
                    "enabled=%u hits=%llu misses=%llu evictions=%llu "
                    "entries=%u capacity=%u pread_bytes=%llu "
                    "pread_bytes_avoided=%llu h2d_bytes=%llu "
                    "cached_join_calls=%llu invariant_failures=%llu\n",
                    (unsigned)state.residual_cache_enabled,
                    (unsigned long long)state.residual_cache_hits,
                    (unsigned long long)state.residual_cache_misses,
                    (unsigned long long)state.residual_cache_evictions,
                    state.cache_count,
                    state.cache_capacity,
                    (unsigned long long)state.residual_cache_pread_bytes,
                    (unsigned long long)state.residual_cache_pread_bytes_avoided,
                    (unsigned long long)state.residual_cache_h2d_bytes,
                    (unsigned long long)state.residual_cache_cached_join_calls,
                    (unsigned long long)state.residual_cache_invariant_failures);
        }
        if (state.profile_enabled) {
            const char *packed = getenv("DS4_CUDA_MOE_ROUTE_PACKED_COPY");
            const char *split_fused = getenv("DS4_CUDA_MOE_SPLIT_FUSED");
            fprintf(stderr,
                    "ds4: [nested-residual-profile] result=summary enabled=1 "
                    "lookup_calls=%llu lookup_s=%.9f "
                    "pread_calls=%llu pread_s=%.9f "
                    "reconstruct_calls=%llu reconstruct_blocks=%llu "
                    "reconstruct_s=%.9f verify_calls=%llu "
                    "verify_bytes=%llu verify_s=%.9f "
                    "reuse_wait_calls=%llu "
                    "reuse_wait_s=%.9f host_copy_calls=%llu "
                    "host_copy_s=%.9f h2d_enqueue_calls=%llu "
                    "h2d_enqueue_s=%.9f h2d_sync_calls=%llu "
                    "h2d_sync_s=%.9f route_begin_calls=%llu "
                    "route_begin_s=%.9f route_resolve_sync_calls=%llu "
                    "route_resolve_sync_s=%.9f route_ready_wait_calls=%llu "
                    "route_ready_wait_s=%.9f packed_copy=%d split_fused=%d "
                    "verify=%d\n",
                    (unsigned long long)state.profile_lookup_calls,
                    state.profile_lookup_seconds,
                    (unsigned long long)state.profile_pread_calls,
                    state.profile_pread_seconds,
                    (unsigned long long)state.profile_reconstruct_calls,
                    (unsigned long long)state.profile_reconstruct_blocks,
                    state.profile_reconstruct_seconds,
                    (unsigned long long)state.profile_verify_calls,
                    (unsigned long long)state.profile_verify_bytes,
                    state.profile_verify_seconds,
                    (unsigned long long)state.profile_reuse_wait_calls,
                    state.profile_reuse_wait_seconds,
                    (unsigned long long)state.profile_host_copy_calls,
                    state.profile_host_copy_seconds,
                    (unsigned long long)state.profile_h2d_enqueue_calls,
                    state.profile_h2d_enqueue_seconds,
                    (unsigned long long)state.profile_h2d_sync_calls,
                    state.profile_h2d_sync_seconds,
                    (unsigned long long)state.profile_route_begin_calls,
                    state.profile_route_begin_seconds,
                    (unsigned long long)state.profile_route_resolve_sync_calls,
                    state.profile_route_resolve_sync_seconds,
                    (unsigned long long)state.profile_route_ready_wait_calls,
                    state.profile_route_ready_wait_seconds,
                    packed && strcmp(packed, "1") == 0,
                    split_fused && strcmp(split_fused, "0") != 0,
                    getenv("DS4_NESTED_RESIDUAL_VERIFY_RECONSTRUCTION") != NULL);
        }
    }
    for (cuda_nested_residual_cache_slot &slot : state.cache_slots) {
        if (!slot.event_created) continue;
        if (slot.copy_pending) (void)cudaEventSynchronize(slot.reuse_event);
        (void)cudaEventDestroy(slot.reuse_event);
    }
    if (state.gpu_join_event_created) {
        if (state.gpu_join_event_pending) {
            (void)cudaEventSynchronize(state.gpu_join_done_event);
        }
        (void)cudaEventDestroy(state.gpu_join_done_event);
    }
    if (state.gpu_join_mutex_ready) {
        os_mutex_destroy(&state.gpu_join_mutex);
    }
    if (state.base) (void)cudaFreeHost(state.base);
    cuda_nested_residual_pageable_free(state.base_pageable);
    if (state.cache) {
        if (state.cache_pageable) {
            cuda_nested_residual_pageable_free(state.cache);
        } else {
            (void)cudaFreeHost(state.cache);
        }
    }
    if (state.gpu_join_residual_host)
        (void)cudaFreeHost(state.gpu_join_residual_host);
    if (state.gpu_join_verify_host)
        (void)cudaFreeHost(state.gpu_join_verify_host);
    if (state.gpu_join_base_device)
        (void)cudaFree(state.gpu_join_base_device);
    if (state.gpu_join_residual_device)
        (void)cudaFree(state.gpu_join_residual_device);
    if (state.file_valid) os_file_close(&state.file);
    state = cuda_nested_residual_state{};
    os_file_init(&state.file);
}

static int cuda_nested_residual_preload_base(void) {
    cuda_nested_residual_state &state = g_nested_residual;
    uint64_t total_base_bytes = 0;
    uint64_t max_base = 0;
    uint64_t max_native = 0;
    uint64_t max_residual = 0;
    uint32_t total_entries = 0;
    uint32_t nested_residual_all_layer_first_layer = UINT32_MAX;
    uint32_t nested_residual_all_layer_last_layer = 0;
    uint32_t nested_residual_all_layer_count = 0;
    for (uint32_t layer = 0; layer < CUDA_NESTED_RESIDUAL_LAYER_COUNT;
         layer++) {
        cuda_nested_residual_layer &entry = state.layers[layer];
        if (!entry.ready) continue;
        nested_residual_all_layer_first_layer = std::min(
            nested_residual_all_layer_first_layer, layer);
        nested_residual_all_layer_last_layer = std::max(
            nested_residual_all_layer_last_layer, layer);
        nested_residual_all_layer_count++;
        entry.base_offset = 0;
        if (entry.base_expert_bytes >
            (UINT64_MAX - total_base_bytes) /
                CUDA_NESTED_RESIDUAL_EXPERT_COUNT) {
            return 0;
        }
        total_base_bytes += entry.base_expert_bytes *
            CUDA_NESTED_RESIDUAL_EXPERT_COUNT;
        if (total_entries > UINT32_MAX -
                CUDA_NESTED_RESIDUAL_EXPERT_COUNT) return 0;
        total_entries += CUDA_NESTED_RESIDUAL_EXPERT_COUNT;
        max_base = std::max(max_base, entry.base_expert_bytes);
        max_native = std::max(max_native, entry.native_expert_bytes);
        max_residual = std::max(max_residual, entry.residual_expert_bytes);
    }
    if (total_base_bytes == 0 || total_entries == 0 || max_base == 0 ||
        max_native == 0 || max_residual == 0 ||
        max_base > UINT64_MAX / total_entries) return 0;

    state.gpu_join_requested_flag =
        cuda_nested_residual_gpu_join_requested() ? 1u : 0u;
    state.residual_cache_requested_flag =
        cuda_nested_residual_gpu_join_residual_cache_requested() ? 1u : 0u;
    state.residual_cache_enabled =
        state.gpu_join_requested_flag && state.residual_cache_requested_flag ?
        1u : 0u;
    const int pageable_base = cuda_nested_residual_env_flag(
        "DS4_NESTED_RESIDUAL_PAGEABLE_BASE");
    const int cache_pageable = cuda_nested_residual_env_flag(
        "DS4_NESTED_RESIDUAL_CACHE_PAGEABLE");
    const uint64_t pinned_budget =
        cuda_nested_residual_base_pinned_budget();
    if (pageable_base < 0 || cache_pageable < 0 ||
        pinned_budget == UINT64_MAX - 1u ||
        (pageable_base && pinned_budget == UINT64_MAX) ||
        (!pageable_base && pinned_budget != UINT64_MAX) ||
        (cache_pageable && !state.residual_cache_enabled)) {
        state.storage_invariant_failures++;
        fprintf(stderr,
                "ds4: nested residual base storage contract invalid "
                "pageable=%d pinned_budget=%llu cache_pageable=%d\n",
                pageable_base, (unsigned long long)pinned_budget,
                cache_pageable);
        return 0;
    }
    const int all_layer_storage = pageable_base || cache_pageable;
    if (all_layer_storage &&
        (nested_residual_all_layer_first_layer != 3u ||
         nested_residual_all_layer_last_layer != 42u ||
         nested_residual_all_layer_count != 40u)) {
        state.storage_invariant_failures++;
        fprintf(stderr,
                "ds4: all-layer nested sidecar coverage must be exactly "
                "layers 3..42 observed_first=%u observed_last=%u "
                "observed_count=%u\n",
                nested_residual_all_layer_first_layer,
                nested_residual_all_layer_last_layer,
                nested_residual_all_layer_count);
        return 0;
    }
    state.all_layer_storage = all_layer_storage ? 1u : 0u;
    state.pageable_base_enabled = pageable_base ? 1u : 0u;
    state.all_layer_first = nested_residual_all_layer_first_layer;
    state.all_layer_last = nested_residual_all_layer_last_layer;
    state.all_layer_count = nested_residual_all_layer_count;
    uint64_t pinned_entries64 = total_entries;
    if (pageable_base) {
        pinned_entries64 = std::min(
            (uint64_t)total_entries, pinned_budget / max_base);
    }
    const uint64_t pageable_entries64 =
        (uint64_t)total_entries - pinned_entries64;
    if (pageable_base &&
        (pinned_entries64 == 0 || pageable_entries64 == 0)) {
        state.storage_invariant_failures++;
        fprintf(stderr,
                "ds4: nested residual pageable base requires both storage "
                "classes pinned_entries=%llu pageable_entries=%llu\n",
                (unsigned long long)pinned_entries64,
                (unsigned long long)pageable_entries64);
        return 0;
    }
    const uint64_t pinned_bytes = pinned_entries64 * max_base;
    const uint64_t pageable_bytes = pageable_entries64 * max_base;
    if (pinned_bytes != 0 &&
        cudaHostAlloc((void **)&state.base, (size_t)pinned_bytes,
                      cudaHostAllocDefault) != cudaSuccess) {
        (void)cudaGetLastError();
        fprintf(stderr,
                "ds4: nested residual pinned base allocation failed bytes=%llu\n",
                (unsigned long long)pinned_bytes);
        return 0;
    }
    if (pageable_bytes != 0) {
        state.base_pageable =
            cuda_nested_residual_pageable_alloc(pageable_bytes);
        if (!state.base_pageable) {
            fprintf(stderr,
                    "ds4: nested residual pageable base allocation failed bytes=%llu\n",
                    (unsigned long long)pageable_bytes);
            return 0;
        }
    }
    state.base_bytes = pinned_bytes + pageable_bytes;
    state.base_pinned_bytes = pinned_bytes;
    state.base_pageable_bytes = pageable_bytes;
    state.base_pinned_entries = (uint32_t)pinned_entries64;
    state.base_pageable_entries = (uint32_t)pageable_entries64;
    state.max_residual_expert_bytes = max_residual;
    try {
        const size_t bindings = (size_t)CUDA_NESTED_RESIDUAL_LAYER_COUNT *
            CUDA_NESTED_RESIDUAL_EXPERT_COUNT;
        state.base_by_layer_expert.assign(bindings, NULL);
        state.base_storage_by_layer_expert.assign(bindings, 0u);
    } catch (...) {
        fprintf(stderr,
                "ds4: nested residual base metadata allocation failed\n");
        return 0;
    }

    uint64_t entry_cursor = 0;
    uint64_t pinned_cursor = 0;
    uint64_t pageable_cursor = 0;
    for (uint32_t layer = 0; layer < CUDA_NESTED_RESIDUAL_LAYER_COUNT;
         layer++) {
        cuda_nested_residual_layer &entry = state.layers[layer];
        if (!entry.ready) continue;
        uint32_t layer_pinned = 0;
        uint32_t layer_pageable = 0;
        for (uint32_t expert = 0;
             expert < CUDA_NESTED_RESIDUAL_EXPERT_COUNT; expert++) {
            const uint64_t pinned_before =
                entry_cursor * pinned_entries64 / total_entries;
            const uint64_t pinned_after =
                (entry_cursor + 1u) * pinned_entries64 / total_entries;
            const int use_pinned = pinned_after > pinned_before;
            uint8_t *expert_base = NULL;
            if (use_pinned) {
                expert_base = state.base + pinned_cursor++ * max_base;
                layer_pinned++;
            } else {
                expert_base = state.base_pageable +
                    pageable_cursor++ * max_base;
                layer_pageable++;
            }
            const size_t binding = (size_t)layer *
                CUDA_NESTED_RESIDUAL_EXPERT_COUNT + expert;
            state.base_by_layer_expert[binding] = expert_base;
            state.base_storage_by_layer_expert[binding] =
                use_pinned ? 0u : 1u;
            entry_cursor++;
            for (uint32_t part = 0;
                 part < CUDA_NESTED_RESIDUAL_PART_COUNT; part++) {
                const cuda_nested_residual_record &record =
                    entry.records[part];
                const uint64_t blocks =
                    (record.ncols / 256u) * record.nrows;
                const uint8_t *native = state.source_map +
                    record.source_offset +
                    (uint64_t)expert * record.native_kind_bytes;
                uint8_t *base = expert_base + record.base_kind_offset;
                for (uint64_t block = 0; block < blocks; block++) {
                    cuda_nested_extract_base_block(
                        record.source_type,
                        native + block * record.native_block_bytes,
                        base + block * record.base_block_bytes);
                }
            }
        }
        fprintf(stderr,
                "ds4: [nested-residual] base-ready layer=%u experts=256 "
                "bytes=%llu pinned_entries=%u pageable_entries=%u "
                "mapped=0\n",
                layer,
                (unsigned long long)(entry.base_expert_bytes * 256u),
                layer_pinned, layer_pageable);
    }
    if (entry_cursor != total_entries ||
        pinned_cursor != pinned_entries64 ||
        pageable_cursor != pageable_entries64) {
        state.storage_invariant_failures++;
        fprintf(stderr,
                "ds4: nested residual base partition invariant failed\n");
        return 0;
    }

    uint32_t cache_capacity = 6u;
    const char *cache_env = getenv("DS4_NESTED_RESIDUAL_CACHE_EXPERTS");
    if (cache_env && cache_env[0]) {
        char *end = NULL;
        const unsigned long value = strtoul(cache_env, &end, 10);
        const unsigned long maximum = cache_pageable ? 4096u : 64u;
        if (end == cache_env || *end != '\0' || value == 0 ||
            value > maximum) {
            fprintf(stderr,
                    "ds4: invalid DS4_NESTED_RESIDUAL_CACHE_EXPERTS=%s\n",
                    cache_env);
            return 0;
        }
        cache_capacity = (uint32_t)value;
    }
    state.cache_slot_bytes = state.residual_cache_enabled ?
        max_residual : max_native;
    if (state.cache_slot_bytes > UINT64_MAX / cache_capacity) return 0;
    state.cache_bytes = state.cache_slot_bytes * cache_capacity;
    state.cache_pageable = cache_pageable ? 1u : 0u;
    if (state.cache_pageable) {
        state.cache = cuda_nested_residual_pageable_alloc(state.cache_bytes);
    } else if (cudaHostAlloc((void **)&state.cache,
                             (size_t)state.cache_bytes,
                             cudaHostAllocDefault) != cudaSuccess) {
        (void)cudaGetLastError();
        state.cache = NULL;
    }
    if (!state.cache) {
        fprintf(stderr,
                "ds4: nested residual cache allocation failed bytes=%llu pageable=%u\n",
                (unsigned long long)state.cache_bytes,
                (unsigned)state.cache_pageable);
        return 0;
    }
    state.cache_capacity = cache_capacity;
    state.cache_slots.assign(cache_capacity,
                             cuda_nested_residual_cache_slot{});
    if (state.cache_pageable && state.all_layer_storage) {
        if (cache_capacity < nested_residual_all_layer_count) {
            fprintf(stderr,
                    "ds4: nested residual pageable cache requires at least "
                    "one slot per ready layer capacity=%u layers=%u\n",
                    cache_capacity, nested_residual_all_layer_count);
            return 0;
        }
        const uint32_t slots_per_layer =
            cache_capacity / nested_residual_all_layer_count;
        const uint32_t extra_slots =
            cache_capacity % nested_residual_all_layer_count;
        uint32_t slot_cursor = 0;
        uint32_t ready_cursor = 0;
        for (uint32_t layer = 0;
             layer < CUDA_NESTED_RESIDUAL_LAYER_COUNT; layer++) {
            if (!state.layers[layer].ready) continue;
            const uint32_t layer_capacity = slots_per_layer +
                (ready_cursor < extra_slots ? 1u : 0u);
            state.cache_layer_begin[layer] = slot_cursor;
            state.cache_layer_capacity[layer] = layer_capacity;
            slot_cursor += layer_capacity;
            ready_cursor++;
        }
        if (slot_cursor != cache_capacity ||
            ready_cursor != nested_residual_all_layer_count) {
            cuda_nested_residual_note_cache_invariant_failure(state);
            fprintf(stderr,
                    "ds4: nested residual cache partition invariant failed "
                    "slots=%u/%u layers=%u/%u\n",
                    slot_cursor, cache_capacity, ready_cursor,
                    nested_residual_all_layer_count);
            return 0;
        }
        state.cache_layer_partitioned = 1u;
    }
    state.cache_by_layer_expert.assign(
        CUDA_NESTED_RESIDUAL_LAYER_COUNT *
            CUDA_NESTED_RESIDUAL_EXPERT_COUNT,
        -1);
    state.residual_scratch.resize((size_t)max_residual);
    if (state.gpu_join_requested_flag) {
        state.gpu_join_requested = 1u;
        cudaError_t err = cudaHostAlloc(
            (void **)&state.gpu_join_residual_host,
            (size_t)max_residual, cudaHostAllocDefault);
        if (err == cudaSuccess) {
            err = cudaHostAlloc((void **)&state.gpu_join_verify_host,
                                (size_t)max_native, cudaHostAllocDefault);
        }
        if (err == cudaSuccess) {
            err = cudaMalloc((void **)&state.gpu_join_base_device,
                             (size_t)max_base);
        }
        if (err == cudaSuccess) {
            err = cudaMalloc((void **)&state.gpu_join_residual_device,
                             (size_t)max_residual);
        }
        if (err == cudaSuccess) {
            const cudaError_t created = cudaEventCreateWithFlags(
                &state.gpu_join_done_event, cudaEventDisableTiming);
            if (created == cudaSuccess) {
                state.gpu_join_event_created = 1u;
            } else {
                err = created;
            }
        }
        if (err == cudaSuccess) {
            if (os_mutex_init(&state.gpu_join_mutex) == 0) {
                state.gpu_join_mutex_ready = 1u;
            } else {
                err = cudaErrorMemoryAllocation;
            }
        }
        if (err != cudaSuccess) {
            fprintf(stderr,
                    "ds4: nested residual GPU join scratch allocation failed: %s\n",
                    cudaGetErrorString(err));
            (void)cudaGetLastError();
            state.gpu_join_failures++;
            return 0;
        }
        state.gpu_join_base_device_bytes = max_base;
        state.gpu_join_residual_device_bytes = max_residual;
        state.gpu_join_verify_host_bytes = max_native;
        state.gpu_join_ready = 1u;
        fprintf(stderr,
                "ds4: [nested-residual-gpu-join] scratch-ready "
                "base_bytes=%llu residual_bytes=%llu verify_bytes=%llu "
                "native_h2d_bytes=0\n",
                (unsigned long long)max_base,
                (unsigned long long)max_residual,
                (unsigned long long)max_native);
    }
    fprintf(stderr,
            "ds4: [nested-residual] bootstrap-ready base_bytes=%llu "
            "base_pinned_bytes=%llu base_pageable_bytes=%llu "
            "base_pinned_entries=%u base_pageable_entries=%u "
            "cache_entries=%u cache_bytes=%llu cache_pageable=%u "
            "cache_layer_partitioned=%u "
            "all_layer=%u all_layer_first=%u all_layer_last=%u "
            "all_layer_count=%u "
            "router=open exact=1\n",
            (unsigned long long)state.base_bytes,
            (unsigned long long)state.base_pinned_bytes,
            (unsigned long long)state.base_pageable_bytes,
            state.base_pinned_entries,
            state.base_pageable_entries,
            state.cache_capacity,
            (unsigned long long)state.cache_bytes,
            (unsigned)state.cache_pageable,
            (unsigned)state.cache_layer_partitioned,
            (unsigned)state.all_layer_storage,
            state.all_layer_first,
            state.all_layer_last,
            state.all_layer_count);
    return 1;
}

static uint64_t cuda_iq1_s_ram_cache_requested_bytes(void) {
    const char *env = getenv("DS4_IQ1_S_RAM_CACHE_GB");
    if (!env || !env[0] || strcmp(env, "0") == 0) return 0;
    char *end = NULL;
    errno = 0;
    const double gib = strtod(env, &end);
    while (end && (*end == ' ' || *end == '\t')) end++;
    if (end == env || errno != 0 || !end || *end != '\0' ||
        !std::isfinite(gib) || gib <= 0.0 || gib > 48.0) {
        fprintf(stderr, "ds4: invalid DS4_IQ1_S_RAM_CACHE_GB=%s\n", env);
        return UINT64_MAX;
    }
    const double bytes = gib * 1073741824.0;
    if (bytes < 1.0 || bytes > (double)UINT64_MAX) return UINT64_MAX;
    return (uint64_t)bytes;
}

static int cuda_iq1_s_env_flag(const char *name) {
    const char *env = getenv(name);
    if (!env || !env[0] || strcmp(env, "0") == 0) return 0;
    if (strcmp(env, "1") == 0) return 1;
    fprintf(stderr, "ds4: invalid %s=%s (expected 0 or 1)\n", name, env);
    return -1;
}

static void cuda_iq1_s_ram_cache_release(void) {
    cuda_iq1_s_ram_cache &cache = g_iq1_s_ram_cache;
    if (cache.attempted || cache.hits || cache.misses || cache.failures) {
        if (cache.pageable || cache.preload_all) {
            fprintf(stderr,
                    "ds4: [iq1-s-ram-cache] result=summary requested_bytes=%llu "
                    "allocated_bytes=%llu capacity=%u count=%u slot_bytes=%llu "
                    "hits=%llu misses=%llu evictions=%llu ssd_bytes=%llu "
                    "h2d_bytes=%llu failures=%llu pinned=0 pageable=1 mapped=0 "
                    "policy=frozen-full preload_all=1 frozen=%u "
                    "preload_layers=%u preload_entries=%llu "
                    "preload_ssd_bytes=%llu preload_read_calls=%llu "
                    "preload_ms=%.3f\n",
                    (unsigned long long)cache.requested_bytes,
                    (unsigned long long)cache.allocated_bytes,
                    cache.capacity, cache.count,
                    (unsigned long long)cache.slot_bytes,
                    (unsigned long long)cache.hits,
                    (unsigned long long)cache.misses,
                    (unsigned long long)cache.evictions,
                    (unsigned long long)cache.ssd_bytes,
                    (unsigned long long)cache.h2d_bytes,
                    (unsigned long long)cache.failures,
                    cache.frozen, cache.preload_layers,
                    (unsigned long long)cache.preload_entries,
                    (unsigned long long)cache.preload_ssd_bytes,
                    (unsigned long long)cache.preload_read_calls,
                    cache.preload_seconds * 1000.0);
        } else {
            fprintf(stderr,
                    "ds4: [iq1-s-ram-cache] result=summary requested_bytes=%llu "
                    "allocated_bytes=%llu capacity=%u count=%u slot_bytes=%llu "
                    "hits=%llu misses=%llu evictions=%llu ssd_bytes=%llu "
                    "h2d_bytes=%llu failures=%llu pinned=1 mapped=0\n",
                    (unsigned long long)cache.requested_bytes,
                    (unsigned long long)cache.allocated_bytes,
                    cache.capacity, cache.count,
                    (unsigned long long)cache.slot_bytes,
                    (unsigned long long)cache.hits,
                    (unsigned long long)cache.misses,
                    (unsigned long long)cache.evictions,
                    (unsigned long long)cache.ssd_bytes,
                    (unsigned long long)cache.h2d_bytes,
                    (unsigned long long)cache.failures);
        }
    }
    if (getenv("DS4_IQ1_S_PROFILE") != NULL &&
        (cache.ssd_read_calls || cache.h2d_batches || cache.h2d_syncs)) {
        fprintf(stderr,
                "ds4: [iq1-s-profile] result=summary ssd_read_calls=%llu "
                "ssd_read_ms=%.3f h2d_batches=%llu h2d_copies=%llu "
                "h2d_enqueue_ms=%.3f "
                "h2d_syncs=%llu h2d_sync_ms=%.3f h2d_bytes=%llu\n",
                (unsigned long long)cache.ssd_read_calls,
                cache.ssd_read_seconds * 1000.0,
                (unsigned long long)cache.h2d_batches,
                (unsigned long long)cache.h2d_copies,
                cache.h2d_enqueue_seconds * 1000.0,
                (unsigned long long)cache.h2d_syncs,
                cache.h2d_sync_seconds * 1000.0,
                (unsigned long long)cache.h2d_bytes);
    }
    if (cache.host_base) {
#ifdef _WIN32
        if (cache.pageable) {
            (void)VirtualFree(cache.host_base, 0, MEM_RELEASE);
        } else
#endif
        {
            (void)cudaFreeHost(cache.host_base);
        }
    }
    cache.host_base = NULL;
    cache.requested_bytes = 0;
    cache.allocated_bytes = 0;
    cache.slot_bytes = 0;
    cache.gate_expert_bytes = 0;
    cache.down_expert_bytes = 0;
    cache.tick = 0;
    cache.hits = 0;
    cache.misses = 0;
    cache.evictions = 0;
    cache.ssd_bytes = 0;
    cache.h2d_bytes = 0;
    cache.ssd_read_calls = 0;
    cache.h2d_batches = 0;
    cache.h2d_copies = 0;
    cache.h2d_syncs = 0;
    cache.ssd_read_seconds = 0.0;
    cache.h2d_enqueue_seconds = 0.0;
    cache.h2d_sync_seconds = 0.0;
    cache.preload_entries = 0;
    cache.preload_ssd_bytes = 0;
    cache.preload_read_calls = 0;
    cache.preload_seconds = 0.0;
    cache.failures = 0;
    cache.capacity = 0;
    cache.count = 0;
    cache.preload_layers = 0;
    cache.attempted = 0;
    cache.pageable = 0;
    cache.preload_all = 0;
    cache.frozen = 0;
    memset(cache.layer_preloaded, 0, sizeof(cache.layer_preloaded));
    cache.slots.clear();
    cache.slot_by_layer_expert.clear();
}

/* Returns 1 when ready, 0 when disabled, and -1 on requested failure. */
static int cuda_iq1_s_ram_cache_prepare(
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes) {
    cuda_iq1_s_ram_cache &cache = g_iq1_s_ram_cache;
    const uint64_t requested = cuda_iq1_s_ram_cache_requested_bytes();
    const int pageable = cuda_iq1_s_env_flag("DS4_IQ1_S_RAM_CACHE_PAGEABLE");
    const int preload_all = cuda_iq1_s_env_flag("DS4_IQ1_S_RAM_CACHE_PRELOAD_ALL");
    if (requested == 0) {
        if (!pageable && !preload_all) return 0;
        cache.attempted = 1;
        cache.failures++;
        return -1;
    }
    if (requested == UINT64_MAX || pageable < 0 || preload_all < 0 ||
        gate_expert_bytes == 0 ||
        down_expert_bytes == 0 ||
        gate_expert_bytes > (UINT64_MAX - down_expert_bytes) / 2ull ||
        (pageable != preload_all)) {
        cache.attempted = 1;
        cache.failures++;
        return -1;
    }
    const uint64_t slot_bytes = gate_expert_bytes * 2ull + down_expert_bytes;
    if (cache.host_base) {
        return cache.requested_bytes == requested &&
               cache.slot_bytes == slot_bytes &&
               cache.gate_expert_bytes == gate_expert_bytes &&
               cache.down_expert_bytes == down_expert_bytes &&
               cache.pageable == (uint8_t)pageable &&
               cache.preload_all == (uint8_t)preload_all ? 1 : -1;
    }
    if (cache.attempted) return -1;
    cache.attempted = 1;
    cache.requested_bytes = requested;
    cache.slot_bytes = slot_bytes;
    cache.gate_expert_bytes = gate_expert_bytes;
    cache.down_expert_bytes = down_expert_bytes;
    cache.pageable = (uint8_t)pageable;
    cache.preload_all = (uint8_t)preload_all;
    const uint64_t max_entries = (uint64_t)CUDA_IQ1_S_LAYER_COUNT * 256ull;
    uint64_t capacity = requested / slot_bytes;
    if (capacity > max_entries) capacity = max_entries;
    if (capacity == 0 || capacity > UINT32_MAX) {
        cache.failures++;
        return -1;
    }
    const uint64_t preload_entries =
        (uint64_t)CUDA_IQ1_S_ROUTED_LAYER_COUNT *
        CUDA_IQ1_S_EXPERTS_PER_LAYER;
    if (preload_all && capacity != preload_entries) {
        fprintf(stderr,
                "ds4: IQ1_S full preload requires exactly %llu slots; got %llu\n",
                (unsigned long long)preload_entries,
                (unsigned long long)capacity);
        cache.failures++;
        return -1;
    }
    cache.capacity = (uint32_t)capacity;
    cache.allocated_bytes = capacity * slot_bytes;
#ifdef _WIN32
    if (pageable) {
        cache.host_base = (char *)VirtualAlloc(
            NULL, (SIZE_T)cache.allocated_bytes,
            MEM_RESERVE | MEM_COMMIT, PAGE_READWRITE);
        if (!cache.host_base) {
            fprintf(stderr,
                    "ds4: IQ1_S pageable RAM cache allocation failed: winerr=%lu "
                    "requested=%.3f GiB\n",
                    (unsigned long)GetLastError(),
                    (double)cache.allocated_bytes / 1073741824.0);
            cache.failures++;
            return -1;
        }
    } else
#endif
    {
        cudaError_t err = cudaHostAlloc(
            (void **)&cache.host_base,
            (size_t)cache.allocated_bytes,
            cudaHostAllocDefault);
        if (err != cudaSuccess) {
            fprintf(stderr,
                    "ds4: IQ1_S pinned RAM cache allocation failed: %s "
                    "requested=%.3f GiB\n",
                    cudaGetErrorString(err),
                    (double)cache.allocated_bytes / 1073741824.0);
            (void)cudaGetLastError();
            cache.host_base = NULL;
            cache.failures++;
            return -1;
        }
    }
    try {
        cache.slots.resize(cache.capacity);
        cache.slot_by_layer_expert.assign(
            (size_t)CUDA_IQ1_S_LAYER_COUNT * 256u, -1);
    } catch (...) {
#ifdef _WIN32
        if (cache.pageable) {
            (void)VirtualFree(cache.host_base, 0, MEM_RELEASE);
        } else
#endif
        {
            (void)cudaFreeHost(cache.host_base);
        }
        cache.host_base = NULL;
        cache.slots.clear();
        cache.slot_by_layer_expert.clear();
        cache.failures++;
        return -1;
    }
    if (preload_all) {
        fprintf(stderr,
                "ds4: [iq1-s-ram-cache] result=ready requested_gib=%.3f "
                "allocated_gib=%.3f capacity=%u slot_bytes=%llu "
                "pinned=0 pageable=1 mapped=0 policy=frozen-full "
                "preload_all=1\n",
                (double)requested / 1073741824.0,
                (double)cache.allocated_bytes / 1073741824.0,
                cache.capacity, (unsigned long long)slot_bytes);
    } else {
        fprintf(stderr,
                "ds4: [iq1-s-ram-cache] result=ready requested_gib=%.3f "
                "allocated_gib=%.3f capacity=%u slot_bytes=%llu "
                "pinned=1 mapped=0 policy=lru\n",
                (double)requested / 1073741824.0,
                (double)cache.allocated_bytes / 1073741824.0,
                cache.capacity, (unsigned long long)slot_bytes);
    }
    return 1;
}

static int cuda_iq1_s_ram_cache_preload_layer(
        uint32_t layer_index,
        uint32_t requested_expert,
        uint64_t gate_src,
        uint64_t up_src,
        uint64_t down_src) {
    cuda_iq1_s_ram_cache &cache = g_iq1_s_ram_cache;
    if (!cache.preload_all || !cache.pageable ||
        layer_index < CUDA_IQ1_S_ROUTED_LAYER_FIRST ||
        layer_index >= CUDA_IQ1_S_ROUTED_LAYER_FIRST +
            CUDA_IQ1_S_ROUTED_LAYER_COUNT ||
        requested_expert >= CUDA_IQ1_S_EXPERTS_PER_LAYER ||
        cache.capacity != CUDA_IQ1_S_ROUTED_LAYER_COUNT *
            CUDA_IQ1_S_EXPERTS_PER_LAYER ||
        gate_src < (uint64_t)requested_expert * cache.gate_expert_bytes ||
        up_src < (uint64_t)requested_expert * cache.gate_expert_bytes ||
        down_src < (uint64_t)requested_expert * cache.down_expert_bytes) {
        cache.failures++;
        return 0;
    }
    if (cache.layer_preloaded[layer_index]) return 1;

    const uint64_t gate_base = gate_src -
        (uint64_t)requested_expert * cache.gate_expert_bytes;
    const uint64_t up_base = up_src -
        (uint64_t)requested_expert * cache.gate_expert_bytes;
    const uint64_t down_base = down_src -
        (uint64_t)requested_expert * cache.down_expert_bytes;
    const uint64_t gate_span =
        (uint64_t)CUDA_IQ1_S_EXPERTS_PER_LAYER * cache.gate_expert_bytes;
    const uint64_t down_span =
        (uint64_t)CUDA_IQ1_S_EXPERTS_PER_LAYER * cache.down_expert_bytes;
    if (!g_iq1_s_sidecar_file_valid ||
        gate_base > g_iq1_s_sidecar_size ||
        gate_span > g_iq1_s_sidecar_size - gate_base ||
        up_base > g_iq1_s_sidecar_size ||
        gate_span > g_iq1_s_sidecar_size - up_base ||
        down_base > g_iq1_s_sidecar_size ||
        down_span > g_iq1_s_sidecar_size - down_base) {
        cache.failures++;
        return 0;
    }

    const double preload_t0 = cuda_wall_sec();
    for (uint32_t expert = 0; expert < CUDA_IQ1_S_EXPERTS_PER_LAYER;
         expert++) {
        const uint32_t slot_index =
            (layer_index - CUDA_IQ1_S_ROUTED_LAYER_FIRST) *
                CUDA_IQ1_S_EXPERTS_PER_LAYER + expert;
        cuda_iq1_s_ram_cache_slot &slot = cache.slots[slot_index];
        if (slot.valid) {
            cache.failures++;
            return 0;
        }
        const uint64_t expert_gate_src = gate_base +
            (uint64_t)expert * cache.gate_expert_bytes;
        const uint64_t expert_up_src = up_base +
            (uint64_t)expert * cache.gate_expert_bytes;
        const uint64_t expert_down_src = down_base +
            (uint64_t)expert * cache.down_expert_bytes;
        char *base = cache.host_base +
            (uint64_t)slot_index * cache.slot_bytes;
        if (!cuda_pread_full(&g_iq1_s_sidecar_file, base,
                             cache.gate_expert_bytes, expert_gate_src) ||
            !cuda_pread_full(&g_iq1_s_sidecar_file,
                             base + cache.gate_expert_bytes,
                             cache.gate_expert_bytes, expert_up_src) ||
            !cuda_pread_full(&g_iq1_s_sidecar_file,
                             base + cache.gate_expert_bytes * 2ull,
                             cache.down_expert_bytes, expert_down_src)) {
            cache.failures++;
            cache.preload_seconds += cuda_wall_sec() - preload_t0;
            return 0;
        }
        slot.layer_index = layer_index;
        slot.expert_id = expert;
        slot.gate_src = expert_gate_src;
        slot.up_src = expert_up_src;
        slot.down_src = expert_down_src;
        slot.age = ++cache.tick;
        slot.valid = 1;
        cache.slot_by_layer_expert[layer_index *
            CUDA_IQ1_S_EXPERTS_PER_LAYER + expert] = (int32_t)slot_index;
        cache.count++;
        cache.preload_entries++;
        cache.preload_ssd_bytes += cache.slot_bytes;
        cache.preload_read_calls += 3u;
    }
    cache.layer_preloaded[layer_index] = 1;
    cache.preload_layers++;
    cache.preload_seconds += cuda_wall_sec() - preload_t0;
    if (cache.preload_layers == CUDA_IQ1_S_ROUTED_LAYER_COUNT) {
        cache.frozen = 1;
    }
    return 1;
}

/* Resolve one complete sidecar expert into a stable pinned host slot. */
static int cuda_iq1_s_ram_cache_resolve(
        uint32_t layer_index,
        uint32_t expert_id,
        uint64_t gate_src,
        uint64_t up_src,
        uint64_t down_src,
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes,
        const char **gate_host,
        const char **up_host,
        const char **down_host) {
    if (!gate_host || !up_host || !down_host ||
        layer_index >= CUDA_IQ1_S_LAYER_COUNT || expert_id >= 256u) {
        return -1;
    }
    const int prepared = cuda_iq1_s_ram_cache_prepare(
        gate_expert_bytes, down_expert_bytes);
    if (prepared <= 0) return prepared;
    cuda_iq1_s_ram_cache &cache = g_iq1_s_ram_cache;
    if (cache.preload_all &&
        !cuda_iq1_s_ram_cache_preload_layer(
            layer_index, expert_id, gate_src, up_src, down_src)) {
        return -1;
    }
    const uint32_t map_index = layer_index * 256u + expert_id;
    int32_t slot_i = cache.slot_by_layer_expert[map_index];
    if (slot_i >= 0 && (uint32_t)slot_i < cache.capacity) {
        cuda_iq1_s_ram_cache_slot &slot = cache.slots[(uint32_t)slot_i];
        if (slot.valid && slot.layer_index == layer_index &&
            slot.expert_id == expert_id && slot.gate_src == gate_src &&
            slot.up_src == up_src && slot.down_src == down_src) {
            slot.age = ++cache.tick;
            cache.hits++;
            const char *base = cache.host_base +
                (uint64_t)(uint32_t)slot_i * cache.slot_bytes;
            *gate_host = base;
            *up_host = base + gate_expert_bytes;
            *down_host = base + gate_expert_bytes * 2ull;
            return 1;
        }
        cache.slot_by_layer_expert[map_index] = -1;
    }

    if (cache.preload_all) {
        cache.failures++;
        return -1;
    }

    cache.misses++;
    uint32_t victim = UINT32_MAX;
    uint64_t oldest = UINT64_MAX;
    for (uint32_t i = 0; i < cache.capacity; i++) {
        if (!cache.slots[i].valid) {
            victim = i;
            break;
        }
        if (cache.slots[i].age < oldest) {
            oldest = cache.slots[i].age;
            victim = i;
        }
    }
    if (victim == UINT32_MAX) {
        cache.failures++;
        return -1;
    }
    cuda_iq1_s_ram_cache_slot &slot = cache.slots[victim];
    const int was_valid = slot.valid != 0;
    if (was_valid && slot.layer_index < CUDA_IQ1_S_LAYER_COUNT &&
        slot.expert_id < 256u) {
        const uint32_t old_index = slot.layer_index * 256u + slot.expert_id;
        if (cache.slot_by_layer_expert[old_index] == (int32_t)victim) {
            cache.slot_by_layer_expert[old_index] = -1;
        }
        cache.evictions++;
    }
    slot.valid = 0;
    char *base = cache.host_base + (uint64_t)victim * cache.slot_bytes;
    char *gate = base;
    char *up = base + gate_expert_bytes;
    char *down = base + gate_expert_bytes * 2ull;
    const int profile = getenv("DS4_IQ1_S_PROFILE") != NULL;
    const double read_t0 = profile ? cuda_wall_sec() : 0.0;
    cache.ssd_read_calls += profile != 0;
    if (!g_iq1_s_sidecar_file_valid ||
        !cuda_pread_full(&g_iq1_s_sidecar_file, gate,
                         gate_expert_bytes, gate_src) ||
        !cuda_pread_full(&g_iq1_s_sidecar_file, up,
                         gate_expert_bytes, up_src) ||
        !cuda_pread_full(&g_iq1_s_sidecar_file, down,
                         down_expert_bytes, down_src)) {
        if (was_valid && cache.count > 0) cache.count--;
        cache.failures++;
        if (profile) cache.ssd_read_seconds += cuda_wall_sec() - read_t0;
        return -1;
    }
    if (profile) cache.ssd_read_seconds += cuda_wall_sec() - read_t0;
    slot.layer_index = layer_index;
    slot.expert_id = expert_id;
    slot.gate_src = gate_src;
    slot.up_src = up_src;
    slot.down_src = down_src;
    slot.age = ++cache.tick;
    slot.valid = 1;
    cache.slot_by_layer_expert[map_index] = (int32_t)victim;
    if (!was_valid) cache.count++;
    cache.ssd_bytes += cache.slot_bytes;
    *gate_host = gate;
    *up_host = up;
    *down_host = down;
    return 1;
}

static int cuda_model_stage_read(void *stage, uint64_t stage_bytes,
                                 uint64_t offset, uint64_t bytes,
                                 const char **payload) {
    *payload = (const char *)stage;
#if defined(__linux__) && defined(O_DIRECT)
    if (g_model_direct_fd >= 0 && g_model_direct_align > 1 && g_model_file_size != 0) {
        const uint64_t aligned_off = cuda_round_down(offset, g_model_direct_align);
        const uint64_t delta = offset - aligned_off;
        uint64_t read_size = cuda_round_up(delta + bytes, g_model_direct_align);
        if (aligned_off <= g_model_file_size &&
            read_size <= stage_bytes &&
            read_size <= g_model_file_size - aligned_off) {
            const int saved_errno = errno;
            errno = 0;
            os_file_t direct_file;
            os_file_init(&direct_file);
            direct_file.fd = g_model_direct_fd;
            if (cuda_pread_full(&direct_file, stage, read_size, aligned_off)) {
                *payload = (const char *)stage + delta;
                errno = saved_errno;
                return 1;
            }
            const int direct_errno = errno;
            if (direct_errno == EINVAL || direct_errno == EFAULT || direct_errno == ENOTSUP || direct_errno == EOPNOTSUPP) {
                if (getenv("DS4_CUDA_WEIGHT_CACHE_VERBOSE")) {
                    fprintf(stderr, "ds4: CUDA direct model read disabled: %s\n", strerror(direct_errno));
                }
                (void)close(g_model_direct_fd);
                g_model_direct_fd = -1;
                g_model_direct_align = 1;
            }
            errno = direct_errno;
        }
    }
#else
    (void)stage_bytes;
#endif
    if (!g_model_file_valid) return 0;
    return cuda_pread_full(&g_model_file, stage, bytes, offset);
}

static uint64_t cuda_model_cache_limit_bytes(void) {
    uint64_t gb = 0;
    const char *env = getenv("DS4_CUDA_WEIGHT_CACHE_LIMIT_GB");
    if (env && env[0]) {
        char *end = NULL;
        unsigned long long v = strtoull(env, &end, 10);
        if (end != env) gb = (uint64_t)v;
    }
    if (gb == 0) return UINT64_MAX;
    return gb * 1073741824ull;
}

static uint64_t cuda_model_arena_chunk_bytes(uint64_t need) {
    uint64_t mb = 1792;
    const char *env = getenv("DS4_CUDA_WEIGHT_ARENA_CHUNK_MB");
    if (env && env[0]) {
        char *end = NULL;
        unsigned long long v = strtoull(env, &end, 10);
        if (end != env && v > 0) mb = (uint64_t)v;
    }
    if (mb < 256) mb = 256;
    if (mb > 8192) mb = 8192;
    uint64_t bytes = mb * 1048576ull;
    if (bytes < need) {
        const uint64_t align = 256ull * 1048576ull;
        bytes = (need + align - 1u) & ~(align - 1u);
    }
    return bytes;
}

static char *cuda_model_arena_alloc(uint64_t bytes, const char *what) {
    if (bytes == 0) return NULL;
    if (g_model_cache_full) return NULL;
    const uint64_t align = 256u;
    const uint64_t aligned = (bytes + align - 1u) & ~(align - 1u);

    for (cuda_model_arena &a : g_model_arenas) {
        const uint64_t used = (a.used + align - 1u) & ~(align - 1u);
        if (used <= a.bytes && aligned <= a.bytes - used) {
            char *ptr = a.device_ptr + used;
            a.used = used + aligned;
            return ptr;
        }
    }

    const uint64_t limit = cuda_model_cache_limit_bytes();
    if (g_model_range_bytes > limit || aligned > limit - g_model_range_bytes) return NULL;

    const uint64_t chunk = cuda_model_arena_chunk_bytes(aligned);
    void *dev = NULL;
    cudaError_t err = cudaMalloc(&dev, (size_t)chunk);
    if (err != cudaSuccess) {
        fprintf(stderr, "ds4: CUDA model arena alloc failed for %s (%.2f MiB chunk): %s\n",
                what ? what : "weights",
                (double)chunk / 1048576.0,
                cudaGetErrorString(err));
        (void)cudaGetLastError();
        g_model_cache_full = 1;
        return NULL;
    }
    g_model_arenas.push_back({(char *)dev, chunk, aligned});
    if (getenv("DS4_CUDA_WEIGHT_CACHE_VERBOSE")) {
        uint64_t arena_bytes = 0;
        for (const cuda_model_arena &a : g_model_arenas) arena_bytes += a.bytes;
        fprintf(stderr, "ds4: CUDA model arena allocated %.2f MiB (arenas %.2f GiB)\n",
                (double)chunk / 1048576.0,
                (double)arena_bytes / 1073741824.0);
    }
    return (char *)dev;
}

/* ---- Streamed-range VRAM allocator with LRU eviction (G6) ---- */
static uint64_t cuda_model_stream_reserve_bytes(void) {
    uint64_t mb = 2048;
    const char *e = NULL;
    if (g_model_streaming_active && g_model_expert_cache_ready) {
        e = getenv("DS4_CUDA_STREAM_RUNTIME_RESERVE_MB");
    }
    if (!e || !e[0]) e = getenv("DS4_CUDA_STREAM_RESERVE_MB");
    if (e && e[0]) { char *end = NULL; unsigned long long v = strtoull(e, &end, 10); if (end != e) mb = (uint64_t)v; }
    return mb * 1048576ull;
}

/* Coldest evictable streamed range outside the pin window; -1 if none.
 * G7 keep-hot: two-tier. Pass 1 considers only UNPINNED ranges (experts) so hot
 * non-expert weights survive; only if there is no evictable expert do we fall back
 * to evicting the coldest PINNED range (pass 2) -- this guarantees forward progress
 * without deadlocking when the whole live set is pinned. */
static long cuda_model_pick_victim(void) {
    const uint64_t pin_floor = (g_model_tick > 4u) ? (g_model_tick - 4u) : 0u; /* protect current MoE working set */
    for (int tier = 0; tier < 2; tier++) {
        long best = -1;
        uint64_t best_tick = UINT64_MAX;
        for (size_t i = 0; i < g_model_ranges.size(); i++) {
            const cuda_model_range &r = g_model_ranges[i];
            if (!r.streamed || !r.device_ptr) continue;
            if (r.last_used_tick > pin_floor) continue;
            if (tier == 0 && r.pinned) continue;      /* pass 1: experts only */
            if (tier == 1 && !r.pinned) continue;     /* pass 2: pinned last resort */
            if (r.last_used_tick < best_tick) { best_tick = r.last_used_tick; best = (long)i; }
        }
        if (best >= 0) return best;
    }
    return -1;
}

/* ---- Recycled-buffer pool for event-based eviction (G7) ----
 * The old eviction path did cudaDeviceSynchronize() before every cudaFree to
 * ensure no in-flight stream-0 kernel read the victim -- a full pipeline drain
 * per eviction (thousands/token) that dominated decode. Instead of freeing a
 * victim's owning cudaMalloc, we record a stream-0 event on it (which fences all
 * prior reads) and park the buffer in a size-bucketed pool. A later same-size
 * allocation reuses a pooled buffer whose event has already completed (query, no
 * wait) -- so evictions cost no sync and the cudaMalloc/cudaFree churn disappears.
 * All streamed-weight readers run on stream 0, so a stream-0 event is a correct
 * fence. Buffers are drained back to the driver only under real VRAM pressure. */
struct cuda_stream_pool_buf {
    char *ptr;
    uint64_t bytes;      /* the aligned allocation size (exact-bucket reuse) */
    cudaEvent_t ev;      /* recorded on stream 0 at eviction; ready => safe to reuse/free */
};
static std::vector<cuda_stream_pool_buf> g_stream_pool;
static uint64_t g_stream_pool_bytes;

/* Park an owning buffer for deferred reuse; fences prior stream-0 reads via event.
 * Falls back to a synchronous free if an event can't be created. */
static void cuda_stream_pool_push(char *ptr, uint64_t aligned) {
    if (!ptr) return;
    cudaEvent_t ev = NULL;
    if (cudaEventCreateWithFlags(&ev, cudaEventDisableTiming) != cudaSuccess) {
        (void)cudaGetLastError();
        (void)cudaDeviceSynchronize();
        (void)cudaFree(ptr);
        return;
    }
    (void)cudaEventRecord(ev, 0);
    g_stream_pool.push_back({ptr, aligned, ev});
    g_stream_pool_bytes += aligned;
}

/* Reuse a ready (event-complete) pooled buffer of the exact size, no wait/malloc. */
static char *cuda_stream_pool_take(uint64_t aligned) {
    for (size_t i = 0; i < g_stream_pool.size(); i++) {
        cuda_stream_pool_buf &b = g_stream_pool[i];
        if (b.bytes != aligned) continue;
        if (cudaEventQuery(b.ev) != cudaSuccess) { (void)cudaGetLastError(); continue; }
        char *ptr = b.ptr;
        (void)cudaEventDestroy(b.ev);
        g_stream_pool_bytes -= b.bytes;
        g_stream_pool.erase(g_stream_pool.begin() + (long)i);
        return ptr;
    }
    return NULL;
}

/* Free one pooled buffer back to the driver to release VRAM. Prefers a ready
 * buffer (no wait); waits on the oldest only if forced. Returns bytes freed. */
static uint64_t cuda_stream_pool_reclaim(void) {
    if (g_stream_pool.empty()) return 0;
    size_t idx = 0; int found_ready = 0;
    for (size_t i = 0; i < g_stream_pool.size(); i++) {
        if (cudaEventQuery(g_stream_pool[i].ev) == cudaSuccess) { idx = i; found_ready = 1; break; }
        (void)cudaGetLastError();
    }
    cuda_stream_pool_buf b = g_stream_pool[idx];
    if (!found_ready) (void)cudaEventSynchronize(b.ev);
    (void)cudaEventDestroy(b.ev);
    (void)cudaFree(b.ptr);
    g_stream_pool_bytes -= b.bytes;
    g_stream_pool.erase(g_stream_pool.begin() + (long)idx);
    return b.bytes;
}

/* Swap-erase range i and park its owning buffer in the recycle pool (deferred,
 * event-fenced free) instead of a synchronous cudaDeviceSynchronize + cudaFree. */
static void cuda_model_range_evict_to_pool(size_t i) {
    const cuda_model_range v = g_model_ranges[i];
    auto mapped = g_model_range_by_offset.find(v.offset);
    if (mapped != g_model_range_by_offset.end() && mapped->second == i) {
        g_model_range_by_offset.erase(mapped);
    }
    if (g_model_range_bytes >= v.bytes) g_model_range_bytes -= v.bytes;
    const size_t last = g_model_ranges.size() - 1u;
    if (i != last) {
        g_model_ranges[i] = g_model_ranges[last];
        g_model_range_by_offset[g_model_ranges[i].offset] = i;
    }
    g_model_ranges.pop_back();
    if (v.device_ptr && v.streamed && !v.arena_allocated) {
        cuda_stream_pool_push(v.device_ptr, (v.bytes + 255u) & ~255ull);
    }
}

/* Allocate `bytes` of VRAM for a streamed range, reusing a recycled buffer or
 * evicting LRU cold ranges as needed. allow_evict=0 during pre-cache (NULL ->
 * caller defers). No per-eviction device sync: safety is via the pool's events. */
static char *cuda_model_stream_alloc(uint64_t bytes, int allow_evict, const char *what) {
    (void)what;
    const uint64_t aligned = (bytes + 255u) & ~255ull;
    const uint64_t reserve = cuda_model_stream_reserve_bytes();
    /* Fast path: recycle a ready same-size buffer (no sync, no malloc). */
    char *reuse = cuda_stream_pool_take(aligned);
    if (reuse) return reuse;
    for (;;) {
        size_t freeb = 0, totalb = 0;
        if (cudaMemGetInfo(&freeb, &totalb) != cudaSuccess) {
            /* Query failure is not OOM: setting freeb=0 here would mass-evict the
             * entire cache one range/iter. Bail instead (caller treats NULL as
             * non-fatal and falls back). */
            (void)cudaGetLastError();
            return NULL;
        }
        if ((uint64_t)freeb >= aligned + reserve) {
            void *dev = NULL;
            cudaError_t err = cudaMalloc(&dev, (size_t)aligned);
            if (err == cudaSuccess) return (char *)dev;
            (void)cudaGetLastError();
        }
        /* Reclaim VRAM parked in the pool before evicting live ranges. */
        if (cuda_stream_pool_reclaim() > 0) continue;
        if (!allow_evict) return NULL;
        const long vi = cuda_model_pick_victim();
        if (vi < 0) return NULL;
        cuda_model_range_evict_to_pool((size_t)vi);   /* event-fenced, no device sync */
        g_model_evict_count++;
        if (getenv("DS4_CUDA_WEIGHT_CACHE_VERBOSE")) {
            fprintf(stderr, "ds4: CUDA evicted streamed range (evicts=%llu)\n",
                    (unsigned long long)g_model_evict_count);
        }
    }
}

static const char *cuda_model_range_ptr_from_fd(
        const void *model_map,
        uint64_t offset,
        uint64_t bytes,
        const char *what) {
    if (!g_model_file_valid || bytes == 0) return NULL;

    /* Dedicated VRAM buffer for this streamed range; evict LRU cold ranges under
     * pressure (inference only; pre-cache defers). No host-pointer fallback: a host
     * pointer is not device-accessible on Windows (no HMM) and would crash a kernel. */
    char *dev = cuda_model_stream_alloc(bytes, g_model_streaming_active, what);
    if (!dev) return NULL;
    cudaError_t err = cudaSuccess;

    const uint64_t chunk = cuda_model_copy_chunk_bytes();
    const uint64_t stage_bytes = chunk + (g_model_direct_align > 1 ? g_model_direct_align : 1);
    uint64_t copied = 0;
    uint64_t chunk_idx = 0;
    /* All error paths below jump to `fail:` which frees the owning `dev` buffer.
     * Previously each `return NULL` leaked `dev` (an owning cudaMalloc not yet
     * tracked in g_model_ranges); with thousands of per-expert fetches a transient
     * hiccup would leak VRAM until spurious OOM. */
    if (!cuda_model_stage_pool_alloc(stage_bytes)) goto fail;

    while (copied < bytes) {
        const uint64_t n = (bytes - copied < chunk) ? (bytes - copied) : chunk;
        const uint64_t bi = chunk_idx % 4u;
        if (chunk_idx >= 4u) {
            err = cudaEventSynchronize(g_model_stage_event[bi]);
            if (err != cudaSuccess) {
                fprintf(stderr, "ds4: CUDA model staging wait failed for %s: %s\n",
                        what ? what : "weights", cudaGetErrorString(err));
                (void)cudaGetLastError();
                goto fail;
            }
        }
        const char *payload = NULL;
        if (!cuda_model_stage_read(g_model_stage[bi], g_model_stage_bytes,
                                   offset + copied, n, &payload)) {
            fprintf(stderr, "ds4: CUDA model range read failed for %s at %.2f MiB: %s\n",
                    what ? what : "weights",
                    (double)copied / 1048576.0,
                    strerror(errno));
            goto fail;
        }
        err = cudaMemcpyAsync(dev + copied, payload, (size_t)n,
                              cudaMemcpyHostToDevice, g_model_upload_stream);
        if (err != cudaSuccess) {
            fprintf(stderr, "ds4: CUDA model range copy failed for %s at %.2f MiB: %s\n",
                    what ? what : "weights",
                    (double)copied / 1048576.0,
                    cudaGetErrorString(err));
            (void)cudaGetLastError();
            goto fail;
        }
        err = cudaEventRecord(g_model_stage_event[bi], g_model_upload_stream);
        if (err != cudaSuccess) {
            fprintf(stderr, "ds4: CUDA model staging record failed for %s: %s\n",
                    what ? what : "weights", cudaGetErrorString(err));
            (void)cudaGetLastError();
            goto fail;
        }
        cuda_model_drop_file_pages(offset + copied, n);
        cuda_model_discard_source_pages(model_map, g_model_registered_size, offset + copied, n);
        copied += n;
        cuda_model_load_progress_note(g_model_range_bytes + copied);
        chunk_idx++;
    }
    err = cudaStreamSynchronize(g_model_upload_stream);
    if (err != cudaSuccess) {
        fprintf(stderr, "ds4: CUDA model range upload sync failed for %s: %s\n",
                what ? what : "weights", cudaGetErrorString(err));
        (void)cudaGetLastError();
        goto fail;
    }

    {
        /* keep-hot: pin every non-expert weight (attn/norm/router/hc/dense) so it
         * is not re-streamed each token; expert slices ("moe_*") stay evictable. */
        const int is_hot = (what == NULL) || (strncmp(what, "moe_", 4) != 0);
        g_model_ranges.push_back({model_map, offset, bytes, dev, NULL, NULL, 0, 0, /*arena_allocated=*/0, /*streamed=*/1, ++g_model_tick, is_hot});
    }
    g_model_range_by_offset[offset] = g_model_ranges.size() - 1u;
    g_model_range_bytes += bytes;
    cuda_model_load_progress_note(g_model_range_bytes);
    if (getenv("DS4_CUDA_WEIGHT_CACHE_VERBOSE")) {
        fprintf(stderr, "ds4: CUDA fd-cached %s %.2f MiB (total %.2f GiB)\n",
                what ? what : "weights",
                (double)bytes / 1048576.0,
                (double)g_model_range_bytes / 1073741824.0);
    }
    return (const char *)dev;

fail:
    (void)cudaDeviceSynchronize();
    (void)cudaFree(dev);
    return NULL;
}

static int cuda_model_copy_chunked(const void *model_map, uint64_t model_size, uint64_t map_offset, uint64_t map_size) {
    if (!model_map || model_size == 0 || map_offset > model_size || map_size > model_size - map_offset) return 0;
    if (getenv("DS4_CUDA_NO_MODEL_COPY") != NULL ||
        getenv("DS4_CUDA_DIRECT_MODEL") != NULL ||
        getenv("DS4_CUDA_WEIGHT_CACHE") != NULL ||
        getenv("DS4_CUDA_WEIGHT_PRELOAD") != NULL) {
        return 0;
    }
    if (g_model_device_owned || g_model_registered) return 1;

    void *dev = NULL;
    const double t0 = cuda_wall_sec();
    cudaError_t err = cudaMalloc(&dev, (size_t)model_size);
    if (err != cudaSuccess) {
        cuda_log_full_model_alloc_failure(model_size, err, "chunk-copy");
        (void)cudaGetLastError();
        return 0;
    }

    fprintf(stderr, "ds4: CUDA chunk-copying %.2f GiB model image\n",
            (double)model_size / 1073741824.0);

    const uint64_t chunk = cuda_model_copy_chunk_bytes();
    void *stage = NULL;
    err = cudaMallocHost(&stage, (size_t)chunk);
    if (err != cudaSuccess) {
        fprintf(stderr, "ds4: CUDA pinned model staging allocation failed: %s\n", cudaGetErrorString(err));
        (void)cudaFree(dev);
        (void)cudaGetLastError();
        return 0;
    }

    if (map_offset > 0) {
        uint64_t copied_header = 0;
        while (copied_header < map_offset) {
            const uint64_t n = (map_offset - copied_header < chunk) ? (map_offset - copied_header) : chunk;
            memcpy(stage, (const char *)model_map + copied_header, (size_t)n);
            err = cudaMemcpy((char *)dev + copied_header, stage, (size_t)n, cudaMemcpyHostToDevice);
            if (err != cudaSuccess) {
                fprintf(stderr, "ds4: CUDA model header copy failed: %s\n", cudaGetErrorString(err));
                (void)cudaFreeHost(stage);
                (void)cudaFree(dev);
                (void)cudaGetLastError();
                return 0;
            }
            copied_header += n;
        }
    }

    uint64_t copied = 0;
    double last_report = t0;
    while (copied < map_size) {
        const uint64_t n = (map_size - copied < chunk) ? (map_size - copied) : chunk;
        const uint64_t off = map_offset + copied;
        memcpy(stage, (const char *)model_map + off, (size_t)n);
        err = cudaMemcpy((char *)dev + off, stage, (size_t)n, cudaMemcpyHostToDevice);
        if (err != cudaSuccess) {
            fprintf(stderr, "ds4: CUDA model chunk copy failed at %.2f GiB: %s\n",
                    (double)copied / 1073741824.0, cudaGetErrorString(err));
            (void)cudaFreeHost(stage);
            (void)cudaFree(dev);
            (void)cudaGetLastError();
            return 0;
        }
        cuda_model_discard_source_pages(model_map, model_size, off, n);
        copied += n;
        const double now = cuda_wall_sec();
        if (getenv("DS4_CUDA_MODEL_COPY_VERBOSE") != NULL && now - last_report >= 2.0) {
            fprintf(stderr, "ds4: CUDA model chunk copy %.2f/%.2f GiB\n",
                    (double)copied / 1073741824.0,
                    (double)map_size / 1073741824.0);
            last_report = now;
        }
    }

    (void)cudaFreeHost(stage);
    g_model_device_base = (const char *)dev;
    g_model_device_owned = 1;
    g_model_hmm_direct = 0;
    const double t1 = cuda_wall_sec();
    fprintf(stderr,
            "ds4: CUDA model chunk copy complete in %.3fs (%.2f GiB tensors)\n",
            t1 - t0,
            (double)map_size / 1073741824.0);
    return 1;
}

static void cuda_model_range_release_all(void) {
    for (const cuda_model_range &r : g_model_ranges) {
        if (r.host_registered && r.registered_base) {
            (void)cudaHostUnregister(r.registered_base);
        } else if (r.device_ptr && !r.arena_allocated) {
            (void)cudaFree(r.device_ptr);
        }
    }
    /* Drain the recycled-buffer pool (event-fenced deferred frees). */
    for (const cuda_stream_pool_buf &b : g_stream_pool) {
        (void)cudaEventDestroy(b.ev);
        (void)cudaFree(b.ptr);
    }
    g_stream_pool.clear();
    g_stream_pool_bytes = 0;
    for (const cuda_model_arena &a : g_model_arenas) {
        if (a.device_ptr) (void)cudaFree(a.device_ptr);
    }
    g_model_arenas.clear();
    g_model_ranges.clear();
    g_model_range_by_offset.clear();
    g_model_range_bytes = 0;
    g_model_registered_range_bytes = 0;
    cuda_model_load_progress_reset();
}

static int cublas_ok(cublasStatus_t st, const char *what) {
    if (st == CUBLAS_STATUS_SUCCESS) return 1;
    fprintf(stderr, "ds4: cuBLAS %s failed: status %d\n", what, (int)st);
    return 0;
}

extern "C" int ds4_gpu_init(void) {
    int dev = 0;
    if (!cuda_ok(cudaSetDevice(dev), "set device")) return 0;
    cudaDeviceProp prop;
    if (cudaGetDeviceProperties(&prop, dev) == cudaSuccess) {
        fprintf(stderr, "ds4: CUDA backend initialized on %s (sm_%d%d)\n",
                prop.name, prop.major, prop.minor);
    }
    if (!g_cublas_ready) {
        if (!cublas_ok(cublasCreate(&g_cublas), "create handle")) return 0;
        const cublasMath_t math_mode =
            (g_quality_mode || getenv("DS4_CUDA_NO_TF32") != NULL)
                ? CUBLAS_DEFAULT_MATH
                : CUBLAS_TF32_TENSOR_OP_MATH;
        (void)cublasSetMathMode(g_cublas, math_mode);
        g_cublas_ready = 1;
    }
    return 1;
}

extern "C" void ds4_gpu_cleanup(void) {
    (void)cudaDeviceSynchronize();
    if (g_cublas_ready) {
        (void)cublasDestroy(g_cublas);
        g_cublas_ready = 0;
        g_cublas = NULL;
    }
    cuda_moe_gather_release();
    cuda_moe_expert_cache_release();
    ds4_gpu_dynamic_arena_release();
    g_primary_moe_geometry.clear();
    g_primary_moe_geometry_map = NULL;
    g_primary_moe_geometry_size = 0;
    g_primary_moe_geometry_n_expert = 0;
    cuda_reap_router_bias_release_all();
    if (g_sparse_bake_active) {
        fprintf(stderr,
                "ds4: [sparse-bake-runtime] result=summary "
                "route_calls=%llu route_slots=%llu rejected=%llu\n",
                (unsigned long long)g_sparse_bake_route_calls,
                (unsigned long long)g_sparse_bake_route_slots,
                (unsigned long long)g_sparse_bake_route_rejections);
    }
    cuda_sparse_bake_reset_state();
    cuda_model_range_release_all();
    cuda_q8_f16_cache_release_all();
    g_q8_f16_disabled_after_oom = 0;
    g_q8_f16_budget_notice_printed = 0;
    for (const cuda_q8_f32_range &r : g_q8_f32_ranges) {
        (void)cudaFree(r.device_ptr);
    }
    g_q8_f32_ranges.clear();
    g_q8_f32_by_offset.clear();
    g_q8_f32_bytes = 0;
    if (g_cuda_tmp) {
        (void)cudaFree(g_cuda_tmp);
        g_cuda_tmp = NULL;
        g_cuda_tmp_bytes = 0;
    }
    cuda_embed_row_stage_release();
    for (size_t i = 0; i < 4; i++) {
#ifdef _WIN32
        if (g_moe_io_event[i]) {
            (void)CloseHandle(g_moe_io_event[i]);
            g_moe_io_event[i] = NULL;
        }
        memset(&g_moe_io_ov[i], 0, sizeof(g_moe_io_ov[i]));
        g_moe_io_stage_used[i] = 0;
#endif
        if (g_model_stage_event[i]) {
            (void)cudaEventDestroy(g_model_stage_event[i]);
            g_model_stage_event[i] = NULL;
        }
        if (g_model_stage_raw[i]) {
            (void)cudaFreeHost(g_model_stage_raw[i]);
            g_model_stage_raw[i] = NULL;
            g_model_stage[i] = NULL;
        }
    }
    g_model_stage_bytes = 0;
    if (g_model_upload_stream) {
        (void)cudaStreamDestroy(g_model_upload_stream);
        g_model_upload_stream = NULL;
    }
    if (g_model_device_owned && g_model_device_base) {
        (void)cudaFree((void *)g_model_device_base);
    }
    if (g_model_window_registered && g_model_host_base) {
        (void)cudaHostUnregister((void *)g_model_host_base);
    }
    g_model_host_base = NULL;
    g_model_device_base = NULL;
    g_model_registered_size = 0;
    g_model_registered = 0;
    g_model_window_registered = 0;
    g_model_window_bytes = 0;
    g_model_device_owned = 0;
    g_model_range_mapping_supported = 1;
    g_model_hmm_direct = 0;
    cuda_nested_residual_clear();
    cuda_model_file_clear();
    cuda_iq1_s_sidecar_clear();
    cuda_q1_0_sidecar_clear();
    g_model_cache_full = 0;
    if (g_model_prefetch_stream) {
        (void)cudaStreamDestroy(g_model_prefetch_stream);
        g_model_prefetch_stream = NULL;
    }
}

extern "C" ds4_gpu_tensor *ds4_gpu_tensor_alloc(uint64_t bytes) {
    if (bytes == 0) bytes = 1;
    ds4_gpu_tensor *t = (ds4_gpu_tensor *)calloc(1, sizeof(*t));
    if (!t) return NULL;
    if (!cuda_ok(cudaMallocManaged(&t->ptr, (size_t)bytes), "tensor alloc")) {
        free(t);
        return NULL;
    }
    t->bytes = bytes;
    t->owner = 1;
    return t;
}

extern "C" ds4_gpu_tensor *ds4_gpu_tensor_view(const ds4_gpu_tensor *base, uint64_t offset, uint64_t bytes) {
    if (!base || offset > base->bytes || bytes > base->bytes - offset) return NULL;
    ds4_gpu_tensor *t = (ds4_gpu_tensor *)calloc(1, sizeof(*t));
    if (!t) return NULL;
    t->ptr = (char *)base->ptr + offset;
    t->bytes = bytes;
    t->owner = 0;
    return t;
}

extern "C" void ds4_gpu_tensor_free(ds4_gpu_tensor *tensor) {
    if (!tensor) return;
    if (tensor->owner && tensor->ptr) (void)cudaFree(tensor->ptr);
    free(tensor);
}

extern "C" uint64_t ds4_gpu_tensor_bytes(const ds4_gpu_tensor *tensor) {
    return tensor ? tensor->bytes : 0;
}

extern "C" void *ds4_gpu_tensor_contents(ds4_gpu_tensor *tensor) {
    if (!tensor) return NULL;
    (void)cudaDeviceSynchronize();
    return tensor->ptr;
}

extern "C" int ds4_gpu_tensor_write(ds4_gpu_tensor *tensor, uint64_t offset, const void *data, uint64_t bytes) {
    if (!tensor || !data || offset > tensor->bytes || bytes > tensor->bytes - offset) return 0;
    return cuda_ok(cudaMemcpy((char *)tensor->ptr + offset, data, (size_t)bytes, cudaMemcpyHostToDevice), "tensor write");
}

extern "C" int ds4_gpu_tensor_read(const ds4_gpu_tensor *tensor, uint64_t offset, void *data, uint64_t bytes) {
    if (!tensor || !data || offset > tensor->bytes || bytes > tensor->bytes - offset) return 0;
    return cuda_ok(cudaMemcpy(data, (const char *)tensor->ptr + offset, (size_t)bytes, cudaMemcpyDeviceToHost), "tensor read");
}

static cuda_dynamic_arena_binding cuda_dynamic_arena_empty_binding(void) {
    const cuda_dynamic_arena_binding empty = {
        UINT32_MAX, DS4_GPU_ARENA_FREE, 0, 0
    };
    return empty;
}

static uint64_t cuda_dynamic_arena_next_generation(void) {
    g_dynamic_arena.next_generation++;
    if (g_dynamic_arena.next_generation == 0) {
        g_dynamic_arena.next_generation++;
    }
    return g_dynamic_arena.next_generation;
}

static int cuda_dynamic_arena_range_valid(
        uint64_t offset,
        uint64_t expert_bytes,
        uint32_t n_expert,
        uint64_t model_size) {
    return expert_bytes != 0 && offset <= model_size &&
        (uint64_t)n_expert <= (model_size - offset) / expert_bytes;
}

static int cuda_dynamic_arena_binding_valid(
        const cuda_dynamic_arena &arena,
        const cuda_dynamic_arena_binding &binding,
        uint32_t layer,
        uint32_t expert,
        uint64_t snapshot_generation,
        ds4_gpu_arena_slot_state required_state) {
    if (binding.slot >= arena.slots.size() ||
        binding.state != (uint32_t)required_state ||
        binding.snapshot_generation != snapshot_generation) {
        return 0;
    }
    const cuda_dynamic_arena_slot &slot = arena.slots[binding.slot];
    return slot.state == required_state &&
        slot.layer == layer && slot.expert == expert &&
        slot.content_generation != 0 &&
        slot.content_generation == binding.slot_generation;
}

static uint64_t cuda_dynamic_arena_fnv1a64_continue(
        const uint8_t *data,
        uint64_t bytes,
        uint64_t checksum) {
    for (uint64_t i = 0; i < bytes; i++) {
        checksum ^= data[i];
        checksum *= UINT64_C(1099511628211);
    }
    return checksum;
}

static uint64_t cuda_dynamic_arena_fnv1a64(
        const uint8_t *data,
        uint64_t bytes) {
    return cuda_dynamic_arena_fnv1a64_continue(
        data, bytes, UINT64_C(14695981039346656037));
}

enum cuda_dynamic_arena_copy_status {
    CUDA_DYNAMIC_ARENA_FATAL = -1,
    CUDA_DYNAMIC_ARENA_MISS = 0,
    CUDA_DYNAMIC_ARENA_ENQUEUED = 1,
};

static cuda_dynamic_arena_copy_status cuda_dynamic_arena_copy_expert_async(
        cuda_dynamic_arena &arena,
        const void *model_map,
        uint32_t layer,
        uint32_t expert,
        uint64_t gate_offset,
        uint64_t up_offset,
        uint64_t down_offset,
        void *gate_dst,
        void *up_dst,
        void *down_dst,
        uint64_t gate_expert_bytes,
        uint64_t up_expert_bytes,
        uint64_t down_expert_bytes) {
    if ((!arena.host_base && !arena.pageable_base) ||
        model_map != arena.model_map ||
        arena.hits_disabled ||
        arena.submissions_blocked ||
        layer >= arena.n_layer ||
        expert >= arena.n_expert) {
        return CUDA_DYNAMIC_ARENA_MISS;
    }
    const ds4_gpu_dynamic_arena_layer &geometry =
        arena.layers[layer];
    if (geometry.gate_offset != gate_offset ||
        geometry.up_offset != up_offset ||
        geometry.down_offset != down_offset) {
        return CUDA_DYNAMIC_ARENA_MISS;
    }
    if (geometry.gate_expert_bytes != gate_expert_bytes ||
        geometry.up_expert_bytes != up_expert_bytes ||
        geometry.down_expert_bytes != down_expert_bytes) {
        arena.fatal_errors++;
        return CUDA_DYNAMIC_ARENA_FATAL;
    }
    const uint32_t entry = layer * arena.n_expert + expert;
    const cuda_dynamic_arena_binding &binding =
        arena.active[entry];
    if (!cuda_dynamic_arena_binding_valid(
            arena,
            binding, layer, expert,
            arena.snapshot_generation,
            DS4_GPU_ARENA_READY)) {
        arena.misses++;
        return CUDA_DYNAMIC_ARENA_MISS;
    }
    cuda_dynamic_arena_slot &slot = arena.slots[binding.slot];
    const char *gate_src = slot.host_ptr;
    const char *up_src = gate_src + gate_expert_bytes;
    const char *down_src = up_src + up_expert_bytes;
    const int q1_profile =
        arena.backing == CUDA_DYNAMIC_ARENA_BACKING_Q1_0 &&
        cuda_q1_0_profile_requested();
    const double enqueue_started = q1_profile ? cuda_wall_sec() : 0.0;
    cudaError_t err = cudaMemcpyAsync(gate_dst, gate_src,
                                      (size_t)gate_expert_bytes,
                                      cudaMemcpyHostToDevice,
                                      g_model_upload_stream);
    if (err == cudaSuccess) {
        err = cudaMemcpyAsync(up_dst, up_src,
                              (size_t)up_expert_bytes,
                              cudaMemcpyHostToDevice,
                              g_model_upload_stream);
    }
    if (err == cudaSuccess) {
        err = cudaMemcpyAsync(down_dst, down_src,
                              (size_t)down_expert_bytes,
                              cudaMemcpyHostToDevice,
                              g_model_upload_stream);
    }
    if (err != cudaSuccess) {
        (void)cudaGetLastError();
        arena.fatal_errors++;
        return CUDA_DYNAMIC_ARENA_FATAL;
    }
    if (q1_profile) {
        const double elapsed = cuda_wall_sec() - enqueue_started;
        if (slot.pageable) {
            g_q1_0_profile.pageable_h2d_enqueue_seconds += elapsed;
        } else {
            g_q1_0_profile.pinned_h2d_enqueue_seconds += elapsed;
        }
    }
    slot.last_dma_sequence = ++arena.dma_sequence;
    arena.hits++;
    arena.bytes_uploaded += gate_expert_bytes +
        up_expert_bytes + down_expert_bytes;
    const uint64_t uploaded = gate_expert_bytes +
        up_expert_bytes + down_expert_bytes;
    if (slot.pageable) {
        arena.pageable_hits++;
        arena.pageable_bytes_uploaded += uploaded;
    } else {
        arena.pinned_hits++;
        arena.pinned_bytes_uploaded += uploaded;
    }
    return CUDA_DYNAMIC_ARENA_ENQUEUED;
}

static void cuda_dynamic_arena_storage_release(void) {
    cuda_q1_0_ssd_wrap_release(0);
    if (g_dynamic_arena.txn) {
        ds4_gpu_dynamic_arena_abort(g_dynamic_arena.txn);
    }
    if (g_dynamic_arena.host_base) {
        if (g_model_upload_stream) {
            (void)cudaStreamSynchronize(g_model_upload_stream);
        }
        (void)cudaFreeHost(g_dynamic_arena.host_base);
        g_dynamic_arena.host_base = NULL;
    }
    if (g_dynamic_arena.pageable_base) {
#ifdef _WIN32
        (void)VirtualFree(g_dynamic_arena.pageable_base, 0, MEM_RELEASE);
#else
        free(g_dynamic_arena.pageable_base);
#endif
        g_dynamic_arena.pageable_base = NULL;
    }
    g_dynamic_arena.allocated_bytes = 0;
    g_dynamic_arena.pageable_bytes = 0;
    g_dynamic_arena.host_budget_bytes = 0;
    g_dynamic_arena.ssd_wrap_ssd_ring_base = NULL;
    g_dynamic_arena.ssd_wrap_h2d_ring_base = NULL;
    g_dynamic_arena.ssd_wrap_ssd_ring_slots = 0;
    g_dynamic_arena.ssd_wrap_h2d_ring_slots = 0;
    g_dynamic_arena.pinned_slot_count = 0;
    g_dynamic_arena.pageable_slot_count = 0;
    g_dynamic_arena.snapshot_generation = 0;
    g_dynamic_arena.submissions_blocked = 0;
    g_dynamic_arena.hits_disabled = 0;
    g_dynamic_arena.tiering_exclusive = 0;
    g_dynamic_arena.slots.clear();
    g_dynamic_arena.active.clear();
    g_dynamic_arena.staging.clear();
    g_dynamic_arena.preloaded.clear();
    g_dynamic_arena.preloaded_parts.clear();
}

static double cuda_dynamic_arena_min_available_gib(void);

static void cuda_q1_0_dynamic_arena_release(int report) {
    cuda_dynamic_arena &arena = g_q1_0_dynamic_arena;
    if (report && arena.host_base && cuda_q1_0_profile_requested()) {
        const double h2d_enqueue_seconds =
            g_q1_0_profile.pinned_h2d_enqueue_seconds +
            g_q1_0_profile.pageable_h2d_enqueue_seconds;
        fprintf(stderr,
                "ds4: [q1-0-profile] result=summary enabled=1 "
                "resident_hits_total=%llu pinned_route_hits=%llu "
                "pageable_route_hits=%llu resident_h2d_bytes_total=%llu "
                "pinned_h2d_bytes=%llu pageable_h2d_bytes=%llu "
                "h2d_enqueue_seconds_total=%.9f "
                "pinned_h2d_enqueue_seconds=%.9f "
                "pageable_h2d_enqueue_seconds=%.9f "
                "upload_sync_calls=%llu upload_sync_seconds_total=%.9f "
                "pinned_upload_sync_seconds=%.9f "
                "pageable_upload_sync_seconds=%.9f "
                "sync_attribution=bytes q1_kernel_calls=%llu "
                "q1_kernel_seconds=%.9f mixed_join_calls=%llu "
                "mixed_join_seconds=%.9f timer_failures=%llu\n",
                (unsigned long long)arena.hits,
                (unsigned long long)arena.pinned_hits,
                (unsigned long long)arena.pageable_hits,
                (unsigned long long)arena.bytes_uploaded,
                (unsigned long long)arena.pinned_bytes_uploaded,
                (unsigned long long)arena.pageable_bytes_uploaded,
                h2d_enqueue_seconds,
                g_q1_0_profile.pinned_h2d_enqueue_seconds,
                g_q1_0_profile.pageable_h2d_enqueue_seconds,
                (unsigned long long)g_q1_0_profile.upload_sync_calls,
                g_q1_0_profile.upload_sync_seconds,
                g_q1_0_profile.pinned_upload_sync_seconds,
                g_q1_0_profile.pageable_upload_sync_seconds,
                (unsigned long long)g_q1_0_profile.q1_kernel_calls,
                g_q1_0_profile.q1_kernel_seconds,
                (unsigned long long)g_q1_0_profile.mixed_join_calls,
                g_q1_0_profile.mixed_join_seconds,
                (unsigned long long)g_q1_0_profile.timer_failures);
    }
    if (report && arena.host_base &&
        (arena.hits || arena.misses || arena.fatal_errors)) {
        fprintf(stderr,
                "ds4: [arena] final hits=%llu misses=%llu fatal=%llu uploaded=%.2f GiB backing=q1_0\n",
                (unsigned long long)arena.hits,
                (unsigned long long)arena.misses,
                (unsigned long long)arena.fatal_errors,
                (double)arena.bytes_uploaded / 1073741824.0);
    }
    if (arena.host_base) {
        if (g_model_upload_stream) {
            (void)cudaStreamSynchronize(g_model_upload_stream);
        }
        (void)cudaFreeHost(arena.host_base);
    }
    if (arena.pageable_base) {
#ifdef _WIN32
        (void)VirtualFree(arena.pageable_base, 0, MEM_RELEASE);
#else
        free(arena.pageable_base);
#endif
    }
    arena = cuda_dynamic_arena{};
    g_q1_0_profile = cuda_q1_0_profile_stats{};
    g_q1_0_dual_sparse_snapshot = cuda_q1_0_dual_sparse_snapshot{};
}

static void cuda_primary_dynamic_arena_release(int report) {
    cuda_q1_0_ssd_wrap_release(report);
    if (report && g_dynamic_arena.host_base &&
        (g_dynamic_arena.hits || g_dynamic_arena.misses ||
         g_dynamic_arena.fatal_errors)) {
        if (g_dynamic_arena.backing == CUDA_DYNAMIC_ARENA_BACKING_Q1_0) {
            fprintf(stderr,
                    "ds4: [arena] final hits=%llu pinned_hits=%llu pageable_hits=%llu misses=%llu fatal=%llu uploaded=%.2f GiB pinned_uploaded=%.2f GiB pageable_uploaded=%.2f GiB backing=q1_0\n",
                    (unsigned long long)g_dynamic_arena.hits,
                    (unsigned long long)g_dynamic_arena.pinned_hits,
                    (unsigned long long)g_dynamic_arena.pageable_hits,
                    (unsigned long long)g_dynamic_arena.misses,
                    (unsigned long long)g_dynamic_arena.fatal_errors,
                    (double)g_dynamic_arena.bytes_uploaded / 1073741824.0,
                    (double)g_dynamic_arena.pinned_bytes_uploaded /
                        1073741824.0,
                    (double)g_dynamic_arena.pageable_bytes_uploaded /
                        1073741824.0);
        } else {
            fprintf(stderr,
                    "ds4: [arena] final hits=%llu misses=%llu fatal=%llu uploaded=%.2f GiB\n",
                    (unsigned long long)g_dynamic_arena.hits,
                    (unsigned long long)g_dynamic_arena.misses,
                    (unsigned long long)g_dynamic_arena.fatal_errors,
                    (double)g_dynamic_arena.bytes_uploaded / 1073741824.0);
        }
    }
    cuda_prefill_mass_observer_release(1);
    cuda_reap_mass_observer_release(1);
    cuda_reap_router_trace_release();
    cuda_dynamic_arena_observer_release();
    cuda_dynamic_arena_storage_release();
    g_dynamic_arena.model_map = NULL;
    g_dynamic_arena.model_size = 0;
    g_dynamic_arena.slot_bytes = 0;
    g_dynamic_arena.hits = 0;
    g_dynamic_arena.misses = 0;
    g_dynamic_arena.fatal_errors = 0;
    g_dynamic_arena.bytes_uploaded = 0;
    g_dynamic_arena.pinned_hits = 0;
    g_dynamic_arena.pageable_hits = 0;
    g_dynamic_arena.pinned_bytes_uploaded = 0;
    g_dynamic_arena.pageable_bytes_uploaded = 0;
    g_dynamic_arena.request_sequence = 0;
    g_dynamic_arena.dma_sequence = 0;
    g_dynamic_arena.n_layer = 0;
    g_dynamic_arena.n_expert = 0;
    g_dynamic_arena.active_layer_first = 0;
    g_dynamic_arena.active_layer_last = 0;
    g_dynamic_arena.backing = CUDA_DYNAMIC_ARENA_BACKING_NONE;
    g_dynamic_arena.layers.clear();
}

extern "C" void ds4_gpu_dynamic_arena_release(void) {
    cuda_q1_0_dynamic_arena_release(1);
    cuda_primary_dynamic_arena_release(1);
}

static int cuda_dynamic_arena_bind(
        const void *model_map, uint64_t model_size,
        const ds4_gpu_dynamic_arena_layer *layers,
        uint32_t n_layer, uint32_t n_expert,
        cuda_dynamic_arena_backing backing,
        uint32_t active_layer_first,
        uint32_t active_layer_last) {
    if (!model_map || model_size == 0 || !layers ||
        n_layer == 0 || n_expert == 0 ||
        backing == CUDA_DYNAMIC_ARENA_BACKING_NONE ||
        active_layer_first >= n_layer ||
        active_layer_last < active_layer_first ||
        active_layer_last >= n_layer) {
        return 0;
    }
    const uint32_t geometry_first =
        backing == CUDA_DYNAMIC_ARENA_BACKING_Q1_0
            ? active_layer_first : 0u;
    const uint32_t geometry_last =
        backing == CUDA_DYNAMIC_ARENA_BACKING_Q1_0
            ? active_layer_last : n_layer - 1u;
    uint64_t slot_bytes = 0;
    for (uint32_t il = geometry_first; il <= geometry_last; il++) {
        const ds4_gpu_dynamic_arena_layer &layer = layers[il];
        if (!cuda_dynamic_arena_range_valid(layer.gate_offset,
                                             layer.gate_expert_bytes,
                                             n_expert, model_size) ||
            !cuda_dynamic_arena_range_valid(layer.up_offset,
                                             layer.up_expert_bytes,
                                             n_expert, model_size) ||
            !cuda_dynamic_arena_range_valid(layer.down_offset,
                                             layer.down_expert_bytes,
                                             n_expert, model_size) ||
            layer.gate_expert_bytes > UINT64_MAX - layer.up_expert_bytes ||
            layer.gate_expert_bytes + layer.up_expert_bytes >
                UINT64_MAX - layer.down_expert_bytes) {
            return 0;
        }
        const uint64_t layer_slot_bytes = layer.gate_expert_bytes +
            layer.up_expert_bytes + layer.down_expert_bytes;
        if (il == geometry_first) slot_bytes = layer_slot_bytes;
        if (layer_slot_bytes != slot_bytes) {
            fprintf(stderr,
                    "ds4: CUDA dynamic arena requires uniform expert geometry "
                    "(layer=%u bytes=%llu expected=%llu)\n",
                    il, (unsigned long long)layer_slot_bytes,
                    (unsigned long long)slot_bytes);
            return 0;
        }
    }
    if (g_dynamic_arena.model_map == model_map &&
        g_dynamic_arena.model_size == model_size &&
        g_dynamic_arena.n_layer == n_layer &&
        g_dynamic_arena.n_expert == n_expert &&
        g_dynamic_arena.slot_bytes == slot_bytes &&
        g_dynamic_arena.backing == backing &&
        g_dynamic_arena.active_layer_first == active_layer_first &&
        g_dynamic_arena.active_layer_last == active_layer_last &&
        g_dynamic_arena.layers.size() == n_layer) {
        int same = 1;
        for (uint32_t il = 0; il < n_layer; il++) {
            if (memcmp(&g_dynamic_arena.layers[il], &layers[il],
                       sizeof(layers[il])) != 0) {
                same = 0;
                break;
            }
        }
        if (same) return 1;
    }
    cuda_primary_dynamic_arena_release(1);
    try {
        g_dynamic_arena.layers.assign(layers, layers + n_layer);
    } catch (...) {
        fprintf(stderr,
                "ds4: CUDA dynamic arena layer metadata allocation failed\n");
        return 0;
    }
    g_dynamic_arena.model_map = model_map;
    g_dynamic_arena.model_size = model_size;
    g_dynamic_arena.n_layer = n_layer;
    g_dynamic_arena.n_expert = n_expert;
    g_dynamic_arena.slot_bytes = slot_bytes;
    g_dynamic_arena.active_layer_first = active_layer_first;
    g_dynamic_arena.active_layer_last = active_layer_last;
    g_dynamic_arena.backing = backing;
    return 1;
}

extern "C" int ds4_gpu_dynamic_arena_bind(
        const void *model_map, uint64_t model_size,
        const ds4_gpu_dynamic_arena_layer *layers,
        uint32_t n_layer, uint32_t n_expert) {
    return cuda_dynamic_arena_bind(
        model_map, model_size, layers, n_layer, n_expert,
        CUDA_DYNAMIC_ARENA_BACKING_PRIMARY, 0u, n_layer ? n_layer - 1u : 0u);
}

extern "C" int ds4_gpu_set_primary_moe_geometry(
        const void *model_map, uint64_t model_size,
        const ds4_gpu_dynamic_arena_layer *layers,
        uint32_t n_layer, uint32_t n_expert) {
    if (!model_map || model_map != g_model_host_base ||
        model_size == 0 || model_size != g_model_registered_size ||
        !layers || n_layer == 0 || n_expert == 0) {
        return 0;
    }
    for (uint32_t layer = 0; layer < n_layer; layer++) {
        const ds4_gpu_dynamic_arena_layer &geometry = layers[layer];
        if (geometry.gate_expert_bytes == 0 ||
            geometry.up_expert_bytes == 0 ||
            geometry.down_expert_bytes == 0 ||
            geometry.gate_expert_bytes > UINT64_MAX / n_expert ||
            geometry.up_expert_bytes > UINT64_MAX / n_expert ||
            geometry.down_expert_bytes > UINT64_MAX / n_expert ||
            !cuda_dynamic_arena_range_valid(
                geometry.gate_offset,
                geometry.gate_expert_bytes, n_expert, model_size) ||
            !cuda_dynamic_arena_range_valid(
                geometry.up_offset,
                geometry.up_expert_bytes, n_expert, model_size) ||
            !cuda_dynamic_arena_range_valid(
                geometry.down_offset,
                geometry.down_expert_bytes, n_expert, model_size)) {
            return 0;
        }
    }
    try {
        g_primary_moe_geometry.assign(layers, layers + n_layer);
    } catch (...) {
        return 0;
    }
    g_primary_moe_geometry_map = model_map;
    g_primary_moe_geometry_size = model_size;
    g_primary_moe_geometry_n_expert = n_expert;
    fprintf(stderr,
            "ds4: primary IQ2 MoE geometry catalog ready: layers=%u experts=%u storage=metadata-only\n",
            n_layer, n_expert);
    return 1;
}

extern "C" int ds4_gpu_dynamic_arena_bind_q1_0(
        const void *model_map, uint64_t model_size,
        const ds4_gpu_dynamic_arena_layer *layers,
        uint32_t n_layer, uint32_t n_expert,
        uint32_t active_layer_first, uint32_t active_layer_last) {
    if (!cuda_q1_0_resident_arena_requested() ||
        !g_q1_0_sidecar_file_valid ||
        model_map != g_q1_0_sidecar_host_base ||
        model_size != g_q1_0_sidecar_size) {
        fprintf(stderr,
                "ds4: [q1-0-resident-arena] result=failed reason=sidecar-binding\n");
        return 0;
    }
    if (!layers || n_layer == 0 || n_expert == 0 ||
        active_layer_first >= n_layer ||
        active_layer_last < active_layer_first ||
        active_layer_last >= n_layer) {
        return 0;
    }
    uint64_t slot_bytes = 0;
    for (uint32_t il = active_layer_first; il <= active_layer_last; il++) {
        const ds4_gpu_dynamic_arena_layer &layer = layers[il];
        if (!cuda_dynamic_arena_range_valid(layer.gate_offset,
                                             layer.gate_expert_bytes,
                                             n_expert, model_size) ||
            !cuda_dynamic_arena_range_valid(layer.up_offset,
                                             layer.up_expert_bytes,
                                             n_expert, model_size) ||
            !cuda_dynamic_arena_range_valid(layer.down_offset,
                                             layer.down_expert_bytes,
                                             n_expert, model_size) ||
            layer.gate_expert_bytes > UINT64_MAX - layer.up_expert_bytes ||
            layer.gate_expert_bytes + layer.up_expert_bytes >
                UINT64_MAX - layer.down_expert_bytes) {
            return 0;
        }
        const uint64_t layer_slot_bytes = layer.gate_expert_bytes +
            layer.up_expert_bytes + layer.down_expert_bytes;
        if (il == active_layer_first) slot_bytes = layer_slot_bytes;
        if (layer_slot_bytes != slot_bytes) {
            fprintf(stderr,
                    "ds4: Q1_0 resident arena requires uniform expert geometry "
                    "(layer=%u bytes=%llu expected=%llu)\n",
                    il, (unsigned long long)layer_slot_bytes,
                    (unsigned long long)slot_bytes);
            return 0;
        }
    }
    cuda_dynamic_arena &arena = g_q1_0_dynamic_arena;
    if (arena.model_map == model_map && arena.model_size == model_size &&
        arena.n_layer == n_layer && arena.n_expert == n_expert &&
        arena.slot_bytes == slot_bytes &&
        arena.active_layer_first == active_layer_first &&
        arena.active_layer_last == active_layer_last &&
        arena.layers.size() == n_layer) {
        int same = 1;
        for (uint32_t il = 0; il < n_layer; il++) {
            if (memcmp(&arena.layers[il], &layers[il],
                       sizeof(layers[il])) != 0) {
                same = 0;
                break;
            }
        }
        if (same) return 1;
    }
    cuda_q1_0_dynamic_arena_release(0);
    try {
        arena.layers.assign(layers, layers + n_layer);
    } catch (...) {
        fprintf(stderr,
                "ds4: Q1_0 resident arena layer metadata allocation failed\n");
        return 0;
    }
    arena.model_map = model_map;
    arena.model_size = model_size;
    arena.n_layer = n_layer;
    arena.n_expert = n_expert;
    arena.slot_bytes = slot_bytes;
    arena.active_layer_first = active_layer_first;
    arena.active_layer_last = active_layer_last;
    arena.backing = CUDA_DYNAMIC_ARENA_BACKING_Q1_0;
    fprintf(stderr,
            "ds4: [q1-0-resident-arena] result=bound backing=q1_0 layers=%u..%u iq2_host_arena=%s mixed_host_backing=%s iq2_vram_cache=q1-routes-bypass\n",
            active_layer_first, active_layer_last,
            cuda_q1_0_dual_arena_requested() ? "enabled" : "disabled",
            cuda_q1_0_dual_arena_requested() ? "dual-arena" : "disabled");
    return 1;
}

extern "C" int ds4_gpu_dynamic_arena_bind_q1_0_snapshot(
        const void *model_map, uint64_t model_size,
        const ds4_gpu_dynamic_arena_layer *layers,
        uint32_t n_layer, uint32_t n_expert,
        uint32_t active_layer_first, uint32_t active_layer_last) {
    if (!cuda_q1_0_snapshot_backing_requested() ||
        !g_q1_0_sidecar_file_valid ||
        model_map != g_q1_0_sidecar_host_base ||
        model_size != g_q1_0_sidecar_size) {
        fprintf(stderr,
                "ds4: [q1-0-snapshot] result=failed reason=sidecar-binding\n");
        return 0;
    }
    const int bound = cuda_dynamic_arena_bind(
        model_map, model_size, layers, n_layer, n_expert,
        CUDA_DYNAMIC_ARENA_BACKING_Q1_0,
        active_layer_first, active_layer_last);
    if (bound) {
        fprintf(stderr,
                "ds4: [q1-0-snapshot] result=bound layers=%u..%u policy=sparse-prefill-ranked iq2_host_snapshot=disabled\n",
                active_layer_first, active_layer_last);
    }
    return bound;
}

extern "C" int ds4_gpu_dynamic_arena_prepare_q1_0(
        uint64_t requested_bytes,
        uint64_t *allocated_bytes,
        uint32_t *slot_count,
        uint64_t *snapshot_generation) {
    if (allocated_bytes) *allocated_bytes = 0;
    if (slot_count) *slot_count = 0;
    if (snapshot_generation) *snapshot_generation = 0;
    cuda_dynamic_arena &arena = g_q1_0_dynamic_arena;
    if (!arena.model_map || arena.backing != CUDA_DYNAMIC_ARENA_BACKING_Q1_0 ||
        arena.slot_bytes == 0 || arena.n_expert == 0 ||
        arena.active_layer_first > arena.active_layer_last) {
        return 0;
    }
    const uint64_t required_entries =
        (uint64_t)(arena.active_layer_last - arena.active_layer_first + 1u) *
        arena.n_expert;
    if (required_entries == 0 || required_entries > UINT32_MAX ||
        arena.slot_bytes > UINT64_MAX / required_entries) {
        return 0;
    }
    const uint64_t required_bytes = required_entries * arena.slot_bytes;
    const int pageable_overflow =
        cuda_q1_0_pageable_overflow_requested() &&
        cuda_q1_0_dual_arena_requested();
    uint64_t pinned_entries = required_entries;
    if (pageable_overflow) {
        pinned_entries = requested_bytes / arena.slot_bytes;
        if (pinned_entries > required_entries) {
            pinned_entries = required_entries;
        }
    }
    if ((!pageable_overflow && requested_bytes < required_bytes) ||
        pinned_entries == 0 || required_bytes > SIZE_MAX) {
        fprintf(stderr,
                "ds4: [q1-0-resident-arena] result=failed reason=capacity "
                "requested=%llu required=%llu pageable_overflow=%u\n",
                (unsigned long long)requested_bytes,
                (unsigned long long)required_bytes,
                pageable_overflow ? 1u : 0u);
        return 0;
    }
    const uint64_t pageable_entries = required_entries - pinned_entries;
    const uint64_t pinned_bytes = pinned_entries * arena.slot_bytes;
    const uint64_t pageable_bytes = pageable_entries * arena.slot_bytes;
    if (pinned_bytes > SIZE_MAX || pageable_bytes > SIZE_MAX) return 0;

    const double min_available_gib = cuda_dynamic_arena_min_available_gib();
#ifdef _WIN32
    MEMORYSTATUSEX memory_status;
    memset(&memory_status, 0, sizeof(memory_status));
    memory_status.dwLength = sizeof(memory_status);
    const int memory_status_ok = GlobalMemoryStatusEx(&memory_status) != 0;
    const double available_before_gib = memory_status_ok
        ? (double)memory_status.ullAvailPhys / 1073741824.0 : -1.0;
#else
    const int memory_status_ok = 0;
    const double available_before_gib = -1.0;
#endif
    if (min_available_gib < 0.0 ||
        (min_available_gib > 0.0 &&
         (!memory_status_ok ||
          (long double)required_bytes >
              (long double)(available_before_gib - min_available_gib) *
                  1073741824.0L))) {
        fprintf(stderr,
                "ds4: [q1-0-resident-arena] result=failed "
                "reason=host-capacity total=%.3f GiB available=%.3f GiB "
                "reserve=%.3f GiB\n",
                (double)required_bytes / 1073741824.0,
                available_before_gib, min_available_gib);
        return 0;
    }

    if (arena.host_base && arena.allocated_bytes == pinned_bytes &&
        arena.pageable_bytes == pageable_bytes &&
        arena.snapshot_generation != 0 &&
        arena.active.size() == (size_t)arena.n_layer * arena.n_expert) {
        if (allocated_bytes) *allocated_bytes = arena.allocated_bytes;
        if (slot_count) *slot_count = (uint32_t)arena.slots.size();
        if (snapshot_generation) {
            *snapshot_generation = arena.snapshot_generation;
        }
        return 1;
    }
    if (arena.host_base || arena.pageable_base) {
        fprintf(stderr,
                "ds4: [q1-0-resident-arena] result=failed reason=unexpected-reprepare\n");
        return 0;
    }

    const size_t binding_count = (size_t)arena.n_layer * arena.n_expert;
    char *host = NULL;
    std::vector<cuda_dynamic_arena_slot> slots;
    std::vector<cuda_dynamic_arena_binding> active;
    std::vector<cuda_dynamic_arena_binding> staging;
    std::vector<cuda_dynamic_arena_binding> preloaded;
    std::vector<uint8_t> preloaded_parts;
    try {
        slots.resize((size_t)required_entries);
        const cuda_dynamic_arena_binding empty =
            cuda_dynamic_arena_empty_binding();
        active.assign(binding_count, empty);
        staging.assign(binding_count, empty);
        preloaded.assign(binding_count, empty);
        preloaded_parts.assign(binding_count, 0);
    } catch (...) {
        return 0;
    }
    if (cudaHostAlloc((void **)&host, (size_t)pinned_bytes,
                      cudaHostAllocDefault) != cudaSuccess) {
        (void)cudaGetLastError();
        fprintf(stderr,
                "ds4: [q1-0-resident-arena] result=failed reason=pinned-allocation bytes=%llu\n",
                (unsigned long long)pinned_bytes);
        return 0;
    }
    char *pageable = NULL;
    if (pageable_bytes != 0) {
#ifdef _WIN32
        pageable = (char *)VirtualAlloc(
            NULL, (SIZE_T)pageable_bytes,
            MEM_RESERVE | MEM_COMMIT, PAGE_READWRITE);
#else
        pageable = (char *)malloc((size_t)pageable_bytes);
#endif
        if (!pageable) {
            (void)cudaFreeHost(host);
            fprintf(stderr,
                    "ds4: [q1-0-resident-arena] result=failed "
                    "reason=pageable-allocation bytes=%llu\n",
                    (unsigned long long)pageable_bytes);
            return 0;
        }
    }

    uint64_t pinned_cursor = 0;
    uint64_t pageable_cursor = 0;
    for (uint32_t slot_index = 0;
         slot_index < (uint32_t)required_entries; slot_index++) {
        cuda_dynamic_arena_slot &slot = slots[slot_index];
        const uint64_t pinned_before =
            (uint64_t)slot_index * pinned_entries / required_entries;
        const uint64_t pinned_after =
            (uint64_t)(slot_index + 1u) * pinned_entries /
            required_entries;
        const int use_pinned = pinned_after > pinned_before;
        slot.host_ptr = use_pinned
            ? host + pinned_cursor++ * arena.slot_bytes
            : pageable + pageable_cursor++ * arena.slot_bytes;
        slot.pageable = use_pinned ? 0u : 1u;
    }
    if (pinned_cursor != pinned_entries ||
        pageable_cursor != pageable_entries) {
        (void)cudaFreeHost(host);
        if (pageable) {
#ifdef _WIN32
            (void)VirtualFree(pageable, 0, MEM_RELEASE);
#else
            free(pageable);
#endif
        }
        fprintf(stderr,
                "ds4: [q1-0-resident-arena] result=failed "
                "reason=slot-partition\n");
        return 0;
    }

    g_q1_0_profile = cuda_q1_0_profile_stats{};
    cuda_q1_0_profile_source_working_set_sample(
        "pre-copy", arena.model_map, arena.model_size);
    cuda_q1_0_source_unlock_stats source_unlock = {};
    cuda_q1_0_source_unlock_begin(&source_unlock);
    uint32_t slot_index = 0;
    uint64_t generation = 1;
    for (uint32_t layer = arena.active_layer_first;
         layer <= arena.active_layer_last; layer++) {
        const ds4_gpu_dynamic_arena_layer &geometry = arena.layers[layer];
        for (uint32_t expert = 0; expert < arena.n_expert; expert++) {
            cuda_dynamic_arena_slot &slot = slots[slot_index];
            char *destination = slot.host_ptr;
            const char *base = (const char *)arena.model_map;
            const char *gate = base + geometry.gate_offset +
                (uint64_t)expert * geometry.gate_expert_bytes;
            const char *up = base + geometry.up_offset +
                (uint64_t)expert * geometry.up_expert_bytes;
            const char *down = base + geometry.down_offset +
                (uint64_t)expert * geometry.down_expert_bytes;
            memcpy(destination, gate, (size_t)geometry.gate_expert_bytes);
            memcpy(destination + geometry.gate_expert_bytes,
                   up, (size_t)geometry.up_expert_bytes);
            memcpy(destination + geometry.gate_expert_bytes +
                       geometry.up_expert_bytes,
                   down, (size_t)geometry.down_expert_bytes);
            slot.layer = layer;
            slot.expert = expert;
            slot.content_generation = generation++;
            slot.checksum = cuda_dynamic_arena_fnv1a64(
                (const uint8_t *)destination, arena.slot_bytes);
            slot.last_dma_sequence = 0;
            slot.state = DS4_GPU_ARENA_READY;
            const uint32_t entry = layer * arena.n_expert + expert;
            active[entry] = {
                slot_index, DS4_GPU_ARENA_READY,
                slot.content_generation, 1
            };
            slot_index++;
        }
        cuda_q1_0_source_unlock_bootstrap_layer(
            arena, geometry, layer, &source_unlock);
    }
    cuda_q1_0_profile_source_working_set_sample(
        "post-bootstrap", arena.model_map, arena.model_size);
    cuda_q1_0_source_unlock_finish(
        &source_unlock, required_entries, required_bytes);
#ifdef _WIN32
    if (cuda_q1_0_profile_requested()) Sleep(1);
#endif
    cuda_q1_0_profile_source_working_set_sample(
        "post-unlock-settle", arena.model_map, arena.model_size);

    arena.submissions_blocked = 1;
    arena.hits_disabled = 1;
    arena.slots.swap(slots);
    arena.active.swap(active);
    arena.staging.swap(staging);
    arena.preloaded.swap(preloaded);
    arena.preloaded_parts.swap(preloaded_parts);
    arena.allocated_bytes = pinned_bytes;
    arena.pageable_base = pageable;
    arena.pageable_bytes = pageable_bytes;
    arena.pinned_slot_count = (uint32_t)pinned_entries;
    arena.pageable_slot_count = (uint32_t)pageable_entries;
    arena.next_generation = generation;
    arena.dma_sequence = 0;
    arena.hits = 0;
    arena.misses = 0;
    arena.fatal_errors = 0;
    arena.bytes_uploaded = 0;
    arena.pinned_hits = 0;
    arena.pageable_hits = 0;
    arena.pinned_bytes_uploaded = 0;
    arena.pageable_bytes_uploaded = 0;
    arena.host_base = host;
    arena.snapshot_generation = 1;
    arena.hits_disabled = 0;
    arena.submissions_blocked = 0;
    g_q1_0_resident_bootstrap_entries = (uint32_t)required_entries;
    if (allocated_bytes) *allocated_bytes = pinned_bytes;
    if (slot_count) *slot_count = (uint32_t)required_entries;
    if (snapshot_generation) *snapshot_generation = 1;
    fprintf(stderr,
            "ds4: [q1-0-resident-arena] result=bootstrapped entries=%u "
            "layers=%u..%u generation=1 source=sidecar-mmap "
            "route_pread=disabled iq2_host_arena=%s "
            "mixed_host_backing=%s pinned=%llu pageable=%llu "
            "pinned_slots=%llu pageable_slots=%llu total_slots=%llu "
            "total_bytes=%llu\n",
            (uint32_t)required_entries,
            arena.active_layer_first, arena.active_layer_last,
            cuda_q1_0_dual_arena_requested() ? "enabled" : "disabled",
            cuda_q1_0_dual_arena_requested() ? "dual-arena" : "disabled",
            (unsigned long long)pinned_bytes,
            (unsigned long long)pageable_bytes,
            (unsigned long long)pinned_entries,
            (unsigned long long)pageable_entries,
            (unsigned long long)required_entries,
            (unsigned long long)required_bytes);
    return 1;
}

extern "C" int ds4_gpu_dynamic_arena_prepare(
        uint64_t requested_bytes,
        uint64_t *allocated_bytes,
        uint32_t *slot_count) {
    if (allocated_bytes) *allocated_bytes = 0;
    if (slot_count) *slot_count = 0;
    if (!g_dynamic_arena.model_map || g_dynamic_arena.slot_bytes == 0 ||
        requested_bytes < g_dynamic_arena.slot_bytes) {
        return 0;
    }
    uint64_t slots64 = requested_bytes / g_dynamic_arena.slot_bytes;
    const uint64_t max_entries =
        (uint64_t)g_dynamic_arena.n_layer * g_dynamic_arena.n_expert;
    if (slots64 > max_entries) slots64 = max_entries;
    if (slots64 == 0 || slots64 > UINT32_MAX) return 0;
    const uint64_t requested_slots64 = slots64;
    const uint64_t requested_capped_bytes =
        requested_slots64 * g_dynamic_arena.slot_bytes;
    const double min_available_gib = cuda_dynamic_arena_min_available_gib();
    double available_before_gib = -1.0;
    int memory_status_ok = 0;
    const char *cap_reason = "ok";
#ifdef _WIN32
    MEMORYSTATUSEX ms_before;
    memset(&ms_before, 0, sizeof(ms_before));
    ms_before.dwLength = sizeof(ms_before);
    if (GlobalMemoryStatusEx(&ms_before)) {
        memory_status_ok = 1;
        available_before_gib =
            (double)ms_before.ullAvailPhys / 1073741824.0;
    }
#endif
    if (min_available_gib < 0.0) {
        slots64 = 0;
        cap_reason = "invalid-min-available";
    } else if (min_available_gib > 0.0) {
        if (!memory_status_ok) {
            slots64 = 0;
            cap_reason = "memory-status-unavailable";
        } else {
            const double budget_gib = available_before_gib - min_available_gib;
            if (budget_gib <= 0.0) {
                slots64 = 0;
            } else {
                const long double budget_bytes_ld =
                    (long double)budget_gib * 1073741824.0L;
                uint64_t budget_slots = 0;
                if (budget_bytes_ld >=
                    (long double)g_dynamic_arena.slot_bytes) {
                    budget_slots =
                        (uint64_t)(budget_bytes_ld /
                                   (long double)g_dynamic_arena.slot_bytes);
                }
                if (budget_slots < slots64) slots64 = budget_slots;
            }
            if (slots64 == 0) cap_reason = "insufficient-available";
        }
    }
    const int ssd_wrap_requested = cuda_q1_0_ssd_wrap_requested();
    if (ssd_wrap_requested < 0) return 0;
    const int primary_ssd_wrap =
        ssd_wrap_requested == 1 &&
        g_dynamic_arena.backing == CUDA_DYNAMIC_ARENA_BACKING_PRIMARY;
    const int q1_pageable_overflow =
        g_dynamic_arena.backing == CUDA_DYNAMIC_ARENA_BACKING_Q1_0 &&
        cuda_q1_0_snapshot_backing_requested() &&
        cuda_q1_0_pageable_overflow_requested();
    uint64_t total_slots64 = slots64;
    if (q1_pageable_overflow) {
        if (g_dynamic_arena.active_layer_first >
                g_dynamic_arena.active_layer_last ||
            g_dynamic_arena.active_layer_last >=
                g_dynamic_arena.n_layer) {
            return 0;
        }
        total_slots64 =
            (uint64_t)(g_dynamic_arena.active_layer_last -
                       g_dynamic_arena.active_layer_first + 1u) *
            g_dynamic_arena.n_expert;
        if (total_slots64 == 0 || total_slots64 > max_entries ||
            total_slots64 > UINT32_MAX || slots64 > total_slots64) {
            return 0;
        }
    }
    uint64_t pinned_allocation_slots64 = slots64;
    uint64_t resident_pinned_slots64 = slots64;
    uint64_t pageable_slots64 = total_slots64 - slots64;
    uint64_t ring_slots64 = 0;
    if (primary_ssd_wrap) {
        uint64_t partition_pinned_slots64 = 0;
        uint64_t partition_pageable_slots64 = 0;
        if (!cuda_q1_0_ssd_wrap_arena_partition(
                slots64 * g_dynamic_arena.slot_bytes,
                g_dynamic_arena.slot_bytes,
                &partition_pinned_slots64,
                &partition_pageable_slots64)) {
            return 0;
        }
        ring_slots64 = CUDA_Q1_0_SSD_WRAP_RING_SLOTS;
        if (partition_pinned_slots64 <= ring_slots64) return 0;
        pinned_allocation_slots64 = partition_pinned_slots64;
        resident_pinned_slots64 = partition_pinned_slots64 - ring_slots64;
        pageable_slots64 = partition_pageable_slots64;
        total_slots64 = resident_pinned_slots64 + pageable_slots64;
        if (total_slots64 == 0 || total_slots64 > UINT32_MAX) return 0;
    }
    const uint64_t bytes =
        pinned_allocation_slots64 * g_dynamic_arena.slot_bytes;
    if (pageable_slots64 != 0 &&
        g_dynamic_arena.slot_bytes > UINT64_MAX / pageable_slots64) {
        return 0;
    }
    const uint64_t pageable_bytes =
        pageable_slots64 * g_dynamic_arena.slot_bytes;
    if (pageable_bytes > UINT64_MAX - bytes) return 0;
    const uint64_t total_storage_bytes = bytes + pageable_bytes;
    if (q1_pageable_overflow && min_available_gib > 0.0) {
        if (!memory_status_ok ||
            (long double)total_storage_bytes >
                (long double)(available_before_gib - min_available_gib) *
                    1073741824.0L) {
            fprintf(stderr,
                    "ds4: [q1-0-pageable-overflow] result=failed reason=host-capacity total=%.3f GiB available=%.3f GiB reserve=%.3f GiB\n",
                    (double)total_storage_bytes / 1073741824.0,
                    available_before_gib, min_available_gib);
            return 0;
        }
    }
    const int cap_capped = slots64 < requested_slots64 ? 1 : 0;
    if (primary_ssd_wrap) {
        fprintf(stderr,
            "ds4: [arena-cap] requested_gib=%.3f min_available_gib=%.3f available_before_gib=%.3f requested_bytes=%llu requested_slots=%llu chosen_bytes=%llu chosen_slots=%llu pageable_bytes=%llu pageable_slots=%llu total_slots=%llu ring_slots=%llu host_budget_bytes=%llu ssd_wrap=1 capped=%d result=%s reason=%s\n",
            (double)requested_capped_bytes / 1073741824.0,
            min_available_gib,
            available_before_gib,
            (unsigned long long)requested_capped_bytes,
            (unsigned long long)requested_slots64,
            (unsigned long long)bytes,
            (unsigned long long)resident_pinned_slots64,
            (unsigned long long)pageable_bytes,
            (unsigned long long)pageable_slots64,
            (unsigned long long)total_slots64,
            (unsigned long long)ring_slots64,
            (unsigned long long)total_storage_bytes,
            cap_capped,
            slots64 == 0 ? "disabled" : "ready",
            cap_reason);
    } else {
        fprintf(stderr,
            "ds4: [arena-cap] requested_gib=%.3f min_available_gib=%.3f available_before_gib=%.3f requested_bytes=%llu requested_slots=%llu chosen_bytes=%llu chosen_slots=%llu pageable_bytes=%llu pageable_slots=%llu total_slots=%llu capped=%d result=%s reason=%s\n",
            (double)requested_capped_bytes / 1073741824.0,
            min_available_gib, available_before_gib,
            (unsigned long long)requested_capped_bytes,
            (unsigned long long)requested_slots64,
            (unsigned long long)bytes,
            (unsigned long long)resident_pinned_slots64,
            (unsigned long long)pageable_bytes,
            (unsigned long long)pageable_slots64,
            (unsigned long long)total_slots64, cap_capped,
            slots64 == 0 ? "disabled" : "ready", cap_reason);
    }
    if (slots64 == 0) return 0;
    if (bytes > (uint64_t)SIZE_MAX ||
        pageable_bytes > (uint64_t)SIZE_MAX) return 0;
    if (g_dynamic_arena.host_base &&
        g_dynamic_arena.allocated_bytes == bytes &&
        g_dynamic_arena.pageable_bytes == pageable_bytes &&
        g_dynamic_arena.host_budget_bytes == total_storage_bytes &&
        g_dynamic_arena.pinned_slot_count == resident_pinned_slots64 &&
        g_dynamic_arena.pageable_slot_count == pageable_slots64 &&
        g_dynamic_arena.ssd_wrap_ssd_ring_slots ==
            (primary_ssd_wrap ? CUDA_Q1_0_SSD_WRAP_SSD_RING_SLOTS : 0u) &&
        g_dynamic_arena.ssd_wrap_h2d_ring_slots ==
            (primary_ssd_wrap ? CUDA_Q1_0_SSD_WRAP_H2D_RING_SLOTS : 0u) &&
        g_dynamic_arena.slots.size() == (size_t)total_slots64) {
        if (allocated_bytes) *allocated_bytes = total_storage_bytes;
        if (slot_count) *slot_count = (uint32_t)total_slots64;
        return 1;
    }

    cuda_dynamic_arena_storage_release();
    const uint64_t stage_bytes = cuda_model_copy_chunk_bytes() +
        (g_model_direct_align > 1 ? g_model_direct_align : 1);
    if (!cuda_model_stage_pool_alloc(stage_bytes)) {
        fprintf(stderr,
                "ds4: CUDA dynamic arena staging preparation failed; arena disabled\n");
        return 0;
    }
    char *host = NULL;
    cudaError_t err = cudaHostAlloc((void **)&host, (size_t)bytes, cudaHostAllocDefault);
    if (err != cudaSuccess || !host) {
        fprintf(stderr,
                "ds4: CUDA dynamic arena allocation %.2f GiB failed: %s; arena disabled\n",
                (double)bytes / 1073741824.0, cudaGetErrorString(err));
        (void)cudaGetLastError();
        return 0;
    }
    char *pageable = NULL;
    if (pageable_bytes != 0) {
#ifdef _WIN32
        pageable = (char *)VirtualAlloc(
            NULL, (SIZE_T)pageable_bytes,
            MEM_RESERVE | MEM_COMMIT, PAGE_READWRITE);
#else
        pageable = (char *)malloc((size_t)pageable_bytes);
#endif
        if (!pageable) {
            (void)cudaFreeHost(host);
            fprintf(stderr,
                    "ds4: Q1_0 pageable overflow allocation %.2f GiB failed; arena disabled\n",
                    (double)pageable_bytes / 1073741824.0);
            return 0;
        }
    }

    try {
        g_dynamic_arena.slots.resize((size_t)total_slots64);
        const size_t bindings =
            (size_t)g_dynamic_arena.n_layer * g_dynamic_arena.n_expert;
        const cuda_dynamic_arena_binding empty = cuda_dynamic_arena_empty_binding();
        g_dynamic_arena.active.assign(bindings, empty);
        g_dynamic_arena.staging.assign(bindings, empty);
        g_dynamic_arena.preloaded.assign(bindings, empty);
        g_dynamic_arena.preloaded_parts.assign(bindings, 0);
    } catch (...) {
        (void)cudaFreeHost(host);
        if (pageable) {
#ifdef _WIN32
            (void)VirtualFree(pageable, 0, MEM_RELEASE);
#else
            free(pageable);
#endif
        }
        g_dynamic_arena.slots.clear();
        g_dynamic_arena.active.clear();
        g_dynamic_arena.staging.clear();
        g_dynamic_arena.preloaded.clear();
        g_dynamic_arena.preloaded_parts.clear();
        fprintf(stderr, "ds4: CUDA dynamic arena metadata allocation failed; arena disabled\n");
        return 0;
    }

    g_dynamic_arena.host_base = host;
    g_dynamic_arena.allocated_bytes = bytes;
    g_dynamic_arena.pageable_base = pageable;
    g_dynamic_arena.pageable_bytes = pageable_bytes;
    g_dynamic_arena.host_budget_bytes = total_storage_bytes;
    g_dynamic_arena.pinned_slot_count =
        (uint32_t)resident_pinned_slots64;
    g_dynamic_arena.pageable_slot_count = (uint32_t)pageable_slots64;
    if (primary_ssd_wrap) {
        g_dynamic_arena.ssd_wrap_ssd_ring_base = host +
            resident_pinned_slots64 * g_dynamic_arena.slot_bytes;
        g_dynamic_arena.ssd_wrap_h2d_ring_base =
            g_dynamic_arena.ssd_wrap_ssd_ring_base +
            (uint64_t)CUDA_Q1_0_SSD_WRAP_SSD_RING_SLOTS *
                g_dynamic_arena.slot_bytes;
        g_dynamic_arena.ssd_wrap_ssd_ring_slots =
            CUDA_Q1_0_SSD_WRAP_SSD_RING_SLOTS;
        g_dynamic_arena.ssd_wrap_h2d_ring_slots =
            CUDA_Q1_0_SSD_WRAP_H2D_RING_SLOTS;
    }
    uint64_t pinned_cursor = 0;
    uint64_t pageable_cursor = 0;
    for (uint32_t i = 0; i < (uint32_t)total_slots64; i++) {
        cuda_dynamic_arena_slot &slot = g_dynamic_arena.slots[i];
        memset(&slot, 0, sizeof(slot));
        const uint64_t pinned_before =
            (uint64_t)i * resident_pinned_slots64 / total_slots64;
        const uint64_t pinned_after =
            (uint64_t)(i + 1u) * resident_pinned_slots64 / total_slots64;
        const int use_pinned = pinned_after > pinned_before;
        if (use_pinned) {
            slot.host_ptr = host +
                pinned_cursor++ * g_dynamic_arena.slot_bytes;
            slot.pageable = 0;
        } else {
            slot.host_ptr = pageable +
                pageable_cursor++ * g_dynamic_arena.slot_bytes;
            slot.pageable = 1;
        }
        slot.layer = UINT32_MAX;
        slot.expert = UINT32_MAX;
        slot.state = DS4_GPU_ARENA_FREE;
    }
    if (pinned_cursor != resident_pinned_slots64 ||
        pageable_cursor != pageable_slots64) {
        cuda_dynamic_arena_storage_release();
        fprintf(stderr,
                "ds4: Q1_0 pageable overflow slot partition failed; arena disabled\n");
        return 0;
    }
    if (allocated_bytes) *allocated_bytes = total_storage_bytes;
    if (slot_count) *slot_count = (uint32_t)total_slots64;
#ifdef _WIN32
    MEMORYSTATUSEX ms;
    memset(&ms, 0, sizeof(ms));
    ms.dwLength = sizeof(ms);
    const double avail_gib = GlobalMemoryStatusEx(&ms)
        ? (double)ms.ullAvailPhys / 1073741824.0 : -1.0;
#else
    const double avail_gib = -1.0;
#endif
    if (primary_ssd_wrap) {
        fprintf(stderr,
            "ds4: CUDA dynamic arena ready pinned=%.2f GiB pageable=%.2f GiB total_slots=%u pinned_slots=%u pageable_slots=%u ring_slots=%u %.2f MiB/slot available_ram=%.2f GiB bytes=%llu host_budget_bytes=%llu slot_bytes=%llu backing=%s iq2_host_arena=%s mixed_host_backing=%s\n",
            (double)bytes / 1073741824.0,
            (double)pageable_bytes / 1073741824.0,
            (uint32_t)total_slots64, (uint32_t)resident_pinned_slots64,
            (uint32_t)pageable_slots64,
            (uint32_t)ring_slots64,
            (double)g_dynamic_arena.slot_bytes / 1048576.0, avail_gib,
            (unsigned long long)bytes,
            (unsigned long long)total_storage_bytes,
            (unsigned long long)g_dynamic_arena.slot_bytes,
            cuda_dynamic_arena_backing_name(g_dynamic_arena.backing),
            g_dynamic_arena.backing == CUDA_DYNAMIC_ARENA_BACKING_Q1_0
                ? "disabled" : "enabled",
            g_dynamic_arena.backing == CUDA_DYNAMIC_ARENA_BACKING_Q1_0
                ? "q1-snapshot-plus-primary-iq2-vram" : "n/a");
    } else {
        fprintf(stderr,
            "ds4: CUDA dynamic arena ready pinned=%.2f GiB pageable=%.2f GiB total_slots=%u pinned_slots=%u pageable_slots=%u %.2f MiB/slot available_ram=%.2f GiB bytes=%llu slot_bytes=%llu backing=%s iq2_host_arena=%s mixed_host_backing=%s\n",
            (double)bytes / 1073741824.0,
            (double)pageable_bytes / 1073741824.0,
            (uint32_t)total_slots64, (uint32_t)resident_pinned_slots64,
            (uint32_t)pageable_slots64,
            (double)g_dynamic_arena.slot_bytes / 1048576.0, avail_gib,
            (unsigned long long)bytes,
            (unsigned long long)g_dynamic_arena.slot_bytes,
            cuda_dynamic_arena_backing_name(g_dynamic_arena.backing),
            g_dynamic_arena.backing == CUDA_DYNAMIC_ARENA_BACKING_Q1_0
                ? "disabled" : "enabled",
            g_dynamic_arena.backing == CUDA_DYNAMIC_ARENA_BACKING_Q1_0
                ? "q1-snapshot-plus-primary-iq2-vram" : "n/a");
    }
    ds4_gpu_dynamic_arena_observer_reset();
    return 1;
}

extern "C" int ds4_gpu_dynamic_arena_begin(
        const uint8_t *target_resident,
        uint32_t entry_count,
        ds4_gpu_dynamic_arena_txn **out_txn,
        const ds4_gpu_dynamic_arena_load **out_loads,
        uint32_t *out_load_count) {
    if (out_txn) *out_txn = NULL;
    if (out_loads) *out_loads = NULL;
    if (out_load_count) *out_load_count = 0;
    const uint64_t expected64 =
        (uint64_t)g_dynamic_arena.n_layer * g_dynamic_arena.n_expert;
    if (!target_resident || !out_txn || !out_loads || !out_load_count ||
        !g_dynamic_arena.host_base || g_dynamic_arena.txn ||
        g_dynamic_arena.tiering_exclusive ||
        expected64 == 0 || expected64 > UINT32_MAX ||
        entry_count != (uint32_t)expected64) {
        return 0;
    }

    uint32_t target_count = 0;
    for (uint32_t i = 0; i < entry_count; i++) {
        if (target_resident[i] && g_sparse_bake_active) {
            const uint32_t layer = i / g_dynamic_arena.n_expert;
            const uint32_t expert = i % g_dynamic_arena.n_expert;
            if (!cuda_sparse_bake_expert_retained(layer, expert)) {
                fprintf(stderr,
                        "ds4: sparse bake rejected arena target layer=%u expert=%u\n",
                        layer, expert);
                return 0;
            }
        }
        target_count += target_resident[i] != 0;
    }
    if (target_count > g_dynamic_arena.slots.size()) return 0;

    ds4_gpu_dynamic_arena_txn *txn =
        new (std::nothrow) ds4_gpu_dynamic_arena_txn();
    if (!txn) return 0;
    txn->base_generation = g_dynamic_arena.snapshot_generation;
    txn->target_generation = cuda_dynamic_arena_next_generation();
    txn->retire_event = NULL;
    txn->failed = 0;
    std::vector<uint8_t> active_slots;
    std::vector<uint32_t> available;
    try {
        txn->target.assign(target_resident, target_resident + entry_count);
        txn->loads.reserve(target_count);
        txn->reserved_slots.reserve(target_count);
        active_slots.assign(g_dynamic_arena.slots.size(), 0);
        available.reserve(g_dynamic_arena.slots.size());
    } catch (...) {
        delete txn;
        return 0;
    }

    if (cudaEventCreateWithFlags(&txn->retire_event,
                                 cudaEventDisableTiming) != cudaSuccess ||
        cudaEventRecord(txn->retire_event,
                        g_model_upload_stream ? g_model_upload_stream : 0) != cudaSuccess ||
        cudaEventSynchronize(txn->retire_event) != cudaSuccess) {
        (void)cudaGetLastError();
        if (txn->retire_event) (void)cudaEventDestroy(txn->retire_event);
        delete txn;
        return 0;
    }

    g_dynamic_arena.txn = txn;
    g_dynamic_arena.submissions_blocked = 1;
    g_dynamic_arena.hits_disabled = 1;
    const cuda_dynamic_arena_binding empty = cuda_dynamic_arena_empty_binding();
    for (uint32_t i = 0; i < entry_count; i++) {
        g_dynamic_arena.staging[i] = empty;
    }

    for (uint32_t entry = 0; entry < entry_count; entry++) {
        const uint32_t layer = entry / g_dynamic_arena.n_expert;
        const uint32_t expert = entry % g_dynamic_arena.n_expert;
        const cuda_dynamic_arena_binding &active = g_dynamic_arena.active[entry];
        if (cuda_dynamic_arena_binding_valid(
                g_dynamic_arena,
                active, layer, expert, txn->base_generation,
                DS4_GPU_ARENA_READY)) {
            active_slots[active.slot] = 1;
            if (target_resident[entry]) {
                cuda_dynamic_arena_binding next = active;
                next.snapshot_generation = txn->target_generation;
                g_dynamic_arena.staging[entry] = next;
            }
        }
        const cuda_dynamic_arena_binding &preloaded =
            g_dynamic_arena.preloaded[entry];
        const int preloaded_loading = cuda_dynamic_arena_binding_valid(
            g_dynamic_arena,
            preloaded, layer, expert, 0,
            DS4_GPU_ARENA_LOADING);
        const int preloaded_staged = cuda_dynamic_arena_binding_valid(
            g_dynamic_arena,
            preloaded, layer, expert, 0,
            DS4_GPU_ARENA_STAGED);
        if (preloaded_loading || preloaded_staged) {
            active_slots[preloaded.slot] = 1;
            if (preloaded_staged && target_resident[entry] &&
                g_dynamic_arena.staging[entry].slot == UINT32_MAX) {
                cuda_dynamic_arena_binding next = preloaded;
                next.snapshot_generation = txn->target_generation;
                g_dynamic_arena.staging[entry] = next;
            }
        }
    }
    for (uint32_t slot = 0; slot < g_dynamic_arena.slots.size(); slot++) {
        if (!active_slots[slot]) available.push_back(slot);
    }

    uint32_t available_cursor = 0;
    try {
        for (uint32_t entry = 0; entry < entry_count; entry++) {
            if (!target_resident[entry] ||
                g_dynamic_arena.staging[entry].slot != UINT32_MAX) {
                continue;
            }
            if (available_cursor >= available.size()) {
                txn->failed = 1;
                ds4_gpu_dynamic_arena_abort(txn);
                return 0;
            }
            const uint32_t layer = entry / g_dynamic_arena.n_expert;
            const uint32_t expert = entry % g_dynamic_arena.n_expert;
            const uint32_t slot_index = available[available_cursor++];
            cuda_dynamic_arena_slot &slot = g_dynamic_arena.slots[slot_index];
            slot.state = DS4_GPU_ARENA_RETIRING;
            slot.layer = layer;
            slot.expert = expert;
            slot.content_generation = cuda_dynamic_arena_next_generation();
            slot.checksum = 0;
            slot.last_dma_sequence = 0;
            slot.state = DS4_GPU_ARENA_LOADING;
            const cuda_dynamic_arena_binding binding = {
                slot_index, DS4_GPU_ARENA_LOADING,
                slot.content_generation, txn->target_generation
            };
            g_dynamic_arena.staging[entry] = binding;
            const ds4_gpu_dynamic_arena_load load = {
                layer, expert, slot_index, slot.content_generation,
                slot.host_ptr, g_dynamic_arena.slot_bytes
            };
            txn->loads.push_back(load);
            txn->reserved_slots.push_back(slot_index);
        }
    } catch (...) {
        txn->failed = 1;
        ds4_gpu_dynamic_arena_abort(txn);
        return 0;
    }

    *out_txn = txn;
    *out_loads = txn->loads.empty() ? NULL : txn->loads.data();
    *out_load_count = (uint32_t)txn->loads.size();
    fprintf(stderr,
            "ds4: [arena] begin base=%llu target=%llu resident=%u loads=%u slots=%u\n",
            (unsigned long long)txn->base_generation,
            (unsigned long long)txn->target_generation,
            target_count, (uint32_t)txn->loads.size(),
            (uint32_t)g_dynamic_arena.slots.size());
    return 1;
}

static int cuda_dynamic_arena_finish_load_impl(
        ds4_gpu_dynamic_arena_txn *txn,
        uint32_t load_index,
        uint64_t checksum,
        int success,
        int verify_checksum) {
    if (!txn || txn != g_dynamic_arena.txn ||
        load_index >= txn->loads.size()) {
        return 0;
    }
    const ds4_gpu_dynamic_arena_load &load = txn->loads[load_index];
    if (load.slot >= g_dynamic_arena.slots.size()) {
        txn->failed = 1;
        return 0;
    }
    cuda_dynamic_arena_slot &slot = g_dynamic_arena.slots[load.slot];
    if (slot.layer != load.layer || slot.expert != load.expert ||
        slot.content_generation != load.slot_generation ||
        slot.state != DS4_GPU_ARENA_LOADING) {
        txn->failed = 1;
        return 0;
    }
    const uint32_t entry = load.layer * g_dynamic_arena.n_expert + load.expert;
    if (!success) {
        slot.state = DS4_GPU_ARENA_POISONED;
        g_dynamic_arena.staging[entry].state = DS4_GPU_ARENA_POISONED;
        txn->failed = 1;
        return 0;
    }
    const uint64_t actual_checksum = verify_checksum ?
        cuda_dynamic_arena_fnv1a64(
            (const uint8_t *)slot.host_ptr, g_dynamic_arena.slot_bytes) :
        checksum;
    if (actual_checksum != checksum) {
        slot.state = DS4_GPU_ARENA_POISONED;
        g_dynamic_arena.staging[entry].state = DS4_GPU_ARENA_POISONED;
        txn->failed = 1;
        return 0;
    }
    slot.checksum = actual_checksum;
    slot.state = DS4_GPU_ARENA_STAGED;
    g_dynamic_arena.staging[entry].state = DS4_GPU_ARENA_STAGED;
    return 1;
}

extern "C" int ds4_gpu_dynamic_arena_finish_load(
        ds4_gpu_dynamic_arena_txn *txn,
        uint32_t load_index,
        uint64_t checksum,
        int success) {
    return cuda_dynamic_arena_finish_load_impl(
        txn, load_index, checksum, success, 1);
}

extern "C" int ds4_gpu_dynamic_arena_publish(
        ds4_gpu_dynamic_arena_txn *txn,
        uint64_t *snapshot_generation) {
    if (snapshot_generation) *snapshot_generation = 0;
    if (!txn || txn != g_dynamic_arena.txn || txn->failed) return 0;
    const uint32_t entries =
        g_dynamic_arena.n_layer * g_dynamic_arena.n_expert;
    uint32_t q1_bootstrap_entries = 0;
    if (g_dynamic_arena.backing == CUDA_DYNAMIC_ARENA_BACKING_Q1_0) {
        const uint64_t expected =
            (uint64_t)(g_dynamic_arena.active_layer_last -
                       g_dynamic_arena.active_layer_first + 1u) *
            g_dynamic_arena.n_expert;
        int target_out_of_range = txn->target.size() != entries;
        uint32_t target_entries = 0;
        if (!target_out_of_range) {
            for (uint32_t entry = 0; entry < entries; entry++) {
                if (!txn->target[entry]) continue;
                const uint32_t layer = entry / g_dynamic_arena.n_expert;
                target_entries++;
                target_out_of_range |=
                    layer < g_dynamic_arena.active_layer_first ||
                    layer > g_dynamic_arena.active_layer_last;
            }
        }
        const int sparse_snapshot =
            cuda_q1_0_snapshot_backing_requested();
        if (expected > UINT32_MAX || target_out_of_range ||
            (!sparse_snapshot && target_entries != (uint32_t)expected) ||
            (sparse_snapshot &&
             (target_entries == 0u ||
              target_entries > g_dynamic_arena.slots.size()))) {
            txn->failed = 1;
            fprintf(stderr,
                    "ds4: [q1-0-resident-arena] result=failed reason=%s target_entries=%u required_entries=%llu capacity=%u router=unchanged\n",
                    sparse_snapshot ? "invalid-sparse-snapshot" :
                        "full-bootstrap-snapshot-required",
                    target_entries, (unsigned long long)expected,
                    (uint32_t)g_dynamic_arena.slots.size());
            return 0;
        }
        q1_bootstrap_entries = target_entries;
    }
    std::vector<uint8_t> referenced;
    try {
        referenced.assign(g_dynamic_arena.slots.size(), 0);
    } catch (...) {
        txn->failed = 1;
        return 0;
    }
    for (uint32_t entry = 0; entry < entries; entry++) {
        if (!txn->target[entry]) continue;
        const uint32_t layer = entry / g_dynamic_arena.n_expert;
        const uint32_t expert = entry % g_dynamic_arena.n_expert;
        cuda_dynamic_arena_binding &binding = g_dynamic_arena.staging[entry];
        if (binding.slot >= g_dynamic_arena.slots.size() ||
            binding.snapshot_generation != txn->target_generation) {
            txn->failed = 1;
            return 0;
        }
        cuda_dynamic_arena_slot &slot = g_dynamic_arena.slots[binding.slot];
        if ((slot.state != DS4_GPU_ARENA_READY &&
             slot.state != DS4_GPU_ARENA_STAGED) ||
            slot.layer != layer || slot.expert != expert ||
            slot.content_generation != binding.slot_generation) {
            txn->failed = 1;
            return 0;
        }
        referenced[binding.slot] = 1;
    }
    /* Validation above is side-effect free. Only after every target is known
     * good do staged slots become visible and bindings become READY. */
    for (uint32_t entry = 0; entry < entries; entry++) {
        if (!txn->target[entry]) continue;
        cuda_dynamic_arena_binding &binding = g_dynamic_arena.staging[entry];
        cuda_dynamic_arena_slot &slot = g_dynamic_arena.slots[binding.slot];
        if (slot.state == DS4_GPU_ARENA_STAGED) {
            slot.state = DS4_GPU_ARENA_READY;
        }
        binding.state = DS4_GPU_ARENA_READY;
    }
    for (uint32_t slot_index = 0;
         slot_index < g_dynamic_arena.slots.size(); slot_index++) {
        if (referenced[slot_index]) continue;
        cuda_dynamic_arena_slot &slot = g_dynamic_arena.slots[slot_index];
        slot.state = DS4_GPU_ARENA_FREE;
        slot.layer = UINT32_MAX;
        slot.expert = UINT32_MAX;
        slot.checksum = 0;
        slot.last_dma_sequence = 0;
    }
    g_dynamic_arena.active.swap(g_dynamic_arena.staging);
    for (uint32_t entry = 0; entry < entries; entry++) {
        g_dynamic_arena.staging[entry] = cuda_dynamic_arena_empty_binding();
        g_dynamic_arena.preloaded[entry] = cuda_dynamic_arena_empty_binding();
        g_dynamic_arena.preloaded_parts[entry] = 0;
    }
    g_dynamic_arena.snapshot_generation = txn->target_generation;
    g_dynamic_arena.submissions_blocked = 0;
    g_dynamic_arena.hits_disabled = 0;
    if (g_dynamic_arena.backing == CUDA_DYNAMIC_ARENA_BACKING_Q1_0) {
        g_q1_0_resident_bootstrap_entries = q1_bootstrap_entries;
    }
    if (snapshot_generation) {
        *snapshot_generation = g_dynamic_arena.snapshot_generation;
    }
    fprintf(stderr,
            "ds4: [arena] publish generation=%llu loads=%u\n",
            (unsigned long long)g_dynamic_arena.snapshot_generation,
            (uint32_t)txn->loads.size());
    if (txn->retire_event) (void)cudaEventDestroy(txn->retire_event);
    g_dynamic_arena.txn = NULL;
    delete txn;
    return 1;
}

extern "C" void ds4_gpu_dynamic_arena_abort(
        ds4_gpu_dynamic_arena_txn *txn) {
    if (!txn || txn != g_dynamic_arena.txn) return;
    for (uint32_t i = 0; i < txn->loads.size(); i++) {
        const ds4_gpu_dynamic_arena_load &load = txn->loads[i];
        if (load.slot >= g_dynamic_arena.slots.size()) continue;
        cuda_dynamic_arena_slot &slot = g_dynamic_arena.slots[load.slot];
        if (slot.content_generation == load.slot_generation &&
            slot.layer == load.layer && slot.expert == load.expert) {
            slot.state = DS4_GPU_ARENA_POISONED;
        }
    }
    const cuda_dynamic_arena_binding empty = cuda_dynamic_arena_empty_binding();
    for (uint32_t entry = 0; entry < g_dynamic_arena.active.size(); entry++) {
        const uint32_t layer = entry / g_dynamic_arena.n_expert;
        const uint32_t expert = entry % g_dynamic_arena.n_expert;
        if (!cuda_dynamic_arena_binding_valid(
                g_dynamic_arena,
                g_dynamic_arena.active[entry], layer, expert,
                g_dynamic_arena.snapshot_generation,
                DS4_GPU_ARENA_READY)) {
            g_dynamic_arena.active[entry] = empty;
        }
        g_dynamic_arena.staging[entry] = empty;
    }
    fprintf(stderr,
            "ds4: [arena] abort base=%llu target=%llu loads=%u failed=%d\n",
            (unsigned long long)txn->base_generation,
            (unsigned long long)txn->target_generation,
            (uint32_t)txn->loads.size(), txn->failed);
    g_dynamic_arena.submissions_blocked = 0;
    g_dynamic_arena.hits_disabled = 0;
    if (txn->retire_event) (void)cudaEventDestroy(txn->retire_event);
    g_dynamic_arena.txn = NULL;
    delete txn;
}

static uint32_t cuda_dynamic_arena_observer_window(void) {
    const char *env = getenv("DS4_CUDA_DYNAMIC_ARENA_OBSERVED_WINDOW");
    if (!env || !env[0]) return 0;
    char *end = NULL;
    errno = 0;
    const unsigned long value = strtoul(env, &end, 10);
    if (errno != 0 || end == env || *end != '\0' ||
        value == 0 || value > 256) {
        fprintf(stderr,
                "ds4: [arena-observe] invalid window '%s'; policy disabled\n",
                env);
        return 0;
    }
    return (uint32_t)value;
}

static uint32_t cuda_dynamic_arena_observer_min_hits(void) {
    const char *env = getenv("DS4_CUDA_DYNAMIC_ARENA_OBSERVED_MIN_HITS");
    if (!env || !env[0]) return 1;
    char *end = NULL;
    errno = 0;
    const unsigned long value = strtoul(env, &end, 10);
    if (errno != 0 || end == env || *end != '\0' ||
        value == 0 || value > 256) {
        fprintf(stderr,
                "ds4: [arena-observe] invalid min-hits '%s'; using 1\n",
                env);
        return 1;
    }
    return (uint32_t)value;
}

static uint32_t cuda_dynamic_arena_observer_grow_interval(void) {
    const char *env = getenv("DS4_CUDA_DYNAMIC_ARENA_GROW_INTERVAL");
    if (!env || !env[0]) return 0;
    char *end = NULL;
    errno = 0;
    const unsigned long value = strtoul(env, &end, 10);
    if (errno != 0 || end == env || *end != '\0' ||
        value == 0 || value > 256) {
        fprintf(stderr,
                "ds4: [arena-observe] invalid grow interval '%s'; growth disabled\n",
                env);
        return 0;
    }
    return (uint32_t)value;
}

static uint32_t cuda_dynamic_arena_observer_workers(uint32_t load_count) {
    uint32_t workers = 8;
    const char *env = getenv("DS4_REAP_PREFETCH_THREADS");
    if (env && env[0]) {
        char *end = NULL;
        errno = 0;
        const unsigned long value = strtoul(env, &end, 10);
        if (errno == 0 && end != env && *end == '\0' &&
            value >= 1 && value <= 32) {
            workers = (uint32_t)value;
        }
    }
    const long cpu_count = os_cpu_count();
    if (cpu_count > 0 && workers > (uint32_t)cpu_count) {
        workers = (uint32_t)cpu_count;
    }
    if (workers > load_count) workers = load_count;
    return workers ? workers : 1;
}

static int cuda_dynamic_arena_copy_load(
        const ds4_gpu_dynamic_arena_load &load,
        uint64_t *checksum) {
    if (!checksum || !load.host_ptr ||
        load.layer >= g_dynamic_arena.n_layer ||
        load.expert >= g_dynamic_arena.n_expert) {
        return 0;
    }
    const ds4_gpu_dynamic_arena_layer &layer =
        g_dynamic_arena.layers[load.layer];
    if (layer.gate_expert_bytes > UINT64_MAX - layer.up_expert_bytes) {
        return 0;
    }
    const uint64_t gate_up_bytes =
        layer.gate_expert_bytes + layer.up_expert_bytes;
    if (gate_up_bytes > UINT64_MAX - layer.down_expert_bytes) return 0;
    const uint64_t slot_bytes = gate_up_bytes + layer.down_expert_bytes;
    if (slot_bytes != load.host_bytes ||
        slot_bytes != g_dynamic_arena.slot_bytes) {
        return 0;
    }
    const uint64_t expert = load.expert;
    const uint64_t gate_offset =
        layer.gate_offset + expert * layer.gate_expert_bytes;
    const uint64_t up_offset =
        layer.up_offset + expert * layer.up_expert_bytes;
    const uint64_t down_offset =
        layer.down_offset + expert * layer.down_expert_bytes;
    if (gate_offset > g_dynamic_arena.model_size ||
        layer.gate_expert_bytes > g_dynamic_arena.model_size - gate_offset ||
        up_offset > g_dynamic_arena.model_size ||
        layer.up_expert_bytes > g_dynamic_arena.model_size - up_offset ||
        down_offset > g_dynamic_arena.model_size ||
        layer.down_expert_bytes > g_dynamic_arena.model_size - down_offset) {
        return 0;
    }

    const uint8_t *model = (const uint8_t *)g_dynamic_arena.model_map;
    uint8_t *destination = (uint8_t *)load.host_ptr;
    memcpy(destination, model + gate_offset,
           (size_t)layer.gate_expert_bytes);
    memcpy(destination + layer.gate_expert_bytes, model + up_offset,
           (size_t)layer.up_expert_bytes);
    memcpy(destination + gate_up_bytes, model + down_offset,
           (size_t)layer.down_expert_bytes);
    *checksum = cuda_dynamic_arena_fnv1a64(destination, slot_bytes);
    return 1;
}

struct cuda_q1_0_dual_sparse_copy_context {
    cuda_dynamic_arena *arena;
    const ds4_gpu_dynamic_arena_load *loads;
    uint32_t load_count;
    std::atomic<uint32_t> next;
    uint8_t *success;
};

static int cuda_q1_0_dual_sparse_copy_load(
        cuda_dynamic_arena &arena,
        const ds4_gpu_dynamic_arena_load &load) {
    if (!load.host_ptr || load.layer >= arena.n_layer ||
        load.expert >= arena.n_expert ||
        load.host_bytes != arena.slot_bytes) {
        return 0;
    }
    const ds4_gpu_dynamic_arena_layer &layer = arena.layers[load.layer];
    if (layer.gate_expert_bytes > UINT64_MAX - layer.up_expert_bytes) {
        return 0;
    }
    const uint64_t gate_up_bytes =
        layer.gate_expert_bytes + layer.up_expert_bytes;
    if (gate_up_bytes > UINT64_MAX - layer.down_expert_bytes ||
        gate_up_bytes + layer.down_expert_bytes != arena.slot_bytes) {
        return 0;
    }
    const uint64_t expert = load.expert;
    const uint64_t gate_offset =
        layer.gate_offset + expert * layer.gate_expert_bytes;
    const uint64_t up_offset =
        layer.up_offset + expert * layer.up_expert_bytes;
    const uint64_t down_offset =
        layer.down_offset + expert * layer.down_expert_bytes;
    if (gate_offset > arena.model_size ||
        layer.gate_expert_bytes > arena.model_size - gate_offset ||
        up_offset > arena.model_size ||
        layer.up_expert_bytes > arena.model_size - up_offset ||
        down_offset > arena.model_size ||
        layer.down_expert_bytes > arena.model_size - down_offset) {
        return 0;
    }
    uint8_t *destination = (uint8_t *)load.host_ptr;
    return cuda_pread_full(
               &g_q1_0_sidecar_file, destination,
               layer.gate_expert_bytes, gate_offset) &&
           cuda_pread_full(
               &g_q1_0_sidecar_file,
               destination + layer.gate_expert_bytes,
               layer.up_expert_bytes, up_offset) &&
           cuda_pread_full(
               &g_q1_0_sidecar_file,
               destination + gate_up_bytes,
               layer.down_expert_bytes, down_offset);
}

static void *cuda_q1_0_dual_sparse_copy_worker(void *arg) {
    cuda_q1_0_dual_sparse_copy_context *context =
        (cuda_q1_0_dual_sparse_copy_context *)arg;
    for (;;) {
        const uint32_t cursor =
            context->next.fetch_add(1, std::memory_order_relaxed);
        if (cursor >= context->load_count) break;
        context->success[cursor] = cuda_q1_0_dual_sparse_copy_load(
            *context->arena, context->loads[cursor]) ? 1u : 0u;
    }
    return NULL;
}

static void cuda_q1_0_dual_sparse_abort(const char *reason) {
    cuda_dynamic_arena &arena = g_q1_0_dynamic_arena;
    arena.submissions_blocked = 1;
    arena.hits_disabled = 1;
    arena.snapshot_generation = 0;
    arena.active.clear();
    arena.staging.clear();
    g_q1_0_dual_sparse_snapshot.staged = 0;
    g_q1_0_dual_sparse_snapshot.ready = 0;
    g_q1_0_dual_sparse_failures++;
    fprintf(stderr,
            "ds4: [q1-0-dual-sparse] result=failed reason=%s\n",
            reason ? reason : "unknown");
}

static int cuda_q1_0_dual_sparse_stage(
        const uint8_t *target, uint32_t entry_count) {
    if (!cuda_q1_0_dual_sparse_companion_requested()) return 1;
    const double started = cuda_wall_sec();
    cuda_dynamic_arena &arena = g_q1_0_dynamic_arena;
    if (!target || entry_count == 0 ||
        !cuda_q1_0_resident_arena_requested() ||
        !cuda_q1_0_dual_arena_requested() ||
        !cuda_q1_0_mixed_cold_one_requested() ||
        g_dynamic_arena.backing != CUDA_DYNAMIC_ARENA_BACKING_PRIMARY ||
        entry_count != g_dynamic_arena.n_layer * g_dynamic_arena.n_expert ||
        !arena.model_map || arena.model_map != g_q1_0_sidecar_host_base ||
        arena.model_size != g_q1_0_sidecar_size ||
        arena.backing != CUDA_DYNAMIC_ARENA_BACKING_Q1_0 ||
        arena.n_layer != g_dynamic_arena.n_layer ||
        arena.n_expert != g_dynamic_arena.n_expert ||
        arena.slot_bytes == 0 || arena.host_base ||
        !g_q1_0_sidecar_file_valid) {
        cuda_q1_0_dual_sparse_abort("contract");
        return 0;
    }

    uint32_t candidate_entries = 0;
    for (uint32_t entry = 0; entry < entry_count; entry++) {
        if (!target[entry]) continue;
        const uint32_t layer = entry / arena.n_expert;
        if (layer < arena.active_layer_first ||
            layer > arena.active_layer_last) {
            cuda_q1_0_dual_sparse_abort("target-layer");
            return 0;
        }
        candidate_entries++;
    }
    if (candidate_entries == 0 ||
        candidate_entries > g_dynamic_arena.slots.size() ||
        arena.slot_bytes > UINT64_MAX / candidate_entries) {
        cuda_q1_0_dual_sparse_abort("capacity");
        return 0;
    }
    const uint64_t required_bytes =
        arena.slot_bytes * (uint64_t)candidate_entries;
    if (required_bytes > SIZE_MAX) {
        cuda_q1_0_dual_sparse_abort("size");
        return 0;
    }
    if (g_model_upload_stream) {
        if (!cuda_ok(cudaStreamSynchronize(g_model_upload_stream),
                     "Q1_0 dual sparse stage sync")) {
            cuda_q1_0_dual_sparse_abort("upload-sync");
            return 0;
        }
    }
    if (arena.pageable_base && arena.pageable_bytes < required_bytes) {
#ifdef _WIN32
        (void)VirtualFree(arena.pageable_base, 0, MEM_RELEASE);
#else
        free(arena.pageable_base);
#endif
        arena.pageable_base = NULL;
        arena.pageable_bytes = 0;
    }
    if (!arena.pageable_base) {
#ifdef _WIN32
        arena.pageable_base = (char *)VirtualAlloc(
            NULL, (SIZE_T)required_bytes,
            MEM_RESERVE | MEM_COMMIT, PAGE_READWRITE);
#else
        arena.pageable_base = (char *)malloc((size_t)required_bytes);
#endif
        if (!arena.pageable_base) {
            cuda_q1_0_dual_sparse_abort("pageable-allocation");
            return 0;
        }
        arena.pageable_bytes = required_bytes;
    }

    const size_t binding_count = (size_t)arena.n_layer * arena.n_expert;
    std::vector<cuda_dynamic_arena_slot> slots;
    std::vector<cuda_dynamic_arena_binding> active;
    std::vector<cuda_dynamic_arena_binding> staging;
    std::vector<ds4_gpu_dynamic_arena_load> loads;
    std::vector<uint8_t> success;
    try {
        slots.resize(candidate_entries);
        const cuda_dynamic_arena_binding empty =
            cuda_dynamic_arena_empty_binding();
        active.assign(binding_count, empty);
        staging.assign(binding_count, empty);
        loads.reserve(candidate_entries);
        success.assign(candidate_entries, 0u);
    } catch (...) {
        cuda_q1_0_dual_sparse_abort("metadata-allocation");
        return 0;
    }

    uint32_t slot_index = 0;
    uint64_t content_generation = 1;
    for (uint32_t entry = 0; entry < entry_count; entry++) {
        if (!target[entry]) continue;
        const uint32_t layer = entry / arena.n_expert;
        const uint32_t expert = entry % arena.n_expert;
        char *destination = arena.pageable_base +
            (uint64_t)slot_index * arena.slot_bytes;
        cuda_dynamic_arena_slot &slot = slots[slot_index];
        slot.host_ptr = destination;
        slot.layer = layer;
        slot.expert = expert;
        slot.content_generation = content_generation++;
        slot.checksum = 0;
        slot.last_dma_sequence = 0;
        slot.state = DS4_GPU_ARENA_LOADING;
        slot.pageable = 1u;
        staging[entry] = {
            slot_index, DS4_GPU_ARENA_STAGED,
            slot.content_generation, 0
        };
        loads.push_back({
            layer, expert, slot_index, slot.content_generation,
            destination, arena.slot_bytes
        });
        slot_index++;
    }

    cuda_q1_0_dual_sparse_copy_context context = {};
    context.arena = &arena;
    context.loads = loads.data();
    context.load_count = candidate_entries;
    context.next.store(0, std::memory_order_relaxed);
    context.success = success.data();
    const uint32_t worker_count =
        cuda_dynamic_arena_observer_workers(candidate_entries);
    std::vector<os_thread_t> threads(worker_count > 0 ? worker_count - 1u : 0u);
    std::vector<os_thread_t> started_threads;
    for (uint32_t i = 0; i < threads.size(); i++) {
        if (os_thread_create(
                &threads[i], cuda_q1_0_dual_sparse_copy_worker,
                &context) == 0) {
            started_threads.push_back(threads[i]);
        }
    }
    (void)cuda_q1_0_dual_sparse_copy_worker(&context);
    for (size_t i = 0; i < started_threads.size(); i++) {
        os_thread_join(started_threads[i]);
    }
    for (uint32_t i = 0; i < candidate_entries; i++) {
        if (!success[i]) {
            cuda_q1_0_dual_sparse_abort("copy");
            return 0;
        }
        slots[i].state = DS4_GPU_ARENA_STAGED;
    }

    arena.submissions_blocked = 1;
    arena.hits_disabled = 1;
    arena.snapshot_generation = 0;
    arena.slots.swap(slots);
    arena.active.swap(active);
    arena.staging.swap(staging);
    arena.preloaded.assign(binding_count, cuda_dynamic_arena_empty_binding());
    arena.preloaded_parts.assign(binding_count, 0u);
    arena.allocated_bytes = 0;
    arena.pinned_slot_count = 0;
    arena.pageable_slot_count = candidate_entries;
    arena.next_generation = content_generation;
    g_q1_0_dual_sparse_snapshot.candidate_fnv1a64 =
        cuda_dynamic_arena_fnv1a64(target, entry_count);
    g_q1_0_dual_sparse_snapshot.primary_generation = 0;
    g_q1_0_dual_sparse_snapshot.q1_generation = 0;
    g_q1_0_dual_sparse_snapshot.candidate_entries = candidate_entries;
    g_q1_0_dual_sparse_snapshot.staged = 1;
    g_q1_0_dual_sparse_snapshot.ready = 0;
    g_q1_0_dual_sparse_seconds = cuda_wall_sec() - started;
    fprintf(stderr,
            "ds4: [q1-0-dual-sparse] result=staged entries=%u "
            "bytes=%llu workers=%u seconds=%.3f candidate_fnv1a64=%016llx "
            "storage=pageable source=pread router=unchanged\n",
            candidate_entries, (unsigned long long)required_bytes,
            1u + (uint32_t)started_threads.size(),
            g_q1_0_dual_sparse_seconds,
            (unsigned long long)
                g_q1_0_dual_sparse_snapshot.candidate_fnv1a64);
    return 1;
}

static int cuda_q1_0_dual_sparse_commit(
        const uint8_t *target, uint32_t entry_count,
        uint64_t primary_generation) {
    if (!cuda_q1_0_dual_sparse_companion_requested()) return 1;
    cuda_dynamic_arena &arena = g_q1_0_dynamic_arena;
    const uint64_t candidate_hash = target && entry_count
        ? cuda_dynamic_arena_fnv1a64(target, entry_count) : 0;
    if (!g_q1_0_dual_sparse_snapshot.staged ||
        g_q1_0_dual_sparse_snapshot.ready ||
        candidate_hash == 0 ||
        candidate_hash != g_q1_0_dual_sparse_snapshot.candidate_fnv1a64 ||
        primary_generation == 0 ||
        g_dynamic_arena.snapshot_generation != primary_generation ||
        arena.staging.size() != (size_t)entry_count ||
        arena.active.size() != (size_t)entry_count) {
        cuda_q1_0_dual_sparse_abort("commit-contract");
        return 0;
    }
    uint32_t committed = 0;
    for (uint32_t entry = 0; entry < entry_count; entry++) {
        const uint32_t layer = entry / arena.n_expert;
        const uint32_t expert = entry % arena.n_expert;
        if (!target[entry]) continue;
        if (!cuda_dynamic_arena_binding_valid(
                g_dynamic_arena, g_dynamic_arena.active[entry],
                layer, expert, primary_generation,
                DS4_GPU_ARENA_READY)) {
            cuda_q1_0_dual_sparse_abort("primary-parity");
            return 0;
        }
        cuda_dynamic_arena_binding &binding = arena.staging[entry];
        if (binding.slot >= arena.slots.size() ||
            binding.state != DS4_GPU_ARENA_STAGED) {
            cuda_q1_0_dual_sparse_abort("q1-stage-parity");
            return 0;
        }
        cuda_dynamic_arena_slot &slot = arena.slots[binding.slot];
        if (slot.layer != layer || slot.expert != expert ||
            slot.state != DS4_GPU_ARENA_STAGED ||
            slot.content_generation != binding.slot_generation) {
            cuda_q1_0_dual_sparse_abort("q1-slot-parity");
            return 0;
        }
        slot.state = DS4_GPU_ARENA_READY;
        binding.state = DS4_GPU_ARENA_READY;
        binding.snapshot_generation = primary_generation;
        arena.active[entry] = binding;
        arena.staging[entry] = cuda_dynamic_arena_empty_binding();
        committed++;
    }
    if (committed != g_q1_0_dual_sparse_snapshot.candidate_entries) {
        cuda_q1_0_dual_sparse_abort("entry-count");
        return 0;
    }
    arena.snapshot_generation = primary_generation;
    arena.submissions_blocked = 0;
    arena.hits_disabled = 0;
    g_q1_0_dual_sparse_snapshot.primary_generation = primary_generation;
    g_q1_0_dual_sparse_snapshot.q1_generation = primary_generation;
    g_q1_0_dual_sparse_snapshot.staged = 0;
    g_q1_0_dual_sparse_snapshot.ready = 1;
    g_q1_0_dual_sparse_entries = committed;
    g_q1_0_dual_sparse_bytes =
        (uint64_t)committed * arena.slot_bytes;
    g_q1_0_dual_sparse_publications++;
    g_q1_0_dual_sparse_published_candidate_fnv1a64 = candidate_hash;
    g_q1_0_dual_sparse_published_primary_generation = primary_generation;
    g_q1_0_dual_sparse_published_q1_generation = primary_generation;
    g_q1_0_dual_sparse_published_ready = 1;
    g_q1_0_resident_bootstrap_entries = committed;
    fprintf(stderr,
            "ds4: [q1-0-dual-sparse] result=published entries=%u "
            "bytes=%llu primary_generation=%llu q1_generation=%llu "
            "candidate_fnv1a64=%016llx pair=ready storage=pageable\n",
            committed, (unsigned long long)g_q1_0_dual_sparse_bytes,
            (unsigned long long)primary_generation,
            (unsigned long long)arena.snapshot_generation,
            (unsigned long long)candidate_hash);
    return 1;
}

struct cuda_dynamic_arena_wrap_context {
    const ds4_gpu_dynamic_arena_load *loads;
    const uint32_t *order;
    uint32_t load_count;
    std::atomic<uint32_t> next;
    uint64_t *checksums;
    uint8_t *success;
};

enum cuda_dynamic_arena_wrap_schedule {
    CUDA_DYNAMIC_ARENA_WRAP_EXPERT_MAJOR = 0,
    CUDA_DYNAMIC_ARENA_WRAP_SOURCE_PARTS = 1,
};

struct cuda_dynamic_arena_wrap_part {
    uint32_t load_index;
    uint8_t part;
    uint64_t source_offset;
    uint64_t bytes;
    uint64_t destination_offset;
};

struct cuda_dynamic_arena_part_copy_context {
    const ds4_gpu_dynamic_arena_load *loads;
    uint32_t load_count;
    const cuda_dynamic_arena_wrap_part *parts;
    uint32_t part_count;
    uint32_t cursor_begin;
    uint32_t cursor_end;
    std::atomic<uint32_t> next;
    uint64_t *checksums;
    uint8_t *success;
    uint8_t phase_part;
    const os_file_t *source_file;
    int checksum_parts;
    int profile_parts;
    double slow_part_threshold_seconds;
    std::atomic<uint32_t> profile_worker_next;
    struct cuda_dynamic_arena_part_worker_profile *profile_workers;
    uint32_t profile_worker_capacity;
};

struct cuda_dynamic_arena_file_qd_profile {
