enum cuda_dynamic_arena_mirror_part : uint8_t {
    CUDA_DYNAMIC_ARENA_MIRROR_GATE = 1u,
    CUDA_DYNAMIC_ARENA_MIRROR_UP = 2u,
    CUDA_DYNAMIC_ARENA_MIRROR_DOWN = 4u,
    CUDA_DYNAMIC_ARENA_MIRROR_COMPLETE = 7u,
};

struct cuda_dynamic_arena_verify_context {
    const uint32_t *entries;
    uint32_t entry_count;
    std::atomic<uint32_t> next;
    uint64_t *checksums;
    uint8_t *success;
};

static void *cuda_dynamic_arena_wrap_worker(void *arg) {
    cuda_dynamic_arena_wrap_context *context =
        (cuda_dynamic_arena_wrap_context *)arg;
    for (;;) {
        const uint32_t cursor =
            context->next.fetch_add(1, std::memory_order_relaxed);
        if (cursor >= context->load_count) break;
        const uint32_t load_index = context->order[cursor];
        uint64_t checksum = 0;
        const int copied = cuda_dynamic_arena_copy_load(
            context->loads[load_index], &checksum);
        context->checksums[load_index] = checksum;
        context->success[load_index] = copied ? 1u : 0u;
    }
    return NULL;
}

static int cuda_dynamic_arena_wrap_add_part(
        std::vector<cuda_dynamic_arena_wrap_part> &parts,
        uint32_t load_index,
        uint8_t part,
        uint64_t base_offset,
        uint64_t expert,
        uint64_t expert_bytes,
        uint64_t destination_offset,
        uint64_t host_bytes) {
    if (expert_bytes == 0 ||
        (expert != 0 && expert_bytes > UINT64_MAX / expert)) {
        return 0;
    }
    const uint64_t expert_delta = expert * expert_bytes;
    if (base_offset > UINT64_MAX - expert_delta) return 0;
    const uint64_t source_offset = base_offset + expert_delta;
    if (source_offset > g_dynamic_arena.model_size ||
        expert_bytes > g_dynamic_arena.model_size - source_offset ||
        destination_offset > host_bytes ||
        expert_bytes > host_bytes - destination_offset) {
        return 0;
    }
    parts.push_back({
        load_index, part, source_offset, expert_bytes, destination_offset
    });
    return 1;
}

static int cuda_dynamic_arena_wrap_build_source_parts(
        const ds4_gpu_dynamic_arena_load *loads,
        uint32_t load_count,
        std::vector<cuda_dynamic_arena_wrap_part> &parts) {
    if (!loads || load_count > UINT32_MAX / 3u) return 0;
    try {
        parts.clear();
        parts.reserve((size_t)load_count * 3u);
        for (uint32_t i = 0; i < load_count; i++) {
            const ds4_gpu_dynamic_arena_load &load = loads[i];
            if (!load.host_ptr ||
                load.layer >= g_dynamic_arena.n_layer ||
                load.expert >= g_dynamic_arena.n_expert) {
                fprintf(stderr,
                        "ds4: [arena-source-parts] invalid-load index=%u layer=%u expert=%u host=%p layers=%u experts=%u\n",
                        i, load.layer, load.expert, load.host_ptr,
                        g_dynamic_arena.n_layer, g_dynamic_arena.n_expert);
                return 0;
            }
            const ds4_gpu_dynamic_arena_layer &layer =
                g_dynamic_arena.layers[load.layer];
            if (layer.gate_expert_bytes >
                    UINT64_MAX - layer.up_expert_bytes) {
                fprintf(stderr,
                        "ds4: [arena-source-parts] geometry-overflow index=%u layer=%u\n",
                        i, load.layer);
                return 0;
            }
            const uint64_t gate_up_bytes =
                layer.gate_expert_bytes + layer.up_expert_bytes;
            if (gate_up_bytes > UINT64_MAX - layer.down_expert_bytes ||
                gate_up_bytes + layer.down_expert_bytes != load.host_bytes ||
                load.host_bytes != g_dynamic_arena.slot_bytes) {
                fprintf(stderr,
                        "ds4: [arena-source-parts] geometry-mismatch index=%u layer=%u expert=%u gate=%llu up=%llu down=%llu host=%llu slot=%llu\n",
                        i, load.layer, load.expert,
                        (unsigned long long)layer.gate_expert_bytes,
                        (unsigned long long)layer.up_expert_bytes,
                        (unsigned long long)layer.down_expert_bytes,
                        (unsigned long long)load.host_bytes,
                        (unsigned long long)g_dynamic_arena.slot_bytes);
                return 0;
            }
            const uint64_t expert = load.expert;
            if (!cuda_dynamic_arena_wrap_add_part(
                    parts, i, CUDA_DYNAMIC_ARENA_MIRROR_GATE,
                    layer.gate_offset, expert, layer.gate_expert_bytes,
                    0, load.host_bytes) ||
                !cuda_dynamic_arena_wrap_add_part(
                    parts, i, CUDA_DYNAMIC_ARENA_MIRROR_UP,
                    layer.up_offset, expert, layer.up_expert_bytes,
                    layer.gate_expert_bytes, load.host_bytes) ||
                !cuda_dynamic_arena_wrap_add_part(
                    parts, i, CUDA_DYNAMIC_ARENA_MIRROR_DOWN,
                    layer.down_offset, expert, layer.down_expert_bytes,
                    gate_up_bytes, load.host_bytes)) {
                fprintf(stderr,
                        "ds4: [arena-source-parts] range-failed index=%u layer=%u expert=%u gate_off=%llu up_off=%llu down_off=%llu gate=%llu up=%llu down=%llu model=%llu\n",
                        i, load.layer, load.expert,
                        (unsigned long long)layer.gate_offset,
                        (unsigned long long)layer.up_offset,
                        (unsigned long long)layer.down_offset,
                        (unsigned long long)layer.gate_expert_bytes,
                        (unsigned long long)layer.up_expert_bytes,
                        (unsigned long long)layer.down_expert_bytes,
                        (unsigned long long)g_dynamic_arena.model_size);
                return 0;
            }
        }
        std::sort(parts.begin(), parts.end(),
            [](const cuda_dynamic_arena_wrap_part &a,
               const cuda_dynamic_arena_wrap_part &b) {
                if (a.source_offset != b.source_offset) {
                    return a.source_offset < b.source_offset;
                }
                if (a.load_index != b.load_index) {
                    return a.load_index < b.load_index;
                }
                return a.part < b.part;
            });
    } catch (...) {
        parts.clear();
        return 0;
    }
    return parts.size() == (size_t)load_count * 3u;
}

static int cuda_dynamic_arena_wrap_layout_profile_enabled(void) {
    const char *value = getenv("DS4_CUDA_ARENA_WRAP_LAYOUT_PROFILE");
    if (!value || !value[0] || strcmp(value, "0") == 0) return 0;
    if (strcmp(value, "1") == 0) return 1;
    static int warned = 0;
    if (!warned) {
        fprintf(stderr,
                "ds4: [arena-wrap-layout-profile] invalid enable value '%s'; disabled\n",
                value);
        warned = 1;
    }
    return 0;
}

struct cuda_dynamic_arena_layout_projection {
    uint64_t reads;
    uint64_t bytes;
};

static const char *cuda_dynamic_arena_wrap_part_name(uint8_t part);

static int cuda_dynamic_arena_wrap_emit_layout_profile(
        const ds4_gpu_dynamic_arena_load *loads,
        uint32_t load_count,
        const std::vector<cuda_dynamic_arena_wrap_part> &parts) {
    if ((!loads && load_count != 0) ||
        parts.size() != (size_t)load_count * 3u) {
        return 0;
    }
    uint64_t page_size = 4096;
#ifdef _WIN32
    SYSTEM_INFO system_info;
    GetSystemInfo(&system_info);
    if (system_info.dwPageSize) page_size = system_info.dwPageSize;
#else
    const long observed_page_size = sysconf(_SC_PAGESIZE);
    if (observed_page_size > 0) page_size = (uint64_t)observed_page_size;
#endif

    const uint8_t phases[3] = {
        CUDA_DYNAMIC_ARENA_MIRROR_GATE,
        CUDA_DYNAMIC_ARENA_MIRROR_UP,
        CUDA_DYNAMIC_ARENA_MIRROR_DOWN,
    };
    const uint64_t thresholds[4] = {0, 4096, 65536, 1048576};
    for (uint32_t phase_index = 0; phase_index < 3u; phase_index++) {
        const uint8_t phase = phases[phase_index];
        uint64_t part_count = 0;
        uint64_t payload_bytes = 0;
        uint64_t gap_count = 0;
        uint64_t overlap_count = 0;
        uint64_t gap_eq0 = 0;
        uint64_t gap_1_4k = 0;
        uint64_t gap_4k_64k = 0;
        uint64_t gap_64k_1m = 0;
        uint64_t gap_gt1m = 0;
        uint64_t source_aligned = 0;
        uint64_t bytes_aligned = 0;
        uint64_t destination_aligned = 0;
        uint64_t previous_end = 0;
        int have_previous = 0;
        cuda_dynamic_arena_layout_projection projections[4] = {};

        for (size_t cursor = 0; cursor < parts.size(); cursor++) {
            const cuda_dynamic_arena_wrap_part &part = parts[cursor];
            if (part.part != phase) continue;
            if (part.load_index >= load_count || part.bytes == 0 ||
                part.source_offset > UINT64_MAX - part.bytes) {
                return 0;
            }
            const ds4_gpu_dynamic_arena_load &load = loads[part.load_index];
            if (!load.host_ptr || part.destination_offset > load.host_bytes ||
                part.bytes > load.host_bytes - part.destination_offset) {
                return 0;
            }

            const uint64_t part_end = part.source_offset + part.bytes;
            payload_bytes += part.bytes;
            if (part.source_offset % page_size == 0) source_aligned++;
            if (part.bytes % page_size == 0) bytes_aligned++;
            const uintptr_t destination =
                (uintptr_t)load.host_ptr + (uintptr_t)part.destination_offset;
            if ((uint64_t)(destination % page_size) == 0) {
                destination_aligned++;
            }

            if (!have_previous) {
                for (uint32_t i = 0; i < 4u; i++) {
                    projections[i].reads = 1;
                    projections[i].bytes = part.bytes;
                }
                have_previous = 1;
            } else if (part.source_offset < previous_end) {
                overlap_count++;
                const uint64_t extension = part_end > previous_end ?
                    part_end - previous_end : 0;
                for (uint32_t i = 0; i < 4u; i++) {
                    projections[i].bytes += extension;
                }
            } else {
                const uint64_t gap = part.source_offset - previous_end;
                gap_count++;
                if (gap == 0) gap_eq0++;
                else if (gap <= 4096) gap_1_4k++;
                else if (gap <= 65536) gap_4k_64k++;
                else if (gap <= 1048576) gap_64k_1m++;
                else gap_gt1m++;
                for (uint32_t i = 0; i < 4u; i++) {
                    if (gap <= thresholds[i]) {
                        projections[i].bytes += gap + part.bytes;
                    } else {
                        projections[i].reads++;
                        projections[i].bytes += part.bytes;
                    }
                }
            }
            if (part_end > previous_end) previous_end = part_end;
            part_count++;
        }

        if (part_count != load_count ||
            (part_count != 0 && gap_count + overlap_count != part_count - 1u)) {
            return 0;
        }
        fprintf(stderr,
                "ds4: [arena-wrap-layout-profile] result=ok phase=%s parts=%llu payload=%llu gaps=%llu overlaps=%llu gap_eq0=%llu gap_1_4k=%llu gap_4k_64k=%llu gap_64k_1m=%llu gap_gt1m=%llu t0_reads=%llu t0_bytes=%llu t4096_reads=%llu t4096_bytes=%llu t65536_reads=%llu t65536_bytes=%llu t1048576_reads=%llu t1048576_bytes=%llu page_size=%llu source_aligned=%llu bytes_aligned=%llu destination_aligned=%llu\n",
                cuda_dynamic_arena_wrap_part_name(phase),
                (unsigned long long)part_count,
                (unsigned long long)payload_bytes,
                (unsigned long long)gap_count,
                (unsigned long long)overlap_count,
                (unsigned long long)gap_eq0,
                (unsigned long long)gap_1_4k,
                (unsigned long long)gap_4k_64k,
                (unsigned long long)gap_64k_1m,
                (unsigned long long)gap_gt1m,
                (unsigned long long)projections[0].reads,
                (unsigned long long)projections[0].bytes,
                (unsigned long long)projections[1].reads,
                (unsigned long long)projections[1].bytes,
                (unsigned long long)projections[2].reads,
                (unsigned long long)projections[2].bytes,
                (unsigned long long)projections[3].reads,
                (unsigned long long)projections[3].bytes,
                (unsigned long long)page_size,
                (unsigned long long)source_aligned,
                (unsigned long long)bytes_aligned,
                (unsigned long long)destination_aligned);
    }
    return 1;
}

static void *cuda_dynamic_arena_part_copy_worker(void *arg) {
    cuda_dynamic_arena_part_copy_context *context =
        (cuda_dynamic_arena_part_copy_context *)arg;
    const uint8_t *model = (const uint8_t *)g_dynamic_arena.model_map;
    if (!context->profile_parts) {
        for (;;) {
            const uint32_t cursor =
                context->next.fetch_add(1, std::memory_order_relaxed);
            if (cursor >= context->cursor_end) break;
            if (cursor < context->cursor_begin ||
                cursor >= context->part_count) {
                continue;
            }
            const cuda_dynamic_arena_wrap_part &part = context->parts[cursor];
            if (context->phase_part && part.part != context->phase_part) {
                continue;
            }
            if (part.load_index >= context->load_count ||
                (part.part != CUDA_DYNAMIC_ARENA_MIRROR_GATE &&
                 part.part != CUDA_DYNAMIC_ARENA_MIRROR_UP &&
                 part.part != CUDA_DYNAMIC_ARENA_MIRROR_DOWN)) {
                continue;
            }
            const ds4_gpu_dynamic_arena_load &load =
                context->loads[part.load_index];
            if (!load.host_ptr ||
                part.source_offset > g_dynamic_arena.model_size ||
                part.bytes > g_dynamic_arena.model_size - part.source_offset ||
                part.destination_offset > load.host_bytes ||
                part.bytes > load.host_bytes - part.destination_offset) {
                continue;
            }
            uint8_t *destination =
                (uint8_t *)load.host_ptr + part.destination_offset;
            const int copied = context->source_file ?
                cuda_pread_full(context->source_file, destination,
                                part.bytes, part.source_offset) :
                (memcpy(destination, model + part.source_offset,
                        (size_t)part.bytes) != NULL);
            if (!copied) continue;
            if (context->checksum_parts) {
                context->checksums[part.load_index] =
                    cuda_dynamic_arena_fnv1a64_continue(
                        destination, part.bytes,
                        context->checksums[part.load_index]);
            }
            context->success[cursor] = 1u;
        }
        return NULL;
    }

    cuda_dynamic_arena_part_worker_profile profile = {};
    const uint32_t worker_index = context->profile_worker_next.fetch_add(
        1, std::memory_order_relaxed);
    const double worker_started_at = cuda_wall_sec();
    for (;;) {
        const uint32_t cursor =
            context->next.fetch_add(1, std::memory_order_relaxed);
        if (cursor >= context->cursor_end) break;
        if (cursor < context->cursor_begin ||
            cursor >= context->part_count) {
            continue;
        }
        const cuda_dynamic_arena_wrap_part &part = context->parts[cursor];
        if (context->phase_part && part.part != context->phase_part) {
            continue;
        }
        if (part.load_index >= context->load_count ||
            (part.part != CUDA_DYNAMIC_ARENA_MIRROR_GATE &&
             part.part != CUDA_DYNAMIC_ARENA_MIRROR_UP &&
             part.part != CUDA_DYNAMIC_ARENA_MIRROR_DOWN)) {
            continue;
        }
        const ds4_gpu_dynamic_arena_load &load =
            context->loads[part.load_index];
        if (!load.host_ptr ||
            part.source_offset > g_dynamic_arena.model_size ||
            part.bytes > g_dynamic_arena.model_size - part.source_offset ||
            part.destination_offset > load.host_bytes ||
            part.bytes > load.host_bytes - part.destination_offset) {
            continue;
        }
        uint8_t *destination =
            (uint8_t *)load.host_ptr + part.destination_offset;
        const double copy_started_at = cuda_wall_sec();
        const int copied = context->source_file ?
            cuda_pread_full(context->source_file, destination,
                            part.bytes, part.source_offset) :
            (memcpy(destination, model + part.source_offset,
                    (size_t)part.bytes) != NULL);
        const double copy_seconds = cuda_wall_sec() - copy_started_at;
        profile.parts++;
        profile.bytes += part.bytes;
        profile.memcpy_seconds += copy_seconds;
        if (copy_seconds > profile.max_part_seconds) {
            profile.max_part_seconds = copy_seconds;
            profile.max_part_bytes = part.bytes;
            profile.max_part_source_offset = part.source_offset;
            profile.max_part_load_index = part.load_index;
            profile.max_part_cursor = cursor;
            profile.max_part_kind = part.part;
        }
        if (copy_seconds >= context->slow_part_threshold_seconds) {
            profile.slow_parts++;
        }
        if (!copied) continue;
        if (context->checksum_parts) {
            context->checksums[part.load_index] =
                cuda_dynamic_arena_fnv1a64_continue(
                    destination, part.bytes,
                    context->checksums[part.load_index]);
        }
        context->success[cursor] = 1u;
    }
    profile.active_seconds = cuda_wall_sec() - worker_started_at;
    if (worker_index < context->profile_worker_capacity &&
        context->profile_workers) {
        context->profile_workers[worker_index] = profile;
    }
    return NULL;
}

#ifdef _WIN32
struct cuda_dynamic_arena_file_qd_slot {
    OVERLAPPED overlapped;
    HANDLE event;
    uint32_t cursor;
    DWORD expected;
    int pending;
};

static void cuda_dynamic_arena_file_qd_drain(
        const os_file_t *source_file,
        cuda_dynamic_arena_file_qd_slot *slots,
        uint32_t count) {
    if (!source_file || !slots) return;
    for (uint32_t i = 0; i < count; i++) {
        if (slots[i].pending) {
            (void)CancelIoEx(source_file->h, &slots[i].overlapped);
        }
    }
    for (uint32_t i = 0; i < count; i++) {
        if (!slots[i].pending) continue;
        DWORD ignored = 0;
        (void)GetOverlappedResult(source_file->h, &slots[i].overlapped,
                                  &ignored, TRUE);
        slots[i].pending = 0;
    }
}

/* Submit several source-sorted reads into their final pinned arena slots.
 * Each checksum phase is drained before the next begins, preserving the
 * canonical gate || up || down FNV order without staging or extra copies. */
static int cuda_dynamic_arena_copy_phase_file_qd(
        cuda_dynamic_arena_part_copy_context *context,
        uint32_t qd,
        cuda_dynamic_arena_file_qd_profile *profile) {
    if (!context || !context->source_file ||
        !os_file_valid(context->source_file) || qd < 2u || qd > 64u ||
        !profile) {
        return 0;
    }

    std::vector<cuda_dynamic_arena_file_qd_slot> slots;
    try {
        slots.resize(qd);
    } catch (...) {
        profile->failures++;
        return 0;
    }
    for (uint32_t i = 0; i < qd; i++) {
        memset(&slots[i].overlapped, 0, sizeof(slots[i].overlapped));
        slots[i].event = CreateEventW(NULL, TRUE, FALSE, NULL);
        slots[i].cursor = 0;
        slots[i].expected = 0;
        slots[i].pending = 0;
        if (!slots[i].event) {
            profile->failures++;
            for (uint32_t j = 0; j < i; j++) CloseHandle(slots[j].event);
            return 0;
        }
    }

    int ok = 1;
    uint32_t cursor = context->cursor_begin;
    while (cursor < context->cursor_end && ok) {
        uint32_t submitted = 0;
        while (cursor < context->cursor_end && submitted < qd) {
            const uint32_t part_cursor = cursor++;
            if (part_cursor >= context->part_count) {
                profile->failures++;
                ok = 0;
                break;
            }
            const cuda_dynamic_arena_wrap_part &part =
                context->parts[part_cursor];
            if (context->phase_part && part.part != context->phase_part) {
                continue;
            }
            if (part.load_index >= context->load_count ||
                (part.part != CUDA_DYNAMIC_ARENA_MIRROR_GATE &&
                 part.part != CUDA_DYNAMIC_ARENA_MIRROR_UP &&
                 part.part != CUDA_DYNAMIC_ARENA_MIRROR_DOWN) ||
                part.bytes == 0 || part.bytes > 0xffffffffull) {
                profile->failures++;
                ok = 0;
                break;
            }
            const ds4_gpu_dynamic_arena_load &load =
                context->loads[part.load_index];
            if (!load.host_ptr ||
                part.source_offset > g_dynamic_arena.model_size ||
                part.bytes > g_dynamic_arena.model_size - part.source_offset ||
                part.destination_offset > load.host_bytes ||
                part.bytes > load.host_bytes - part.destination_offset) {
                profile->failures++;
                ok = 0;
                break;
            }

            cuda_dynamic_arena_file_qd_slot &slot = slots[submitted];
            OVERLAPPED &overlapped = slot.overlapped;
            memset(&overlapped, 0, sizeof(overlapped));
            overlapped.Offset = (DWORD)(part.source_offset & 0xffffffffu);
            overlapped.OffsetHigh = (DWORD)(part.source_offset >> 32);
            overlapped.hEvent = slot.event;
            (void)ResetEvent(slot.event);
            slot.cursor = part_cursor;
            slot.expected = (DWORD)part.bytes;
            slot.pending = 0;
            uint8_t *destination =
                (uint8_t *)load.host_ptr + part.destination_offset;
            const BOOL started = ReadFile(context->source_file->h,
                                          destination, slot.expected,
                                          NULL, &overlapped);
            if (!started && GetLastError() != ERROR_IO_PENDING) {
                fprintf(stderr,
                        "ds4: [arena-wrap-file-qd] submit failed offset=%llu error=%lu\n",
                        (unsigned long long)part.source_offset,
                        (unsigned long)GetLastError());
                profile->failures++;
                ok = 0;
                break;
            }
            slot.pending = 1;
            submitted++;
            profile->submits++;
            if (submitted > profile->observed) profile->observed = submitted;
        }

        for (uint32_t i = 0; i < submitted; i++) {
            cuda_dynamic_arena_file_qd_slot &slot = slots[i];
            if (!slot.pending) continue;
            DWORD got = 0;
            const BOOL completed = GetOverlappedResult(
                context->source_file->h, &slot.overlapped, &got, TRUE);
            slot.pending = 0;
            if (!completed || got != slot.expected) {
                const DWORD error = completed ? ERROR_READ_FAULT : GetLastError();
                fprintf(stderr,
                        "ds4: [arena-wrap-file-qd] completion failed cursor=%u error=%lu bytes=%lu/%lu\n",
                        slot.cursor, (unsigned long)error,
                        (unsigned long)got, (unsigned long)slot.expected);
                profile->failures++;
                ok = 0;
                continue;
            }
            const cuda_dynamic_arena_wrap_part &part =
                context->parts[slot.cursor];
            const ds4_gpu_dynamic_arena_load &load =
                context->loads[part.load_index];
            uint8_t *destination =
                (uint8_t *)load.host_ptr + part.destination_offset;
            if (context->checksum_parts) {
                context->checksums[part.load_index] =
                    cuda_dynamic_arena_fnv1a64_continue(
                        destination, part.bytes,
                        context->checksums[part.load_index]);
            }
            context->success[slot.cursor] = 1u;
            profile->completions++;
        }
        if (!ok) {
            cuda_dynamic_arena_file_qd_drain(
                context->source_file, slots.data(), submitted);
        }
    }

    for (uint32_t i = 0; i < qd; i++) CloseHandle(slots[i].event);
    return ok;
}
#else
static int cuda_dynamic_arena_copy_phase_file_qd(
        cuda_dynamic_arena_part_copy_context *, uint32_t,
        cuda_dynamic_arena_file_qd_profile *) {
    return 0;
}
#endif

static void *cuda_dynamic_arena_checksum_worker(void *arg) {
    cuda_dynamic_arena_checksum_context *context =
        (cuda_dynamic_arena_checksum_context *)arg;
    for (;;) {
        const uint32_t cursor =
            context->next.fetch_add(1, std::memory_order_relaxed);
        if (cursor >= context->load_count) break;
        const ds4_gpu_dynamic_arena_load &load = context->loads[cursor];
        if (!load.host_ptr || load.host_bytes != g_dynamic_arena.slot_bytes) {
            continue;
        }
        context->checksums[cursor] = cuda_dynamic_arena_fnv1a64(
            (const uint8_t *)load.host_ptr, load.host_bytes);
        context->success[cursor] = 1u;
    }
    return NULL;
}

static cuda_dynamic_arena_wrap_schedule
cuda_dynamic_arena_wrap_schedule_env(void) {
    const char *value = getenv("DS4_CUDA_ARENA_WRAP_SCHEDULE");
    if (!value || !value[0] || strcmp(value, "0") == 0 ||
        strcmp(value, "expert-major") == 0) {
        return CUDA_DYNAMIC_ARENA_WRAP_EXPERT_MAJOR;
    }
    if (strcmp(value, "source-parts") == 0 ||
        strcmp(value, "g44-source-parts") == 0) {
        return CUDA_DYNAMIC_ARENA_WRAP_SOURCE_PARTS;
    }
    static int warned = 0;
    if (!warned) {
        fprintf(stderr,
                "ds4: [arena-wrap-profile] invalid schedule '%s'; using expert-major\n",
                value);
        warned = 1;
    }
    return CUDA_DYNAMIC_ARENA_WRAP_EXPERT_MAJOR;
}

static int cuda_dynamic_arena_wrap_sequential_file(void) {
    const char *value = getenv("DS4_CUDA_ARENA_WRAP_SEQUENTIAL_FILE");
    return value && value[0] && strcmp(value, "0") != 0;
}

static int cuda_dynamic_arena_wrap_random_file(void) {
    const char *value = getenv("DS4_CUDA_ARENA_WRAP_RANDOM_FILE");
    return value && value[0] && strcmp(value, "0") != 0;
}

static double cuda_dynamic_arena_min_available_gib(void) {
    const char *value = getenv("DS4_CUDA_DYNAMIC_ARENA_MIN_AVAILABLE_GIB");
    if (!value || !value[0]) return 0.0;
    char *end = NULL;
    errno = 0;
    const double parsed = strtod(value, &end);
    if (errno == 0 && end && *end == '\0' &&
        isfinite(parsed) && parsed >= 0.0 && parsed <= 64.0) {
        return parsed;
    }
    static int warned = 0;
    if (!warned) {
        fprintf(stderr,
                "ds4: [arena-cap] invalid min_available_gib '%s'; dynamic arena disabled\n",
                value);
        warned = 1;
    }
    return -1.0;
}

static uint32_t cuda_dynamic_arena_wrap_sequential_workers(
        uint32_t work_count) {
    const char *value = getenv("DS4_CUDA_ARENA_WRAP_SEQUENTIAL_WORKERS");
    uint32_t workers = 1;
    if (value && value[0]) {
        char *end = NULL;
        errno = 0;
        unsigned long parsed = strtoul(value, &end, 10);
        if (errno == 0 && end && *end == '\0' && parsed >= 1 && parsed <= 32) {
            workers = (uint32_t)parsed;
        } else {
            static int warned = 0;
            if (!warned) {
                fprintf(stderr,
                        "ds4: invalid sequential WRAP worker count '%s'; using 1\n",
                        value);
                warned = 1;
            }
        }
    }
    if (work_count != 0 && workers > work_count) workers = work_count;
    return workers;
}

static uint32_t cuda_dynamic_arena_wrap_file_qd(void) {
    const char *value = getenv("DS4_CUDA_ARENA_WRAP_FILE_QD");
    if (!value || !value[0]) return 1;
    char *end = NULL;
    errno = 0;
    const unsigned long parsed = strtoul(value, &end, 10);
    if (errno == 0 && end && *end == '\0' &&
        parsed >= 1 && parsed <= 64) {
        return (uint32_t)parsed;
    }
    static int warned = 0;
    if (!warned) {
        fprintf(stderr,
                "ds4: [arena-wrap-file-qd] invalid queue depth '%s'; using 1\n",
                value);
        warned = 1;
    }
    return 1;
}

static int cuda_dynamic_arena_wrap_trust_worker_checksum(void) {
    const char *value =
        getenv("DS4_CUDA_ARENA_WRAP_TRUST_WORKER_CHECKSUM");
    if (!value || !value[0] || strcmp(value, "0") == 0) return 0;
    if (strcmp(value, "1") == 0) return 1;
    static int warned = 0;
    if (!warned) {
        fprintf(stderr,
                "ds4: [arena-wrap-profile] invalid trust-worker-checksum value '%s'; disabled\n",
                value);
