static int cuda_dynamic_arena_trim_process_working_set(uint32_t *last_error) {
#ifdef _WIN32
    SetLastError(ERROR_SUCCESS);
    const BOOL ok = SetProcessWorkingSetSize(
        GetCurrentProcess(), (SIZE_T)-1, (SIZE_T)-1);
    if (last_error) *last_error = ok ? 0u : (uint32_t)GetLastError();
    return ok ? 1 : 0;
#else
    if (last_error) *last_error = (uint32_t)ENOTSUP;
    return 0;
#endif
}

#ifdef _WIN32
typedef BOOL (WINAPI *cuda_dynamic_arena_get_process_memory_info_fn)(
    HANDLE, PPROCESS_MEMORY_COUNTERS, DWORD);

static void cuda_dynamic_arena_source_unlock_snapshot_read(
        cuda_dynamic_arena_source_unlock_snapshot *snapshot) {
    if (!snapshot) return;
    memset(snapshot, 0, sizeof(*snapshot));
    MEMORYSTATUSEX ms;
    memset(&ms, 0, sizeof(ms));
    ms.dwLength = sizeof(ms);
    if (GlobalMemoryStatusEx(&ms)) {
        snapshot->available_bytes = (uint64_t)ms.ullAvailPhys;
    }

    HMODULE kernel32 = GetModuleHandleW(L"kernel32.dll");
    cuda_dynamic_arena_get_process_memory_info_fn get_process_memory_info =
        kernel32 ? (cuda_dynamic_arena_get_process_memory_info_fn)
            GetProcAddress(kernel32, "K32GetProcessMemoryInfo") : NULL;
    if (get_process_memory_info) {
        PROCESS_MEMORY_COUNTERS counters;
        memset(&counters, 0, sizeof(counters));
        counters.cb = sizeof(counters);
        if (get_process_memory_info(
                GetCurrentProcess(), &counters, sizeof(counters))) {
            snapshot->working_set_bytes = (uint64_t)counters.WorkingSetSize;
            snapshot->page_fault_count = (uint64_t)counters.PageFaultCount;
        }
    }

    IO_COUNTERS io_counters;
    memset(&io_counters, 0, sizeof(io_counters));
    if (GetProcessIoCounters(GetCurrentProcess(), &io_counters)) {
        snapshot->read_transfer_bytes =
            (uint64_t)io_counters.ReadTransferCount;
    }
}
#else
static void cuda_dynamic_arena_source_unlock_snapshot_read(
        cuda_dynamic_arena_source_unlock_snapshot *snapshot) {
    if (!snapshot) return;
    memset(snapshot, 0, sizeof(*snapshot));
}
#endif

static int cuda_dynamic_arena_source_unlock_emit_phase(
        const cuda_dynamic_arena_source_unlock_phase_stats *stats) {
    if (!stats) return 0;
    const char *result = stats->failed ? "failed" : "ok";
    if (stats->waves) {
        fprintf(stderr,
                "ds4: [arena-wrap-source-unlock] result=%s phase=%s waves=%u max_wave_bytes=%llu parts=%llu ranges=%llu bytes_requested=%llu calls=%u true=%u error_not_locked=%u failed=%u seconds=%.6f available_before=%llu available_after=%llu working_set_before=%llu working_set_after=%llu page_fault_before=%llu page_fault_after=%llu read_transfer_before=%llu read_transfer_after=%llu last_error=%u\n",
                result,
                stats->phase ? stats->phase : "unknown",
                stats->waves,
                (unsigned long long)stats->max_wave_bytes,
                (unsigned long long)stats->parts,
                (unsigned long long)stats->ranges,
                (unsigned long long)stats->bytes_requested,
                stats->calls,
                stats->true_count,
                stats->error_not_locked,
                stats->failed,
                stats->seconds,
                (unsigned long long)stats->before.available_bytes,
                (unsigned long long)stats->after.available_bytes,
                (unsigned long long)stats->before.working_set_bytes,
                (unsigned long long)stats->after.working_set_bytes,
                (unsigned long long)stats->before.page_fault_count,
                (unsigned long long)stats->after.page_fault_count,
                (unsigned long long)stats->before.read_transfer_bytes,
                (unsigned long long)stats->after.read_transfer_bytes,
                stats->last_error);
    } else {
        fprintf(stderr,
                "ds4: [arena-wrap-source-unlock] result=%s phase=%s parts=%llu ranges=%llu bytes_requested=%llu calls=%u true=%u error_not_locked=%u failed=%u seconds=%.6f available_before=%llu available_after=%llu working_set_before=%llu working_set_after=%llu page_fault_before=%llu page_fault_after=%llu read_transfer_before=%llu read_transfer_after=%llu last_error=%u\n",
                result,
                stats->phase ? stats->phase : "unknown",
                (unsigned long long)stats->parts,
                (unsigned long long)stats->ranges,
                (unsigned long long)stats->bytes_requested,
                stats->calls,
                stats->true_count,
                stats->error_not_locked,
                stats->failed,
                stats->seconds,
                (unsigned long long)stats->before.available_bytes,
                (unsigned long long)stats->after.available_bytes,
                (unsigned long long)stats->before.working_set_bytes,
                (unsigned long long)stats->after.working_set_bytes,
                (unsigned long long)stats->before.page_fault_count,
                (unsigned long long)stats->after.page_fault_count,
                (unsigned long long)stats->before.read_transfer_bytes,
                (unsigned long long)stats->after.read_transfer_bytes,
                stats->last_error);
    }
    return stats->failed == 0;
}

static int cuda_dynamic_arena_source_unlock_aligned_model_range(
        uint64_t source_offset,
        uint64_t bytes,
        uint64_t model_size,
        uint64_t page_size,
        uint64_t *aligned_start,
        uint64_t *aligned_end) {
    if (!aligned_start || !aligned_end || page_size == 0 ||
        (page_size & (page_size - 1u)) != 0 ||
        bytes == 0 ||
        source_offset > model_size ||
        bytes > model_size - source_offset) {
        return 0;
    }
    const uint64_t end = source_offset + bytes;
    uint64_t range_start = source_offset & ~(page_size - 1u);
    uint64_t range_end = end;
    const uint64_t remainder = range_end & (page_size - 1u);
    if (remainder) {
        const uint64_t add = page_size - remainder;
        if (range_end > UINT64_MAX - add) return 0;
        range_end += add;
    }
    if (range_end > model_size) {
        range_end = model_size;
    }
    if (range_end <= range_start) return 0;
    *aligned_start = range_start;
    *aligned_end = range_end;
    return 1;
}

static int cuda_dynamic_arena_source_unlock_aligned_range(
        const cuda_dynamic_arena_wrap_part &part,
        uint64_t page_size,
        uint64_t *aligned_start,
        uint64_t *aligned_end) {
    return cuda_dynamic_arena_source_unlock_aligned_model_range(
        part.source_offset, part.bytes, g_dynamic_arena.model_size,
        page_size, aligned_start, aligned_end);
}

static uint64_t cuda_dynamic_arena_source_unlock_page_size(void) {
#ifdef _WIN32
    SYSTEM_INFO system_info;
    GetSystemInfo(&system_info);
    uint64_t page_size = (uint64_t)system_info.dwPageSize;
    if (page_size == 0 || (page_size & (page_size - 1u)) != 0) {
        page_size = 4096;
    }
    return page_size;
#else
    const long observed_page_size = sysconf(_SC_PAGESIZE);
    uint64_t page_size = observed_page_size > 0 ?
        (uint64_t)observed_page_size : 4096u;
    if (page_size == 0 || (page_size & (page_size - 1u)) != 0) {
        page_size = 4096;
    }
    return page_size;
#endif
}

#ifdef _WIN32
typedef BOOL (WINAPI *cuda_q1_0_query_working_set_ex_fn)(
    HANDLE, PVOID, DWORD);
#endif

static void cuda_q1_0_profile_source_working_set_sample(
        const char *phase,
        const void *mapping,
        uint64_t mapping_bytes) {
    if (!cuda_q1_0_profile_requested()) return;
#ifdef _WIN32
    const uint64_t page_size =
        cuda_dynamic_arena_source_unlock_page_size();
    uint64_t queried_pages = 0;
    uint64_t resident_pages = 0;
    uint64_t shared_pages = 0;
    uint64_t query_calls = 0;
    uint32_t last_error = 0;
    int ok = mapping && mapping_bytes != 0 && page_size != 0 &&
        mapping_bytes <= UINT64_MAX - (page_size - 1u);
    const uint64_t page_count = ok ?
        (mapping_bytes + page_size - 1u) / page_size : 0;
    const uintptr_t mapping_address = (uintptr_t)mapping;
    if (ok && (page_count == 0 ||
               page_count - 1u >
                   (UINTPTR_MAX - mapping_address) / page_size)) {
        ok = 0;
        last_error = ERROR_ARITHMETIC_OVERFLOW;
    }

    HMODULE kernel32 = GetModuleHandleW(L"kernel32.dll");
    cuda_q1_0_query_working_set_ex_fn query_working_set_ex =
        kernel32 ? (cuda_q1_0_query_working_set_ex_fn)
            GetProcAddress(kernel32, "K32QueryWorkingSetEx") : NULL;
    if (ok && !query_working_set_ex) {
        ok = 0;
        last_error = ERROR_PROC_NOT_FOUND;
    }

    std::vector<PSAPI_WORKING_SET_EX_INFORMATION> rows;
    const uint64_t max_chunk_pages = 65536u;
    if (ok) {
        try {
            rows.resize((size_t)std::min(page_count, max_chunk_pages));
        } catch (...) {
            ok = 0;
            last_error = ERROR_NOT_ENOUGH_MEMORY;
        }
    }
    for (uint64_t cursor = 0; ok && cursor < page_count;) {
        const uint64_t remaining = page_count - cursor;
        const uint64_t chunk_pages =
            std::min(remaining, max_chunk_pages);
        const uint64_t query_bytes64 =
            chunk_pages * sizeof(PSAPI_WORKING_SET_EX_INFORMATION);
        if (query_bytes64 > MAXDWORD) {
            ok = 0;
            last_error = ERROR_ARITHMETIC_OVERFLOW;
            break;
        }
        for (uint64_t i = 0; i < chunk_pages; i++) {
            rows[(size_t)i] = PSAPI_WORKING_SET_EX_INFORMATION{};
            rows[(size_t)i].VirtualAddress = (PVOID)(
                mapping_address + (cursor + i) * page_size);
        }
        SetLastError(ERROR_SUCCESS);
        if (!query_working_set_ex(
                GetCurrentProcess(), rows.data(), (DWORD)query_bytes64)) {
            ok = 0;
            last_error = (uint32_t)GetLastError();
            break;
        }
        query_calls++;
        queried_pages += chunk_pages;
        for (uint64_t i = 0; i < chunk_pages; i++) {
            if (!rows[(size_t)i].VirtualAttributes.Valid) continue;
            resident_pages++;
            if (rows[(size_t)i].VirtualAttributes.Shared) shared_pages++;
        }
        cursor += chunk_pages;
    }
    const uint64_t not_shared_pages = resident_pages - shared_pages;
    fprintf(stderr,
            "ds4: [q1-0-source-working-set] result=%s phase=%s windows=1 "
            "page_size=%llu mapping_bytes=%llu queried_pages=%llu "
            "resident_pages=%llu resident_bytes=%llu shared_pages=%llu "
            "shared_bytes=%llu not_shared_pages=%llu "
            "not_shared_bytes=%llu "
            "file_backed_pages=%llu file_backed_bytes=%llu "
            "query_calls=%llu last_error=%u "
            "file_backed_basis=sidecar-file-mapping\n",
            ok ? "ok" : "failed", phase ? phase : "unknown",
            (unsigned long long)page_size,
            (unsigned long long)mapping_bytes,
            (unsigned long long)queried_pages,
            (unsigned long long)resident_pages,
            (unsigned long long)(resident_pages * page_size),
            (unsigned long long)shared_pages,
            (unsigned long long)(shared_pages * page_size),
            (unsigned long long)not_shared_pages,
            (unsigned long long)(not_shared_pages * page_size),
            (unsigned long long)resident_pages,
            (unsigned long long)(resident_pages * page_size),
            (unsigned long long)query_calls,
            last_error);
#else
    fprintf(stderr,
            "ds4: [q1-0-source-working-set] result=unsupported phase=%s "
            "windows=0 page_size=0 mapping_bytes=%llu queried_pages=0 "
            "resident_pages=0 resident_bytes=0 shared_pages=0 "
            "shared_bytes=0 not_shared_pages=0 not_shared_bytes=0 "
            "file_backed_pages=0 file_backed_bytes=0 query_calls=0 "
            "last_error=%u file_backed_basis=unavailable\n",
            phase ? phase : "unknown",
            (unsigned long long)mapping_bytes,
            (unsigned int)ENOTSUP);
#endif
}

static void cuda_q1_0_source_unlock_snapshot_store(
        cuda_q1_0_source_unlock_stats *stats,
        int after) {
#ifdef _WIN32
    if (!stats) return;
    cuda_dynamic_arena_source_unlock_snapshot snapshot;
    cuda_dynamic_arena_source_unlock_snapshot_read(&snapshot);
    if (after) {
        stats->available_after_bytes = snapshot.available_bytes;
        stats->working_set_after_bytes = snapshot.working_set_bytes;
        stats->page_fault_after = snapshot.page_fault_count;
        stats->read_transfer_after_bytes = snapshot.read_transfer_bytes;
    } else {
        stats->available_before_bytes = snapshot.available_bytes;
        stats->working_set_before_bytes = snapshot.working_set_bytes;
        stats->page_fault_before = snapshot.page_fault_count;
        stats->read_transfer_before_bytes = snapshot.read_transfer_bytes;
    }
#else
    (void)stats;
    (void)after;
#endif
}

static void cuda_q1_0_source_unlock_begin(
        cuda_q1_0_source_unlock_stats *stats) {
    if (!stats) return;
    memset(stats, 0, sizeof(*stats));
#ifdef _WIN32
    stats->windows = 1u;
    stats->page_aligned = 1u;
    stats->destination_unchanged = 1u;
    stats->page_size = cuda_dynamic_arena_source_unlock_page_size();
    stats->started_at = cuda_wall_sec();
    cuda_q1_0_source_unlock_snapshot_store(stats, 0);
#endif
}

static void cuda_q1_0_source_unlock_bootstrap_range(
        const cuda_dynamic_arena &arena,
        uint64_t source_offset,
        uint64_t expert_bytes,
        cuda_q1_0_source_unlock_stats *stats) {
#ifdef _WIN32
    if (!stats || !stats->windows) return;
    stats->ranges_attempted++;
    if (!arena.model_map || arena.n_expert == 0 || expert_bytes == 0 ||
        expert_bytes > UINT64_MAX / arena.n_expert) {
        stats->failed++;
        stats->last_error = ERROR_INVALID_PARAMETER;
        return;
    }
    const uint64_t bytes = expert_bytes * arena.n_expert;
    uint64_t aligned_start = 0;
    uint64_t aligned_end = 0;
    if (!cuda_dynamic_arena_source_unlock_aligned_model_range(
            source_offset, bytes, arena.model_size, stats->page_size,
            &aligned_start, &aligned_end)) {
        stats->failed++;
        stats->last_error = ERROR_INVALID_PARAMETER;
        return;
    }
    const uint64_t len = aligned_end - aligned_start;
    if (len == 0 || len > (uint64_t)SIZE_MAX ||
        stats->bytes_attempted > UINT64_MAX - len) {
        stats->failed++;
        stats->last_error = ERROR_INVALID_PARAMETER;
        return;
    }
    stats->bytes_attempted += len;
    stats->calls++;
    const uint8_t *base = (const uint8_t *)arena.model_map;
    SetLastError(ERROR_SUCCESS);
    const BOOL ok = VirtualUnlock((LPVOID)(base + aligned_start), (SIZE_T)len);
    if (ok) {
        stats->success++;
    } else {
        const DWORD error = GetLastError();
        if (error == ERROR_NOT_LOCKED) {
            stats->not_locked++;
        } else {
            stats->failed++;
            stats->last_error = (uint32_t)error;
        }
    }
#else
    (void)arena;
    (void)source_offset;
    (void)expert_bytes;
    (void)stats;
#endif
}

static void cuda_q1_0_source_unlock_bootstrap_layer(
        const cuda_dynamic_arena &arena,
        const ds4_gpu_dynamic_arena_layer &geometry,
        uint32_t layer,
        cuda_q1_0_source_unlock_stats *stats) {
#ifdef _WIN32
    (void)layer;
    if (!stats || !stats->windows) return;
    cuda_q1_0_source_unlock_bootstrap_range(
        arena, geometry.gate_offset, geometry.gate_expert_bytes, stats);
    cuda_q1_0_source_unlock_bootstrap_range(
        arena, geometry.up_offset, geometry.up_expert_bytes, stats);
    cuda_q1_0_source_unlock_bootstrap_range(
        arena, geometry.down_offset, geometry.down_expert_bytes, stats);
    stats->layers_completed++;
#else
    (void)arena;
    (void)geometry;
    (void)layer;
    (void)stats;
#endif
}

static void cuda_q1_0_source_unlock_finish(
        cuda_q1_0_source_unlock_stats *stats,
        uint64_t expected_entries,
        uint64_t total_bytes) {
#ifdef _WIN32
    if (!stats || !stats->windows) return;
    cuda_q1_0_source_unlock_snapshot_store(stats, 1);
    stats->seconds = cuda_wall_sec() - stats->started_at;
    fprintf(stderr,
            "ds4: [q1-0-source-unlock] result=complete phase=bootstrap "
            "source=sidecar-mmap windows=%u page_size=%llu page_aligned=%u "
            "destination_unchanged=%u layers=%llu ranges_attempted=%llu "
            "bytes_attempted=%llu calls=%u success=%u true=%u "
            "not_locked=%u error_not_locked=%u failed=%u seconds=%.6f "
            "available_before=%llu available_after=%llu "
            "working_set_before=%llu working_set_after=%llu "
            "page_fault_before=%llu page_fault_after=%llu "
            "read_transfer_before=%llu read_transfer_after=%llu "
            "last_error=%u expected_entries=%llu total_bytes=%llu\n",
            stats->windows,
            (unsigned long long)stats->page_size,
            stats->page_aligned,
            stats->destination_unchanged,
            (unsigned long long)stats->layers_completed,
            (unsigned long long)stats->ranges_attempted,
            (unsigned long long)stats->bytes_attempted,
            stats->calls,
            stats->success,
            stats->success,
            stats->not_locked,
            stats->not_locked,
            stats->failed,
            stats->seconds,
            (unsigned long long)stats->available_before_bytes,
            (unsigned long long)stats->available_after_bytes,
            (unsigned long long)stats->working_set_before_bytes,
            (unsigned long long)stats->working_set_after_bytes,
            (unsigned long long)stats->page_fault_before,
            (unsigned long long)stats->page_fault_after,
            (unsigned long long)stats->read_transfer_before_bytes,
            (unsigned long long)stats->read_transfer_after_bytes,
            stats->last_error,
            (unsigned long long)expected_entries,
            (unsigned long long)total_bytes);
#else
    (void)stats;
    (void)expected_entries;
    (void)total_bytes;
#endif
}

static int cuda_dynamic_arena_source_unlock_phase_range(
        const std::vector<cuda_dynamic_arena_wrap_part> &parts,
        std::vector<uint8_t> &part_success,
        uint8_t phase_part,
        uint32_t cursor_begin,
        uint32_t cursor_end,
        cuda_dynamic_arena_source_unlock_phase_stats *stats,
        int emit) {
    if (!stats) return 0;
    cuda_dynamic_arena_source_unlock_phase_stats local = {};
    local.phase = cuda_dynamic_arena_wrap_part_name(phase_part);
#ifndef _WIN32
    local.failed = 1;
    local.last_error = (uint32_t)ENOTSUP;
    (void)parts;
    (void)part_success;
    (void)cursor_begin;
    (void)cursor_end;
    *stats = local;
    return emit ? cuda_dynamic_arena_source_unlock_emit_phase(stats) : 0;
#else
    if (!g_dynamic_arena.model_map ||
        parts.size() != part_success.size() ||
        cursor_begin > cursor_end ||
        cursor_end > parts.size() ||
        (phase_part != CUDA_DYNAMIC_ARENA_MIRROR_GATE &&
         phase_part != CUDA_DYNAMIC_ARENA_MIRROR_UP &&
         phase_part != CUDA_DYNAMIC_ARENA_MIRROR_DOWN)) {
        local.failed = 1;
        local.last_error = ERROR_INVALID_PARAMETER;
        *stats = local;
        return emit ? cuda_dynamic_arena_source_unlock_emit_phase(stats) : 0;
    }

    SYSTEM_INFO system_info;
    GetSystemInfo(&system_info);
    uint64_t page_size = (uint64_t)system_info.dwPageSize;
    if (page_size == 0 || (page_size & (page_size - 1u)) != 0) {
        page_size = 4096;
    }
    struct range_t {
        uint64_t start;
        uint64_t end;
    };
    std::vector<range_t> ranges;
    try {
        ranges.reserve(cursor_end - cursor_begin);
        for (size_t i = cursor_begin; i < cursor_end; i++) {
            const cuda_dynamic_arena_wrap_part &part = parts[i];
            if (part.part != phase_part || part_success[i] != 1u) continue;
            uint64_t aligned_start = 0;
            uint64_t aligned_end = 0;
            if (!cuda_dynamic_arena_source_unlock_aligned_range(
                    part, page_size, &aligned_start, &aligned_end)) {
                continue;
            }
            ranges.push_back({aligned_start, aligned_end});
            local.parts++;
        }
        if (!local.failed) {
            std::sort(ranges.begin(), ranges.end(),
                [](const range_t &a, const range_t &b) {
                    if (a.start != b.start) return a.start < b.start;
                    return a.end < b.end;
                });
            size_t out = 0;
            for (size_t i = 0; i < ranges.size(); i++) {
                if (out == 0 || ranges[i].start > ranges[out - 1].end) {
                    ranges[out++] = ranges[i];
                } else if (ranges[i].end > ranges[out - 1].end) {
                    ranges[out - 1].end = ranges[i].end;
                }
            }
            ranges.resize(out);
        }
    } catch (...) {
        local.failed = 1;
        local.last_error = ERROR_OUTOFMEMORY;
    }

    const double started_at = cuda_wall_sec();
    cuda_dynamic_arena_source_unlock_snapshot_read(&local.before);
    const uint8_t *base = (const uint8_t *)g_dynamic_arena.model_map;
    if (!local.failed) {
        local.ranges = (uint64_t)ranges.size();
        for (size_t i = 0; i < ranges.size(); i++) {
            const uint64_t len = ranges[i].end - ranges[i].start;
            if (len == 0 || len > (uint64_t)SIZE_MAX) {
                local.failed++;
                local.last_error = ERROR_INVALID_PARAMETER;
                continue;
            }
            local.bytes_requested += len;
            local.calls++;
            SetLastError(ERROR_SUCCESS);
            const BOOL ok = VirtualUnlock(
                (LPVOID)(base + ranges[i].start), (SIZE_T)len);
            if (ok) {
                local.true_count++;
            } else {
                const DWORD error = GetLastError();
                if (error == ERROR_NOT_LOCKED) {
                    local.error_not_locked++;
                } else {
                    local.failed++;
                    local.last_error = (uint32_t)error;
                }
            }
        }
    }
    if (!local.failed) {
        for (size_t i = cursor_begin; i < cursor_end; i++) {
            if (parts[i].part == phase_part && part_success[i] == 1u) {
                part_success[i] = 2u;
            }
        }
    }
    cuda_dynamic_arena_source_unlock_snapshot_read(&local.after);
    local.seconds = cuda_wall_sec() - started_at;
    local.max_wave_bytes = local.bytes_requested;
    *stats = local;
    return emit ? cuda_dynamic_arena_source_unlock_emit_phase(stats) :
        (stats->failed == 0);
#endif
}

static int cuda_dynamic_arena_source_unlock_phase(
        const std::vector<cuda_dynamic_arena_wrap_part> &parts,
        std::vector<uint8_t> &part_success,
        uint8_t phase_part,
        cuda_dynamic_arena_source_unlock_phase_stats *stats) {
    return cuda_dynamic_arena_source_unlock_phase_range(
        parts, part_success, phase_part, 0u, (uint32_t)parts.size(),
        stats, 1);
}

static double cuda_dynamic_arena_wrap_unlock_wave_gib(void) {
    const char *value = getenv("DS4_CUDA_ARENA_WRAP_UNLOCK_WAVE_GIB");
    if (!value || !value[0]) return 0.0;
    char *end = NULL;
    errno = 0;
    const double gib = strtod(value, &end);
    if (errno == 0 && end && *end == '\0' &&
        isfinite(gib) && gib >= 0.0 && gib <= 64.0) {
        return gib;
    }
    static int warned = 0;
    if (!warned) {
        fprintf(stderr,
                "ds4: [arena-wrap-source-unlock] invalid wave GiB '%s'; disabled\n",
                value);
        warned = 1;
    }
    return 0.0;
}

static double cuda_dynamic_arena_wrap_slow_part_seconds(void) {
    const char *value = getenv("DS4_CUDA_ARENA_WRAP_SLOW_PART_MS");
    if (!value || !value[0]) return 0.025;
    char *end = NULL;
    errno = 0;
    const double milliseconds = strtod(value, &end);
    if (errno == 0 && end && *end == '\0' &&
        isfinite(milliseconds) && milliseconds > 0.0 &&
        milliseconds <= 600000.0) {
        return milliseconds / 1000.0;
    }
    static int warned = 0;
    if (!warned) {
        fprintf(stderr,
                "ds4: [arena-wrap-part-profile] invalid slow-part-ms '%s'; using 25ms\n",
                value);
        warned = 1;
    }
    return 0.025;
}

static const char *cuda_dynamic_arena_wrap_part_name(uint8_t part) {
    if (part == CUDA_DYNAMIC_ARENA_MIRROR_GATE) return "gate";
    if (part == CUDA_DYNAMIC_ARENA_MIRROR_UP) return "up";
    if (part == CUDA_DYNAMIC_ARENA_MIRROR_DOWN) return "down";
    return "unknown";
}

static int cuda_primary_dynamic_arena_layer_allowed(uint32_t layer) {
    return !cuda_nested_residual_layer_required(layer);
}

static int cuda_dynamic_arena_wrap_publish_target(
        const uint8_t *target,
        uint32_t entry_count,
        cuda_dynamic_arena_wrap_result *result) {
    cuda_dynamic_arena_wrap_result local = {};
    local.reason = "begin";
    const double started_at = cuda_wall_sec();
    const int trust_worker_checksum =
        cuda_dynamic_arena_wrap_trust_worker_checksum();
    const int part_profile = cuda_dynamic_arena_wrap_part_profile();
    const int layout_profile =
        cuda_dynamic_arena_wrap_layout_profile_enabled();
    const int trim_between_phases_requested =
        cuda_dynamic_arena_wrap_trim_between_phases();
    const int unlock_source_ranges_requested =
        cuda_dynamic_arena_wrap_unlock_source_ranges();
    const double unlock_wave_gib =
        cuda_dynamic_arena_wrap_unlock_wave_gib();
    const int unlock_wave_requested = unlock_wave_gib > 0.0;
    const double slow_part_threshold_seconds =
        part_profile ? cuda_dynamic_arena_wrap_slow_part_seconds() : 0.025;
    const cuda_dynamic_arena_wrap_schedule schedule =
        cuda_dynamic_arena_wrap_schedule_env();
    const int sequential_file_requested =
        cuda_dynamic_arena_wrap_sequential_file();
    const int random_file_requested = cuda_dynamic_arena_wrap_random_file();
    const uint32_t file_qd_requested =
        cuda_dynamic_arena_wrap_file_qd();
    const char *schedule_name =
        schedule == CUDA_DYNAMIC_ARENA_WRAP_SOURCE_PARTS ?
        "source-parts" : "expert-major";
    const char *source_name = sequential_file_requested ? "sequential-file" :
        (random_file_requested ? "random-file" : "mmap");
    const char *checksum_name = trust_worker_checksum ?
            "fnv1a64-worker-only" :
            "fnv1a64-worker-plus-finish";
    if (g_nested_residual.active && target &&
        g_dynamic_arena.n_expert != 0) {
        for (uint32_t entry = 0; entry < entry_count; entry++) {
            if (!target[entry]) continue;
            const uint32_t layer = entry / g_dynamic_arena.n_expert;
            if (cuda_primary_dynamic_arena_layer_allowed(layer)) continue;
            local.reason = "nested-residual-duplicate-primary";
            local.seconds = cuda_wall_sec() - started_at;
            fprintf(stderr,
                    "ds4: [nested-residual] primary-arena-filter result=failed "
                    "reason=duplicate layer=%u expert=%u\n",
                    layer, entry % g_dynamic_arena.n_expert);
            if (result) *result = local;
            return 0;
        }
    }
    if ((cuda_q1_0_exclusive_arena_active() ||
         g_dynamic_arena.backing == CUDA_DYNAMIC_ARENA_BACKING_Q1_0) &&
        (sequential_file_requested || random_file_requested)) {
        local.reason = "q1-sidecar-file-source-unavailable";
        local.seconds = cuda_wall_sec() - started_at;
        fprintf(stderr,
                "ds4: [q1-0-resident-arena] result=failed reason=%s route_pread=disabled\n",
                local.reason);
        if (result) *result = local;
        return 0;
    }
    if (sequential_file_requested && random_file_requested) {
        local.reason = "multiple-file-sources";
        local.seconds = cuda_wall_sec() - started_at;
        if (result) *result = local;
        return 0;
    }
    if (unlock_source_ranges_requested &&
        (schedule != CUDA_DYNAMIC_ARENA_WRAP_SOURCE_PARTS ||
         !trust_worker_checksum ||
         trim_between_phases_requested ||
         sequential_file_requested ||
         random_file_requested)) {
        local.reason = "source-unlock-contract";
        local.seconds = cuda_wall_sec() - started_at;
        fprintf(stderr,
                "ds4: [arena-wrap-source-unlock] result=failed phase=contract parts=0 ranges=0 bytes_requested=0 calls=0 true=0 error_not_locked=0 failed=1 seconds=0.000000 available_before=0 available_after=0 working_set_before=0 working_set_after=0 page_fault_before=0 page_fault_after=0 read_transfer_before=0 read_transfer_after=0 last_error=%u\n",
                87u);
        fprintf(stderr,
                "ds4: [arena-wrap-source-unlock-summary] result=failed phases=0 parts=0 ranges=0 bytes_requested=0 calls=0 true=0 error_not_locked=0 failed=1 seconds=0.000000\n");
        if (result) *result = local;
        return 0;
    }
    if (unlock_wave_requested && !unlock_source_ranges_requested) {
        local.reason = "source-unlock-wave-contract";
        local.seconds = cuda_wall_sec() - started_at;
        fprintf(stderr,
                "ds4: [arena-wrap-source-unlock] result=failed phase=contract waves=0 parts=0 ranges=0 bytes_requested=0 calls=0 true=0 error_not_locked=0 failed=1 seconds=0.000000 available_before=0 available_after=0 working_set_before=0 working_set_after=0 page_fault_before=0 page_fault_after=0 read_transfer_before=0 read_transfer_after=0 last_error=%u\n",
                87u);
        fprintf(stderr,
                "ds4: [arena-wrap-source-unlock-summary] result=failed phases=0 waves=0 wave_gib=%.6f max_wave_bytes=0 parts=0 ranges=0 bytes_requested=0 calls=0 true=0 error_not_locked=0 failed=1 seconds=0.000000\n",
                unlock_wave_gib);
        if (result) *result = local;
        return 0;
    }
    if (layout_profile &&
        schedule != CUDA_DYNAMIC_ARENA_WRAP_SOURCE_PARTS) {
        local.reason = "layout-profile-requires-source-parts";
        local.seconds = cuda_wall_sec() - started_at;
        if (result) *result = local;
        return 0;
    }
    if ((sequential_file_requested || random_file_requested) &&
        (schedule != CUDA_DYNAMIC_ARENA_WRAP_SOURCE_PARTS ||
         (sequential_file_requested && !g_model_file_sequential_valid) ||
         (random_file_requested && !g_model_file_valid))) {
        local.reason = schedule != CUDA_DYNAMIC_ARENA_WRAP_SOURCE_PARTS ?
            "file-source-requires-source-parts" : "file-source-unavailable";
        local.seconds = cuda_wall_sec() - started_at;
        fprintf(stderr,
                "ds4: [arena-wrap-profile] result=failed schedule=%s source=%s checksum=%s loads=0 workers=0 begin=0.000 copy_checksum=0.000 finish=0.000 publish=0.000 total=%.3f source_parts_copy=0.000 source_parts_checksum=0.000 parts=0 copy_workers=0 checksum_workers=0 reason=%s\n",
                schedule_name, source_name, checksum_name, local.seconds,
                local.reason);
        if (result) *result = local;
        return 0;
    }
    ds4_gpu_dynamic_arena_txn *txn = NULL;
    const ds4_gpu_dynamic_arena_load *loads = NULL;
    uint32_t load_count = 0;
    if (!ds4_gpu_dynamic_arena_begin(
            target, entry_count, &txn, &loads, &load_count) || !txn) {
        if (txn) ds4_gpu_dynamic_arena_abort(txn);
        local.seconds = cuda_wall_sec() - started_at;
        if (result) *result = local;
        return 0;
    }
    const double begin_done_at = cuda_wall_sec();
    double copy_done_at = begin_done_at;
    double finish_done_at = begin_done_at;
    double source_parts_copy_seconds = 0;
    double source_parts_checksum_seconds = 0;
    uint32_t checksum_workers = 0;
    uint32_t requested_copy_workers = 0;
    int source_parts_copy_failed = 0;
    double source_parts_main_worker_seconds = 0;
    double source_parts_join_seconds = 0;
    double source_parts_worker_active_min_seconds = -1;
    double source_parts_worker_active_max_seconds = 0;
    double source_parts_memcpy_seconds = 0;
    double source_parts_max_part_seconds = 0;
    uint64_t source_parts_profile_parts = 0;
    uint64_t source_parts_profile_bytes = 0;
    uint64_t source_parts_worker_parts_min = UINT64_MAX;
    uint64_t source_parts_worker_parts_max = 0;
    uint64_t source_parts_max_part_bytes = 0;
    uint64_t source_parts_max_part_source_offset = 0;
    uint32_t source_parts_max_part_load_index = 0;
    uint32_t source_parts_max_part_cursor = 0;
    uint32_t source_parts_slow_parts = 0;
    uint32_t source_parts_profile_workers = 0;
    uint8_t source_parts_max_part_kind = 0;
    uint32_t source_parts_trim_calls = 0;
    uint32_t source_parts_trim_succeeded = 0;
    uint32_t source_parts_trim_failed = 0;
    uint32_t source_parts_trim_last_error = 0;
    double source_parts_trim_seconds = 0;
    cuda_dynamic_arena_source_unlock_summary source_unlock_summary = {};
    cuda_dynamic_arena_file_qd_profile file_qd_profile = {};
    file_qd_profile.requested = file_qd_requested;
    file_qd_profile.observed = file_qd_requested == 1u ? 1u : 0u;

    local.loads = load_count;
    int all_succeeded = loads != NULL || load_count == 0;
    std::vector<uint32_t> order;
    std::vector<cuda_dynamic_arena_wrap_part> parts;
    std::vector<uint64_t> checksums;
    std::vector<uint8_t> success;
    std::vector<uint8_t> part_success;
    std::vector<cuda_dynamic_arena_part_worker_profile> part_worker_profiles;
    std::vector<os_thread_t> threads;
    std::vector<os_thread_t> started_threads;
    if (load_count != 0) {
        try {
            checksums.assign(load_count, 0);
            success.assign(load_count, 0);
            uint32_t work_count = load_count;
            if (schedule == CUDA_DYNAMIC_ARENA_WRAP_SOURCE_PARTS) {
                if (!cuda_dynamic_arena_wrap_build_source_parts(
                        loads, load_count, parts)) {
                    local.reason = "part-order";
                    all_succeeded = 0;
                } else {
                    part_success.assign(parts.size(), 0);
                    if (layout_profile &&
                        !cuda_dynamic_arena_wrap_emit_layout_profile(
                            loads, load_count, parts)) {
                        local.reason = "layout-profile";
                        all_succeeded = 0;
                    }
                    if (trust_worker_checksum) {
                        std::fill(checksums.begin(), checksums.end(),
                                  UINT64_C(14695981039346656037));
                    }
                    work_count = (uint32_t)parts.size();
                }
            } else {
                order.resize(load_count);
                for (uint32_t i = 0; i < load_count; i++) order[i] = i;
                std::sort(order.begin(), order.end(),
                    [&](uint32_t lhs, uint32_t rhs) {
                        const ds4_gpu_dynamic_arena_load &a = loads[lhs];
                        const ds4_gpu_dynamic_arena_load &b = loads[rhs];
                        const ds4_gpu_dynamic_arena_layer &la =
                            g_dynamic_arena.layers[a.layer];
                        const ds4_gpu_dynamic_arena_layer &lb =
                            g_dynamic_arena.layers[b.layer];
                        const uint64_t ao = la.gate_offset +
                            (uint64_t)a.expert * la.gate_expert_bytes;
                        const uint64_t bo = lb.gate_offset +
                            (uint64_t)b.expert * lb.gate_expert_bytes;
                        return ao < bo;
                    });
            }
            const uint32_t requested_workers = sequential_file_requested ?
                cuda_dynamic_arena_wrap_sequential_workers(work_count) :
                (random_file_requested ? 1u :
                 cuda_dynamic_arena_observer_workers(work_count));
            requested_copy_workers = requested_workers;
            if (file_qd_requested > 1u &&
                (schedule != CUDA_DYNAMIC_ARENA_WRAP_SOURCE_PARTS ||
                 !sequential_file_requested || random_file_requested ||
                 !trust_worker_checksum || requested_workers != 1u ||
                 part_profile)) {
                local.reason = "file-qd-contract";
                source_parts_copy_failed = 1;
                all_succeeded = 0;
            }
            threads.resize(requested_workers > 1 ? requested_workers - 1 : 0);
            started_threads.reserve(threads.size());
            if (part_profile &&
                schedule == CUDA_DYNAMIC_ARENA_WRAP_SOURCE_PARTS) {
                part_worker_profiles.resize(threads.size() + 1u);
            }
        } catch (...) {
            local.reason = "allocation";
            all_succeeded = 0;
        }
    }

    if (all_succeeded && load_count != 0) {
        if (schedule == CUDA_DYNAMIC_ARENA_WRAP_SOURCE_PARTS) {
            cuda_dynamic_arena_part_copy_context context;
            context.loads = loads;
            context.load_count = load_count;
            context.parts = parts.data();
            context.part_count = (uint32_t)parts.size();
            context.cursor_begin = 0;
            context.cursor_end = context.part_count;
            context.checksums = checksums.data();
            context.success = part_success.data();
            context.source_file = sequential_file_requested ?
                &g_model_file_sequential :
                (random_file_requested ? &g_model_file : NULL);
            context.checksum_parts = trust_worker_checksum;
            context.profile_parts = part_profile;
            context.slow_part_threshold_seconds = slow_part_threshold_seconds;
            context.profile_workers = NULL;
            context.profile_worker_capacity = 0;
            context.profile_worker_next.store(0, std::memory_order_relaxed);
            const uint8_t phases[3] = {
                CUDA_DYNAMIC_ARENA_MIRROR_GATE,
                CUDA_DYNAMIC_ARENA_MIRROR_UP,
                CUDA_DYNAMIC_ARENA_MIRROR_DOWN,
            };
            const uint32_t phase_count = trust_worker_checksum ? 3u : 1u;
            const uint64_t unlock_wave_target_bytes = unlock_wave_requested ?
                (uint64_t)(unlock_wave_gib * 1073741824.0) : 0u;
            const uint64_t unlock_wave_page_size =
                cuda_dynamic_arena_source_unlock_page_size();
            for (uint32_t phase = 0; phase < phase_count; phase++) {
                context.phase_part = trust_worker_checksum ?
                    phases[phase] : 0;
                cuda_dynamic_arena_source_unlock_phase_stats phase_unlock = {};
                phase_unlock.phase =
                    cuda_dynamic_arena_wrap_part_name(context.phase_part);
                uint32_t wave_cursor = 0;
                int phase_has_work = 1;
                while (phase_has_work && all_succeeded) {
                    uint32_t cursor_begin = 0;
                    uint32_t cursor_end = context.part_count;
                    if (unlock_wave_requested) {
                        phase_has_work = 0;
                        uint64_t wave_union_bytes = 0;
                        uint64_t wave_union_end = 0;
                        for (uint32_t cursor = wave_cursor;
                             cursor < context.part_count; cursor++) {
                            const cuda_dynamic_arena_wrap_part &part =
                                parts[cursor];
                            if (part.part != context.phase_part ||
                                part_success[cursor] != 0u) {
                                continue;
                            }
                            uint64_t aligned_start = 0;
                            uint64_t aligned_end = 0;
                            if (!cuda_dynamic_arena_source_unlock_aligned_range(
                                    part, unlock_wave_page_size,
                                    &aligned_start, &aligned_end)) {
                                local.reason = "source-unlock-wave-range";
                                source_parts_copy_failed = 1;
                                all_succeeded = 0;
                                break;
                            }
                            uint64_t increment = aligned_end - aligned_start;
                            if (phase_has_work) {
                                if (aligned_start > wave_union_end) {
                                    increment = aligned_end - aligned_start;
                                } else if (aligned_end > wave_union_end) {
                                    increment = aligned_end - wave_union_end;
                                } else {
                                    increment = 0;
                                }
                            }
                            if (!phase_has_work) {
                                if (increment > unlock_wave_target_bytes) {
                                    local.reason =
                                        "source-unlock-wave-part-exceeds-target";
                                    source_parts_copy_failed = 1;
                                    all_succeeded = 0;
                                    break;
                                }
                                cursor_begin = cursor;
                                cursor_end = cursor + 1u;
                                wave_union_bytes = increment;
                                wave_union_end = aligned_end;
                                phase_has_work = 1;
                            } else if (increment > 0u &&
                                       (wave_union_bytes >
                                            UINT64_MAX - increment ||
                                        wave_union_bytes + increment >
                                            unlock_wave_target_bytes)) {
                                break;
                            } else {
                                cursor_end = cursor + 1u;
                                wave_union_bytes += increment;
                                if (aligned_end > wave_union_end) {
                                    wave_union_end = aligned_end;
                                }
                            }
                        }
                        if (!all_succeeded || !phase_has_work) break;
                        wave_cursor = cursor_end;
                    } else {
                        phase_has_work = 0;
                    }
                    context.cursor_begin = cursor_begin;
                    context.cursor_end = cursor_end;
                    context.next.store(cursor_begin,
                                       std::memory_order_relaxed);
                    if (part_profile) {
                        std::fill(part_worker_profiles.begin(),
                                  part_worker_profiles.end(),
                                  cuda_dynamic_arena_part_worker_profile{});
                        context.profile_workers = part_worker_profiles.data();
                        context.profile_worker_capacity =
                            (uint32_t)part_worker_profiles.size();
                        context.profile_worker_next.store(0,
                            std::memory_order_relaxed);
                    }
                    started_threads.clear();
                    if (file_qd_requested == 1u) {
                        for (uint32_t i = 0; i < threads.size(); i++) {
                            if (os_thread_create(
                                    &threads[i],
                                    cuda_dynamic_arena_part_copy_worker,
                                    &context) == 0) {
                                started_threads.push_back(threads[i]);
                            }
                        }
                    }
                    const uint32_t phase_workers =
                        file_qd_requested > 1u ? 1u :
                        1u + (uint32_t)started_threads.size();
                    if (phase_workers > local.workers) {
                        local.workers = phase_workers;
                    }
                    if ((sequential_file_requested || random_file_requested) &&
                        phase_workers != requested_copy_workers) {
                        local.reason = "copy-workers";
                        source_parts_copy_failed = 1;
                        all_succeeded = 0;
                    }
                    const double main_worker_started_at = cuda_wall_sec();
                    if (file_qd_requested > 1u) {
                        if (!cuda_dynamic_arena_copy_phase_file_qd(
                                &context, file_qd_requested,
                                &file_qd_profile)) {
                            local.reason = "file-qd-copy";
                            source_parts_copy_failed = 1;
                            all_succeeded = 0;
                        }
                    } else {
                        (void)cuda_dynamic_arena_part_copy_worker(&context);
                    }
                    source_parts_main_worker_seconds +=
                        cuda_wall_sec() - main_worker_started_at;
                    const double join_started_at = cuda_wall_sec();
                    for (uint32_t i = 0; i < started_threads.size(); i++) {
                        os_thread_join(started_threads[i]);
                    }
                    source_parts_join_seconds +=
                        cuda_wall_sec() - join_started_at;
                    if (part_profile) {
                        const uint32_t profiled_workers =
                            context.profile_worker_next.load(
                                std::memory_order_relaxed);
                        if (profiled_workers > source_parts_profile_workers) {
                            source_parts_profile_workers = profiled_workers;
                        }
                        const uint32_t worker_limit = std::min(
                            profiled_workers, context.profile_worker_capacity);
                        for (uint32_t i = 0; i < worker_limit; i++) {
                            const cuda_dynamic_arena_part_worker_profile
                                &profile = part_worker_profiles[i];
                            source_parts_profile_parts += profile.parts;
                            source_parts_profile_bytes += profile.bytes;
                            source_parts_memcpy_seconds +=
                                profile.memcpy_seconds;
                            source_parts_slow_parts += profile.slow_parts;
                            source_parts_worker_parts_min = std::min(
                                source_parts_worker_parts_min, profile.parts);
                            source_parts_worker_parts_max = std::max(
                                source_parts_worker_parts_max, profile.parts);
                            if (source_parts_worker_active_min_seconds < 0 ||
                                profile.active_seconds <
                                    source_parts_worker_active_min_seconds) {
                                source_parts_worker_active_min_seconds =
                                    profile.active_seconds;
                            }
                            source_parts_worker_active_max_seconds = std::max(
                                source_parts_worker_active_max_seconds,
                                profile.active_seconds);
                            if (profile.max_part_seconds >
                                    source_parts_max_part_seconds) {
                                source_parts_max_part_seconds =
                                    profile.max_part_seconds;
                                source_parts_max_part_bytes =
                                    profile.max_part_bytes;
                                source_parts_max_part_source_offset =
                                    profile.max_part_source_offset;
                                source_parts_max_part_load_index =
                                    profile.max_part_load_index;
                                source_parts_max_part_cursor =
                                    profile.max_part_cursor;
                                source_parts_max_part_kind =
                                    profile.max_part_kind;
                            }
                        }
                    }
                    if (unlock_source_ranges_requested &&
                        (unlock_wave_requested ||
                         context.phase_part == CUDA_DYNAMIC_ARENA_MIRROR_GATE ||
                         context.phase_part == CUDA_DYNAMIC_ARENA_MIRROR_UP)) {
                        cuda_dynamic_arena_source_unlock_phase_stats
                            unlock_stats;
                        const int unlock_ok = unlock_wave_requested ?
                            cuda_dynamic_arena_source_unlock_phase_range(
                                parts, part_success, context.phase_part,
                                cursor_begin, cursor_end, &unlock_stats, 0) :
                            cuda_dynamic_arena_source_unlock_phase(
                                parts, part_success, context.phase_part,
                                &unlock_stats);
                        if (unlock_wave_requested) {
                            if (phase_unlock.waves == 0u) {
                                phase_unlock.before = unlock_stats.before;
                            }
                            phase_unlock.after = unlock_stats.after;
                            phase_unlock.waves++;
                            phase_unlock.calls += unlock_stats.calls;
                            phase_unlock.true_count +=
                                unlock_stats.true_count;
                            phase_unlock.error_not_locked +=
                                unlock_stats.error_not_locked;
                            phase_unlock.failed += unlock_stats.failed;
                            phase_unlock.parts += unlock_stats.parts;
                            phase_unlock.ranges += unlock_stats.ranges;
                            phase_unlock.bytes_requested +=
                                unlock_stats.bytes_requested;
                            if (unlock_stats.bytes_requested >
                                    phase_unlock.max_wave_bytes) {
                                phase_unlock.max_wave_bytes =
                                    unlock_stats.bytes_requested;
                            }
                            phase_unlock.seconds += unlock_stats.seconds;
                            if (unlock_stats.last_error) {
                                phase_unlock.last_error =
                                    unlock_stats.last_error;
                            }
                        } else {
                            source_unlock_summary.phases++;
                            source_unlock_summary.calls += unlock_stats.calls;
                            source_unlock_summary.true_count +=
                                unlock_stats.true_count;
                            source_unlock_summary.error_not_locked +=
                                unlock_stats.error_not_locked;
                            source_unlock_summary.failed +=
                                unlock_stats.failed;
                            source_unlock_summary.parts += unlock_stats.parts;
                            source_unlock_summary.ranges += unlock_stats.ranges;
                            source_unlock_summary.bytes_requested +=
                                unlock_stats.bytes_requested;
                            source_unlock_summary.seconds +=
                                unlock_stats.seconds;
                        }
                        if (!unlock_ok) {
                            local.reason = "source-unlock";
                            source_parts_copy_failed = 1;
                            all_succeeded = 0;
                        }
                    }
                }
                if (unlock_wave_requested) {
                    const int unlock_ok =
                        cuda_dynamic_arena_source_unlock_emit_phase(
                            &phase_unlock);
                    source_unlock_summary.phases++;
                    source_unlock_summary.waves += phase_unlock.waves;
                    source_unlock_summary.calls += phase_unlock.calls;
                    source_unlock_summary.true_count +=
                        phase_unlock.true_count;
                    source_unlock_summary.error_not_locked +=
                        phase_unlock.error_not_locked;
                    source_unlock_summary.failed += phase_unlock.failed;
                    source_unlock_summary.parts += phase_unlock.parts;
                    source_unlock_summary.ranges += phase_unlock.ranges;
                    source_unlock_summary.bytes_requested +=
                        phase_unlock.bytes_requested;
                    if (phase_unlock.max_wave_bytes >
                            source_unlock_summary.max_wave_bytes) {
                        source_unlock_summary.max_wave_bytes =
                            phase_unlock.max_wave_bytes;
                    }
                    source_unlock_summary.seconds += phase_unlock.seconds;
                    if (!unlock_ok || phase_unlock.waves == 0u) {
                        if (!local.reason || strcmp(local.reason, "begin") == 0) {
                            local.reason = "source-unlock";
                        }
                        source_parts_copy_failed = 1;
                        all_succeeded = 0;
                    }
                }
                if (trim_between_phases_requested &&
                    phase + 1u < phase_count) {
                    const double trim_started_at = cuda_wall_sec();
                    uint32_t trim_error = 0;
                    const int trim_ok =
                        cuda_dynamic_arena_trim_process_working_set(&trim_error);
                    source_parts_trim_seconds +=
                        cuda_wall_sec() - trim_started_at;
                    source_parts_trim_calls++;
                    if (trim_ok) {
                        source_parts_trim_succeeded++;
                    } else {
                        source_parts_trim_failed++;
                        source_parts_trim_last_error = trim_error;
                    }
                }
            }
            if (unlock_source_ranges_requested) {
                const uint32_t expected_unlock_phases =
                    unlock_wave_requested ? 3u : 2u;
                const int unlock_complete =
                    source_unlock_summary.phases == expected_unlock_phases &&
                    source_unlock_summary.failed == 0u;
                if (unlock_wave_requested) {
                    fprintf(stderr,
                            "ds4: [arena-wrap-source-unlock-summary] result=%s phases=%u waves=%u wave_gib=%.6f max_wave_bytes=%llu parts=%llu ranges=%llu bytes_requested=%llu calls=%u true=%u error_not_locked=%u failed=%u seconds=%.6f\n",
                            unlock_complete ? "complete" : "failed",
                            source_unlock_summary.phases,
                            source_unlock_summary.waves,
                            unlock_wave_gib,
                            (unsigned long long)
                                source_unlock_summary.max_wave_bytes,
                            (unsigned long long)source_unlock_summary.parts,
                            (unsigned long long)source_unlock_summary.ranges,
                            (unsigned long long)
                                source_unlock_summary.bytes_requested,
                            source_unlock_summary.calls,
                            source_unlock_summary.true_count,
                            source_unlock_summary.error_not_locked,
                            source_unlock_summary.failed,
                            source_unlock_summary.seconds);
                } else {
                    fprintf(stderr,
                            "ds4: [arena-wrap-source-unlock-summary] result=%s phases=%u parts=%llu ranges=%llu bytes_requested=%llu calls=%u true=%u error_not_locked=%u failed=%u seconds=%.6f\n",
                            unlock_complete ? "complete" : "failed",
                            source_unlock_summary.phases,
                            (unsigned long long)source_unlock_summary.parts,
                            (unsigned long long)source_unlock_summary.ranges,
                            (unsigned long long)
                                source_unlock_summary.bytes_requested,
                            source_unlock_summary.calls,
                            source_unlock_summary.true_count,
                            source_unlock_summary.error_not_locked,
                            source_unlock_summary.failed,
                            source_unlock_summary.seconds);
                }
                if (!unlock_complete) {
                    local.reason = "source-unlock";
                    source_parts_copy_failed = 1;
                    all_succeeded = 0;
                }
            }
            const double source_copy_done_at = cuda_wall_sec();
            source_parts_copy_seconds =
                source_copy_done_at - begin_done_at;
            if (part_profile) {
                if (source_parts_worker_parts_min == UINT64_MAX) {
                    source_parts_worker_parts_min = 0;
                }
                fprintf(stderr,
                        "ds4: [arena-wrap-part-profile] result=copy-complete phases=%u workers=%u parts=%llu bytes=%llu memcpy_sum=%.3f main_worker=%.3f join=%.3f phase_worker_active_min=%.3f phase_worker_active_max=%.3f phase_worker_parts_min=%llu phase_worker_parts_max=%llu slow_threshold_ms=%.3f slow_parts=%u max_part_ms=%.3f max_part_bytes=%llu max_part_load=%u max_part_cursor=%u max_part_kind=%s max_part_source=%llu\n",
                        phase_count, source_parts_profile_workers,
                        (unsigned long long)source_parts_profile_parts,
                        (unsigned long long)source_parts_profile_bytes,
                        source_parts_memcpy_seconds,
                        source_parts_main_worker_seconds,
                        source_parts_join_seconds,
                        source_parts_worker_active_min_seconds,
                        source_parts_worker_active_max_seconds,
                        (unsigned long long)source_parts_worker_parts_min,
                        (unsigned long long)source_parts_worker_parts_max,
                        slow_part_threshold_seconds * 1000.0,
                        source_parts_slow_parts,
                        source_parts_max_part_seconds * 1000.0,
                        (unsigned long long)source_parts_max_part_bytes,
                        source_parts_max_part_load_index,
                        source_parts_max_part_cursor,
                        cuda_dynamic_arena_wrap_part_name(
                            source_parts_max_part_kind),
                        (unsigned long long)
                            source_parts_max_part_source_offset);
            }
            if (trim_between_phases_requested) {
                const int trim_contract_valid =
                    schedule == CUDA_DYNAMIC_ARENA_WRAP_SOURCE_PARTS &&
                    trust_worker_checksum && phase_count == 3u;
                const char *trim_result = !trim_contract_valid ? "skipped" :
                    (source_parts_trim_calls == 2u &&
                     source_parts_trim_succeeded == 2u &&
                     source_parts_trim_failed == 0u ? "complete" : "failed");
                fprintf(stderr,
                        "ds4: [arena-wrap-trim] result=%s calls=%u succeeded=%u failed=%u seconds=%.6f last_error=%u\n",
                        trim_result,
                        source_parts_trim_calls,
                        source_parts_trim_succeeded,
                        source_parts_trim_failed,
                        source_parts_trim_seconds,
                        source_parts_trim_last_error);
            }
            for (size_t i = 0; i < part_success.size(); i++) {
                if (!part_success[i]) {
                    if (!source_parts_copy_failed) {
                        local.reason = "copy-part";
                    }
                    all_succeeded = 0;
                    source_parts_copy_failed = 1;
                }
            }

            if (all_succeeded && trust_worker_checksum) {
                for (uint32_t i = 0; i < load_count; i++) {
                    success[i] = 1u;
                }
                copy_done_at = source_copy_done_at;
            } else if (all_succeeded) {
                started_threads.clear();
                const uint32_t requested_checksum_workers =
                    cuda_dynamic_arena_observer_workers(load_count);
                threads.resize(requested_checksum_workers > 1 ?
                               requested_checksum_workers - 1 : 0);
                cuda_dynamic_arena_checksum_context checksum_context;
                checksum_context.loads = loads;
                checksum_context.load_count = load_count;
                checksum_context.next.store(0, std::memory_order_relaxed);
                checksum_context.checksums = checksums.data();
                checksum_context.success = success.data();
                for (uint32_t i = 0; i < threads.size(); i++) {
                    if (os_thread_create(&threads[i],
                                         cuda_dynamic_arena_checksum_worker,
                                         &checksum_context) == 0) {
                        started_threads.push_back(threads[i]);
                    }
                }
                checksum_workers =
                    1u + (uint32_t)started_threads.size();
                (void)cuda_dynamic_arena_checksum_worker(&checksum_context);
                for (uint32_t i = 0; i < started_threads.size(); i++) {
                    os_thread_join(started_threads[i]);
                }
                copy_done_at = cuda_wall_sec();
                source_parts_checksum_seconds =
                    copy_done_at - source_copy_done_at;
            } else {
                copy_done_at = source_copy_done_at;
            }
        } else {
            cuda_dynamic_arena_wrap_context context;
            context.loads = loads;
            context.order = order.data();
            context.load_count = load_count;
            context.next.store(0, std::memory_order_relaxed);
            context.checksums = checksums.data();
            context.success = success.data();
            for (uint32_t i = 0; i < threads.size(); i++) {
                if (os_thread_create(&threads[i],
                                     cuda_dynamic_arena_wrap_worker,
                                     &context) == 0) {
                    started_threads.push_back(threads[i]);
                }
            }
            local.workers = 1u + (uint32_t)started_threads.size();
            (void)cuda_dynamic_arena_wrap_worker(&context);
            for (uint32_t i = 0; i < started_threads.size(); i++) {
                os_thread_join(started_threads[i]);
            }
            copy_done_at = cuda_wall_sec();
        }
        for (uint32_t i = 0; i < load_count; i++) {
            if (!success[i]) {
                if (!source_parts_copy_failed) local.reason = "copy";
                all_succeeded = 0;
            }
            const int finished = cuda_dynamic_arena_finish_load_impl(
                txn, i, checksums[i], success[i] ? 1 : 0,
                trust_worker_checksum ? 0 : 1);
            if (!finished && success[i]) {
                local.reason = "finish";
                all_succeeded = 0;
            }
        }
        finish_done_at = cuda_wall_sec();
    }

    const double publish_started_at = cuda_wall_sec();
    const int published = all_succeeded &&
        ds4_gpu_dynamic_arena_publish(txn, &local.generation);
    const double publish_done_at = cuda_wall_sec();
    if (published) {
        txn = NULL;
        local.reason = "ok";
        local.published = 1;
        local.seconds = publish_done_at - started_at;
        fprintf(stderr,
                "ds4: [arena-wrap-profile] result=published schedule=%s source=%s checksum=%s loads=%u workers=%u begin=%.3f copy_checksum=%.3f finish=%.3f publish=%.3f total=%.3f source_parts_copy=%.3f source_parts_checksum=%.3f parts=%u copy_workers=%u checksum_workers=%u file_qd=%u file_qd_observed=%u file_submits=%llu file_completions=%llu file_failures=%u\n",
                schedule_name,
                source_name,
                checksum_name,
                local.loads, local.workers,
                begin_done_at - started_at,
                copy_done_at - begin_done_at,
                finish_done_at - copy_done_at,
                publish_done_at - publish_started_at,
                local.seconds,
                source_parts_copy_seconds,
                source_parts_checksum_seconds,
                (uint32_t)parts.size(), local.workers, checksum_workers,
                file_qd_profile.requested, file_qd_profile.observed,
                (unsigned long long)file_qd_profile.submits,
                (unsigned long long)file_qd_profile.completions,
                file_qd_profile.failures);
        if (result) *result = local;
        return 1;
    }
    if (all_succeeded) local.reason = "publish";
    if (txn) {
        ds4_gpu_dynamic_arena_abort(txn);
        local.aborted = 1;
    }
    local.seconds = cuda_wall_sec() - started_at;
    fprintf(stderr,
            "ds4: [arena-wrap-profile] result=failed schedule=%s source=%s checksum=%s loads=%u workers=%u begin=%.3f copy_checksum=%.3f finish=%.3f publish=%.3f total=%.3f source_parts_copy=%.3f source_parts_checksum=%.3f parts=%u copy_workers=%u checksum_workers=%u file_qd=%u file_qd_observed=%u file_submits=%llu file_completions=%llu file_failures=%u reason=%s\n",
            schedule_name,
            source_name,
            checksum_name,
            local.loads, local.workers,
            begin_done_at - started_at,
            copy_done_at - begin_done_at,
            finish_done_at - copy_done_at,
            publish_done_at - publish_started_at,
            local.seconds,
            source_parts_copy_seconds,
            source_parts_checksum_seconds,
            (uint32_t)parts.size(), local.workers, checksum_workers,
            file_qd_profile.requested, file_qd_profile.observed,
            (unsigned long long)file_qd_profile.submits,
            (unsigned long long)file_qd_profile.completions,
            file_qd_profile.failures,
            local.reason ? local.reason : "unknown");
    if (result) *result = local;
    return 0;
}

static void *cuda_dynamic_arena_verify_worker(void *arg) {
    cuda_dynamic_arena_verify_context *context =
        (cuda_dynamic_arena_verify_context *)arg;
    for (;;) {
        const uint32_t cursor =
            context->next.fetch_add(1, std::memory_order_relaxed);
        if (cursor >= context->entry_count) break;
        const uint32_t entry = context->entries[cursor];
        if (entry >= g_dynamic_arena.preloaded.size() ||
            entry >= g_dynamic_arena.preloaded_parts.size()) {
            continue;
        }
        const uint32_t layer = entry / g_dynamic_arena.n_expert;
        const uint32_t expert = entry % g_dynamic_arena.n_expert;
        const cuda_dynamic_arena_binding &binding =
            g_dynamic_arena.preloaded[entry];
        if (g_dynamic_arena.preloaded_parts[entry] !=
                CUDA_DYNAMIC_ARENA_MIRROR_COMPLETE ||
            !cuda_dynamic_arena_binding_valid(
                g_dynamic_arena,
                binding, layer, expert, 0,
                DS4_GPU_ARENA_LOADING)) {
            continue;
        }
        const cuda_dynamic_arena_slot &slot =
            g_dynamic_arena.slots[binding.slot];
        context->checksums[cursor] = cuda_dynamic_arena_fnv1a64(
            (const uint8_t *)slot.host_ptr,
            g_dynamic_arena.slot_bytes);
        context->success[cursor] = 1;
    }
    return NULL;
}

static int cuda_dynamic_arena_observer_finalize_preloads(
        uint32_t *workers_out,
        double *seconds_out) {
    if (workers_out) *workers_out = 0;
    if (seconds_out) *seconds_out = 0.0;
    cuda_dynamic_arena_observer &observer = g_dynamic_arena_observer;
    std::vector<uint32_t> entries;
    try {
        entries.reserve(observer.unique_entries);
        for (uint32_t entry = 0; entry < observer.target.size(); entry++) {
            if (!observer.target[entry]) continue;
            const cuda_dynamic_arena_binding &binding =
                g_dynamic_arena.preloaded[entry];
            const uint32_t layer = entry / g_dynamic_arena.n_expert;
            const uint32_t expert = entry % g_dynamic_arena.n_expert;
            if (cuda_dynamic_arena_binding_valid(
                    g_dynamic_arena,
                    binding, layer, expert, 0,
                    DS4_GPU_ARENA_STAGED)) {
                continue;
            }
            if (g_dynamic_arena.preloaded_parts[entry] ==
                    CUDA_DYNAMIC_ARENA_MIRROR_COMPLETE &&
                cuda_dynamic_arena_binding_valid(
                    g_dynamic_arena,
                    binding, layer, expert, 0,
                    DS4_GPU_ARENA_LOADING)) {
                entries.push_back(entry);
            }
        }
    } catch (...) {
        return 0;
    }
    if (entries.empty()) return 1;

    const double started = cuda_wall_sec();
    const uint32_t workers =
        cuda_dynamic_arena_observer_workers((uint32_t)entries.size());
    std::vector<uint64_t> checksums;
    std::vector<uint8_t> success;
    std::vector<os_thread_t> threads;
    try {
        checksums.assign(entries.size(), 0);
        success.assign(entries.size(), 0);
        threads.resize(workers > 1 ? workers - 1 : 0);
    } catch (...) {
        return 0;
    }

    cuda_dynamic_arena_verify_context context;
    context.entries = entries.data();
    context.entry_count = (uint32_t)entries.size();
    context.next.store(0, std::memory_order_relaxed);
    context.checksums = checksums.data();
    context.success = success.data();
    std::vector<os_thread_t> started_threads;
    try {
        started_threads.reserve(threads.size());
    } catch (...) {
        return 0;
    }
    for (uint32_t i = 0; i + 1 < workers; i++) {
        if (os_thread_create(&threads[i],
                             cuda_dynamic_arena_verify_worker,
                             &context) == 0) {
            started_threads.push_back(threads[i]);
        }
    }
    (void)cuda_dynamic_arena_verify_worker(&context);
    for (uint32_t i = 0; i < started_threads.size(); i++) {
        os_thread_join(started_threads[i]);
    }

    for (uint32_t i = 0; i < entries.size(); i++) {
        if (!success[i]) return 0;
        const uint32_t entry = entries[i];
        const uint32_t layer = entry / g_dynamic_arena.n_expert;
        const uint32_t expert = entry % g_dynamic_arena.n_expert;
        const cuda_dynamic_arena_binding &binding =
            g_dynamic_arena.preloaded[entry];
        if (!cuda_dynamic_arena_binding_valid(
                g_dynamic_arena,
                binding, layer, expert, 0,
                DS4_GPU_ARENA_LOADING)) {
            return 0;
        }
    }
    for (uint32_t i = 0; i < entries.size(); i++) {
        const uint32_t entry = entries[i];
        cuda_dynamic_arena_binding &binding =
            g_dynamic_arena.preloaded[entry];
        cuda_dynamic_arena_slot &slot =
            g_dynamic_arena.slots[binding.slot];
        slot.checksum = checksums[i];
        slot.state = DS4_GPU_ARENA_STAGED;
        binding.state = DS4_GPU_ARENA_STAGED;
    }
    observer.preloaded_entries += (uint32_t)entries.size();
    if (workers_out) {
        *workers_out = (uint32_t)started_threads.size() + 1u;
    }
    if (seconds_out) *seconds_out = cuda_wall_sec() - started;
    return 1;
}

static void cuda_dynamic_arena_observer_discard_preloads(void) {
    if (g_dynamic_arena.txn) return;
    for (uint32_t entry = 0;
         entry < g_dynamic_arena.preloaded.size(); entry++) {
        const cuda_dynamic_arena_binding &binding =
            g_dynamic_arena.preloaded[entry];
        if (binding.slot < g_dynamic_arena.slots.size()) {
            cuda_dynamic_arena_slot &slot =
                g_dynamic_arena.slots[binding.slot];
            if (slot.layer == entry / g_dynamic_arena.n_expert &&
                slot.expert == entry % g_dynamic_arena.n_expert &&
                slot.content_generation == binding.slot_generation &&
                (slot.state == DS4_GPU_ARENA_LOADING ||
                 slot.state == DS4_GPU_ARENA_STAGED)) {
                slot.state = DS4_GPU_ARENA_FREE;
                slot.layer = UINT32_MAX;
                slot.expert = UINT32_MAX;
                slot.checksum = 0;
                slot.last_dma_sequence = 0;
            }
        }
        g_dynamic_arena.preloaded[entry] =
            cuda_dynamic_arena_empty_binding();
        g_dynamic_arena.preloaded_parts[entry] = 0;
    }
}

static uint32_t cuda_dynamic_arena_observer_new_eligible(void) {
    cuda_dynamic_arena_observer &observer = g_dynamic_arena_observer;
    uint32_t count = 0;
    for (uint32_t entry = 0; entry < observer.target.size(); entry++) {
        if (!observer.target[entry] ||
            observer.counts[entry] < observer.min_hits) {
            continue;
        }
        const uint32_t layer = entry / g_dynamic_arena.n_expert;
        const uint32_t expert = entry % g_dynamic_arena.n_expert;
        if (!cuda_dynamic_arena_binding_valid(
                g_dynamic_arena,
                g_dynamic_arena.active[entry], layer, expert,
                g_dynamic_arena.snapshot_generation,
                DS4_GPU_ARENA_READY)) {
            count++;
        }
    }
    return count;
}

static int cuda_dynamic_arena_observer_publish(void) {
    const uint32_t entry_count =
        g_dynamic_arena.n_layer * g_dynamic_arena.n_expert;
    if (!g_dynamic_arena_observer.enabled ||
        g_dynamic_arena_observer.target.size() != entry_count) {
        return 0;
    }

    uint32_t resident = 0;
    for (uint32_t entry = 0; entry < entry_count; entry++) {
        if (!g_dynamic_arena_observer.target[entry]) continue;
        if (g_dynamic_arena_observer.counts[entry] <
            g_dynamic_arena_observer.min_hits) {
            g_dynamic_arena_observer.target[entry] = 0;
            continue;
        }
        resident++;
    }
    g_dynamic_arena_observer.unique_entries = resident;
    if (resident > g_dynamic_arena.slots.size()) {
        fprintf(stderr,
                "ds4: [arena-observe] grow capacity reached tokens=%u resident=%u slots=%u\n",
                g_dynamic_arena_observer.completed_tokens, resident,
                (uint32_t)g_dynamic_arena.slots.size());
        return -1;
    }

    uint32_t verify_workers = 0;
    double verify_seconds = 0.0;
    if (!cuda_dynamic_arena_observer_finalize_preloads(
            &verify_workers, &verify_seconds)) {
        fprintf(stderr,
                "ds4: [arena-observe] preload verification failed tokens=%u resident=%u\n",
                g_dynamic_arena_observer.completed_tokens,
                g_dynamic_arena_observer.unique_entries);
        return 0;
    }

    cuda_dynamic_arena_wrap_result wrap = {};
    if (cuda_dynamic_arena_wrap_publish_target(
            g_dynamic_arena_observer.target.data(), entry_count, &wrap)) {
        fprintf(stderr,
                "ds4: [arena-observe] WRAP published tokens=%u resident=%u loads=%u workers=%u seconds=%.3f generation=%llu preloaded=%u mirror=%.2f GiB verify_workers=%u verify_seconds=%.3f\n",
                g_dynamic_arena_observer.completed_tokens,
                g_dynamic_arena_observer.unique_entries,
                wrap.loads, wrap.workers, wrap.seconds,
                (unsigned long long)wrap.generation,
                g_dynamic_arena_observer.preloaded_entries,
                (double)g_dynamic_arena_observer.mirrored_bytes / 1073741824.0,
                verify_workers, verify_seconds);
        return 1;
    }

    fprintf(stderr,
            "ds4: [arena-observe] WRAP aborted tokens=%u resident=%u loads=%u seconds=%.3f reason=%s\n",
            g_dynamic_arena_observer.completed_tokens,
            g_dynamic_arena_observer.unique_entries,
            wrap.loads, wrap.seconds, wrap.reason ? wrap.reason : "unknown");
    return 0;
}

static char *cuda_dynamic_arena_observer_mirror_ptr(
        const void *model_map,
        uint32_t layer,
        uint32_t expert,
        uint8_t part,
        uint64_t source_offset,
        uint64_t bytes,
        uint32_t *entry_out) {
    if (entry_out) *entry_out = UINT32_MAX;
    cuda_dynamic_arena_observer &observer = g_dynamic_arena_observer;
    if (!observer.enabled || observer.settled ||
        model_map != g_dynamic_arena.model_map ||
        layer < 3 || layer >= g_dynamic_arena.n_layer ||
        !cuda_primary_dynamic_arena_layer_allowed(layer) ||
        expert >= g_dynamic_arena.n_expert ||
        (part != CUDA_DYNAMIC_ARENA_MIRROR_GATE &&
         part != CUDA_DYNAMIC_ARENA_MIRROR_UP &&
         part != CUDA_DYNAMIC_ARENA_MIRROR_DOWN)) {
        return NULL;
    }
    const uint32_t entry = layer * g_dynamic_arena.n_expert + expert;
    if (observer.target.size() <= entry || !observer.target[entry] ||
        observer.counts.size() <= entry ||
        observer.counts[entry] < observer.min_hits ||
        g_dynamic_arena.preloaded.size() <= entry ||
        g_dynamic_arena.preloaded_parts.size() <= entry) {
        return NULL;
    }
    const ds4_gpu_dynamic_arena_layer &geometry =
        g_dynamic_arena.layers[layer];
    uint64_t expected_offset = 0;
    uint64_t expected_bytes = 0;
    if (part == CUDA_DYNAMIC_ARENA_MIRROR_GATE) {
        expected_offset = geometry.gate_offset +
            (uint64_t)expert * geometry.gate_expert_bytes;
        expected_bytes = geometry.gate_expert_bytes;
    } else if (part == CUDA_DYNAMIC_ARENA_MIRROR_UP) {
        expected_offset = geometry.up_offset +
            (uint64_t)expert * geometry.up_expert_bytes;
        expected_bytes = geometry.up_expert_bytes;
    } else {
        expected_offset = geometry.down_offset +
            (uint64_t)expert * geometry.down_expert_bytes;
        expected_bytes = geometry.down_expert_bytes;
    }
    if (source_offset != expected_offset || bytes != expected_bytes) {
        return NULL;
    }
    if (cuda_dynamic_arena_binding_valid(
            g_dynamic_arena,
            g_dynamic_arena.active[entry], layer, expert,
            g_dynamic_arena.snapshot_generation,
            DS4_GPU_ARENA_READY)) {
        return NULL;
    }

    cuda_dynamic_arena_binding &binding =
        g_dynamic_arena.preloaded[entry];
    int valid = cuda_dynamic_arena_binding_valid(
        g_dynamic_arena,
        binding, layer, expert, 0, DS4_GPU_ARENA_LOADING);
    if (!valid) {
        valid = cuda_dynamic_arena_binding_valid(
            g_dynamic_arena,
            binding, layer, expert, 0, DS4_GPU_ARENA_STAGED);
    }
    if (!valid) {
        uint32_t slot_index = UINT32_MAX;
        for (uint32_t i = 0; i < g_dynamic_arena.slots.size(); i++) {
            if (g_dynamic_arena.slots[i].state == DS4_GPU_ARENA_FREE) {
                slot_index = i;
                break;
            }
        }
        if (slot_index == UINT32_MAX) return NULL;
        cuda_dynamic_arena_slot &slot =
            g_dynamic_arena.slots[slot_index];
        slot.layer = layer;
        slot.expert = expert;
        slot.content_generation = cuda_dynamic_arena_next_generation();
        slot.checksum = 0;
        slot.last_dma_sequence = 0;
        slot.state = DS4_GPU_ARENA_LOADING;
        binding = {
            slot_index, DS4_GPU_ARENA_LOADING,
            slot.content_generation, 0
        };
        g_dynamic_arena.preloaded_parts[entry] = 0;
    }
    if ((g_dynamic_arena.preloaded_parts[entry] & part) != 0) return NULL;

    cuda_dynamic_arena_slot &slot =
        g_dynamic_arena.slots[binding.slot];
    uint64_t offset = 0;
    if (part == CUDA_DYNAMIC_ARENA_MIRROR_UP) {
        offset = geometry.gate_expert_bytes;
    } else if (part == CUDA_DYNAMIC_ARENA_MIRROR_DOWN) {
        offset = geometry.gate_expert_bytes + geometry.up_expert_bytes;
    }
    if (entry_out) *entry_out = entry;
    return slot.host_ptr + offset;
}

static void cuda_dynamic_arena_observer_mirror_done(
        uint32_t entry,
        uint8_t part,
        uint64_t bytes) {
    if (entry >= g_dynamic_arena.preloaded.size() ||
        entry >= g_dynamic_arena.preloaded_parts.size()) {
        return;
    }
    const uint32_t layer = entry / g_dynamic_arena.n_expert;
    const uint32_t expert = entry % g_dynamic_arena.n_expert;
    cuda_dynamic_arena_binding &binding =
        g_dynamic_arena.preloaded[entry];
    if (!cuda_dynamic_arena_binding_valid(
            g_dynamic_arena,
            binding, layer, expert, 0,
            DS4_GPU_ARENA_LOADING)) {
        return;
    }
    uint8_t &parts = g_dynamic_arena.preloaded_parts[entry];
    if ((parts & part) != 0) return;
    parts |= part;
    g_dynamic_arena_observer.mirrored_bytes += bytes;
    if (parts != CUDA_DYNAMIC_ARENA_MIRROR_COMPLETE) return;

    /* Keep the completed slot inactive. The observer finalizes checksums in a
     * bounded parallel pass at the publication boundary, off the token path. */
}

static void cuda_dynamic_arena_observer_release(void) {
    cuda_dynamic_arena_observer_discard_preloads();
    g_dynamic_arena_observer.target.clear();
    g_dynamic_arena_observer.counts.clear();
    g_dynamic_arena_observer.window = 0;
    g_dynamic_arena_observer.min_hits = 1;
    g_dynamic_arena_observer.grow_interval = 0;
    g_dynamic_arena_observer.completed_tokens = 0;
    g_dynamic_arena_observer.last_publish_tokens = 0;
    g_dynamic_arena_observer.growth_publications = 0;
    g_dynamic_arena_observer.published_entries = 0;
    g_dynamic_arena_observer.unique_entries = 0;
    g_dynamic_arena_observer.preloaded_entries = 0;
    g_dynamic_arena_observer.last_layer = 0;
    g_dynamic_arena_observer.mirrored_bytes = 0;
    g_dynamic_arena_observer.enabled = 0;
    g_dynamic_arena_observer.have_last_layer = 0;
    g_dynamic_arena_observer.settled = 0;
    g_dynamic_arena_observer.initial_published = 0;
}

static int cuda_prefill_mass_wrap_requested(void) {
    const char *value = getenv("DS4_CUDA_PREFILL_MASS_WRAP");
    if (!value || !value[0] || strcmp(value, "0") == 0) return 0;
    if (strcmp(value, "1") == 0) return 1;
    static int warned = 0;
    if (!warned) {
        fprintf(stderr,
                "ds4: [prefill-mass-wrap] invalid value '%s'; policy disabled\n",
                value);
        warned = 1;
    }
    return 0;
}

static int cuda_prefill_mass_observe_requested(void) {
    const char *value = getenv("DS4_CUDA_PREFILL_MASS_OBSERVE");
    if (!value || !value[0] || strcmp(value, "0") == 0) return 0;
    if (strcmp(value, "1") == 0) return 1;
    static int warned = 0;
    if (!warned) {
        fprintf(stderr,
                "ds4: [prefill-mass] invalid observe value '%s'; observer disabled\n",
                value);
        warned = 1;
    }
    return 0;
}

static int cuda_prefill_mass_layer_stripe_config(
        uint32_t *full_every,
        uint32_t *full_phase) {
    if (!full_every || !full_phase) return -1;
    *full_every = 0;
    *full_phase = 0;
    const char *value =
        getenv("DS4_CUDA_PREFILL_MASS_LAYER_FULL_EVERY");
    if (!value || !value[0] || strcmp(value, "0") == 0) return 0;

    char *end = NULL;
    const unsigned long stride = strtoul(value, &end, 10);
    if (!end || *end != '\0' || stride == 0 || stride > 40u) {
        fprintf(stderr,
                "ds4: [prefill-mass-layer-stripe] result=failed reason=invalid-stride value=%s\n",
                value);
        return -1;
    }

    const char *phase_value =
        getenv("DS4_CUDA_PREFILL_MASS_LAYER_FULL_PHASE");
    unsigned long phase = 0;
    if (phase_value && phase_value[0]) {
        end = NULL;
        phase = strtoul(phase_value, &end, 10);
        if (!end || *end != '\0' || phase >= stride) {
            fprintf(stderr,
                    "ds4: [prefill-mass-layer-stripe] result=failed reason=invalid-phase value=%s stride=%lu\n",
                    phase_value, stride);
            return -1;
        }
    }
    *full_every = (uint32_t)stride;
    *full_phase = (uint32_t)phase;
    return 1;
}

static int cuda_prefill_mass_observer_needs_weights(void) {
    return g_prefill_mass_observer.enabled &&
        !g_prefill_mass_observer.finalized;
}

static int cuda_reap_mass_observe_requested(void) {
    const char *value = getenv("DS4_CUDA_REAP_MASS_OBSERVE");
    if (!value || !value[0] || strcmp(value, "0") == 0) return 0;
    if (strcmp(value, "1") == 0) return 1;
    static int warned = 0;
    if (!warned) {
        fprintf(stderr,
                "ds4: [reap-mass] invalid observe value '%s'; observer disabled\n",
                value);
        warned = 1;
    }
    return 0;
}

static int cuda_reap_mass_wrap_requested(void) {
    const char *value = getenv("DS4_CUDA_REAP_MASS_WRAP");
    if (!value || !value[0] || strcmp(value, "0") == 0) return 0;
    if (strcmp(value, "1") == 0) return 1;
    static int warned = 0;
    if (!warned) {
        fprintf(stderr,
                "ds4: [reap-mass-wrap] invalid value '%s'; policy disabled\n",
                value);
        warned = 1;
    }
    return 0;
}

static uint32_t cuda_reap_mass_window(void) {
    const char *value = getenv("DS4_CUDA_REAP_MASS_WINDOW");
    if (!value || !value[0]) return 16;
    char *end = NULL;
    errno = 0;
    unsigned long parsed = strtoul(value, &end, 10);
    if (errno == 0 && end && *end == '\0' && parsed >= 1 && parsed <= 256) {
        return (uint32_t)parsed;
    }
    fprintf(stderr,
            "ds4: [reap-mass] invalid window value '%s'; observer disabled\n",
            value);
    return 0;
}

static uint32_t cuda_reap_mass_grow_interval(void) {
    const char *value = getenv("DS4_CUDA_REAP_MASS_GROW_INTERVAL");
    if (!value || !value[0]) return 4;
    char *end = NULL;
    errno = 0;
    const unsigned long parsed = strtoul(value, &end, 10);
    if (errno == 0 && end && end != value && *end == '\0' &&
        parsed >= 1 && parsed <= 256) {
        return (uint32_t)parsed;
    }
    fprintf(stderr,
            "ds4: [reap-mass-wrap] invalid grow interval '%s'; policy disabled\n",
            value);
    return 0;
}

static double cuda_reap_mass_hysteresis(void) {
    const char *value = getenv("DS4_CUDA_REAP_MASS_HYSTERESIS");
    if (!value || !value[0]) return 1.25;
    char *end = NULL;
    errno = 0;
    const double parsed = strtod(value, &end);
    if (errno == 0 && end && end != value && *end == '\0' &&
        isfinite(parsed) && parsed >= 1.0 && parsed <= 100.0) {
        return parsed;
    }
    fprintf(stderr,
            "ds4: [reap-mass-wrap] invalid hysteresis '%s'; policy disabled\n",
            value);
    return 0.0;
}

static uint32_t cuda_reap_mass_swap_slots(uint32_t physical_capacity) {
    if (physical_capacity <= 1) return 0;
    return std::min(8u, physical_capacity - 1u);
}

static uint32_t cuda_reap_mass_resident_limit(void) {
    const uint32_t physical_capacity =
        (uint32_t)g_dynamic_arena.slots.size();
    return physical_capacity -
        cuda_reap_mass_swap_slots(physical_capacity);
}

static int cuda_reap_mass_observer_needs_weights(void) {
    return g_reap_mass_observer.enabled;
}

static void cuda_reap_router_trace_release(void) {
    g_reap_router_trace_valid = 0;
    if (g_reap_router_trace_host) {
        (void)cudaFreeHost(g_reap_router_trace_host);
        g_reap_router_trace_host = NULL;
    }
    if (g_reap_router_trace_device) {
        (void)cudaFree(g_reap_router_trace_device);
        g_reap_router_trace_device = NULL;
    }
}

static int cuda_reap_router_trace_ensure(void) {
    if (g_reap_router_trace_device && g_reap_router_trace_host) return 1;
    cuda_reap_router_trace_release();
    if (!cuda_ok(cudaMalloc((void **)&g_reap_router_trace_device,
                            sizeof(*g_reap_router_trace_device)),
                 "reap router trace device alloc")) {
        cuda_reap_router_trace_release();
        return 0;
    }
    if (!cuda_ok(cudaHostAlloc((void **)&g_reap_router_trace_host,
                               sizeof(*g_reap_router_trace_host),
                               cudaHostAllocDefault),
                 "reap router trace host alloc")) {
        cuda_reap_router_trace_release();
        return 0;
    }
    memset(g_reap_router_trace_host, 0, sizeof(*g_reap_router_trace_host));
    g_reap_router_trace_valid = 0;
    return 1;
}

static void cuda_reap_mass_report(const char *reason) {
    cuda_reap_mass_observer &observer = g_reap_mass_observer;
    if (!observer.enabled || !observer.armed || observer.tokens == 0) return;
    double top_mass = 0.0;
    for (double value : observer.totals) {
        if (value > top_mass) top_mass = value;
    }
    observer.top_mass = top_mass;
    fprintf(stderr,
            "ds4: [reap-mass] %s tokens=%llu observed_slots=%llu unique=%u top_mass=%.6f touched=%u\n",
            reason ? reason : "checkpoint",
            (unsigned long long)observer.tokens,
            (unsigned long long)observer.observed_slots,
            observer.unique_entries, observer.top_mass,
            observer.last_touched);
}

static void cuda_reap_mass_clear_pending(void) {
    for (std::vector<std::pair<uint32_t, double>> &row :
         g_reap_mass_observer.pending) {
        row.clear();
    }
}

static void cuda_reap_mass_mark_touched(uint32_t entry) {
    cuda_reap_mass_observer &observer = g_reap_mass_observer;
    if (entry >= observer.touched.size() || observer.touched[entry]) return;
    observer.touched[entry] = 1;
    observer.touched_entries.push_back(entry);
}

static void cuda_reap_mass_commit_pending_token(
        const std::vector<std::pair<uint32_t, double>> &pending) {
    cuda_reap_mass_observer &observer = g_reap_mass_observer;
    if (!observer.enabled || observer.entry_count == 0 || observer.window == 0) {
        return;
    }
    const uint32_t slot = (uint32_t)(observer.tokens % observer.window);
    double *ring_row = observer.ring.data() +
        (uint64_t)slot * observer.entry_count;
    observer.touched_entries.clear();
    for (uint32_t entry = 0; entry < observer.entry_count; entry++) {
        const double old = ring_row[entry];
        if (old == 0.0) continue;
        const double before = observer.totals[entry];
        const double after = before - old;
        observer.totals[entry] = after;
        ring_row[entry] = 0.0;
        if (before > 0.0 && after <= 0.0 && observer.unique_entries > 0) {
            observer.unique_entries--;
        }
        cuda_reap_mass_mark_touched(entry);
    }
    for (const std::pair<uint32_t, double> &item : pending) {
        if (item.first >= observer.entry_count || item.second == 0.0) continue;
        const double before = observer.totals[item.first];
        ring_row[item.first] += item.second;
        observer.totals[item.first] = before + item.second;
        if (before <= 0.0 && observer.totals[item.first] > 0.0) {
            observer.unique_entries++;
        }
        cuda_reap_mass_mark_touched(item.first);
    }
    observer.tokens++;
    observer.last_touched = (uint32_t)observer.touched_entries.size();
    for (uint32_t entry : observer.touched_entries) {
        observer.touched[entry] = 0;
    }
    if ((observer.tokens & (observer.tokens - 1ull)) == 0) {
        cuda_reap_mass_report("checkpoint");
    }
}

static void cuda_reap_mass_commit_all_pending(void) {
    cuda_reap_mass_observer &observer = g_reap_mass_observer;
    if (!observer.enabled) return;
    for (const std::vector<std::pair<uint32_t, double>> &row :
         observer.pending) {
        if (!row.empty()) cuda_reap_mass_commit_pending_token(row);
    }
    cuda_reap_mass_clear_pending();
}

static int cuda_reap_mass_publish_residency(void) {
    cuda_reap_mass_observer &observer = g_reap_mass_observer;
    if (!observer.enabled || !observer.armed ||
        !observer.wrap_requested || observer.tokens == 0 ||
        observer.grow_interval == 0 ||
        observer.tokens - observer.last_publish_tokens <
            observer.grow_interval) {
        return 0;
    }

    observer.last_publish_tokens = observer.tokens;
    observer.wrap_attempts++;
    const uint64_t snapshot_before = g_dynamic_arena.snapshot_generation;
    const uint32_t resident_before = cuda_dynamic_arena_active_count();
    const uint32_t physical_capacity =
        (uint32_t)g_dynamic_arena.slots.size();
    const uint32_t resident_limit = cuda_reap_mass_resident_limit();
    const uint32_t free_before = resident_before < resident_limit ?
        resident_limit - resident_before : 0;
    const char *result_name = "skipped";
    const char *reason = "no-candidate";
    uint32_t entrants_added = 0;
    uint32_t victims_removed = 0;
    cuda_dynamic_arena_wrap_result wrap = {};

    struct ranked_entry {
        double mass;
        uint32_t entry;
    };
    std::vector<ranked_entry> entrants;
    std::vector<ranked_entry> victims;

    do {
        if (!g_dynamic_arena.host_base || resident_limit == 0 ||
            observer.entry_count == 0 ||
            observer.entry_count != g_dynamic_arena.active.size() ||
            observer.totals.size() != observer.entry_count ||
            observer.target.size() != observer.entry_count) {
            reason = "arena-not-ready";
            break;
        }
        if (g_dynamic_arena.txn || g_dynamic_arena.submissions_blocked ||
            g_dynamic_arena.hits_disabled) {
            reason = "transaction-active";
            break;
        }
        if (g_dynamic_arena_observer.enabled) {
            reason = "observer-active";
            break;
        }

        try {
            std::fill(observer.target.begin(), observer.target.end(), 0);
            entrants.reserve(observer.unique_entries);
            victims.reserve(resident_before);
            for (uint32_t entry = 0; entry < observer.entry_count; entry++) {
                const uint32_t layer = entry / g_dynamic_arena.n_expert;
                const uint32_t expert = entry % g_dynamic_arena.n_expert;
                const int resident = cuda_dynamic_arena_binding_valid(
                    g_dynamic_arena,
                    g_dynamic_arena.active[entry], layer, expert,
                    snapshot_before, DS4_GPU_ARENA_READY);
                const double mass = observer.totals[entry] > 0.0 ?
                    observer.totals[entry] : 0.0;
                if (resident) {
                    observer.target[entry] = 1;
                    victims.push_back({mass, entry});
                } else if (mass > 0.0) {
                    entrants.push_back({mass, entry});
                }
            }
        } catch (...) {
            result_name = "failed";
            reason = "allocation";
            break;
        }

        std::sort(entrants.begin(), entrants.end(),
                  [](const ranked_entry &a, const ranked_entry &b) {
                      if (a.mass != b.mass) return a.mass > b.mass;
                      return a.entry < b.entry;
                  });
        std::sort(victims.begin(), victims.end(),
                  [](const ranked_entry &a, const ranked_entry &b) {
                      if (a.mass != b.mass) return a.mass < b.mass;
                      return a.entry > b.entry;
                  });

        if (resident_before > resident_limit) {
            const uint32_t excess = resident_before - resident_limit;
            if (excess > victims.size()) {
                result_name = "failed";
                reason = "resident-invariant";
                break;
            }
            for (uint32_t i = 0; i < excess; i++) {
                observer.target[victims[i].entry] = 0;
                victims_removed++;
            }
        }

        uint32_t entrant_cursor = 0;
        if (victims_removed == 0) {
            const uint32_t free_admissions = std::min(
                free_before, (uint32_t)entrants.size());
            for (; entrant_cursor < free_admissions; entrant_cursor++) {
                observer.target[entrants[entrant_cursor].entry] = 1;
                entrants_added++;
            }

            if (free_admissions == 0) {
                uint32_t victim_cursor = 0;
                const uint32_t swap_capacity =
                    resident_before < physical_capacity ?
                    physical_capacity - resident_before : 0;
                const double epsilon = 1e-12;
                while (entrant_cursor < entrants.size() &&
                       victim_cursor < victims.size() &&
                       victims_removed < swap_capacity) {
                    const ranked_entry &entrant = entrants[entrant_cursor];
                    const ranked_entry &victim = victims[victim_cursor];
                    const double threshold =
                        victim.mass * observer.hysteresis + epsilon;
                    if (entrant.mass <= threshold) break;
                    observer.target[victim.entry] = 0;
                    observer.target[entrant.entry] = 1;
                    entrants_added++;
                    victims_removed++;
                    entrant_cursor++;
                    victim_cursor++;
                }
            }
        }

        if (entrants_added == 0 && victims_removed == 0) {
            reason = entrants.empty() ?
                "no-candidate" : "hysteresis";
            break;
        }

        if (cuda_dynamic_arena_wrap_publish_target(
                observer.target.data(), observer.entry_count, &wrap)) {
            result_name = "published";
            reason = "ok";
        } else {
            result_name = wrap.aborted ? "aborted" : "failed";
            reason = wrap.reason ? wrap.reason : "publish";
        }
    } while (0);

    const uint64_t snapshot_after = g_dynamic_arena.snapshot_generation;
    const uint32_t resident_after = cuda_dynamic_arena_active_count();
    if (strcmp(result_name, "published") == 0) {
        const uint32_t expected_after =
            resident_before + entrants_added - victims_removed;
        if (resident_after != expected_after ||
            snapshot_after == snapshot_before ||
            wrap.loads > entrants_added) {
            result_name = "failed";
            reason = "publish-invariant";
            g_dynamic_arena.fatal_errors++;
            observer.wrap_failures++;
        } else {
            observer.wrap_publications++;
            observer.wrap_entrants += entrants_added;
            observer.wrap_victims += victims_removed;
        }
    } else if (strcmp(result_name, "skipped") == 0) {
        if (snapshot_after != snapshot_before ||
            resident_after != resident_before) {
            result_name = "failed";
            reason = "skip-invariant";
            g_dynamic_arena.fatal_errors++;
            observer.wrap_failures++;
        } else {
            observer.wrap_skips++;
        }
    } else {
        observer.wrap_failures++;
        if (snapshot_after != snapshot_before ||
            resident_after != resident_before) {
            reason = "rollback-invariant";
            g_dynamic_arena.fatal_errors++;
        }
    }

    fprintf(stderr,
            "ds4: [reap-mass-wrap] result=%s reason=%s tokens=%llu entrants=%u victims=%u free_before=%u resident_before=%u resident_after=%u loads=%u workers=%u seconds=%.3f snapshot_before=%llu snapshot_after=%llu generation=%llu router=unbiased mask=off\n",
            result_name, reason, (unsigned long long)observer.tokens,
            entrants_added, victims_removed, free_before,
            resident_before, resident_after, wrap.loads, wrap.workers,
            wrap.seconds, (unsigned long long)snapshot_before,
            (unsigned long long)snapshot_after,
            (unsigned long long)wrap.generation);
    return strcmp(result_name, "published") == 0;
}

static void cuda_reap_mass_observer_release(int report) {
    if (report) cuda_reap_mass_commit_all_pending();
    if (report) (void)cuda_reap_mass_publish_residency();
    if (report) cuda_reap_mass_report("request-end");
    if (report && g_reap_mass_observer.wrap_requested) {
        fprintf(stderr,
                "ds4: [reap-mass-wrap] request-end attempts=%llu publications=%llu skips=%llu failures=%llu entrants=%llu victims=%llu\n",
                (unsigned long long)g_reap_mass_observer.wrap_attempts,
                (unsigned long long)g_reap_mass_observer.wrap_publications,
                (unsigned long long)g_reap_mass_observer.wrap_skips,
                (unsigned long long)g_reap_mass_observer.wrap_failures,
                (unsigned long long)g_reap_mass_observer.wrap_entrants,
                (unsigned long long)g_reap_mass_observer.wrap_victims);
    }
    g_reap_mass_observer.totals.clear();
    g_reap_mass_observer.ring.clear();
    g_reap_mass_observer.pending.clear();
    g_reap_mass_observer.touched.clear();
    g_reap_mass_observer.touched_entries.clear();
    g_reap_mass_observer.target.clear();
    g_reap_mass_observer.enabled = 0;
    g_reap_mass_observer.armed = 0;
    g_reap_mass_observer.wrap_requested = 0;
    g_reap_mass_observer.window = 0;
    g_reap_mass_observer.top = 0;
    g_reap_mass_observer.grow_interval = 0;
    g_reap_mass_observer.entry_count = 0;
    g_reap_mass_observer.layer_min = 3;
    g_reap_mass_observer.layer_max = 42;
    g_reap_mass_observer.last_layer = 0;
    g_reap_mass_observer.unique_entries = 0;
    g_reap_mass_observer.last_touched = 0;
    g_reap_mass_observer.tokens = 0;
    g_reap_mass_observer.last_publish_tokens = 0;
    g_reap_mass_observer.observed_slots = 0;
    g_reap_mass_observer.wrap_attempts = 0;
    g_reap_mass_observer.wrap_publications = 0;
    g_reap_mass_observer.wrap_skips = 0;
    g_reap_mass_observer.wrap_failures = 0;
    g_reap_mass_observer.wrap_entrants = 0;
    g_reap_mass_observer.wrap_victims = 0;
    g_reap_mass_observer.top_mass = 0.0;
    g_reap_mass_observer.hysteresis = 0.0;
}

static void cuda_reap_mass_observer_reset(void) {
    cuda_reap_mass_observer_release(1);
    const int wrap = cuda_reap_mass_wrap_requested();
    if (!cuda_reap_mass_observe_requested() && !wrap) return;
    const uint32_t window = cuda_reap_mass_window();
    if (window == 0) return;
    const uint32_t grow_interval = wrap ?
        cuda_reap_mass_grow_interval() : 0;
    const double hysteresis = wrap ? cuda_reap_mass_hysteresis() : 0.0;
    if (wrap && (grow_interval == 0 || hysteresis < 1.0)) return;
    if (!g_dynamic_arena.host_base || g_dynamic_arena.n_layer <= 3 ||
        g_dynamic_arena.n_expert == 0) {
        fprintf(stderr,
                "ds4: [reap-mass] unavailable reason=dynamic-arena-not-ready\n");
        return;
    }
    if (!cuda_reap_router_trace_ensure()) {
        fprintf(stderr,
                "ds4: [reap-mass] packed router trace unavailable; observer disabled\n");
        return;
    }
    const uint32_t layer_max = std::min(42u, g_dynamic_arena.n_layer - 1u);
    if (layer_max < 3) return;
    const uint32_t entry_count =
        g_dynamic_arena.n_layer * g_dynamic_arena.n_expert;
    try {
        g_reap_mass_observer.totals.assign(entry_count, 0.0);
        g_reap_mass_observer.ring.assign(
            (uint64_t)window * entry_count, 0.0);
        g_reap_mass_observer.pending.clear();
        g_reap_mass_observer.touched.assign(entry_count, 0);
        g_reap_mass_observer.touched_entries.reserve(entry_count);
        if (wrap) g_reap_mass_observer.target.assign(entry_count, 0);
    } catch (...) {
        cuda_reap_mass_observer_release(0);
        fprintf(stderr,
                "ds4: [reap-mass] metadata allocation failed; observer disabled\n");
        return;
    }
    g_reap_mass_observer.enabled = 1;
    g_reap_mass_observer.wrap_requested = wrap;
    g_reap_mass_observer.window = window;
    g_reap_mass_observer.grow_interval = grow_interval;
    g_reap_mass_observer.hysteresis = hysteresis;
    g_reap_mass_observer.entry_count = entry_count;
    g_reap_mass_observer.layer_min = 3;
    g_reap_mass_observer.layer_max = layer_max;
    if (wrap) cuda_dynamic_arena_observer_release();
}

static void cuda_reap_mass_arm(uint32_t top, uint32_t n_tokens) {
    cuda_reap_mass_observer &observer = g_reap_mass_observer;
    if (observer.armed) return;
    try {
        observer.pending.assign(n_tokens, {});
    } catch (...) {
        fprintf(stderr,
                "ds4: [reap-mass] pending allocation failed; observer disabled\n");
        cuda_reap_mass_observer_release(0);
        return;
    }
    observer.top = top;
    observer.armed = 1;
    fprintf(stderr,
            "ds4: [reap-mass] armed window=%u top=%u layers=%u..%u semantics=selected_weight_normalized_per_token sliding_ring_observe_only transport=packed-router-d2h\n",
            observer.window, observer.top,
            observer.layer_min, observer.layer_max);
    if (observer.wrap_requested) {
        fprintf(stderr,
                "ds4: [reap-mass-wrap] armed grow_interval=%u hysteresis=%.9g capacity=%u router=unbiased mask=off policy=free-then-mass-victim\n",
                observer.grow_interval, observer.hysteresis,
                cuda_reap_mass_resident_limit());
    }
}

static void cuda_prefill_mass_observer_report_decode(const char *reason) {
    const cuda_prefill_mass_observer &observer = g_prefill_mass_observer;
    if (!observer.enabled || !observer.finalized ||
        observer.decode_slots == 0) {
        return;
    }
    uint32_t reported_tokens = observer.decode_tokens;
    if (observer.have_decode_layer && reason &&
        strcmp(reason, "request-end") == 0) {
        reported_tokens++;
    }
    const char *policy = observer.wrap_requested ?
        "bulk-wrap" : "observe-only";
    fprintf(stderr,
            "ds4: [prefill-mass] decode reason=%s tokens=%u slots=%llu candidate_hits=%llu hit_rate=%.4f policy=%s\n",
            reason ? reason : "unknown", reported_tokens,
            (unsigned long long)observer.decode_slots,
            (unsigned long long)observer.decode_candidate_hits,
            (double)observer.decode_candidate_hits /
                (double)observer.decode_slots, policy);
}

static int cuda_sparse_bake_router_bias_topology_matches(void) {
    if (!g_sparse_bake_active || g_dynamic_arena.n_expert != 256u) return 0;
    const size_t layers = std::max(
        (size_t)g_dynamic_arena.n_layer, g_reap_router_bias.size());
    for (size_t layer = 0; layer < layers; layer++) {
        const int expected = layer < g_dynamic_arena.n_layer &&
            cuda_sparse_bake_layer_is_sparse((uint32_t)layer);
        const int actual = layer < g_reap_router_bias.size() &&
            g_reap_router_bias[layer] != NULL;
        if (expected != actual) return 0;
    }
    return 1;
}

static int cuda_sparse_bake_restore_router_bias(const char *where) {
    if (!g_sparse_bake_active || g_dynamic_arena.n_expert != 256u) return 0;
    float bias[256];
    uint32_t layers = 0;
    uint32_t kept = 0;
    uint32_t pruned = 0;
    for (uint32_t layer = 0; layer < g_dynamic_arena.n_layer; layer++) {
        if (!cuda_sparse_bake_layer_is_sparse(layer)) continue;
        uint32_t layer_kept = 0;
        for (uint32_t expert = 0; expert < 256u; expert++) {
            const int retained =
                cuda_sparse_bake_expert_retained(layer, expert);
            bias[expert] = retained ? 0.0f : -1.0e9f;
            layer_kept += retained;
        }
        if (!ds4_gpu_reap_router_bias_update(layer, bias, 256u)) {
            fprintf(stderr,
                    "ds4: [prefill-mass-compose-mask] result=restore-failed reason=upload where=%s layer=%u layers=%u kept=%u pruned=%u base=embedded-sparse-bake\n",
                    where ? where : "unknown", layer, layers, kept, pruned);
            return 0;
        }
        layers++;
        kept += layer_kept;
        pruned += 256u - layer_kept;
    }
    fprintf(stderr,
            "ds4: [prefill-mass-compose-mask] result=restored reason=ok where=%s layers=%u kept=%u pruned=%u base=embedded-sparse-bake\n",
            where ? where : "unknown", layers, kept, pruned);
    return layers > 0;
}

static void cuda_prefill_mass_compose_release_router_mask(const char *where) {
    if (!g_sparse_bake_active) {
        ds4_gpu_reap_router_bias_reset();
        fprintf(stderr,
                "ds4: [prefill-mass-compose-mask] result=restored reason=ok "
                "where=%s layers=0 kept=0 pruned=0 base=none\n",
                where ? where : "unknown");
        return;
    }
    if (cuda_sparse_bake_restore_router_bias(where)) return;
    ds4_gpu_reap_router_bias_reset();
    g_dynamic_arena.submissions_blocked = 1;
    g_dynamic_arena.hits_disabled = 1;
    g_dynamic_arena.fatal_errors++;
}

static void cuda_prefill_mass_observer_release(int report) {
    if (report) cuda_prefill_mass_observer_report_decode("request-end");
    if (g_prefill_mass_observer.compose_mask_applied) {
        cuda_prefill_mass_compose_release_router_mask("request-end");
    }
    g_prefill_mass_observer.mass.clear();
    g_prefill_mass_observer.counts.clear();
    g_prefill_mass_observer.rows_by_layer.clear();
    g_prefill_mass_observer.layer_seen.clear();
    g_prefill_mass_observer.candidate.clear();
    g_prefill_mass_observer.enabled = 0;
    g_prefill_mass_observer.finalized = 0;
    g_prefill_mass_observer.have_decode_layer = 0;
    g_prefill_mass_observer.wrap_requested = 0;
    g_prefill_mass_observer.wrap_attempted = 0;
    g_prefill_mass_observer.wrap_published = 0;
    g_prefill_mass_observer.compose_mask_applied = 0;
    g_prefill_mass_observer.compose_router_open = 0;
    g_prefill_mass_observer.unique_entries = 0;
    g_prefill_mass_observer.layers_seen = 0;
    g_prefill_mass_observer.candidate_entries = 0;
    g_prefill_mass_observer.last_decode_layer = 0;
    g_prefill_mass_observer.decode_tokens = 0;
    g_prefill_mass_observer.routed_slots = 0;
    g_prefill_mass_observer.decode_slots = 0;
    g_prefill_mass_observer.decode_candidate_hits = 0;
}

static void cuda_prefill_mass_compose_fail_closed(void) {
    if (cuda_moe_prefill_tier_compose_requested() <= 0 &&
        !cuda_q1_0_snapshot_backing_requested()) return;
    if (g_prefill_mass_observer.compose_mask_applied) {
        cuda_prefill_mass_compose_release_router_mask("fail-closed");
        g_prefill_mass_observer.compose_mask_applied = 0;
    }
    /* A composed snapshot without its complete request mask is unsafe. Keep
     * the arena poisoned until process teardown and make decode fail instead
     * of falling back to model-map/SSD transport. */
    g_dynamic_arena.submissions_blocked = 1;
    g_dynamic_arena.hits_disabled = 1;
    if (cuda_q1_0_dual_sparse_companion_requested()) {
        cuda_q1_0_dual_sparse_abort("prefill-compose");
    }
}

static int cuda_prefill_mass_compose_apply_router_mask(void) {
    cuda_prefill_mass_observer &observer = g_prefill_mass_observer;
    if (cuda_moe_prefill_tier_compose_requested() <= 0) return 1;
    if (cuda_q1_0_exclusive_arena_active()) {
        fprintf(stderr,
                "ds4: [q1-0-resident-arena] result=failed reason=mixed-host-resolver-not-implemented router=unchanged\n");
        return 0;
    }
    const int router_open =
        cuda_moe_prefill_tier_router_open_requested();
    if (router_open < 0) return 0;
    uint32_t existing_bias_layers = 0;
    for (float *device_bias : g_reap_router_bias) {
        existing_bias_layers += device_bias != NULL;
    }
    if (router_open) {
        if (existing_bias_layers != 0u || g_sparse_bake_active) {
            fprintf(stderr,
                    "ds4: [prefill-mass-compose-mask] result=failed reason=open-router-existing-bias layers=%u kept=0 pruned=0 base=%s\n",
                    existing_bias_layers,
                    g_sparse_bake_active ? "embedded-sparse-bake" : "unknown");
            return 0;
        }
        observer.compose_router_open = 1;
        fprintf(stderr,
                "ds4: [prefill-mass-compose-mask] result=applied reason=ok layers=0 kept=0 pruned=0 semantics=request-scoped-open base=none existing_layers=0\n");
        return 1;
    }
    const char *mask_base = "none";
    if (existing_bias_layers > 0) {
        if (!g_sparse_bake_active ||
            !cuda_sparse_bake_router_bias_topology_matches()) {
            fprintf(stderr,
                    "ds4: [prefill-mass-compose-mask] result=failed reason=existing-router-bias layers=%u kept=0 pruned=0 base=unknown\n",
                    existing_bias_layers);
            return 0;
        }
        mask_base = "embedded-sparse-bake";
    }
    std::vector<float> bias;
    try {
        bias.assign(g_dynamic_arena.n_expert, -1.0e9f);
    } catch (...) {
        fprintf(stderr,
                "ds4: [prefill-mass-compose-mask] result=failed reason=metadata-allocation layers=0 kept=0 pruned=0\n");
        return 0;
    }
    uint32_t layers = 0;
    uint32_t kept = 0;
    uint32_t pruned = 0;
    for (uint32_t layer = 3; layer < g_dynamic_arena.n_layer; layer++) {
        uint32_t layer_kept = 0;
        const uint32_t layer_base = layer * g_dynamic_arena.n_expert;
        for (uint32_t expert = 0;
             expert < g_dynamic_arena.n_expert; expert++) {
            const int resident =
                observer.candidate[layer_base + expert] != 0;
            if (resident &&
                !cuda_sparse_bake_expert_retained(layer, expert)) {
                cuda_prefill_mass_compose_release_router_mask(
                    "candidate-not-retained");
                fprintf(stderr,
                        "ds4: [prefill-mass-compose-mask] result=failed reason=candidate-not-retained layer=%u kept=%u pruned=%u base=%s\n",
                        layer, layer_kept,
                        g_dynamic_arena.n_expert - layer_kept, mask_base);
                return 0;
            }
            bias[expert] = resident ? 0.0f : -1.0e9f;
            layer_kept += resident;
        }
        if (layer_kept < 6u ||
            !ds4_gpu_reap_router_bias_update(
                layer, bias.data(), g_dynamic_arena.n_expert)) {
            cuda_prefill_mass_compose_release_router_mask("apply-failure");
            fprintf(stderr,
                    "ds4: [prefill-mass-compose-mask] result=failed reason=layer-mask layer=%u kept=%u pruned=%u base=%s\n",
                    layer, layer_kept,
                    g_dynamic_arena.n_expert - layer_kept, mask_base);
            return 0;
        }
        layers++;
        kept += layer_kept;
        pruned += g_dynamic_arena.n_expert - layer_kept;
    }
    observer.compose_mask_applied = 1;
    fprintf(stderr,
            "ds4: [prefill-mass-compose-mask] result=applied reason=ok layers=%u kept=%u pruned=%u semantics=request-scoped-closed base=%s existing_layers=%u\n",
            layers, kept, pruned, mask_base, existing_bias_layers);
    return 1;
}

static void cuda_prefill_mass_observer_reset(void) {
    cuda_prefill_mass_observer_release(1);
    if (cuda_q1_0_exclusive_arena_active()) {
        fprintf(stderr,
                "ds4: [q1-0-resident-arena] prefill_mass=disabled snapshot=full-bootstrap router=unchanged dynamic_masks=not-implemented\n");
        return;
    }
    const int wrap = cuda_prefill_mass_wrap_requested();
    const int observe = cuda_prefill_mass_observe_requested();
    if (!observe && !wrap) return;
    if (!g_dynamic_arena.host_base || g_dynamic_arena.n_layer <= 3 ||
        g_dynamic_arena.n_expert == 0 || g_dynamic_arena.slots.empty()) {
        fprintf(stderr,
                "ds4: [prefill-mass] unavailable reason=dynamic-arena-not-ready policy=%s\n",
                wrap ? "bulk-wrap" : "observe-only");
        return;
    }

    const size_t entry_count =
        (size_t)g_dynamic_arena.n_layer * g_dynamic_arena.n_expert;
    try {
        g_prefill_mass_observer.mass.assign(entry_count, 0.0);
        g_prefill_mass_observer.counts.assign(entry_count, 0);
        g_prefill_mass_observer.rows_by_layer.assign(
            g_dynamic_arena.n_layer, 0);
        g_prefill_mass_observer.layer_seen.assign(
            g_dynamic_arena.n_layer, 0);
        g_prefill_mass_observer.candidate.assign(entry_count, 0);
    } catch (...) {
        cuda_prefill_mass_observer_release(0);
        fprintf(stderr,
                "ds4: [prefill-mass] metadata allocation failed; observer disabled\n");
        return;
    }
    g_prefill_mass_observer.enabled = 1;
    g_prefill_mass_observer.wrap_requested = wrap;
    fprintf(stderr,
            "ds4: [prefill-mass] armed slots=%u layers=3..%u router=unbiased residency=%s policy=%s\n",
            (uint32_t)g_dynamic_arena.slots.size(),
            g_dynamic_arena.n_layer - 1u,
            wrap ? "prefill-ranked" : "unchanged",
            wrap ? "bulk-wrap" : "observe-only");
}

static int cuda_prefill_mass_publish_candidate(void) {
    cuda_prefill_mass_observer &observer = g_prefill_mass_observer;
    cuda_request_phase_trace("wrap-enter");
    observer.wrap_attempted = 1;
    const uint64_t snapshot_before = g_dynamic_arena.snapshot_generation;
    const uint32_t resident_before = cuda_dynamic_arena_active_count();
    const uint32_t entry_count =
        g_dynamic_arena.n_layer * g_dynamic_arena.n_expert;
    const char *terminal = "skipped";
    const char *reason = "no-routing";
    cuda_dynamic_arena_wrap_result wrap = {};
    int q1_companion_staged = 0;

    do {
        if (!observer.wrap_requested || observer.candidate_entries == 0) {
            break;
        }
        if (!g_dynamic_arena.host_base || g_dynamic_arena.slots.empty() ||
            g_dynamic_arena.active.size() != entry_count ||
            g_dynamic_arena.staging.size() != entry_count ||
            g_dynamic_arena.preloaded.size() != entry_count ||
            g_dynamic_arena.preloaded_parts.size() != entry_count) {
            reason = "arena-not-ready";
            break;
        }
        if (g_dynamic_arena.txn || g_dynamic_arena.submissions_blocked ||
            g_dynamic_arena.hits_disabled) {
            reason = "transaction-active";
            break;
        }
        if (g_dynamic_arena_observer.enabled ||
            !g_dynamic_arena_observer.target.empty() ||
            !g_dynamic_arena_observer.counts.empty()) {
            reason = "observer-active";
            break;
        }
        int preloads_active = 0;
        for (uint32_t entry = 0; entry < entry_count; entry++) {
            if (g_dynamic_arena.preloaded_parts[entry] != 0 ||
                g_dynamic_arena.preloaded[entry].slot != UINT32_MAX) {
                preloads_active = 1;
                break;
            }
        }
        if (preloads_active) {
            reason = "preloads-active";
            break;
        }
        uint32_t candidate_count = 0;
        for (uint32_t entry = 0; entry < observer.candidate.size(); entry++) {
            candidate_count += observer.candidate[entry] != 0;
        }
        if (observer.candidate.size() != entry_count ||
            candidate_count != observer.candidate_entries ||
            observer.candidate_entries > g_dynamic_arena.slots.size()) {
            reason = "invalid-target";
            break;
        }
        if (cuda_q1_0_dual_sparse_companion_requested()) {
            if (!cuda_q1_0_dual_sparse_stage(
                    observer.candidate.data(), entry_count)) {
                reason = "q1-companion-stage";
                break;
            }
            q1_companion_staged = 1;
        }
        cuda_request_phase_trace("wrap-copy-enter");
        const int published = cuda_dynamic_arena_wrap_publish_target(
                observer.candidate.data(), entry_count, &wrap);
        cuda_request_phase_trace("wrap-copy-return");
        if (published) {
            if (q1_companion_staged &&
                !cuda_q1_0_dual_sparse_commit(
                    observer.candidate.data(), entry_count,
                    wrap.generation)) {
                terminal = "failed";
                reason = "q1-companion-commit";
                g_dynamic_arena.fatal_errors++;
                cuda_prefill_mass_compose_fail_closed();
            } else if (cuda_prefill_mass_compose_apply_router_mask()) {
                terminal = "published";
                reason = "ok";
                observer.wrap_published = 1;
            } else {
                terminal = "failed";
                reason = "compose-mask";
                g_dynamic_arena.fatal_errors++;
                cuda_prefill_mass_compose_fail_closed();
            }
        } else {
            if (q1_companion_staged) {
                cuda_q1_0_dual_sparse_abort("primary-publish");
            }
            terminal = wrap.aborted ? "aborted" : "failed";
            reason = wrap.reason ? wrap.reason : "publish";
        }
    } while (0);

    const uint64_t snapshot_after = g_dynamic_arena.snapshot_generation;
    const uint32_t resident_after = cuda_dynamic_arena_active_count();
    if (observer.wrap_published &&
        (wrap.loads > observer.candidate_entries ||
         (snapshot_before == 0 &&
          wrap.loads != observer.candidate_entries) ||
         resident_after != observer.candidate_entries ||
         snapshot_after <= snapshot_before ||
         wrap.generation != snapshot_after)) {
        terminal = "failed";
        reason = "publish-invariant";
        observer.wrap_published = 0;
        g_dynamic_arena.fatal_errors++;
        cuda_prefill_mass_compose_fail_closed();
    } else if (!observer.wrap_published &&
               (snapshot_after != snapshot_before ||
                resident_after != resident_before)) {
        terminal = "failed";
        reason = "rollback-invariant";
        g_dynamic_arena.fatal_errors++;
        cuda_prefill_mass_compose_fail_closed();
    }
    fprintf(stderr,
            "ds4: [prefill-mass-wrap] result=%s reason=%s candidate=%u loads=%u workers=%u seconds=%.3f snapshot_before=%llu snapshot_after=%llu resident_before=%u resident_after=%u generation=%llu preloaded=0 router=unbiased mask=%s\n",
            terminal, reason, observer.candidate_entries,
            wrap.loads, wrap.workers, wrap.seconds,
            (unsigned long long)snapshot_before,
            (unsigned long long)snapshot_after,
            resident_before, resident_after,
            (unsigned long long)wrap.generation,
            observer.compose_mask_applied ? "request-scoped-closed" :
            (observer.compose_router_open ? "request-scoped-open" : "off"));
    cuda_request_phase_trace("wrap-terminal");
    return observer.wrap_published;
}

static void cuda_prefill_mass_observer_finalize(void) {
    cuda_prefill_mass_observer &observer = g_prefill_mass_observer;
    if (!observer.enabled || observer.finalized) return;
    cuda_request_phase_trace("prefill-finalize-enter");
    observer.finalized = 1;
    if (observer.routed_slots == 0 || observer.unique_entries == 0) {
        fprintf(stderr,
                "ds4: [prefill-mass] finalize result=no-prefill-routing policy=%s\n",
                observer.wrap_requested ? "bulk-wrap" : "observe-only");
        if (observer.wrap_requested) {
            (void)cuda_prefill_mass_publish_candidate();
        }
        cuda_request_phase_trace("prefill-finalize-return");
        return;
    }

    struct ranked_entry {
        double mass;
        uint32_t entry;
    };
    std::vector<ranked_entry> ranked;
    try {
        ranked.reserve(observer.unique_entries);
        for (uint32_t entry = 0; entry < observer.counts.size(); entry++) {
            if (observer.counts[entry] == 0) continue;
            ranked.push_back({observer.mass[entry], entry});
        }
    } catch (...) {
        fprintf(stderr,
                "ds4: [prefill-mass] rank allocation failed; observer disabled\n");
        if (observer.wrap_requested) {
            fprintf(stderr,
                    "ds4: [prefill-mass-wrap] result=failed reason=allocation candidate=0 loads=0 workers=0 seconds=0.000 snapshot_before=%llu snapshot_after=%llu resident_before=%u resident_after=%u generation=0 preloaded=0 router=unbiased mask=off\n",
                    (unsigned long long)g_dynamic_arena.snapshot_generation,
                    (unsigned long long)g_dynamic_arena.snapshot_generation,
                    cuda_dynamic_arena_active_count(),
                    cuda_dynamic_arena_active_count());
        }
        cuda_prefill_mass_observer_release(0);
        cuda_request_phase_trace("prefill-finalize-return");
        return;
    }
    std::sort(ranked.begin(), ranked.end(),
              [](const ranked_entry &a, const ranked_entry &b) {
                  if (a.mass != b.mass) return a.mass > b.mass;
                  return a.entry < b.entry;
              });

    size_t residency_capacity =
        g_reap_mass_observer.wrap_requested ?
        (size_t)cuda_reap_mass_resident_limit() :
        g_dynamic_arena.slots.size();
    const int compose_requested = observer.wrap_requested ?
        cuda_moe_prefill_tier_compose_requested() : 0;
    const int full_q1_snapshot_requested = observer.wrap_requested &&
        cuda_q1_0_snapshot_backing_requested();
    const int compose_router_open = compose_requested > 0 ?
        cuda_moe_prefill_tier_router_open_requested() : 0;
    const int promotion_probation_slots = compose_router_open > 0 ?
        cuda_quant_promotion_probation_slots_requested() : 0;
    const int configured_reserve_slots = compose_router_open > 0 ?
        cuda_moe_prefill_tier_reserve_slots_requested() : 0;
    const int reserved_slots = std::max(
        promotion_probation_slots, configured_reserve_slots);
    if (g_nested_residual.active && compose_requested > 0 &&
        compose_router_open != 1) {
        fprintf(stderr,
                "ds4: [prefill-mass-wrap] result=failed "
                "reason=nested-residual-requires-open-router candidate=0 "
                "loads=0 workers=0 seconds=0.000 snapshot_before=%llu "
                "snapshot_after=%llu resident_before=%u resident_after=%u "
                "generation=0 preloaded=0 router=unbiased mask=off\n",
                (unsigned long long)g_dynamic_arena.snapshot_generation,
                (unsigned long long)g_dynamic_arena.snapshot_generation,
                cuda_dynamic_arena_active_count(),
                cuda_dynamic_arena_active_count());
        cuda_prefill_mass_compose_fail_closed();
        cuda_request_phase_trace("prefill-finalize-return");
        return;
    }
    if (compose_router_open < 0 || promotion_probation_slots < 0 ||
        configured_reserve_slots < 0 || reserved_slots < 0 ||
        (size_t)reserved_slots >= residency_capacity) {
        fprintf(stderr,
                "ds4: [prefill-mass-wrap] result=failed reason=probation-capacity candidate=0 loads=0 workers=0 seconds=0.000 snapshot_before=%llu snapshot_after=%llu resident_before=%u resident_after=%u generation=0 preloaded=0 router=unbiased mask=off\n",
                (unsigned long long)g_dynamic_arena.snapshot_generation,
                (unsigned long long)g_dynamic_arena.snapshot_generation,
                cuda_dynamic_arena_active_count(),
                cuda_dynamic_arena_active_count());
        cuda_prefill_mass_compose_fail_closed();
        cuda_request_phase_trace("prefill-finalize-return");
        return;
    }
    if (reserved_slots > 0) {
        residency_capacity -= (size_t)reserved_slots;
    }
    const uint32_t hash_layers =
        (compose_requested > 0 || full_q1_snapshot_requested) ?
        std::min(3u, g_dynamic_arena.n_layer) : 0u;
    const size_t hash_entries =
        (size_t)hash_layers * g_dynamic_arena.n_expert;
    if (hash_entries > residency_capacity) {
        fprintf(stderr,
                "ds4: [prefill-mass-wrap] result=failed reason=compose-hash-capacity candidate=0 loads=0 workers=0 seconds=0.000 snapshot_before=%llu snapshot_after=%llu resident_before=%u resident_after=%u generation=0 preloaded=0 router=unbiased mask=off\n",
                (unsigned long long)g_dynamic_arena.snapshot_generation,
                (unsigned long long)g_dynamic_arena.snapshot_generation,
                cuda_dynamic_arena_active_count(),
                cuda_dynamic_arena_active_count());
        cuda_request_phase_trace("prefill-finalize-return");
        return;
    }
    const size_t ranked_capacity = residency_capacity - hash_entries;
    const auto sparse_entry_retained = [](uint32_t entry) {
        if (!g_sparse_bake_active) return 1;
        const uint32_t layer = entry / g_dynamic_arena.n_expert;
        const uint32_t expert = entry % g_dynamic_arena.n_expert;
        return cuda_sparse_bake_expert_retained(layer, expert);
    };
    uint32_t sparse_skipped_ranked = 0;
    uint32_t nested_skipped_ranked = 0;
    uint32_t stripe_stride = 0;
    uint32_t stripe_phase = 0;
    const int stripe_config = cuda_prefill_mass_layer_stripe_config(
        &stripe_stride, &stripe_phase);
    if (stripe_config < 0 ||
        (stripe_config > 0 && compose_requested <= 0)) {
        fprintf(stderr,
                "ds4: [prefill-mass-layer-stripe] result=failed reason=%s\n",
                stripe_config < 0 ? "invalid-config" : "compose-required");
        cuda_prefill_mass_compose_fail_closed();
        cuda_request_phase_trace("prefill-finalize-return");
        return;
    }
    if (stripe_config > 0 && g_nested_residual.active) {
        fprintf(stderr,
                "ds4: [prefill-mass-layer-stripe] result=failed "
                "reason=nested-residual-not-supported\n");
        cuda_prefill_mass_compose_fail_closed();
        cuda_request_phase_trace("prefill-finalize-return");
        return;
    }

    uint32_t capacity = (uint32_t)std::min(
        ranked.size(), ranked_capacity);
    if (stripe_config > 0) {
        const uint32_t first_layer = 3u;
        const uint32_t routed_layers =
            g_dynamic_arena.n_layer > first_layer ?
            g_dynamic_arena.n_layer - first_layer : 0u;
        if (ranked_capacity >
                (size_t)routed_layers * g_dynamic_arena.n_expert ||
            ranked_capacity > UINT32_MAX || routed_layers == 0) {
            fprintf(stderr,
                    "ds4: [prefill-mass-layer-stripe] result=failed reason=invalid-capacity stride=%u phase=%u routed_layers=%u capacity=%llu\n",
                    stripe_stride, stripe_phase, routed_layers,
                    (unsigned long long)ranked_capacity);
            cuda_prefill_mass_compose_fail_closed();
            cuda_request_phase_trace("prefill-finalize-return");
            return;
        }

        std::vector<uint8_t> full_layer;
        std::vector<uint32_t> quota;
        std::vector<uint32_t> selected_by_layer;
        try {
            full_layer.assign(g_dynamic_arena.n_layer, 0);
            quota.assign(g_dynamic_arena.n_layer, 0);
            selected_by_layer.assign(g_dynamic_arena.n_layer, 0);
        } catch (...) {
            fprintf(stderr,
                    "ds4: [prefill-mass-layer-stripe] result=failed reason=metadata-allocation\n");
            cuda_prefill_mass_compose_fail_closed();
            cuda_request_phase_trace("prefill-finalize-return");
            return;
        }

        uint32_t full_layers = 0;
        for (uint32_t layer = first_layer;
             layer < g_dynamic_arena.n_layer; layer++) {
            const uint32_t relative = layer - first_layer;
            if (relative % stripe_stride == stripe_phase) {
                full_layer[layer] = 1;
                quota[layer] = g_dynamic_arena.n_expert;
                full_layers++;
            }
        }
        const uint32_t partial_layers = routed_layers - full_layers;
        const uint64_t full_entries =
            (uint64_t)full_layers * g_dynamic_arena.n_expert;
        if (full_layers == 0 || full_entries > ranked_capacity ||
            (partial_layers == 0 && full_entries != ranked_capacity)) {
            fprintf(stderr,
                    "ds4: [prefill-mass-layer-stripe] result=failed reason=full-layer-capacity stride=%u phase=%u full_layers=%u partial_layers=%u full_entries=%llu capacity=%llu\n",
                    stripe_stride, stripe_phase, full_layers, partial_layers,
                    (unsigned long long)full_entries,
                    (unsigned long long)ranked_capacity);
            cuda_prefill_mass_compose_fail_closed();
            cuda_request_phase_trace("prefill-finalize-return");
            return;
        }

        const uint32_t partial_entries =
            (uint32_t)(ranked_capacity - full_entries);
        const uint32_t partial_keep_min = partial_layers ?
            partial_entries / partial_layers : 0u;
        const uint32_t partial_keep_extra = partial_layers ?
            partial_entries % partial_layers : 0u;
        const uint32_t partial_keep_max = partial_keep_min +
            (partial_keep_extra ? 1u : 0u);
        if (partial_layers &&
            (partial_keep_min < 6u ||
             partial_keep_max > g_dynamic_arena.n_expert)) {
            fprintf(stderr,
                    "ds4: [prefill-mass-layer-stripe] result=failed reason=partial-layer-capacity stride=%u phase=%u partial_min=%u partial_max=%u\n",
                    stripe_stride, stripe_phase,
                    partial_keep_min, partial_keep_max);
            cuda_prefill_mass_compose_fail_closed();
            cuda_request_phase_trace("prefill-finalize-return");
            return;
        }

        uint32_t extra_left = partial_keep_extra;
        for (uint32_t layer = first_layer;
             layer < g_dynamic_arena.n_layer; layer++) {
            if (full_layer[layer]) continue;
            quota[layer] = partial_keep_min + (extra_left ? 1u : 0u);
            if (extra_left) extra_left--;
        }
        for (uint32_t layer = first_layer;
             layer < g_dynamic_arena.n_layer; layer++) {
            if (!full_layer[layer]) continue;
            const uint32_t base = layer * g_dynamic_arena.n_expert;
            for (uint32_t expert = 0;
                 expert < g_dynamic_arena.n_expert; expert++) {
                observer.candidate[base + expert] = 1;
            }
            selected_by_layer[layer] = g_dynamic_arena.n_expert;
        }
        for (const ranked_entry &item : ranked) {
            const uint32_t layer = item.entry / g_dynamic_arena.n_expert;
            if (layer < first_layer || layer >= g_dynamic_arena.n_layer ||
                full_layer[layer] ||
                selected_by_layer[layer] >= quota[layer]) {
                continue;
            }
            observer.candidate[item.entry] = 1;
            selected_by_layer[layer]++;
        }
        for (uint32_t layer = first_layer;
             layer < g_dynamic_arena.n_layer; layer++) {
            if (full_layer[layer]) continue;
            const uint32_t base = layer * g_dynamic_arena.n_expert;
            for (uint32_t expert = 0;
                 expert < g_dynamic_arena.n_expert &&
                 selected_by_layer[layer] < quota[layer]; expert++) {
                const uint32_t entry = base + expert;
                if (observer.candidate[entry]) continue;
                observer.candidate[entry] = 1;
                selected_by_layer[layer]++;
            }
            if (selected_by_layer[layer] != quota[layer]) {
                fprintf(stderr,
                        "ds4: [prefill-mass-layer-stripe] result=failed reason=quota-fill layer=%u selected=%u quota=%u\n",
                        layer, selected_by_layer[layer], quota[layer]);
                cuda_prefill_mass_compose_fail_closed();
                cuda_request_phase_trace("prefill-finalize-return");
                return;
            }
        }
        capacity = (uint32_t)ranked_capacity;
        fprintf(stderr,
                "ds4: [prefill-mass-layer-stripe] result=applied stride=%u phase=%u routed_layers=%u full_layers=%u partial_layers=%u full_keep=%u partial_keep_min=%u partial_keep_max=%u routed_candidate=%u total_candidate=%u capacity=%u semantics=budget-preserving\n",
                stripe_stride, stripe_phase, routed_layers,
                full_layers, partial_layers, g_dynamic_arena.n_expert,
                partial_keep_min, partial_keep_max, capacity,
                capacity + (uint32_t)hash_entries,
                (uint32_t)residency_capacity);
    } else {
        capacity = 0;
        for (const ranked_entry &item : ranked) {
            if ((size_t)capacity >= ranked_capacity) break;
            const uint32_t layer =
                item.entry / g_dynamic_arena.n_expert;
            if (cuda_nested_residual_layer_required(layer)) {
                nested_skipped_ranked++;
                continue;
            }
            if (!sparse_entry_retained(item.entry)) {
                sparse_skipped_ranked++;
                continue;
            }
            if (observer.candidate[item.entry]) continue;
            observer.candidate[item.entry] = 1;
            capacity++;
        }
        if ((compose_requested > 0 || full_q1_snapshot_requested) &&
            (size_t)capacity != ranked_capacity) {
            fprintf(stderr,
                    "ds4: [prefill-mass-wrap] result=failed reason=compose-retained-capacity candidate=%u loads=0 workers=0 seconds=0.000 snapshot_before=%llu snapshot_after=%llu resident_before=%u resident_after=%u generation=0 preloaded=0 router=unbiased mask=off\n",
                    capacity,
                    (unsigned long long)g_dynamic_arena.snapshot_generation,
                    (unsigned long long)g_dynamic_arena.snapshot_generation,
                    cuda_dynamic_arena_active_count(),
                    cuda_dynamic_arena_active_count());
            cuda_prefill_mass_compose_fail_closed();
            cuda_request_phase_trace("prefill-finalize-return");
            return;
        }
    }
    for (uint32_t entry = 0; entry < hash_entries; entry++) {
        if (!sparse_entry_retained(entry)) {
            fprintf(stderr,
                    "ds4: [prefill-mass-wrap] result=failed reason=compose-hash-sparse-absent candidate=%u loads=0 workers=0 seconds=0.000 snapshot_before=%llu snapshot_after=%llu resident_before=%u resident_after=%u generation=0 preloaded=0 router=unbiased mask=off\n",
                    capacity,
                    (unsigned long long)g_dynamic_arena.snapshot_generation,
                    (unsigned long long)g_dynamic_arena.snapshot_generation,
                    cuda_dynamic_arena_active_count(),
                    cuda_dynamic_arena_active_count());
            cuda_prefill_mass_compose_fail_closed();
            cuda_request_phase_trace("prefill-finalize-return");
            return;
        }
        observer.candidate[entry] = 1;
    }
    observer.candidate_entries = capacity + (uint32_t)hash_entries;
    double total_mass = 0.0;
    double candidate_mass = 0.0;
    double cutoff = 0.0;
    int cutoff_set = 0;
    for (const ranked_entry &item : ranked) {
        total_mass += item.mass;
        if (!observer.candidate[item.entry]) continue;
        candidate_mass += item.mass;
        if (!cutoff_set || item.mass < cutoff) {
            cutoff = item.mass;
            cutoff_set = 1;
        }
    }
    if (compose_requested > 0) {
        const uint64_t candidate_hash = cuda_dynamic_arena_fnv1a64(
            observer.candidate.data(), observer.candidate.size());
        fprintf(stderr,
                "ds4: [prefill-mass-compose] hash_layers=%u hash_seed_entries=%u ranked_entries=%u total_candidate=%u capacity=%u candidate_fnv1a64=%016llx sparse_skipped_ranked=%u nested_skipped_ranked=%u mass_source=full-probability-normalized-per-token\n",
                hash_layers, (uint32_t)hash_entries, capacity,
                observer.candidate_entries,
                (uint32_t)residency_capacity,
                (unsigned long long)candidate_hash,
                sparse_skipped_ranked, nested_skipped_ranked);
    }

    uint32_t rows_min = UINT32_MAX;
    uint32_t rows_max = 0;
    for (uint32_t layer = 3; layer < observer.rows_by_layer.size(); layer++) {
        if (!observer.layer_seen[layer]) continue;
        rows_min = std::min(rows_min, observer.rows_by_layer[layer]);
        rows_max = std::max(rows_max, observer.rows_by_layer[layer]);
    }
    if (rows_min == UINT32_MAX) rows_min = 0;
    const double coverage = total_mass > 0.0 ? candidate_mass / total_mass : 0.0;
    const int wrap = observer.wrap_requested;
    fprintf(stderr,
            "ds4: [prefill-mass] finalize layers=%u rows_min=%u rows_max=%u routed_slots=%llu unique=%u candidate=%u capacity=%u mass_total=%.6f mass_candidate=%.6f mass_coverage=%.4f cutoff=%.6f router=unbiased residency=%s policy=%s\n",
            observer.layers_seen, rows_min, rows_max,
            (unsigned long long)observer.routed_slots,
            observer.unique_entries, observer.candidate_entries,
            (uint32_t)g_dynamic_arena.slots.size(), total_mass,
            candidate_mass, coverage, cutoff,
            wrap ? "prefill-ranked" : "unchanged",
            wrap ? "bulk-wrap" : "observe-only");
    if (wrap) (void)cuda_prefill_mass_publish_candidate();
    cuda_request_phase_trace("prefill-finalize-return");
}

static void cuda_prefill_mass_observe_selected(
        uint32_t layer_index, uint32_t n_tokens,
        const int32_t *selected, const float *weights,
        uint32_t selected_count,
        const float *full_probs, uint32_t full_prob_count) {
    cuda_prefill_mass_observer &observer = g_prefill_mass_observer;
    if (!observer.enabled || !selected || selected_count == 0 ||
        layer_index < 3 || layer_index >= g_dynamic_arena.n_layer) {
        return;
    }
    const uint32_t base = layer_index * g_dynamic_arena.n_expert;
    if (!observer.finalized) {
        const uint64_t expected_full_probs =
            (uint64_t)n_tokens * g_dynamic_arena.n_expert;
        const int use_full_probs = full_probs &&
            full_prob_count == expected_full_probs &&
            (cuda_moe_prefill_tier_compose_requested() > 0 ||
             cuda_q1_0_snapshot_backing_requested());
        if (!use_full_probs && !weights) {
            fprintf(stderr,
                    "ds4: [prefill-mass] weights unavailable; observer disabled\n");
            cuda_prefill_mass_observer_release(0);
            return;
        }
        if (!observer.layer_seen[layer_index]) {
            observer.layer_seen[layer_index] = 1;
            observer.layers_seen++;
        }
        if (UINT32_MAX - observer.rows_by_layer[layer_index] >= n_tokens) {
            observer.rows_by_layer[layer_index] += n_tokens;
        } else {
            observer.rows_by_layer[layer_index] = UINT32_MAX;
        }
        observer.routed_slots += selected_count;
        if (use_full_probs) {
            for (uint32_t token = 0; token < n_tokens; token++) {
                const float *row = full_probs +
                    (uint64_t)token * g_dynamic_arena.n_expert;
                double row_sum = 0.0;
                for (uint32_t expert = 0;
                     expert < g_dynamic_arena.n_expert; expert++) {
                    if (isfinite(row[expert]) && row[expert] > 0.0f) {
                        row_sum += (double)row[expert];
                    }
                }
                if (!(row_sum > 0.0) || !isfinite(row_sum)) continue;
                for (uint32_t expert = 0;
                     expert < g_dynamic_arena.n_expert; expert++) {
                    if (!isfinite(row[expert]) || row[expert] <= 0.0f) continue;
                    const uint32_t entry = base + expert;
                    if (observer.counts[entry] == 0) observer.unique_entries++;
                    if (observer.counts[entry] != UINT32_MAX) {
                        observer.counts[entry]++;
                    }
                    observer.mass[entry] += (double)row[expert] / row_sum;
                }
            }
        } else {
            for (uint32_t i = 0; i < selected_count; i++) {
                const int32_t expert = selected[i];
                if (expert < 0 ||
                    (uint32_t)expert >= g_dynamic_arena.n_expert ||
                    !isfinite(weights[i])) {
                    continue;
                }
                const uint32_t entry = base + (uint32_t)expert;
                if (observer.counts[entry] == 0) observer.unique_entries++;
                if (observer.counts[entry] != UINT32_MAX) observer.counts[entry]++;
                observer.mass[entry] += (double)weights[i];
            }
        }
        return;
    }

    if (observer.have_decode_layer &&
        layer_index <= observer.last_decode_layer) {
        observer.decode_tokens++;
        if ((observer.decode_tokens & (observer.decode_tokens - 1u)) == 0) {
            cuda_prefill_mass_observer_report_decode("checkpoint");
        }
    }
    for (uint32_t i = 0; i < selected_count; i++) {
        const int32_t expert = selected[i];
        if (expert < 0 || (uint32_t)expert >= g_dynamic_arena.n_expert) {
            continue;
        }
        observer.decode_slots++;
        if (observer.candidate[base + (uint32_t)expert]) {
            observer.decode_candidate_hits++;
        }
    }
    observer.last_decode_layer = layer_index;
    observer.have_decode_layer = 1;
}

static void cuda_reap_mass_observe_selected(
        uint32_t layer_index, uint32_t n_tokens,
        const int32_t *selected, const float *weights,
        uint32_t selected_count) {
    cuda_reap_mass_observer &observer = g_reap_mass_observer;
    if (!observer.enabled || !selected || selected_count == 0 ||
        n_tokens != 1 || layer_index < observer.layer_min ||
        layer_index > observer.layer_max ||
        layer_index >= g_dynamic_arena.n_layer) {
        return;
    }
    if (!weights) {
        fprintf(stderr,
                "ds4: [reap-mass] weights unavailable; observer disabled\n");
        cuda_reap_mass_observer_release(0);
        return;
    }
    if (selected_count % n_tokens != 0) {
        fprintf(stderr,
                "ds4: [reap-mass] invalid selected geometry; observer disabled\n");
        cuda_reap_mass_observer_release(0);
        return;
    }
    const uint32_t top = selected_count / n_tokens;
    if (top == 0) return;
    if (!observer.armed) {
        cuda_reap_mass_arm(top, n_tokens);
        if (!observer.enabled || !observer.armed) return;
    } else if (observer.top != top) {
        fprintf(stderr,
                "ds4: [reap-mass] top changed old=%u new=%u; observer disabled\n",
                observer.top, top);
        cuda_reap_mass_observer_release(0);
        return;
    } else if (observer.pending.size() != n_tokens) {
        cuda_reap_mass_commit_all_pending();
        (void)cuda_reap_mass_publish_residency();
        try {
            observer.pending.assign(n_tokens, {});
        } catch (...) {
            fprintf(stderr,
                    "ds4: [reap-mass] pending resize failed; observer disabled\n");
            cuda_reap_mass_observer_release(0);
            return;
        }
    } else if (observer.last_layer != 0 &&
               layer_index <= observer.last_layer) {
        cuda_reap_mass_commit_all_pending();
        (void)cuda_reap_mass_publish_residency();
    }

    const uint32_t base = layer_index * g_dynamic_arena.n_expert;
    for (uint32_t t = 0; t < n_tokens; t++) {
        const uint32_t row = t * top;
        double sum = 0.0;
        for (uint32_t k = 0; k < top; k++) {
            const int32_t expert = selected[row + k];
            const float weight = weights[row + k];
            if (expert < 0 || (uint32_t)expert >= g_dynamic_arena.n_expert ||
                !isfinite(weight) || weight <= 0.0f) {
                continue;
            }
            sum += (double)weight;
        }
        if (sum <= 0.0) continue;
        std::vector<std::pair<uint32_t, double>> &pending =
            observer.pending[t];
        try {
            for (uint32_t k = 0; k < top; k++) {
                const int32_t expert = selected[row + k];
                const float weight = weights[row + k];
                if (expert < 0 ||
                    (uint32_t)expert >= g_dynamic_arena.n_expert ||
                    !isfinite(weight) || weight <= 0.0f) {
                    continue;
                }
                pending.push_back({
                    base + (uint32_t)expert,
                    (double)weight / sum
                });
                observer.observed_slots++;
            }
        } catch (...) {
            fprintf(stderr,
                    "ds4: [reap-mass] pending append failed; observer disabled\n");
            cuda_reap_mass_observer_release(0);
            return;
        }
    }
    observer.last_layer = layer_index;
}

static int cuda_dynamic_arena_carry_mode(void) {
    if (cuda_q1_0_exclusive_arena_active()) {
        return 1;
    }
    const char *value =
        getenv("DS4_CUDA_DYNAMIC_ARENA_CARRY_ACROSS_REQUESTS");
    if (!value || !value[0]) return -1;
    if (strcmp(value, "0") == 0) return 0;
    if (strcmp(value, "1") == 0) return 1;
    static int warned = 0;
    if (!warned) {
        fprintf(stderr,
                "ds4: [arena-carry] invalid value '%s'; control disabled\n",
                value);
        warned = 1;
    }
    return -1;
}

static uint32_t cuda_dynamic_arena_active_count(void) {
    uint32_t resident = 0;
    for (uint32_t entry = 0; entry < g_dynamic_arena.active.size(); entry++) {
        const uint32_t layer = entry / g_dynamic_arena.n_expert;
        const uint32_t expert = entry % g_dynamic_arena.n_expert;
        if (cuda_dynamic_arena_binding_valid(
                g_dynamic_arena,
                g_dynamic_arena.active[entry], layer, expert,
                g_dynamic_arena.snapshot_generation,
                DS4_GPU_ARENA_READY)) {
            resident++;
        }
    }
    return resident;
}

extern "C" void ds4_gpu_dynamic_arena_request_begin(void) {
    /* Drain prior-request SSD work before advancing the authoritative request
     * epoch. OFF is a true no-op. */
    cuda_q1_0_ssd_wrap_flush();
    if (g_cuda_request_epoch != UINT64_MAX) {
        g_cuda_request_epoch++;
    }
    cuda_expert_recovery_trace_request_begin();
    cuda_moe_tiering_request_boundary_reset();
    cuda_prefill_mass_observer_reset();
    if (cuda_q1_0_exclusive_arena_active()) {
        cuda_reap_mass_observer_release(1);
    } else {
        cuda_reap_mass_observer_reset();
    }
    const int mode = cuda_dynamic_arena_carry_mode();
    if (mode < 0 || !g_dynamic_arena.host_base) return;

    const uint64_t request = ++g_dynamic_arena.request_sequence;
    if (g_dynamic_arena.snapshot_generation == 0) {
        g_dynamic_arena.hits_disabled = 0;
        fprintf(stderr,
                "ds4: [arena-carry] request=%llu mode=prime snapshot=0 resident=0 lookup=enabled observer=learning\n",
                (unsigned long long)request);
        return;
    }

    cuda_dynamic_arena_observer_release();
    g_dynamic_arena.hits_disabled = mode == 0;
    const uint32_t resident = cuda_dynamic_arena_active_count();
    fprintf(stderr,
            "ds4: [arena-carry] request=%llu mode=%s snapshot=%llu resident=%u lookup=%s observer=frozen\n",
            (unsigned long long)request,
            mode == 0 ? "drop" : "keep",
            (unsigned long long)g_dynamic_arena.snapshot_generation,
            resident,
            mode == 0 ? "disabled" : "enabled");
}

extern "C" void ds4_gpu_dynamic_arena_observer_reset(void) {
    if (cuda_q1_0_exclusive_arena_active()) {
        cuda_prefill_mass_observer_release(1);
        cuda_dynamic_arena_observer_release();
        cuda_reap_mass_observer_release(1);
        return;
    }
    cuda_prefill_mass_observer_finalize();
    const uint32_t window = cuda_dynamic_arena_observer_window();
    const uint32_t min_hits = cuda_dynamic_arena_observer_min_hits();
    const uint32_t grow_interval =
        cuda_dynamic_arena_observer_grow_interval();
    cuda_dynamic_arena_observer_release();
    if (g_reap_mass_observer.wrap_requested) return;
    if (cuda_dynamic_arena_carry_mode() >= 0 &&
        g_dynamic_arena.snapshot_generation != 0) {
        return;
    }
    if (window == 0 || !g_dynamic_arena.host_base ||
        g_dynamic_arena.n_layer <= 3 || g_dynamic_arena.n_expert == 0) {
        return;
    }
    const size_t entry_count =
        (size_t)g_dynamic_arena.n_layer * g_dynamic_arena.n_expert;
    try {
        g_dynamic_arena_observer.target.assign(entry_count, 0);
        g_dynamic_arena_observer.counts.assign(entry_count, 0);
    } catch (...) {
        fprintf(stderr,
                "ds4: [arena-observe] metadata allocation failed; policy disabled\n");
        return;
    }
    g_dynamic_arena_observer.window = window;
    g_dynamic_arena_observer.min_hits = min_hits;
    g_dynamic_arena_observer.grow_interval = grow_interval;
    g_dynamic_arena_observer.enabled = 1;
    fprintf(stderr,
            "ds4: [arena-observe] armed window=%u min_hits=%u grow_interval=%u layers=3..%u router=unbiased residency-only\n",
            window, min_hits, grow_interval,
            g_dynamic_arena.n_layer - 1u);
}

static void cuda_dynamic_arena_observe_selected(
        uint32_t layer_index,
        uint32_t n_tokens,
        const int32_t *selected,
        uint32_t selected_count) {
    cuda_dynamic_arena_observer &observer = g_dynamic_arena_observer;
    if (!observer.enabled || observer.settled || n_tokens != 1 ||
        !selected || selected_count == 0 ||
        layer_index < 3 || layer_index >= g_dynamic_arena.n_layer ||
        !cuda_primary_dynamic_arena_layer_allowed(layer_index)) {
        return;
    }

    if (observer.have_last_layer && layer_index <= observer.last_layer) {
        observer.completed_tokens++;
        const int initial_due = !observer.initial_published &&
            observer.completed_tokens >= observer.window;
        const int growth_due = observer.initial_published &&
            observer.grow_interval != 0 &&
            observer.completed_tokens - observer.last_publish_tokens >=
                observer.grow_interval;
        if (initial_due || growth_due) {
            if (growth_due &&
                cuda_dynamic_arena_observer_new_eligible() == 0) {
                observer.last_publish_tokens = observer.completed_tokens;
                fprintf(stderr,
                        "ds4: [arena-observe] grow skipped tokens=%u resident=%u reason=no-new-eligible\n",
                        observer.completed_tokens,
                        observer.published_entries);
            } else {
                const int published =
                    cuda_dynamic_arena_observer_publish();
                if (published > 0) {
                    observer.initial_published = 1;
                    observer.last_publish_tokens = observer.completed_tokens;
                    observer.published_entries = observer.unique_entries;
                    if (growth_due) observer.growth_publications++;
                    observer.settled = observer.grow_interval == 0 ||
                        observer.published_entries >=
                            g_dynamic_arena.slots.size();
                } else {
                    observer.settled = 1;
                    cuda_dynamic_arena_observer_discard_preloads();
                }
                fprintf(stderr,
                        "ds4: [arena-observe] %s tokens=%u resident=%u growths=%u result=%s%s\n",
                        initial_due ? "window complete" : "grow complete",
                        observer.completed_tokens, observer.unique_entries,
                        observer.growth_publications,
                        published > 0 ? "published" : "fallback",
                        observer.settled ? " settled" : "");
            }
            if (observer.settled) return;
        }
    }

    const uint32_t base = layer_index * g_dynamic_arena.n_expert;
    for (uint32_t i = 0; i < selected_count; i++) {
        const int32_t expert = selected[i];
        if (expert < 0 || (uint32_t)expert >= g_dynamic_arena.n_expert) {
            continue;
        }
        uint8_t &entry = observer.target[base + (uint32_t)expert];
        uint16_t &count = observer.counts[base + (uint32_t)expert];
        if (count != UINT16_MAX) count++;
        if (!entry) {
            entry = 1;
            observer.unique_entries++;
        }
    }
    observer.last_layer = layer_index;
    observer.have_last_layer = 1;
}

extern "C" ds4_gpu_async_read *ds4_gpu_async_read_ring_alloc(
        uint64_t bytes,
        uint32_t slots) {
    if (bytes == 0) bytes = 1;
    if (slots == 0 || slots > 64u || bytes > UINT64_MAX / slots) return NULL;
    ds4_gpu_async_read *r = (ds4_gpu_async_read *)calloc(1, sizeof(*r));
    if (!r) return NULL;
    r->bytes = bytes;
    r->slots = slots;
    r->pending_bytes = (uint64_t *)calloc(slots, sizeof(*r->pending_bytes));
    r->ready = (cudaEvent_t *)calloc(slots, sizeof(*r->ready));
    r->done = (cudaEvent_t *)calloc(slots, sizeof(*r->done));
    r->pending = (int *)calloc(slots, sizeof(*r->pending));
    int ok = r->pending_bytes && r->ready && r->done && r->pending;
    if (ok) {
        ok = cuda_ok(cudaHostAlloc(&r->host, (size_t)(bytes * slots), cudaHostAllocDefault),
                     "async read host alloc");
    }
    if (ok) {
        ok = cuda_ok(cudaStreamCreateWithFlags(&r->stream, cudaStreamNonBlocking),
                     "async read stream create");
    }
    for (uint32_t i = 0; ok && i < slots; i++) {
        ok = cuda_ok(cudaEventCreateWithFlags(&r->ready[i], cudaEventDisableTiming),
                     "async read ready event create") &&
             cuda_ok(cudaEventCreateWithFlags(&r->done[i], cudaEventDisableTiming),
                     "async read done event create");
    }
    if (!ok) {
        ds4_gpu_async_read_free(r);
        return NULL;
    }
    return r;
}

extern "C" ds4_gpu_async_read *ds4_gpu_async_read_alloc(uint64_t bytes) {
    return ds4_gpu_async_read_ring_alloc(bytes, 1);
}

extern "C" void ds4_gpu_async_read_free(ds4_gpu_async_read *readback) {
    if (!readback) return;
    /* Ordered readbacks use stream 0. Fence it even if enqueue failed before
     * pending[] could be published. This is teardown-only. */
    (void)cudaStreamSynchronize(0);
    if (readback->stream) (void)cudaStreamSynchronize(readback->stream);
    for (uint32_t i = 0; i < readback->slots; i++) {
        if (readback->pending && readback->pending[i] &&
            readback->done && readback->done[i]) {
            (void)cudaEventSynchronize(readback->done[i]);
            readback->pending[i] = 0;
        }
    }
    for (uint32_t i = 0; i < readback->slots; i++) {
        if (readback->done && readback->done[i]) (void)cudaEventDestroy(readback->done[i]);
        if (readback->ready && readback->ready[i]) (void)cudaEventDestroy(readback->ready[i]);
    }
    if (readback->stream) (void)cudaStreamDestroy(readback->stream);
    if (readback->host) (void)cudaFreeHost(readback->host);
    free(readback->pending_bytes);
    free(readback->ready);
    free(readback->done);
    free(readback->pending);
    free(readback);
}

extern "C" void *ds4_gpu_async_read_host_slot(
        ds4_gpu_async_read *readback,
        uint32_t slot) {
    if (!readback || slot >= readback->slots) return NULL;
    return (char *)readback->host + (uint64_t)slot * readback->bytes;
}

extern "C" void *ds4_gpu_async_read_host(ds4_gpu_async_read *readback) {
    return ds4_gpu_async_read_host_slot(readback, 0);
}

extern "C" int ds4_gpu_async_read_ready_slot(
        ds4_gpu_async_read *readback,
        uint32_t slot) {
    if (!readback || slot >= readback->slots || !readback->pending[slot]) return 0;
    cudaError_t err = cudaEventQuery(readback->done[slot]);
    if (err == cudaSuccess) {
        readback->pending[slot] = 0;
        return 1;
    }
    if (err == cudaErrorNotReady) return 0;
    readback->pending[slot] = 0;
    (void)cuda_ok(err, "async read query");
    return -1;
}

extern "C" int ds4_gpu_async_read_ready(ds4_gpu_async_read *readback) {
    return ds4_gpu_async_read_ready_slot(readback, 0);
}

extern "C" int ds4_gpu_async_read_wait_slot(
        ds4_gpu_async_read *readback,
        uint32_t slot) {
    if (!readback || slot >= readback->slots || !readback->pending[slot]) return 0;
    const int ok = cuda_ok(cudaEventSynchronize(readback->done[slot]), "async read wait");
    readback->pending[slot] = 0;
    return ok;
}

extern "C" int ds4_gpu_async_read_wait(ds4_gpu_async_read *readback) {
    return ds4_gpu_async_read_wait_slot(readback, 0);
}

extern "C" int ds4_gpu_tensor_read_async_slot(
        ds4_gpu_async_read *readback,
        uint32_t slot,
        const ds4_gpu_tensor *tensor,
        uint64_t offset,
        uint64_t bytes) {
    if (!readback || !tensor || offset > tensor->bytes ||
        slot >= readback->slots || bytes > tensor->bytes - offset ||
        bytes > readback->bytes) {
        return 0;
    }
    if (readback->pending[slot]) {
        const int ready = ds4_gpu_async_read_ready_slot(readback, slot);
        if (ready <= 0) return 0;
    }
    readback->pending[slot] = 0;
    readback->pending_bytes[slot] = bytes;
    if (bytes == 0) return 1;
    if (!cuda_ok(cudaEventRecord(readback->ready[slot], 0),
                 "async read dependency event record") ||
        !cuda_ok(cudaStreamWaitEvent(readback->stream, readback->ready[slot], 0),
                 "async read stream wait") ||
        !cuda_ok(cudaMemcpyAsync((char *)readback->host + (uint64_t)slot * readback->bytes,
                                 (const char *)tensor->ptr + offset,
                                 (size_t)bytes,
                                 cudaMemcpyDeviceToHost,
                                 readback->stream),
                 "async tensor read copy")) {
        return 0;
    }
    if (!cuda_ok(cudaEventRecord(readback->done[slot], readback->stream),
                 "async read done event record")) {
        (void)cudaStreamSynchronize(readback->stream);
        return 0;
    }
    readback->pending[slot] = 1;
    return 1;
}

extern "C" int ds4_gpu_tensor_read_async(ds4_gpu_async_read *readback,
                                          const ds4_gpu_tensor *tensor,
                                          uint64_t offset,
                                          uint64_t bytes) {
    return ds4_gpu_tensor_read_async_slot(readback, 0, tensor, offset, bytes);
}

extern "C" int ds4_gpu_tensor_read_async_ordered_slot(
        ds4_gpu_async_read *readback,
        uint32_t slot,
        const ds4_gpu_tensor *tensor,
        uint64_t offset,
        uint64_t bytes) {
    if (!readback || !tensor || offset > tensor->bytes ||
        slot >= readback->slots || bytes > tensor->bytes - offset ||
        bytes > readback->bytes) {
        return 0;
    }
    if (readback->pending[slot]) {
        const int ready = ds4_gpu_async_read_ready_slot(readback, slot);
        if (ready <= 0) return 0;
    }
    readback->pending[slot] = 0;
    readback->pending_bytes[slot] = bytes;
    if (bytes == 0) return 1;
    if (!cuda_ok(cudaMemcpyAsync(
                     (char *)readback->host + (uint64_t)slot * readback->bytes,
                     (const char *)tensor->ptr + offset,
                     (size_t)bytes,
                     cudaMemcpyDeviceToHost,
                     0),
                 "ordered async tensor read copy")) {
        return 0;
    }
    if (!cuda_ok(cudaEventRecord(readback->done[slot], 0),
                 "ordered async read done event record")) {
        (void)cudaStreamSynchronize(0);
        return 0;
    }
    readback->pending[slot] = 1;
    return 1;
}

static int cuda_spex_key_equal(
        const ds4_gpu_spex_key *a,
        const ds4_gpu_spex_key *b) {
    return a && b &&
           a->epoch == b->epoch &&
           a->decode_seq == b->decode_seq &&
           a->source_layer == b->source_layer &&
           a->target_layer == b->target_layer;
}

static char *cuda_spex_host_gate(ds4_gpu_spex_queue *q, uint32_t slot) {
    return q->host_gate + (uint64_t)slot * q->expert_cap * q->gate_expert_bytes;
}

static char *cuda_spex_host_up(ds4_gpu_spex_queue *q, uint32_t slot) {
    return q->host_up + (uint64_t)slot * q->expert_cap * q->gate_expert_bytes;
}

static char *cuda_spex_host_down(ds4_gpu_spex_queue *q, uint32_t slot) {
    return q->host_down + (uint64_t)slot * q->expert_cap * q->down_expert_bytes;
}

static char *cuda_spex_device_gate(ds4_gpu_spex_queue *q, uint32_t slot) {
    return q->device_gate + (uint64_t)slot * q->expert_cap * q->gate_expert_bytes;
}

static char *cuda_spex_device_up(ds4_gpu_spex_queue *q, uint32_t slot) {
    return q->device_up + (uint64_t)slot * q->expert_cap * q->gate_expert_bytes;
}

static char *cuda_spex_device_down(ds4_gpu_spex_queue *q, uint32_t slot) {
    return q->device_down + (uint64_t)slot * q->expert_cap * q->down_expert_bytes;
}

static int cuda_spex_prefetch_read_job(
        ds4_gpu_spex_queue *q,
        uint32_t slot,
        const ds4_gpu_spex_job *job,
        uint64_t *bytes_read) {
    uint64_t read_total = 0;
    for (uint32_t i = 0; i < job->expert_count; i++) {
        const uint64_t expert = job->expert_ids[i];
        const uint64_t gate_src = job->gate_offset + expert * q->gate_expert_bytes;
        const uint64_t up_src = job->up_offset + expert * q->gate_expert_bytes;
        const uint64_t down_src = job->down_offset + expert * q->down_expert_bytes;
        char *hg = cuda_spex_host_gate(q, slot) + (uint64_t)i * q->gate_expert_bytes;
        char *hu = cuda_spex_host_up(q, slot) + (uint64_t)i * q->gate_expert_bytes;
        char *hd = cuda_spex_host_down(q, slot) + (uint64_t)i * q->down_expert_bytes;
        if (os_pread(&q->file, hg, q->gate_expert_bytes, gate_src) !=
                (int64_t)q->gate_expert_bytes ||
            os_pread(&q->file, hu, q->gate_expert_bytes, up_src) !=
                (int64_t)q->gate_expert_bytes ||
            os_pread(&q->file, hd, q->down_expert_bytes, down_src) !=
                (int64_t)q->down_expert_bytes) {
            return 0;
        }
        read_total += q->gate_expert_bytes * 2u + q->down_expert_bytes;
    }
    const uint64_t gate_bytes = (uint64_t)job->expert_count * q->gate_expert_bytes;
    const uint64_t down_bytes = (uint64_t)job->expert_count * q->down_expert_bytes;
    int enqueued = 1;
    if (cudaMemcpyAsync(cuda_spex_device_gate(q, slot), cuda_spex_host_gate(q, slot),
                        (size_t)gate_bytes, cudaMemcpyHostToDevice, q->upload_stream) != cudaSuccess) {
        enqueued = 0;
    }
    if (cudaMemcpyAsync(cuda_spex_device_up(q, slot), cuda_spex_host_up(q, slot),
                        (size_t)gate_bytes, cudaMemcpyHostToDevice, q->upload_stream) != cudaSuccess) {
        enqueued = 0;
    }
    if (cudaMemcpyAsync(cuda_spex_device_down(q, slot), cuda_spex_host_down(q, slot),
                        (size_t)down_bytes, cudaMemcpyHostToDevice, q->upload_stream) != cudaSuccess) {
        enqueued = 0;
    }
    const cudaError_t fenced = cudaStreamSynchronize(q->upload_stream);
    if (!enqueued || fenced != cudaSuccess) {
        (void)cudaGetLastError();
        return fenced == cudaSuccess ? 0 : -1;
    }
    if (bytes_read) *bytes_read = read_total;
    return 1;
}

static void *cuda_spex_prefetch_worker(void *arg) {
    ds4_gpu_spex_queue *q = (ds4_gpu_spex_queue *)arg;
    for (;;) {
        uint32_t selected = UINT32_MAX;
        ds4_gpu_spex_job job;
        os_mutex_lock(&q->mutex);
        for (;;) {
            if (q->stop || q->disabled) break;
            for (uint32_t i = 0; i < q->slots; i++) {
                if (q->slot[i].state == CUDA_SPEX_PREFETCH_QUEUED) {
                    selected = i;
                    q->slot[i].state = CUDA_SPEX_PREFETCH_LOADING;
                    job = q->slot[i].job;
                    break;
                }
            }
            if (selected != UINT32_MAX || q->stop || q->disabled) break;
            (void)os_cond_wait(&q->cond, &q->mutex);
        }
        const int stop = q->stop || q->disabled;
        os_mutex_unlock(&q->mutex);
        if (stop) break;

        uint64_t bytes_read = 0;
        const int read_status = cuda_spex_prefetch_read_job(q, selected, &job, &bytes_read);
        os_mutex_lock(&q->mutex);
        cuda_spex_prefetch_slot *slot = &q->slot[selected];
        if (read_status < 0) {
            q->errors++;
            q->poisoned++;
            q->disabled = 1;
            slot->state = CUDA_SPEX_PREFETCH_RETIRING;
            slot->discard = 1;
        } else if (read_status == 0) {
            q->errors++;
            slot->state = CUDA_SPEX_PREFETCH_FREE;
        } else if (slot->discard || job.key.epoch != q->epoch) {
            slot->state = CUDA_SPEX_PREFETCH_FREE;
        } else {
            q->loaded++;
            q->bytes_read += bytes_read;
            slot->state = CUDA_SPEX_PREFETCH_READY;
        }
        if (read_status >= 0) slot->discard = 0;
        os_cond_broadcast(&q->cond);
        os_mutex_unlock(&q->mutex);
    }
    return NULL;
}

extern "C" ds4_gpu_spex_queue *ds4_gpu_spex_queue_create(
        const os_file_t *model_file,
        uint64_t model_size,
        uint32_t slots,
        uint32_t expert_cap,
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes) {
    if (!model_file || !os_file_valid(model_file) || model_size == 0 ||
        slots == 0 || slots > 8u || expert_cap != 1u ||
        gate_expert_bytes == 0 || down_expert_bytes == 0) return NULL;
    ds4_gpu_spex_queue *q = (ds4_gpu_spex_queue *)calloc(1, sizeof(*q));
    if (!q) return NULL;
    os_file_init(&q->file);
    q->model_size = model_size;
    q->slots = slots;
    q->expert_cap = expert_cap;
    q->gate_expert_bytes = gate_expert_bytes;
    q->down_expert_bytes = down_expert_bytes;
    q->epoch = 1;
    q->slot = (cuda_spex_prefetch_slot *)calloc(slots, sizeof(*q->slot));
    const uint64_t gate_total = (uint64_t)slots * expert_cap * gate_expert_bytes;
    const uint64_t down_total = (uint64_t)slots * expert_cap * down_expert_bytes;
    int ok = q->slot && os_file_dup(&q->file, model_file) == 0;
    if (ok && os_mutex_init(&q->mutex) == 0) q->mutex_ready = 1; else ok = 0;
    if (ok && os_cond_init(&q->cond) == 0) q->cond_ready = 1; else ok = 0;
    if (ok) ok = cuda_ok(cudaHostAlloc(&q->host_gate, (size_t)gate_total, cudaHostAllocDefault), "SPEX prefetch host gate") &&
                 cuda_ok(cudaHostAlloc(&q->host_up, (size_t)gate_total, cudaHostAllocDefault), "SPEX prefetch host up") &&
                 cuda_ok(cudaHostAlloc(&q->host_down, (size_t)down_total, cudaHostAllocDefault), "SPEX prefetch host down") &&
                 cuda_ok(cudaMalloc(&q->device_gate, (size_t)gate_total), "SPEX prefetch device gate") &&
                 cuda_ok(cudaMalloc(&q->device_up, (size_t)gate_total), "SPEX prefetch device up") &&
                 cuda_ok(cudaMalloc(&q->device_down, (size_t)down_total), "SPEX prefetch device down") &&
                 cuda_ok(cudaStreamCreateWithFlags(&q->upload_stream, cudaStreamNonBlocking), "SPEX prefetch stream");
    if (ok && os_thread_create(&q->thread, cuda_spex_prefetch_worker, q) == 0) {
        q->thread_started = 1;
    } else {
        ok = 0;
    }
    if (!ok) {
        ds4_gpu_spex_queue_destroy(q);
        return NULL;
    }
    fprintf(stderr,
            "ds4: SPEX prefetch active k=%u slots=%u %.2f MiB/expert; fallback is nonblocking\n",
            expert_cap, slots,
            (double)(gate_expert_bytes * 2u + down_expert_bytes) / 1048576.0);
    return q;
}

extern "C" void ds4_gpu_spex_queue_reset(
        ds4_gpu_spex_queue *q,
        uint64_t epoch) {
    if (!q || !q->mutex_ready) return;
    os_mutex_lock(&q->mutex);
    q->epoch = epoch ? epoch : q->epoch + 1u;
    for (uint32_t i = 0; i < q->slots; i++) {
        if (q->slot[i].state == CUDA_SPEX_PREFETCH_QUEUED ||
            q->slot[i].state == CUDA_SPEX_PREFETCH_READY) {
            q->slot[i].state = CUDA_SPEX_PREFETCH_FREE;
        } else if (q->slot[i].state == CUDA_SPEX_PREFETCH_LOADING ||
                   q->slot[i].state == CUDA_SPEX_PREFETCH_IN_USE) {
            q->slot[i].discard = 1;
        }
    }
    os_cond_broadcast(&q->cond);
    os_mutex_unlock(&q->mutex);
}

extern "C" int ds4_gpu_spex_queue_submit(
        ds4_gpu_spex_queue *q,
        const ds4_gpu_spex_job *job) {
    if (!q || !job || job->expert_count == 0 ||
        job->expert_count > q->expert_cap || job->key.epoch == 0) return 0;
    for (uint32_t i = 0; i < job->expert_count; i++) {
        if (job->expert_ids[i] >= 256u ||
            !cuda_sparse_bake_expert_retained(
                job->key.target_layer, job->expert_ids[i])) return 0;
    }
    const uint64_t max_expert = job->expert_ids[0];
    if (job->gate_offset > q->model_size || job->up_offset > q->model_size ||
        job->down_offset > q->model_size ||
        (max_expert + 1u) * q->gate_expert_bytes > q->model_size - job->gate_offset ||
        (max_expert + 1u) * q->gate_expert_bytes > q->model_size - job->up_offset ||
        (max_expert + 1u) * q->down_expert_bytes > q->model_size - job->down_offset) return 0;
    os_mutex_lock(&q->mutex);
    if (q->disabled || job->key.epoch != q->epoch) {
        q->dropped++;
        os_mutex_unlock(&q->mutex);
        return 0;
    }
    int selected = -1;
    for (uint32_t i = 0; i < q->slots; i++) {
        if (q->slot[i].state == CUDA_SPEX_PREFETCH_READY &&
            q->slot[i].job.key.decode_seq < job->key.decode_seq) {
            q->slot[i].state = CUDA_SPEX_PREFETCH_FREE;
        }
        if (selected < 0 && q->slot[i].state == CUDA_SPEX_PREFETCH_FREE) selected = (int)i;
    }
    if (selected < 0) {
        q->dropped++;
        os_mutex_unlock(&q->mutex);
        return 0;
    }
    q->slot[(uint32_t)selected].job = *job;
    q->slot[(uint32_t)selected].discard = 0;
    q->slot[(uint32_t)selected].state = CUDA_SPEX_PREFETCH_QUEUED;
    q->submitted++;
    os_cond_signal(&q->cond);
    os_mutex_unlock(&q->mutex);
    return 1;
}

extern "C" void ds4_gpu_spex_queue_cancel(
        ds4_gpu_spex_queue *q,
        const ds4_gpu_spex_key *key) {
    if (!q || !key || !q->mutex_ready) return;
    os_mutex_lock(&q->mutex);
    for (uint32_t i = 0; i < q->slots; i++) {
        cuda_spex_prefetch_slot *slot = &q->slot[i];
        if (!cuda_spex_key_equal(&slot->job.key, key)) continue;
        if (slot->state == CUDA_SPEX_PREFETCH_LOADING ||
            slot->state == CUDA_SPEX_PREFETCH_IN_USE) {
            slot->discard = 1;
        } else if (slot->state == CUDA_SPEX_PREFETCH_QUEUED ||
                   slot->state == CUDA_SPEX_PREFETCH_READY) {
            slot->state = CUDA_SPEX_PREFETCH_FREE;
            slot->discard = 0;
        }
        q->canceled++;
        os_cond_signal(&q->cond);
        break;
    }
    os_mutex_unlock(&q->mutex);
}

extern "C" void ds4_gpu_spex_queue_destroy(ds4_gpu_spex_queue *q) {
    if (!q) return;
    if (q->mutex_ready) {
        os_mutex_lock(&q->mutex);
        q->stop = 1;
        if (q->cond_ready) os_cond_broadcast(&q->cond);
        os_mutex_unlock(&q->mutex);
    }
    if (q->thread_started) os_thread_join(q->thread);
    if (q->upload_stream) (void)cudaStreamSynchronize(q->upload_stream);
    (void)cudaDeviceSynchronize();
    fprintf(stderr,
            "ds4: [spex-prefetch] final submitted=%llu dropped=%llu loaded=%llu matched=%llu consumed=%llu no_hits=%llu late=%llu canceled=%llu poisoned=%llu errors=%llu disabled=%u bytes_read=%llu bytes_used=%llu\n",
            (unsigned long long)q->submitted,
            (unsigned long long)q->dropped,
            (unsigned long long)q->loaded,
            (unsigned long long)q->matched,
            (unsigned long long)q->hits,
            (unsigned long long)q->no_hits,
            (unsigned long long)q->late,
            (unsigned long long)q->canceled,
            (unsigned long long)q->poisoned,
            (unsigned long long)q->errors,
            q->disabled ? 1u : 0u,
            (unsigned long long)q->bytes_read,
            (unsigned long long)q->bytes_used);
    if (q->upload_stream) (void)cudaStreamDestroy(q->upload_stream);
    if (q->device_gate) (void)cudaFree(q->device_gate);
    if (q->device_up) (void)cudaFree(q->device_up);
    if (q->device_down) (void)cudaFree(q->device_down);
    if (q->host_gate) (void)cudaFreeHost(q->host_gate);
    if (q->host_up) (void)cudaFreeHost(q->host_up);
    if (q->host_down) (void)cudaFreeHost(q->host_down);
    os_file_close(&q->file);
    if (q->cond_ready) os_cond_destroy(&q->cond);
    if (q->mutex_ready) os_mutex_destroy(&q->mutex);
    free(q->slot);
    free(q);
}

static int cuda_spex_prefetch_claim(
        ds4_gpu_spex_queue *q,
        const ds4_gpu_spex_key *key,
        uint64_t gate_offset,
        uint64_t up_offset,
        uint64_t down_offset,
        const std::vector<int32_t> &compact,
        int *out_slot,
        uint32_t *out_prediction,
        uint32_t *out_compact) {
    if (!q || !key || !out_slot || !out_prediction || !out_compact) return 0;
    os_mutex_lock(&q->mutex);
    if (q->disabled) {
        os_mutex_unlock(&q->mutex);
        return 0;
    }
    for (uint32_t i = 0; i < q->slots; i++) {
        cuda_spex_prefetch_slot *slot = &q->slot[i];
        if (!cuda_spex_key_equal(&slot->job.key, key)) continue;
        if (slot->job.gate_offset != gate_offset ||
            slot->job.up_offset != up_offset ||
            slot->job.down_offset != down_offset) {
            if (slot->state == CUDA_SPEX_PREFETCH_LOADING ||
                slot->state == CUDA_SPEX_PREFETCH_IN_USE) {
                slot->discard = 1;
            } else {
                slot->state = CUDA_SPEX_PREFETCH_FREE;
            }
            q->errors++;
            os_mutex_unlock(&q->mutex);
            return 0;
        }
        if (slot->state == CUDA_SPEX_PREFETCH_QUEUED) {
            slot->state = CUDA_SPEX_PREFETCH_FREE;
            q->late++;
            os_mutex_unlock(&q->mutex);
            return 0;
        }
        if (slot->state == CUDA_SPEX_PREFETCH_LOADING) {
            slot->discard = 1;
            q->late++;
            os_mutex_unlock(&q->mutex);
            return 0;
        }
        if (slot->state != CUDA_SPEX_PREFETCH_READY) {
            os_mutex_unlock(&q->mutex);
            return 0;
        }
        for (uint32_t p = 0; p < slot->job.expert_count; p++) {
            for (uint32_t c = 0; c < compact.size(); c++) {
                if ((int32_t)slot->job.expert_ids[p] == compact[c]) {
                    slot->state = CUDA_SPEX_PREFETCH_IN_USE;
                    q->matched++;
                    *out_slot = (int)i;
                    *out_prediction = p;
                    *out_compact = c;
                    os_mutex_unlock(&q->mutex);
                    return 1;
                }
            }
        }
        slot->state = CUDA_SPEX_PREFETCH_FREE;
        q->no_hits++;
        os_cond_signal(&q->cond);
        os_mutex_unlock(&q->mutex);
        return 0;
    }
    os_mutex_unlock(&q->mutex);
    return 0;
}

static int cuda_spex_prefetch_copy_to_compact(
        ds4_gpu_spex_queue *q,
        uint32_t slot,
        uint32_t prediction,
        char *gate_dst,
        char *up_dst,
        char *down_dst) {
    if (!q || slot >= q->slots || prediction >= q->expert_cap ||
        !gate_dst || !up_dst || !down_dst) return 0;
    const uint64_t gate_src = ((uint64_t)slot * q->expert_cap + prediction) *
        q->gate_expert_bytes;
    const uint64_t down_src = ((uint64_t)slot * q->expert_cap + prediction) *
        q->down_expert_bytes;
    return cudaMemcpyAsync(gate_dst, q->device_gate + gate_src,
                           (size_t)q->gate_expert_bytes, cudaMemcpyDeviceToDevice,
                           g_model_upload_stream) == cudaSuccess &&
           cudaMemcpyAsync(up_dst, q->device_up + gate_src,
                           (size_t)q->gate_expert_bytes, cudaMemcpyDeviceToDevice,
                           g_model_upload_stream) == cudaSuccess &&
           cudaMemcpyAsync(down_dst, q->device_down + down_src,
                           (size_t)q->down_expert_bytes, cudaMemcpyDeviceToDevice,
                           g_model_upload_stream) == cudaSuccess;
}

static void cuda_spex_prefetch_release(
        ds4_gpu_spex_queue *q,
        int slot,
        int reusable,
        int consumed) {
    if (!q || slot < 0 || (uint32_t)slot >= q->slots) return;
    os_mutex_lock(&q->mutex);
    if (reusable && consumed &&
        q->slot[(uint32_t)slot].state == CUDA_SPEX_PREFETCH_IN_USE) {
        q->hits++;
        q->bytes_used += q->gate_expert_bytes * 2u + q->down_expert_bytes;
    }
    if (!reusable) {
        q->errors++;
        q->poisoned++;
        q->disabled = 1;
    }
    q->slot[(uint32_t)slot].state = reusable
        ? CUDA_SPEX_PREFETCH_FREE : CUDA_SPEX_PREFETCH_RETIRING;
    q->slot[(uint32_t)slot].discard = reusable ? 0 : 1;
    if (reusable) os_cond_signal(&q->cond);
    else os_cond_broadcast(&q->cond);
    os_mutex_unlock(&q->mutex);
}

extern "C" int ds4_gpu_tensor_copy(ds4_gpu_tensor *dst, uint64_t dst_offset,
                                     const ds4_gpu_tensor *src, uint64_t src_offset,
                                     uint64_t bytes) {
    if (!dst || !src || dst_offset > dst->bytes || src_offset > src->bytes ||
        bytes > dst->bytes - dst_offset || bytes > src->bytes - src_offset) {
        return 0;
    }
    if (bytes == 0) return 1;
    return cuda_ok(cudaMemcpy((char *)dst->ptr + dst_offset,
                              (const char *)src->ptr + src_offset,
                              (size_t)bytes,
                              cudaMemcpyDeviceToDevice),
                   "tensor copy");
}

extern "C" int ds4_gpu_begin_commands(void) { return 1; }
extern "C" int ds4_gpu_flush_commands(void) { return cuda_ok(cudaDeviceSynchronize(), "flush"); }
extern "C" int ds4_gpu_end_commands(void) { return cuda_ok(cudaDeviceSynchronize(), "end commands"); }
extern "C" int ds4_gpu_synchronize(void) { return cuda_ok(cudaDeviceSynchronize(), "synchronize"); }

extern "C" int ds4_gpu_set_model_map(const void *model_map, uint64_t model_size) {
    if (!model_map || model_size == 0) return 0;
    if (g_model_host_base == model_map && g_model_registered_size == model_size) return 1;
    cuda_moe_gather_release();
    cuda_moe_expert_cache_release();
    ds4_gpu_dynamic_arena_release();
    cuda_reap_router_bias_release_all();
    cuda_model_range_release_all();
    cuda_q8_f16_cache_release_all();
    cuda_embed_row_stage_release();
    g_q8_f16_disabled_after_oom = 0;
    g_q8_f16_budget_notice_printed = 0;
    for (const cuda_q8_f32_range &r : g_q8_f32_ranges) {
        (void)cudaFree(r.device_ptr);
    }
    g_q8_f32_ranges.clear();
    g_q8_f32_by_offset.clear();
    g_q8_f32_bytes = 0;
    if (g_model_device_owned && g_model_device_base) {
        (void)cudaFree((void *)g_model_device_base);
        g_model_device_owned = 0;
    }
    if (g_model_window_registered && g_model_host_base) {
        (void)cudaHostUnregister((void *)g_model_host_base);
        g_model_registered = 0;
        g_model_window_registered = 0;
        g_model_window_bytes = 0;
    }
    g_model_host_base = model_map;
    g_model_device_base = (const char *)model_map;
    g_model_registered_size = model_size;
    if (!cuda_expert_recovery_trace_bind_model_map(model_map, model_size)) {
        return 0;
    }
    g_model_range_mapping_supported = 1;
    g_model_hmm_direct = 0;
    g_model_cache_full = 0;

    const char *copy_env = getenv("DS4_CUDA_COPY_MODEL");
    if (g_sparse_bake_active && copy_env && copy_env[0]) {
        fprintf(stderr,
                "ds4: sparse bake rejects DS4_CUDA_COPY_MODEL full-range copy\n");
        return 0;
    }
    if (copy_env && copy_env[0]) {
        void *dev = NULL;
        const double t0 = clock() / (double)CLOCKS_PER_SEC;
        cudaError_t err = cudaMalloc(&dev, (size_t)model_size);
        if (err == cudaSuccess) {
            fprintf(stderr, "ds4: CUDA copying %.2f GiB model to device memory\n",
                    (double)model_size / 1073741824.0);
            err = cudaMemcpy(dev, model_map, (size_t)model_size, cudaMemcpyHostToDevice);
            if (err == cudaSuccess) {
                g_model_device_base = (const char *)dev;
                g_model_device_owned = 1;
                const double t1 = clock() / (double)CLOCKS_PER_SEC;
                fprintf(stderr, "ds4: CUDA model copy complete in %.3fs\n", t1 - t0);
                return 1;
            }
            fprintf(stderr, "ds4: CUDA model copy failed: %s\n", cudaGetErrorString(err));
            (void)cudaFree(dev);
            (void)cudaGetLastError();
        } else {
            cuda_log_full_model_alloc_failure(model_size, err, "explicit-copy");
            (void)cudaGetLastError();
        }
    }

    /* Whole-model host-register, both platforms. Budget-gated: never attempt to
     * pin the entire ~80 GiB image (exceeds the WDDM ~24 GiB cap and would fail).
     * When it doesn't fit, leave g_model_range_mapping_supported = 1 so the
     * per-range register / fd-cache / chunked path handles weights. Previously
     * this whole branch was #ifndef _WIN32 with the Windows side setting
     * g_model_range_mapping_supported = 0 (disabling zero-copy entirely). */
    /* Register ONE contiguous host window (up to the WDDM host-pin budget) and
     * serve every weight whose [offset, offset+bytes) is inside it via a device
     * pointer + offset (zero-copy, ~24 GiB/s). This replaces per-tensor-span
     * cudaHostRegister, which fails on Windows: adjacent tensor spans share a
     * boundary page, so page-align-up(prev)+page-align-down(next) both claim it
     * -> cudaErrorHostMemoryAlreadyRegistered. One contiguous window has no such
     * shared-page conflict. Weights beyond the window fall through to fd-cache/copy. */
    const char *dynamic_arena_env = getenv("DS4_CUDA_DYNAMIC_ARENA_GB");
    const int dynamic_arena_requested =
        dynamic_arena_env && dynamic_arena_env[0] && atof(dynamic_arena_env) > 0.0;
    if (!dynamic_arena_requested && !g_sparse_bake_active) {
        uint64_t window = model_size;
        const uint64_t budget = cuda_host_register_budget_bytes();
        if (window > budget) window = budget;
        window &= ~(uint64_t)(cuda_page_size() - 1u);
        if (window > 0) {
            cudaError_t err = cudaHostRegister((void *)model_map, (size_t)window,
                                               cudaHostRegisterMapped | cudaHostRegisterReadOnly);
            if (err == cudaSuccess) {
                void *dev = NULL;
                err = cudaHostGetDevicePointer(&dev, (void *)model_map, 0);
                if (err == cudaSuccess && dev) {
                    g_model_device_base = (const char *)dev;
                    g_model_window_bytes = window;
                    g_model_window_registered = 1;
                    if (window >= model_size) g_model_registered = 1; /* whole model resident */
                    fprintf(stderr, "ds4: CUDA registered %.2f GiB contiguous host window (of %.2f GiB model) for zero-copy device access\n",
                            (double)window / 1073741824.0, (double)model_size / 1073741824.0);
                } else {
                    fprintf(stderr, "ds4: CUDA host window devptr lookup failed: %s\n", cudaGetErrorString(err));
                    (void)cudaHostUnregister((void *)model_map);
                    g_model_window_registered = 0;
                    g_model_window_bytes = 0;
                    (void)cudaGetLastError();
                }
            } else {
                fprintf(stderr, "ds4: CUDA host window register skipped: %s\n", cudaGetErrorString(err));
                (void)cudaGetLastError();
            }
        }
    }
#ifdef _WIN32
    g_model_range_mapping_supported = 0; /* per-span register is broken on Win32 (shared boundary pages); rely on the window + fd-cache */
#endif
    return 1;
}

extern "C" int ds4_gpu_set_model_map_range(const void *model_map, uint64_t model_size, uint64_t map_offset, uint64_t map_size) {
    if (!ds4_gpu_set_model_map(model_map, model_size)) return 0;
    if (g_sparse_bake_active &&
        getenv("DS4_CUDA_COPY_MODEL_CHUNKED") != NULL) {
        fprintf(stderr,
                "ds4: sparse bake rejects DS4_CUDA_COPY_MODEL_CHUNKED full-range copy\n");
        return 0;
    }
#ifdef _WIN32
    /* Findings win-copy-chunked-allocates-full-model-in-vram / -skip-conflated:
     * cuda_model_copy_chunked does cudaMalloc(model_size) — an ~80 GiB model
     * cannot fit 12 GiB VRAM (fatal abort), and an intentional env skip also
     * returns 0. Do NOT treat either as fatal. Mirror Linux: full-model chunked
     * copy is opt-in; on skip/failure fall through to the per-range register-mmap
     * / fd-streaming path (now enabled on Windows) so the model still loads. */
    if (getenv("DS4_CUDA_COPY_MODEL_CHUNKED") != NULL) {
        (void)cuda_model_copy_chunked(model_map, model_size, map_offset, map_size);
    }
#else
    if (getenv("DS4_CUDA_COPY_MODEL_CHUNKED") != NULL &&
        !cuda_model_copy_chunked(model_map, model_size, map_offset, map_size)) {
        (void)cuda_model_prefetch_range(model_map, model_size, map_offset, map_size);
    }
#endif
    return 1;
}

extern "C" int ds4_gpu_set_model_file(const os_file_t *file) {
    cuda_moe_expert_cache_invalidate();
    cuda_model_file_clear();
    if (!file || !os_file_valid(file)) return 1;
    if (os_file_dup(&g_model_file, file) != 0) {
        fprintf(stderr, "ds4: CUDA model file duplicate failed: %s\n", strerror(errno));
        return 0;
    }
    g_model_file_valid = 1;
    if (g_model_file_valid) {
        const uint64_t file_size = os_file_size(&g_model_file);
        if (file_size != UINT64_MAX) g_model_file_size = file_size;
        if (cuda_dynamic_arena_wrap_sequential_file()) {
            if (os_file_reopen_read_sequential(
                    &g_model_file_sequential, &g_model_file, 1) != 0) {
                fprintf(stderr,
                        "ds4: CUDA sequential WRAP model-file reopen failed: %s\n",
                        strerror(errno));
                cuda_model_file_clear();
                return 0;
            }
            g_model_file_sequential_valid = 1;
            fprintf(stderr,
                    "ds4: CUDA sequential WRAP model-file source enabled\n");
        }
#if defined(__linux__) && defined(O_DIRECT)
        if (getenv("DS4_CUDA_NO_DIRECT_IO") == NULL) {
            char proc_path[64];
            snprintf(proc_path, sizeof(proc_path), "/proc/self/fd/%d", g_model_file.fd);
            int direct_fd = open(proc_path, O_RDONLY | O_DIRECT);
            if (direct_fd >= 0) {
                g_model_direct_fd = direct_fd;
                struct stat st;
                if (fstat(g_model_file.fd, &st) == 0 && st.st_blksize > 1) {
                    g_model_direct_align = (uint64_t)st.st_blksize;
                }
                if (g_model_direct_align < 512) g_model_direct_align = 512;
                if (getenv("DS4_CUDA_WEIGHT_CACHE_VERBOSE")) {
                    fprintf(stderr, "ds4: CUDA model direct I/O enabled (align=%llu)\n",
                            (unsigned long long)g_model_direct_align);
                }
            } else if (getenv("DS4_CUDA_WEIGHT_CACHE_VERBOSE")) {
                fprintf(stderr, "ds4: CUDA model direct I/O unavailable: %s\n", strerror(errno));
            }
        }
#endif
    }
    return 1;
}

extern "C" int ds4_gpu_cache_model_range(const void *model_map, uint64_t model_size, uint64_t offset, uint64_t bytes, const char *label) {
    if (!model_map || bytes == 0) return 1;
    if (offset > model_size || bytes > model_size - offset) return -1; /* bad metadata: hard error */
    /* NULL = couldn't make this span resident now -> DEFER to on-demand streaming
     * at inference (cuda_model_range_ptr is called again per weight per token). */
    if (!cuda_model_range_ptr(model_map, offset, bytes, label ? label : "model_tensor")) return 0;
    return cuda_model_range_is_cached(model_map, offset, bytes) ? 1 : 0;
}

extern "C" int ds4_gpu_model_range_update(
        const void *model_map,
        uint64_t offset,
        const void *data,
        uint64_t bytes) {
    if (!model_map || !data || bytes == 0) return 0;
    if (offset + bytes < offset) return 0;

    if (cuda_model_range *r = cuda_model_range_find_override(model_map, offset, bytes)) {
        cudaError_t err = cudaMemcpy(r->device_ptr + (offset - r->offset),
                                     data,
                                     (size_t)bytes,
                                     cudaMemcpyHostToDevice);
        if (err != cudaSuccess) {
            fprintf(stderr, "ds4: CUDA model override update failed off=%llu bytes=%llu: %s\n",
                    (unsigned long long)offset,
                    (unsigned long long)bytes,
                    cudaGetErrorString(err));
            (void)cudaGetLastError();
            return 0;
        }
        return 1;
    }

    void *dev = NULL;
    cudaError_t err = cudaMalloc(&dev, (size_t)bytes);
    if (err != cudaSuccess) {
        fprintf(stderr, "ds4: CUDA model override alloc failed off=%llu bytes=%llu: %s\n",
                (unsigned long long)offset,
                (unsigned long long)bytes,
                cudaGetErrorString(err));
        (void)cudaGetLastError();
        return 0;
    }
    err = cudaMemcpy(dev, data, (size_t)bytes, cudaMemcpyHostToDevice);
    if (err != cudaSuccess) {
        fprintf(stderr, "ds4: CUDA model override upload failed off=%llu bytes=%llu: %s\n",
                (unsigned long long)offset,
                (unsigned long long)bytes,
                cudaGetErrorString(err));
        (void)cudaFree(dev);
        (void)cudaGetLastError();
        return 0;
    }

    g_model_ranges.push_back({model_map, offset, bytes, (char *)dev,
                              NULL, NULL, 0,
                              0, 0, 0, 0, 1, 1});
    g_model_range_by_offset[offset] = g_model_ranges.size() - 1u;
    return 2;
}

extern "C" void ds4_gpu_reap_router_bias_reset(void) {
    cuda_reap_router_bias_release_all();
}

extern "C" int ds4_gpu_reap_router_bias_update(
        uint32_t layer_index,
        const float *bias,
        uint32_t count) {
    if (!bias || count != 256u || layer_index > 1024u) return 0;
    if (g_reap_router_bias.size() <= layer_index) {
        try {
            g_reap_router_bias.resize((size_t)layer_index + 1u, NULL);
        } catch (...) {
            return 0;
        }
    }
    float *device_bias = g_reap_router_bias[layer_index];
    const int created = device_bias == NULL;
    if (created) {
        if (!cuda_ok(cudaMalloc((void **)&device_bias,
                                (size_t)count * sizeof(float)),
                     "REAP router bias alloc")) {
            return 0;
        }
        g_reap_router_bias[layer_index] = device_bias;
    }
    if (!cuda_ok(cudaMemcpy(device_bias, bias,
                            (size_t)count * sizeof(float),
                            cudaMemcpyHostToDevice),
                 "REAP router bias upload")) {
        if (created) {
            (void)cudaFree(device_bias);
            g_reap_router_bias[layer_index] = NULL;
        }
        return 0;
    }
    return created ? 2 : 1;
}

extern "C" int ds4_gpu_sparse_bake_set_retained_mask(
        const uint8_t *mask,
        uint32_t layers,
        uint32_t experts,
        uint32_t mask_bytes) {
    if (!mask || layers != 43u || experts != 256u ||
        mask_bytes != sizeof(g_sparse_bake_retained)) return 0;

    uint16_t counts[43u] = {0};
    uint32_t retained_total = 0;
    uint32_t sparse_layers = 0;
    for (uint32_t layer = 0; layer < layers; layer++) {
        for (uint32_t expert = 0; expert < experts; expert++) {
            const uint32_t bit = layer * experts + expert;
            counts[layer] +=
                (mask[bit >> 3] >> (bit & 7u)) & 1u;
        }
        if (counts[layer] < 6u) return 0;
        retained_total += counts[layer];
        if (counts[layer] < experts) sparse_layers++;
    }
    memcpy(g_sparse_bake_retained, mask,
           sizeof(g_sparse_bake_retained));
    memcpy(g_sparse_bake_retained_count, counts,
           sizeof(g_sparse_bake_retained_count));
    g_sparse_bake_active = 1;
    g_sparse_bake_route_calls = 0;
    g_sparse_bake_route_slots = 0;
    g_sparse_bake_route_rejections = 0;
    fprintf(stderr,
            "ds4: [sparse-bake-runtime] result=guards-installed "
            "layers=%u sparse_layers=%u retained=%u rejected=0\n",
            layers, sparse_layers, retained_total);
    return 1;
}

extern "C" int ds4_gpu_set_iq1_s_sidecar(
        const os_file_t *file,
        const void *model_map,
        uint64_t model_size) {
    cuda_iq1_s_sidecar_clear();
    if (!file && !model_map && model_size == 0) return 1;
    if (!file || !os_file_valid(file) || !model_map || model_size == 0) {
        fprintf(stderr, "ds4: CUDA IQ1_S sidecar rejected incomplete source\n");
        return 0;
    }
    if (os_file_dup(&g_iq1_s_sidecar_file, file) != 0) {
        fprintf(stderr, "ds4: CUDA IQ1_S sidecar file duplicate failed: %s\n",
                strerror(errno));
        return 0;
    }
    g_iq1_s_sidecar_file_valid = 1;
    const uint64_t file_size = os_file_size(&g_iq1_s_sidecar_file);
    if (file_size == UINT64_MAX || file_size != model_size) {
        fprintf(stderr,
                "ds4: CUDA IQ1_S sidecar size mismatch: file=%llu map=%llu\n",
                (unsigned long long)file_size,
                (unsigned long long)model_size);
        cuda_iq1_s_sidecar_clear();
        return 0;
    }
    g_iq1_s_sidecar_host_base = model_map;
    g_iq1_s_sidecar_size = model_size;
    fprintf(stderr,
            "ds4: CUDA IQ1_S routed-expert sidecar installed: %.2f GiB\n",
            (double)model_size / 1073741824.0);
    return 1;
}

extern "C" int ds4_gpu_set_q1_0_sidecar(
        const os_file_t *file,
        const void *model_map,
        uint64_t model_size) {
    cuda_q1_0_sidecar_clear();
    if (!file && !model_map && model_size == 0) return 1;
    if (!file || !os_file_valid(file) || !model_map || model_size == 0) {
        fprintf(stderr, "ds4: CUDA Q1_0 sidecar rejected incomplete source\n");
        return 0;
    }
    if (os_file_dup(&g_q1_0_sidecar_file, file) != 0) {
        fprintf(stderr, "ds4: CUDA Q1_0 sidecar file duplicate failed: %s\n",
                strerror(errno));
        return 0;
    }
    g_q1_0_sidecar_file_valid = 1;
    const uint64_t file_size = os_file_size(&g_q1_0_sidecar_file);
    if (file_size == UINT64_MAX || file_size != model_size) {
        fprintf(stderr,
                "ds4: CUDA Q1_0 sidecar size mismatch: file=%llu map=%llu\n",
                (unsigned long long)file_size,
                (unsigned long long)model_size);
        cuda_q1_0_sidecar_clear();
        return 0;
    }
    g_q1_0_sidecar_host_base = model_map;
