    float acc = 0.0f;
    for (uint32_t b = lane; b < midq_blocks; b += 32u) {
        acc += dev_dot_iq1_s_q8_K_block(wr + b, xq + b);
    }
    acc = warp_sum_f32(acc);
    if (lane == 0u) {
        down_out[(uint64_t)pair * out_dim + row] = acc;
    }
}

