__global__ static void moe_gate_up_mid_decode_lut_qwarp32_kernel(
        float *gate_out,
        float *up_out,
        float *mid_out,
        const char *gate_base,
        const char *up_base,
        const cuda_block_q8_K *xq,
        const int32_t *selected,
        const float *weights,
        uint64_t gate_expert_bytes,
        uint64_t gate_row_bytes,
        uint32_t xq_blocks,
        uint32_t expert_mid_dim,
        uint32_t n_expert,
        uint32_t write_aux,
        float clamp) {
    uint32_t lane = threadIdx.x & 7u;
    uint32_t row_lane = threadIdx.x >> 3u;
    uint32_t pair = blockIdx.y;
    uint32_t tok = pair / n_expert;
    uint32_t slot = pair - tok * n_expert;
    int32_t expert_i = selected[(uint64_t)tok * n_expert + slot];
    if (expert_i < 0) expert_i = 0;
    uint32_t expert = (uint32_t)expert_i;
    const cuda_block_q8_K *xqb = xq + (uint64_t)tok * xq_blocks;
    __shared__ cuda_block_q8_K sxq[16];
    __shared__ uint64_t s_iq2_grid[256];
    __shared__ uint8_t s_iq2_signs[128];
    if (xq_blocks <= 16u) {
        for (uint32_t i = threadIdx.x; i < xq_blocks; i += blockDim.x) sxq[i] = xqb[i];
        for (uint32_t i = threadIdx.x; i < 256u; i += blockDim.x) s_iq2_grid[i] = cuda_iq2xxs_grid[i];
        for (uint32_t i = threadIdx.x; i < 128u; i += blockDim.x) s_iq2_signs[i] = cuda_ksigns_iq2xs[i];
        __syncthreads();
        xqb = sxq;
    }
    for (uint32_t rr = 0; rr < 4u; rr++) {
        uint32_t row = blockIdx.x * 128u + row_lane + rr * 32u;
        if (row >= expert_mid_dim) continue;
        const cuda_block_iq2_xxs *gr = (const cuda_block_iq2_xxs *)(gate_base + (uint64_t)expert * gate_expert_bytes + (uint64_t)row * gate_row_bytes);
        const cuda_block_iq2_xxs *ur = (const cuda_block_iq2_xxs *)(up_base + (uint64_t)expert * gate_expert_bytes + (uint64_t)row * gate_row_bytes);
        float gate = 0.0f;
        float up = 0.0f;
        for (uint32_t b = lane; b < xq_blocks; b += 8u) {
            gate += dev_dot_iq2_xxs_q8_K_block_lut(gr + b, xqb + b, s_iq2_grid, s_iq2_signs);
            up += dev_dot_iq2_xxs_q8_K_block_lut(ur + b, xqb + b, s_iq2_grid, s_iq2_signs);
        }
        gate = quarter_warp_sum_f32(gate, lane);
        up = quarter_warp_sum_f32(up, lane);
        if (lane == 0) {
            if (clamp > 1.0e-6f) {
                if (gate > clamp) gate = clamp;
                if (up > clamp) up = clamp;
                if (up < -clamp) up = -clamp;
            }
            const uint64_t off = (uint64_t)pair * expert_mid_dim + row;
            if (write_aux) {
                gate_out[off] = gate;
                up_out[off] = up;
            }
            mid_out[off] = (gate / (1.0f + expf(-gate))) * up * weights[(uint64_t)tok * n_expert + slot];
        }
    }
}

__global__ static void moe_gate_up_mid_decode_ptrs_lut_qwarp32_kernel(
        float *gate_out,
        float *up_out,
        float *mid_out,
        const uint64_t *route_ptrs,
        const cuda_block_q8_K *xq,
        const float *weights,
        uint64_t gate_row_bytes,
        uint32_t xq_blocks,
        uint32_t expert_mid_dim,
        uint32_t n_expert,
        uint32_t write_aux,
        float clamp,
        const uint32_t *route_hit_mask,
        uint32_t select_hits) {
    uint32_t lane = threadIdx.x & 7u;
    uint32_t row_lane = threadIdx.x >> 3u;
    uint32_t slot = blockIdx.y;
    if (route_hit_mask) {
        const uint32_t is_hit = (*route_hit_mask >> slot) & 1u;
        if (is_hit != select_hits) return;
    }
    const cuda_block_q8_K *xqb = xq;
    __shared__ cuda_block_q8_K sxq[16];
    __shared__ uint64_t s_iq2_grid[256];
    __shared__ uint8_t s_iq2_signs[128];
    if (xq_blocks <= 16u) {
        for (uint32_t i = threadIdx.x; i < xq_blocks; i += blockDim.x) sxq[i] = xqb[i];
        for (uint32_t i = threadIdx.x; i < 256u; i += blockDim.x) s_iq2_grid[i] = cuda_iq2xxs_grid[i];
        for (uint32_t i = threadIdx.x; i < 128u; i += blockDim.x) s_iq2_signs[i] = cuda_ksigns_iq2xs[i];
        __syncthreads();
        xqb = sxq;
    }
    const char *gate_ptr = (const char *)(uintptr_t)route_ptrs[slot];
    const char *up_ptr = (const char *)(uintptr_t)route_ptrs[n_expert + slot];
    for (uint32_t rr = 0; rr < 4u; rr++) {
        uint32_t row = blockIdx.x * 128u + row_lane + rr * 32u;
        if (row >= expert_mid_dim) continue;
        const cuda_block_iq2_xxs *gr = (const cuda_block_iq2_xxs *)(gate_ptr + (uint64_t)row * gate_row_bytes);
        const cuda_block_iq2_xxs *ur = (const cuda_block_iq2_xxs *)(up_ptr + (uint64_t)row * gate_row_bytes);
        float gate = 0.0f;
        float up = 0.0f;
        for (uint32_t b = lane; b < xq_blocks; b += 8u) {
            gate += dev_dot_iq2_xxs_q8_K_block_lut(gr + b, xqb + b, s_iq2_grid, s_iq2_signs);
            up += dev_dot_iq2_xxs_q8_K_block_lut(ur + b, xqb + b, s_iq2_grid, s_iq2_signs);
        }
        gate = quarter_warp_sum_f32(gate, lane);
        up = quarter_warp_sum_f32(up, lane);
        if (lane == 0) {
            if (clamp > 1.0e-6f) {
                if (gate > clamp) gate = clamp;
                if (up > clamp) up = clamp;
                if (up < -clamp) up = -clamp;
            }
            const uint64_t off = (uint64_t)slot * expert_mid_dim + row;
            if (write_aux) {
                gate_out[off] = gate;
                up_out[off] = up;
            }
            mid_out[off] = (gate / (1.0f + expf(-gate))) * up * weights[slot];
        }
    }
}

__global__ static void moe_resolve_resident_routes_kernel(
        uint64_t *route_ptrs,
        uint32_t *route_hit_mask,
        volatile uint32_t *ready_sequence,
        cuda_moe_route_request *request,
        const int32_t *selected,
        const float *weights,
        const int32_t *slot_by_layer_expert,
        uint32_t layer_index,
        uint32_t sequence,
        const char *cache_gate,
        const char *cache_up,
        const char *cache_down,
        uint64_t gate_offset,
        uint64_t up_offset,
        uint64_t down_offset,
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes,
        uint32_t route_count) {
    if (blockIdx.x != 0 || threadIdx.x != 0) return;
    if (route_count == 0u || route_count > 6u) return;
    uint32_t miss_count = 0;
    uint32_t hit_mask = 0;
    int32_t selected_local[6];
    int32_t hit_slots_local[6];
    uint32_t miss_routes_local[6];
    for (uint32_t route = 0; route < route_count; route++) {
        const int32_t expert = selected[route];
        int32_t slot = -1;
        if (expert >= 0 && expert < 256) {
            slot = slot_by_layer_expert[(uint64_t)layer_index * 256u + (uint32_t)expert];
        }
        selected_local[route] = expert;
        hit_slots_local[route] = slot;
        if (slot >= 0) {
            hit_mask |= 1u << route;
            const uint64_t gate_byte = (uint64_t)(uint32_t)slot * gate_expert_bytes;
            const uint64_t down_byte = (uint64_t)(uint32_t)slot * down_expert_bytes;
            route_ptrs[route] = (uint64_t)(uintptr_t)(cache_gate + gate_byte);
            route_ptrs[route_count + route] =
                (uint64_t)(uintptr_t)(cache_up + gate_byte);
            route_ptrs[2u * route_count + route] =
                (uint64_t)(uintptr_t)(cache_down + down_byte);
        } else {
            route_ptrs[route] = 0;
            route_ptrs[route_count + route] = 0;
            route_ptrs[2u * route_count + route] = 0;
            miss_routes_local[miss_count++] = route;
        }
    }
    *route_hit_mask = hit_mask;
    request->layer_index = layer_index;
    request->miss_count = miss_count;
    request->route_count = route_count;
    request->gate_offset = gate_offset;
    request->up_offset = up_offset;
    request->down_offset = down_offset;
    request->gate_expert_bytes = gate_expert_bytes;
    request->down_expert_bytes = down_expert_bytes;
    for (uint32_t route = 0; route < route_count; route++) {
        request->selected[route] = selected_local[route];
        request->weights[route] = weights[route];
        request->hit_slots[route] = hit_slots_local[route];
    }
    if (miss_count == 0u) {
        __threadfence_system();
        request->sequence = sequence;
        __threadfence_system();
        *ready_sequence = sequence;
        return;
    }
    for (uint32_t miss = 0; miss < miss_count; miss++) {
        request->miss_routes[miss] = miss_routes_local[miss];
    }
    __threadfence_system();
    request->sequence = sequence;
}

__global__ static void iq1_mixed_cold_one_plan_kernel(
        int32_t *hot_selected,
        float *hot_weights,
        int32_t *cold_selected,
        float *cold_weight,
        cuda_iq1_mixed_gpu_plan_request *request,
        const int32_t *selected,
        const float *weights,
        uint32_t layer_index,
        uint32_t sequence) {
    if (blockIdx.x != 0 || threadIdx.x != 0) return;
    uint32_t cold_slot = 0;
    float min_weight = weights[0];
    for (uint32_t route = 1; route < 6u; route++) {
        if (weights[route] < min_weight) {
            min_weight = weights[route];
            cold_slot = route;
        }
    }
    uint32_t hot = 0;
    for (uint32_t route = 0; route < 6u; route++) {
        if (route == cold_slot) continue;
        hot_selected[hot] = selected[route];
        hot_weights[hot] = weights[route];
        hot++;
    }
    const int32_t expert = selected[cold_slot];
    *cold_selected = expert;
    *cold_weight = min_weight;
    request->layer_index = layer_index;
    request->cold_slot = cold_slot;
    request->cold_expert = expert;
    request->cold_weight = min_weight;
    __threadfence_system();
    request->sequence = sequence;
}

__global__ static void moe_publish_transient_route_kernel(
        uint64_t *route_ptrs,
        uint32_t route_count,
        uint32_t route,
        uint32_t transient_slot,
        const char *transient_gate,
        const char *transient_up,
        const char *transient_down,
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes) {
    if (blockIdx.x != 0 || threadIdx.x != 0 ||
        route_count == 0u || route_count > 6u || route >= route_count) return;
    const uint64_t gate_byte = (uint64_t)transient_slot * gate_expert_bytes;
    const uint64_t down_byte = (uint64_t)transient_slot * down_expert_bytes;
    route_ptrs[route] =
        (uint64_t)(uintptr_t)(transient_gate + gate_byte);
    route_ptrs[route_count + route] =
        (uint64_t)(uintptr_t)(transient_up + gate_byte);
    route_ptrs[2u * route_count + route] =
        (uint64_t)(uintptr_t)(transient_down + down_byte);
}

__global__ static void moe_publish_resident_route_kernel(
        int32_t *slot_by_layer_expert,
        uint64_t *route_ptrs,
        int32_t old_map_index,
        uint32_t new_map_index,
        uint32_t cache_slot,
        uint32_t route_count,
        uint32_t route,
        const char *cache_gate,
        const char *cache_up,
        const char *cache_down,
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes) {
    if (blockIdx.x != 0 || threadIdx.x != 0 ||
        route_count == 0u || route_count > 6u || route >= route_count) return;
    if (old_map_index >= 0 &&
        slot_by_layer_expert[(uint32_t)old_map_index] == (int32_t)cache_slot) {
        slot_by_layer_expert[(uint32_t)old_map_index] = -1;
    }
    slot_by_layer_expert[new_map_index] = (int32_t)cache_slot;
    const uint64_t gate_byte = (uint64_t)cache_slot * gate_expert_bytes;
    const uint64_t down_byte = (uint64_t)cache_slot * down_expert_bytes;
    route_ptrs[route] = (uint64_t)(uintptr_t)(cache_gate + gate_byte);
    route_ptrs[route_count + route] =
        (uint64_t)(uintptr_t)(cache_up + gate_byte);
    route_ptrs[2u * route_count + route] =
        (uint64_t)(uintptr_t)(cache_down + down_byte);
}

__global__ static void moe_count_sorted_pairs_kernel(
        uint32_t *counts,
        const int32_t *selected,
        uint32_t pair_count) {
    uint32_t pair = (uint32_t)((uint64_t)blockIdx.x * blockDim.x + threadIdx.x);
    if (pair >= pair_count) return;
    int32_t expert_i = selected[pair];
    if (expert_i < 0) expert_i = 0;
    atomicAdd(counts + (uint32_t)expert_i, 1u);
}

__global__ static void moe_prefix_sorted_pairs_kernel(
        uint32_t *offsets,
        uint32_t *cursors,
        const uint32_t *counts) {
    if (threadIdx.x == 0) {
        uint32_t sum = 0;
        for (uint32_t e = 0; e < 256u; e++) {
            offsets[e] = sum;
            cursors[e] = sum;
            sum += counts[e];
        }
        offsets[256] = sum;
    }
}

__global__ static void moe_scatter_sorted_pairs_kernel(
        uint32_t *sorted_pairs,
        uint32_t *cursors,
        const int32_t *selected,
        uint32_t pair_count) {
    uint32_t pair = (uint32_t)((uint64_t)blockIdx.x * blockDim.x + threadIdx.x);
    if (pair >= pair_count) return;
    int32_t expert_i = selected[pair];
    if (expert_i < 0) expert_i = 0;
    uint32_t pos = atomicAdd(cursors + (uint32_t)expert_i, 1u);
    sorted_pairs[pos] = pair;
}

__global__ static void moe_build_expert_tile_offsets_kernel(
        uint32_t *tile_offsets,
        uint32_t *tile_total,
        const uint32_t *counts,
        uint32_t block_m) {
    if (threadIdx.x == 0) {
        uint32_t sum = 0;
        for (uint32_t e = 0; e < 256u; e++) {
            tile_offsets[e] = sum;
            sum += (counts[e] + block_m - 1u) / block_m;
        }
        tile_offsets[256] = sum;
        *tile_total = sum;
    }
}

__global__ static void moe_build_expert_tiles_kernel(
        uint32_t *tile_experts,
        uint32_t *tile_starts,
        const uint32_t *tile_offsets,
        const uint32_t *counts,
        uint32_t block_m) {
    uint32_t e = threadIdx.x;
    if (e >= 256u) return;
    uint32_t ntiles = (counts[e] + block_m - 1u) / block_m;
    uint32_t off = tile_offsets[e];
    for (uint32_t t = 0; t < ntiles; t++) {
        tile_experts[off + t] = e;
        tile_starts[off + t] = t * block_m;
    }
}

__global__ static void moe_gate_up_mid_sorted_qwarp32_kernel(
        float *gate_out,
        float *up_out,
        float *mid_out,
        const char *gate_base,
        const char *up_base,
        const cuda_block_q8_K *xq,
        const uint32_t *sorted_pairs,
        const int32_t *selected,
        const float *weights,
        uint64_t gate_expert_bytes,
        uint64_t gate_row_bytes,
        uint32_t xq_blocks,
        uint32_t expert_mid_dim,
        uint32_t n_expert,
        float clamp) {
    uint32_t lane = threadIdx.x & 7u;
    uint32_t row = blockIdx.x * 32u + (threadIdx.x >> 3u);
    uint32_t pair = sorted_pairs[blockIdx.y];
    if (row >= expert_mid_dim) return;
    uint32_t tok = pair / n_expert;
    uint32_t slot = pair - tok * n_expert;
    int32_t expert_i = selected[(uint64_t)tok * n_expert + slot];
    if (expert_i < 0) expert_i = 0;
    uint32_t expert = (uint32_t)expert_i;
    const cuda_block_iq2_xxs *gr = (const cuda_block_iq2_xxs *)(gate_base + (uint64_t)expert * gate_expert_bytes + (uint64_t)row * gate_row_bytes);
    const cuda_block_iq2_xxs *ur = (const cuda_block_iq2_xxs *)(up_base + (uint64_t)expert * gate_expert_bytes + (uint64_t)row * gate_row_bytes);
    const cuda_block_q8_K *xqb = xq + (uint64_t)tok * xq_blocks;
    float gate = 0.0f;
    float up = 0.0f;
    for (uint32_t b = lane; b < xq_blocks; b += 8u) {
        gate += dev_dot_iq2_xxs_q8_K_block(gr + b, xqb + b);
        up += dev_dot_iq2_xxs_q8_K_block(ur + b, xqb + b);
    }
    gate = quarter_warp_sum_f32(gate, lane);
    up = quarter_warp_sum_f32(up, lane);
    if (lane == 0) {
        if (clamp > 1.0e-6f) {
            if (gate > clamp) gate = clamp;
            if (up > clamp) up = clamp;
            if (up < -clamp) up = -clamp;
        }
        const uint64_t off = (uint64_t)pair * expert_mid_dim + row;
        gate_out[off] = gate;
        up_out[off] = up;
        mid_out[off] = (gate / (1.0f + expf(-gate))) * up * weights[(uint64_t)tok * n_expert + slot];
    }
}

__global__ static DS4_CUDA_UNUSED void moe_gate_up_mid_expert_tile8_kernel(
        float *gate_out,
        float *up_out,
        float *mid_out,
        const char *gate_base,
        const char *up_base,
        const cuda_block_q8_K *xq,
        const uint32_t *sorted_pairs,
        const uint32_t *offsets,
        const uint32_t *counts,
        const uint32_t *tile_total,
        const uint32_t *tile_experts,
        const uint32_t *tile_starts,
        const float *weights,
        uint64_t gate_expert_bytes,
        uint64_t gate_row_bytes,
        uint32_t xq_blocks,
        uint32_t expert_mid_dim,
        uint32_t n_expert,
        float clamp) {
    uint32_t tile = blockIdx.y;
    if (tile >= *tile_total) return;
    uint32_t group = threadIdx.x >> 3u;
    uint32_t lane = threadIdx.x & 7u;
    uint32_t pair_slot = group & 7u;
    uint32_t row_lane = group >> 3u;
    uint32_t expert = tile_experts[tile];
    uint32_t local_pair = tile_starts[tile] + pair_slot;
    if (local_pair >= counts[expert]) return;
    uint32_t sorted_idx = offsets[expert] + local_pair;
    uint32_t pair = sorted_pairs[sorted_idx];
    uint32_t tok = pair / n_expert;
    uint32_t slot = pair - tok * n_expert;
    const cuda_block_q8_K *xqb = xq + (uint64_t)tok * xq_blocks;

    for (uint32_t rr = 0; rr < 2u; rr++) {
        uint32_t row = blockIdx.x * 8u + row_lane + rr * 4u;
        if (row >= expert_mid_dim) continue;
        const cuda_block_iq2_xxs *gr = (const cuda_block_iq2_xxs *)(gate_base + (uint64_t)expert * gate_expert_bytes + (uint64_t)row * gate_row_bytes);
        const cuda_block_iq2_xxs *ur = (const cuda_block_iq2_xxs *)(up_base + (uint64_t)expert * gate_expert_bytes + (uint64_t)row * gate_row_bytes);
        float gate = 0.0f;
        float up = 0.0f;
        for (uint32_t b = lane; b < xq_blocks; b += 8u) {
            gate += dev_dot_iq2_xxs_q8_K_block(gr + b, xqb + b);
            up += dev_dot_iq2_xxs_q8_K_block(ur + b, xqb + b);
        }
        gate = quarter_warp_sum_f32(gate, lane);
        up = quarter_warp_sum_f32(up, lane);
        if (lane == 0) {
            if (clamp > 1.0e-6f) {
                if (gate > clamp) gate = clamp;
                if (up > clamp) up = clamp;
                if (up < -clamp) up = -clamp;
            }
            const uint64_t off = (uint64_t)pair * expert_mid_dim + row;
            gate_out[off] = gate;
            up_out[off] = up;
            mid_out[off] = (gate / (1.0f + expf(-gate))) * up * weights[(uint64_t)tok * n_expert + slot];
        }
    }
}

__global__ static void moe_gate_up_mid_expert_tile4_row32_kernel(
        float *gate_out,
        float *up_out,
