__global__ static void moe_down_ptrs_masked_qwarp32_kernel(
        float *down_out,
        const uint64_t *down_ptrs,
        const cuda_block_q8_K *midq,
        const uint32_t *route_hit_mask,
        uint32_t select_hits,
        uint64_t down_row_bytes,
        uint32_t midq_blocks,
        uint32_t out_dim) {
    uint32_t lane = threadIdx.x & 7u;
    uint32_t row = blockIdx.x * 32u + (threadIdx.x >> 3u);
    uint32_t slot = blockIdx.y;
    if (row >= out_dim) return;
    const uint32_t is_hit = (*route_hit_mask >> slot) & 1u;
    if (is_hit != select_hits) return;
    const char *down_ptr = (const char *)(uintptr_t)down_ptrs[slot];
    const cuda_block_q2_K *wr =
        (const cuda_block_q2_K *)(down_ptr + (uint64_t)row * down_row_bytes);
    const cuda_block_q8_K *xq = midq + (uint64_t)slot * midq_blocks;
    float acc = 0.0f;
    for (uint32_t b = lane; b < midq_blocks; b += 8u) {
        acc += dev_dot_q2_K_q8_K_block(wr + b, xq + b);
    }
    acc = quarter_warp_sum_f32(acc, lane);
    if (lane == 0) down_out[(uint64_t)slot * out_dim + row] = acc;
}

__global__ static void moe_down_split_fused_finish_qwarp32_kernel(
        float *out,
        const float *hit_down,
        const uint64_t *down_ptrs,
        const cuda_block_q8_K *midq,
        const uint32_t *route_hit_mask,
        uint64_t down_row_bytes,
        uint32_t midq_blocks,
        uint32_t n_expert,
        uint32_t out_dim) {
    uint32_t lane = threadIdx.x & 7u;
    uint32_t row = blockIdx.x * 32u + (threadIdx.x >> 3u);
    if (row >= out_dim) return;
    const uint32_t hit_mask = *route_hit_mask;
    float total = 0.0f;
    for (uint32_t slot = 0; slot < n_expert; slot++) {
        if ((hit_mask >> slot) & 1u) {
            if (lane == 0) {
                total += hit_down[(uint64_t)slot * out_dim + row];
            }
            continue;
        }
        const char *down_ptr =
            (const char *)(uintptr_t)down_ptrs[slot];
        const cuda_block_q2_K *wr = (const cuda_block_q2_K *)(
            down_ptr + (uint64_t)row * down_row_bytes);
        const cuda_block_q8_K *xq =
            midq + (uint64_t)slot * midq_blocks;
        float acc = 0.0f;
        for (uint32_t b = lane; b < midq_blocks; b += 8u) {
            acc += dev_dot_q2_K_q8_K_block(wr + b, xq + b);
        }
        acc = quarter_warp_sum_f32(acc, lane);
        if (lane == 0) total += acc;
    }
    if (lane == 0) out[row] = total;
}

