static int cuda_quant_promotion_gate_config(
        int q1_0,
        uint64_t *min_touches, double *min_weight, double *min_mass,
        uint64_t *request_budget, uint64_t *window_calls,
        uint64_t *window_budget) {
    if (!min_touches || !min_weight || !min_mass || !request_budget ||
        !window_calls || !window_budget) return 0;
    const char *min_touches_name = q1_0
        ? "DS4_Q1_0_PROMOTION_MIN_TOUCHES"
        : "DS4_IQ1_PROMOTION_MIN_TOUCHES";
    const char *min_weight_name = q1_0
        ? "DS4_Q1_0_PROMOTION_MIN_WEIGHT"
        : "DS4_IQ1_PROMOTION_MIN_WEIGHT";
    const char *min_mass_name = q1_0
        ? "DS4_Q1_0_PROMOTION_MIN_MASS"
        : "DS4_IQ1_PROMOTION_MIN_MASS";
    const char *request_budget_name = q1_0
        ? "DS4_Q1_0_PROMOTION_REQUEST_BUDGET"
        : "DS4_IQ1_PROMOTION_REQUEST_BUDGET";
    const char *window_calls_name = q1_0
        ? "DS4_Q1_0_PROMOTION_WINDOW_CALLS"
        : "DS4_IQ1_PROMOTION_WINDOW_CALLS";
    const char *window_budget_name = q1_0
        ? "DS4_Q1_0_PROMOTION_WINDOW_BUDGET"
        : "DS4_IQ1_PROMOTION_WINDOW_BUDGET";
    if (!cuda_iq1_promotion_u64_env(
            min_touches_name, 1u, 1u, UINT64_MAX,
            min_touches) ||
        !cuda_moe_tiering_double_env(
            min_weight_name, 0.0, 0.0, 1.0e300,
            min_weight) ||
        !cuda_moe_tiering_double_env(
            min_mass_name, 0.0, 0.0, 1.0e300,
            min_mass) ||
        !cuda_iq1_promotion_u64_env(
            request_budget_name, 0u, 0u, UINT64_MAX,
            request_budget) ||
        !cuda_iq1_promotion_u64_env(
            window_calls_name, 0u, 0u, UINT64_MAX,
            window_calls) ||
        !cuda_iq1_promotion_u64_env(
            window_budget_name, 0u, 0u, UINT64_MAX,
            window_budget)) {
        return 0;
    }
    if ((*window_calls == 0u) != (*window_budget == 0u)) {
        fprintf(stderr,
                "ds4: invalid %s promotion window config: %s and %s "
                "must both be zero or both >0\n",
                q1_0 ? "Q1_0" : "IQ1", window_calls_name,
                window_budget_name);
        return 0;
    }
    return 1;
}

static int cuda_moe_tiering_adaptive_budget_requested(int *value) {
    const char *env = getenv("DS4_EXPERT_TIER_ADAPTIVE_BUDGET");
    if (!value) return 0;
    *value = 0;
    if (!env || !env[0] || strcmp(env, "0") == 0) return 1;
    if (strcmp(env, "1") == 0) {
        *value = 1;
        return 1;
    }
    fprintf(stderr,
            "ds4: invalid DS4_EXPERT_TIER_ADAPTIVE_BUDGET=%s; adaptive budget disabled\n",
            env);
    return 0;
}

static int cuda_moe_tiering_double_env(
        const char *name, double fallback,
        double min_value, double max_value, double *value) {
    const char *env = getenv(name);
    if (!value) return 0;
    if (!env || !env[0]) {
        *value = fallback;
        return 1;
    }
    char *end = NULL;
    errno = 0;
    const double parsed = strtod(env, &end);
    while (end && (*end == ' ' || *end == '\t')) end++;
    if (end == env || errno != 0 || !end || *end != '\0' ||
        !isfinite(parsed) || parsed < min_value || parsed > max_value) {
        fprintf(stderr, "ds4: invalid %s=%s\n", name, env);
        return 0;
    }
    *value = parsed;
    return 1;
}

static size_t cuda_moe_tiering_entry_index(uint32_t layer, uint32_t expert) {
    return (size_t)layer * 256u + expert;
}

static double cuda_moe_tiering_lfru(
        const cuda_moe_tier_entry &entry, uint64_t now) {
    const uint64_t age = now > entry.last_call ? now - entry.last_call : 0;
    return entry.mass + (double)entry.frequency / (double)(age + 1u);
}

static void cuda_moe_tiering_clear_owned_slots(void) {
    for (uint32_t entry_index = 0;
         entry_index < g_moe_tiering.entries.size(); entry_index++) {
        cuda_moe_tier_entry &entry = g_moe_tiering.entries[entry_index];
        if (entry.ram_slot >= g_dynamic_arena.slots.size()) continue;
        cuda_dynamic_arena_slot &slot = g_dynamic_arena.slots[entry.ram_slot];
        const uint32_t layer = entry_index / 256u;
        const uint32_t expert = entry_index % 256u;
        if (slot.layer == layer && slot.expert == expert &&
            slot.content_generation == entry.ram_generation) {
            slot.state = DS4_GPU_ARENA_FREE;
            slot.layer = UINT32_MAX;
            slot.expert = UINT32_MAX;
            slot.checksum = 0;
            slot.last_dma_sequence = 0;
        }
        entry.ram_slot = UINT32_MAX;
        entry.ram_generation = 0;
        entry.vram_eligible_after_call = 0;
        entry.has_2bit_ram = 0;
        entry.promoted_from_iq1_cold = 0;
    }
}

static void cuda_moe_tiering_report_and_reset(void) {
    cuda_q1_0_ssd_wrap_flush();
    if (g_moe_tiering.mode != CUDA_MOE_TIER_OFF) {
        uint32_t states[4] = {0, 0, 0, 0};
        double mass_sum = 0.0;
        double lfru_top = 0.0;
        for (const cuda_moe_tier_entry &entry : g_moe_tiering.entries) {
            const uint32_t state = (uint32_t)entry.state;
            if (state < 4u) states[state]++;
            mass_sum += entry.mass;
            const double score = cuda_moe_tiering_lfru(
                entry, g_moe_tiering.call_tick);
            if (score > lfru_top) lfru_top = score;
        }
        if (g_moe_tiering.compose_prefill_mass_tiering) {
            fprintf(stderr,
                "ds4: [expert-tiering] final mode=%s policy=%s compose_prefill_mass_tiering=%u compose_router_open=%u snapshot_generation=%llu snapshot_backing_entries=%u snapshot_backing_hits=%llu snapshot_backing_misses=%llu snapshot_to_vram_bytes=%llu forbidden_cold_ssd_to_vram=%llu general_backing_reclaims=%llu clock_calls=%u replacement_budget=%u replacement_budget_base=%u adaptive_budget=%u adaptive_current_budget=%u adaptive_min=%u adaptive_max=%u adaptive_step=%u adaptive_pressure_threshold=%u adaptive_ups=%llu adaptive_downs=%llu adaptive_pressure_epochs=%llu adaptive_quiet_epochs=%llu adaptive_last_budget_skips_delta=%llu adaptive_last_replacements_delta=%llu min_frequency=%u hysteresis=%.9g calls=%llu selected=%llu cold=%llu ram_hits=%llu vram_hits=%llu cold_to_ram=%llu cold_to_vram=%llu ram_to_warm=%llu vram_promotions=%llu vram_demotions=%llu ram_evictions=%llu ram_admit_skips=%llu transient=%llu failures=%llu ssd_bytes=%llu ram_h2d_bytes=%llu policy_epochs=%llu policy_free_promotions=%llu policy_replacements=%llu policy_min_frequency_skips=%llu policy_budget_skips=%llu policy_score_skips=%llu states_ssd=%u states_probation=%u states_warm=%u states_vram=%u mass_sum=%.9g lfru_top=%.9g\n",
                cuda_moe_tiering_mode_name(g_moe_tiering.mode),
                cuda_moe_tiering_policy_name(g_moe_tiering.policy),
                g_moe_tiering.compose_prefill_mass_tiering ? 1u : 0u,
                g_moe_tiering.compose_router_open ? 1u : 0u,
                (unsigned long long)g_moe_tiering.snapshot_generation,
                g_moe_tiering.snapshot_backing_entries,
                (unsigned long long)g_moe_tiering.snapshot_backing_hits,
                (unsigned long long)g_moe_tiering.snapshot_backing_misses,
                (unsigned long long)g_moe_tiering.snapshot_to_vram_bytes,
                (unsigned long long)g_moe_tiering.forbidden_cold_ssd_to_vram,
                (unsigned long long)g_moe_tiering.general_backing_reclaims,
                g_moe_tiering.policy_clock_calls,
                g_moe_tiering.policy_replacement_budget,
                g_moe_tiering.policy_replacement_budget_base,
                g_moe_tiering.policy_adaptive_budget ? 1u : 0u,
                g_moe_tiering.policy_replacement_budget,
                g_moe_tiering.policy_adaptive_budget_min,
                g_moe_tiering.policy_adaptive_budget_max,
                g_moe_tiering.policy_adaptive_budget_step,
                g_moe_tiering.policy_adaptive_pressure_threshold,
                (unsigned long long)g_moe_tiering.policy_adaptive_budget_ups,
                (unsigned long long)g_moe_tiering.policy_adaptive_budget_downs,
                (unsigned long long)g_moe_tiering.policy_adaptive_pressure_epochs,
                (unsigned long long)g_moe_tiering.policy_adaptive_quiet_epochs,
                (unsigned long long)g_moe_tiering.policy_adaptive_last_budget_skips_delta,
                (unsigned long long)g_moe_tiering.policy_adaptive_last_replacements_delta,
                g_moe_tiering.policy_min_frequency,
                g_moe_tiering.policy_hysteresis,
                (unsigned long long)g_moe_tiering.calls,
                (unsigned long long)g_moe_tiering.selected,
                (unsigned long long)g_moe_tiering.cold,
                (unsigned long long)g_moe_tiering.ram_hits,
                (unsigned long long)g_moe_tiering.vram_hits,
                (unsigned long long)g_moe_tiering.cold_to_ram,
                (unsigned long long)g_moe_tiering.cold_to_vram,
                (unsigned long long)g_moe_tiering.ram_to_warm,
                (unsigned long long)g_moe_tiering.vram_promotions,
                (unsigned long long)g_moe_tiering.vram_demotions,
                (unsigned long long)g_moe_tiering.ram_evictions,
                (unsigned long long)g_moe_tiering.ram_admit_skips,
                (unsigned long long)g_moe_tiering.transient,
                (unsigned long long)g_moe_tiering.failures,
                (unsigned long long)g_moe_tiering.ssd_bytes,
                (unsigned long long)g_moe_tiering.ram_h2d_bytes,
                (unsigned long long)g_moe_tiering.policy_epochs,
                (unsigned long long)g_moe_tiering.policy_free_promotions,
                (unsigned long long)g_moe_tiering.policy_replacements,
                (unsigned long long)g_moe_tiering.policy_min_frequency_skips,
                (unsigned long long)g_moe_tiering.policy_budget_skips,
                (unsigned long long)g_moe_tiering.policy_score_skips,
                states[CUDA_MOE_TIER_SSD_COLD],
                states[CUDA_MOE_TIER_RAM_PROBATION],
                states[CUDA_MOE_TIER_RAM_WARM],
                states[CUDA_MOE_TIER_VRAM_PROTECTED],
                mass_sum, lfru_top);
        } else {
            fprintf(stderr,
                "ds4: [expert-tiering] final mode=%s policy=%s clock_calls=%u replacement_budget=%u replacement_budget_base=%u adaptive_budget=%u adaptive_current_budget=%u adaptive_min=%u adaptive_max=%u adaptive_step=%u adaptive_pressure_threshold=%u adaptive_ups=%llu adaptive_downs=%llu adaptive_pressure_epochs=%llu adaptive_quiet_epochs=%llu adaptive_last_budget_skips_delta=%llu adaptive_last_replacements_delta=%llu min_frequency=%u hysteresis=%.9g calls=%llu selected=%llu cold=%llu ram_hits=%llu vram_hits=%llu cold_to_ram=%llu cold_to_vram=%llu ram_to_warm=%llu vram_promotions=%llu vram_demotions=%llu ram_evictions=%llu ram_admit_skips=%llu general_backing_reclaims=%llu transient=%llu failures=%llu ssd_bytes=%llu ram_h2d_bytes=%llu policy_epochs=%llu policy_free_promotions=%llu policy_replacements=%llu policy_min_frequency_skips=%llu policy_budget_skips=%llu policy_score_skips=%llu states_ssd=%u states_probation=%u states_warm=%u states_vram=%u mass_sum=%.9g lfru_top=%.9g\n",
                cuda_moe_tiering_mode_name(g_moe_tiering.mode),
                cuda_moe_tiering_policy_name(g_moe_tiering.policy),
                g_moe_tiering.policy_clock_calls,
                g_moe_tiering.policy_replacement_budget,
                g_moe_tiering.policy_replacement_budget_base,
                g_moe_tiering.policy_adaptive_budget ? 1u : 0u,
                g_moe_tiering.policy_replacement_budget,
                g_moe_tiering.policy_adaptive_budget_min,
                g_moe_tiering.policy_adaptive_budget_max,
                g_moe_tiering.policy_adaptive_budget_step,
                g_moe_tiering.policy_adaptive_pressure_threshold,
                (unsigned long long)g_moe_tiering.policy_adaptive_budget_ups,
                (unsigned long long)g_moe_tiering.policy_adaptive_budget_downs,
                (unsigned long long)g_moe_tiering.policy_adaptive_pressure_epochs,
                (unsigned long long)g_moe_tiering.policy_adaptive_quiet_epochs,
                (unsigned long long)g_moe_tiering.policy_adaptive_last_budget_skips_delta,
                (unsigned long long)g_moe_tiering.policy_adaptive_last_replacements_delta,
                g_moe_tiering.policy_min_frequency,
                g_moe_tiering.policy_hysteresis,
                (unsigned long long)g_moe_tiering.calls,
                (unsigned long long)g_moe_tiering.selected,
                (unsigned long long)g_moe_tiering.cold,
                (unsigned long long)g_moe_tiering.ram_hits,
                (unsigned long long)g_moe_tiering.vram_hits,
                (unsigned long long)g_moe_tiering.cold_to_ram,
                (unsigned long long)g_moe_tiering.cold_to_vram,
                (unsigned long long)g_moe_tiering.ram_to_warm,
                (unsigned long long)g_moe_tiering.vram_promotions,
                (unsigned long long)g_moe_tiering.vram_demotions,
                (unsigned long long)g_moe_tiering.ram_evictions,
                (unsigned long long)g_moe_tiering.ram_admit_skips,
                (unsigned long long)g_moe_tiering.general_backing_reclaims,
                (unsigned long long)g_moe_tiering.transient,
                (unsigned long long)g_moe_tiering.failures,
                (unsigned long long)g_moe_tiering.ssd_bytes,
                (unsigned long long)g_moe_tiering.ram_h2d_bytes,
                (unsigned long long)g_moe_tiering.policy_epochs,
                (unsigned long long)g_moe_tiering.policy_free_promotions,
                (unsigned long long)g_moe_tiering.policy_replacements,
                (unsigned long long)g_moe_tiering.policy_min_frequency_skips,
                (unsigned long long)g_moe_tiering.policy_budget_skips,
                (unsigned long long)g_moe_tiering.policy_score_skips,
                states[CUDA_MOE_TIER_SSD_COLD],
                states[CUDA_MOE_TIER_RAM_PROBATION],
                states[CUDA_MOE_TIER_RAM_WARM],
                states[CUDA_MOE_TIER_VRAM_PROTECTED],
                mass_sum, lfru_top);
        }
    }
    if (g_iq1_promotion.requested_slots != 0u) {
        fprintf(stderr,
            "ds4: [iq1-promotion] final requested_slots=%u reserved_slots=%u "
            "strategy=%s "
            "min_touches=%llu min_weight=%.9g min_mass=%.9g "
            "request_budget=%llu window_calls=%llu window_budget=%llu "
            "snapshot_evictions=%llu cold_observed=%llu cold_existing_2bit=%llu "
            "cold_to_2bit_ram=%llu probation_ram_hits=%llu next_token_waits=%llu "
            "promotion_2bit_ssd_bytes=%llu promotion_2bit_ssd_seconds=%.9g "
            "direct_ssd_to_vram_rejected=%llu probation_backing_reclaims=%llu "
            "cold_gate_candidates=%llu weight_ge_001=%llu weight_ge_002=%llu "
            "weight_ge_005=%llu weight_ge_010=%llu skips_touches=%llu "
            "skips_weight=%llu skips_mass=%llu skips_request_budget=%llu "
            "skips_window_budget=%llu q1_0_observed=%llu "
            "q1_0_stage_attempts=%llu q1_0_stage_successes=%llu "
            "q1_0_next_call_guards=%llu "
            "q1_0_record_rejects=%llu q1_0_record_attempts=%llu "
            "q1_0_record_successes=%llu q1_0_record_failures=%llu "
            "failures=%llu\n",
            g_iq1_promotion.requested_slots,
            g_iq1_promotion.reserved_slots,
            g_moe_tiering.compose_router_open ?
                "pre-reserved-open-router" : "snapshot-evict",
            (unsigned long long)g_iq1_promotion.min_touches,
            g_iq1_promotion.min_weight,
            g_iq1_promotion.min_mass,
            (unsigned long long)g_iq1_promotion.request_budget,
            (unsigned long long)g_iq1_promotion.window_calls,
            (unsigned long long)g_iq1_promotion.window_budget,
            (unsigned long long)g_iq1_promotion.snapshot_evictions,
            (unsigned long long)g_iq1_promotion.cold_observed,
            (unsigned long long)g_iq1_promotion.cold_existing_2bit,
            (unsigned long long)g_iq1_promotion.cold_to_2bit_ram,
            (unsigned long long)g_iq1_promotion.probation_ram_hits,
            (unsigned long long)g_iq1_promotion.next_token_waits,
            (unsigned long long)g_iq1_promotion.promotion_2bit_ssd_bytes,
            g_iq1_promotion.promotion_2bit_ssd_seconds,
            (unsigned long long)g_iq1_promotion.direct_ssd_to_vram_rejected,
            (unsigned long long)g_iq1_promotion.probation_backing_reclaims,
            (unsigned long long)g_iq1_promotion.cold_gate_candidates,
            (unsigned long long)g_iq1_promotion.weight_ge_001,
            (unsigned long long)g_iq1_promotion.weight_ge_002,
            (unsigned long long)g_iq1_promotion.weight_ge_005,
            (unsigned long long)g_iq1_promotion.weight_ge_010,
            (unsigned long long)g_iq1_promotion.skips_touches,
            (unsigned long long)g_iq1_promotion.skips_weight,
            (unsigned long long)g_iq1_promotion.skips_mass,
            (unsigned long long)g_iq1_promotion.skips_request_budget,
            (unsigned long long)g_iq1_promotion.skips_window_budget,
            (unsigned long long)g_iq1_promotion.q1_0_observed,
            (unsigned long long)g_iq1_promotion.q1_0_stage_attempts,
            (unsigned long long)g_iq1_promotion.q1_0_stage_successes,
            (unsigned long long)g_iq1_promotion.q1_0_next_call_guards,
            (unsigned long long)g_iq1_promotion.q1_0_record_rejects,
            (unsigned long long)g_iq1_promotion.q1_0_record_attempts,
            (unsigned long long)g_iq1_promotion.q1_0_record_successes,
            (unsigned long long)g_iq1_promotion.q1_0_record_failures,
            (unsigned long long)g_iq1_promotion.failures);
    }
    cuda_moe_tiering_clear_owned_slots();
    g_dynamic_arena.tiering_exclusive = 0;
    g_moe_tiering = cuda_moe_tiering();
    g_iq1_promotion = cuda_iq1_promotion();
}

static void cuda_moe_tiering_request_boundary_reset(void) {
    if (g_moe_tiering.mode != CUDA_MOE_TIER_OFF &&
        g_moe_tiering.compose_prefill_mass_tiering) {
        cuda_moe_tiering_report_and_reset();
    }
}

static int cuda_moe_tiering_reserve_open_router_slots(uint32_t requested) {
    if (requested == 0u) return 1;
    if (!g_moe_tiering.compose_prefill_mass_tiering ||
        !g_moe_tiering.compose_router_open ||
        requested >= g_moe_tiering.snapshot_backing_entries) {
        fprintf(stderr,
                "ds4: open-router backing reserve refused requested=%u backing=%u\n",
                requested, g_moe_tiering.snapshot_backing_entries);
        return 0;
    }
    try {
        g_moe_tiering.open_router_pool_slot.assign(
            g_dynamic_arena.slots.size(), 0u);
    } catch (...) {
        fprintf(stderr,
                "ds4: open-router backing reserve metadata allocation failed\n");
        return 0;
    }
    uint32_t free_slots = 0u;
    uint32_t reserved_slots = 0u;
    for (uint32_t slot = 0;
         slot < g_dynamic_arena.slots.size(); slot++) {
        if (g_dynamic_arena.slots[slot].state != DS4_GPU_ARENA_FREE) {
            continue;
        }
        free_slots++;
        if (reserved_slots < requested) {
            g_moe_tiering.open_router_pool_slot[slot] = 1u;
            reserved_slots++;
        }
    }
    if (reserved_slots < requested) {
        fprintf(stderr,
                "ds4: open-router backing reserve short requested=%u free=%u\n",
                requested, free_slots);
        g_moe_tiering.open_router_pool_slot.clear();
        return 0;
    }
    g_moe_tiering.open_router_reserve_slots = reserved_slots;
    if (g_iq1_promotion.requested_slots != 0u) {
        g_iq1_promotion.reserved_slots = reserved_slots;
    }
    fprintf(stderr,
            "ds4: [expert-tiering] open-router backing ready requested_slots=%u "
            "reserved_slots=%u remaining_snapshot=%u free_slots=%u "
            "strategy=pre-reserved-open-router\n",
            requested, g_moe_tiering.open_router_reserve_slots,
            g_moe_tiering.snapshot_backing_entries,
            free_slots);
    return 1;
}

static int cuda_moe_tiering_prepare(void) {
    const int requested = cuda_moe_tiering_mode_requested();
    if (requested < 0) return 0;
    const int compose_requested = cuda_moe_prefill_tier_compose_requested();
    const int compose_router_open =
        cuda_moe_prefill_tier_router_open_requested();
    const int promotion_probation_slots =
        cuda_quant_promotion_probation_slots_requested();
    const int promotion_q1_0 =
        cuda_q1_0_dynamic_promotion_requested();
    const int configured_reserve_slots =
        cuda_moe_prefill_tier_reserve_slots_requested();
    if (compose_requested < 0 || compose_router_open < 0 ||
        promotion_probation_slots < 0 ||
        configured_reserve_slots < 0) return 0;
    if (cuda_q1_0_exclusive_arena_active() &&
        (requested != CUDA_MOE_TIER_OFF || compose_requested > 0 ||
         compose_router_open > 0 || promotion_probation_slots > 0 ||
         configured_reserve_slots > 0)) {
        fprintf(stderr,
                "ds4: [q1-0-resident-arena] result=failed reason=mixed-host-resolver-not-implemented expert_tiering=%d compose=%d router_open=%d promotion_probation=%d reserve=%d\n",
                requested, compose_requested, compose_router_open,
                promotion_probation_slots, configured_reserve_slots);
        return 0;
    }
    uint64_t promotion_min_touches = 1u;
    double promotion_min_weight = 0.0;
    double promotion_min_mass = 0.0;
    uint64_t promotion_request_budget = 0u;
    uint64_t promotion_window_calls = 0u;
    uint64_t promotion_window_budget = 0u;
    if (promotion_probation_slots > 0 &&
        !cuda_quant_promotion_gate_config(
            promotion_q1_0,
            &promotion_min_touches, &promotion_min_weight,
            &promotion_min_mass, &promotion_request_budget,
            &promotion_window_calls, &promotion_window_budget)) {
        return 0;
    }
    if (compose_router_open && !compose_requested) {
        fprintf(stderr,
                "ds4: open prefill tier router requires composed tiering\n");
        return 0;
    }
    const char *iq1_mixed = getenv("DS4_IQ1_S_MIXED_COLD_K");
    if (!promotion_q1_0 && promotion_probation_slots > 0 &&
        (requested != CUDA_MOE_TIER_ENFORCE || !compose_requested ||
         !compose_router_open ||
         configured_reserve_slots != promotion_probation_slots ||
         !g_iq1_s_sidecar_file_valid || !iq1_mixed ||
         strcmp(iq1_mixed, "1") != 0)) {
        fprintf(stderr,
                "ds4: IQ1 promotion probation requires mixed IQ1_S, open-router composed enforce tiering, matching reserve/probation slots, and a bound sidecar\n");
        return 0;
    }
    if (promotion_q1_0 &&
        (promotion_probation_slots <= 0 ||
         requested != CUDA_MOE_TIER_ENFORCE || !compose_requested ||
         !compose_router_open ||
         configured_reserve_slots != promotion_probation_slots ||
         !g_q1_0_sidecar_file_valid ||
         !cuda_q1_0_dual_arena_requested() ||
         cuda_q1_0_snapshot_backing_requested())) {
        fprintf(stderr,
                "ds4: Q1_0 promotion probation requires full resident "
                "dual-arena Q1_0, open-router composed enforce tiering, "
                "and matching reserve/probation slots\n");
        return 0;
    }
    if (requested == CUDA_MOE_TIER_OFF) {
        if (compose_requested > 0) {
            fprintf(stderr,
                    "ds4: prefill/tiering compose requires expert tiering enforce\n");
            return 0;
        }
        if (g_moe_tiering.mode != CUDA_MOE_TIER_OFF) {
            cuda_moe_tiering_report_and_reset();
        }
        return 1;
    }
    const int policy_requested = cuda_moe_tiering_policy_requested();
    uint32_t clock_calls = 430u;
    uint32_t replacement_budget = 16u;
    int adaptive_budget = 0;
    uint32_t adaptive_budget_min = 16u;
    uint32_t adaptive_budget_max = 32u;
    uint32_t adaptive_budget_step = 8u;
    uint32_t adaptive_pressure_threshold = 64u;
    uint32_t min_frequency = 3u;
    double hysteresis = 1.25;
    if (policy_requested < 0 ||
        !cuda_moe_tiering_u32_env(
            "DS4_EXPERT_TIER_CLOCK_CALLS", 430u, 1u, 1000000u,
            &clock_calls) ||
        !cuda_moe_tiering_u32_env(
            "DS4_EXPERT_TIER_REPLACEMENT_BUDGET", 16u, 1u, 512u,
            &replacement_budget) ||
        !cuda_moe_tiering_u32_env(
            "DS4_EXPERT_TIER_MIN_FREQUENCY", 3u, 2u, 1000000u,
            &min_frequency) ||
        !cuda_moe_tiering_double_env(
            "DS4_EXPERT_TIER_HYSTERESIS", 1.25, 1.0, 100.0,
            &hysteresis)) {
        return 0;
    }
    if (!cuda_moe_tiering_adaptive_budget_requested(&adaptive_budget)) {
        adaptive_budget = 0;
    }
    if (adaptive_budget) {
        int adaptive_config_ok = 1;
        adaptive_config_ok = adaptive_config_ok &&
            cuda_moe_tiering_u32_env(
                "DS4_EXPERT_TIER_ADAPTIVE_BUDGET_MIN", 16u, 1u, 512u,
                &adaptive_budget_min);
        adaptive_config_ok = adaptive_config_ok &&
            cuda_moe_tiering_u32_env(
                "DS4_EXPERT_TIER_ADAPTIVE_BUDGET_MAX", 32u, 1u, 512u,
                &adaptive_budget_max);
        adaptive_config_ok = adaptive_config_ok &&
            cuda_moe_tiering_u32_env(
                "DS4_EXPERT_TIER_ADAPTIVE_BUDGET_STEP", 8u, 1u, 512u,
                &adaptive_budget_step);
        adaptive_config_ok = adaptive_config_ok &&
            cuda_moe_tiering_u32_env(
                "DS4_EXPERT_TIER_ADAPTIVE_PRESSURE_THRESHOLD", 64u, 1u,
                1000000u, &adaptive_pressure_threshold);
        if (!adaptive_config_ok ||
            adaptive_budget_min > adaptive_budget_max ||
            adaptive_budget_step >
                adaptive_budget_max - adaptive_budget_min + 1u ||
            replacement_budget < adaptive_budget_min ||
            replacement_budget > adaptive_budget_max) {
            fprintf(stderr,
                    "ds4: invalid adaptive expert tier budget config; adaptive budget disabled\n");
            adaptive_budget = 0;
            adaptive_budget_min = 16u;
            adaptive_budget_max = 32u;
            adaptive_budget_step = 8u;
            adaptive_pressure_threshold = 64u;
        }
    }
    if (policy_requested == CUDA_MOE_TIER_POLICY_SECOND_TOUCH) {
        clock_calls = 0u;
        replacement_budget = 0u;
        adaptive_budget = 0;
        min_frequency = 2u;
        hysteresis = 1.0;
    }
    if (g_moe_tiering.mode == (cuda_moe_tier_mode)requested &&
        g_moe_tiering.policy == (cuda_moe_tier_policy)policy_requested &&
        g_moe_tiering.policy_clock_calls == clock_calls &&
        g_moe_tiering.policy_replacement_budget_base == replacement_budget &&
        g_moe_tiering.policy_adaptive_budget == adaptive_budget &&
        g_moe_tiering.policy_adaptive_budget_min == adaptive_budget_min &&
        g_moe_tiering.policy_adaptive_budget_max == adaptive_budget_max &&
        g_moe_tiering.policy_adaptive_budget_step == adaptive_budget_step &&
        g_moe_tiering.policy_adaptive_pressure_threshold ==
            adaptive_pressure_threshold &&
        g_moe_tiering.policy_min_frequency == min_frequency &&
        g_moe_tiering.policy_hysteresis == hysteresis &&
        g_iq1_promotion.requested_slots ==
            (uint32_t)promotion_probation_slots &&
        g_iq1_promotion.min_touches == promotion_min_touches &&
        g_iq1_promotion.min_weight == promotion_min_weight &&
        g_iq1_promotion.min_mass == promotion_min_mass &&
        g_iq1_promotion.request_budget == promotion_request_budget &&
        g_iq1_promotion.window_calls == promotion_window_calls &&
        g_iq1_promotion.window_budget == promotion_window_budget &&
        g_moe_tiering.open_router_reserve_slots ==
            (uint32_t)configured_reserve_slots &&
        g_moe_tiering.compose_prefill_mass_tiering == compose_requested &&
        g_moe_tiering.compose_router_open == compose_router_open &&
        (!compose_requested ||
         g_moe_tiering.snapshot_generation ==
             g_dynamic_arena.snapshot_generation) &&
        g_moe_tiering.entries.size() ==
            (size_t)CUDA_MOE_LAYER_COUNT * 256u) {
        return 1;
    }
    if (g_moe_tiering.mode != CUDA_MOE_TIER_OFF) {
        cuda_moe_tiering_report_and_reset();
    }
    if (requested == CUDA_MOE_TIER_ENFORCE) {
        if (!g_dynamic_arena.host_base || g_dynamic_arena.txn ||
            g_dynamic_arena.n_layer != CUDA_MOE_LAYER_COUNT ||
            g_dynamic_arena.n_expert != 256u ||
            g_dynamic_arena.slots.empty()) {
            fprintf(stderr,
                    "ds4: expert tiering enforce requires an idle pinned dynamic arena\n");
            return 0;
        }
        if (compose_requested) {
            if (policy_requested != CUDA_MOE_TIER_POLICY_MASS_LFRU ||
                g_dynamic_arena.snapshot_generation == 0 ||
                g_dynamic_arena.hits_disabled ||
                g_dynamic_arena.submissions_blocked ||
                g_dynamic_arena_observer.enabled ||
                !g_dynamic_arena_observer.target.empty() ||
                !g_dynamic_arena_observer.counts.empty() ||
                !g_prefill_mass_observer.enabled ||
                !g_prefill_mass_observer.finalized ||
                !g_prefill_mass_observer.wrap_published ||
                g_reap_mass_observer.enabled) {
                fprintf(stderr,
                        "ds4: prefill/tiering compose requires finalized published prefill snapshot and no dynamic/REAP observer\n");
                return 0;
            }
        } else if (g_dynamic_arena.snapshot_generation != 0 ||
                   g_dynamic_arena_observer.enabled ||
                   g_prefill_mass_observer.enabled ||
                   g_reap_mass_observer.enabled) {
            fprintf(stderr,
                    "ds4: expert tiering enforce requires an idle pinned dynamic arena\n");
            return 0;
        }
    }
    try {
        cuda_moe_tier_entry empty;
        memset(&empty, 0, sizeof(empty));
        empty.ram_slot = UINT32_MAX;
        empty.state = CUDA_MOE_TIER_SSD_COLD;
        g_moe_tiering.entries.assign(
            (size_t)CUDA_MOE_LAYER_COUNT * 256u, empty);
    } catch (...) {
        fprintf(stderr, "ds4: expert tiering metadata allocation failed\n");
        return 0;
    }
    g_moe_tiering.mode = (cuda_moe_tier_mode)requested;
    g_moe_tiering.policy = (cuda_moe_tier_policy)policy_requested;
    g_moe_tiering.compose_prefill_mass_tiering = compose_requested;
    g_moe_tiering.compose_router_open = compose_router_open;
    g_moe_tiering.policy_clock_calls = clock_calls;
    g_moe_tiering.policy_replacement_budget = replacement_budget;
    g_moe_tiering.policy_replacement_budget_base = replacement_budget;
    g_moe_tiering.policy_adaptive_budget = adaptive_budget;
    g_moe_tiering.policy_adaptive_budget_min = adaptive_budget_min;
    g_moe_tiering.policy_adaptive_budget_max = adaptive_budget_max;
    g_moe_tiering.policy_adaptive_budget_step = adaptive_budget_step;
    g_moe_tiering.policy_adaptive_pressure_threshold =
        adaptive_pressure_threshold;
    g_moe_tiering.policy_min_frequency = min_frequency;
    g_moe_tiering.policy_hysteresis = hysteresis;
    g_moe_tiering.policy_epoch = UINT64_MAX;
    g_iq1_promotion = cuda_iq1_promotion();
    g_iq1_promotion.requested_slots =
        (uint32_t)promotion_probation_slots;
    g_iq1_promotion.min_touches = promotion_min_touches;
    g_iq1_promotion.min_weight = promotion_min_weight;
    g_iq1_promotion.min_mass = promotion_min_mass;
    g_iq1_promotion.request_budget = promotion_request_budget;
    g_iq1_promotion.window_calls = promotion_window_calls;
    g_iq1_promotion.window_budget = promotion_window_budget;
    if (compose_requested) {
        g_moe_tiering.snapshot_generation =
            g_dynamic_arena.snapshot_generation;
        for (uint32_t entry_index = 0;
             entry_index < g_dynamic_arena.active.size() &&
             entry_index < g_moe_tiering.entries.size(); entry_index++) {
            const uint32_t layer = entry_index / 256u;
            const uint32_t expert = entry_index % 256u;
            if (cuda_dynamic_arena_binding_valid(
                    g_dynamic_arena,
                    g_dynamic_arena.active[entry_index],
                    layer, expert,
                    g_moe_tiering.snapshot_generation,
                    DS4_GPU_ARENA_READY)) {
                cuda_moe_tier_entry &entry =
                    g_moe_tiering.entries[entry_index];
                /* Snapshot-backed RAM is borrowed backing, not tier-owned. */
                entry.ram_slot = UINT32_MAX;
                entry.ram_generation = 0;
                entry.has_2bit_ram =
                    g_dynamic_arena.backing ==
                    CUDA_DYNAMIC_ARENA_BACKING_PRIMARY;
                entry.state = CUDA_MOE_TIER_RAM_PROBATION;
                g_moe_tiering.snapshot_backing_entries++;
            }
        }
        if (g_moe_tiering.snapshot_backing_entries == 0u) {
            fprintf(stderr,
                    "ds4: prefill/tiering compose requires non-empty snapshot backing\n");
            g_moe_tiering = cuda_moe_tiering();
            g_iq1_promotion = cuda_iq1_promotion();
            return 0;
        }
        if (!cuda_moe_tiering_reserve_open_router_slots(
                (uint32_t)configured_reserve_slots)) {
            g_moe_tiering = cuda_moe_tiering();
            g_iq1_promotion = cuda_iq1_promotion();
            return 0;
        }
    }
    if (g_moe_tiering.mode == CUDA_MOE_TIER_ENFORCE) {
        g_dynamic_arena.tiering_exclusive = 1;
    }
    fprintf(stderr, "ds4: expert tiering active mode=%s policy=%s compose_prefill_mass_tiering=%u compose_router_open=%u snapshot_generation=%llu snapshot_backing_entries=%u clock_calls=%u replacement_budget=%u replacement_budget_base=%u adaptive_budget=%u adaptive_current_budget=%u adaptive_min=%u adaptive_max=%u adaptive_step=%u adaptive_pressure_threshold=%u adaptive_ups=%llu adaptive_downs=%llu adaptive_pressure_epochs=%llu adaptive_quiet_epochs=%llu adaptive_last_budget_skips_delta=%llu adaptive_last_replacements_delta=%llu min_frequency=%u hysteresis=%.9g entries=%u ram_slots=%u\n",
            cuda_moe_tiering_mode_name(g_moe_tiering.mode),
            cuda_moe_tiering_policy_name(g_moe_tiering.policy),
            g_moe_tiering.compose_prefill_mass_tiering ? 1u : 0u,
            g_moe_tiering.compose_router_open ? 1u : 0u,
            (unsigned long long)g_moe_tiering.snapshot_generation,
            g_moe_tiering.snapshot_backing_entries,
            g_moe_tiering.policy_clock_calls,
            g_moe_tiering.policy_replacement_budget,
            g_moe_tiering.policy_replacement_budget_base,
            g_moe_tiering.policy_adaptive_budget ? 1u : 0u,
            g_moe_tiering.policy_replacement_budget,
            g_moe_tiering.policy_adaptive_budget_min,
            g_moe_tiering.policy_adaptive_budget_max,
            g_moe_tiering.policy_adaptive_budget_step,
            g_moe_tiering.policy_adaptive_pressure_threshold,
            (unsigned long long)g_moe_tiering.policy_adaptive_budget_ups,
            (unsigned long long)g_moe_tiering.policy_adaptive_budget_downs,
            (unsigned long long)g_moe_tiering.policy_adaptive_pressure_epochs,
            (unsigned long long)g_moe_tiering.policy_adaptive_quiet_epochs,
            (unsigned long long)g_moe_tiering.policy_adaptive_last_budget_skips_delta,
            (unsigned long long)g_moe_tiering.policy_adaptive_last_replacements_delta,
            g_moe_tiering.policy_min_frequency,
            g_moe_tiering.policy_hysteresis,
            (uint32_t)g_moe_tiering.entries.size(),
            (uint32_t)g_dynamic_arena.slots.size());
    return 1;
}

static int cuda_moe_tiering_snapshot_ram_ptrs(
        uint32_t layer, uint32_t expert,
        char **gate, char **up, char **down) {
    if (!g_moe_tiering.compose_prefill_mass_tiering ||
        g_dynamic_arena.backing != CUDA_DYNAMIC_ARENA_BACKING_PRIMARY ||
        layer >= CUDA_MOE_LAYER_COUNT || expert >= 256u ||
        !gate || !up || !down ||
        g_dynamic_arena.snapshot_generation !=
            g_moe_tiering.snapshot_generation ||
        g_dynamic_arena.hits_disabled ||
        g_dynamic_arena.submissions_blocked) {
        return 0;
    }
    const uint32_t entry = layer * 256u + expert;
    if (entry >= g_dynamic_arena.active.size()) return 0;
    const cuda_dynamic_arena_binding &binding =
        g_dynamic_arena.active[entry];
    if (!cuda_dynamic_arena_binding_valid(
            g_dynamic_arena,
            binding, layer, expert,
            g_moe_tiering.snapshot_generation,
            DS4_GPU_ARENA_READY)) {
        return 0;
    }
    cuda_dynamic_arena_slot &slot = g_dynamic_arena.slots[binding.slot];
    *gate = slot.host_ptr;
    *up = slot.host_ptr + g_moe_expert_cache.gate_expert_bytes;
    *down = *up + g_moe_expert_cache.gate_expert_bytes;
    return 1;
}

static int cuda_moe_tiering_ram_ptrs(
        uint32_t layer, uint32_t expert,
        char **gate, char **up, char **down) {
    if (layer >= CUDA_MOE_LAYER_COUNT || expert >= 256u ||
        !gate || !up || !down) return 0;
    cuda_moe_tier_entry &entry =
        g_moe_tiering.entries[cuda_moe_tiering_entry_index(layer, expert)];
    if (entry.ram_slot >= g_dynamic_arena.slots.size()) return 0;
    cuda_dynamic_arena_slot &slot = g_dynamic_arena.slots[entry.ram_slot];
    if ((slot.state != DS4_GPU_ARENA_READY &&
         slot.state != DS4_GPU_ARENA_STAGED) ||
        slot.layer != layer || slot.expert != expert ||
        slot.content_generation != entry.ram_generation) {
        return 0;
    }
    *gate = slot.host_ptr;
    *up = slot.host_ptr + g_moe_expert_cache.gate_expert_bytes;
    *down = *up + g_moe_expert_cache.gate_expert_bytes;
    return 1;
}

static int cuda_moe_tiering_has_exact_vram(
        uint32_t layer, uint32_t expert) {
    if (layer >= CUDA_MOE_LAYER_COUNT || expert >= 256u ||
        g_moe_expert_cache.host_slot_by_layer_expert.empty()) {
        return 0;
    }
    const uint32_t map_index = layer * 256u + expert;
    if (map_index >= g_moe_expert_cache.host_slot_by_layer_expert.size()) {
        return 0;
    }
    const int32_t slot_i =
        g_moe_expert_cache.host_slot_by_layer_expert[map_index];
    if (slot_i < 0 || (uint32_t)slot_i >= g_moe_expert_cache.slots.size()) {
        return 0;
    }
    const cuda_moe_cache_slot &slot =
        g_moe_expert_cache.slots[(uint32_t)slot_i];
    return slot.state == CUDA_MOE_CACHE_VALID &&
        slot.layer_index == layer &&
        slot.expert_id == expert;
}

static int cuda_moe_tiering_pick_ram_slot(
        uint32_t current_layer, uint32_t current_expert,
        size_t *victim_entry_out, int preferred_pageable = -1) {
    if (!victim_entry_out) return -1;
    *victim_entry_out = SIZE_MAX;
    const int open_router_pool_active =
        g_moe_tiering.compose_prefill_mass_tiering &&
        g_moe_tiering.compose_router_open &&
        g_moe_tiering.open_router_reserve_slots > 0u;
    const auto slot_allowed = [open_router_pool_active](uint32_t slot) -> bool {
        if (!open_router_pool_active) return true;
        return slot < g_moe_tiering.open_router_pool_slot.size() &&
            g_moe_tiering.open_router_pool_slot[slot] != 0u;
    };
    for (uint32_t pass = 0; pass < (preferred_pageable < 0 ? 1u : 2u);
         pass++) {
        for (uint32_t slot = 0; slot < g_dynamic_arena.slots.size(); slot++) {
            if (!slot_allowed(slot)) continue;
            if (cuda_q1_0_ssd_wrap_slot_reserved(slot)) continue;
            const cuda_dynamic_arena_slot &arena_slot =
                g_dynamic_arena.slots[slot];
            if (arena_slot.state != DS4_GPU_ARENA_FREE) continue;
            if (pass == 0u && preferred_pageable >= 0 &&
                (int)arena_slot.pageable != preferred_pageable) {
                continue;
            }
            return (int)slot;
        }
    }
    for (uint32_t pass = 0; pass < (preferred_pageable < 0 ? 1u : 2u);
         pass++) {
        int best_slot = -1;
        size_t best_entry = 0;
        double best_score = 1.0e300;
        for (size_t index = 0; index < g_moe_tiering.entries.size(); index++) {
            const cuda_moe_tier_entry &entry = g_moe_tiering.entries[index];
            const uint32_t entry_layer = (uint32_t)(index / 256u);
            const uint32_t entry_expert = (uint32_t)(index % 256u);
            const int reclaimable_vram_backing =
                entry.state == CUDA_MOE_TIER_VRAM_PROTECTED &&
                cuda_moe_tiering_has_exact_vram(entry_layer, entry_expert);
            if (entry.ram_slot >= g_dynamic_arena.slots.size() ||
                !slot_allowed(entry.ram_slot) ||
                cuda_q1_0_ssd_wrap_slot_reserved(entry.ram_slot) ||
                (pass == 0u && preferred_pageable >= 0 &&
                 (int)g_dynamic_arena.slots[entry.ram_slot].pageable !=
                     preferred_pageable) ||
                (entry.state == CUDA_MOE_TIER_VRAM_PROTECTED &&
                 !reclaimable_vram_backing) ||
                entry.last_call == g_moe_tiering.call_tick ||
                index == cuda_moe_tiering_entry_index(
                    current_layer, current_expert)) {
                continue;
            }
            const double score = cuda_moe_tiering_lfru(
                entry, g_moe_tiering.call_tick);
            if (score < best_score) {
                best_score = score;
                best_slot = (int)entry.ram_slot;
                best_entry = index;
            }
        }
        if (best_slot >= 0) {
            *victim_entry_out = best_entry;
            return best_slot;
        }
    }
    return -1;
}

