    g_moe_expert_cache.misses = 0;
    g_moe_expert_cache.admissions = 0;
    g_moe_expert_cache.evictions = 0;
    g_moe_expert_cache.direct_loads = 0;
    g_moe_expert_cache.requested = 0;
    g_moe_expert_cache.capacity = 0;
