static void cuda_moe_gather_release(void) {
    if (g_prefill_union_stats.calls != 0) {
        const double dedup_ratio =
            (double)g_prefill_union_stats.selected_slots /
            (double)g_prefill_union_stats.unique_experts;
        fprintf(stderr,
                "ds4: [prefill-union] final calls=%llu tokens=%llu selected_slots=%llu unique_experts=%llu dedup_ratio=%.9g max_tokens=%u max_union=%u arena_experts=%llu cache_hits=%llu cache_admissions=%llu direct_experts=%llu spex_experts=%llu nonresident_experts=%llu source_span_bytes=%llu arena_h2d_bytes=%llu cache_d2d_bytes=%llu upload_syncs=%llu\n",
                (unsigned long long)g_prefill_union_stats.calls,
                (unsigned long long)g_prefill_union_stats.tokens,
                (unsigned long long)g_prefill_union_stats.selected_slots,
                (unsigned long long)g_prefill_union_stats.unique_experts,
                dedup_ratio,
                g_prefill_union_stats.max_tokens,
                g_prefill_union_stats.max_union,
                (unsigned long long)g_prefill_union_stats.arena_experts,
                (unsigned long long)g_prefill_union_stats.cache_hit_experts,
                (unsigned long long)g_prefill_union_stats.cache_admitted_experts,
                (unsigned long long)g_prefill_union_stats.direct_experts,
                (unsigned long long)g_prefill_union_stats.spex_experts,
                (unsigned long long)g_prefill_union_stats.nonresident_experts,
                (unsigned long long)g_prefill_union_stats.source_span_bytes,
                (unsigned long long)g_prefill_union_stats.arena_h2d_bytes,
                (unsigned long long)g_prefill_union_stats.cache_d2d_bytes,
                (unsigned long long)g_prefill_union_stats.upload_syncs);
    }
    g_prefill_union_stats = {};
    if (g_prefill_wave_stats.activations != 0) {
        fprintf(stderr,
                "ds4: [prefill-waves] final activations=%llu layers=%llu waves=%llu max_wave=%u active_pairs=%llu unique_experts=%llu upload_waits=%llu failures=%llu\n",
                (unsigned long long)g_prefill_wave_stats.activations,
                (unsigned long long)g_prefill_wave_stats.layers,
                (unsigned long long)g_prefill_wave_stats.waves,
                g_prefill_wave_stats.max_wave,
                (unsigned long long)g_prefill_wave_stats.active_pairs,
                (unsigned long long)g_prefill_wave_stats.unique_experts,
                (unsigned long long)g_prefill_wave_stats.upload_waits,
                (unsigned long long)g_prefill_wave_stats.failures);
    }
    g_prefill_wave_stats = {};
    if (g_prefill_wave_overlap_stats.activations != 0) {
        fprintf(stderr,
                "ds4: [prefill-wave-overlap] final activations=%llu layers=%llu waves=%llu reuse_waits=%llu compute_records=%llu failures=%llu\n",
                (unsigned long long)g_prefill_wave_overlap_stats.activations,
                (unsigned long long)g_prefill_wave_overlap_stats.layers,
                (unsigned long long)g_prefill_wave_overlap_stats.waves,
                (unsigned long long)g_prefill_wave_overlap_stats.reuse_waits,
                (unsigned long long)g_prefill_wave_overlap_stats.compute_records,
                (unsigned long long)g_prefill_wave_overlap_stats.failures);
    }
    g_prefill_wave_overlap_stats = {};
    g_moe_selected_prepared.valid = 0;
    g_moe_last_selected.valid = 0;
    if (g_moe_gather.gate) (void)cudaFree(g_moe_gather.gate);
    if (g_moe_gather.up) (void)cudaFree(g_moe_gather.up);
    if (g_moe_gather.down) (void)cudaFree(g_moe_gather.down);
    if (g_moe_gather.slot) (void)cudaFree(g_moe_gather.slot);
    if (g_moe_gather.route_ptrs) (void)cudaFree(g_moe_gather.route_ptrs);
    if (g_moe_gather.wave_upload_ready) {
        (void)cudaEventDestroy(g_moe_gather.wave_upload_ready);
    }
    for (uint32_t i = 0; i < 2u; i++) {
        if (g_moe_gather.wave_gate[i]) (void)cudaFree(g_moe_gather.wave_gate[i]);
