    double prior_weight;
};

static int cuda_moe_prefill_vram_seed(
        cuda_moe_expert_cache *cache,
        uint32_t requested_per_layer,
        uint32_t requested_total,
        uint32_t floor_per_layer) {
    const uint32_t first_layer = 3u;
    const uint32_t routed_layers = CUDA_MOE_LAYER_COUNT - first_layer;
    const int global_mode = requested_total > 0u;
    const uint64_t requested_entries_64 = global_mode
        ? (uint64_t)requested_total
        : (uint64_t)requested_per_layer * routed_layers;
    const uint32_t requested_entries =
        requested_entries_64 <= UINT32_MAX ?
        (uint32_t)requested_entries_64 : UINT32_MAX;
    const double started = cuda_wall_sec();
    const char *reason = "contract";
    uint64_t uploaded_bytes = 0;
    double selected_prior_mass = 0.0;
    const int q1_0_exact_iq2_seed =
        cuda_q1_0_mixed_exact_iq2_resolver_requested();
    const int primary_mmap_source =
        q1_0_exact_iq2_seed;
    std::vector<cuda_moe_prefill_vram_seed_entry> selected;
    std::vector<cuda_moe_prefill_vram_seed_entry> global_ranked;

    if (!cache || requested_entries == 0u ||
        (global_mode && requested_per_layer != 0u) ||
        (!global_mode && floor_per_layer != 0u) ||
        (global_mode &&
         (uint64_t)floor_per_layer * routed_layers > requested_total) ||
        g_moe_tiering.mode != CUDA_MOE_TIER_ENFORCE ||
        g_moe_tiering.policy != CUDA_MOE_TIER_POLICY_MASS_LFRU ||
        !g_moe_tiering.compose_prefill_mass_tiering) {
        reason = "config-contract";
        goto failed;
    }
    if (!g_prefill_mass_observer.enabled ||
        !g_prefill_mass_observer.finalized ||
        !g_prefill_mass_observer.wrap_published) {
        reason = "observer-contract";
        goto failed;
    }
    if (!cache->device_slot_by_layer_expert ||
        !cache->route_upload_stream ||
        cache->capacity < requested_entries) {
        reason = "cache-capacity";
        fprintf(stderr,
                "ds4: [prefill-vram-seed-contract] cache_capacity=%u requested_entries=%u device_map=%d upload_stream=%d\n",
                cache->capacity, requested_entries,
                cache->device_slot_by_layer_expert ? 1 : 0,
                cache->route_upload_stream ? 1 : 0);
        goto failed;
    }
    if (g_dynamic_arena.snapshot_generation == 0 ||
        g_dynamic_arena.snapshot_generation !=
            g_moe_tiering.snapshot_generation ||
        g_dynamic_arena.n_layer != CUDA_MOE_LAYER_COUNT ||
        g_dynamic_arena.n_expert != 256u) {
        reason = "snapshot-contract";
        goto failed;
    }
    if (cuda_q1_0_snapshot_backing_requested() &&
        (g_primary_moe_geometry_map != g_model_host_base ||
         g_primary_moe_geometry_size != g_model_registered_size ||
         g_primary_moe_geometry_n_expert != 256u ||
         g_primary_moe_geometry.size() != CUDA_MOE_LAYER_COUNT)) {
        reason = "source-contract";
        goto failed;
    }
    if (q1_0_exact_iq2_seed &&
        !cuda_q1_0_snapshot_backing_requested() &&
        (g_dynamic_arena.backing != CUDA_DYNAMIC_ARENA_BACKING_PRIMARY ||
         g_dynamic_arena.model_map != g_model_host_base ||
         g_dynamic_arena.model_size != g_model_registered_size ||
         g_dynamic_arena.layers.size() != CUDA_MOE_LAYER_COUNT)) {
        reason = "source-contract";
        goto failed;
    }
    if (g_prefill_mass_observer.mass.size() !=
            (size_t)CUDA_MOE_LAYER_COUNT * 256u ||
        g_prefill_mass_observer.counts.size() !=
            (size_t)CUDA_MOE_LAYER_COUNT * 256u ||
        g_prefill_mass_observer.candidate.size() !=
            (size_t)CUDA_MOE_LAYER_COUNT * 256u ||
        cache->host_slot_by_layer_expert.size() !=
            (size_t)CUDA_MOE_LAYER_COUNT * 256u) {
        reason = "metadata-contract";
        goto failed;
    }

    reason = "rank";
    try {
        selected.reserve(requested_entries);
        if (global_mode) {
            global_ranked.reserve((size_t)routed_layers * 256u);
        }
        for (uint32_t layer = first_layer;
             layer < CUDA_MOE_LAYER_COUNT; layer++) {
            std::vector<cuda_moe_prefill_vram_seed_entry> ranked;
            ranked.reserve(256u);
            const uint32_t base = layer * 256u;
            for (uint32_t expert = 0; expert < 256u; expert++) {
                const uint32_t entry = base + expert;
                if ((!q1_0_exact_iq2_seed &&
                     !g_prefill_mass_observer.candidate[entry]) ||
                    g_prefill_mass_observer.counts[entry] == 0u) {
                    continue;
                }
                const cuda_dynamic_arena_binding &binding =
                    g_dynamic_arena.active[entry];
                if (!q1_0_exact_iq2_seed &&
                    !cuda_dynamic_arena_binding_valid(
                        g_dynamic_arena,
                        binding, layer, expert,
                        g_dynamic_arena.snapshot_generation,
                        DS4_GPU_ARENA_READY)) {
                    continue;
                }
                /* Keep the same mass definition used by the prefill snapshot:
                 * normalized gate weight accumulated over the request. Dividing
                 * by observations would favor rare high-weight spikes instead
                 * of the experts expected to save the most decode H2D traffic. */
                const double prior =
                    g_prefill_mass_observer.mass[entry];
                if (!isfinite(prior) || prior <= 0.0) continue;
                const double prior_weight = prior /
                    (double)g_prefill_mass_observer.counts[entry];
                if (!isfinite(prior_weight) || prior_weight <= 0.0) continue;
                ranked.push_back({entry, prior, prior_weight});
            }
            std::sort(ranked.begin(), ranked.end(),
                      [](const cuda_moe_prefill_vram_seed_entry &a,
                         const cuda_moe_prefill_vram_seed_entry &b) {
                          if (a.prior_mass != b.prior_mass) {
                              return a.prior_mass > b.prior_mass;
                          }
                          return a.entry < b.entry;
                      });
            const uint32_t layer_floor = global_mode
                ? floor_per_layer : requested_per_layer;
            if (ranked.size() < layer_floor) goto failed;
            for (uint32_t rank = 0; rank < layer_floor; rank++) {
                selected.push_back(ranked[rank]);
                selected_prior_mass += ranked[rank].prior_mass;
            }
            if (global_mode) {
                global_ranked.insert(global_ranked.end(),
                                     ranked.begin() + layer_floor,
                                     ranked.end());
            }
        }
        if (global_mode) {
            std::sort(global_ranked.begin(), global_ranked.end(),
                      [](const cuda_moe_prefill_vram_seed_entry &a,
                         const cuda_moe_prefill_vram_seed_entry &b) {
                          if (a.prior_mass != b.prior_mass) {
                              return a.prior_mass > b.prior_mass;
                          }
                          return a.entry < b.entry;
                      });
            const uint32_t remaining = requested_total -
                (uint32_t)selected.size();
            if (global_ranked.size() < remaining) goto failed;
            for (uint32_t rank = 0; rank < remaining; rank++) {
                selected.push_back(global_ranked[rank]);
                selected_prior_mass += global_ranked[rank].prior_mass;
            }
        }
    } catch (...) {
        reason = "metadata-allocation";
        goto failed;
    }
    if (selected.size() != requested_entries) goto failed;

    reason = "upload";
    {
        std::vector<int32_t> seed_map(
            (size_t)CUDA_MOE_LAYER_COUNT * 256u, -1);
        int upload_ok = 1;
        for (uint32_t slot = 0;
             upload_ok && slot < selected.size(); slot++) {
            const uint32_t entry = selected[slot].entry;
            const uint32_t layer = entry / 256u;
            const uint32_t expert = entry % 256u;
            const ds4_gpu_dynamic_arena_layer &geometry =
                cuda_q1_0_snapshot_backing_requested()
                    ? g_primary_moe_geometry[layer]
                    : g_dynamic_arena.layers[layer];
            const cuda_dynamic_arena_binding &binding =
                g_dynamic_arena.active[entry];
            if (geometry.gate_expert_bytes != cache->gate_expert_bytes ||
                geometry.up_expert_bytes != cache->gate_expert_bytes ||
                geometry.down_expert_bytes != cache->down_expert_bytes ||
                (!primary_mmap_source &&
                 binding.slot >= g_dynamic_arena.slots.size())) {
                reason = "geometry";
                upload_ok = 0;
                break;
            }
            const uint64_t gate_dst =
                (uint64_t)slot * cache->gate_expert_bytes;
            const uint64_t down_dst =
                (uint64_t)slot * cache->down_expert_bytes;
            const char *host_gate = NULL;
            const char *host_up = NULL;
            const char *host_down = NULL;
            if (primary_mmap_source) {
                const char *base = (const char *)(
                    cuda_q1_0_snapshot_backing_requested()
                        ? g_primary_moe_geometry_map
                        : g_model_host_base);
                host_gate = base + geometry.gate_offset +
                    (uint64_t)expert * geometry.gate_expert_bytes;
                host_up = base + geometry.up_offset +
                    (uint64_t)expert * geometry.up_expert_bytes;
                host_down = base + geometry.down_offset +
                    (uint64_t)expert * geometry.down_expert_bytes;
            } else {
                const cuda_dynamic_arena_slot &arena_slot =
                    g_dynamic_arena.slots[binding.slot];
                if (!arena_slot.host_ptr) {
                    reason = "source";
                    upload_ok = 0;
                    break;
                }
                host_gate = arena_slot.host_ptr;
                host_up = host_gate + cache->gate_expert_bytes;
                host_down = host_up + cache->gate_expert_bytes;
            }
            cudaError_t copy_error = cudaMemcpyAsync(
                cache->gate + gate_dst, host_gate,
                (size_t)cache->gate_expert_bytes, cudaMemcpyHostToDevice,
                cache->route_upload_stream);
            if (copy_error == cudaSuccess) {
                copy_error = cudaMemcpyAsync(
                    cache->up + gate_dst, host_up,
                    (size_t)cache->gate_expert_bytes, cudaMemcpyHostToDevice,
                    cache->route_upload_stream);
            }
            if (copy_error == cudaSuccess) {
                copy_error = cudaMemcpyAsync(
                    cache->down + down_dst, host_down,
                    (size_t)cache->down_expert_bytes, cudaMemcpyHostToDevice,
                    cache->route_upload_stream);
            }
            if (copy_error != cudaSuccess) {
                reason = "copy";
                fprintf(stderr,
                        "ds4: prefill VRAM seed copy failed source=%s layer=%u expert=%u error=%s\n",
                        primary_mmap_source ? "primary-mmap" : "primary-arena",
                        layer, expert, cudaGetErrorString(copy_error));
                (void)cudaGetLastError();
                upload_ok = 0;
                break;
            }
            seed_map[entry] = (int32_t)slot;
        }
        if (upload_ok &&
            cudaMemcpyAsync(cache->device_slot_by_layer_expert,
                            seed_map.data(),
                            seed_map.size() * sizeof(int32_t),
                            cudaMemcpyHostToDevice,
                            cache->route_upload_stream) != cudaSuccess) {
            reason = "map-copy";
            (void)cudaGetLastError();
            upload_ok = 0;
        }
        const cudaError_t upload_sync =
            cudaStreamSynchronize(cache->route_upload_stream);
        if (!upload_ok || upload_sync != cudaSuccess) {
            if (upload_ok) reason = "sync";
            (void)cudaGetLastError();
            goto failed;
        }
        cache->host_slot_by_layer_expert.swap(seed_map);
    }

    for (uint32_t slot = 0; slot < selected.size(); slot++) {
        const uint32_t entry_index = selected[slot].entry;
        const uint32_t layer = entry_index / 256u;
        const uint32_t expert = entry_index % 256u;
        const ds4_gpu_dynamic_arena_layer &geometry =
            cuda_q1_0_snapshot_backing_requested()
                ? g_primary_moe_geometry[layer]
                : g_dynamic_arena.layers[layer];
        cuda_moe_cache_slot &cache_entry = cache->slots[slot];
        cache_entry.key = {
            geometry.gate_offset +
                (uint64_t)expert * geometry.gate_expert_bytes,
            geometry.up_offset +
                (uint64_t)expert * geometry.up_expert_bytes,
            geometry.down_offset +
                (uint64_t)expert * geometry.down_expert_bytes
        };
        cache_entry.layer_key = geometry.gate_offset;
        cache_entry.age = ++cache->tick;
        cache_entry.layer_index = layer;
        cache_entry.expert_id = expert;
        cache_entry.layer_owned = 0;
        cache_entry.state = CUDA_MOE_CACHE_VALID;

        cuda_moe_tier_entry &tier = g_moe_tiering.entries[entry_index];
        tier.frequency = 1u;
        tier.last_call = 0u;
        /* Rank by cumulative request mass, but seed the decode EMA with one
         * synthetic observation in weight units so the initial request does
         * not make the cache permanently sticky. */
        tier.mass = selected[slot].prior_weight;
        tier.last_weight = (float)selected[slot].prior_weight;
        tier.state = CUDA_MOE_TIER_VRAM_PROTECTED;
    }
    cache->count = requested_entries;
    cache->admissions += requested_entries;
    g_moe_tiering.vram_promotions += requested_entries;
    g_moe_tiering.policy_free_promotions += requested_entries;
    uploaded_bytes = (uint64_t)requested_entries *
        (cache->gate_expert_bytes * 2ull + cache->down_expert_bytes);
    g_moe_tiering.snapshot_to_vram_bytes += uploaded_bytes;
    g_moe_tiering.ram_h2d_bytes += uploaded_bytes;
    fprintf(stderr,
            "ds4: [prefill-vram-seed-source] source=%s bytes=%llu semantics=one-time-exact-iq2\n",
            primary_mmap_source ? "primary-mmap" : "primary-arena",
            (unsigned long long)uploaded_bytes);
    if (global_mode) {
        fprintf(stderr,
                "ds4: [prefill-vram-seed-global] result=ok reason=ok requested_total=%u floor_per_layer=%u layers=%u entries=%u bytes=%llu seconds=%.3f failures=0 prior_mass=%.9g semantics=request-scoped-global-mass\n",
                requested_total, floor_per_layer, routed_layers,
                requested_entries, (unsigned long long)uploaded_bytes,
                cuda_wall_sec() - started, selected_prior_mass);
    } else {
        fprintf(stderr,
                "ds4: [prefill-vram-seed] result=ok reason=ok requested_per_layer=%u layers=%u entries=%u bytes=%llu seconds=%.3f failures=0 prior_mass=%.9g semantics=request-scoped-top-per-layer\n",
                requested_per_layer, routed_layers, requested_entries,
                (unsigned long long)uploaded_bytes,
                cuda_wall_sec() - started, selected_prior_mass);
    }
    return 1;

failed:
    g_moe_tiering.failures++;
    if (global_mode) {
        fprintf(stderr,
                "ds4: [prefill-vram-seed-global] result=failed reason=%s requested_total=%u floor_per_layer=%u layers=%u entries=0 bytes=0 seconds=%.3f failures=1 prior_mass=0 semantics=request-scoped-global-mass\n",
                reason, requested_total, floor_per_layer, routed_layers,
                cuda_wall_sec() - started);
    } else {
        fprintf(stderr,
                "ds4: [prefill-vram-seed] result=failed reason=%s requested_per_layer=%u layers=%u entries=0 bytes=0 seconds=%.3f failures=1 prior_mass=0 semantics=request-scoped-top-per-layer\n",
                reason, requested_per_layer, routed_layers,
                cuda_wall_sec() - started);
    }
    return 0;
}

static cuda_moe_expert_cache *cuda_moe_expert_cache_prepare(
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes) {
    const uint32_t requested = cuda_moe_expert_cache_requested();
    const int tier_mode = cuda_moe_tiering_mode_requested();
    const int compose_requested = cuda_moe_prefill_tier_compose_requested();
    const int compose_router_open =
        cuda_moe_prefill_tier_router_open_requested();
    const int promotion_probation_slots =
        cuda_quant_promotion_probation_slots_requested();
    const int promotion_q1_0 =
        cuda_q1_0_dynamic_promotion_requested();
    const int gpu_routes = cuda_moe_gpu_routes_requested();
    const int packed_copy_requested = cuda_moe_route_packed_copy_requested();
    const int prefill_vram_seed_per_layer =
        cuda_moe_prefill_vram_seed_per_layer_requested();
    const int prefill_vram_seed_total =
        cuda_moe_prefill_vram_seed_total_requested();
    const int prefill_vram_seed_floor_per_layer =
        cuda_moe_prefill_vram_seed_floor_per_layer_requested();
    uint64_t promotion_min_touches = 1u;
    double promotion_min_weight = 0.0;
    double promotion_min_mass = 0.0;
    uint64_t promotion_request_budget = 0u;
    uint64_t promotion_window_calls = 0u;
    uint64_t promotion_window_budget = 0u;
    if (promotion_probation_slots > 0 &&
        !cuda_quant_promotion_gate_config(
            promotion_q1_0,
            &promotion_min_touches, &promotion_min_weight,
            &promotion_min_mass, &promotion_request_budget,
            &promotion_window_calls, &promotion_window_budget)) {
        return NULL;
    }
    if (compose_requested > 0 && g_prefill_mass_observer.enabled &&
        (!g_prefill_mass_observer.finalized ||
         !g_prefill_mass_observer.wrap_published)) {
        return NULL;
    }
    if (tier_mode < 0 || compose_requested < 0 || compose_router_open < 0 ||
        promotion_probation_slots < 0 ||
        prefill_vram_seed_per_layer < 0 ||
        prefill_vram_seed_total < 0 ||
        prefill_vram_seed_floor_per_layer < 0 ||
        (tier_mode != CUDA_MOE_TIER_OFF && !gpu_routes)) {
        if (tier_mode != CUDA_MOE_TIER_OFF) {
            fprintf(stderr,
                    "ds4: expert tiering requires GPU-resident routes\n");
        }
        return NULL;
    }
    if ((prefill_vram_seed_per_layer > 0 ||
         prefill_vram_seed_total > 0) &&
        (tier_mode != CUDA_MOE_TIER_ENFORCE ||
         !compose_requested || !gpu_routes)) {
        fprintf(stderr,
                "ds4: prefill VRAM seed requires composed enforce tiering and GPU-resident routes\n");
        return NULL;
    }
    if ((prefill_vram_seed_per_layer > 0 &&
         prefill_vram_seed_total > 0) ||
        (prefill_vram_seed_floor_per_layer > 0 &&
         prefill_vram_seed_total == 0) ||
        (prefill_vram_seed_total > 0 &&
         (uint64_t)prefill_vram_seed_floor_per_layer *
             (CUDA_MOE_LAYER_COUNT - 3u) >
             (uint64_t)prefill_vram_seed_total)) {
        fprintf(stderr,
                "ds4: prefill VRAM seed mode/budget contract invalid\n");
        return NULL;
    }
    if (requested == 0) {
        if (g_moe_expert_cache.capacity != 0) cuda_moe_expert_cache_release();
        return NULL;
    }
    if (gate_expert_bytes == 0 || down_expert_bytes == 0 ||
        gate_expert_bytes > (UINT64_MAX - down_expert_bytes) / 2ull) {
        return NULL;
    }
    if (g_moe_expert_cache.capacity != 0 &&
        g_moe_expert_cache.requested == requested &&
        g_moe_expert_cache.gate_expert_bytes == gate_expert_bytes &&
        g_moe_expert_cache.down_expert_bytes == down_expert_bytes &&
        g_moe_expert_cache.packed_copy_requested ==
            (packed_copy_requested ? 1u : 0u) &&
        g_moe_expert_cache.prefill_vram_seed_per_layer ==
            (uint32_t)prefill_vram_seed_per_layer &&
        g_moe_expert_cache.prefill_vram_seed_total ==
            (uint32_t)prefill_vram_seed_total &&
        g_moe_expert_cache.prefill_vram_seed_floor_per_layer ==
            (uint32_t)prefill_vram_seed_floor_per_layer &&
        g_moe_tiering.mode == (cuda_moe_tier_mode)tier_mode &&
        g_moe_tiering.compose_prefill_mass_tiering == compose_requested &&
        g_moe_tiering.compose_router_open == compose_router_open &&
        g_iq1_promotion.requested_slots ==
            (uint32_t)promotion_probation_slots &&
        g_iq1_promotion.min_touches == promotion_min_touches &&
        g_iq1_promotion.min_weight == promotion_min_weight &&
        g_iq1_promotion.min_mass == promotion_min_mass &&
        g_iq1_promotion.request_budget == promotion_request_budget &&
        g_iq1_promotion.window_calls == promotion_window_calls &&
        g_iq1_promotion.window_budget == promotion_window_budget &&
        (tier_mode != CUDA_MOE_TIER_ENFORCE ||
         (g_moe_expert_cache.route_transient_gate &&
          g_moe_expert_cache.route_transient_up &&
          g_moe_expert_cache.route_transient_down))) {
        return &g_moe_expert_cache;
    }
    cuda_moe_expert_cache_release();

    const uint64_t per_expert = gate_expert_bytes * 2ull + down_expert_bytes;
    size_t free_b = 0;
    size_t total_b = 0;
    cudaError_t err = cudaMemGetInfo(&free_b, &total_b);
    if (err != cudaSuccess) {
        fprintf(stderr, "ds4: CUDA resident expert cache memory query failed: %s\n",
                cudaGetErrorString(err));
        (void)cudaGetLastError();
        return NULL;
    }
    uint64_t reserve = cuda_moe_expert_cache_reserve_bytes();
    if (total_b != 0 && reserve > (uint64_t)total_b / 2ull) reserve = (uint64_t)total_b / 2ull;
    uint32_t cap = 0;
    if ((uint64_t)free_b > reserve) {
        const uint64_t max_slots = ((uint64_t)free_b - reserve) / per_expert;
        cap = max_slots < requested ? (uint32_t)max_slots : requested;
    }
    if (cap == 0) {
        fprintf(stderr,
                "ds4: CUDA resident expert cache disabled: free %.2f GiB <= reserve %.2f GiB\n",
                (double)free_b / 1073741824.0, (double)reserve / 1073741824.0);
        return NULL;
    }

    while (cap != 0) {
        void *packed_base = NULL;
        void *gate = NULL;
        void *up = NULL;
        void *down = NULL;
        int32_t *device_map = NULL;
        uint64_t *device_routes = NULL;
        uint32_t *device_hit_mask = NULL;
        uint32_t *ready_host = NULL;
        uint32_t *failed_host = NULL;
        uint32_t *device_ready = NULL;
        uint32_t *device_failed = NULL;
        cuda_moe_route_request *request_host = NULL;
        cuda_moe_route_request *request_device = NULL;
        char *host_packed_base = NULL;
        char *host_gate = NULL;
        char *host_up = NULL;
        char *host_down = NULL;
        char *transient_packed_base = NULL;
        char *transient_gate = NULL;
        char *transient_up = NULL;
        char *transient_down = NULL;
        cudaStream_t route_stream = NULL;
        if (packed_copy_requested) {
            const uint64_t gate_plane_bytes =
                (uint64_t)cap * gate_expert_bytes;
            const uint64_t down_plane_bytes =
                (uint64_t)cap * down_expert_bytes;
            if (gate_plane_bytes >
                    (UINT64_MAX - down_plane_bytes) / 2ull) {
                err = cudaErrorMemoryAllocation;
            } else {
                const uint64_t packed_bytes =
                    gate_plane_bytes * 2ull + down_plane_bytes;
                err = cudaMalloc(&packed_base, (size_t)packed_bytes);
            }
            if (err == cudaSuccess) {
                gate = packed_base;
                up = (char *)packed_base + gate_plane_bytes;
                down = (char *)packed_base + gate_plane_bytes * 2ull;
            }
        } else {
            err = cudaMalloc(&gate, (size_t)((uint64_t)cap * gate_expert_bytes));
            if (err == cudaSuccess) err = cudaMalloc(&up, (size_t)((uint64_t)cap * gate_expert_bytes));
            if (err == cudaSuccess) err = cudaMalloc(&down, (size_t)((uint64_t)cap * down_expert_bytes));
        }
        if (err == cudaSuccess && gpu_routes) {
            err = cudaMalloc((void **)&device_map,
                (size_t)CUDA_MOE_LAYER_COUNT * 256u * sizeof(int32_t));
        }
        if (err == cudaSuccess && gpu_routes) {
            err = cudaMalloc((void **)&device_routes,
                (size_t)CUDA_MOE_ROUTE_COUNT * 3u * sizeof(uint64_t));
        }
        if (err == cudaSuccess && gpu_routes) {
            err = cudaMalloc((void **)&device_hit_mask, sizeof(uint32_t));
        }
        if (err == cudaSuccess && gpu_routes) {
            err = cudaHostAlloc((void **)&ready_host, sizeof(uint32_t),
                                cudaHostAllocMapped);
        }
        if (err == cudaSuccess && gpu_routes) {
            err = cudaHostGetDevicePointer((void **)&device_ready, ready_host, 0);
        }
        if (err == cudaSuccess && gpu_routes) {
            err = cudaHostAlloc((void **)&failed_host, sizeof(uint32_t),
                                cudaHostAllocMapped);
        }
        if (err == cudaSuccess && gpu_routes) {
            err = cudaHostGetDevicePointer((void **)&device_failed, failed_host, 0);
        }
        if (err == cudaSuccess && gpu_routes) {
            err = cudaHostAlloc((void **)&request_host, sizeof(*request_host),
                                cudaHostAllocMapped);
        }
        if (err == cudaSuccess && gpu_routes) {
            err = cudaHostGetDevicePointer((void **)&request_device, request_host, 0);
        }
        if (err == cudaSuccess && gpu_routes && packed_copy_requested) {
            const uint64_t gate_plane_bytes =
                (uint64_t)CUDA_MOE_ROUTE_COUNT * gate_expert_bytes;
            const uint64_t down_plane_bytes =
                (uint64_t)CUDA_MOE_ROUTE_COUNT * down_expert_bytes;
            if (gate_plane_bytes >
                    (UINT64_MAX - down_plane_bytes) / 2ull) {
                err = cudaErrorMemoryAllocation;
            } else {
                const uint64_t packed_bytes =
                    gate_plane_bytes * 2ull + down_plane_bytes;
                err = cudaHostAlloc((void **)&host_packed_base,
                    (size_t)packed_bytes, cudaHostAllocDefault);
            }
            if (err == cudaSuccess) {
                host_gate = host_packed_base;
                host_up = host_packed_base + gate_plane_bytes;
                host_down = host_packed_base + gate_plane_bytes * 2ull;
            }
        }
        if (err == cudaSuccess && gpu_routes && !packed_copy_requested) {
            err = cudaHostAlloc((void **)&host_gate,
                (size_t)CUDA_MOE_ROUTE_COUNT * gate_expert_bytes, cudaHostAllocDefault);
        }
        if (err == cudaSuccess && gpu_routes && !packed_copy_requested) {
            err = cudaHostAlloc((void **)&host_up,
                (size_t)CUDA_MOE_ROUTE_COUNT * gate_expert_bytes, cudaHostAllocDefault);
        }
        if (err == cudaSuccess && gpu_routes && !packed_copy_requested) {
            err = cudaHostAlloc((void **)&host_down,
                (size_t)CUDA_MOE_ROUTE_COUNT * down_expert_bytes, cudaHostAllocDefault);
        }
        if (err == cudaSuccess && tier_mode == CUDA_MOE_TIER_ENFORCE &&
            packed_copy_requested) {
            const uint64_t gate_plane_bytes =
                (uint64_t)CUDA_MOE_ROUTE_COUNT * gate_expert_bytes;
            const uint64_t down_plane_bytes =
                (uint64_t)CUDA_MOE_ROUTE_COUNT * down_expert_bytes;
            if (gate_plane_bytes >
                    (UINT64_MAX - down_plane_bytes) / 2ull) {
                err = cudaErrorMemoryAllocation;
            } else {
                const uint64_t packed_bytes =
                    gate_plane_bytes * 2ull + down_plane_bytes;
                err = cudaMalloc((void **)&transient_packed_base,
                    (size_t)packed_bytes);
            }
            if (err == cudaSuccess) {
                transient_gate = transient_packed_base;
                transient_up = transient_packed_base + gate_plane_bytes;
                transient_down = transient_packed_base +
                    gate_plane_bytes * 2ull;
            }
        }
        if (err == cudaSuccess && tier_mode == CUDA_MOE_TIER_ENFORCE &&
            !packed_copy_requested) {
            err = cudaMalloc((void **)&transient_gate,
                (size_t)CUDA_MOE_ROUTE_COUNT * gate_expert_bytes);
        }
        if (err == cudaSuccess && tier_mode == CUDA_MOE_TIER_ENFORCE &&
            !packed_copy_requested) {
            err = cudaMalloc((void **)&transient_up,
                (size_t)CUDA_MOE_ROUTE_COUNT * gate_expert_bytes);
        }
        if (err == cudaSuccess && tier_mode == CUDA_MOE_TIER_ENFORCE &&
            !packed_copy_requested) {
            err = cudaMalloc((void **)&transient_down,
                (size_t)CUDA_MOE_ROUTE_COUNT * down_expert_bytes);
        }
        if (err == cudaSuccess && gpu_routes) {
            err = cudaStreamCreateWithFlags(&route_stream, cudaStreamNonBlocking);
        }
        if (err == cudaSuccess) {
            try {
                g_moe_expert_cache.slots.resize(cap);
                if (gpu_routes) {
                    g_moe_expert_cache.host_slot_by_layer_expert.assign(
                        (size_t)CUDA_MOE_LAYER_COUNT * 256u, -1);
                }
            } catch (...) {
                err = cudaErrorMemoryAllocation;
            }
        }
        if (err == cudaSuccess) {
            g_moe_expert_cache.packed_base = (char *)packed_base;
            g_moe_expert_cache.gate = (char *)gate;
            g_moe_expert_cache.up = (char *)up;
            g_moe_expert_cache.down = (char *)down;
            g_moe_expert_cache.gate_expert_bytes = gate_expert_bytes;
            g_moe_expert_cache.down_expert_bytes = down_expert_bytes;
            g_moe_expert_cache.requested = requested;
            g_moe_expert_cache.capacity = cap;
            g_moe_expert_cache.prefill_vram_seed_per_layer =
                (uint32_t)prefill_vram_seed_per_layer;
            g_moe_expert_cache.prefill_vram_seed_total =
                (uint32_t)prefill_vram_seed_total;
            g_moe_expert_cache.prefill_vram_seed_floor_per_layer =
                (uint32_t)prefill_vram_seed_floor_per_layer;
            g_moe_expert_cache.device_slot_by_layer_expert = device_map;
            g_moe_expert_cache.device_route_ptrs = device_routes;
            g_moe_expert_cache.device_route_hit_mask = device_hit_mask;
            g_moe_expert_cache.route_ready_host = ready_host;
            g_moe_expert_cache.route_failed_host = failed_host;
            g_moe_expert_cache.device_route_ready_sequence = device_ready;
            g_moe_expert_cache.device_route_failed_sequence = device_failed;
            g_moe_expert_cache.route_request_host = request_host;
            g_moe_expert_cache.route_request_device = request_device;
            g_moe_expert_cache.route_host_packed_base = host_packed_base;
            g_moe_expert_cache.route_host_gate = host_gate;
            g_moe_expert_cache.route_host_up = host_up;
            g_moe_expert_cache.route_host_down = host_down;
            g_moe_expert_cache.route_transient_packed_base =
                transient_packed_base;
            g_moe_expert_cache.route_transient_gate = transient_gate;
            g_moe_expert_cache.route_transient_up = transient_up;
            g_moe_expert_cache.route_transient_down = transient_down;
            g_moe_expert_cache.packed_copy_requested =
                packed_copy_requested ? 1u : 0u;
            g_moe_expert_cache.packed_resident_alloc =
                packed_base ? 1u : 0u;
            g_moe_expert_cache.packed_route_host_alloc =
                host_packed_base ? 1u : 0u;
            g_moe_expert_cache.packed_transient_alloc =
                transient_packed_base ? 1u : 0u;
            g_moe_expert_cache.route_upload_stream = route_stream;
            g_moe_expert_cache.route_stop = 0;
            g_moe_expert_cache.route_worker_ready = 0;
            g_moe_expert_cache.route_worker_failed = 0;
            (void)cudaGetDevice(&g_moe_expert_cache.route_device);
            if (!cuda_moe_tiering_prepare()) {
                fprintf(stderr, "ds4: expert tiering preparation failed\n");
                cuda_moe_expert_cache_release();
                return NULL;
            }
            cuda_moe_expert_cache_invalidate();
            if ((prefill_vram_seed_per_layer > 0 ||
                 prefill_vram_seed_total > 0) &&
                !cuda_moe_prefill_vram_seed(
                    &g_moe_expert_cache,
                    (uint32_t)prefill_vram_seed_per_layer,
                    (uint32_t)prefill_vram_seed_total,
                    (uint32_t)prefill_vram_seed_floor_per_layer)) {
                fprintf(stderr, "ds4: prefill VRAM seed failed\n");
                cuda_moe_expert_cache_release();
                return NULL;
            }
            if (gpu_routes &&
                os_thread_create(&g_moe_expert_cache.route_thread,
                                 cuda_moe_route_worker,
                                 &g_moe_expert_cache) != 0) {
                fprintf(stderr, "ds4: CUDA GPU-resident route worker creation failed\n");
                cuda_moe_expert_cache_release();
                return NULL;
            }
            g_moe_expert_cache.route_thread_started = gpu_routes ? 1 : 0;
            if (gpu_routes) {
                const double ready_deadline = cuda_wall_sec() + 2.0;
                while (!g_moe_expert_cache.route_worker_ready &&
                       !g_moe_expert_cache.route_worker_failed &&
                       cuda_wall_sec() < ready_deadline) {
#ifdef _WIN32
                    (void)SwitchToThread();
#else
                    usleep(0);
#endif
                }
                if (!g_moe_expert_cache.route_worker_ready) {
                    fprintf(stderr, "ds4: CUDA GPU-resident route worker failed to initialize\n");
                    cuda_moe_expert_cache_release();
                    return NULL;
                }
            }
            const uint64_t startup_reserve = cuda_model_stream_reserve_bytes();
            g_model_expert_cache_ready = 1;
            const uint64_t runtime_reserve = cuda_model_stream_reserve_bytes();
            fprintf(stderr,
                    "ds4: CUDA resident expert cache ready: %u/%u experts, %.2f MiB/expert, %.2f GiB total\n",
                    cap, requested, (double)per_expert / 1048576.0,
                    (double)((uint64_t)cap * per_expert) / 1073741824.0);
            if (gpu_routes) {
                fprintf(stderr,
                        "ds4: CUDA GPU-resident route resolver active: exact miss worker, %u slots\n",
                        cap);
                if (packed_copy_requested) {
                    fprintf(stderr,
                            "ds4: CUDA route packed H2D copy active: gate_bytes=%llu down_bytes=%llu submissions_per_expert=2 resident_gate_pitch=%llu transient_gate_pitch=%llu\n",
                            (unsigned long long)gate_expert_bytes,
                            (unsigned long long)down_expert_bytes,
                            (unsigned long long)((uint64_t)cap * gate_expert_bytes),
                            (unsigned long long)((uint64_t)CUDA_MOE_ROUTE_COUNT * gate_expert_bytes));
                }
            }
            if (startup_reserve != runtime_reserve) {
                fprintf(stderr,
                        "ds4: CUDA stream runtime reserve activated: %.2f GiB -> %.2f GiB\n",
                        (double)startup_reserve / 1073741824.0,
                        (double)runtime_reserve / 1073741824.0);
            }
            return &g_moe_expert_cache;
        }
        const char *why = cudaGetErrorString(err);
        (void)cudaGetLastError();
        g_moe_expert_cache.slots.clear();
        if (packed_base) {
            (void)cudaFree(packed_base);
        } else {
            if (gate) (void)cudaFree(gate);
            if (up) (void)cudaFree(up);
            if (down) (void)cudaFree(down);
        }
        if (device_map) (void)cudaFree(device_map);
        if (device_routes) (void)cudaFree(device_routes);
        if (device_hit_mask) (void)cudaFree(device_hit_mask);
        if (ready_host) (void)cudaFreeHost(ready_host);
        if (failed_host) (void)cudaFreeHost(failed_host);
        if (request_host) (void)cudaFreeHost(request_host);
        if (host_packed_base) {
            (void)cudaFreeHost(host_packed_base);
        } else {
            if (host_gate) (void)cudaFreeHost(host_gate);
            if (host_up) (void)cudaFreeHost(host_up);
            if (host_down) (void)cudaFreeHost(host_down);
        }
        if (transient_packed_base) {
            (void)cudaFree(transient_packed_base);
        } else {
            if (transient_gate) (void)cudaFree(transient_gate);
            if (transient_up) (void)cudaFree(transient_up);
            if (transient_down) (void)cudaFree(transient_down);
        }
        if (route_stream) (void)cudaStreamDestroy(route_stream);
        const uint32_t release = (cap + 9u) / 10u;
        const uint32_t next = cap > release ? cap - release : 0;
        fprintf(stderr,
                "ds4: CUDA resident expert cache allocation failed at %u slots: %s; retry=%u\n",
                cap, why, next);
        cap = next;
    }
    cuda_moe_expert_cache_release();
    return NULL;
}

static int cuda_moe_expert_cache_find(
        cuda_moe_expert_cache *cache,
        const cuda_moe_cache_key &key) {
    if (!cache) return -1;
    for (uint32_t i = 0; i < cache->capacity; i++) {
        const cuda_moe_cache_slot &slot = cache->slots[i];
        if (slot.state == CUDA_MOE_CACHE_VALID &&
            slot.key.gate_src == key.gate_src &&
            slot.key.up_src == key.up_src &&
            slot.key.down_src == key.down_src) {
            return (int)i;
        }
    }
    return -1;
}

static int cuda_moe_expert_cache_lru_slot(
        cuda_moe_expert_cache *cache,
        const std::vector<uint8_t> &claimed) {
    if (!cache || claimed.size() < cache->capacity) return -1;
    for (uint32_t i = 0; i < cache->capacity; i++) {
        if (!claimed[i] && cache->slots[i].state == CUDA_MOE_CACHE_EMPTY) return (int)i;
    }
    int best = -1;
    uint64_t best_age = UINT64_MAX;
    for (uint32_t i = 0; i < cache->capacity; i++) {
        const cuda_moe_cache_slot &slot = cache->slots[i];
        if (claimed[i] || slot.state != CUDA_MOE_CACHE_VALID) continue;
        if (slot.age < best_age) {
            best = (int)i;
            best_age = slot.age;
        }
    }
    return best;
}

static int cuda_moe_route_worker_pick_slot(
        cuda_moe_expert_cache *cache,
        const uint8_t *claimed) {
    if (!cache || !claimed) return -1;
    for (uint32_t i = 0; i < cache->capacity; i++) {
        if (!claimed[i] && cache->slots[i].state == CUDA_MOE_CACHE_EMPTY) {
            return (int)i;
        }
    }
    int best = -1;
    uint64_t best_age = UINT64_MAX;
    for (uint32_t i = 0; i < cache->capacity; i++) {
        const cuda_moe_cache_slot &slot = cache->slots[i];
        if (claimed[i] || slot.state != CUDA_MOE_CACHE_VALID) continue;
        if (slot.age < best_age) {
            best = (int)i;
            best_age = slot.age;
        }
    }
    return best;
}

static int cuda_moe_route_copy_expert_h2d_async(
        cuda_moe_expert_cache *cache,
        char *dst_gate,
        char *dst_up,
        char *dst_down,
        uint64_t dst_pitch,
        const char *host_gate,
        const char *host_up,
        const char *host_down,
        uint64_t src_pitch) {
    if (!cache || !cache->packed_copy_requested ||
        cache->gate_expert_bytes == 0 ||
        cache->down_expert_bytes == 0 ||
        !dst_gate || !dst_up || !dst_down ||
        !host_gate || !host_up || !host_down ||
        dst_pitch == 0 || src_pitch == 0) {
        return 0;
    }
    if (dst_up != dst_gate + dst_pitch ||
        host_up != host_gate + src_pitch) {
        fprintf(stderr,
                "ds4: CUDA route packed H2D copy refused: gate/up layout is not contiguous\n");
        return 0;
    }
    if (cudaMemcpy2DAsync(dst_gate, (size_t)dst_pitch,
                          host_gate, (size_t)src_pitch,
                          (size_t)cache->gate_expert_bytes, 2u,
                          cudaMemcpyHostToDevice,
                          cache->route_upload_stream) != cudaSuccess ||
        cudaMemcpyAsync(dst_down, host_down,
                        (size_t)cache->down_expert_bytes,
                        cudaMemcpyHostToDevice,
                        cache->route_upload_stream) != cudaSuccess) {
        (void)cudaGetLastError();
        return 0;
    }
    cache->packed_copy_experts++;
    cache->packed_copy_submissions += 2ull;
    cache->packed_copy_bytes +=
        cache->gate_expert_bytes * 2ull + cache->down_expert_bytes;
    return 1;
}

static int cuda_moe_route_legacy_copy_expert_h2d_async(
        cuda_moe_expert_cache *cache,
        char *dst_gate,
        char *dst_up,
        char *dst_down,
        const char *host_gate,
        const char *host_up,
        const char *host_down) {
    if (!cache || !dst_gate || !dst_up || !dst_down ||
        !host_gate || !host_up || !host_down) {
        return 0;
    }
    if (cudaMemcpyAsync(dst_gate, host_gate,
                        (size_t)cache->gate_expert_bytes,
                        cudaMemcpyHostToDevice,
                        cache->route_upload_stream) != cudaSuccess ||
        cudaMemcpyAsync(dst_up, host_up,
                        (size_t)cache->gate_expert_bytes,
                        cudaMemcpyHostToDevice,
                        cache->route_upload_stream) != cudaSuccess ||
        cudaMemcpyAsync(dst_down, host_down,
                        (size_t)cache->down_expert_bytes,
                        cudaMemcpyHostToDevice,
                        cache->route_upload_stream) != cudaSuccess) {
        (void)cudaGetLastError();
        return 0;
    }
    cache->legacy_copy_submissions += 3ull;
    return 1;
}

static double cuda_moe_tiering_mass_lfru_score(
        const cuda_moe_tier_entry &entry) {
    const uint64_t age = g_moe_tiering.call_tick > entry.last_call ?
        g_moe_tiering.call_tick - entry.last_call : 0;
    const double clock = g_moe_tiering.policy_clock_calls ?
        (double)g_moe_tiering.policy_clock_calls : 1.0;
    const double recency = 1.0 / (1.0 + (double)age / clock);
    const double frequency = 1.0 + log1p((double)entry.frequency);
    return entry.mass * frequency * recency;
}

static int cuda_moe_tiering_pick_vram_slot(
        cuda_moe_expert_cache *cache, const uint8_t *claimed,
        const cuda_moe_tier_entry &candidate) {
    if (candidate.promoted_from_iq1_cold) {
        if (!candidate.has_2bit_ram) return -1;
        if (g_moe_tiering.call_tick < candidate.vram_eligible_after_call) {
            g_iq1_promotion.next_token_waits++;
            return -1;
        }
    }
    const uint32_t min_frequency =
        g_moe_tiering.policy == CUDA_MOE_TIER_POLICY_MASS_LFRU ?
        g_moe_tiering.policy_min_frequency : 2u;
    if (candidate.frequency < min_frequency) {
        g_moe_tiering.policy_min_frequency_skips++;
        return -1;
    }
    for (uint32_t slot = 0; slot < cache->capacity; slot++) {
        if (!claimed[slot] &&
            cache->slots[slot].state == CUDA_MOE_CACHE_EMPTY) {
            g_moe_tiering.policy_free_promotions++;
            return (int)slot;
        }
    }
    if (g_moe_tiering.policy == CUDA_MOE_TIER_POLICY_SECOND_TOUCH) {
        const int slot = cuda_moe_route_worker_pick_slot(cache, claimed);
        if (slot >= 0) g_moe_tiering.policy_replacements++;
        return slot;
    }

    const uint64_t epoch = g_moe_tiering.call_tick /
        (uint64_t)g_moe_tiering.policy_clock_calls;
    if (epoch != g_moe_tiering.policy_epoch) {
        const int completed_epoch =
            g_moe_tiering.policy_epoch != UINT64_MAX;
        if (g_moe_tiering.policy_adaptive_budget && completed_epoch) {
            const uint64_t budget_skips_delta =
                g_moe_tiering.policy_budget_skips >=
                    g_moe_tiering.policy_adaptive_last_budget_skips ?
                g_moe_tiering.policy_budget_skips -
                    g_moe_tiering.policy_adaptive_last_budget_skips : 0ull;
            const uint64_t replacements_delta =
                g_moe_tiering.policy_replacements >=
                    g_moe_tiering.policy_adaptive_last_replacements ?
                g_moe_tiering.policy_replacements -
                    g_moe_tiering.policy_adaptive_last_replacements : 0ull;
            g_moe_tiering.policy_adaptive_last_budget_skips =
                g_moe_tiering.policy_budget_skips;
            g_moe_tiering.policy_adaptive_last_replacements =
                g_moe_tiering.policy_replacements;
            g_moe_tiering.policy_adaptive_last_budget_skips_delta =
                budget_skips_delta;
            g_moe_tiering.policy_adaptive_last_replacements_delta =
                replacements_delta;
            if (budget_skips_delta >=
                    (uint64_t)g_moe_tiering.policy_adaptive_pressure_threshold &&
                replacements_delta >=
                    (uint64_t)g_moe_tiering.policy_replacement_budget) {
                g_moe_tiering.policy_adaptive_pressure_epochs++;
                g_moe_tiering.policy_adaptive_quiet_epochs = 0ull;
                if (g_moe_tiering.policy_replacement_budget <
                        g_moe_tiering.policy_adaptive_budget_max) {
                    uint32_t next_budget =
                        g_moe_tiering.policy_replacement_budget +
                        g_moe_tiering.policy_adaptive_budget_step;
                    if (next_budget <
                            g_moe_tiering.policy_replacement_budget ||
                        next_budget >
                            g_moe_tiering.policy_adaptive_budget_max) {
                        next_budget =
                            g_moe_tiering.policy_adaptive_budget_max;
                    }
                    if (next_budget !=
                            g_moe_tiering.policy_replacement_budget) {
                        g_moe_tiering.policy_replacement_budget = next_budget;
                        g_moe_tiering.policy_adaptive_budget_ups++;
                    }
                }
            } else if (budget_skips_delta == 0ull) {
                g_moe_tiering.policy_adaptive_quiet_epochs++;
                if (g_moe_tiering.policy_adaptive_quiet_epochs >= 2ull &&
                    g_moe_tiering.policy_replacement_budget >
                        g_moe_tiering.policy_adaptive_budget_min) {
                    const uint32_t step =
                        g_moe_tiering.policy_adaptive_budget_step;
                    g_moe_tiering.policy_replacement_budget =
                        g_moe_tiering.policy_replacement_budget >
                            g_moe_tiering.policy_adaptive_budget_min + step ?
                        g_moe_tiering.policy_replacement_budget - step :
                        g_moe_tiering.policy_adaptive_budget_min;
                    g_moe_tiering.policy_adaptive_budget_downs++;
                    g_moe_tiering.policy_adaptive_quiet_epochs = 0ull;
                }
            } else {
                g_moe_tiering.policy_adaptive_quiet_epochs = 0ull;
            }
        }
        g_moe_tiering.policy_epoch = epoch;
        g_moe_tiering.policy_budget_remaining =
            g_moe_tiering.policy_replacement_budget;
        g_moe_tiering.policy_epochs++;
    }
    if (g_moe_tiering.policy_budget_remaining == 0u) {
        g_moe_tiering.policy_budget_skips++;
        return -1;
    }

    int victim_slot = -1;
    double victim_score = 1.0e300;
    for (uint32_t slot = 0; slot < cache->capacity; slot++) {
        const cuda_moe_cache_slot &cache_entry = cache->slots[slot];
        if (claimed[slot] || cache_entry.state != CUDA_MOE_CACHE_VALID ||
            cache_entry.layer_index >= CUDA_MOE_LAYER_COUNT ||
            cache_entry.expert_id >= 256u) {
            continue;
        }
        const cuda_moe_tier_entry &tier_entry = g_moe_tiering.entries[
            cuda_moe_tiering_entry_index(
                cache_entry.layer_index, cache_entry.expert_id)];
        if (tier_entry.state != CUDA_MOE_TIER_VRAM_PROTECTED) continue;
        const double score = cuda_moe_tiering_mass_lfru_score(tier_entry);
        if (score < victim_score) {
            victim_score = score;
            victim_slot = (int)slot;
        }
    }
    if (victim_slot < 0) {
        g_moe_tiering.policy_score_skips++;
        return -1;
    }
    const double candidate_score =
        cuda_moe_tiering_mass_lfru_score(candidate);
    if (candidate_score <
            victim_score * g_moe_tiering.policy_hysteresis) {
        g_moe_tiering.policy_score_skips++;
        return -1;
    }
    g_moe_tiering.policy_budget_remaining--;
    g_moe_tiering.policy_replacements++;
    return victim_slot;
}

static int cuda_moe_tiering_enforce_request(
        cuda_moe_expert_cache *cache,
        const cuda_moe_route_request &request,
        uint8_t *claimed) {
    if (!cache || !claimed ||
        g_moe_tiering.mode != CUDA_MOE_TIER_ENFORCE ||
        !cache->route_transient_gate || !cache->route_transient_up ||
        !cache->route_transient_down) {
        fprintf(stderr,
                "ds4: [tiering-enforce] result=refused layer=%u sequence=%u "
                "cache=%d claimed=%d mode=%u gate=%d up=%d down=%d\n",
                request.layer_index, request.sequence, cache != NULL,
                claimed != NULL, (unsigned)g_moe_tiering.mode,
                cache && cache->route_transient_gate,
                cache && cache->route_transient_up,
                cache && cache->route_transient_down);
        return 0;
    }
    uint32_t admitted[CUDA_MOE_ROUTE_COUNT] = {0};
    uint32_t admitted_count = 0;
    int ok = 1;
    const char *failure_reason = "none";
    if (g_moe_tiering.compose_prefill_mass_tiering &&
        g_dynamic_arena.snapshot_generation !=
            g_moe_tiering.snapshot_generation) {
        g_moe_tiering.failures++;
        fprintf(stderr,
                "ds4: [tiering-enforce] result=snapshot-generation-mismatch "
                "layer=%u sequence=%u arena=%llu tier=%llu\n",
                request.layer_index, request.sequence,
                (unsigned long long)g_dynamic_arena.snapshot_generation,
                (unsigned long long)g_moe_tiering.snapshot_generation);
        return 0;
    }
    for (uint32_t miss = 0; ok && miss < request.miss_count; miss++) {
        const uint32_t route = request.miss_routes[miss];
        if (route >= request.route_count) {
            failure_reason = "route-oob";
            ok = 0;
            break;
        }
        const int32_t expert_i = request.selected[route];
        if (expert_i < 0 || expert_i >= 256) {
            failure_reason = "expert-oob";
            ok = 0;
            break;
        }
        const uint32_t expert = (uint32_t)expert_i;
        if (g_sparse_bake_active &&
            !cuda_sparse_bake_expert_retained(request.layer_index, expert)) {
            g_sparse_bake_route_rejections++;
            fprintf(stderr,
                    "ds4: sparse bake rejected tiering route miss "
                    "layer=%u seq=%u route=%u expert=%u\n",
                    request.layer_index, request.sequence, route, expert);
            g_moe_tiering.failures++;
            failure_reason = "sparse-rejected";
            ok = 0;
            break;
        }
        cuda_moe_tier_entry &tier = g_moe_tiering.entries[
            cuda_moe_tiering_entry_index(request.layer_index, expert)];

        char *host_gate = NULL;
        char *host_up = NULL;
        char *host_down = NULL;
        int from_nested = 0;
        if (cuda_nested_residual_gpu_cache_requested() &&
            cuda_nested_residual_layer_required(request.layer_index)) {
            if (cuda_nested_residual_gpu_join_requested()) {
                from_nested = 1;
            } else {
                host_gate = cache->route_host_gate +
                    (uint64_t)miss * cache->gate_expert_bytes;
                host_up = cache->route_host_up +
                    (uint64_t)miss * cache->gate_expert_bytes;
                host_down = cache->route_host_down +
                    (uint64_t)miss * cache->down_expert_bytes;
                from_nested = cuda_nested_residual_fill_route_host_exact(
                    request.layer_index, expert,
                    request.gate_offset, request.up_offset, request.down_offset,
                    cache->gate_expert_bytes, cache->down_expert_bytes,
                    host_gate, host_up, host_down);
                if (from_nested != 1) {
                    failure_reason = "nested-exact";
                    ok = 0;
                    break;
                }
            }
        }
        const int from_snapshot = !from_nested &&
            cuda_moe_tiering_snapshot_ram_ptrs(
            request.layer_index, expert,
            &host_gate, &host_up, &host_down);
        const int from_probation = !from_nested && !from_snapshot &&
            cuda_moe_tiering_ram_ptrs(
                request.layer_index, expert,
                &host_gate, &host_up, &host_down);
        int have_ram = from_nested || from_snapshot || from_probation;
        if (from_snapshot) {
            g_moe_tiering.snapshot_backing_hits++;
        } else if (from_probation) {
            g_iq1_promotion.probation_ram_hits++;
        } else if (g_moe_tiering.compose_prefill_mass_tiering) {
            g_moe_tiering.snapshot_backing_misses++;
            if (!g_moe_tiering.compose_router_open) {
                g_moe_tiering.forbidden_cold_ssd_to_vram++;
                g_moe_tiering.failures++;
                failure_reason = "snapshot-miss";
                ok = 0;
                break;
            }
        }
        if (!have_ram &&
            (!g_moe_tiering.compose_prefill_mass_tiering ||
             g_moe_tiering.compose_router_open) &&
            tier.state == CUDA_MOE_TIER_SSD_COLD) {
            /* Mixed 5+1 keeps the five high-weight routes exact. An open
             * snapshot miss must first enter the pinned probation pool;
             * only the minimum-weight sixth route executes as IQ1_S and is
             * staged for a later token by the mixed path. */
            (void)cuda_moe_tiering_load_to_ram(
                request, request.layer_index, expert);
            have_ram = cuda_moe_tiering_ram_ptrs(
                request.layer_index, expert,
                &host_gate, &host_up, &host_down);
        }
        if (!have_ram &&
            (!g_moe_tiering.compose_prefill_mass_tiering ||
             g_moe_tiering.compose_router_open) &&
            tier.state != CUDA_MOE_TIER_SSD_COLD) {
            if (tier.state == CUDA_MOE_TIER_VRAM_PROTECTED) {
                /* A protected entry must have been resolved as a device-map
                 * hit before the miss worker. Never create a second resident
                 * slot for the same expert if that map invariant is broken. */
                g_moe_tiering.failures++;
                failure_reason = "vram-map-miss";
                ok = 0;
                break;
            }
            tier.state = CUDA_MOE_TIER_SSD_COLD;
            tier.ram_slot = UINT32_MAX;
            tier.ram_generation = 0;
            (void)cuda_moe_tiering_load_to_ram(
                request, request.layer_index, expert);
            have_ram = cuda_moe_tiering_ram_ptrs(
                request.layer_index, expert,
                &host_gate, &host_up, &host_down);
        }
        if (!have_ram) {
            if (g_moe_tiering.compose_prefill_mass_tiering) {
                g_moe_tiering.forbidden_cold_ssd_to_vram++;
                g_moe_tiering.failures++;
                failure_reason = "ram-required";
                ok = 0;
                break;
            }
            host_gate = cache->route_host_gate +
                (uint64_t)miss * cache->gate_expert_bytes;
            host_up = cache->route_host_up +
                (uint64_t)miss * cache->gate_expert_bytes;
            host_down = cache->route_host_down +
                (uint64_t)miss * cache->down_expert_bytes;
            const uint64_t gate_src = request.gate_offset +
                (uint64_t)expert * cache->gate_expert_bytes;
            const uint64_t up_src = request.up_offset +
                (uint64_t)expert * cache->gate_expert_bytes;
            const uint64_t down_src = request.down_offset +
                (uint64_t)expert * cache->down_expert_bytes;
            if (!g_model_file_valid ||
                !cuda_pread_full(&g_model_file, host_gate,
                                 cache->gate_expert_bytes, gate_src) ||
                !cuda_pread_full(&g_model_file, host_up,
                                 cache->gate_expert_bytes, up_src) ||
                !cuda_pread_full(&g_model_file, host_down,
                                 cache->down_expert_bytes, down_src)) {
                g_moe_tiering.failures++;
                failure_reason = "pread";
                ok = 0;
                break;
            }
            g_moe_tiering.ssd_bytes +=
                cache->gate_expert_bytes * 2ull + cache->down_expert_bytes;
        }

        uint32_t ssd_wrap_h2d_ring = UINT32_MAX;
        if (have_ram && !from_nested && g_q1_0_ssd_wrap.enabled) {
            const int pageable = cuda_q1_0_ssd_wrap_host_is_pageable(
                request.layer_index, expert, from_snapshot, from_probation);
            if (pageable < 0 || !cuda_q1_0_ssd_wrap_prepare_h2d_source(
                    &host_gate, &host_up, &host_down,
                    cache->gate_expert_bytes, cache->down_expert_bytes,
                    pageable, &ssd_wrap_h2d_ring)) {
                failure_reason = "ssd-wrap-host-source";
                ok = 0;
                break;
            }
        }

        /* Transport accounting is representation-neutral: for supported nested
         * types, base plus residual bytes equal the native expert byte count. */
        const int cache_slot_i = have_ram ?
            cuda_moe_tiering_pick_vram_slot(cache, claimed, tier) : -1;
        const int promote = cache_slot_i >= 0;
        if (promote) {
            const uint32_t cache_slot = (uint32_t)cache_slot_i;
            claimed[cache_slot] = 1u;
            cuda_moe_cache_slot &entry = cache->slots[cache_slot];
            admitted[admitted_count++] = cache_slot;
            int32_t old_map_index = -1;
            const int was_valid = entry.state == CUDA_MOE_CACHE_VALID;
            if (was_valid && entry.layer_index < CUDA_MOE_LAYER_COUNT &&
                entry.expert_id < 256u) {
                cuda_moe_tiering_demote_cache_entry(
                    entry.layer_index, entry.expert_id);
                old_map_index = (int32_t)(
                    entry.layer_index * 256u + entry.expert_id);
                if ((size_t)old_map_index <
                        cache->host_slot_by_layer_expert.size() &&
                    cache->host_slot_by_layer_expert[(size_t)old_map_index] ==
                        (int32_t)cache_slot) {
                    cache->host_slot_by_layer_expert[(size_t)old_map_index] = -1;
                }
            }
            entry.state = CUDA_MOE_CACHE_LOADING;
            const uint64_t gate_dst =
                (uint64_t)cache_slot * cache->gate_expert_bytes;
            const uint64_t down_dst =
                (uint64_t)cache_slot * cache->down_expert_bytes;
            const uint64_t resident_pitch =
                (uint64_t)cache->capacity * cache->gate_expert_bytes;
            const uint64_t source_pitch =
                (from_nested || (!have_ram && !from_snapshot)) ?
                    (uint64_t)CUDA_MOE_ROUTE_COUNT *
                        cache->gate_expert_bytes :
                    cache->gate_expert_bytes;
            const double h2d_enqueue_started =
                from_nested && g_nested_residual.profile_enabled ?
                cuda_wall_sec() : 0.0;
            const int copy_ok =
                from_nested && cuda_nested_residual_gpu_join_requested() ?
                cuda_nested_residual_join_to_device_exact(
                    request.layer_index, expert,
                    request.gate_offset, request.up_offset,
                    request.down_offset,
                    cache->gate_expert_bytes, cache->down_expert_bytes,
                    cache->gate + gate_dst,
                    cache->up + gate_dst,
                    cache->down + down_dst,
                    cache->route_upload_stream) == 1 :
                (cache->packed_copy_requested ?
                    cuda_moe_route_copy_expert_h2d_async(
                        cache,
                        cache->gate + gate_dst,
                        cache->up + gate_dst,
                        cache->down + down_dst,
                        resident_pitch,
                        host_gate, host_up, host_down,
                        source_pitch) :
                    cuda_moe_route_legacy_copy_expert_h2d_async(
                        cache,
                        cache->gate + gate_dst,
                        cache->up + gate_dst,
                        cache->down + down_dst,
                        host_gate, host_up, host_down));
            if (from_nested && g_nested_residual.profile_enabled) {
                g_nested_residual.profile_h2d_enqueue_calls++;
                g_nested_residual.profile_h2d_enqueue_seconds +=
                    cuda_wall_sec() - h2d_enqueue_started;
            }
            if (!copy_ok) {
                if (from_nested) g_nested_residual.gpu_cache_failures++;
                failure_reason = "resident-copy";
                ok = 0;
                break;
            }
            if (!cuda_q1_0_ssd_wrap_record_h2d(
                    ssd_wrap_h2d_ring, cache->route_upload_stream)) {
                failure_reason = "ssd-wrap-h2d-event";
                ok = 0;
                break;
            }
            if (from_nested && cuda_nested_residual_gpu_join_requested()) {
                g_nested_residual.route_h2d_bytes +=
                    cache->gate_expert_bytes * 2ull +
                    cache->down_expert_bytes;
            }
            const uint64_t gate_src = request.gate_offset +
                (uint64_t)expert * cache->gate_expert_bytes;
            const uint64_t up_src = request.up_offset +
                (uint64_t)expert * cache->gate_expert_bytes;
            const uint64_t down_src = request.down_offset +
                (uint64_t)expert * cache->down_expert_bytes;
            const uint32_t new_map_index =
                request.layer_index * 256u + expert;
            moe_publish_resident_route_kernel<<<
                    1, 1, 0, cache->route_upload_stream>>>(
                cache->device_slot_by_layer_expert,
                cache->device_route_ptrs,
                old_map_index,
                new_map_index,
                cache_slot,
                request.route_count,
                route,
                cache->gate,
                cache->up,
                cache->down,
                cache->gate_expert_bytes,
                cache->down_expert_bytes);
            if (cudaGetLastError() != cudaSuccess) {
                (void)cudaGetLastError();
                failure_reason = "resident-publish";
                ok = 0;
                break;
            }
            entry.key = {gate_src, up_src, down_src};
            entry.layer_index = request.layer_index;
            entry.expert_id = expert;
            entry.age = ++cache->tick;
            entry.layer_owned = 0;
            entry.layer_key = request.gate_offset;
            cache->host_slot_by_layer_expert[new_map_index] =
                (int32_t)cache_slot;
            if (!was_valid && cache->count < cache->capacity) cache->count++;
            else if (was_valid) cache->evictions++;
            cache->admissions++;
            if (tier.state == CUDA_MOE_TIER_RAM_PROBATION) {
                g_moe_tiering.ram_to_warm++;
            }
            if (from_snapshot) {
                g_moe_tiering.snapshot_to_vram_bytes +=
                    cache->gate_expert_bytes * 2ull +
                    cache->down_expert_bytes;
            } else if (!have_ram) {
                g_moe_tiering.forbidden_cold_ssd_to_vram++;
            }
            tier.state = CUDA_MOE_TIER_VRAM_PROTECTED;
            g_moe_tiering.vram_promotions++;
            g_moe_tiering.ram_h2d_bytes +=
                cache->gate_expert_bytes * 2ull + cache->down_expert_bytes;
        } else {
            if (from_snapshot) {
                g_moe_tiering.snapshot_to_vram_bytes +=
                    cache->gate_expert_bytes * 2ull +
                    cache->down_expert_bytes;
            }
            const uint64_t gate_dst =
                (uint64_t)route * cache->gate_expert_bytes;
            const uint64_t down_dst =
                (uint64_t)route * cache->down_expert_bytes;
            const uint64_t transient_pitch =
                (uint64_t)CUDA_MOE_ROUTE_COUNT * cache->gate_expert_bytes;
            const uint64_t source_pitch =
                (from_nested || (!have_ram && !from_snapshot)) ?
                    transient_pitch : cache->gate_expert_bytes;
            const double h2d_enqueue_started =
                from_nested && g_nested_residual.profile_enabled ?
                cuda_wall_sec() : 0.0;
            const int copy_ok =
                from_nested && cuda_nested_residual_gpu_join_requested() ?
                cuda_nested_residual_join_to_device_exact(
                    request.layer_index, expert,
                    request.gate_offset, request.up_offset,
                    request.down_offset,
                    cache->gate_expert_bytes, cache->down_expert_bytes,
                    cache->route_transient_gate + gate_dst,
                    cache->route_transient_up + gate_dst,
                    cache->route_transient_down + down_dst,
                    cache->route_upload_stream) == 1 :
                (cache->packed_copy_requested ?
                    cuda_moe_route_copy_expert_h2d_async(
                        cache,
                        cache->route_transient_gate + gate_dst,
                        cache->route_transient_up + gate_dst,
                        cache->route_transient_down + down_dst,
                        transient_pitch,
                        host_gate, host_up, host_down,
                        source_pitch) :
                    cuda_moe_route_legacy_copy_expert_h2d_async(
                        cache,
                        cache->route_transient_gate + gate_dst,
                        cache->route_transient_up + gate_dst,
                        cache->route_transient_down + down_dst,
                        host_gate, host_up, host_down));
            if (from_nested && g_nested_residual.profile_enabled) {
                g_nested_residual.profile_h2d_enqueue_calls++;
                g_nested_residual.profile_h2d_enqueue_seconds +=
                    cuda_wall_sec() - h2d_enqueue_started;
            }
            if (!copy_ok) {
                if (from_nested) g_nested_residual.gpu_cache_failures++;
                failure_reason = "transient-copy";
                ok = 0;
                break;
            }
            if (!cuda_q1_0_ssd_wrap_record_h2d(
                    ssd_wrap_h2d_ring, cache->route_upload_stream)) {
                failure_reason = "ssd-wrap-h2d-event";
                ok = 0;
                break;
            }
            if (from_nested && cuda_nested_residual_gpu_join_requested()) {
                g_nested_residual.route_h2d_bytes +=
                    cache->gate_expert_bytes * 2ull +
                    cache->down_expert_bytes;
            }
            moe_publish_transient_route_kernel<<<
                    1, 1, 0, cache->route_upload_stream>>>(
                cache->device_route_ptrs,
                request.route_count,
                route,
                route,
                cache->route_transient_gate,
                cache->route_transient_up,
                cache->route_transient_down,
                cache->gate_expert_bytes,
                cache->down_expert_bytes);
            if (cudaGetLastError() != cudaSuccess) {
                (void)cudaGetLastError();
                failure_reason = "transient-publish";
                ok = 0;
                break;
            }
            g_moe_tiering.transient++;
            g_moe_tiering.ram_h2d_bytes +=
                cache->gate_expert_bytes * 2ull + cache->down_expert_bytes;
        }
        if (from_nested && !cuda_nested_residual_gpu_join_requested()) {
            const uint64_t native_bytes =
                cache->gate_expert_bytes * 2ull + cache->down_expert_bytes;
            g_nested_residual.h2d_bytes += native_bytes;
            g_nested_residual.route_h2d_bytes += native_bytes;
        }
    }
    const double h2d_sync_started =
        g_nested_residual.profile_enabled &&
        cuda_nested_residual_gpu_cache_requested() &&
        cuda_nested_residual_layer_required(request.layer_index) ?
        cuda_wall_sec() : 0.0;
    const cudaError_t pending_error = cudaGetLastError();
    const cudaError_t sync_error =
        cudaStreamSynchronize(cache->route_upload_stream);
    if (h2d_sync_started != 0.0) {
        g_nested_residual.profile_h2d_sync_calls++;
        g_nested_residual.profile_h2d_sync_seconds +=
            cuda_wall_sec() - h2d_sync_started;
    }
    if (pending_error != cudaSuccess || sync_error != cudaSuccess) {
        (void)cudaGetLastError();
        failure_reason = "upload-sync";
        ok = 0;
    }
    if (ok) {
        for (uint32_t i = 0; i < admitted_count; i++) {
            cache->slots[admitted[i]].state = CUDA_MOE_CACHE_VALID;
        }
    } else if (admitted_count > 0u) {
        /* A failed asynchronous upload can have already changed both host and
         * device maps. Invalidate the complete resident cache so no later
         * request can observe a protected tier entry backed by an empty or
         * partially overwritten slot. This is failure-only and deliberately
         * favors a coherent cold restart over preserving cache contents. */
        for (uint32_t i = 0; i < admitted_count; i++) {
            const cuda_moe_cache_slot &entry = cache->slots[admitted[i]];
            if (entry.layer_index < CUDA_MOE_LAYER_COUNT &&
                entry.expert_id < 256u) {
                cuda_moe_tiering_demote_cache_entry(
                    entry.layer_index, entry.expert_id);
            }
        }
        cuda_moe_expert_cache_invalidate();
    }
    if (!ok) {
        fprintf(stderr,
                "ds4: [tiering-enforce] result=failed layer=%u sequence=%u "
                "routes=%u misses=%u reason=%s admitted=%u\n",
                request.layer_index, request.sequence, request.route_count,
                request.miss_count, failure_reason, admitted_count);
    }
    return ok;
}

static void *cuda_moe_route_worker(void *arg) {
    cuda_moe_expert_cache *cache = (cuda_moe_expert_cache *)arg;
    if (!cache || cudaSetDevice(cache->route_device) != cudaSuccess) {
        if (cache) {
            cache->route_worker_errors++;
            cache->route_worker_failed = 1;
        }
        (void)cudaGetLastError();
        return NULL;
    }
    cache->route_worker_ready = 1;
    uint32_t consumed_sequence = 0;
    std::vector<uint8_t> claimed(cache->capacity, 0u);

    while (!cache->route_stop) {
        const uint32_t sequence = cache->route_request_host->sequence;
        if (sequence == 0u || sequence == consumed_sequence) {
#ifdef _WIN32
            (void)SwitchToThread();
#else
            usleep(0);
#endif
            continue;
        }
#ifdef _WIN32
        MemoryBarrier();
#else
        __sync_synchronize();
#endif
        cuda_moe_route_request request;
        memcpy(&request, cache->route_request_host, sizeof(request));
        if (request.sequence != sequence) continue;
        consumed_sequence = sequence;
        if (sequence <= 2u) {
            fprintf(stderr,
                    "ds4: [gpu-route-debug] request seq=%u layer=%u misses=%u\n",
                    sequence, request.layer_index, request.miss_count);
        }
        int request_valid =
            request.route_count > 0u &&
            request.route_count <= CUDA_MOE_ROUTE_COUNT &&
            request.miss_count <= request.route_count &&
            request.layer_index < CUDA_MOE_LAYER_COUNT &&
            request.gate_expert_bytes == cache->gate_expert_bytes &&
            request.down_expert_bytes == cache->down_expert_bytes;
        if (request_valid &&
            !cuda_sparse_bake_validate_selected(
                request.layer_index, request.selected,
                request.route_count, "gpu resident route",
                sequence)) {
            request_valid = 0;
        }
        if (!request_valid) {
            fprintf(stderr,
                    "ds4: [gpu-route-request] result=invalid sequence=%u "
                    "layer=%u routes=%u misses=%u gate_bytes=%llu/%llu "
                    "down_bytes=%llu/%llu\n",
                    request.sequence, request.layer_index,
                    request.route_count, request.miss_count,
                    (unsigned long long)request.gate_expert_bytes,
                    (unsigned long long)cache->gate_expert_bytes,
                    (unsigned long long)request.down_expert_bytes,
                    (unsigned long long)cache->down_expert_bytes);
        }
        if (request_valid &&
            g_moe_tiering.compose_prefill_mass_tiering &&
            g_dynamic_arena.snapshot_generation !=
                g_moe_tiering.snapshot_generation) {
            g_moe_tiering.failures++;
            request_valid = 0;
        }
        if (g_moe_tiering.mode != CUDA_MOE_TIER_OFF && request_valid) {
            if (!cuda_moe_tiering_advance_call_tick("gpu-route-request")) {
                request_valid = 0;
            }
        }
        if (g_moe_tiering.mode != CUDA_MOE_TIER_OFF && request_valid) {
            g_moe_tiering.calls++;
            g_moe_tiering.selected += request.route_count;
            for (uint32_t route = 0;
                 route < request.route_count; route++) {
                const int32_t expert_i = request.selected[route];
                if (expert_i < 0 || expert_i >= 256) {
                    request_valid = 0;
                    break;
                }
                (void)cuda_moe_tiering_observe_route(
                    request.layer_index, (uint32_t)expert_i,
                    request.weights[route]);
            }
            if (!request_valid) {
                fprintf(stderr,
                        "ds4: [gpu-route-request] result=invalid-selected "
                        "sequence=%u layer=%u routes=%u selected="
                        "%d,%d,%d,%d,%d,%d\n",
                        request.sequence, request.layer_index,
                        request.route_count,
                        request.selected[0], request.selected[1],
                        request.selected[2], request.selected[3],
                        request.selected[4], request.selected[5]);
            }
        }
        const char *precheck_failure_reason = "request-invalid";
        if (request_valid && request.miss_count == 0u) {
            if (g_moe_tiering.mode != CUDA_MOE_TIER_OFF) {
                for (uint32_t route = 0;
                     route < request.route_count; route++) {
                    const uint32_t expert =
                        (uint32_t)request.selected[route];
                    cuda_moe_tier_entry &tier = g_moe_tiering.entries[
                        cuda_moe_tiering_entry_index(
                            request.layer_index, expert)];
                    if (g_moe_tiering.mode == CUDA_MOE_TIER_ENFORCE &&
                        tier.state != CUDA_MOE_TIER_VRAM_PROTECTED) {
                        if (tier.state == CUDA_MOE_TIER_SSD_COLD) {
                            g_moe_tiering.forbidden_cold_ssd_to_vram++;
                            g_iq1_promotion.direct_ssd_to_vram_rejected++;
                        }
                        fprintf(stderr,
                                "ds4: [tiering-enforce] result=all-hit-state-mismatch "
                                "layer=%u sequence=%u expert=%u state=%u\n",
                                request.layer_index, request.sequence, expert,
                                (unsigned)tier.state);
                        g_moe_tiering.failures++;
                        if (g_iq1_promotion.requested_slots != 0u) {
                            g_iq1_promotion.failures++;
                        }
                        precheck_failure_reason =
                            "all-hit-tier-state-mismatch";
                        request_valid = 0;
                        break;
                    }
                    if (tier.state != CUDA_MOE_TIER_VRAM_PROTECTED) {
                        if (tier.state == CUDA_MOE_TIER_SSD_COLD) {
                            g_moe_tiering.cold_to_vram++;
                            if (g_moe_tiering.compose_prefill_mass_tiering) {
                                g_moe_tiering.forbidden_cold_ssd_to_vram++;
                            }
                        } else {
                            g_moe_tiering.vram_promotions++;
                        }
                        tier.state = CUDA_MOE_TIER_VRAM_PROTECTED;
                    }
                }
            }
            if (request_valid) {
                cache->route_all_hit_observed++;
                cache->hits += request.route_count;
                cache->calls++;
                continue;
            }
        }
        const double started = cuda_wall_sec();
        const int nested_profile_request =
            g_nested_residual.profile_enabled &&
            cuda_nested_residual_gpu_cache_requested() &&
            cuda_nested_residual_layer_required(request.layer_index);
        int ok = request_valid &&
                 request.miss_count > 0u &&
                 request.miss_count <= request.route_count;
        const char *failure_reason = ok ? "none" : precheck_failure_reason;
        cudaError_t failure_cuda_error = cudaSuccess;
        std::fill(claimed.begin(), claimed.end(), 0u);
        for (uint32_t route = 0; ok && route < request.route_count; route++) {
            const int32_t slot = request.hit_slots[route];
            if (slot >= 0) {
                if ((uint32_t)slot >= cache->capacity) {
                    fprintf(stderr,
                            "ds4: [gpu-route-request] result=invalid-hit-slot "
                            "sequence=%u layer=%u route=%u slot=%d capacity=%u\n",
                            request.sequence, request.layer_index, route, slot,
                            cache->capacity);
                    ok = 0;
                    failure_reason = "hit-slot-oob";
                    break;
                }
                claimed[(uint32_t)slot] = 1u;
                cache->slots[(uint32_t)slot].age = ++cache->tick;
            }
        }

        uint32_t admitted[CUDA_MOE_ROUTE_COUNT] = {0};
        uint32_t admitted_count = 0;
        if (ok && g_moe_tiering.mode == CUDA_MOE_TIER_ENFORCE) {
            ok = cuda_moe_tiering_enforce_request(
                cache, request, claimed.data());
        }
        for (uint32_t miss = 0;
             ok && g_moe_tiering.mode != CUDA_MOE_TIER_ENFORCE &&
             miss < request.miss_count; miss++) {
            const uint32_t route = request.miss_routes[miss];
            if (route >= request.route_count) {
                ok = 0;
                failure_reason = "miss-route-oob";
                break;
            }
            const int32_t expert_i = request.selected[route];
            if (expert_i < 0 || expert_i >= 256) {
                ok = 0;
                failure_reason = "expert-oob";
                break;
            }
            const uint32_t expert = (uint32_t)expert_i;
            if (g_sparse_bake_active &&
                !cuda_sparse_bake_expert_retained(request.layer_index, expert)) {
                g_sparse_bake_route_rejections++;
                fprintf(stderr,
                        "ds4: sparse bake rejected route worker miss "
                        "layer=%u seq=%u route=%u expert=%u\n",
                        request.layer_index, sequence, route, expert);
                ok = 0;
                failure_reason = "sparse-rejected";
                break;
            }
            const int cache_slot_i = cuda_moe_route_worker_pick_slot(cache, claimed.data());
            if (cache_slot_i < 0) {
                ok = 0;
                failure_reason = "no-cache-slot";
                break;
            }
            const uint32_t cache_slot = (uint32_t)cache_slot_i;
            claimed[cache_slot] = 1u;
            cuda_moe_cache_slot &entry = cache->slots[cache_slot];
            admitted[admitted_count++] = cache_slot;
            int32_t old_map_index = -1;
            const int was_valid = entry.state == CUDA_MOE_CACHE_VALID;
            if (was_valid && entry.layer_index < CUDA_MOE_LAYER_COUNT &&
                entry.expert_id < 256u) {
                cuda_moe_tiering_demote_cache_entry(
                    entry.layer_index, entry.expert_id);
                old_map_index = (int32_t)(entry.layer_index * 256u + entry.expert_id);
                if ((size_t)old_map_index < cache->host_slot_by_layer_expert.size() &&
                    cache->host_slot_by_layer_expert[(size_t)old_map_index] ==
                        (int32_t)cache_slot) {
                    cache->host_slot_by_layer_expert[(size_t)old_map_index] = -1;
                }
            }
            entry.state = CUDA_MOE_CACHE_LOADING;

            char *host_gate = cache->route_host_gate +
                (uint64_t)miss * cache->gate_expert_bytes;
            char *host_up = cache->route_host_up +
                (uint64_t)miss * cache->gate_expert_bytes;
            char *host_down = cache->route_host_down +
                (uint64_t)miss * cache->down_expert_bytes;
            const uint64_t gate_src = request.gate_offset +
                (uint64_t)expert * cache->gate_expert_bytes;
            const uint64_t up_src = request.up_offset +
                (uint64_t)expert * cache->gate_expert_bytes;
            const uint64_t down_src = request.down_offset +
                (uint64_t)expert * cache->down_expert_bytes;
            int from_nested = 0;
            if (cuda_nested_residual_gpu_cache_requested() &&
                cuda_nested_residual_layer_required(request.layer_index)) {
                if (cuda_nested_residual_gpu_join_requested()) {
                    from_nested = 1;
                } else {
                    from_nested = cuda_nested_residual_fill_route_host_exact(
                        request.layer_index, expert,
                        request.gate_offset, request.up_offset,
                        request.down_offset,
                        cache->gate_expert_bytes, cache->down_expert_bytes,
                        host_gate, host_up, host_down);
                    if (from_nested != 1) {
                        ok = 0;
                        failure_reason = "nested-exact";
                        break;
                    }
                }
            } else if (!g_model_file_valid ||
                       !cuda_pread_full(&g_model_file, host_gate,
                                        cache->gate_expert_bytes, gate_src) ||
                       !cuda_pread_full(&g_model_file, host_up,
                                        cache->gate_expert_bytes, up_src) ||
                       !cuda_pread_full(&g_model_file, host_down,
                                        cache->down_expert_bytes, down_src)) {
                    ok = 0;
                    failure_reason = "pread";
                    break;
            }
            const uint64_t gate_dst = (uint64_t)cache_slot * cache->gate_expert_bytes;
            const uint64_t down_dst = (uint64_t)cache_slot * cache->down_expert_bytes;
            const uint64_t resident_pitch =
                (uint64_t)cache->capacity * cache->gate_expert_bytes;
            const uint64_t source_pitch =
                (uint64_t)CUDA_MOE_ROUTE_COUNT * cache->gate_expert_bytes;
            const double h2d_enqueue_started =
                from_nested && g_nested_residual.profile_enabled ?
                cuda_wall_sec() : 0.0;
            const int copy_ok =
                from_nested && cuda_nested_residual_gpu_join_requested() ?
                cuda_nested_residual_join_to_device_exact(
                    request.layer_index, expert,
                    request.gate_offset, request.up_offset,
                    request.down_offset,
                    cache->gate_expert_bytes, cache->down_expert_bytes,
                    cache->gate + gate_dst,
                    cache->up + gate_dst,
                    cache->down + down_dst,
                    cache->route_upload_stream) == 1 :
                (cache->packed_copy_requested ?
                    cuda_moe_route_copy_expert_h2d_async(
                        cache,
                        cache->gate + gate_dst,
                        cache->up + gate_dst,
                        cache->down + down_dst,
                        resident_pitch,
                        host_gate, host_up, host_down,
                        source_pitch) :
                    cuda_moe_route_legacy_copy_expert_h2d_async(
                        cache,
                        cache->gate + gate_dst,
                        cache->up + gate_dst,
                        cache->down + down_dst,
                        host_gate, host_up, host_down));
            if (from_nested && g_nested_residual.profile_enabled) {
                g_nested_residual.profile_h2d_enqueue_calls++;
                g_nested_residual.profile_h2d_enqueue_seconds +=
                    cuda_wall_sec() - h2d_enqueue_started;
            }
            if (!copy_ok) {
                if (from_nested) g_nested_residual.gpu_cache_failures++;
                ok = 0;
                failure_reason = "h2d-copy";
                failure_cuda_error = cudaPeekAtLastError();
                break;
            }
            if (from_nested && cuda_nested_residual_gpu_join_requested()) {
                g_nested_residual.route_h2d_bytes +=
                    cache->gate_expert_bytes * 2ull +
                    cache->down_expert_bytes;
            }
            if (from_nested && !cuda_nested_residual_gpu_join_requested()) {
                const uint64_t native_bytes =
                    cache->gate_expert_bytes * 2ull +
                    cache->down_expert_bytes;
                g_nested_residual.h2d_bytes += native_bytes;
                g_nested_residual.route_h2d_bytes += native_bytes;
            }
            const uint32_t new_map_index = request.layer_index * 256u + expert;
            moe_publish_resident_route_kernel<<<1, 1, 0, cache->route_upload_stream>>>(
                cache->device_slot_by_layer_expert,
                cache->device_route_ptrs,
                old_map_index,
                new_map_index,
                cache_slot,
                request.route_count,
                route,
                cache->gate,
                cache->up,
                cache->down,
                cache->gate_expert_bytes,
                cache->down_expert_bytes);
            const cudaError_t publish_error = cudaGetLastError();
            if (publish_error != cudaSuccess) {
                failure_cuda_error = publish_error;
                ok = 0;
                failure_reason = "publish-launch";
                break;
            }
            entry.key = {gate_src, up_src, down_src};
            entry.layer_index = request.layer_index;
            entry.expert_id = expert;
            entry.age = ++cache->tick;
            entry.layer_owned = 0;
            entry.layer_key = request.gate_offset;
            cache->host_slot_by_layer_expert[new_map_index] = (int32_t)cache_slot;
            if (!was_valid && cache->count < cache->capacity) cache->count++;
            else if (was_valid) cache->evictions++;
            cache->admissions++;
            if (g_moe_tiering.mode == CUDA_MOE_TIER_OBSERVE) {
                cuda_moe_tier_entry &tier = g_moe_tiering.entries[
                    cuda_moe_tiering_entry_index(
                        request.layer_index, expert)];
                if (tier.state == CUDA_MOE_TIER_SSD_COLD) {
                    g_moe_tiering.cold_to_vram++;
                } else if (tier.state != CUDA_MOE_TIER_VRAM_PROTECTED) {
                    g_moe_tiering.vram_promotions++;
                }
                tier.state = CUDA_MOE_TIER_VRAM_PROTECTED;
            }
        }

        if (g_moe_tiering.mode != CUDA_MOE_TIER_ENFORCE) {
            const double h2d_sync_started =
                nested_profile_request ? cuda_wall_sec() : 0.0;
            const cudaError_t pending_error = cudaGetLastError();
            const cudaError_t sync_error =
                cudaStreamSynchronize(cache->route_upload_stream);
            if (nested_profile_request) {
                g_nested_residual.profile_h2d_sync_calls++;
                g_nested_residual.profile_h2d_sync_seconds +=
                    cuda_wall_sec() - h2d_sync_started;
            }
            if (pending_error != cudaSuccess || sync_error != cudaSuccess) {
                failure_cuda_error = pending_error != cudaSuccess ?
                    pending_error : sync_error;
                failure_reason = pending_error != cudaSuccess ?
                    "pending-cuda-error" : "upload-sync";
                ok = 0;
            }
            if (ok) {
                for (uint32_t i = 0; i < admitted_count; i++) {
                    cache->slots[admitted[i]].state = CUDA_MOE_CACHE_VALID;
                }
            } else if (admitted_count > 0u) {
                for (uint32_t i = 0; i < admitted_count; i++) {
                    const cuda_moe_cache_slot &entry =
                        cache->slots[admitted[i]];
                    if (entry.layer_index < CUDA_MOE_LAYER_COUNT &&
                        entry.expert_id < 256u) {
                        cuda_moe_tiering_demote_cache_entry(
                            entry.layer_index, entry.expert_id);
                    }
                }
                cuda_moe_expert_cache_invalidate();
            }
        }
        cache->route_worker_jobs++;
        cache->route_miss_experts += request.miss_count;
        cache->route_worker_seconds += cuda_wall_sec() - started;
        cache->misses += request.miss_count;
        cache->hits += request.route_count - request.miss_count;
        cache->calls++;
        if (!ok) {
            if (g_moe_tiering.mode != CUDA_MOE_TIER_OFF) {
                g_moe_tiering.failures++;
            }
            *cache->route_failed_host = sequence;
            cache->route_worker_errors++;
            fprintf(stderr,
                    "ds4: CUDA GPU-resident route worker failed seq=%u layer=%u "
                    "routes=%u misses=%u reason=%s cuda=%s\n",
                    sequence, request.layer_index, request.route_count,
                    request.miss_count, failure_reason,
                    failure_cuda_error == cudaSuccess ? "none" :
                        cudaGetErrorString(failure_cuda_error));
        }
#ifdef _WIN32
        MemoryBarrier();
#else
        __sync_synchronize();
#endif
        *cache->route_ready_host = sequence;
#ifdef _WIN32
        MemoryBarrier();
#else
        __sync_synchronize();
#endif
    }
    return NULL;
}

static int cuda_moe_expert_cache_copy_to_compact_async(
        cuda_moe_expert_cache *cache,
        uint32_t cache_slot,
        uint32_t compact_slot) {
    const uint64_t gate_src = (uint64_t)cache_slot * cache->gate_expert_bytes;
    const uint64_t gate_dst = (uint64_t)compact_slot * cache->gate_expert_bytes;
    const uint64_t down_src = (uint64_t)cache_slot * cache->down_expert_bytes;
    const uint64_t down_dst = (uint64_t)compact_slot * cache->down_expert_bytes;
    return cudaMemcpyAsync(g_moe_gather.gate + gate_dst, cache->gate + gate_src,
                           (size_t)cache->gate_expert_bytes, cudaMemcpyDeviceToDevice,
                           g_model_upload_stream) == cudaSuccess &&
           cudaMemcpyAsync(g_moe_gather.up + gate_dst, cache->up + gate_src,
                           (size_t)cache->gate_expert_bytes, cudaMemcpyDeviceToDevice,
                           g_model_upload_stream) == cudaSuccess &&
           cudaMemcpyAsync(g_moe_gather.down + down_dst, cache->down + down_src,
                           (size_t)cache->down_expert_bytes, cudaMemcpyDeviceToDevice,
                           g_model_upload_stream) == cudaSuccess;
}

/* Selected-load profiling accumulators (DS4_CUDA_SEL_PROFILE). */
static uint64_t g_sel_prof_calls;
static uint64_t g_sel_prof_experts;
static double g_sel_prof_fetch_s;
static uint64_t g_route_prof_calls;
static double g_route_prof_d2h_s;
static double g_route_prof_observe_s;
static double g_route_prof_map_s;
static double g_route_prof_transport_s;
static double g_route_prof_publish_s;

static int cuda_model_range_in_window(const void *model_map, uint64_t offset, uint64_t bytes) {
    return g_model_window_bytes && model_map == g_model_host_base && g_model_device_base &&
           offset + bytes <= g_model_window_bytes;
}

static const os_file_t *cuda_model_route_source_file(
        const void *model_map,
        int *is_main_file) {
    if (is_main_file) *is_main_file = 0;
    if (g_iq1_s_sidecar_file_valid &&
        model_map == g_iq1_s_sidecar_host_base) {
        return &g_iq1_s_sidecar_file;
    }
    if (g_model_file_valid && model_map == g_model_host_base) {
        if (is_main_file) *is_main_file = 1;
        return &g_model_file;
    }
    return NULL;
}

/* Persistent staging rotation so consecutive span uploads pipeline (pread of the
 * next tensor overlaps the H2D copy of the previous one). */
static uint64_t g_stream_span_idx = 0;

/* Stream `bytes` from the model file at `offset` DIRECTLY into a caller-owned
 * device buffer `dst`, async on the upload stream via the pinned staging pool.
 * No cudaMalloc / eviction / range-cache: this is the fast path for MoE experts
 * (cross-token reuse ~0, so the per-expert VRAM cache's malloc/evict churn --
 * ~40 ms/expert on WDDM, disk-independent -- is pure overhead). The caller MUST
 * cudaStreamSynchronize(g_model_upload_stream) before the data is read elsewhere. */
static int cuda_model_stream_span_into(
        char *dst,
        const void *model_map,
        uint64_t offset,
        uint64_t bytes,
        char *mirror) {
    int is_main_file = 0;
    const os_file_t *source = cuda_model_route_source_file(
        model_map, &is_main_file);
    if (!source || bytes == 0 || !dst) return 0;
    const uint64_t chunk = cuda_model_copy_chunk_bytes();
    const uint64_t stage_bytes = chunk + (g_model_direct_align > 1 ? g_model_direct_align : 1);
    if (!cuda_model_stage_pool_alloc(stage_bytes)) return 0;
    uint64_t copied = 0;
    while (copied < bytes) {
        const uint64_t n = (bytes - copied < chunk) ? (bytes - copied) : chunk;
        const uint64_t bi = g_stream_span_idx % 4u;
        if (g_stream_span_idx >= 4u) {
            if (cudaEventSynchronize(g_model_stage_event[bi]) != cudaSuccess) { (void)cudaGetLastError(); return 0; }
        }
        const char *payload = NULL;
        if (is_main_file) {
            if (!cuda_model_stage_read(g_model_stage[bi], g_model_stage_bytes,
                                       offset + copied, n, &payload)) return 0;
        } else {
            if (!cuda_pread_full(source, g_model_stage[bi], n,
                                 offset + copied)) return 0;
            payload = (const char *)g_model_stage[bi];
        }
        if (mirror) {
            memcpy(mirror + copied, payload, (size_t)n);
            if (memcmp(mirror + copied, payload, (size_t)n) != 0) return 0;
        }
        if (cudaMemcpyAsync(dst + copied, payload, (size_t)n, cudaMemcpyHostToDevice, g_model_upload_stream) != cudaSuccess) {
            (void)cudaGetLastError();
            return 0;
        }
        if (cudaEventRecord(g_model_stage_event[bi], g_model_upload_stream) != cudaSuccess) { (void)cudaGetLastError(); return 0; }
        if (is_main_file) cuda_model_drop_file_pages(offset + copied, n);
        copied += n;
        g_stream_span_idx++;
    }
    return 1;
}

#ifdef _WIN32
static uint32_t cuda_moe_io_queue_depth(void) {
    uint32_t qd = 1;
    const char *env = getenv("DS4_CUDA_MOE_IO_QD");
    if (env && env[0]) {
        char *end = NULL;
        const unsigned long v = strtoul(env, &end, 10);
        if (end != env && v > 0) qd = (uint32_t)v;
    }
    if (qd > 4u) qd = 4u;
    return qd;
}

static int cuda_moe_io_events_ensure(void) {
    for (uint32_t i = 0; i < 4u; i++) {
        if (g_moe_io_event[i]) continue;
        g_moe_io_event[i] = CreateEventW(NULL, TRUE, FALSE, NULL);
        if (!g_moe_io_event[i]) {
            fprintf(stderr, "ds4: CUDA MoE overlapped I/O event creation failed: %lu\n",
                    (unsigned long)GetLastError());
            return 0;
        }
    }
    return 1;
}

static void cuda_moe_io_cancel_pending(
        const os_file_t *source,
        const int pending[4],
        uint32_t count) {
    if (!source) return;
    for (uint32_t i = 0; i < count; i++) {
        if (pending[i]) (void)CancelIoEx(source->h, &g_moe_io_ov[i]);
    }
    for (uint32_t i = 0; i < count; i++) {
        if (!pending[i]) continue;
        DWORD ignored = 0;
        (void)GetOverlappedResult(source->h, &g_moe_io_ov[i], &ignored, TRUE);
    }
}

/* Batch selected-expert file spans through the existing pinned staging ring.
 * ReadFile operations are submitted concurrently; completed buffers are then
 * uploaded on the existing nonblocking CUDA stream. The caller retains the
 * layer-level upload sync, so this path changes only host I/O concurrency. */
static int cuda_moe_fill_spans_overlapped(
        const void *model_map,
        const std::vector<cuda_moe_gather::span> &spans,
        uint32_t qd) {
    int is_main_file = 0;
    const os_file_t *source = cuda_model_route_source_file(
        model_map, &is_main_file);
    if (qd < 2u || qd > 4u || !source) return 0;
    const uint64_t stage_bytes = cuda_model_copy_chunk_bytes() +
        (g_model_direct_align > 1 ? g_model_direct_align : 1);
    if (!cuda_model_stage_pool_alloc(stage_bytes) || !cuda_moe_io_events_ensure()) return 0;

    size_t base = 0;
    while (base < spans.size()) {
        const uint32_t count = (uint32_t)((spans.size() - base < qd) ?
            spans.size() - base : qd);
        int pending[4] = {0, 0, 0, 0};

        for (uint32_t i = 0; i < count; i++) {
            const cuda_moe_gather::span &s = spans[base + i];
            if (cuda_model_range_in_window(model_map, s.offset, s.bytes)) {
                const char *src = g_model_device_base + s.offset;
                if (s.mirror) {
                    memcpy(s.mirror,
                           (const char *)model_map + s.offset,
                           (size_t)s.bytes);
                    if (memcmp(s.mirror,
                               (const char *)model_map + s.offset,
                               (size_t)s.bytes) != 0) {
                        cuda_moe_io_cancel_pending(source, pending, count);
                        return 0;
                    }
                    cuda_dynamic_arena_observer_mirror_done(
                        s.arena_entry, s.arena_part, s.bytes);
                }
                if (cudaMemcpyAsync(s.dst, src, (size_t)s.bytes, cudaMemcpyDefault,
                                    g_model_upload_stream) != cudaSuccess) {
                    (void)cudaGetLastError();
                    cuda_moe_io_cancel_pending(source, pending, count);
                    return 0;
                }
                continue;
            }
            if (s.bytes == 0 || s.bytes > g_model_stage_bytes || s.bytes > 0xffffffffull) {
                cuda_moe_io_cancel_pending(source, pending, count);
                return 0;
            }
            /* The serial and overlapped readers share this pinned staging
             * ring. Event ownership, not producer-local bookkeeping, decides
             * when a buffer may be overwritten by the next ReadFile. */
            if (cudaEventSynchronize(g_model_stage_event[i]) != cudaSuccess) {
                (void)cudaGetLastError();
                cuda_moe_io_cancel_pending(source, pending, count);
                return 0;
            }

            OVERLAPPED &ov = g_moe_io_ov[i];
            memset(&ov, 0, sizeof(ov));
            ov.Offset = (DWORD)(s.offset & 0xffffffffu);
            ov.OffsetHigh = (DWORD)(s.offset >> 32);
            ov.hEvent = g_moe_io_event[i];
            (void)ResetEvent(ov.hEvent);
            const BOOL started = ReadFile(source->h, g_model_stage[i],
                                          (DWORD)s.bytes, NULL, &ov);
            if (!started && GetLastError() != ERROR_IO_PENDING) {
                fprintf(stderr, "ds4: CUDA MoE overlapped read submit failed at %llu: %lu\n",
                        (unsigned long long)s.offset, (unsigned long)GetLastError());
                cuda_moe_io_cancel_pending(source, pending, count);
                return 0;
            }
            pending[i] = 1;
        }

        for (uint32_t i = 0; i < count; i++) {
            if (!pending[i]) continue;
            const cuda_moe_gather::span &s = spans[base + i];
            DWORD got = 0;
            if (!GetOverlappedResult(source->h, &g_moe_io_ov[i], &got, TRUE) ||
                got != (DWORD)s.bytes) {
                fprintf(stderr, "ds4: CUDA MoE overlapped read completion failed at %llu: %lu (%lu/%llu bytes)\n",
                        (unsigned long long)s.offset, (unsigned long)GetLastError(),
                        (unsigned long)got, (unsigned long long)s.bytes);
                cuda_moe_io_cancel_pending(source, pending, count);
                return 0;
            }
            pending[i] = 0;
            if (s.mirror) {
                memcpy(s.mirror, g_model_stage[i], (size_t)s.bytes);
                if (memcmp(s.mirror, g_model_stage[i],
                           (size_t)s.bytes) != 0) {
                    cuda_moe_io_cancel_pending(source, pending, count);
                    return 0;
                }
                cuda_dynamic_arena_observer_mirror_done(
                    s.arena_entry, s.arena_part, s.bytes);
            }
            if (cudaMemcpyAsync(s.dst, g_model_stage[i], (size_t)s.bytes,
                                cudaMemcpyHostToDevice, g_model_upload_stream) != cudaSuccess ||
                cudaEventRecord(g_model_stage_event[i], g_model_upload_stream) != cudaSuccess) {
                (void)cudaGetLastError();
                cuda_moe_io_cancel_pending(source, pending, count);
                return 0;
            }
            g_moe_io_stage_used[i] = 1;
            if (is_main_file) cuda_model_drop_file_pages(s.offset, s.bytes);
        }
        base += count;
    }
    static int notice_printed = 0;
    if (!notice_printed) {
        fprintf(stderr, "ds4: CUDA MoE overlapped read succeeded queue depth=%u\n", qd);
        notice_printed = 1;
    }
    return 1;
}
#endif

/* Fill one compact slot for one expert weight (gate/up/down): zero-copy D2D from
 * the pinned host window when in-window, else stream straight from the file.
 * All async on the upload stream; caller batches one sync per layer. */
static int cuda_moe_fill_span(
        char *dst,
        const void *model_map,
        uint64_t offset,
        uint64_t bytes,
        char *mirror) {
    if (cuda_model_range_in_window(model_map, offset, bytes)) {
        const char *src = g_model_device_base + offset;   /* device-mapped host window */
        if (mirror) {
            memcpy(mirror, (const char *)model_map + offset, (size_t)bytes);
            if (memcmp(mirror, (const char *)model_map + offset,
                       (size_t)bytes) != 0) {
                return 0;
            }
        }
        if (cudaMemcpyAsync(dst, src, (size_t)bytes, cudaMemcpyDefault, g_model_upload_stream) != cudaSuccess) {
            (void)cudaGetLastError();
            return 0;
        }
        return 1;
    }
    return cuda_model_stream_span_into(dst, model_map, offset, bytes, mirror);
}

static int cuda_moe_gather_ensure(char **ptr, uint64_t *cap, uint64_t bytes, const char *what) {
    if (bytes == 0) return 1;
    if (*ptr && *cap >= bytes) return 1;
    if (*ptr) { (void)cudaFree(*ptr); *ptr = NULL; *cap = 0; }
    char *dev = cuda_model_stream_alloc(bytes, 1, what);
    if (!dev) return 0;
    *ptr = dev; *cap = bytes; return 1;
}

static int cuda_moe_gather_ensure_i32(int32_t **ptr, uint64_t *cap, uint32_t count, const char *what) {
    return cuda_moe_gather_ensure((char **)ptr, cap, (uint64_t)count * sizeof(int32_t), what);
}

static int cuda_iq1_s_vram_cache_requested_per_layer(void) {
    const char *env = getenv("DS4_IQ1_S_VRAM_CACHE_PER_LAYER");
    if (!env || !env[0] || strcmp(env, "0") == 0) return 0;
    char *end = NULL;
    errno = 0;
    const unsigned long value = strtoul(env, &end, 10);
    while (end && (*end == ' ' || *end == '\t')) end++;
    if (end == env || errno != 0 || !end || *end != '\0' ||
        value == 0 || value > 4) {
        fprintf(stderr, "ds4: invalid DS4_IQ1_S_VRAM_CACHE_PER_LAYER=%s\n", env);
        return -1;
    }
    return (int)value;
}

static void cuda_iq1_s_vram_cache_release(void) {
    cuda_iq1_s_vram_cache &cache = g_iq1_s_vram_cache;
    if (cache.attempted || cache.hits || cache.misses || cache.failures) {
        fprintf(stderr,
                "ds4: [iq1-s-vram-cache] result=summary per_layer=%u "
                "capacity=%u count=%u slot_bytes=%llu hits=%llu misses=%llu "
                "evictions=%llu h2d_bytes=%llu failures=%llu\n",
                cache.per_layer, cache.capacity, cache.count,
                (unsigned long long)cache.slot_bytes,
                (unsigned long long)cache.hits,
                (unsigned long long)cache.misses,
                (unsigned long long)cache.evictions,
                (unsigned long long)cache.h2d_bytes,
                (unsigned long long)cache.failures);
    }
    if (cache.device_base) (void)cudaFree(cache.device_base);
    cache.device_base = NULL;
    cache.allocated_bytes = 0;
    cache.slot_bytes = 0;
    cache.gate_expert_bytes = 0;
    cache.down_expert_bytes = 0;
    cache.tick = 0;
    cache.hits = 0;
    cache.misses = 0;
    cache.evictions = 0;
    cache.h2d_bytes = 0;
    cache.failures = 0;
    cache.per_layer = 0;
    cache.capacity = 0;
    cache.count = 0;
    cache.attempted = 0;
    cache.slots.clear();
}

/* Returns 1 when ready, 0 when disabled, and -1 on requested failure. */
static int cuda_iq1_s_vram_cache_prepare(
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes) {
    cuda_iq1_s_vram_cache &cache = g_iq1_s_vram_cache;
    const int requested = cuda_iq1_s_vram_cache_requested_per_layer();
    if (requested == 0) return 0;
    if (requested < 0 || gate_expert_bytes == 0 || down_expert_bytes == 0 ||
        gate_expert_bytes > (UINT64_MAX - down_expert_bytes) / 2ull) {
        cache.attempted = 1;
        cache.failures++;
        return -1;
    }
    const uint64_t slot_bytes = gate_expert_bytes * 2ull + down_expert_bytes;
    const uint32_t capacity = CUDA_IQ1_S_LAYER_COUNT * (uint32_t)requested;
    if (slot_bytes > UINT64_MAX / capacity) {
        cache.attempted = 1;
        cache.failures++;
        return -1;
    }
    const uint64_t allocated_bytes = slot_bytes * capacity;
    if (cache.device_base) {
        return cache.per_layer == (uint32_t)requested &&
               cache.capacity == capacity && cache.slot_bytes == slot_bytes &&
               cache.gate_expert_bytes == gate_expert_bytes &&
               cache.down_expert_bytes == down_expert_bytes ? 1 : -1;
    }
    if (cache.attempted) return -1;
    cache.attempted = 1;
    cache.per_layer = (uint32_t)requested;
    cache.capacity = capacity;
    cache.slot_bytes = slot_bytes;
    cache.gate_expert_bytes = gate_expert_bytes;
    cache.down_expert_bytes = down_expert_bytes;
    cache.allocated_bytes = allocated_bytes;
    cudaError_t err = cudaMalloc((void **)&cache.device_base,
                                 (size_t)allocated_bytes);
    if (err != cudaSuccess) {
        fprintf(stderr,
                "ds4: IQ1_S VRAM cache allocation failed: %s requested=%.3f GiB\n",
                cudaGetErrorString(err),
                (double)allocated_bytes / 1073741824.0);
        (void)cudaGetLastError();
        cache.device_base = NULL;
        cache.failures++;
        return -1;
    }
    try {
        cache.slots.resize(capacity);
    } catch (...) {
        (void)cudaFree(cache.device_base);
        cache.device_base = NULL;
        cache.failures++;
        return -1;
    }
    fprintf(stderr,
            "ds4: [iq1-s-vram-cache] result=ready per_layer=%u capacity=%u "
            "allocated_bytes=%llu slot_bytes=%llu policy=layer-lru\n",
            cache.per_layer, cache.capacity,
            (unsigned long long)cache.allocated_bytes,
            (unsigned long long)cache.slot_bytes);
    return 1;
}

/* Returns the device slot. hit=1 is immediately usable; hit=0 is reserved
 * invalid until the caller completes and fences its H2D upload. */
static int cuda_iq1_s_vram_cache_resolve_slot(
        uint32_t layer_index,
        uint32_t expert_id,
        int *hit,
        int *evicted) {
    if (!hit || !evicted || layer_index >= CUDA_IQ1_S_LAYER_COUNT ||
        expert_id >= 256u)
        return -1;
    *evicted = 0;
    cuda_iq1_s_vram_cache &cache = g_iq1_s_vram_cache;
    if (!cache.device_base || cache.per_layer == 0) return -1;
    const uint32_t first = layer_index * cache.per_layer;
    uint32_t victim = UINT32_MAX;
    uint64_t oldest = UINT64_MAX;
    for (uint32_t i = 0; i < cache.per_layer; i++) {
        const uint32_t slot_index = first + i;
        cuda_iq1_s_vram_cache_slot &slot = cache.slots[slot_index];
        if (slot.valid && slot.expert_id == (int32_t)expert_id) {
            slot.age = ++cache.tick;
            cache.hits++;
            *hit = 1;
            return (int)slot_index;
        }
        if (!slot.valid) {
            victim = slot_index;
            break;
        } else if (slot.age < oldest) {
            oldest = slot.age;
            victim = slot_index;
        }
    }
    if (victim == UINT32_MAX) {
        cache.failures++;
        return -1;
    }
    cuda_iq1_s_vram_cache_slot &slot = cache.slots[victim];
    if (slot.valid) {
        cache.evictions++;
        *evicted = 1;
    }
    slot.valid = 0;
    slot.expert_id = (int32_t)expert_id;
    slot.age = ++cache.tick;
    cache.misses++;
    *hit = 0;
    return (int)victim;
}

static char *cuda_iq1_s_vram_cache_slot_base(uint32_t slot_index) {
    cuda_iq1_s_vram_cache &cache = g_iq1_s_vram_cache;
    if (!cache.device_base || slot_index >= cache.capacity) return NULL;
    return cache.device_base + (uint64_t)slot_index * cache.slot_bytes;
}

static int cuda_prefill_waves_requested(void) {
    const char *env = getenv("DS4_CUDA_PREFILL_WAVES");
    return env && env[0] && strcmp(env, "0") != 0;
}

static int cuda_prefill_wave_double_buffer_requested(void) {
    const char *env = getenv("DS4_CUDA_PREFILL_WAVE_DOUBLE_BUFFER");
    if (!env || !env[0] || strcmp(env, "0") == 0) return 0;
    if (strcmp(env, "1") == 0) return 1;
    fprintf(stderr,
            "ds4: [prefill-wave-overlap] invalid DS4_CUDA_PREFILL_WAVE_DOUBLE_BUFFER=%s; request refused\n",
            env);
    return -1;
}

static uint32_t cuda_prefill_wave_force_experts(void) {
    const char *env = getenv("DS4_CUDA_PREFILL_WAVE_FORCE_EXPERTS");
    if (!env || !env[0]) return 0;
    char *end = NULL;
    errno = 0;
    const unsigned long v = strtoul(env, &end, 10);
    while (end && (*end == ' ' || *end == '\t')) end++;
    if (end == env || errno != 0 || !end || *end != '\0' || v == 0 || v > 256ul) {
        fprintf(stderr,
                "ds4: [prefill-waves] invalid DS4_CUDA_PREFILL_WAVE_FORCE_EXPERTS=%s; request refused\n",
                env);
        return UINT32_MAX;
    }
    return (uint32_t)v;
}

static int cuda_prefill_wave_debug_dump_active(void) {
    static const char *names[] = {
        "DS4_METAL_GRAPH_DUMP_PREFIX",
        "DS4_METAL_GRAPH_DUMP_LOGITS",
        "DS4_METAL_DUMP_PREFILL_LOGITS",
        "DS4_CPU_DUMP_PREFILL_LOGITS",
        "DS4_CPU_DUMP_LOGITS",
        "DS4_CUDA_GRAPH_DUMP_PREFIX",
        "DS4_CUDA_DUMP_PREFILL_LOGITS",
        "DS4_CUDA_DUMP_LOGITS",
        "DS4_CUDA_DUMP_TENSORS",
    };
    for (uint32_t i = 0; i < (uint32_t)(sizeof(names) / sizeof(names[0])); i++) {
        const char *value = getenv(names[i]);
        if (value && value[0]) return 1;
    }
    return 0;
}

static uint32_t cuda_prefill_wave_budget_experts(
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes,
        int double_buffer) {
    if (gate_expert_bytes > (UINT64_MAX - down_expert_bytes) / 2ull) {
        return 0;
    }
    const uint64_t expert_bytes = gate_expert_bytes * 2ull + down_expert_bytes;
    if (expert_bytes == 0) return 0;
    if (double_buffer && expert_bytes > UINT64_MAX / 2ull) return 0;
    size_t free_b = 0, total_b = 0;
    if (cudaMemGetInfo(&free_b, &total_b) != cudaSuccess) {
        (void)cudaGetLastError();
        return 0;
    }
    uint64_t free_bytes = (uint64_t)free_b;
    const uint64_t reserve = cuda_model_stream_reserve_bytes();
    const uint64_t reusable = cuda_u64_saturating_add(
        cuda_u64_saturating_add(g_moe_gather.gate_cap, g_moe_gather.up_cap),
        g_moe_gather.down_cap);
    uint64_t reusable_db = 0;
    if (double_buffer) {
        for (uint32_t i = 0; i < 2u; i++) {
            reusable_db = cuda_u64_saturating_add(
                reusable_db,
                cuda_u64_saturating_add(
                    cuda_u64_saturating_add(g_moe_gather.wave_gate_cap[i],
                                            g_moe_gather.wave_up_cap[i]),
                    g_moe_gather.wave_down_cap[i]));
        }
    }
    if (free_bytes > reserve) free_bytes -= reserve;
    else free_bytes = 0;
    const uint64_t budget = cuda_u64_saturating_add(
        free_bytes, double_buffer ? reusable_db : reusable);
    const uint64_t divisor = double_buffer ? expert_bytes * 2ull : expert_bytes;
    if (divisor == 0) return 0;
    uint64_t experts = budget / divisor;
    if (experts > 256ull) experts = 256ull;
    return (uint32_t)experts;
}

static int cuda_moe_wave_slab_ensure(
        uint32_t parity,
        uint32_t wave_experts,
        uint32_t slot_count,
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes) {
    if (parity >= 2u) return 0;
    const uint64_t cgate = (uint64_t)wave_experts * gate_expert_bytes;
    const uint64_t cdown = (uint64_t)wave_experts * down_expert_bytes;
    if (!cuda_moe_gather_ensure(&g_moe_gather.wave_gate[parity],
                                &g_moe_gather.wave_gate_cap[parity],
                                cgate, "moe wave overlap gate") ||
        !cuda_moe_gather_ensure(&g_moe_gather.wave_up[parity],
                                &g_moe_gather.wave_up_cap[parity],
                                cgate, "moe wave overlap up") ||
        !cuda_moe_gather_ensure(&g_moe_gather.wave_down[parity],
                                &g_moe_gather.wave_down_cap[parity],
                                cdown, "moe wave overlap down") ||
        !cuda_moe_gather_ensure_i32(&g_moe_gather.wave_slot[parity],
                                     &g_moe_gather.wave_slot_cap[parity],
                                     slot_count, "moe wave overlap slots") ||
        !cuda_moe_gather_ensure(
            (char **)&g_moe_gather.wave_pair[parity],
            &g_moe_gather.wave_pair_cap[parity],
            (uint64_t)slot_count * sizeof(uint32_t),
            "moe wave overlap pairs")) {
        return 0;
    }
    if (!g_moe_gather.wave_upload_ready_db[parity] &&
        !cuda_ok(cudaEventCreateWithFlags(
                     &g_moe_gather.wave_upload_ready_db[parity],
                     cudaEventDisableTiming),
                 "moe wave overlap upload event")) {
        return 0;
    }
    if (!g_moe_gather.wave_compute_done[parity] &&
        !cuda_ok(cudaEventCreateWithFlags(
                     &g_moe_gather.wave_compute_done[parity],
                     cudaEventDisableTiming),
                 "moe wave overlap compute event")) {
        return 0;
    }
    return 1;
}

static int cuda_moe_selected_stage_wave(
        const void *model_map,
        uint32_t layer_index,
        uint64_t gate_offset,
        uint64_t up_offset,
        uint64_t down_offset,
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes,
        uint32_t n_total_expert,
        uint32_t n_expert,
        uint32_t n_tokens,
        uint32_t wave_index) {
    if (!g_moe_gather.wave_active || g_moe_gather.wave_max_experts == 0 ||
        n_total_expert == 0 || n_expert == 0 ||
        wave_index >= g_moe_gather.wave_count) {
        return 0;
    }
    const uint32_t slot_count = n_tokens * n_expert;
    const uint32_t begin = wave_index * g_moe_gather.wave_max_experts;
    uint32_t end = begin + g_moe_gather.wave_max_experts;
    const uint32_t compact_count = (uint32_t)g_moe_gather.h_compact_ids.size();
    if (begin >= compact_count) return 0;
    if (end > compact_count) end = compact_count;
    const uint32_t wave_experts = end - begin;
    const uint32_t parity = wave_index & 1u;
    const int double_buffer = g_moe_gather.wave_double_buffer != 0;
    const uint64_t cgate = (uint64_t)wave_experts * gate_expert_bytes;
    const uint64_t cdown = (uint64_t)wave_experts * down_expert_bytes;
    char *gate_dst_base = NULL;
    char *up_dst_base = NULL;
    char *down_dst_base = NULL;
    int32_t *slot_dst_base = NULL;
    cudaEvent_t upload_ready = NULL;
    std::vector<int32_t> *wave_slots_ptr = &g_moe_gather.h_wave_slots;
    std::vector<uint32_t> *wave_pairs_ptr = &g_moe_gather.h_wave_pairs;
    if (double_buffer) {
        if (g_moe_gather.wave_compute_recorded[parity]) {
            if (!cuda_ok(cudaEventSynchronize(
                             g_moe_gather.wave_compute_done[parity]),
                         "moe wave overlap reuse fence")) {
                return 0;
            }
            g_moe_gather.wave_compute_recorded[parity] = 0;
            g_prefill_wave_overlap_stats.reuse_waits =
                cuda_u64_saturating_add(
                    g_prefill_wave_overlap_stats.reuse_waits, 1);
        }
        /* A staged parity may not have reached compute ownership when a prior
         * launch failed. Fence its upload before ensure can resize/free the
         * destination slabs or the pageable metadata vectors are rewritten. */
        if (g_moe_gather.wave_upload_ready_db[parity] &&
            !cuda_ok(cudaEventSynchronize(
                         g_moe_gather.wave_upload_ready_db[parity]),
                     "moe wave overlap prior upload fence")) {
            return 0;
        }
        if (!cuda_moe_wave_slab_ensure(parity, wave_experts, slot_count,
                                       gate_expert_bytes, down_expert_bytes)) {
            return 0;
        }
        gate_dst_base = g_moe_gather.wave_gate[parity];
        up_dst_base = g_moe_gather.wave_up[parity];
        down_dst_base = g_moe_gather.wave_down[parity];
        slot_dst_base = g_moe_gather.wave_slot[parity];
        upload_ready = g_moe_gather.wave_upload_ready_db[parity];
        wave_slots_ptr = &g_moe_gather.h_wave_slots_db[parity];
        wave_pairs_ptr = &g_moe_gather.h_wave_pairs_db[parity];
    } else {
        if (!cuda_moe_gather_ensure(&g_moe_gather.gate, &g_moe_gather.gate_cap,
                                    cgate, "moe wave gate") ||
            !cuda_moe_gather_ensure(&g_moe_gather.up, &g_moe_gather.up_cap,
                                    cgate, "moe wave up") ||
            !cuda_moe_gather_ensure(&g_moe_gather.down, &g_moe_gather.down_cap,
                                    cdown, "moe wave down") ||
            !cuda_moe_gather_ensure_i32(&g_moe_gather.slot,
                                        &g_moe_gather.slot_cap,
                                        slot_count, "moe wave slots")) {
            return 0;
        }
        if (!g_moe_gather.wave_upload_ready &&
            !cuda_ok(cudaEventCreateWithFlags(
                         &g_moe_gather.wave_upload_ready,
                         cudaEventDisableTiming),
                     "moe wave upload event")) {
            return 0;
        }
        gate_dst_base = g_moe_gather.gate;
        up_dst_base = g_moe_gather.up;
        down_dst_base = g_moe_gather.down;
        slot_dst_base = g_moe_gather.slot;
        upload_ready = g_moe_gather.wave_upload_ready;
    }

    std::vector<int32_t> &wave_slots = *wave_slots_ptr;
    std::vector<uint32_t> &wave_pairs = *wave_pairs_ptr;
    wave_slots.assign(slot_count, 0);
    wave_pairs.clear();
    wave_pairs.reserve(slot_count);
    std::vector<int32_t> &e2s = g_moe_gather.h_expert_to_slot;
    e2s.assign(n_total_expert, -1);
    for (uint32_t i = begin; i < end; i++) {
        const int32_t expert = g_moe_gather.h_compact_ids[i];
        if (expert < 0 || (uint32_t)expert >= n_total_expert) return 0;
        e2s[(uint32_t)expert] = (int32_t)(i - begin);
    }
    for (uint32_t i = 0; i < slot_count; i++) {
        const int32_t expert = g_moe_gather.h_sel[i];
        if (expert < 0 || (uint32_t)expert >= n_total_expert) return 0;
        const int32_t wave_slot = e2s[(uint32_t)expert];
        if (wave_slot >= 0) {
            wave_slots[i] = wave_slot;
            wave_pairs.push_back(i);
        }
    }
    if (wave_pairs.empty()) return 0;

    std::vector<cuda_moe_gather::span> &spans = g_moe_gather.h_spans;
    std::vector<uint8_t> &arena_resident = g_moe_gather.h_arena_resident;
    spans.clear();
    spans.reserve((size_t)wave_experts * 3u);
    arena_resident.assign(wave_experts, 0);
    const int arena_active = g_dynamic_arena.host_base &&
        g_dynamic_arena.snapshot_generation != 0 &&
        !g_dynamic_arena.hits_disabled &&
        !g_dynamic_arena.submissions_blocked;
    auto append_span = [&](char *destination,
                           uint64_t source,
                           uint64_t bytes,
                           uint32_t expert,
                           uint8_t part) {
        uint32_t arena_entry = UINT32_MAX;
        char *mirror = cuda_dynamic_arena_observer_mirror_ptr(
            model_map, layer_index, expert, part, source, bytes,
            &arena_entry);
        spans.push_back({
            destination, source, bytes, mirror, arena_entry, part
        });
    };
    for (uint32_t i = 0; i < wave_experts; i++) {
        const uint32_t expert = (uint32_t)g_moe_gather.h_compact_ids[begin + i];
        const uint64_t gate_dst = (uint64_t)i * gate_expert_bytes;
        const uint64_t down_dst = (uint64_t)i * down_expert_bytes;
        if (arena_active) {
            const cuda_dynamic_arena_copy_status arena_status =
                cuda_dynamic_arena_copy_expert_async(
                    g_dynamic_arena,
                    model_map, layer_index, expert,
                    gate_offset, up_offset, down_offset,
                    gate_dst_base + gate_dst,
                    up_dst_base + gate_dst,
                    down_dst_base + down_dst,
                    gate_expert_bytes, gate_expert_bytes,
                    down_expert_bytes);
            if (arena_status == CUDA_DYNAMIC_ARENA_FATAL) {
                (void)cudaStreamSynchronize(g_model_upload_stream);
                return 0;
            }
            if (arena_status == CUDA_DYNAMIC_ARENA_ENQUEUED) {
                arena_resident[i] = 1u;
                continue;
            }
        }
        append_span(gate_dst_base + gate_dst,
                    gate_offset + (uint64_t)expert * gate_expert_bytes,
                    gate_expert_bytes, expert,
                    CUDA_DYNAMIC_ARENA_MIRROR_GATE);
        append_span(up_dst_base + gate_dst,
                    up_offset + (uint64_t)expert * gate_expert_bytes,
                    gate_expert_bytes, expert,
                    CUDA_DYNAMIC_ARENA_MIRROR_UP);
        append_span(down_dst_base + down_dst,
                    down_offset + (uint64_t)expert * down_expert_bytes,
                    down_expert_bytes, expert,
                    CUDA_DYNAMIC_ARENA_MIRROR_DOWN);
    }

    int fill_ok = 0;
#ifdef _WIN32
    const uint32_t io_qd = cuda_moe_io_queue_depth();
    if (io_qd > 1u) {
        fill_ok = cuda_moe_fill_spans_overlapped(model_map, spans, io_qd);
    } else
#endif
    {
        fill_ok = 1;
        for (const cuda_moe_gather::span &s : spans) {
            if (!cuda_moe_fill_span(
                    s.dst, model_map, s.offset, s.bytes, s.mirror)) {
                fill_ok = 0;
                break;
            }
            if (s.mirror) {
                cuda_dynamic_arena_observer_mirror_done(
                    s.arena_entry, s.arena_part, s.bytes);
            }
        }
    }
    int metadata_ok = fill_ok &&
        cuda_ok(cudaMemcpyAsync(slot_dst_base, wave_slots.data(),
                                (size_t)slot_count * sizeof(int32_t),
                                cudaMemcpyHostToDevice,
                                g_model_upload_stream),
                "moe wave slots upload");
    if (metadata_ok && double_buffer) {
        metadata_ok = cuda_ok(cudaMemcpyAsync(
                                  g_moe_gather.wave_pair[parity],
                                  wave_pairs.data(),
                                  (size_t)wave_pairs.size() * sizeof(uint32_t),
                                  cudaMemcpyHostToDevice,
                                  g_model_upload_stream),
                              "moe wave overlap pairs upload");
    }
    if (!metadata_ok ||
        !cuda_ok(cudaEventRecord(upload_ready, g_model_upload_stream),
                 "moe wave upload ready")) {
        (void)cudaStreamSynchronize(g_model_upload_stream);
        return 0;
    }
    uint64_t source_span_bytes = 0;
    uint64_t arena_experts = 0;
    for (const cuda_moe_gather::span &span : spans) {
        source_span_bytes = cuda_u64_saturating_add(
            source_span_bytes, span.bytes);
    }
    for (uint8_t resident : arena_resident) {
        arena_experts += resident != 0;
    }
    uint64_t expert_bytes = UINT64_MAX;
    if (gate_expert_bytes <= (UINT64_MAX - down_expert_bytes) / 2ull) {
        expert_bytes = gate_expert_bytes * 2ull + down_expert_bytes;
    }
    g_moe_gather.wave_source_span_bytes = cuda_u64_saturating_add(
        g_moe_gather.wave_source_span_bytes, source_span_bytes);
    g_moe_gather.wave_arena_h2d_bytes = cuda_u64_saturating_add(
        g_moe_gather.wave_arena_h2d_bytes,
        cuda_u64_saturating_mul(arena_experts, expert_bytes));
    g_moe_gather.wave_arena_experts = cuda_u64_saturating_add(
        g_moe_gather.wave_arena_experts, arena_experts);
    g_moe_gather.wave_direct_experts = cuda_u64_saturating_add(
        g_moe_gather.wave_direct_experts, wave_experts - arena_experts);
    g_moe_gather.slot_tensor.ptr = slot_dst_base;
    g_moe_gather.slot_tensor.bytes = (uint64_t)slot_count * sizeof(int32_t);
    g_moe_gather.slot_tensor.owner = 0;
    g_moe_gather.wave_index = wave_index;
    g_moe_gather.wave_current_experts = wave_experts;
    g_moe_gather.wave_active_pairs = (uint32_t)wave_pairs.size();
    if (double_buffer) {
        g_moe_gather.wave_current_experts_db[parity] = wave_experts;
        g_moe_gather.wave_active_pairs_db[parity] =
            (uint32_t)wave_pairs.size();
    }
    return 1;
}

/* Publish ownership of a parity after any of its slabs have been consumed by
 * stream 0. On the exceptional event-record path, drain stream 0 before
 * returning failure so later requests cannot reuse in-flight storage. */
static int cuda_moe_wave_compute_seal(uint32_t parity) {
    if (parity >= 2u || !g_moe_gather.wave_compute_done[parity]) return 0;
    cudaError_t err = cudaEventRecord(
        g_moe_gather.wave_compute_done[parity], 0);
    if (err == cudaSuccess) {
        g_moe_gather.wave_compute_recorded[parity] = 1;
        g_prefill_wave_overlap_stats.compute_records =
            cuda_u64_saturating_add(
                g_prefill_wave_overlap_stats.compute_records, 1);
        return 1;
    }
    fprintf(stderr, "ds4: CUDA moe wave overlap compute seal failed: %s\n",
            cudaGetErrorString(err));
    (void)cudaGetLastError();
    err = cudaStreamSynchronize(0);
    g_moe_gather.wave_compute_recorded[parity] = 0;
    if (err != cudaSuccess) {
        fprintf(stderr, "ds4: CUDA moe wave overlap failure drain failed: %s\n",
                cudaGetErrorString(err));
        (void)cudaGetLastError();
    }
    return 0;
}

extern "C" int ds4_gpu_routed_moe_prepare_selected(
        const void *model_map, uint64_t model_size,
        uint64_t gate_offset, uint64_t up_offset, uint64_t down_offset,
        uint64_t gate_expert_bytes, uint64_t down_expert_bytes,
        const ds4_gpu_tensor *selected, uint32_t n_expert, uint32_t n_tokens) {
    g_moe_selected_prepared.valid = 0;
    const char *env = getenv("DS4_CUDA_MOE_OVERLAP_SHARED");
    const char *full_env = getenv("DS4_CUDA_MOE_OVERLAP_SHARED_FULL");
    const int minimal_enabled = env && env[0] && strcmp(env, "0") != 0;
    const int full_enabled = full_env && full_env[0] && strcmp(full_env, "0") != 0;
    if ((!minimal_enabled && !full_enabled) ||
        getenv("DS4_CUDA_MOE_NO_SELECTED_LOAD") != NULL ||
        cuda_moe_expert_cache_requested() != 0) {
        return 0;
    }
    const uint32_t n_total_expert = 256u;
    if (!model_map || !selected || !selected->ptr || n_expert == 0 || n_tokens == 0 ||
        gate_expert_bytes == 0 || down_expert_bytes == 0 ||
        n_tokens > UINT32_MAX / n_expert) {
        return 0;
    }
    const uint32_t slot_count = n_tokens * n_expert;
    if (selected->bytes < (uint64_t)slot_count * sizeof(int32_t) ||
        gate_expert_bytes > UINT64_MAX / n_total_expert ||
        down_expert_bytes > UINT64_MAX / n_total_expert) {
        return 0;
    }
    const uint64_t gate_bytes = (uint64_t)n_total_expert * gate_expert_bytes;
    const uint64_t down_bytes = (uint64_t)n_total_expert * down_expert_bytes;
    if (gate_offset > model_size || gate_bytes > model_size - gate_offset ||
        up_offset > model_size || gate_bytes > model_size - up_offset ||
        down_offset > model_size || down_bytes > model_size - down_offset) {
        return 0;
    }
    if (cuda_model_range_in_window(model_map, gate_offset, gate_bytes) &&
        cuda_model_range_in_window(model_map, up_offset, gate_bytes) &&
        cuda_model_range_in_window(model_map, down_offset, down_bytes)) {
        return 0;
    }

    g_moe_gather.h_sel.resize(slot_count);
    if (!cuda_ok(cudaMemcpy(g_moe_gather.h_sel.data(), selected->ptr,
                            (size_t)slot_count * sizeof(int32_t),
                            cudaMemcpyDeviceToHost), "moe overlap selected D2H")) {
        return 0;
    }
    g_moe_selected_prepared.model_map = model_map;
    g_moe_selected_prepared.selected_ptr = selected->ptr;
    g_moe_selected_prepared.gate_offset = gate_offset;
    g_moe_selected_prepared.up_offset = up_offset;
    g_moe_selected_prepared.down_offset = down_offset;
    g_moe_selected_prepared.gate_expert_bytes = gate_expert_bytes;
    g_moe_selected_prepared.down_expert_bytes = down_expert_bytes;
    g_moe_selected_prepared.n_expert = n_expert;
    g_moe_selected_prepared.n_tokens = n_tokens;
    g_moe_selected_prepared.full = full_enabled;
    g_moe_selected_prepared.valid = 1;
    return 1;
}

static int cuda_nested_residual_resolve_exact(
        uint32_t layer_index, uint32_t expert, uint32_t *slot_out) {
    cuda_nested_residual_state &state = g_nested_residual;
    if (state.residual_cache_enabled) {
        fprintf(stderr,
                "ds4: nested residual CPU resolver refused in residual-cache mode\n");
        cuda_nested_residual_note_cache_invariant_failure(state);
        state.failures++;
        state.hard_failure = 1;
        return -1;
    }
    if (!slot_out || !state.active ||
        layer_index >= CUDA_NESTED_RESIDUAL_LAYER_COUNT ||
        expert >= CUDA_NESTED_RESIDUAL_EXPERT_COUNT ||
        !state.layers[layer_index].ready) {
        return 0;
    }
    const int profile = state.profile_enabled != 0;
    const double lookup_started = profile ? cuda_wall_sec() : 0.0;
    if (profile) state.profile_lookup_calls++;
    const uint32_t map_index = layer_index *
        CUDA_NESTED_RESIDUAL_EXPERT_COUNT + expert;
    const int32_t cached = state.cache_by_layer_expert[map_index];
    if (cached >= 0 && (uint32_t)cached < state.cache_capacity) {
        cuda_nested_residual_cache_slot &slot =
            state.cache_slots[(uint32_t)cached];
        if (slot.valid && slot.layer == layer_index && slot.expert == expert) {
            if (profile) {
                state.profile_lookup_seconds +=
                    cuda_wall_sec() - lookup_started;
            }
            slot.age = ++state.age;
            state.exact_cache_hits++;
            *slot_out = (uint32_t)cached;
            return 1;
        }
        if (profile) {
            state.profile_lookup_seconds += cuda_wall_sec() - lookup_started;
        }
        state.reconstruction_mismatches++;
        state.failures++;
        return -1;
    }

    uint32_t victim = UINT32_MAX;
    uint64_t oldest = UINT64_MAX;
    for (uint32_t i = 0; i < state.cache_capacity; i++) {
        const cuda_nested_residual_cache_slot &slot = state.cache_slots[i];
        if (!slot.valid) {
            victim = i;
            break;
        }
        if (slot.age < oldest) {
            oldest = slot.age;
            victim = i;
        }
    }
    if (victim == UINT32_MAX) {
        if (profile) {
            state.profile_lookup_seconds += cuda_wall_sec() - lookup_started;
        }
        state.failures++;
        return -1;
    }
    if (profile) {
        state.profile_lookup_seconds += cuda_wall_sec() - lookup_started;
    }
    cuda_nested_residual_cache_slot &slot = state.cache_slots[victim];
    const int victim_was_valid = slot.valid != 0;

    cuda_nested_residual_layer &layer = state.layers[layer_index];
    const uint64_t residual_offset = layer.residual_layer_start +
        (uint64_t)expert * layer.residual_expert_bytes;
    if (layer.residual_expert_bytes > state.residual_scratch.size() ||
        residual_offset > state.file_size ||
        layer.residual_expert_bytes > state.file_size - residual_offset) {
        state.failures++;
        return -1;
    }
    const double pread_started = profile ? cuda_wall_sec() : 0.0;
    const int pread_ok = cuda_pread_full(
        &state.file, state.residual_scratch.data(),
        layer.residual_expert_bytes, residual_offset);
    if (profile) {
        state.profile_pread_calls++;
        state.profile_pread_seconds += cuda_wall_sec() - pread_started;
    }
    if (!pread_ok) {
        state.failures++;
        return -1;
    }
    state.exact_cache_misses++;
    state.residual_preads++;
    state.residual_bytes += layer.residual_expert_bytes;

    if (slot.copy_pending) {
        const double wait_started = profile ? cuda_wall_sec() : 0.0;
        const cudaError_t wait = cudaEventSynchronize(slot.reuse_event);
        if (profile) {
            state.profile_reuse_wait_calls++;
            state.profile_reuse_wait_seconds +=
                cuda_wall_sec() - wait_started;
        }
        if (wait != cudaSuccess) {
            fprintf(stderr,
                    "ds4: nested residual cache reuse wait failed: %s\n",
                    cudaGetErrorString(wait));
            (void)cudaGetLastError();
            state.failures++;
            return -1;
        }
        slot.copy_pending = 0;
    }
    if (slot.valid) {
        const uint32_t old_index = slot.layer *
            CUDA_NESTED_RESIDUAL_EXPERT_COUNT + slot.expert;
        if (state.cache_by_layer_expert[old_index] == (int32_t)victim) {
            state.cache_by_layer_expert[old_index] = -1;
        }
        slot.valid = 0;
    }

    uint8_t base_pageable = 0;
    const uint8_t *expert_base = cuda_nested_residual_base_expert(
        state, layer_index, expert, &base_pageable);
    if (!expert_base) {
        state.failures++;
        return -1;
    }
    if (base_pageable) {
        state.base_pageable_hits++;
    } else {
        state.base_pinned_hits++;
    }
    uint8_t *native = state.cache +
        (uint64_t)victim * state.cache_slot_bytes;
    if (profile) state.profile_reconstruct_calls++;
    for (uint32_t part = 0; part < CUDA_NESTED_RESIDUAL_PART_COUNT;
         part++) {
        const cuda_nested_residual_record &record = layer.records[part];
        const uint64_t blocks = (record.ncols / 256u) * record.nrows;
        const uint8_t *base = expert_base + record.base_kind_offset;
        const uint8_t *residual = state.residual_scratch.data() +
            record.kind_offset;
        uint8_t *destination = native + record.native_kind_offset;
        const double reconstruct_started = profile ? cuda_wall_sec() : 0.0;
        for (uint64_t block = 0; block < blocks; block++) {
            cuda_nested_join_block(
                record.source_type,
                base + block * record.base_block_bytes,
                residual + block * record.residual_block_bytes,
                destination + block * record.native_block_bytes);
        }
        if (profile) {
            state.profile_reconstruct_blocks += blocks;
            state.profile_reconstruct_seconds +=
                cuda_wall_sec() - reconstruct_started;
        }
        if (getenv("DS4_NESTED_RESIDUAL_VERIFY_RECONSTRUCTION") != NULL) {
            const uint8_t *authoritative = state.source_map +
                record.source_offset +
                (uint64_t)expert * record.native_kind_bytes;
            const double verify_started = profile ? cuda_wall_sec() : 0.0;
            const int verify_mismatch =
                memcmp(destination, authoritative,
                       (size_t)record.native_kind_bytes) != 0;
            if (profile) {
                state.profile_verify_calls++;
                state.profile_verify_bytes += record.native_kind_bytes;
                state.profile_verify_seconds +=
                    cuda_wall_sec() - verify_started;
            }
            if (verify_mismatch) {
                state.reconstruction_mismatches++;
                state.failures++;
                return -1;
            }
        }
    }
    slot.layer = layer_index;
    slot.expert = expert;
    slot.age = ++state.age;
    slot.valid = 1;
    if (!victim_was_valid && state.cache_count < state.cache_capacity) {
        state.cache_count++;
    }
    state.cache_by_layer_expert[map_index] = (int32_t)victim;
    state.reconstructed_experts++;
    *slot_out = victim;
    return 1;
}

static int cuda_nested_residual_cache_scan_range(
        cuda_nested_residual_state &state,
        uint32_t layer_index,
        uint32_t *begin_out,
        uint32_t *count_out) {
    if (!begin_out || !count_out ||
        layer_index >= CUDA_NESTED_RESIDUAL_LAYER_COUNT ||
        state.cache_capacity == 0) {
        cuda_nested_residual_note_cache_invariant_failure(state);
        return 0;
    }
    uint32_t begin = 0;
    uint32_t count = state.cache_capacity;
    if (state.cache_layer_partitioned) {
        begin = state.cache_layer_begin[layer_index];
        count = state.cache_layer_capacity[layer_index];
        if (count == 0 || begin > state.cache_capacity ||
            count > state.cache_capacity - begin) {
            cuda_nested_residual_note_cache_invariant_failure(state);
            return 0;
        }
    }
    *begin_out = begin;
    *count_out = count;
    return 1;
}

static int cuda_nested_residual_resolve_residual_slot_locked(
        uint32_t layer_index, uint32_t expert, uint32_t *slot_out) {
    cuda_nested_residual_state &state = g_nested_residual;
    if (!slot_out || !state.residual_cache_enabled ||
        layer_index >= CUDA_NESTED_RESIDUAL_LAYER_COUNT ||
        expert >= CUDA_NESTED_RESIDUAL_EXPERT_COUNT ||
        !state.layers[layer_index].ready) {
        cuda_nested_residual_note_cache_invariant_failure(state);
        state.failures++;
        return -1;
    }
    cuda_nested_residual_layer &layer = state.layers[layer_index];
    if (layer.residual_expert_bytes == 0 ||
        layer.residual_expert_bytes > state.cache_slot_bytes ||
        state.cache_capacity == 0 ||
        state.cache_by_layer_expert.size() <
            CUDA_NESTED_RESIDUAL_LAYER_COUNT *
                CUDA_NESTED_RESIDUAL_EXPERT_COUNT) {
        cuda_nested_residual_note_cache_invariant_failure(state);
        state.failures++;
        return -1;
    }

    uint32_t scan_begin = 0;
    uint32_t scan_count = 0;
    if (!cuda_nested_residual_cache_scan_range(
            state, layer_index, &scan_begin, &scan_count)) {
        state.failures++;
        return -1;
    }

    const int profile = state.profile_enabled != 0;
    const double lookup_started = profile ? cuda_wall_sec() : 0.0;
    if (profile) state.profile_lookup_calls++;
    const uint32_t map_index = layer_index *
        CUDA_NESTED_RESIDUAL_EXPERT_COUNT + expert;
    const int32_t cached = state.cache_by_layer_expert[map_index];
    if (cached >= 0 && (uint32_t)cached < state.cache_capacity) {
        if ((uint32_t)cached < scan_begin ||
            (uint32_t)cached >= scan_begin + scan_count) {
            cuda_nested_residual_note_cache_invariant_failure(state);
            state.failures++;
            return -1;
        }
        cuda_nested_residual_cache_slot &slot =
            state.cache_slots[(uint32_t)cached];
        if (slot.valid && slot.layer == layer_index && slot.expert == expert) {
            if (profile) {
                state.profile_lookup_seconds +=
                    cuda_wall_sec() - lookup_started;
            }
            slot.age = ++state.age;
            state.residual_cache_hits++;
            state.residual_cache_pread_bytes_avoided +=
                layer.residual_expert_bytes;
            *slot_out = (uint32_t)cached;
            return 1;
        }
        if (profile) {
            state.profile_lookup_seconds += cuda_wall_sec() - lookup_started;
        }
        cuda_nested_residual_note_cache_invariant_failure(state);
        state.reconstruction_mismatches++;
        state.failures++;
        return -1;
    }

    uint32_t victim = UINT32_MAX;
    uint64_t oldest = UINT64_MAX;
    for (uint32_t offset = 0; offset < scan_count; offset++) {
        const uint32_t i = scan_begin + offset;
        const cuda_nested_residual_cache_slot &slot = state.cache_slots[i];
        if (!slot.valid) {
            victim = i;
            break;
        }
        if (slot.age < oldest) {
            oldest = slot.age;
            victim = i;
        }
    }
    if (victim == UINT32_MAX) {
        if (profile) {
            state.profile_lookup_seconds += cuda_wall_sec() - lookup_started;
        }
        cuda_nested_residual_note_cache_invariant_failure(state);
        state.failures++;
        return -1;
    }
    if (profile) {
        state.profile_lookup_seconds += cuda_wall_sec() - lookup_started;
    }

    cuda_nested_residual_cache_slot &slot = state.cache_slots[victim];
    if (slot.copy_pending) {
        const double wait_started = profile ? cuda_wall_sec() : 0.0;
        const cudaError_t wait = cudaEventSynchronize(slot.reuse_event);
        if (profile) {
            state.profile_reuse_wait_calls++;
            state.profile_reuse_wait_seconds +=
                cuda_wall_sec() - wait_started;
        }
        if (wait != cudaSuccess) {
            fprintf(stderr,
                    "ds4: nested residual residual-cache reuse wait failed: %s\n",
                    cudaGetErrorString(wait));
            (void)cudaGetLastError();
            cuda_nested_residual_note_cache_invariant_failure(state);
            state.failures++;
            return -1;
        }
        slot.copy_pending = 0;
    }
    if (slot.valid) {
        if (state.cache_layer_partitioned && slot.layer != layer_index) {
            cuda_nested_residual_note_cache_invariant_failure(state);
            state.failures++;
            return -1;
        }
        const uint32_t old_index = slot.layer *
            CUDA_NESTED_RESIDUAL_EXPERT_COUNT + slot.expert;
        if (old_index < state.cache_by_layer_expert.size() &&
            state.cache_by_layer_expert[old_index] == (int32_t)victim) {
            state.cache_by_layer_expert[old_index] = -1;
        }
        slot.valid = 0;
        if (state.cache_count > 0) state.cache_count--;
        state.residual_cache_evictions++;
    }

    const uint64_t residual_offset = layer.residual_layer_start +
        (uint64_t)expert * layer.residual_expert_bytes;
    if (residual_offset > state.file_size ||
        layer.residual_expert_bytes > state.file_size - residual_offset) {
        cuda_nested_residual_note_cache_invariant_failure(state);
        state.failures++;
        return -1;
    }
    uint8_t *destination = state.cache +
        (uint64_t)victim * state.cache_slot_bytes;
    const double pread_started = profile ? cuda_wall_sec() : 0.0;
    const int pread_ok = cuda_pread_full(
        &state.file, destination, layer.residual_expert_bytes,
        residual_offset);
    if (profile) {
        state.profile_pread_calls++;
        state.profile_pread_seconds += cuda_wall_sec() - pread_started;
    }
    if (!pread_ok) {
        state.failures++;
        return -1;
    }

    state.residual_cache_misses++;
    state.residual_preads++;
    state.residual_bytes += layer.residual_expert_bytes;
    state.residual_cache_pread_bytes += layer.residual_expert_bytes;
    slot.layer = layer_index;
    slot.expert = expert;
    slot.age = ++state.age;
    slot.valid = 1;
    if (state.cache_count < state.cache_capacity) {
        state.cache_count++;
    }
    state.cache_by_layer_expert[map_index] = (int32_t)victim;
    *slot_out = victim;
    return 1;
}

static int cuda_nested_residual_join_to_device_exact(
        uint32_t layer_index, uint32_t expert,
        uint64_t gate_offset, uint64_t up_offset, uint64_t down_offset,
        uint64_t gate_expert_bytes, uint64_t down_expert_bytes,
        char *dst_gate, char *dst_up, char *dst_down,
        cudaStream_t stream) {
    cuda_nested_residual_state &state = g_nested_residual;
    if (state.hard_failure) return -1;
    if (!cuda_nested_residual_gpu_join_requested()) return 0;
    state.gpu_join_observed = 1u;
    if (!state.active || !state.gpu_join_ready || !stream ||
        layer_index >= CUDA_NESTED_RESIDUAL_LAYER_COUNT ||
        !state.layers[layer_index].ready) {
        state.gpu_join_failures++;
        state.failures++;
        return -1;
    }
    if (expert >= CUDA_NESTED_RESIDUAL_EXPERT_COUNT ||
        !dst_gate || !dst_up || !dst_down) {
        state.gpu_join_failures++;
        state.failures++;
        return -1;
    }
    cuda_nested_residual_layer &layer = state.layers[layer_index];
    const cuda_nested_residual_record &gate = layer.records[0];
    const cuda_nested_residual_record &up = layer.records[1];
    const cuda_nested_residual_record &down = layer.records[2];
    uint64_t residual_offset = 0;
    const uint8_t *expert_base = NULL;
    uint8_t base_pageable = 0;
    const uint8_t *residual_host_source = state.gpu_join_residual_host;
    uint32_t residual_cache_slot = UINT32_MAX;
    double join_started = 0.0;
    cudaError_t err = cudaSuccess;
    char *dst[CUDA_NESTED_RESIDUAL_PART_COUNT] = {
        dst_gate, dst_up, dst_down
    };
    if (gate.source_offset != gate_offset || up.source_offset != up_offset ||
        down.source_offset != down_offset ||
        gate.native_kind_bytes != gate_expert_bytes ||
        up.native_kind_bytes != gate_expert_bytes ||
        down.native_kind_bytes != down_expert_bytes ||
        layer.base_expert_bytes > state.gpu_join_base_device_bytes ||
        layer.residual_expert_bytes > state.gpu_join_residual_device_bytes ||
        layer.native_expert_bytes > state.gpu_join_verify_host_bytes) {
        fprintf(stderr,
                "ds4: nested residual GPU join geometry mismatch layer=%u\n",
                layer_index);
        state.gpu_join_failures++;
        state.failures++;
        return -1;
    }
    for (uint32_t part = 0; part < CUDA_NESTED_RESIDUAL_PART_COUNT; part++) {
        const cuda_nested_residual_record &record = layer.records[part];
        const uint64_t residual_kind_bytes =
            record.residual_bytes / record.nexperts;
        if ((record.source_type != 16u && record.source_type != 10u) ||
            record.residual_block_bytes != 32u ||
            record.base_kind_offset > layer.base_expert_bytes ||
            record.base_kind_bytes >
                layer.base_expert_bytes - record.base_kind_offset ||
            record.kind_offset > layer.residual_expert_bytes ||
            residual_kind_bytes >
                layer.residual_expert_bytes - record.kind_offset) {
            state.gpu_join_failures++;
            state.failures++;
            return -1;
        }
    }
    if (!state.gpu_join_mutex_ready || !state.gpu_join_event_created) {
        state.gpu_join_failures++;
        state.failures++;
        return -1;
    }
    os_mutex_lock(&state.gpu_join_mutex);
    int scratch_locked = 1;
    int stream_touched = 0;
    if (state.gpu_join_event_pending) {
        const double wait_started = cuda_wall_sec();
        const cudaError_t wait =
            cudaEventSynchronize(state.gpu_join_done_event);
        state.gpu_join_wait_calls++;
        state.gpu_join_wait_seconds += cuda_wall_sec() - wait_started;
        if (wait != cudaSuccess) {
            fprintf(stderr,
                    "ds4: nested residual GPU join scratch wait failed: %s\n",
                    cudaGetErrorString(wait));
            (void)cudaGetLastError();
            state.gpu_join_failures++;
            state.failures++;
            os_mutex_unlock(&state.gpu_join_mutex);
            return -1;
        }
        state.gpu_join_event_pending = 0u;
    }
    if (state.residual_cache_enabled) {
        if (cuda_nested_residual_resolve_residual_slot_locked(
                layer_index, expert, &residual_cache_slot) != 1) {
            state.gpu_join_failures++;
            goto fail_locked;
        }
        residual_host_source = state.cache +
            (uint64_t)residual_cache_slot * state.cache_slot_bytes;
    } else {
        residual_offset = layer.residual_layer_start +
            (uint64_t)expert * layer.residual_expert_bytes;
        if (residual_offset > state.file_size ||
            layer.residual_expert_bytes > state.file_size - residual_offset) {
            state.gpu_join_failures++;
            state.failures++;
            goto fail_locked;
        }
        if (!cuda_pread_full(&state.file, state.gpu_join_residual_host,
                             layer.residual_expert_bytes, residual_offset)) {
            state.gpu_join_failures++;
            state.failures++;
            goto fail_locked;
        }
        state.exact_cache_misses++;
        state.residual_preads++;
        state.residual_bytes += layer.residual_expert_bytes;
    }

    expert_base = cuda_nested_residual_base_expert(
        state, layer_index, expert, &base_pageable);
    if (!expert_base) {
        state.gpu_join_failures++;
        state.failures++;
        goto fail_locked;
    }
    join_started = cuda_wall_sec();
    err = cudaMemcpyAsync(
        state.gpu_join_base_device, expert_base,
        (size_t)layer.base_expert_bytes, cudaMemcpyHostToDevice, stream);
    if (err == cudaSuccess) stream_touched = 1;
    if (err == cudaSuccess) {
        err = cudaMemcpyAsync(
            state.gpu_join_residual_device, residual_host_source,
            (size_t)layer.residual_expert_bytes,
            cudaMemcpyHostToDevice, stream);
        if (err == cudaSuccess) stream_touched = 1;
    }
    if (err != cudaSuccess) {
        fprintf(stderr,
                "ds4: nested residual GPU join H2D failed: %s\n",
                cudaGetErrorString(err));
        (void)cudaGetLastError();
        state.gpu_join_failures++;
        state.failures++;
        goto fail_locked;
    }
    state.gpu_join_base_h2d_bytes += layer.base_expert_bytes;
    state.gpu_join_residual_h2d_bytes += layer.residual_expert_bytes;
    if (base_pageable) {
        state.base_pageable_hits++;
        state.base_pageable_h2d_bytes += layer.base_expert_bytes;
    } else {
        state.base_pinned_hits++;
        state.base_pinned_h2d_bytes += layer.base_expert_bytes;
    }
    if (state.residual_cache_enabled) {
        state.residual_cache_h2d_bytes += layer.residual_expert_bytes;
        state.residual_cache_cached_join_calls++;
    }
    state.h2d_bytes +=
        layer.base_expert_bytes + layer.residual_expert_bytes;

    for (uint32_t part = 0; part < CUDA_NESTED_RESIDUAL_PART_COUNT; part++) {
        const cuda_nested_residual_record &record = layer.records[part];
        const uint64_t blocks = (record.ncols / 256u) * record.nrows;
        const uint32_t threads = 128u;
        const uint32_t grid = (uint32_t)((blocks + threads - 1u) / threads);
        cuda_nested_join_blocks_kernel<<<grid, threads, 0, stream>>>(
            record.source_type,
            state.gpu_join_base_device + record.base_kind_offset,
            state.gpu_join_residual_device + record.kind_offset,
            (uint8_t *)dst[part],
            blocks,
            record.base_block_bytes,
            record.residual_block_bytes,
            record.native_block_bytes);
        err = cudaGetLastError();
        if (err == cudaSuccess) stream_touched = 1;
        if (err != cudaSuccess) {
            fprintf(stderr,
                    "ds4: nested residual GPU join launch failed: %s\n",
                    cudaGetErrorString(err));
            (void)cudaGetLastError();
            state.gpu_join_failures++;
            state.failures++;
            goto fail_locked;
        }
        state.gpu_join_blocks += blocks;
    }
    state.gpu_join_calls++;
    state.gpu_join_seconds += cuda_wall_sec() - join_started;
    state.reconstructed_experts++;

    if (getenv("DS4_NESTED_RESIDUAL_VERIFY_RECONSTRUCTION") != NULL) {
        const double verify_started = cuda_wall_sec();
        for (uint32_t part = 0; part < CUDA_NESTED_RESIDUAL_PART_COUNT;
             part++) {
            const cuda_nested_residual_record &record = layer.records[part];
            err = cudaMemcpyAsync(
                state.gpu_join_verify_host, dst[part],
                (size_t)record.native_kind_bytes,
                cudaMemcpyDeviceToHost, stream);
            if (err != cudaSuccess) {
                (void)cudaGetLastError();
                state.gpu_join_failures++;
                state.failures++;
                goto fail_locked;
            }
            err = cudaStreamSynchronize(stream);
            if (err != cudaSuccess) {
                (void)cudaGetLastError();
                state.gpu_join_failures++;
                state.failures++;
                goto fail_locked;
            }
            stream_touched = 0;
            const uint8_t *authoritative = state.source_map +
                record.source_offset +
                (uint64_t)expert * record.native_kind_bytes;
            state.gpu_join_verify_calls++;
            state.gpu_join_verify_bytes += record.native_kind_bytes;
            if (memcmp(state.gpu_join_verify_host, authoritative,
                       (size_t)record.native_kind_bytes) != 0) {
                state.gpu_join_verify_mismatches++;
                state.reconstruction_mismatches++;
                state.gpu_join_failures++;
                state.failures++;
                state.gpu_join_verify_seconds +=
                    cuda_wall_sec() - verify_started;
                goto fail_locked;
            }
        }
        state.gpu_join_verify_seconds += cuda_wall_sec() - verify_started;
    }
    err = cudaEventRecord(state.gpu_join_done_event, stream);
    if (err != cudaSuccess) {
        fprintf(stderr,
                "ds4: nested residual GPU join completion event failed: %s\n",
                cudaGetErrorString(err));
        (void)cudaGetLastError();
        state.gpu_join_failures++;
        state.failures++;
        goto fail_locked;
    }
    state.gpu_join_event_pending = 1u;
    os_mutex_unlock(&state.gpu_join_mutex);
    scratch_locked = 0;
    return 1;

fail_locked:
    if (stream_touched) (void)cudaStreamSynchronize(stream);
    if (scratch_locked) os_mutex_unlock(&state.gpu_join_mutex);
    return -1;
}

/* Resolve one covered expert to authoritative native bytes, then copy it into
 * the route worker's pinned host buffers. CUDA ownership remains with the
 * route worker so a successful GPU-cache hit never touches this path. */
static int cuda_nested_residual_fill_route_host_exact(
        uint32_t layer_index, uint32_t expert,
        uint64_t gate_offset, uint64_t up_offset, uint64_t down_offset,
        uint64_t gate_expert_bytes, uint64_t down_expert_bytes,
        char *host_gate, char *host_up, char *host_down) {
    cuda_nested_residual_state &state = g_nested_residual;
    if (state.hard_failure) return -1;
    if (!state.active ||
        layer_index >= CUDA_NESTED_RESIDUAL_LAYER_COUNT ||
        !state.layers[layer_index].ready) {
        return 0;
    }
    if (expert >= CUDA_NESTED_RESIDUAL_EXPERT_COUNT ||
        !host_gate || !host_up || !host_down) {
        state.failures++;
        state.gpu_cache_failures++;
        state.hard_failure = 1;
        return -1;
    }
    cuda_nested_residual_layer &layer = state.layers[layer_index];
    const cuda_nested_residual_record &gate = layer.records[0];
    const cuda_nested_residual_record &up = layer.records[1];
    const cuda_nested_residual_record &down = layer.records[2];
    if (gate.source_offset != gate_offset || up.source_offset != up_offset ||
        down.source_offset != down_offset ||
        gate.native_kind_bytes != gate_expert_bytes ||
        up.native_kind_bytes != gate_expert_bytes ||
        down.native_kind_bytes != down_expert_bytes) {
        fprintf(stderr,
                "ds4: nested residual GPU-cache geometry mismatch layer=%u\n",
                layer_index);
        state.failures++;
        state.gpu_cache_failures++;
        state.hard_failure = 1;
        return -1;
    }
    uint32_t cache_slot = 0;
    if (cuda_nested_residual_resolve_exact(
            layer_index, expert, &cache_slot) <= 0) {
        state.gpu_cache_failures++;
        state.hard_failure = 1;
        return -1;
    }
    const uint8_t *native = state.cache +
        (uint64_t)cache_slot * state.cache_slot_bytes;
    const double copy_started =
        state.profile_enabled ? cuda_wall_sec() : 0.0;
    memcpy(host_gate, native + gate.native_kind_offset,
           (size_t)gate_expert_bytes);
    memcpy(host_up, native + up.native_kind_offset,
           (size_t)gate_expert_bytes);
    memcpy(host_down, native + down.native_kind_offset,
           (size_t)down_expert_bytes);
    if (state.profile_enabled) {
        state.profile_host_copy_calls++;
        state.profile_host_copy_seconds += cuda_wall_sec() - copy_started;
    }
    const uint64_t native_bytes =
        gate_expert_bytes * 2ull + down_expert_bytes;
    state.route_host_fills++;
    state.route_host_bytes += native_bytes;
    return 1;
}

/* Returns 1 when the target layer was filled from nested exact bytes, 0 when
 * the layer is not covered, and -1 for a fail-closed covered-layer error. */
static int cuda_nested_residual_upload_exact(
        uint32_t layer_index,
        uint64_t gate_offset, uint64_t up_offset, uint64_t down_offset,
        uint64_t gate_expert_bytes, uint64_t down_expert_bytes,
        const std::vector<int32_t> &compact) {
    cuda_nested_residual_state &state = g_nested_residual;
    if (state.hard_failure) return -1;
    if (!state.active ||
        layer_index >= CUDA_NESTED_RESIDUAL_LAYER_COUNT ||
        !state.layers[layer_index].ready) {
        return 0;
    }
    cuda_nested_residual_layer &layer = state.layers[layer_index];
    const cuda_nested_residual_record &gate = layer.records[0];
    const cuda_nested_residual_record &up = layer.records[1];
    const cuda_nested_residual_record &down = layer.records[2];
    if (gate.source_offset != gate_offset || up.source_offset != up_offset ||
        down.source_offset != down_offset ||
        gate.native_kind_bytes != gate_expert_bytes ||
        up.native_kind_bytes != gate_expert_bytes ||
        down.native_kind_bytes != down_expert_bytes) {
        fprintf(stderr,
                "ds4: nested residual runtime geometry mismatch layer=%u\n",
                layer_index);
        state.failures++;
        state.hard_failure = 1;
        return -1;
    }
    if (cuda_nested_residual_gpu_join_requested()) {
        for (uint32_t i = 0; i < compact.size(); i++) {
            const int32_t selected = compact[i];
            if (selected < 0 ||
                (uint32_t)selected >= CUDA_NESTED_RESIDUAL_EXPERT_COUNT) {
                state.failures++;
                state.gpu_join_failures++;
                state.hard_failure = 1;
                return -1;
            }
            const uint64_t gate_dst = (uint64_t)i * gate_expert_bytes;
            const uint64_t down_dst = (uint64_t)i * down_expert_bytes;
            if (cuda_nested_residual_join_to_device_exact(
                    layer_index, (uint32_t)selected,
                    gate_offset, up_offset, down_offset,
                    gate_expert_bytes, down_expert_bytes,
                    g_moe_gather.gate + gate_dst,
                    g_moe_gather.up + gate_dst,
                    g_moe_gather.down + down_dst,
                    g_model_upload_stream) != 1) {
                state.hard_failure = 1;
                return -1;
            }
        }
        state.router_open_calls++;
        return 1;
    }
    for (uint32_t i = 0; i < compact.size(); i++) {
        const int32_t selected = compact[i];
        if (selected < 0 ||
            (uint32_t)selected >= CUDA_NESTED_RESIDUAL_EXPERT_COUNT) {
            state.failures++;
            state.hard_failure = 1;
            return -1;
        }
        uint32_t cache_slot = 0;
        if (cuda_nested_residual_resolve_exact(
                layer_index, (uint32_t)selected, &cache_slot) <= 0) {
            state.hard_failure = 1;
            return -1;
        }
        const uint8_t *native = state.cache +
            (uint64_t)cache_slot * state.cache_slot_bytes;
        const uint64_t gate_dst = (uint64_t)i * gate_expert_bytes;
        const uint64_t down_dst = (uint64_t)i * down_expert_bytes;
        if (cudaMemcpyAsync(
                g_moe_gather.gate + gate_dst,
                native + gate.native_kind_offset,
                (size_t)gate_expert_bytes,
                cudaMemcpyHostToDevice, g_model_upload_stream) != cudaSuccess ||
            cudaMemcpyAsync(
                g_moe_gather.up + gate_dst,
                native + up.native_kind_offset,
                (size_t)gate_expert_bytes,
                cudaMemcpyHostToDevice, g_model_upload_stream) != cudaSuccess ||
            cudaMemcpyAsync(
                g_moe_gather.down + down_dst,
                native + down.native_kind_offset,
                (size_t)down_expert_bytes,
                cudaMemcpyHostToDevice, g_model_upload_stream) != cudaSuccess) {
            (void)cudaGetLastError();
            (void)cudaStreamSynchronize(g_model_upload_stream);
            state.failures++;
            state.hard_failure = 1;
            return -1;
        }
        cuda_nested_residual_cache_slot &slot =
            state.cache_slots[cache_slot];
        if (!slot.event_created) {
            const cudaError_t created = cudaEventCreateWithFlags(
                &slot.reuse_event, cudaEventDisableTiming);
            if (created != cudaSuccess) {
                fprintf(stderr,
                        "ds4: nested residual reuse event creation failed: %s\n",
                        cudaGetErrorString(created));
                (void)cudaGetLastError();
                (void)cudaStreamSynchronize(g_model_upload_stream);
                state.failures++;
                state.hard_failure = 1;
                return -1;
            }
            slot.event_created = 1;
        }
        const cudaError_t recorded = cudaEventRecord(
            slot.reuse_event, g_model_upload_stream);
        if (recorded != cudaSuccess) {
            fprintf(stderr,
                    "ds4: nested residual reuse event record failed: %s\n",
                    cudaGetErrorString(recorded));
            (void)cudaGetLastError();
            (void)cudaStreamSynchronize(g_model_upload_stream);
            state.failures++;
            state.hard_failure = 1;
            return -1;
        }
        slot.copy_pending = 1;
        state.h2d_bytes += gate_expert_bytes * 2u + down_expert_bytes;
    }
    state.router_open_calls++;
    return 1;
}

static int cuda_nested_residual_layer_required(uint32_t layer_index) {
    return g_nested_residual.active &&
        layer_index < CUDA_NESTED_RESIDUAL_LAYER_COUNT &&
        g_nested_residual.layers[layer_index].ready;
}

/* Returns 1 and populates g_moe_gather (compact gate/up/down + remapped slot tensor)
 * on success; 0 on any failure (caller falls back to the whole-256-block path). */
static int cuda_moe_selected_load(
        const void *model_map, uint64_t model_size,
        uint32_t layer_index,
        uint64_t gate_offset, uint64_t up_offset, uint64_t down_offset,
        uint64_t gate_expert_bytes, uint64_t down_expert_bytes,
        uint32_t expert_in_dim,
        uint32_t n_total_expert, uint32_t n_expert, uint32_t n_tokens,
        const ds4_gpu_tensor *selected_arg,
        const ds4_gpu_tensor *weights_arg,
        const ds4_gpu_tensor *probs_arg,
        ds4_gpu_spex_queue *spex_queue,
        const ds4_gpu_spex_key *spex_key,
        int allow_prefill_mixed_route_ptrs) {
    g_moe_last_selected.valid = 0;
    g_moe_gather.direct_cache_active = 0;
    g_moe_gather.mixed_direct_active = 0;
    g_moe_gather.mixed_cache_routes = 0;
    g_moe_gather.mixed_compact_routes = 0;
    g_moe_gather.wave_active = 0;
    g_moe_gather.wave_fail_closed = 0;
    g_moe_gather.wave_count = 0;
    g_moe_gather.wave_index = 0;
    g_moe_gather.wave_max_experts = 0;
    g_moe_gather.wave_current_experts = 0;
    g_moe_gather.wave_active_pairs = 0;
    g_moe_gather.wave_unique_experts = 0;
    g_moe_gather.wave_source_span_bytes = 0;
    g_moe_gather.wave_arena_h2d_bytes = 0;
    g_moe_gather.wave_arena_experts = 0;
    g_moe_gather.wave_direct_experts = 0;
    g_moe_gather.wave_double_buffer = 0;
    for (uint32_t i = 0; i < 2u; i++) {
        g_moe_gather.wave_active_pairs_db[i] = 0;
        g_moe_gather.wave_current_experts_db[i] = 0;
    }
    const int route_prof = getenv("DS4_CUDA_MOE_ROUTE_PROFILE") != NULL;
    const int prefill_union_stats = n_tokens > 1u &&
        getenv("DS4_CUDA_PREFILL_UNION_STATS") != NULL;
    const double route_t0 = route_prof ? cuda_wall_sec() : 0.0;
    double route_t_d2h = route_t0;
    double route_t_observe = route_t0;
    double route_t_map = route_t0;
    double route_t_transport = route_t0;
    (void)model_size;
    if (n_total_expert == 0 || n_expert == 0 || n_tokens == 0) return 0;
    if (!selected_arg || !selected_arg->ptr) return 0;
    if (gate_expert_bytes == 0 || down_expert_bytes == 0) return 0;
    if (n_tokens > UINT32_MAX / n_expert) return 0;
    const uint32_t slot_count = n_tokens * n_expert;
    if (slot_count == 0) return 0;
    if (selected_arg->bytes < (uint64_t)slot_count * sizeof(int32_t)) return 0;
    const int iq1_mixed_host_prepared =
        g_iq1_mixed_host_selected.valid && slot_count == 1u &&
        g_iq1_mixed_host_selected.model_map == model_map &&
        g_iq1_mixed_host_selected.selected_ptr == selected_arg->ptr &&
        g_iq1_mixed_host_selected.gate_offset == gate_offset &&
        g_iq1_mixed_host_selected.up_offset == up_offset &&
        g_iq1_mixed_host_selected.down_offset == down_offset &&
        g_iq1_mixed_host_selected.gate_expert_bytes == gate_expert_bytes &&
        g_iq1_mixed_host_selected.down_expert_bytes == down_expert_bytes;
    const int32_t iq1_mixed_host_expert =
        g_iq1_mixed_host_selected.expert;
    const float iq1_mixed_host_weight =
        g_iq1_mixed_host_selected.weight;
    g_iq1_mixed_host_selected.valid = 0;
    const int prefill_mass_weights =
        cuda_prefill_mass_observer_needs_weights();
    const int compose_requested =
        cuda_moe_prefill_tier_compose_requested();
    const int full_q1_snapshot_requested =
        cuda_q1_0_snapshot_backing_requested();
    if (n_tokens == 1u &&
        (compose_requested > 0 || full_q1_snapshot_requested) &&
        g_prefill_mass_observer.enabled &&
        g_prefill_mass_observer.finalized &&
        !g_prefill_mass_observer.wrap_published) {
        fprintf(stderr,
                "ds4: [prefill-mass-compose] decode refused: closed snapshot publication failed\n");
        return 0;
    }
    const int prefill_mass_full_probs = prefill_mass_weights &&
        n_tokens > 1u &&
        (compose_requested > 0 || full_q1_snapshot_requested);
    const int reap_mass_requested = n_tokens == 1 &&
        cuda_reap_mass_observer_needs_weights() &&
        g_reap_router_trace_valid;
    const int weights_available = weights_arg && weights_arg->ptr &&
        weights_arg->bytes >= (uint64_t)slot_count * sizeof(float);
    const int reap_mass_weights = reap_mass_requested && weights_available;
    if (reap_mass_requested && !weights_available) {
        g_reap_router_trace_valid = 0;
    }
    const int layer_top1 =
        cuda_moe_expert_cache_requested() != 0 && cuda_moe_expert_cache_layer_top1();
    if (layer_top1 &&
        !weights_available) {
        return 0;
    }
    const int packed_reap_trace = reap_mass_weights && weights_available &&
        g_reap_router_trace_device && g_reap_router_trace_host;
    const int copy_weights =
        weights_available &&
        (layer_top1 || prefill_mass_weights ||
         (reap_mass_weights && !packed_reap_trace));
    const int host_weights_available =
        copy_weights || packed_reap_trace || iq1_mixed_host_prepared;
    const uint64_t full_prob_count =
        (uint64_t)n_tokens * n_total_expert;
    if (prefill_mass_full_probs &&
        (!probs_arg || !probs_arg->ptr ||
         probs_arg->bytes < full_prob_count * sizeof(float) ||
         full_prob_count > UINT32_MAX)) {
        fprintf(stderr,
                "ds4: [prefill-mass] full router probabilities unavailable; observer disabled\n");
        cuda_prefill_mass_observer_release(0);
        return 0;
    }

    const int prepared =
        g_moe_selected_prepared.valid &&
        g_moe_selected_prepared.model_map == model_map &&
        g_moe_selected_prepared.selected_ptr == selected_arg->ptr &&
        g_moe_selected_prepared.gate_offset == gate_offset &&
        g_moe_selected_prepared.up_offset == up_offset &&
        g_moe_selected_prepared.down_offset == down_offset &&
        g_moe_selected_prepared.gate_expert_bytes == gate_expert_bytes &&
        g_moe_selected_prepared.down_expert_bytes == down_expert_bytes &&
        g_moe_selected_prepared.n_expert == n_expert &&
        g_moe_selected_prepared.n_tokens == n_tokens;
    g_moe_selected_prepared.valid = 0;
    if (prepared && g_moe_selected_prepared.full) {
        static int full_overlap_notice_printed = 0;
        if (!full_overlap_notice_printed) {
            fprintf(stderr, "ds4: CUDA MoE full shared-overlap consumed\n");
            full_overlap_notice_printed = 1;
        }
    } else if (prepared) {
        static int overlap_notice_printed = 0;
        if (!overlap_notice_printed) {
            fprintf(stderr, "ds4: CUDA MoE shared-overlap consumed\n");
            overlap_notice_printed = 1;
        }
    }

    /* 1. Router outputs -> host. Layer-top1 also consumes the selected weights
     * to choose residency; selection itself remains unchanged. */
    if (iq1_mixed_host_prepared) {
        if (iq1_mixed_host_expert < 0 ||
            (uint32_t)iq1_mixed_host_expert >= n_total_expert) {
            return 0;
        }
        g_moe_gather.h_sel.assign(1u, iq1_mixed_host_expert);
        g_moe_gather.h_weights.assign(1u, iq1_mixed_host_weight);
    } else if (prepared) {
        if (g_moe_gather.h_sel.size() != slot_count) return 0;
        if (packed_reap_trace) {
            g_moe_gather.h_weights.resize(slot_count);
            g_reap_router_trace_valid = 0;
            if (!cuda_ok(cudaMemcpy(
                    g_reap_router_trace_host, g_reap_router_trace_device,
                    sizeof(*g_reap_router_trace_host),
                    cudaMemcpyDeviceToHost), "moe packed router trace D2H")) {
                return 0;
            }
            memcpy(g_moe_gather.h_weights.data(),
                   g_reap_router_trace_host->weights,
                   (size_t)slot_count * sizeof(float));
        } else if (copy_weights) {
            g_moe_gather.h_weights.resize(slot_count);
            if (!cuda_ok(cudaMemcpy(
                    g_moe_gather.h_weights.data(), weights_arg->ptr,
                    (size_t)slot_count * sizeof(float),
                    cudaMemcpyDeviceToHost), "moe weights D2H")) {
                return 0;
            }
        }
    } else if (packed_reap_trace) {
        g_moe_gather.h_sel.resize(slot_count);
        g_moe_gather.h_weights.resize(slot_count);
        g_reap_router_trace_valid = 0;
        if (!cuda_ok(cudaMemcpy(
                g_reap_router_trace_host, g_reap_router_trace_device,
                sizeof(*g_reap_router_trace_host),
                cudaMemcpyDeviceToHost), "moe packed router trace D2H")) {
            return 0;
        }
        memcpy(g_moe_gather.h_sel.data(),
               g_reap_router_trace_host->selected,
               (size_t)slot_count * sizeof(int32_t));
        memcpy(g_moe_gather.h_weights.data(),
               g_reap_router_trace_host->weights,
               (size_t)slot_count * sizeof(float));
    } else if (copy_weights) {
        g_moe_gather.h_sel.resize(slot_count);
        g_moe_gather.h_weights.resize(slot_count);
        if (!cuda_ok(cudaMemcpyAsync(g_moe_gather.h_sel.data(), selected_arg->ptr,
                                     (size_t)slot_count * sizeof(int32_t),
                                     cudaMemcpyDeviceToHost, 0), "moe selected D2H enqueue") ||
            !cuda_ok(cudaMemcpyAsync(g_moe_gather.h_weights.data(), weights_arg->ptr,
                                     (size_t)slot_count * sizeof(float),
                                     cudaMemcpyDeviceToHost, 0), "moe weights D2H enqueue") ||
            !cuda_ok(cudaStreamSynchronize(0), "moe router D2H sync")) return 0;
    } else {
        g_moe_gather.h_sel.resize(slot_count);
        if (!cuda_ok(cudaMemcpy(g_moe_gather.h_sel.data(), selected_arg->ptr,
                                (size_t)slot_count * sizeof(int32_t),
                                cudaMemcpyDeviceToHost), "moe selected D2H")) return 0;
    }
    if (prefill_mass_full_probs) {
        g_moe_gather.h_probs.resize((size_t)full_prob_count);
        if (!cuda_ok(cudaMemcpy(
                g_moe_gather.h_probs.data(), probs_arg->ptr,
                (size_t)full_prob_count * sizeof(float),
                cudaMemcpyDeviceToHost), "moe full router probabilities D2H")) {
            return 0;
        }
    }
    if (!cuda_sparse_bake_validate_selected(
            layer_index, g_moe_gather.h_sel.data(), slot_count,
            "routed selection", 0u)) {
        return 0;
    }
    if (route_prof) route_t_d2h = cuda_wall_sec();

    cuda_prefill_mass_observe_selected(
        layer_index, n_tokens, g_moe_gather.h_sel.data(),
        host_weights_available ? g_moe_gather.h_weights.data() : NULL,
        slot_count,
        prefill_mass_full_probs ? g_moe_gather.h_probs.data() : NULL,
        prefill_mass_full_probs ? (uint32_t)full_prob_count : 0u);
    if (reap_mass_weights) {
        cuda_reap_mass_observe_selected(
            layer_index, n_tokens, g_moe_gather.h_sel.data(),
            g_moe_gather.h_weights.data(), slot_count);
    }

    /* Residency learning consumes the exact selected ids already required by
     * execution. It does not change router scores, top-k, or the active mask. */
    cuda_dynamic_arena_observe_selected(
        layer_index, n_tokens, g_moe_gather.h_sel.data(), slot_count);
    if (route_prof) route_t_observe = cuda_wall_sec();

    /* 2. dedupe -> compact ids (ascending expert order) + per-slot remap */
    std::vector<int32_t> &e2s = g_moe_gather.h_expert_to_slot;
    e2s.assign(n_total_expert, -1);
    std::vector<int32_t> &compact = g_moe_gather.h_compact_ids; compact.clear();
    std::vector<int32_t> &slots = g_moe_gather.h_slot_ids; slots.resize(slot_count);
    for (uint32_t i = 0; i < slot_count; i++) {
        const int32_t e = g_moe_gather.h_sel[i];
        if (e < 0 || (uint32_t)e >= n_total_expert) return 0;
        e2s[(uint32_t)e] = -2;
    }
    for (uint32_t e = 0; e < n_total_expert; e++) {
        if (e2s[e] != -2) continue;
        e2s[e] = (int32_t)compact.size();
        compact.push_back((int32_t)e);
    }
    for (uint32_t i = 0; i < slot_count; i++)
        slots[i] = e2s[(uint32_t)g_moe_gather.h_sel[i]];
    const uint32_t compact_count = (uint32_t)compact.size();
    if (compact_count == 0 || compact_count > n_total_expert) return 0;
    if (route_prof) route_t_map = cuda_wall_sec();

    if (cuda_prefill_waves_requested() && n_tokens > 1u) {
        if (cuda_prefill_wave_debug_dump_active()) {
            g_moe_gather.wave_fail_closed = 1;
            fprintf(stderr,
                    "ds4: [prefill-waves] refused reason=debug-dump-active layer=%u tokens=%u compact=%u\n",
                    layer_index, n_tokens, compact_count);
            return 0;
        }
        const int double_buffer_requested =
            cuda_prefill_wave_double_buffer_requested();
        if (double_buffer_requested < 0) {
            g_moe_gather.wave_fail_closed = 1;
            return 0;
        }
        uint32_t max_wave_experts = cuda_prefill_wave_force_experts();
        if (max_wave_experts == UINT32_MAX) {
            g_moe_gather.wave_fail_closed = 1;
            return 0;
        }
        if (max_wave_experts == 0) {
            const uint32_t budget_experts =
                cuda_prefill_wave_budget_experts(gate_expert_bytes,
                                                 down_expert_bytes,
                                                 double_buffer_requested > 0);
            if (budget_experts != 0 && compact_count > budget_experts) {
                max_wave_experts = budget_experts;
            }
        }
        if (max_wave_experts != 0 && max_wave_experts < compact_count) {
            g_moe_gather.wave_active = 1;
            g_moe_gather.wave_fail_closed = 1;
            g_moe_gather.wave_double_buffer =
                double_buffer_requested > 0 ? 1u : 0u;
            g_moe_gather.wave_max_experts = max_wave_experts;
            g_moe_gather.wave_count =
                (compact_count + max_wave_experts - 1u) / max_wave_experts;
            g_moe_gather.wave_unique_experts = compact_count;
            if (!cuda_moe_selected_stage_wave(
                    model_map, layer_index,
                    gate_offset, up_offset, down_offset,
                    gate_expert_bytes, down_expert_bytes,
                    n_total_expert, n_expert, n_tokens, 0u)) {
                if (g_moe_gather.wave_double_buffer) {
                    g_prefill_wave_overlap_stats.failures =
                        cuda_u64_saturating_add(
                            g_prefill_wave_overlap_stats.failures, 1);
                }
                return 0;
            }
            g_prefill_wave_stats.activations = cuda_u64_saturating_add(
                g_prefill_wave_stats.activations, 1);
            g_prefill_wave_stats.unique_experts = cuda_u64_saturating_add(
                g_prefill_wave_stats.unique_experts, compact_count);
            if (max_wave_experts > g_prefill_wave_stats.max_wave) {
                g_prefill_wave_stats.max_wave = max_wave_experts;
            }
            if (g_moe_gather.wave_double_buffer) {
                g_prefill_wave_overlap_stats.activations =
                    cuda_u64_saturating_add(
                        g_prefill_wave_overlap_stats.activations, 1);
            }
            if (route_prof) {
                route_t_transport = cuda_wall_sec();
                const double route_t_publish = cuda_wall_sec();
                g_route_prof_calls++;
                g_route_prof_d2h_s += route_t_d2h - route_t0;
                g_route_prof_observe_s += route_t_observe - route_t_d2h;
                g_route_prof_map_s += route_t_map - route_t_observe;
                g_route_prof_transport_s += route_t_transport - route_t_map;
                g_route_prof_publish_s += route_t_publish - route_t_transport;
            }
            return 1;
        }
    }

    /* 3. compact device buffers (grow-only, reused across layers/tokens) */
    const uint64_t cgate = (uint64_t)compact_count * gate_expert_bytes;
    const uint64_t cdown = (uint64_t)compact_count * down_expert_bytes;
    const int slot_will_grow = !g_moe_gather.slot ||
        g_moe_gather.slot_cap < (uint64_t)slot_count * sizeof(int32_t);
    const int iq1_sidecar_route = g_iq1_s_sidecar_file_valid &&
        model_map == g_iq1_s_sidecar_host_base;
    const int iq1_vram_cache_state = iq1_sidecar_route ?
        cuda_iq1_s_vram_cache_prepare(
            gate_expert_bytes, down_expert_bytes) : 0;
    if (iq1_vram_cache_state < 0 ||
        (iq1_vram_cache_state > 0 && compact_count != 1u)) {
        return 0;
    }
    const int iq1_vram_cache_active = iq1_vram_cache_state > 0;
    const int iq1_packed_h2d = !iq1_vram_cache_active &&
        compact_count == 1u && iq1_sidecar_route &&
        getenv("DS4_IQ1_S_PACKED_H2D") != NULL;
    const uint64_t iq1_packed_bytes = cgate * 2ull + cdown;
    if ((!iq1_vram_cache_active && iq1_packed_h2d &&
         !cuda_moe_gather_ensure(&g_moe_gather.iq1_packed,
                                 &g_moe_gather.iq1_packed_cap,
                                 iq1_packed_bytes,
                                 "moe IQ1_S packed gather")) ||
        (!iq1_vram_cache_active && !iq1_packed_h2d &&
         (!cuda_moe_gather_ensure(&g_moe_gather.gate, &g_moe_gather.gate_cap, cgate, "moe gather gate") ||
          !cuda_moe_gather_ensure(&g_moe_gather.up,   &g_moe_gather.up_cap,   cgate, "moe gather up") ||
          !cuda_moe_gather_ensure(&g_moe_gather.down, &g_moe_gather.down_cap, cdown, "moe gather down"))) ||
        !cuda_moe_gather_ensure_i32(&g_moe_gather.slot, &g_moe_gather.slot_cap, slot_count, "moe gather slots"))
        return 0;
    if (slot_will_grow) g_moe_gather.iq1_slot_zero_valid = 0;
    g_moe_gather.iq1_active_gate = NULL;
    g_moe_gather.iq1_active_up = NULL;
    g_moe_gather.iq1_active_down = NULL;

    /* Dynamic-arena hits go straight from their stable pinned slot to the
     * compact execution buffers. They never enter the legacy pread/staging
     * list and never take a detour through the persistent VRAM cache. */
    std::vector<uint8_t> &arena_resident = g_moe_gather.h_arena_resident;
    arena_resident.assign(compact_count, 0);
    const int nested_exact = cuda_nested_residual_upload_exact(
        layer_index,
        gate_offset, up_offset, down_offset,
        gate_expert_bytes, down_expert_bytes,
        compact);
    if (nested_exact < 0) {
        g_moe_gather.wave_fail_closed = 1;
        return 0;
    }
    if (nested_exact > 0) {
        std::fill(arena_resident.begin(), arena_resident.end(), 1u);
    }
    const int arena_active = nested_exact == 0 && g_dynamic_arena.host_base &&
        g_dynamic_arena.snapshot_generation != 0 &&
        !g_dynamic_arena.hits_disabled &&
        !g_dynamic_arena.submissions_blocked;
    if (arena_active) {
        for (uint32_t i = 0; i < compact_count; i++) {
            const uint32_t expert = (uint32_t)compact[i];
            const uint64_t gate_dst = (uint64_t)i * gate_expert_bytes;
            const uint64_t down_dst = (uint64_t)i * down_expert_bytes;
            const cuda_dynamic_arena_copy_status arena_status =
                cuda_dynamic_arena_copy_expert_async(
                    g_dynamic_arena,
                    model_map, layer_index, expert,
                    gate_offset, up_offset, down_offset,
                    g_moe_gather.gate + gate_dst,
                    g_moe_gather.up + gate_dst,
                    g_moe_gather.down + down_dst,
                    gate_expert_bytes, gate_expert_bytes,
                    down_expert_bytes);
            if (arena_status == CUDA_DYNAMIC_ARENA_FATAL) {
                (void)cudaStreamSynchronize(g_model_upload_stream);
                return 0;
            }
            arena_resident[i] =
                arena_status == CUDA_DYNAMIC_ARENA_ENQUEUED ? 1u : 0u;
        }
    }

    std::vector<uint8_t> &iq1_ram_resident =
        g_moe_gather.h_iq1_ram_resident;
    iq1_ram_resident.assign(compact_count, 0);
    const int iq1_profile = getenv("DS4_IQ1_S_PROFILE") != NULL;
    const double iq1_enqueue_t0 = iq1_profile ? cuda_wall_sec() : 0.0;
    uint32_t iq1_upload_experts = 0;
    int iq1_vram_pending_slot = -1;
    int iq1_vram_pending_new = 0;
    if (iq1_sidecar_route) {
        for (uint32_t i = 0; i < compact_count; i++) {
            const uint32_t expert = (uint32_t)compact[i];
            char *iq1_vram_base = NULL;
            if (iq1_vram_cache_active) {
                int vram_hit = 0;
                int vram_evicted = 0;
                const int vram_slot = cuda_iq1_s_vram_cache_resolve_slot(
                    layer_index, expert, &vram_hit, &vram_evicted);
                if (vram_slot < 0) return 0;
                iq1_vram_base = cuda_iq1_s_vram_cache_slot_base(
                    (uint32_t)vram_slot);
                if (!iq1_vram_base) return 0;
                g_moe_gather.iq1_active_gate = iq1_vram_base;
                g_moe_gather.iq1_active_up =
                    iq1_vram_base + gate_expert_bytes;
                g_moe_gather.iq1_active_down =
                    iq1_vram_base + gate_expert_bytes * 2ull;
                iq1_ram_resident[i] = 1u;
                if (vram_hit) continue;
                iq1_vram_pending_slot = vram_slot;
                iq1_vram_pending_new = !vram_evicted;
            }
            const uint64_t gate_src = gate_offset +
                (uint64_t)expert * gate_expert_bytes;
            const uint64_t up_src = up_offset +
                (uint64_t)expert * gate_expert_bytes;
            const uint64_t down_src = down_offset +
                (uint64_t)expert * down_expert_bytes;
            const char *gate_host = NULL;
            const char *up_host = NULL;
            const char *down_host = NULL;
            const int resolved = cuda_iq1_s_ram_cache_resolve(
                layer_index, expert, gate_src, up_src, down_src,
                gate_expert_bytes, down_expert_bytes,
                &gate_host, &up_host, &down_host);
            if (resolved < 0) return 0;
            if (resolved == 0) {
                if (iq1_vram_cache_active) {
                    g_iq1_s_vram_cache.failures++;
                    return 0;
                }
                break;
            }
            const uint64_t gate_dst = (uint64_t)i * gate_expert_bytes;
            const uint64_t down_dst = (uint64_t)i * down_expert_bytes;
            const int single_copy_h2d = iq1_vram_cache_active ||
                iq1_packed_h2d;
            if (single_copy_h2d &&
                (up_host != gate_host + gate_expert_bytes ||
                 down_host != gate_host + gate_expert_bytes * 2ull)) {
                g_iq1_s_ram_cache.failures++;
                return 0;
            }
            char *single_copy_destination = iq1_vram_cache_active ?
                iq1_vram_base : g_moe_gather.iq1_packed;
            const int copy_ok = single_copy_h2d ?
                cudaMemcpyAsync(
                    single_copy_destination, gate_host,
                    (size_t)iq1_packed_bytes, cudaMemcpyHostToDevice,
                    g_model_upload_stream) == cudaSuccess :
                (cudaMemcpyAsync(
                     g_moe_gather.gate + gate_dst, gate_host,
                     (size_t)gate_expert_bytes, cudaMemcpyHostToDevice,
                     g_model_upload_stream) == cudaSuccess &&
                 cudaMemcpyAsync(
                     g_moe_gather.up + gate_dst, up_host,
                     (size_t)gate_expert_bytes, cudaMemcpyHostToDevice,
                     g_model_upload_stream) == cudaSuccess &&
                 cudaMemcpyAsync(
                     g_moe_gather.down + down_dst, down_host,
                     (size_t)down_expert_bytes, cudaMemcpyHostToDevice,
                     g_model_upload_stream) == cudaSuccess);
            if (!copy_ok) {
                (void)cudaGetLastError();
                g_iq1_s_ram_cache.failures++;
                if (iq1_vram_cache_active)
                    g_iq1_s_vram_cache.failures++;
                return 0;
            }
            g_iq1_s_ram_cache.h2d_copies += single_copy_h2d ? 1u : 3u;
            iq1_ram_resident[i] = 1u;
            iq1_upload_experts++;
            g_iq1_s_ram_cache.h2d_bytes +=
                gate_expert_bytes * 2ull + down_expert_bytes;
            if (iq1_vram_cache_active) {
                g_iq1_s_vram_cache.h2d_bytes +=
                    gate_expert_bytes * 2ull + down_expert_bytes;
            } else if (iq1_packed_h2d) {
                g_moe_gather.iq1_active_gate = g_moe_gather.iq1_packed;
                g_moe_gather.iq1_active_up =
                    g_moe_gather.iq1_packed + gate_expert_bytes;
                g_moe_gather.iq1_active_down =
                    g_moe_gather.iq1_packed + gate_expert_bytes * 2ull;
            }
        }
    }
    if (iq1_profile && iq1_upload_experts != 0) {
        g_iq1_s_ram_cache.h2d_batches++;
        g_iq1_s_ram_cache.h2d_enqueue_seconds +=
            cuda_wall_sec() - iq1_enqueue_t0;
    }

    int spex_prefetch_slot = -1;
    uint32_t spex_prediction_slot = 0;
    uint32_t spex_compact_slot = UINT32_MAX;
    if (spex_queue && spex_key && cuda_moe_expert_cache_requested() == 0) {
        (void)cuda_spex_prefetch_claim(
            spex_queue, spex_key,
            gate_offset, up_offset, down_offset,
            compact,
            &spex_prefetch_slot,
            &spex_prediction_slot,
            &spex_compact_slot);
        if (spex_prefetch_slot >= 0 &&
            spex_compact_slot < arena_resident.size() &&
            arena_resident[spex_compact_slot]) {
            cuda_spex_prefetch_release(
                spex_queue, spex_prefetch_slot, 1, 0);
            spex_prefetch_slot = -1;
            spex_compact_slot = UINT32_MAX;
        }
    }

    /* 4. Resolve exact-byte resident hits, admit misses into persistent VRAM
     * slots when enabled, and stream overflow misses directly into compact
     * buffers. Cache policy changes residency only; router selection and the
     * compact slot map are unchanged. */
    const int prof = getenv("DS4_CUDA_SEL_PROFILE") != NULL;
    const double t_fetch0 = prof ? cuda_wall_sec() : 0.0;
    cuda_moe_expert_cache *cache = allow_prefill_mixed_route_ptrs ? NULL :
        cuda_moe_expert_cache_prepare(gate_expert_bytes, down_expert_bytes);
    /* P3 owns persistent residency. The generic selected-load path still
     * serves prefill exactly through compact buffers, but must not smuggle a
     * first-touch expert straight into the persistent VRAM cache. Decode uses
     * the fail-closed GPU route worker below. */
    if (cuda_moe_tiering_mode_requested() == CUDA_MOE_TIER_ENFORCE) {
        cache = NULL;
    }
    std::vector<cuda_moe_gather::span> &spans = g_moe_gather.h_spans;
    std::vector<int32_t> &cache_slots = g_moe_gather.h_cache_slots;
    std::vector<uint8_t> &claimed = g_moe_gather.h_cache_claimed;
    std::vector<uint32_t> &admission_compact = g_moe_gather.h_cache_admission_compact;
    std::vector<uint32_t> &admission_slots = g_moe_gather.h_cache_admission_slots;
    std::vector<uint8_t> &admission_evicted = g_moe_gather.h_cache_admission_evicted;
    spans.clear();
    spans.reserve((size_t)compact_count * 3u);
    cache_slots.assign(compact_count, -1);
    claimed.assign(cache ? cache->capacity : 0u, 0u);
    admission_compact.clear();
    admission_slots.clear();
    admission_evicted.clear();
    admission_compact.reserve(compact_count);
    admission_slots.reserve(compact_count);
    admission_evicted.reserve(compact_count);

    uint64_t local_hits = 0;
    uint64_t local_misses = 0;
    uint64_t local_evictions = 0;
    uint64_t local_direct = 0;
    int cache_map_dirty = 0;

    auto expert_key = [&](uint32_t compact_slot) {
        const uint64_t e = (uint64_t)(uint32_t)compact[compact_slot];
        return cuda_moe_cache_key{
            gate_offset + e * gate_expert_bytes,
            up_offset + e * gate_expert_bytes,
            down_offset + e * down_expert_bytes,
        };
    };
    auto append_span = [&](char *destination,
                           uint64_t source,
                           uint64_t bytes,
                           uint32_t expert,
                           uint8_t part) {
        uint32_t arena_entry = UINT32_MAX;
        char *mirror = cuda_dynamic_arena_observer_mirror_ptr(
            model_map, layer_index, expert, part, source, bytes,
            &arena_entry);
        spans.push_back({
            destination, source, bytes, mirror, arena_entry, part
        });
    };
    auto append_direct = [&](uint32_t compact_slot, const cuda_moe_cache_key &key) {
        const uint32_t expert = (uint32_t)compact[compact_slot];
        append_span(
            g_moe_gather.gate + (uint64_t)compact_slot * gate_expert_bytes,
            key.gate_src, gate_expert_bytes, expert,
            CUDA_DYNAMIC_ARENA_MIRROR_GATE);
        append_span(
            g_moe_gather.up + (uint64_t)compact_slot * gate_expert_bytes,
            key.up_src, gate_expert_bytes, expert,
            CUDA_DYNAMIC_ARENA_MIRROR_UP);
        append_span(
            g_moe_gather.down + (uint64_t)compact_slot * down_expert_bytes,
            key.down_src, down_expert_bytes, expert,
            CUDA_DYNAMIC_ARENA_MIRROR_DOWN);
        local_direct++;
    };
    auto append_admission = [&](uint32_t compact_slot, uint32_t cache_slot,
                                 const cuda_moe_cache_key &key) {
        cuda_moe_cache_slot &entry = cache->slots[cache_slot];
        const uint8_t evicted = entry.state == CUDA_MOE_CACHE_VALID ? 1u : 0u;
        if (evicted && entry.layer_index < CUDA_MOE_LAYER_COUNT &&
            entry.expert_id < 256u &&
            !cache->host_slot_by_layer_expert.empty()) {
            const uint32_t old_index = entry.layer_index * 256u + entry.expert_id;
            if (cache->host_slot_by_layer_expert[old_index] == (int32_t)cache_slot) {
                cache->host_slot_by_layer_expert[old_index] = -1;
            }
        }
        entry.state = CUDA_MOE_CACHE_LOADING;
        entry.key = key;
        entry.age = 0;
        entry.layer_index = layer_index;
        entry.expert_id = (uint32_t)compact[compact_slot];
        claimed[cache_slot] = 1;
        cache_slots[compact_slot] = (int32_t)cache_slot;
        admission_compact.push_back(compact_slot);
        admission_slots.push_back(cache_slot);
        admission_evicted.push_back(evicted);
        local_evictions += evicted;
        if (!cache->host_slot_by_layer_expert.empty()) {
            cache->host_slot_by_layer_expert[
                layer_index * 256u + entry.expert_id] = (int32_t)cache_slot;
            cache_map_dirty = 1;
        }
        const uint64_t gate_dst = (uint64_t)cache_slot * gate_expert_bytes;
        const uint64_t down_dst = (uint64_t)cache_slot * down_expert_bytes;
        const uint32_t expert = (uint32_t)compact[compact_slot];
        append_span(cache->gate + gate_dst, key.gate_src,
                    gate_expert_bytes, expert,
                    CUDA_DYNAMIC_ARENA_MIRROR_GATE);
        append_span(cache->up + gate_dst, key.up_src,
                    gate_expert_bytes, expert,
                    CUDA_DYNAMIC_ARENA_MIRROR_UP);
        append_span(cache->down + down_dst, key.down_src,
                    down_expert_bytes, expert,
                    CUDA_DYNAMIC_ARENA_MIRROR_DOWN);
    };
    if (cache && layer_top1) {
        int layer_slot = -1;
        for (uint32_t i = 0; i < cache->capacity; i++) {
            if (cache->slots[i].layer_owned && cache->slots[i].layer_key == gate_offset) {
                layer_slot = (int)i;
                break;
            }
        }
        if (layer_slot < 0) {
            for (uint32_t i = 0; i < cache->capacity; i++) {
                if (cache->slots[i].layer_owned) continue;
                cache->slots[i].layer_owned = 1;
                cache->slots[i].layer_key = gate_offset;
                layer_slot = (int)i;
                break;
            }
        }

        if (layer_slot >= 0 && cache->slots[(uint32_t)layer_slot].state == CUDA_MOE_CACHE_VALID) {
            const cuda_moe_cache_key resident = cache->slots[(uint32_t)layer_slot].key;
            for (uint32_t i = 0; i < compact_count; i++) {
                if (arena_resident[i] || iq1_ram_resident[i]) continue;
                const cuda_moe_cache_key key = expert_key(i);
                if (key.gate_src == resident.gate_src &&
                    key.up_src == resident.up_src &&
                    key.down_src == resident.down_src) {
                    cache_slots[i] = layer_slot;
                    claimed[(uint32_t)layer_slot] = 1;
                    local_hits = 1;
                    break;
                }
            }
        }
        uint32_t cache_eligible = 0;
        for (uint32_t i = 0; i < compact_count; i++) {
            cache_eligible +=
                arena_resident[i] == 0 && iq1_ram_resident[i] == 0;
        }
        local_misses = cache_eligible - local_hits;

        if (layer_slot >= 0 && local_hits == 0) {
            std::vector<float> &mass = g_moe_gather.h_compact_mass;
            mass.assign(compact_count, 0.0f);
            for (uint32_t i = 0; i < slot_count; i++) {
                mass[(uint32_t)slots[i]] += g_moe_gather.h_weights[i];
            }
            uint32_t candidate = UINT32_MAX;
            for (uint32_t i = 0; i < compact_count; i++) {
                if (arena_resident[i] || iq1_ram_resident[i]) continue;
                if (candidate == UINT32_MAX || mass[i] > mass[candidate]) {
                    candidate = i;
                }
            }
            if (candidate != UINT32_MAX) {
                append_admission(candidate, (uint32_t)layer_slot,
                                 expert_key(candidate));
            }
        }
        for (uint32_t i = 0; i < compact_count; i++) {
            if (!arena_resident[i] && !iq1_ram_resident[i] &&
                cache_slots[i] < 0 &&
                i != spex_compact_slot) {
                append_direct(i, expert_key(i));
            }
        }
    } else {
        if (cache) {
            for (uint32_t i = 0; i < compact_count; i++) {
                if (arena_resident[i] || iq1_ram_resident[i]) continue;
                const cuda_moe_cache_key key = expert_key(i);
                const int slot = cuda_moe_expert_cache_find(cache, key);
                if (slot >= 0 && !claimed[(uint32_t)slot]) {
                    cache_slots[i] = slot;
                    claimed[(uint32_t)slot] = 1;
                    local_hits++;
                } else {
                    local_misses++;
                }
            }
        }

        for (uint32_t i = 0; i < compact_count; i++) {
            if (arena_resident[i] || iq1_ram_resident[i]) continue;
            if (cache_slots[i] >= 0) continue;
            if (i == spex_compact_slot) continue;
            const cuda_moe_cache_key key = expert_key(i);
            const int cache_slot = cache ? cuda_moe_expert_cache_lru_slot(cache, claimed) : -1;
            if (cache_slot >= 0) {
                append_admission(i, (uint32_t)cache_slot, key);
            } else {
                append_direct(i, key);
            }
        }
    }
    int fill_ok = 0;
    if (spex_prefetch_slot >= 0) {
        const uint64_t gate_dst = (uint64_t)spex_compact_slot * gate_expert_bytes;
        const uint64_t down_dst = (uint64_t)spex_compact_slot * down_expert_bytes;
        if (!cuda_spex_prefetch_copy_to_compact(
                spex_queue,
                (uint32_t)spex_prefetch_slot,
                spex_prediction_slot,
                g_moe_gather.gate + gate_dst,
                g_moe_gather.up + gate_dst,
                g_moe_gather.down + down_dst)) {
            (void)cudaGetLastError();
            const int fenced = cudaStreamSynchronize(g_model_upload_stream) == cudaSuccess;
            cuda_spex_prefetch_release(spex_queue, spex_prefetch_slot, fenced, 0);
            if (cache) cuda_moe_expert_cache_invalidate();
            return 0;
        }
    }
#ifdef _WIN32
    const uint32_t io_qd = cuda_moe_io_queue_depth();
    if (io_qd > 1u) {
        fill_ok = cuda_moe_fill_spans_overlapped(model_map, spans, io_qd);
        if (!fill_ok) {
            fprintf(stderr, "ds4: CUDA MoE overlapped read failed; selected-load fallback requested\n");
        }
    }
    else
#endif
    {
        fill_ok = 1;
        for (const cuda_moe_gather::span &s : spans) {
            if (!cuda_moe_fill_span(
                    s.dst, model_map, s.offset, s.bytes, s.mirror)) {
                fill_ok = 0;
                break;
            }
            if (s.mirror) {
                cuda_dynamic_arena_observer_mirror_done(
                    s.arena_entry, s.arena_part, s.bytes);
            }
        }
    }
    if (!fill_ok) {
        const int fenced = cudaStreamSynchronize(g_model_upload_stream) == cudaSuccess;
        cuda_spex_prefetch_release(spex_queue, spex_prefetch_slot, fenced, 0);
        if (cache) cuda_moe_expert_cache_invalidate();
        return 0;
    }

    const int mixed_direct_active =
        getenv("DS4_CUDA_MOE_MIXED_DIRECT") != NULL &&
        (n_tokens == 1u || allow_prefill_mixed_route_ptrs) &&
        n_expert == 6u && cache &&
        expert_in_dim / CUDA_QK_K <= 16u &&
        spex_prefetch_slot < 0 &&
        getenv("DS4_CUDA_MOE_NO_DECODE_LUT_GATE") == NULL &&
        getenv("DS4_CUDA_MOE_NO_DIRECT_DOWN_SUM6") == NULL;
    int direct_cache_active = 0;
    if (!mixed_direct_active &&
        getenv("DS4_CUDA_MOE_DIRECT_CACHE_HITS") != NULL &&
        n_tokens == 1u && cache && spex_prefetch_slot < 0 &&
        admission_slots.empty() && spans.empty()) {
        direct_cache_active = 1;
        for (uint32_t i = 0; i < compact_count; i++) {
            if (arena_resident[i] || iq1_ram_resident[i] ||
                cache_slots[i] < 0) {
                direct_cache_active = 0;
                break;
            }
        }
    }

    if (cache && !direct_cache_active && !mixed_direct_active) {
        for (uint32_t i = 0; i < compact_count; i++) {
            if (cache_slots[i] < 0) continue;
            if (!cuda_moe_expert_cache_copy_to_compact_async(
                    cache, (uint32_t)cache_slots[i], i)) {
                (void)cudaGetLastError();
                const int fenced = cudaStreamSynchronize(g_model_upload_stream) == cudaSuccess;
                cuda_spex_prefetch_release(spex_queue, spex_prefetch_slot, fenced, 0);
                if (cache) cuda_moe_expert_cache_invalidate();
                return 0;
            }
        }
    }

    int arena_upload_pending = 0;
    for (uint32_t i = 0; i < compact_count; i++) {
        if (arena_resident[i]) {
            arena_upload_pending = 1;
            break;
        }
    }
    arena_upload_pending |= iq1_upload_experts != 0;
    const int iq1_vram_all_hit = iq1_vram_cache_active &&
        iq1_upload_experts == 0 && g_moe_gather.iq1_active_gate != NULL;
    const int upload_sync_required =
        !iq1_vram_all_hit && !direct_cache_active &&
        (!mixed_direct_active || !spans.empty() ||
         spex_prefetch_slot >= 0 || arena_upload_pending);
    const double iq1_sync_t0 =
        iq1_profile && iq1_upload_experts != 0 ? cuda_wall_sec() : 0.0;
    if (upload_sync_required &&
        !cuda_ok(cudaStreamSynchronize(g_model_upload_stream), "moe compact upload sync")) {
        if (iq1_vram_pending_slot >= 0)
            g_iq1_s_vram_cache.failures++;
        cuda_spex_prefetch_release(spex_queue, spex_prefetch_slot, 0, 0);
        if (cache) cuda_moe_expert_cache_invalidate();
        return 0;
    }
    if (iq1_profile && iq1_upload_experts != 0 && upload_sync_required) {
        g_iq1_s_ram_cache.h2d_syncs++;
            g_iq1_s_ram_cache.h2d_sync_seconds += cuda_wall_sec() - iq1_sync_t0;
    }
    if (iq1_vram_pending_slot >= 0) {
        cuda_iq1_s_vram_cache_slot &slot =
            g_iq1_s_vram_cache.slots[(uint32_t)iq1_vram_pending_slot];
        slot.valid = 1;
        if (iq1_vram_pending_new &&
            g_iq1_s_vram_cache.count < g_iq1_s_vram_cache.capacity) {
            g_iq1_s_vram_cache.count++;
        }
    }
    if (prefill_union_stats) {
        uint64_t arena_experts = 0;
        uint64_t cache_copies = 0;
        uint64_t iq1_ram_experts = 0;
        uint64_t source_span_bytes = 0;
        uint64_t expert_bytes = UINT64_MAX;
        for (uint8_t resident : arena_resident) arena_experts += resident != 0;
        for (uint8_t resident : iq1_ram_resident) {
            iq1_ram_experts += resident != 0;
        }
        for (int32_t cache_slot : cache_slots) cache_copies += cache_slot >= 0;
        for (const cuda_moe_gather::span &span : spans) {
            source_span_bytes = cuda_u64_saturating_add(source_span_bytes, span.bytes);
        }
        if (gate_expert_bytes <= (UINT64_MAX - down_expert_bytes) / 2ull) {
            expert_bytes = gate_expert_bytes * 2ull + down_expert_bytes;
        }
        g_prefill_union_stats.calls =
            cuda_u64_saturating_add(g_prefill_union_stats.calls, 1);
        g_prefill_union_stats.tokens =
            cuda_u64_saturating_add(g_prefill_union_stats.tokens, n_tokens);
        g_prefill_union_stats.selected_slots =
            cuda_u64_saturating_add(g_prefill_union_stats.selected_slots, slot_count);
        g_prefill_union_stats.unique_experts =
            cuda_u64_saturating_add(g_prefill_union_stats.unique_experts, compact_count);
        g_prefill_union_stats.arena_experts =
            cuda_u64_saturating_add(g_prefill_union_stats.arena_experts, arena_experts);
        g_prefill_union_stats.cache_hit_experts =
            cuda_u64_saturating_add(g_prefill_union_stats.cache_hit_experts, local_hits);
        g_prefill_union_stats.cache_admitted_experts = cuda_u64_saturating_add(
            g_prefill_union_stats.cache_admitted_experts, admission_slots.size());
        g_prefill_union_stats.direct_experts =
            cuda_u64_saturating_add(g_prefill_union_stats.direct_experts, local_direct);
        g_prefill_union_stats.spex_experts = cuda_u64_saturating_add(
            g_prefill_union_stats.spex_experts, spex_prefetch_slot >= 0);
        g_prefill_union_stats.nonresident_experts = cuda_u64_saturating_add(
            g_prefill_union_stats.nonresident_experts,
            compact_count - arena_experts - iq1_ram_experts - local_hits);
        g_prefill_union_stats.source_span_bytes = cuda_u64_saturating_add(
            g_prefill_union_stats.source_span_bytes, source_span_bytes);
        g_prefill_union_stats.arena_h2d_bytes = cuda_u64_saturating_add(
            g_prefill_union_stats.arena_h2d_bytes,
            cuda_u64_saturating_mul(arena_experts, expert_bytes));
        g_prefill_union_stats.cache_d2d_bytes = cuda_u64_saturating_add(
            g_prefill_union_stats.cache_d2d_bytes,
            cuda_u64_saturating_mul(cache_copies, expert_bytes));
        g_prefill_union_stats.upload_syncs = cuda_u64_saturating_add(
            g_prefill_union_stats.upload_syncs, upload_sync_required != 0);
        if (n_tokens > g_prefill_union_stats.max_tokens) {
            g_prefill_union_stats.max_tokens = n_tokens;
        }
        if (compact_count > g_prefill_union_stats.max_union) {
            g_prefill_union_stats.max_union = compact_count;
        }
    }
    if (cache) {
        for (size_t i = 0; i < admission_slots.size(); i++) {
            cuda_moe_cache_slot &entry = cache->slots[admission_slots[i]];
            entry.state = CUDA_MOE_CACHE_VALID;
            if (!admission_evicted[i] && cache->count < cache->capacity) cache->count++;
        }
        for (int32_t slot : cache_slots) {
            if (slot >= 0) cache->slots[(uint32_t)slot].age = ++cache->tick;
        }
        if (cache_map_dirty && cache->device_slot_by_layer_expert &&
            cudaMemcpyAsync(cache->device_slot_by_layer_expert,
                            cache->host_slot_by_layer_expert.data(),
                            cache->host_slot_by_layer_expert.size() * sizeof(int32_t),
                            cudaMemcpyHostToDevice, 0) != cudaSuccess) {
            (void)cudaGetLastError();
            cuda_moe_expert_cache_invalidate();
            return 0;
        }
        cache->calls++;
        cache->hits += local_hits;
        cache->misses += local_misses;
        cache->admissions += admission_slots.size();
        cache->evictions += local_evictions;
        cache->direct_loads += local_direct;
        const uint64_t stats_interval = cuda_moe_expert_cache_stats_interval();
        if (stats_interval != 0 && cache->calls % stats_interval == 0u) {
            const uint64_t lookups = cache->hits + cache->misses;
            fprintf(stderr,
                    "ds4: [moecache] calls=%llu layer=%u compact=%u cap=%u count=%u hits=%llu misses=%llu hit_rate=%.3f admissions=%llu evictions=%llu direct=%llu\n",
                    (unsigned long long)cache->calls, layer_index, compact_count,
                    cache->capacity, cache->count,
                    (unsigned long long)cache->hits, (unsigned long long)cache->misses,
                    lookups ? (double)cache->hits / (double)lookups : 0.0,
                    (unsigned long long)cache->admissions,
                    (unsigned long long)cache->evictions,
                    (unsigned long long)cache->direct_loads);
        }
    }
    if (prof) {
        g_sel_prof_calls++;
        g_sel_prof_experts += compact_count;
        g_sel_prof_fetch_s += cuda_wall_sec() - t_fetch0;
        if (g_sel_prof_calls % 60u == 0u) {
            fprintf(stderr, "ds4: [selprof] calls=%llu experts=%llu fill=%.3fs (%.2f ms/expert)\n",
                    (unsigned long long)g_sel_prof_calls, (unsigned long long)g_sel_prof_experts,
                    g_sel_prof_fetch_s,
                    g_sel_prof_experts ? 1000.0 * g_sel_prof_fetch_s / (double)g_sel_prof_experts : 0.0);
        }
    }

    /* 5. Publish either compact slots or stable resident-cache slots. Pure
     * hits read the persistent quantized bytes in place. Any miss retains the
     * existing compact-buffer path and its synchronization. */
    if (direct_cache_active) {
        for (uint32_t i = 0; i < slot_count; i++) {
            const uint32_t compact_slot = (uint32_t)slots[i];
            slots[i] = cache_slots[compact_slot];
        }
        g_moe_gather.direct_cache_active = 1;
        if (getenv("DS4_CUDA_MOE_DIRECT_CACHE_STATS") != NULL) {
            fprintf(stderr,
                    "ds4: CUDA MoE direct resident-cache hit layer=%u slots=%u compact=%u\n",
                    layer_index, slot_count, compact_count);
        }
    }
    if (route_prof) route_t_transport = cuda_wall_sec();
    if (mixed_direct_active) {
        const uint64_t route_ptr_count = (uint64_t)slot_count * 3ull;
        const uint64_t route_ptr_bytes = route_ptr_count * sizeof(uint64_t);
        if (!cuda_moe_gather_ensure(
                (char **)&g_moe_gather.route_ptrs,
                &g_moe_gather.route_ptrs_cap,
                route_ptr_bytes,
                "moe mixed route pointers")) {
            cuda_spex_prefetch_release(spex_queue, spex_prefetch_slot, 1, 0);
            return 0;
        }
        std::vector<uint64_t> &route_ptrs = g_moe_gather.h_route_ptrs;
        route_ptrs.resize((size_t)route_ptr_count);
        uint32_t cache_routes = 0;
        uint32_t compact_routes = 0;
        for (uint32_t i = 0; i < slot_count; i++) {
            const uint32_t compact_slot = (uint32_t)slots[i];
            const int32_t cache_slot = cache_slots[compact_slot];
            if (cache_slot >= 0) {
                const uint64_t gate_off = (uint64_t)(uint32_t)cache_slot * gate_expert_bytes;
                const uint64_t down_off = (uint64_t)(uint32_t)cache_slot * down_expert_bytes;
                route_ptrs[i] = (uint64_t)(uintptr_t)(cache->gate + gate_off);
                route_ptrs[slot_count + i] = (uint64_t)(uintptr_t)(cache->up + gate_off);
                route_ptrs[2u * slot_count + i] = (uint64_t)(uintptr_t)(cache->down + down_off);
                cache_routes++;
            } else {
                const uint64_t gate_off = (uint64_t)compact_slot * gate_expert_bytes;
                const uint64_t down_off = (uint64_t)compact_slot * down_expert_bytes;
                route_ptrs[i] = (uint64_t)(uintptr_t)(g_moe_gather.gate + gate_off);
                route_ptrs[slot_count + i] = (uint64_t)(uintptr_t)(g_moe_gather.up + gate_off);
                route_ptrs[2u * slot_count + i] = (uint64_t)(uintptr_t)(g_moe_gather.down + down_off);
                compact_routes++;
            }
        }
        if (!cuda_ok(cudaMemcpy(
                g_moe_gather.route_ptrs, route_ptrs.data(),
                (size_t)route_ptr_bytes, cudaMemcpyHostToDevice),
                "moe mixed route pointers")) {
            cuda_spex_prefetch_release(spex_queue, spex_prefetch_slot, 1, 0);
            return 0;
        }
        g_moe_gather.mixed_direct_active = 1;
        g_moe_gather.mixed_cache_routes = cache_routes;
        g_moe_gather.mixed_compact_routes = compact_routes;
        if (getenv("DS4_CUDA_MOE_MIXED_DIRECT_STATS") != NULL) {
            fprintf(stderr,
                    "ds4: CUDA MoE mixed direct layer=%u cache_routes=%u compact_routes=%u\n",
                    layer_index, cache_routes, compact_routes);
        }
    }
    const int slot_is_zero = slot_count == 1u && slots[0] == 0;
    if (!(iq1_vram_all_hit && slot_is_zero &&
          g_moe_gather.iq1_slot_zero_valid)) {
        if (!cuda_ok(cudaMemcpy(g_moe_gather.slot, slots.data(),
                                (size_t)slot_count * sizeof(int32_t),
                                cudaMemcpyHostToDevice), "moe gather slots")) {
            cuda_spex_prefetch_release(spex_queue, spex_prefetch_slot, 1, 0);
            return 0;
        }
        g_moe_gather.iq1_slot_zero_valid = slot_is_zero ? 1u : 0u;
    }
    g_moe_gather.slot_tensor.ptr = g_moe_gather.slot;
    g_moe_gather.slot_tensor.bytes = (uint64_t)slot_count * sizeof(int32_t);
    g_moe_gather.slot_tensor.owner = 0;

    if (route_prof) {
        const double route_t_publish = cuda_wall_sec();
        g_route_prof_calls++;
        g_route_prof_d2h_s += route_t_d2h - route_t0;
        g_route_prof_observe_s += route_t_observe - route_t_d2h;
        g_route_prof_map_s += route_t_map - route_t_observe;
        g_route_prof_transport_s += route_t_transport - route_t_map;
        g_route_prof_publish_s += route_t_publish - route_t_transport;
        if (g_route_prof_calls % 60u == 0u) {
            const double scale = 1000.0 / (double)g_route_prof_calls;
            fprintf(stderr,
                    "ds4: [routeprof] calls=%llu d2h=%.3fms observe=%.3fms map=%.3fms transport=%.3fms publish=%.3fms\n",
                    (unsigned long long)g_route_prof_calls,
                    g_route_prof_d2h_s * scale,
                    g_route_prof_observe_s * scale,
                    g_route_prof_map_s * scale,
                    g_route_prof_transport_s * scale,
                    g_route_prof_publish_s * scale);
        }
    }

    if (getenv("DS4_CUDA_WEIGHT_CACHE_VERBOSE")) {
        fprintf(stderr, "ds4: CUDA MoE selected-load slots=%u compact=%u gate/up %.2f MiB down %.2f MiB\n",
                slot_count, compact_count,
                (double)cgate / 1048576.0, (double)cdown / 1048576.0);
    }
    g_moe_last_selected.gate_offset = gate_offset;
    g_moe_last_selected.count = compact_count;
    memcpy(g_moe_last_selected.ids, compact.data(),
           (size_t)compact_count * sizeof(g_moe_last_selected.ids[0]));
    g_moe_last_selected.valid = 1;
    cuda_spex_prefetch_release(spex_queue, spex_prefetch_slot, 1, 1);
    return 1;
}

extern "C" uint32_t ds4_gpu_routed_moe_last_selected(
        uint64_t gate_offset,
        int32_t *out_ids,
        uint32_t out_cap) {
    if (!out_ids || out_cap == 0 || !g_moe_last_selected.valid ||
        g_moe_last_selected.gate_offset != gate_offset) {
        return 0;
    }
    uint32_t count = g_moe_last_selected.count;
    if (count > out_cap) count = out_cap;
    memcpy(out_ids, g_moe_last_selected.ids,
           (size_t)count * sizeof(g_moe_last_selected.ids[0]));
    return count;
}

static int cuda_moe_route_split_down_ensure(
        cuda_moe_expert_cache *cache,
        uint32_t out_dim) {
    const uint64_t bytes =
        (uint64_t)CUDA_MOE_ROUTE_COUNT * out_dim * sizeof(float);
    if (cache->device_route_split_down &&
        cache->device_route_split_down_bytes >= bytes) {
        return 1;
    }
    if (cache->device_route_split_down) {
        (void)cudaFree(cache->device_route_split_down);
        cache->device_route_split_down = NULL;
        cache->device_route_split_down_bytes = 0;
    }
    if (cudaMalloc((void **)&cache->device_route_split_down, (size_t)bytes) !=
        cudaSuccess) {
        (void)cudaGetLastError();
        return 0;
    }
    cache->device_route_split_down_bytes = bytes;
    return 1;
}

static int cuda_moe_selected_load_q1_0(
        const void *model_map, uint64_t model_size,
        uint32_t layer_index,
        uint64_t gate_offset, uint64_t up_offset, uint64_t down_offset,
        uint64_t gate_expert_bytes, uint64_t down_expert_bytes,
        uint32_t n_total_expert, uint32_t n_expert, uint32_t n_tokens,
        const ds4_gpu_tensor *selected_arg) {
    if (!g_q1_0_sidecar_file_valid ||
        model_map != g_q1_0_sidecar_host_base ||
        model_size != g_q1_0_sidecar_size ||
        getenv("DS4_Q1_0_SELECTED_LOAD") == NULL) {
        return 0;
    }
    if (!selected_arg || !selected_arg->ptr ||
        n_total_expert == 0 || n_expert == 0 || n_tokens == 0 ||
        gate_expert_bytes == 0 || down_expert_bytes == 0 ||
        n_tokens > UINT32_MAX / n_expert) {
        return 0;
    }
    const uint32_t slot_count = n_tokens * n_expert;
    if (selected_arg->bytes < (uint64_t)slot_count * sizeof(int32_t)) return 0;

    g_moe_gather.h_sel.resize(slot_count);
    if (!cuda_ok(cudaMemcpy(g_moe_gather.h_sel.data(), selected_arg->ptr,
                            (size_t)slot_count * sizeof(int32_t),
                            cudaMemcpyDeviceToHost),
                 "Q1_0 selected D2H")) {
        return 0;
    }
    if (!cuda_sparse_bake_validate_selected(
            layer_index, g_moe_gather.h_sel.data(), slot_count,
            "Q1_0 routed selection", 0u)) {
        return 0;
    }

    std::vector<int32_t> &e2s = g_moe_gather.h_expert_to_slot;
    e2s.assign(n_total_expert, -1);
    std::vector<int32_t> &compact = g_moe_gather.h_compact_ids;
    compact.clear();
    std::vector<int32_t> &slots = g_moe_gather.h_slot_ids;
    slots.resize(slot_count);
    for (uint32_t i = 0; i < slot_count; i++) {
        const int32_t e = g_moe_gather.h_sel[i];
        if (e < 0 || (uint32_t)e >= n_total_expert) return 0;
        e2s[(uint32_t)e] = -2;
    }
    for (uint32_t e = 0; e < n_total_expert; e++) {
        if (e2s[e] != -2) continue;
        e2s[e] = (int32_t)compact.size();
        compact.push_back((int32_t)e);
    }
    for (uint32_t i = 0; i < slot_count; i++) {
        slots[i] = e2s[(uint32_t)g_moe_gather.h_sel[i]];
    }
    const uint32_t compact_count = (uint32_t)compact.size();
    if (compact_count == 0 || compact_count > n_total_expert) return 0;

    const uint64_t cgate = (uint64_t)compact_count * gate_expert_bytes;
    const uint64_t cdown = (uint64_t)compact_count * down_expert_bytes;
    if (!cuda_moe_gather_ensure(&g_moe_gather.gate, &g_moe_gather.gate_cap,
                                cgate, "Q1_0 gather gate") ||
        !cuda_moe_gather_ensure(&g_moe_gather.up, &g_moe_gather.up_cap,
                                cgate, "Q1_0 gather up") ||
        !cuda_moe_gather_ensure(&g_moe_gather.down, &g_moe_gather.down_cap,
                                cdown, "Q1_0 gather down") ||
        !cuda_moe_gather_ensure_i32(&g_moe_gather.slot, &g_moe_gather.slot_cap,
                                    slot_count, "Q1_0 gather slots")) {
        return 0;
    }

    if (cuda_q1_0_resident_transport_requested()) {
        cuda_dynamic_arena *q1_arena =
            cuda_q1_0_route_arena(layer_index);
        if (!q1_arena ||
            q1_arena->backing != CUDA_DYNAMIC_ARENA_BACKING_Q1_0 ||
            q1_arena->model_map != model_map ||
            q1_arena->model_size != model_size) {
            g_q1_0_resident_misses++;
            return 0;
        }
        uint64_t route_h2d_bytes = 0;
        const uint64_t pinned_h2d_before =
            q1_arena->pinned_bytes_uploaded;
        const uint64_t pageable_h2d_before =
            q1_arena->pageable_bytes_uploaded;
        for (uint32_t i = 0; i < compact_count; i++) {
            const uint32_t expert = (uint32_t)compact[i];
            const uint64_t gate_dst = (uint64_t)i * gate_expert_bytes;
            const uint64_t down_dst = (uint64_t)i * down_expert_bytes;
            const cuda_dynamic_arena_copy_status status =
                cuda_dynamic_arena_copy_expert_async(
                    *q1_arena,
                    model_map, layer_index, expert,
                    gate_offset, up_offset, down_offset,
                    g_moe_gather.gate + gate_dst,
                    g_moe_gather.up + gate_dst,
                    g_moe_gather.down + down_dst,
                    gate_expert_bytes, gate_expert_bytes,
                    down_expert_bytes);
            if (status != CUDA_DYNAMIC_ARENA_ENQUEUED) {
                g_q1_0_resident_misses++;
                (void)cudaStreamSynchronize(g_model_upload_stream);
                return 0;
            }
            route_h2d_bytes += gate_expert_bytes * 2u + down_expert_bytes;
        }
        if (!cuda_ok(cudaMemcpyAsync(
                         g_moe_gather.slot, slots.data(),
                         (size_t)slot_count * sizeof(int32_t),
                         cudaMemcpyHostToDevice, g_model_upload_stream),
                     "Q1_0 resident slots H2D")) {
            return 0;
        }
        const int q1_profile = cuda_q1_0_profile_requested();
        const double sync_started = q1_profile ? cuda_wall_sec() : 0.0;
        const cudaError_t sync_error =
            cudaStreamSynchronize(g_model_upload_stream);
        if (q1_profile) {
            const double sync_seconds = cuda_wall_sec() - sync_started;
            const uint64_t pinned_h2d =
                q1_arena->pinned_bytes_uploaded - pinned_h2d_before;
            const uint64_t pageable_h2d =
                q1_arena->pageable_bytes_uploaded - pageable_h2d_before;
            const uint64_t attributed_h2d = pinned_h2d + pageable_h2d;
            g_q1_0_profile.upload_sync_calls++;
            g_q1_0_profile.upload_sync_seconds += sync_seconds;
            if (attributed_h2d != 0) {
                const double pinned_seconds = sync_seconds *
                    (double)pinned_h2d / (double)attributed_h2d;
                g_q1_0_profile.pinned_upload_sync_seconds +=
                    pinned_seconds;
                g_q1_0_profile.pageable_upload_sync_seconds +=
                    sync_seconds - pinned_seconds;
            }
        }
        if (!cuda_ok(sync_error, "Q1_0 resident compact upload sync")) {
            return 0;
        }
        g_q1_0_resident_hits += compact_count;
        g_q1_0_resident_h2d_bytes += route_h2d_bytes;
    } else {
        std::vector<uint8_t> host_gate;
        std::vector<uint8_t> host_up;
        std::vector<uint8_t> host_down;
        try {
            host_gate.resize((size_t)cgate);
            host_up.resize((size_t)cgate);
            host_down.resize((size_t)cdown);
        } catch (...) {
            return 0;
        }

        g_q1_0_direct_pread_fallbacks++;
        for (uint32_t i = 0; i < compact_count; i++) {
            const uint32_t expert = (uint32_t)compact[i];
            const uint64_t gate_src = gate_offset +
                (uint64_t)expert * gate_expert_bytes;
            const uint64_t up_src = up_offset +
                (uint64_t)expert * gate_expert_bytes;
            const uint64_t down_src = down_offset +
                (uint64_t)expert * down_expert_bytes;
            if (gate_src > g_q1_0_sidecar_size ||
                gate_expert_bytes > g_q1_0_sidecar_size - gate_src ||
                up_src > g_q1_0_sidecar_size ||
                gate_expert_bytes > g_q1_0_sidecar_size - up_src ||
                down_src > g_q1_0_sidecar_size ||
                down_expert_bytes > g_q1_0_sidecar_size - down_src) {
                return 0;
            }
            if (!cuda_pread_full(
                    &g_q1_0_sidecar_file,
                    host_gate.data() + (uint64_t)i * gate_expert_bytes,
                    gate_expert_bytes, gate_src) ||
                !cuda_pread_full(
                    &g_q1_0_sidecar_file,
                    host_up.data() + (uint64_t)i * gate_expert_bytes,
                    gate_expert_bytes, up_src) ||
                !cuda_pread_full(
                    &g_q1_0_sidecar_file,
                    host_down.data() + (uint64_t)i * down_expert_bytes,
                    down_expert_bytes, down_src)) {
                return 0;
            }
        }

        if (!cuda_ok(cudaMemcpy(g_moe_gather.gate, host_gate.data(),
                                (size_t)cgate, cudaMemcpyHostToDevice),
                     "Q1_0 gate H2D") ||
            !cuda_ok(cudaMemcpy(g_moe_gather.up, host_up.data(),
                                (size_t)cgate, cudaMemcpyHostToDevice),
                     "Q1_0 up H2D") ||
            !cuda_ok(cudaMemcpy(g_moe_gather.down, host_down.data(),
                                (size_t)cdown, cudaMemcpyHostToDevice),
                     "Q1_0 down H2D") ||
            !cuda_ok(cudaMemcpy(g_moe_gather.slot, slots.data(),
                                (size_t)slot_count * sizeof(int32_t),
                                cudaMemcpyHostToDevice),
                     "Q1_0 slots H2D")) {
            return 0;
        }
        g_q1_0_direct_pread_bytes += cgate * 2u + cdown;
    }

    g_moe_gather.slot_tensor.ptr = g_moe_gather.slot;
    g_moe_gather.slot_tensor.bytes = (uint64_t)slot_count * sizeof(int32_t);
    g_moe_gather.slot_tensor.owner = 0;
    g_moe_gather.mixed_direct_active = 0;
    g_moe_gather.direct_cache_active = 0;
    return 1;
}

static cuda_moe_expert_cache *cuda_moe_gpu_resident_routes_begin(
        uint32_t layer_index,
        uint64_t gate_offset,
        uint64_t up_offset,
        uint64_t down_offset,
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes,
        uint32_t expert_in_dim,
        const ds4_gpu_tensor *selected,
        const ds4_gpu_tensor *weights,
        uint32_t n_expert,
        uint32_t n_tokens,
        ds4_gpu_spex_queue *spex_queue,
        uint32_t split_out_dim,
        uint32_t *sequence_out) {
    const int compose_requested = cuda_moe_prefill_tier_compose_requested();
    if (!cuda_moe_gpu_routes_requested() || !selected || !selected->ptr ||
        compose_requested < 0 ||
        !weights || !weights->ptr ||
        n_tokens != 1u || n_expert == 0u || n_expert > CUDA_MOE_ROUTE_COUNT ||
        layer_index >= CUDA_MOE_LAYER_COUNT || spex_queue ||
        cuda_moe_expert_cache_layer_top1() ||
        g_dynamic_arena_observer.enabled ||
        (g_prefill_mass_observer.enabled &&
         (!compose_requested ||
          !g_prefill_mass_observer.finalized ||
          !g_prefill_mass_observer.wrap_published)) ||
        g_reap_mass_observer.enabled ||
        expert_in_dim / CUDA_QK_K > 16u ||
        getenv("DS4_CUDA_MOE_NO_DECODE_LUT_GATE") != NULL ||
        getenv("DS4_CUDA_MOE_NO_DIRECT_DOWN_SUM6") != NULL) {
        if (n_expert != CUDA_MOE_ROUTE_COUNT) {
            fprintf(stderr,
                    "ds4: [gpu-route-variable] result=begin-refused routes=%u "
                    "requested=%d selected=%d weights=%d tokens=%u layer=%u "
                    "spex=%d top1=%d arena_observer=%d prefill_observer=%d "
                    "prefill_finalized=%d prefill_wrapped=%d reap_observer=%d "
                    "xq_blocks=%u no_lut=%d no_sum6=%d compose=%d\n",
                    n_expert, cuda_moe_gpu_routes_requested(),
                    selected && selected->ptr, weights && weights->ptr,
                    n_tokens, layer_index, spex_queue != NULL,
                    cuda_moe_expert_cache_layer_top1(),
                    g_dynamic_arena_observer.enabled,
                    g_prefill_mass_observer.enabled,
                    g_prefill_mass_observer.finalized,
                    g_prefill_mass_observer.wrap_published,
                    g_reap_mass_observer.enabled,
                    expert_in_dim / CUDA_QK_K,
                    getenv("DS4_CUDA_MOE_NO_DECODE_LUT_GATE") != NULL,
                    getenv("DS4_CUDA_MOE_NO_DIRECT_DOWN_SUM6") != NULL,
                    compose_requested);
        }
        return NULL;
    }
    cuda_moe_expert_cache *cache =
        cuda_moe_expert_cache_prepare(gate_expert_bytes, down_expert_bytes);
    if (!cache || !cache->route_thread_started || !cache->route_worker_ready ||
        cache->route_worker_failed || cache->route_stop ||
        cache->capacity < CUDA_MOE_ROUTE_COUNT ||
        !cache->device_slot_by_layer_expert || !cache->device_route_ptrs ||
        !cache->device_route_hit_mask ||
        !cache->route_ready_host || !cache->route_failed_host ||
        !cache->device_route_ready_sequence ||
        !cache->device_route_failed_sequence ||
        !cache->route_request_device) {
        if (n_expert != CUDA_MOE_ROUTE_COUNT) {
            fprintf(stderr,
                    "ds4: [gpu-route-variable] result=cache-refused routes=%u "
                    "cache=%d thread=%d ready=%d failed=%d stop=%d capacity=%u "
                    "slot_map=%d ptrs=%d hit_mask=%d ready_host=%d failed_host=%d "
                    "ready_dev=%d failed_dev=%d request_dev=%d\n",
                    n_expert, cache != NULL,
                    cache ? cache->route_thread_started : 0,
                    cache ? cache->route_worker_ready : 0,
                    cache ? cache->route_worker_failed : 0,
                    cache ? cache->route_stop : 0,
                    cache ? cache->capacity : 0,
                    cache && cache->device_slot_by_layer_expert,
                    cache && cache->device_route_ptrs,
                    cache && cache->device_route_hit_mask,
                    cache && cache->route_ready_host,
                    cache && cache->route_failed_host,
                    cache && cache->device_route_ready_sequence,
                    cache && cache->device_route_failed_sequence,
                    cache && cache->route_request_device);
        }
        return NULL;
    }
    if (split_out_dim != 0u &&
        !cuda_moe_route_split_down_ensure(cache, split_out_dim)) {
        if (n_expert != CUDA_MOE_ROUTE_COUNT) {
            fprintf(stderr,
                    "ds4: [gpu-route-variable] result=split-buffer-refused "
                    "routes=%u out_dim=%u\n",
                    n_expert, split_out_dim);
        }
        return NULL;
    }
    uint32_t sequence = ++cache->route_sequence;
    if (sequence == 0u) sequence = ++cache->route_sequence;
    const int nested_profile = g_nested_residual.profile_enabled &&
        cuda_nested_residual_gpu_cache_requested() &&
        cuda_nested_residual_layer_required(layer_index);
    const double route_begin_started =
        nested_profile ? cuda_wall_sec() : 0.0;
    moe_resolve_resident_routes_kernel<<<1, 1>>>(
        cache->device_route_ptrs,
        cache->device_route_hit_mask,
        cache->device_route_ready_sequence,
        cache->route_request_device,
        (const int32_t *)selected->ptr,
        (const float *)weights->ptr,
        cache->device_slot_by_layer_expert,
        layer_index,
        sequence,
        cache->gate,
        cache->up,
        cache->down,
        gate_offset,
        up_offset,
        down_offset,
        gate_expert_bytes,
        down_expert_bytes,
        n_expert);
    const cudaError_t resolve_launch_error = cudaGetLastError();
    if (nested_profile) {
        g_nested_residual.profile_route_begin_calls++;
        g_nested_residual.profile_route_begin_seconds +=
            cuda_wall_sec() - route_begin_started;
    }
    if (resolve_launch_error != cudaSuccess) {
        if (n_expert != CUDA_MOE_ROUTE_COUNT) {
            fprintf(stderr,
                    "ds4: [gpu-route-variable] result=resolve-launch-failed "
                    "routes=%u error=%s\n",
                    n_expert, cudaGetErrorString(resolve_launch_error));
        }
        return NULL;
    }
    cache->route_submitted_sequence = sequence;
    if (sequence_out) *sequence_out = sequence;
    return cache;
}

static cuda_moe_expert_cache *cuda_moe_gpu_resident_routes_finish(
        cuda_moe_expert_cache *cache,
        uint32_t sequence,
        uint32_t layer_index,
        int split_mode,
        uint32_t split_out_dim) {
    if (!cache || sequence == 0u) return NULL;
    const int nested_profile = g_nested_residual.profile_enabled &&
        cuda_nested_residual_gpu_cache_requested() &&
        cuda_nested_residual_layer_required(layer_index);
    if (cuda_moe_route_no_default_sync_requested()) {
        cache->route_no_default_sync_calls++;
    } else {
        cache->route_default_sync_calls++;
        const double resolve_started = cuda_wall_sec();
        const cudaError_t resolve_err = cudaStreamSynchronize(0);
        const double resolve_seconds = cuda_wall_sec() - resolve_started;
        cache->route_resolve_sync_seconds += resolve_seconds;
        if (nested_profile) {
            g_nested_residual.profile_route_resolve_sync_calls++;
            g_nested_residual.profile_route_resolve_sync_seconds +=
                resolve_seconds;
        }
        if (resolve_err != cudaSuccess) {
            fprintf(stderr,
                    "ds4: CUDA GPU-resident route resolver sync failed: %s\n",
                    cudaGetErrorString(resolve_err));
            abort();
        }
    }
    const double wait_started = cuda_wall_sec();
    const double wait_deadline = wait_started + 5.0;
    while (*(volatile uint32_t *)cache->route_ready_host != sequence) {
        if (cache->route_stop || cache->route_worker_failed) {
            fprintf(stderr,
                    "ds4: CUDA GPU-resident route resolver lost worker seq=%u\n",
                    sequence);
            abort();
        }
        if (cuda_wall_sec() >= wait_deadline) {
            fprintf(stderr,
                    "ds4: CUDA GPU-resident route worker timed out seq=%u\n",
                    sequence);
            abort();
        }
#ifdef _WIN32
        (void)SwitchToThread();
#else
        usleep(0);
#endif
    }
#ifdef _WIN32
    MemoryBarrier();
#else
    __sync_synchronize();
#endif
    const double ready_wait_seconds = cuda_wall_sec() - wait_started;
    cache->route_ready_wait_seconds += ready_wait_seconds;
    if (nested_profile) {
        g_nested_residual.profile_route_ready_wait_calls++;
        g_nested_residual.profile_route_ready_wait_seconds +=
            ready_wait_seconds;
    }
    if (*(volatile uint32_t *)cache->route_failed_host == sequence) {
        fprintf(stderr,
                "ds4: CUDA GPU-resident route resolver observed failure seq=%u; falling back\n",
                sequence);
        if (cuda_nested_residual_gpu_cache_requested() &&
            cuda_nested_residual_layer_required(layer_index)) {
            g_nested_residual.gpu_cache_failures++;
            g_nested_residual.hard_failure = 1;
        }
        cuda_moe_expert_cache_invalidate();
        return NULL;
    }
    const cuda_moe_route_request *request = cache->route_request_host;
    if (request && request->sequence == sequence &&
        request->route_count > 0u &&
        request->route_count <= CUDA_MOE_ROUTE_COUNT &&
        request->layer_index == layer_index) {
        if (cuda_nested_residual_gpu_cache_requested() &&
            cuda_nested_residual_layer_required(layer_index)) {
            g_nested_residual.router_open_calls++;
            g_nested_residual.gpu_route_calls++;
            g_nested_residual.gpu_route_hits +=
                request->route_count - request->miss_count;
            g_nested_residual.gpu_route_misses += request->miss_count;
        }
        g_moe_last_selected.gate_offset = request->gate_offset;
        g_moe_last_selected.count = request->route_count;
        memcpy(g_moe_last_selected.ids, request->selected,
               request->route_count * sizeof(g_moe_last_selected.ids[0]));
        g_moe_last_selected.valid = 1;
    }
    if (sequence <= 2u) {
        fprintf(stderr,
                "ds4: [gpu-route-debug] submit seq=%u layer=%u\n",
                sequence, layer_index);
    }
    cache->route_calls++;
    if (split_mode == 1) {
        cache->route_split_calls++;
    } else if (split_mode == 2) {
        cache->route_split_fused_calls++;
        if (!request || request->sequence != sequence ||
            request->route_count == 0u ||
            request->route_count > CUDA_MOE_ROUTE_COUNT ||
            request->miss_count > request->route_count ||
            split_out_dim == 0u) {
            fprintf(stderr,
                    "ds4: CUDA fused split telemetry contract failed seq=%u\n",
                    sequence);
            abort();
        }
        const uint64_t misses = request->miss_count;
        const uint64_t hits = request->route_count - misses;
        cache->route_split_fused_hits += hits;
        cache->route_split_fused_misses += misses;
        cache->route_split_fused_miss_scratch_bytes_avoided +=
            misses * split_out_dim * sizeof(float);
        cache->route_split_fused_sum_read_bytes_avoided +=
            misses * split_out_dim * sizeof(float);
    }
    return cache;
}

static cuda_moe_expert_cache *cuda_moe_gpu_resident_routes_submit(
        uint32_t layer_index,
        uint64_t gate_offset,
        uint64_t up_offset,
        uint64_t down_offset,
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes,
        uint32_t expert_in_dim,
        const ds4_gpu_tensor *selected,
        const ds4_gpu_tensor *weights,
        uint32_t n_expert,
        uint32_t n_tokens,
        ds4_gpu_spex_queue *spex_queue) {
    uint32_t sequence = 0;
    cuda_moe_expert_cache *cache = cuda_moe_gpu_resident_routes_begin(
        layer_index, gate_offset, up_offset, down_offset,
        gate_expert_bytes, down_expert_bytes, expert_in_dim,
        selected, weights, n_expert, n_tokens, spex_queue, 0u, &sequence);
    return cuda_moe_gpu_resident_routes_finish(
        cache, sequence, layer_index, 0, 0u);
}

static int routed_moe_launch(
        ds4_gpu_tensor *out,
        ds4_gpu_tensor *gate,
        ds4_gpu_tensor *up,
        ds4_gpu_tensor *mid,
        ds4_gpu_tensor *down,
        const void *model_map,
        uint64_t model_size,
        uint32_t layer_index,
        uint64_t gate_offset,
        uint64_t up_offset,
        uint64_t down_offset,
        uint32_t gate_type,
        uint32_t down_type,
        uint64_t gate_expert_bytes,
        uint64_t gate_row_bytes,
        uint64_t down_expert_bytes,
        uint64_t down_row_bytes,
        uint32_t expert_in_dim,
        uint32_t expert_mid_dim,
        uint32_t out_dim,
        const ds4_gpu_tensor *selected,
        const ds4_gpu_tensor *weights,
        const ds4_gpu_tensor *probs,
        uint32_t n_expert,
        float clamp,
        const ds4_gpu_tensor *x,
        uint32_t n_tokens,
        ds4_gpu_spex_queue *spex_queue,
        const ds4_gpu_spex_key *spex_key) {
    g_moe_last_selected.valid = 0;
    /* Wave state belongs to this routed-MoE invocation. Decode can take the
     * resident-route path without calling selected-load, so stale prefill
     * activation must never survive into the next layer/token. Per-parity
     * compute ownership is persistent and is cleared only by the reuse fence
     * in cuda_moe_selected_stage_wave(). */
    g_moe_gather.wave_active = 0;
    g_moe_gather.wave_fail_closed = 0;
    g_moe_gather.wave_double_buffer = 0;
    for (uint32_t i = 0; i < 2u; i++) {
        g_moe_gather.wave_active_pairs_db[i] = 0;
        g_moe_gather.wave_current_experts_db[i] = 0;
    }
    if (!out || !gate || !up || !mid || !down || !model_map || !selected || !weights || !x ||
        n_tokens == 0 || n_expert == 0 ||
        expert_in_dim % CUDA_QK_K != 0 || expert_mid_dim % CUDA_QK_K != 0 ||
        gate_offset > model_size || up_offset > model_size || down_offset > model_size ||
        x->bytes < (uint64_t)n_tokens * expert_in_dim * sizeof(float) ||
        selected->bytes < (uint64_t)n_tokens * n_expert * sizeof(int32_t) ||
        weights->bytes < (uint64_t)n_tokens * n_expert * sizeof(float) ||
        gate->bytes < (uint64_t)n_tokens * n_expert * expert_mid_dim * sizeof(float) ||
        up->bytes < (uint64_t)n_tokens * n_expert * expert_mid_dim * sizeof(float) ||
        mid->bytes < (uint64_t)n_tokens * n_expert * expert_mid_dim * sizeof(float) ||
        down->bytes < (uint64_t)n_tokens * n_expert * out_dim * sizeof(float) ||
        out->bytes < (uint64_t)n_tokens * out_dim * sizeof(float)) {
        return 0;
    }
    const uint32_t route_iq2_q2 = gate_type == 16u && down_type == 10u;
    const uint32_t route_iq1_s =
        gate_type == 19u && (down_type == 19u || down_type == 10u);
    const uint32_t route_q1_0 =
        gate_type == 41u && (down_type == 41u || down_type == 10u);
    if (!route_iq2_q2 && !route_iq1_s && !route_q1_0) return 0;
    if (route_iq1_s) {
        g_iq1_s_route_calls++;
        g_iq1_s_route_slots += (uint64_t)n_tokens * n_expert;
        if (getenv("DS4_CUDA_MOE_NO_SELECTED_LOAD") != NULL) {
            g_iq1_s_selected_load_failures++;
            fprintf(stderr,
                    "ds4: IQ1_S sidecar requires selected expert loading at layer=%u\n",
                    layer_index);
            return 0;
        }
    }
    if (route_q1_0) {
        g_q1_0_route_calls++;
        g_q1_0_route_slots += (uint64_t)n_tokens * n_expert;
        if (down_type != 41u) {
            g_q1_0_selected_load_failures++;
            fprintf(stderr,
                    "ds4: Q1_0 sidecar requires Q1_0 down tensor at layer=%u\n",
                    layer_index);
            return 0;
        }
        if (getenv("DS4_Q1_0_SELECTED_LOAD") == NULL ||
            getenv("DS4_CUDA_MOE_NO_SELECTED_LOAD") != NULL) {
            g_q1_0_selected_load_failures++;
            fprintf(stderr,
                    "ds4: Q1_0 sidecar requires opt-in selected expert loading at layer=%u\n",
                    layer_index);
            return 0;
        }
    }
    const uint32_t n_total_expert = 256u;
    const uint64_t gate_bytes = (uint64_t)n_total_expert * gate_expert_bytes;
    const uint64_t down_bytes = (uint64_t)n_total_expert * down_expert_bytes;
    if (gate_bytes > model_size - gate_offset ||
        gate_bytes > model_size - up_offset ||
        down_bytes > model_size - down_offset) {
        return 0;
    }
    const int sparse_bake_layer =
        cuda_sparse_bake_layer_is_sparse(layer_index);
    if (sparse_bake_layer &&
        getenv("DS4_CUDA_MOE_NO_SELECTED_LOAD") != NULL) {
        fprintf(stderr,
                "ds4: sparse bake requires selected expert loading at layer=%u\n",
                layer_index);
        return 0;
    }
    if (sparse_bake_layer) {
        spex_queue = NULL;
        spex_key = NULL;
    }
    const char *gate_w = NULL;
    const char *up_w = NULL;
    const char *down_w = NULL;
    uint32_t use_mixed_route_ptrs = 0;
    uint32_t use_split_hit_miss = 0;
    uint32_t use_split_fused = 0;
    uint32_t gpu_route_sequence = 0;
    const uint64_t *mixed_route_ptrs = NULL;
    const int nested_layer_required =
        cuda_nested_residual_layer_required(layer_index);
    const int nested_gpu_cache_requested = nested_layer_required &&
        cuda_nested_residual_gpu_cache_requested();
    if (nested_layer_required &&
        (getenv("DS4_CUDA_MOE_NO_SELECTED_LOAD") != NULL ||
         getenv("DS4_CUDA_PREFILL_WAVES") != NULL ||
         spex_queue != NULL)) {
        g_nested_residual.failures++;
        g_nested_residual.hard_failure = 1;
        fprintf(stderr,
                "ds4: nested residual covered layer requires exclusive "
                "selected-load transport layer=%u\n",
                layer_index);
        return 0;
    }
    if (g_nested_residual.active && g_nested_residual.hard_failure) {
        fprintf(stderr,
                "ds4: nested residual request refused after hard failure\n");
        return 0;
    }
    /* Selected-expert load: when the whole 256-expert block is beyond the pinned
     * host window (streaming regime), fetch/gather ONLY the routed experts into a
     * compact VRAM buffer and rebind `selected` to compact slots -- the unchanged
     * MoE kernels then touch top-6 of 256 (~42x less streamed per layer). Falls
     * back to the whole-block path on failure or when fully in-window (zero-copy). */
    const int whole_in_window =
        !route_iq1_s && !route_q1_0 && !sparse_bake_layer &&
        !nested_layer_required &&
        cuda_model_range_in_window(model_map, gate_offset, gate_bytes) &&
        cuda_model_range_in_window(model_map, up_offset, gate_bytes) &&
        cuda_model_range_in_window(model_map, down_offset, down_bytes);
    cuda_moe_expert_cache *gpu_route_cache = NULL;
    const int split_hit_miss_requested =
        (route_iq1_s || route_q1_0) ? 0 : cuda_moe_split_hit_miss_requested();
    const int split_fused_requested =
        (route_iq1_s || route_q1_0) ? 0 : cuda_moe_split_fused_requested();
    if (split_hit_miss_requested && split_fused_requested) {
        fprintf(stderr,
                "ds4: split hit/miss and fused split are mutually exclusive\n");
        return 0;
    }
    if (!route_iq1_s && !route_q1_0 &&
        (!nested_layer_required || nested_gpu_cache_requested) &&
        !whole_in_window &&
        getenv("DS4_CUDA_MOE_NO_SELECTED_LOAD") == NULL) {
        if (!sparse_bake_layer &&
            (split_hit_miss_requested || split_fused_requested) &&
            getenv("DS4_CUDA_MOE_PROFILE") == NULL) {
            gpu_route_cache = cuda_moe_gpu_resident_routes_begin(
                layer_index,
                gate_offset, up_offset, down_offset,
                gate_expert_bytes, down_expert_bytes,
                expert_in_dim,
                selected, weights, n_expert, n_tokens,
                spex_queue, out_dim, &gpu_route_sequence);
            use_split_fused = gpu_route_cache != NULL && split_fused_requested;
            use_split_hit_miss = gpu_route_cache != NULL && split_hit_miss_requested;
        } else {
            gpu_route_cache = cuda_moe_gpu_resident_routes_submit(
                layer_index,
                gate_offset, up_offset, down_offset,
                gate_expert_bytes, down_expert_bytes,
                expert_in_dim,
                selected, weights, n_expert, n_tokens,
                spex_queue);
        }
    }
    if (!route_iq1_s && !route_q1_0 &&
        (!nested_layer_required || nested_gpu_cache_requested) &&
        !gpu_route_cache && !whole_in_window && n_tokens == 1u &&
        (nested_gpu_cache_requested ||
         cuda_moe_tiering_mode_requested() != CUDA_MOE_TIER_OFF)) {
        if (nested_gpu_cache_requested) {
            g_nested_residual.gpu_cache_failures++;
            g_nested_residual.hard_failure = 1;
        }
        fprintf(stderr,
                "ds4: %s decode route unavailable at layer=%u; refusing fallback\n",
                nested_gpu_cache_requested ?
                    "nested residual GPU-cache" : "expert tiering",
                layer_index);
        return 0;
    }
    if (gpu_route_cache) {
        gate_w = gpu_route_cache->gate;
        up_w = gpu_route_cache->up;
        down_w = gpu_route_cache->down;
        use_mixed_route_ptrs = 1;
        mixed_route_ptrs = gpu_route_cache->device_route_ptrs;
        if (getenv("DS4_IQ1_MIXED_DEBUG") &&
            n_expert != CUDA_MOE_ROUTE_COUNT) {
            uint64_t route_ptrs[CUDA_MOE_ROUTE_COUNT * 3u] = {0};
            if (cuda_ok(cudaMemcpy(
                            route_ptrs, mixed_route_ptrs,
                            (size_t)n_expert * 3u * sizeof(uint64_t),
                            cudaMemcpyDeviceToHost),
                        "iq1 mixed route pointers D2H")) {
                for (uint32_t route = 0; route < n_expert; route++) {
                    const uint64_t gate_ptr = route_ptrs[route];
                    const uint64_t up_ptr = route_ptrs[n_expert + route];
                    const uint64_t down_ptr = route_ptrs[2u * n_expert + route];
                    const uint64_t gate_base =
                        (uint64_t)(uintptr_t)gpu_route_cache->gate;
                    const uint64_t up_base =
                        (uint64_t)(uintptr_t)gpu_route_cache->up;
                    const uint64_t down_base =
                        (uint64_t)(uintptr_t)gpu_route_cache->down;
                    fprintf(stderr,
                            "ds4: [iq1-mixed-debug] phase=route-ptrs route=%u "
                            "gate_slot=%llu gate_rem=%llu up_slot=%llu up_rem=%llu "
                            "down_slot=%llu down_rem=%llu\n",
                            route,
                            (unsigned long long)((gate_ptr - gate_base) /
                                gate_expert_bytes),
                            (unsigned long long)((gate_ptr - gate_base) %
                                gate_expert_bytes),
                            (unsigned long long)((up_ptr - up_base) /
                                gate_expert_bytes),
                            (unsigned long long)((up_ptr - up_base) %
                                gate_expert_bytes),
                            (unsigned long long)((down_ptr - down_base) /
                                down_expert_bytes),
                            (unsigned long long)((down_ptr - down_base) %
                                down_expert_bytes));
                }
            }
        }
    } else if (route_q1_0) {
        const int selected_loaded =
            cuda_moe_selected_load_q1_0(
                model_map, model_size, layer_index,
                gate_offset, up_offset, down_offset,
                gate_expert_bytes, down_expert_bytes,
                n_total_expert, n_expert, n_tokens, selected);
        if (selected_loaded) {
            g_q1_0_selected_loads++;
            gate_w = g_moe_gather.gate;
            up_w = g_moe_gather.up;
            down_w = g_moe_gather.down;
            selected = &g_moe_gather.slot_tensor;
        } else {
            g_q1_0_selected_load_failures++;
            ds4_gpu_spex_queue_cancel(spex_queue, spex_key);
            fprintf(stderr,
                    "ds4: Q1_0 sidecar selected load failed closed at layer=%u\n",
                    layer_index);
            return 0;
        }
    } else if (!whole_in_window && getenv("DS4_CUDA_MOE_NO_SELECTED_LOAD") == NULL) {
        const int selected_loaded =
            cuda_moe_selected_load(model_map, model_size, layer_index,
                                   gate_offset, up_offset, down_offset,
                                   gate_expert_bytes, down_expert_bytes,
                                    expert_in_dim,
                                    n_total_expert, n_expert, n_tokens,
                                    selected, weights, probs,
                                     spex_queue, spex_key, route_iq1_s);
        if (route_iq1_s) {
            if (selected_loaded) g_iq1_s_selected_loads++;
            else g_iq1_s_selected_load_failures++;
        }
        if (!selected_loaded &&
            (g_moe_gather.wave_fail_closed || nested_layer_required ||
             g_nested_residual.hard_failure)) {
            ds4_gpu_spex_queue_cancel(spex_queue, spex_key);
            if (nested_layer_required) {
                fprintf(stderr,
                        "ds4: nested residual selected load failed closed "
                        "at layer=%u\n",
                        layer_index);
            }
            return 0;
        }
        if (selected_loaded) {
            if (g_moe_gather.direct_cache_active) {
                gate_w = g_moe_expert_cache.gate;
                up_w = g_moe_expert_cache.up;
                down_w = g_moe_expert_cache.down;
            } else {
                if (g_moe_gather.wave_double_buffer) {
                    gate_w = g_moe_gather.wave_gate[0];
                    up_w = g_moe_gather.wave_up[0];
                    down_w = g_moe_gather.wave_down[0];
                } else {
                    if (route_iq1_s && n_expert == 1u &&
                        g_moe_gather.iq1_active_gate &&
                        g_moe_gather.iq1_active_up &&
                        g_moe_gather.iq1_active_down) {
                        gate_w = g_moe_gather.iq1_active_gate;
                        up_w = g_moe_gather.iq1_active_up;
                        down_w = g_moe_gather.iq1_active_down;
                    } else {
                        gate_w = g_moe_gather.gate;
                        up_w = g_moe_gather.up;
                        down_w = g_moe_gather.down;
                    }
                }
            }
            use_mixed_route_ptrs = g_moe_gather.mixed_direct_active;
            mixed_route_ptrs = use_mixed_route_ptrs ? g_moe_gather.route_ptrs : NULL;
            selected = &g_moe_gather.slot_tensor;   /* kernels index compact slots */
        } else {
            ds4_gpu_spex_queue_cancel(spex_queue, spex_key);
            if (nested_layer_required) {
                g_nested_residual.failures++;
                g_nested_residual.hard_failure = 1;
                fprintf(stderr,
                        "ds4: nested residual refused source fallback "
                        "at layer=%u\n",
                        layer_index);
                return 0;
            }
            if (route_iq1_s) {
                fprintf(stderr,
                        "ds4: IQ1_S sidecar selected load failed closed at layer=%u\n",
                        layer_index);
                return 0;
            }
            if (sparse_bake_layer) {
                fprintf(stderr,
                        "ds4: sparse bake selected load failed closed at layer=%u\n",
                        layer_index);
                return 0;
            }
            gate_w = cuda_model_range_ptr(model_map, gate_offset, gate_bytes, "moe_gate");
            up_w = cuda_model_range_ptr(model_map, up_offset, gate_bytes, "moe_up");
            down_w = cuda_model_range_ptr(model_map, down_offset, down_bytes, "moe_down");
        }
    } else {
        ds4_gpu_spex_queue_cancel(spex_queue, spex_key);
        if (nested_layer_required) {
            g_nested_residual.failures++;
            g_nested_residual.hard_failure = 1;
            fprintf(stderr,
                    "ds4: nested residual refused whole-tensor fallback "
                    "at layer=%u\n",
                    layer_index);
            return 0;
        }
        gate_w = cuda_model_range_ptr(model_map, gate_offset, gate_bytes, "moe_gate");
        up_w = cuda_model_range_ptr(model_map, up_offset, gate_bytes, "moe_up");
        down_w = cuda_model_range_ptr(model_map, down_offset, down_bytes, "moe_down");
    }
    if (!gate_w || !up_w || !down_w) return 0;

    int ok = 1;
    const uint32_t xq_blocks = expert_in_dim / CUDA_QK_K;
    const uint32_t midq_blocks = expert_mid_dim / CUDA_QK_K;
    const uint64_t xq_count = (uint64_t)n_tokens * xq_blocks;
    const uint64_t midq_count = (uint64_t)n_tokens * n_expert * midq_blocks;
    const uint64_t xq_bytes = xq_count * sizeof(cuda_block_q8_K);
    const uint64_t midq_bytes = midq_count * sizeof(cuda_block_q8_K);
    if (down->bytes >= xq_bytes && gate->bytes >= midq_bytes) {
        const uint32_t pair_count = n_tokens * n_expert;
        cuda_block_q8_K *xq = (cuda_block_q8_K *)down->ptr;
        uint32_t *wave_pairs_dev = NULL;
        if (g_moe_gather.wave_active) {
            if (xq_bytes > UINT64_MAX - 255ull) return 0;
            const uint64_t xq_scratch_bytes = (xq_bytes + 255ull) & ~255ull;
            const uint64_t wave_pairs_bytes =
                (uint64_t)pair_count * sizeof(uint32_t);
            if (wave_pairs_bytes > UINT64_MAX - xq_scratch_bytes) return 0;
            uint8_t *wave_scratch = (uint8_t *)cuda_tmp_alloc(
                xq_scratch_bytes + wave_pairs_bytes,
                "routed_moe wave xq and pairs");
            if (!wave_scratch) return 0;
            xq = (cuda_block_q8_K *)wave_scratch;
            wave_pairs_dev = (uint32_t *)(wave_scratch + xq_scratch_bytes);
        }
        cuda_block_q8_K *midq = (cuda_block_q8_K *)gate->ptr;
        const uint32_t legacy_profile_moe =
            getenv("DS4_CUDA_MOE_PROFILE") != NULL;
        const uint32_t q1_profile_moe =
            route_q1_0 && cuda_q1_0_profile_requested();
        const uint32_t profile_moe =
            legacy_profile_moe || q1_profile_moe;
        cudaEvent_t prof_ev[7] = {NULL, NULL, NULL, NULL, NULL, NULL, NULL};
        if (profile_moe) {
            for (uint32_t i = 0; i < 7u; i++) {
                if (cudaEventCreate(&prof_ev[i]) != cudaSuccess) {
                    for (uint32_t j = 0; j < i; j++) (void)cudaEventDestroy(prof_ev[j]);
                    memset(prof_ev, 0, sizeof(prof_ev));
                    if (q1_profile_moe) g_q1_0_profile.timer_failures++;
                    break;
                }
            }
            if (prof_ev[0]) (void)cudaEventRecord(prof_ev[0], 0);
        }
        const uint32_t use_sorted_pairs = n_tokens > 1u;
        const uint32_t use_expert_tiles = use_sorted_pairs && getenv("DS4_CUDA_MOE_NO_EXPERT_TILES") == NULL;
        const uint32_t expert_tile_m = getenv("DS4_CUDA_MOE_TILE4") ? 4u : 8u;
        const uint32_t write_gate_up = getenv("DS4_CUDA_MOE_WRITE_GATE_UP") != NULL;
        const uint32_t use_p2_sorted = use_sorted_pairs && getenv("DS4_CUDA_MOE_NO_P2") == NULL;
        const uint32_t use_atomic_down = use_expert_tiles &&
            (getenv("DS4_CUDA_MOE_ATOMIC_DOWN") != NULL ||
             (n_tokens >= 128u && getenv("DS4_CUDA_MOE_NO_ATOMIC_DOWN") == NULL));
        const uint32_t use_gate_row2048 = use_expert_tiles && expert_tile_m == 8u &&
            (getenv("DS4_CUDA_MOE_GATE_ROW2048") != NULL ||
             getenv("DS4_CUDA_MOE_GATE_ROW256") != NULL ||
             getenv("DS4_CUDA_MOE_GATE_ROW128") != NULL ||
             (n_tokens >= 128u &&
              getenv("DS4_CUDA_MOE_NO_GATE_ROW2048") == NULL &&
              getenv("DS4_CUDA_MOE_NO_GATE_ROW256") == NULL &&
              getenv("DS4_CUDA_MOE_NO_GATE_ROW128") == NULL));
        const uint32_t use_down_tile16 = use_atomic_down && expert_tile_m == 8u &&
            n_tokens >= 128u && getenv("DS4_CUDA_MOE_NO_DOWN_TILE16") == NULL;
        const uint32_t use_down_block16 = use_down_tile16 && midq_blocks <= 8u &&
            getenv("DS4_CUDA_MOE_NO_DOWN_BLOCK16") == NULL;
        const uint32_t use_decode_lut_gate =
            n_tokens == 1u && xq_blocks <= 16u &&
            getenv("DS4_CUDA_MOE_NO_DECODE_LUT_GATE") == NULL;
        const uint32_t gate_row_span =
            getenv("DS4_CUDA_MOE_GATE_ROW512") != NULL ? 512u :
            getenv("DS4_CUDA_MOE_GATE_ROW2048") != NULL ? 2048u : 1024u;
        const uint32_t down_row_span =
            getenv("DS4_CUDA_MOE_DOWN_ROW512") != NULL ? 512u :
            getenv("DS4_CUDA_MOE_DOWN_ROW1024") != NULL ? 1024u : 2048u;
        const uint32_t use_down_row2048 = use_atomic_down && expert_tile_m == 8u &&
            (getenv("DS4_CUDA_MOE_DOWN_ROW2048") != NULL ||
             getenv("DS4_CUDA_MOE_DOWN_ROW256") != NULL ||
             getenv("DS4_CUDA_MOE_DOWN_ROW128") != NULL ||
             getenv("DS4_CUDA_MOE_DOWN_ROW64") != NULL ||
             (use_down_tile16 &&
              getenv("DS4_CUDA_MOE_NO_DOWN_ROW2048") == NULL &&
              getenv("DS4_CUDA_MOE_NO_DOWN_ROW256") == NULL &&
              getenv("DS4_CUDA_MOE_NO_DOWN_ROW128") == NULL &&
              getenv("DS4_CUDA_MOE_NO_DOWN_ROW64") == NULL));
        const uint32_t use_direct_down_sum6 =
            n_tokens == 1u && n_expert == 6u &&
            getenv("DS4_CUDA_MOE_NO_DIRECT_DOWN_SUM6") == NULL;
        uint32_t *sorted_pairs = NULL;
        uint32_t *sorted_offsets = NULL;
        uint32_t *sorted_counts = NULL;
        uint32_t *tile_total = NULL;
        uint32_t *tile_experts = NULL;
        uint32_t *tile_starts = NULL;
        uint32_t *tile16_total = NULL;
        uint32_t *tile16_experts = NULL;
        uint32_t *tile16_starts = NULL;
        uint32_t tile_capacity = 0;
        uint32_t tile16_capacity = 0;
        dim3 xq_grid(xq_blocks, n_tokens, 1);
        q8_K_quantize_kernel<<<xq_grid, 256>>>(
            xq, (const float *)x->ptr, expert_in_dim, n_tokens,
            NULL, 0u, 0u);
        ok = cuda_ok(cudaGetLastError(), "routed_moe x quantize launch");
        if (prof_ev[1]) (void)cudaEventRecord(prof_ev[1], 0);
        if (route_q1_0) {
            if (g_moe_gather.wave_active) ok = 0;
            if (prof_ev[2]) (void)cudaEventRecord(prof_ev[2], 0);
            if (ok) {
                dim3 mgrid((expert_mid_dim + 7u) / 8u,
                           pair_count, 1);
                moe_gate_up_mid_q1_0_qwarp32_kernel<<<mgrid, 256>>>(
                    (float *)gate->ptr,
                    (float *)up->ptr,
                    (float *)mid->ptr,
                    gate_w,
                    up_w,
                    NULL,
                    xq,
                    (const int32_t *)selected->ptr,
                    (const float *)weights->ptr,
                    gate_expert_bytes,
                    gate_row_bytes,
                    xq_blocks,
                    expert_mid_dim,
                    n_expert,
                    pair_count,
                    clamp);
                ok = cuda_ok(cudaGetLastError(),
                             "routed_moe Q1_0 gate/up launch");
            }
            if (prof_ev[3]) (void)cudaEventRecord(prof_ev[3], 0);
            if (ok) {
                dim3 midq_grid(midq_blocks, pair_count, 1);
                q8_K_quantize_kernel<<<midq_grid, 256>>>(
                    midq, (const float *)mid->ptr, expert_mid_dim,
                    pair_count, NULL, 0u, 0u);
                ok = cuda_ok(cudaGetLastError(),
                             "routed_moe Q1_0 mid quantize launch");
            }
            if (prof_ev[4]) (void)cudaEventRecord(prof_ev[4], 0);
            if (ok) {
                dim3 dgrid((out_dim + 7u) / 8u, pair_count, 1);
                moe_down_q1_0_qwarp32_kernel<<<dgrid, 256>>>(
                    (float *)down->ptr,
                    down_w,
                    NULL,
                    midq,
                    (const int32_t *)selected->ptr,
                    down_expert_bytes,
                    down_row_bytes,
                    midq_blocks,
                    out_dim,
                    n_expert,
                    pair_count);
                ok = cuda_ok(cudaGetLastError(),
                             "routed_moe Q1_0 down launch");
            }
            if (prof_ev[5]) (void)cudaEventRecord(prof_ev[5], 0);
            if (ok) {
                const uint64_t n = (uint64_t)n_tokens * out_dim;
                const uint32_t blocks = (uint32_t)((n + 255u) / 256u);
                moe_sum_kernel<<<blocks, 256>>>(
                    (float *)out->ptr, (const float *)down->ptr,
                    out_dim, n_expert, n_tokens);
                ok = cuda_ok(cudaGetLastError(),
                             "routed_moe Q1_0 sum launch");
            }
            if (prof_ev[6]) {
                const cudaError_t record_error = cudaEventRecord(prof_ev[6], 0);
                const cudaError_t synchronize_error =
                    record_error == cudaSuccess ?
                        cudaEventSynchronize(prof_ev[6]) : record_error;
                if (synchronize_error == cudaSuccess) {
                    float ms_xq = 0.0f, ms_gate = 0.0f;
                    float ms_midq = 0.0f, ms_down = 0.0f;
                    float ms_sum = 0.0f, ms_total = 0.0f;
                    (void)cudaEventElapsedTime(&ms_xq, prof_ev[0], prof_ev[1]);
                    (void)cudaEventElapsedTime(&ms_gate, prof_ev[2], prof_ev[3]);
                    (void)cudaEventElapsedTime(&ms_midq, prof_ev[3], prof_ev[4]);
                    (void)cudaEventElapsedTime(&ms_down, prof_ev[4], prof_ev[5]);
                    (void)cudaEventElapsedTime(&ms_sum, prof_ev[5], prof_ev[6]);
                    const cudaError_t elapsed_error = cudaEventElapsedTime(
                        &ms_total, prof_ev[0], prof_ev[6]);
                    if (q1_profile_moe) {
                        if (elapsed_error == cudaSuccess) {
                            g_q1_0_profile.q1_kernel_calls++;
                            g_q1_0_profile.q1_kernel_seconds +=
                                (double)ms_total / 1000.0;
                        } else {
                            g_q1_0_profile.timer_failures++;
                        }
                    }
                    if (legacy_profile_moe) {
                        fprintf(stderr,
                                "ds4: CUDA Q1_0 MoE profile tokens=%u pairs=%u xq=%.3f gateup=%.3f midq=%.3f down=%.3f sum=%.3f total=%.3f ms\n",
                                n_tokens, pair_count, ms_xq, ms_gate, ms_midq,
                                ms_down, ms_sum, ms_total);
                    }
                } else if (q1_profile_moe) {
                    g_q1_0_profile.timer_failures++;
                }
                for (uint32_t i = 0; i < 7u; i++) {
                    (void)cudaEventDestroy(prof_ev[i]);
                }
            }
            return ok;
        }
        if (route_iq1_s) {
            if (ok && g_moe_gather.wave_active) {
                if (!wave_pairs_dev) ok = 0;
                const int wave_double_buffer =
                    g_moe_gather.wave_double_buffer != 0;
                for (uint32_t wave = 0; ok && wave < g_moe_gather.wave_count; wave++) {
                    const uint32_t parity = wave & 1u;
                    int wave_work_enqueued = 0;
                    const char *wave_gate_w = gate_w;
                    const char *wave_up_w = up_w;
                    const char *wave_down_w = down_w;
                    const int32_t *wave_selected =
                        (const int32_t *)selected->ptr;
                    uint32_t *wave_pairs_current = wave_pairs_dev;
