                        (float *)down->ptr,
                        down_w,
                        use_mixed_route_ptrs ? mixed_route_ptrs : NULL,
                        midq,
                        (const int32_t *)selected->ptr,
                        down_expert_bytes,
                        down_row_bytes,
                        midq_blocks,
                        out_dim,
                        n_expert,
                        pair_count);
                } else {
                    moe_down_q2_K_route_qwarp32_kernel<<<dgrid, 256>>>(
                        (float *)down->ptr,
                        down_w,
                        use_mixed_route_ptrs ? mixed_route_ptrs : NULL,
                        midq,
                        (const int32_t *)selected->ptr,
                        down_expert_bytes,
                        down_row_bytes,
                        midq_blocks,
                        out_dim,
                        n_expert,
                        pair_count);
                }
                ok = cuda_ok(cudaGetLastError(),
                             "routed_moe IQ1_S down launch");
            }
            if (prof_ev[5]) (void)cudaEventRecord(prof_ev[5], 0);
            if (ok) {
                const uint64_t n = (uint64_t)n_tokens * out_dim;
                const uint32_t blocks = (uint32_t)((n + 255u) / 256u);
                moe_sum_kernel<<<blocks, 256>>>(
                    (float *)out->ptr, (const float *)down->ptr,
                    out_dim, n_expert, n_tokens);
                ok = cuda_ok(cudaGetLastError(),
                             "routed_moe IQ1_S sum launch");
            }
            if (prof_ev[6]) {
                (void)cudaEventRecord(prof_ev[6], 0);
                if (cudaEventSynchronize(prof_ev[6]) == cudaSuccess) {
                    float ms_xq = 0.0f, ms_gate = 0.0f;
                    float ms_midq = 0.0f, ms_down = 0.0f;
                    float ms_sum = 0.0f, ms_total = 0.0f;
                    (void)cudaEventElapsedTime(&ms_xq, prof_ev[0], prof_ev[1]);
                    (void)cudaEventElapsedTime(&ms_gate, prof_ev[2], prof_ev[3]);
                    (void)cudaEventElapsedTime(&ms_midq, prof_ev[3], prof_ev[4]);
                    (void)cudaEventElapsedTime(&ms_down, prof_ev[4], prof_ev[5]);
                    (void)cudaEventElapsedTime(&ms_sum, prof_ev[5], prof_ev[6]);
                    (void)cudaEventElapsedTime(&ms_total, prof_ev[0], prof_ev[6]);
                    fprintf(stderr,
                            "ds4: CUDA IQ1_S MoE profile tokens=%u pairs=%u xq=%.3f gateup=%.3f midq=%.3f down=%.3f sum=%.3f total=%.3f ms\n",
                            n_tokens, pair_count, ms_xq, ms_gate, ms_midq,
                            ms_down, ms_sum, ms_total);
                }
                for (uint32_t i = 0; i < 7u; i++) {
                    (void)cudaEventDestroy(prof_ev[i]);
                }
            }
            return ok;
        }
        if (ok && g_moe_gather.wave_active) {
            if (!wave_pairs_dev) ok = 0;
            const int wave_double_buffer =
                g_moe_gather.wave_double_buffer != 0;
            for (uint32_t wave = 0; ok && wave < g_moe_gather.wave_count; wave++) {
                const uint32_t parity = wave & 1u;
                int wave_work_enqueued = 0;
                const char *wave_gate_w = gate_w;
                const char *wave_up_w = up_w;
                const char *wave_down_w = down_w;
                const int32_t *wave_selected =
                    (const int32_t *)selected->ptr;
                uint32_t *wave_pairs_current = wave_pairs_dev;
                cudaEvent_t wave_upload_ready =
                    g_moe_gather.wave_upload_ready;
                std::vector<uint32_t> *wave_pairs_host =
                    &g_moe_gather.h_wave_pairs;
                uint32_t wave_pair_count =
                    g_moe_gather.wave_active_pairs;
                if (wave_double_buffer) {
                    wave_gate_w = g_moe_gather.wave_gate[parity];
                    wave_up_w = g_moe_gather.wave_up[parity];
                    wave_down_w = g_moe_gather.wave_down[parity];
                    wave_selected = g_moe_gather.wave_slot[parity];
                    wave_pairs_current = g_moe_gather.wave_pair[parity];
                    wave_upload_ready =
                        g_moe_gather.wave_upload_ready_db[parity];
                    wave_pairs_host =
                        &g_moe_gather.h_wave_pairs_db[parity];
                    wave_pair_count =
                        g_moe_gather.wave_active_pairs_db[parity];
                }
                if (!wave_double_buffer && wave != 0u) {
                    ok = cuda_ok(cudaStreamSynchronize(0),
                                 "moe wave execution sync");
                }
                if (ok && !wave_double_buffer && wave != 0u) {
                    ok = cuda_moe_selected_stage_wave(
                        model_map, layer_index,
                        gate_offset, up_offset, down_offset,
                        gate_expert_bytes, down_expert_bytes,
                        n_total_expert, n_expert, n_tokens, wave);
                    wave_pair_count = g_moe_gather.wave_active_pairs;
                }
                if (ok) {
                    ok = cuda_ok(cudaStreamWaitEvent(
                                     0, wave_upload_ready, 0),
                                 "moe wave upload wait");
                }
                if (!ok) break;
                g_prefill_wave_stats.upload_waits =
                    cuda_u64_saturating_add(g_prefill_wave_stats.upload_waits, 1);
                if (wave_pair_count == 0 ||
                    wave_pair_count > pair_count ||
                    wave_pairs_host->size() != wave_pair_count) {
                    ok = 0;
                    break;
                }
                if (!wave_double_buffer) {
                    ok = cuda_ok(cudaMemcpyAsync(
                                     wave_pairs_dev,
                                     wave_pairs_host->data(),
                                     (size_t)wave_pair_count * sizeof(uint32_t),
                                     cudaMemcpyHostToDevice, 0),
                                 "routed_moe wave pairs upload");
                }
                if (!ok) break;

                dim3 mgrid((expert_mid_dim + 31u) / 32u,
                           wave_pair_count, 1);
                moe_gate_up_mid_sorted_qwarp32_kernel<<<mgrid, 256>>>(
                    (float *)gate->ptr,
                    (float *)up->ptr,
                    (float *)mid->ptr,
                    wave_gate_w,
                    wave_up_w,
                    xq,
                    wave_pairs_current,
                    wave_selected,
                    (const float *)weights->ptr,
                    gate_expert_bytes,
                    gate_row_bytes,
                    xq_blocks,
                    expert_mid_dim,
                    n_expert,
                    clamp);
                ok = cuda_ok(cudaGetLastError(), "routed_moe wave gate/up launch");
                if (!ok) break;
                wave_work_enqueued = 1;

                dim3 midq_grid(midq_blocks, n_tokens * n_expert, 1);
                q8_K_quantize_kernel<<<midq_grid, 256>>>(
                    midq, (const float *)mid->ptr, expert_mid_dim,
                    n_tokens * n_expert, NULL, 0u, 0u);
                ok = cuda_ok(cudaGetLastError(), "routed_moe wave mid quantize launch");
                if (!ok) {
                    if (wave_double_buffer && wave_work_enqueued) {
                        (void)cuda_moe_wave_compute_seal(parity);
                    }
                    break;
                }

                dim3 dgrid((out_dim + 31u) / 32u, wave_pair_count, 1);
                moe_down_sorted_qwarp32_kernel<<<dgrid, 256>>>(
                    (float *)down->ptr,
                    wave_down_w,
                    midq,
                    wave_pairs_current,
                    wave_selected,
                    down_expert_bytes,
                    down_row_bytes,
                    midq_blocks,
                    out_dim,
                    n_expert);
                ok = cuda_ok(cudaGetLastError(), "routed_moe wave down launch");
                if (!ok) {
                    if (wave_double_buffer && wave_work_enqueued) {
                        (void)cuda_moe_wave_compute_seal(parity);
                    }
                    break;
                }
                if (wave_double_buffer) {
                    ok = cuda_moe_wave_compute_seal(parity);
                    if (!ok) break;
                }

                g_prefill_wave_stats.waves =
                    cuda_u64_saturating_add(g_prefill_wave_stats.waves, 1);
                g_prefill_wave_stats.active_pairs =
                    cuda_u64_saturating_add(g_prefill_wave_stats.active_pairs,
                                            wave_pair_count);
                if (wave_double_buffer) {
                    g_prefill_wave_overlap_stats.waves =
                        cuda_u64_saturating_add(
                            g_prefill_wave_overlap_stats.waves, 1);
                    const uint32_t next_wave = wave + 1u;
                    if (next_wave < g_moe_gather.wave_count) {
                        ok = cuda_moe_selected_stage_wave(
                            model_map, layer_index,
                            gate_offset, up_offset, down_offset,
                            gate_expert_bytes, down_expert_bytes,
                            n_total_expert, n_expert, n_tokens, next_wave);
                        if (!ok) break;
                    }
                }
            }
            if (prof_ev[5]) (void)cudaEventRecord(prof_ev[5], 0);
            if (ok) {
                uint64_t n = (uint64_t)n_tokens * out_dim;
                moe_sum_kernel<<<(n + 255) / 256, 256>>>(
                    (float *)out->ptr,
                    (const float *)down->ptr,
                    out_dim,
                    n_expert,
                    n_tokens);
                ok = cuda_ok(cudaGetLastError(), "routed_moe wave sum launch");
            }
            if (ok) {
                g_prefill_wave_stats.layers = cuda_u64_saturating_add(
                    g_prefill_wave_stats.layers, 1);
                if (wave_double_buffer) {
                    g_prefill_wave_overlap_stats.layers =
                        cuda_u64_saturating_add(
                            g_prefill_wave_overlap_stats.layers, 1);
                }
                if (getenv("DS4_CUDA_PREFILL_UNION_STATS") != NULL) {
                    g_prefill_union_stats.calls = cuda_u64_saturating_add(
                        g_prefill_union_stats.calls, 1);
                    g_prefill_union_stats.tokens = cuda_u64_saturating_add(
                        g_prefill_union_stats.tokens, n_tokens);
                    g_prefill_union_stats.selected_slots = cuda_u64_saturating_add(
                        g_prefill_union_stats.selected_slots, pair_count);
                    g_prefill_union_stats.unique_experts = cuda_u64_saturating_add(
                        g_prefill_union_stats.unique_experts,
                        g_moe_gather.wave_unique_experts);
                    g_prefill_union_stats.arena_experts = cuda_u64_saturating_add(
                        g_prefill_union_stats.arena_experts,
                        g_moe_gather.wave_arena_experts);
                    g_prefill_union_stats.direct_experts = cuda_u64_saturating_add(
                        g_prefill_union_stats.direct_experts,
                        g_moe_gather.wave_direct_experts);
                    g_prefill_union_stats.nonresident_experts = cuda_u64_saturating_add(
                        g_prefill_union_stats.nonresident_experts,
                        g_moe_gather.wave_direct_experts);
                    g_prefill_union_stats.source_span_bytes = cuda_u64_saturating_add(
                        g_prefill_union_stats.source_span_bytes,
                        g_moe_gather.wave_source_span_bytes);
                    g_prefill_union_stats.arena_h2d_bytes = cuda_u64_saturating_add(
                        g_prefill_union_stats.arena_h2d_bytes,
                        g_moe_gather.wave_arena_h2d_bytes);
                    if (n_tokens > g_prefill_union_stats.max_tokens) {
                        g_prefill_union_stats.max_tokens = n_tokens;
                    }
                    if (g_moe_gather.wave_unique_experts >
                        g_prefill_union_stats.max_union) {
                        g_prefill_union_stats.max_union =
                            g_moe_gather.wave_unique_experts;
                    }
                }
            } else {
                g_prefill_wave_stats.failures = cuda_u64_saturating_add(
                    g_prefill_wave_stats.failures, 1);
                if (wave_double_buffer) {
                    g_prefill_wave_overlap_stats.failures =
                        cuda_u64_saturating_add(
                            g_prefill_wave_overlap_stats.failures, 1);
                }
            }
            if (prof_ev[6]) {
                (void)cudaEventRecord(prof_ev[6], 0);
                if (cudaEventSynchronize(prof_ev[6]) == cudaSuccess) {
                    float ms_xq = 0.0f, ms_waves = 0.0f, ms_sum = 0.0f, ms_total = 0.0f;
                    (void)cudaEventElapsedTime(&ms_xq, prof_ev[0], prof_ev[1]);
                    (void)cudaEventElapsedTime(&ms_waves, prof_ev[1], prof_ev[5]);
                    (void)cudaEventElapsedTime(&ms_sum, prof_ev[5], prof_ev[6]);
                    (void)cudaEventElapsedTime(&ms_total, prof_ev[0], prof_ev[6]);
                    fprintf(stderr,
                            "ds4: CUDA MoE wave profile tokens=%u pairs=%u waves=%u max_wave=%u xq=%.3f waves_ms=%.3f sum=%.3f total=%.3f ms\n",
                            n_tokens, pair_count, g_moe_gather.wave_count,
                            g_moe_gather.wave_max_experts, ms_xq, ms_waves,
                            ms_sum, ms_total);
                }
                for (uint32_t i = 0; i < 7u; i++) (void)cudaEventDestroy(prof_ev[i]);
            }
            return ok;
        }
        if (ok && (use_split_hit_miss || use_split_fused)) {
            dim3 qgrid((expert_mid_dim + 127u) / 128u, n_expert, 1);
            dim3 midq_grid(midq_blocks, n_expert, 1);
            dim3 dgrid((out_dim + 31u) / 32u, n_expert, 1);
            const uint32_t *hit_mask = gpu_route_cache->device_route_hit_mask;
            float *split_down = gpu_route_cache->device_route_split_down;

            moe_gate_up_mid_decode_ptrs_lut_qwarp32_kernel<<<qgrid, 256>>>(
                (float *)gate->ptr,
                (float *)up->ptr,
                (float *)mid->ptr,
                mixed_route_ptrs,
                xq,
                (const float *)weights->ptr,
                gate_row_bytes,
                xq_blocks,
                expert_mid_dim,
                n_expert,
                write_gate_up,
                clamp,
                hit_mask,
                1u);
            ok = cuda_ok(cudaGetLastError(), "routed_moe split hit gate/up launch");
            if (ok) {
                q8_K_quantize_kernel<<<midq_grid, 256>>>(
                    midq, (const float *)mid->ptr, expert_mid_dim, n_expert,
                    hit_mask, n_expert, 1u);
                ok = cuda_ok(cudaGetLastError(), "routed_moe split hit mid quantize launch");
            }
            if (ok) {
                moe_down_ptrs_masked_qwarp32_kernel<<<dgrid, 256>>>(
                    split_down,
                    mixed_route_ptrs + 2u * n_expert,
                    midq,
                    hit_mask,
                    1u,
                    down_row_bytes,
                    midq_blocks,
                    out_dim);
                ok = cuda_ok(cudaGetLastError(), "routed_moe split hit down launch");
            }

            gpu_route_cache = cuda_moe_gpu_resident_routes_finish(
                gpu_route_cache, gpu_route_sequence, layer_index,
                use_split_fused ? 2 : 1, out_dim);
            if (!gpu_route_cache) ok = 0;

            if (ok) {
                moe_gate_up_mid_decode_ptrs_lut_qwarp32_kernel<<<qgrid, 256>>>(
                    (float *)gate->ptr,
                    (float *)up->ptr,
                    (float *)mid->ptr,
                    mixed_route_ptrs,
                    xq,
                    (const float *)weights->ptr,
                    gate_row_bytes,
                    xq_blocks,
                    expert_mid_dim,
                    n_expert,
                    write_gate_up,
                    clamp,
                    hit_mask,
                    0u);
                ok = cuda_ok(cudaGetLastError(), "routed_moe split miss gate/up launch");
            }
            if (ok) {
                q8_K_quantize_kernel<<<midq_grid, 256>>>(
                    midq, (const float *)mid->ptr, expert_mid_dim, n_expert,
                    hit_mask, n_expert, 0u);
                ok = cuda_ok(cudaGetLastError(), "routed_moe split miss mid quantize launch");
            }
            if (ok && !use_split_fused) {
                moe_down_ptrs_masked_qwarp32_kernel<<<dgrid, 256>>>(
                    split_down,
                    mixed_route_ptrs + 2u * n_expert,
                    midq,
                    hit_mask,
                    0u,
                    down_row_bytes,
                    midq_blocks,
                    out_dim);
                ok = cuda_ok(cudaGetLastError(), "routed_moe split miss down launch");
            }
            if (ok && use_split_fused) {
                dim3 fgrid((out_dim + 31u) / 32u, 1, 1);
                moe_down_split_fused_finish_qwarp32_kernel<<<fgrid, 256>>>(
                    (float *)out->ptr,
                    split_down,
                    mixed_route_ptrs + 2u * n_expert,
                    midq,
                    hit_mask,
                    down_row_bytes,
                    midq_blocks,
                    n_expert,
                    out_dim);
                ok = cuda_ok(cudaGetLastError(),
                             "routed_moe fused split finish launch");
            }
            if (ok && !use_split_fused) {
                moe_sum_kernel<<<(out_dim + 255u) / 256u, 256>>>(
                    (float *)out->ptr,
                    split_down,
                    out_dim,
                    n_expert,
                    1u);
                ok = cuda_ok(cudaGetLastError(), "routed_moe split sum launch");
            }
            return ok;
        }
        if (ok && use_sorted_pairs) {
            const uint64_t counts_bytes = 256ull * sizeof(uint32_t);
            const uint64_t offsets_bytes = 257ull * sizeof(uint32_t);
            const uint64_t cursors_bytes = 256ull * sizeof(uint32_t);
            const uint64_t sorted_bytes = (uint64_t)pair_count * sizeof(uint32_t);
            tile_capacity = (pair_count + expert_tile_m - 1u) / expert_tile_m + 256u;
            tile16_capacity = use_down_tile16 ? ((pair_count + 15u) / 16u + 256u) : 0u;
            const uint64_t tile_offsets_bytes = 257ull * sizeof(uint32_t);
            const uint64_t tile_total_bytes = sizeof(uint32_t);
            const uint64_t tile_experts_bytes = (uint64_t)tile_capacity * sizeof(uint32_t);
            const uint64_t tile_starts_bytes = (uint64_t)tile_capacity * sizeof(uint32_t);
            const uint64_t tile16_offsets_bytes = use_down_tile16 ? 257ull * sizeof(uint32_t) : 0u;
            const uint64_t tile16_total_bytes = use_down_tile16 ? sizeof(uint32_t) : 0u;
            const uint64_t tile16_experts_bytes = (uint64_t)tile16_capacity * sizeof(uint32_t);
            const uint64_t tile16_starts_bytes = (uint64_t)tile16_capacity * sizeof(uint32_t);
            const uint64_t tile_offsets_off = counts_bytes + offsets_bytes + cursors_bytes + sorted_bytes;
            const uint64_t tile_total_off = tile_offsets_off + tile_offsets_bytes;
            const uint64_t tile_experts_off = tile_total_off + tile_total_bytes;
            const uint64_t tile_starts_off = tile_experts_off + tile_experts_bytes;
            const uint64_t tile16_offsets_off = tile_starts_off + tile_starts_bytes;
            const uint64_t tile16_total_off = tile16_offsets_off + tile16_offsets_bytes;
            const uint64_t tile16_experts_off = tile16_total_off + tile16_total_bytes;
            const uint64_t tile16_starts_off = tile16_experts_off + tile16_experts_bytes;
            const uint64_t scratch_bytes = tile16_starts_off + tile16_starts_bytes;
            uint8_t *scratch = (uint8_t *)cuda_tmp_alloc(scratch_bytes,
                                                         "routed_moe sorted pairs");
            if (!scratch) {
                ok = 0;
            } else {
                uint32_t *counts = (uint32_t *)scratch;
                uint32_t *offsets = (uint32_t *)(scratch + counts_bytes);
                uint32_t *cursors = (uint32_t *)(scratch + counts_bytes + offsets_bytes);
                sorted_pairs = (uint32_t *)(scratch + counts_bytes + offsets_bytes + cursors_bytes);
                sorted_offsets = offsets;
                sorted_counts = counts;
                uint32_t *tile_offsets = (uint32_t *)(scratch + tile_offsets_off);
                tile_total = (uint32_t *)(scratch + tile_total_off);
                tile_experts = (uint32_t *)(scratch + tile_experts_off);
                tile_starts = (uint32_t *)(scratch + tile_starts_off);
                uint32_t *tile16_offsets = use_down_tile16 ? (uint32_t *)(scratch + tile16_offsets_off) : NULL;
                tile16_total = use_down_tile16 ? (uint32_t *)(scratch + tile16_total_off) : NULL;
                tile16_experts = use_down_tile16 ? (uint32_t *)(scratch + tile16_experts_off) : NULL;
                tile16_starts = use_down_tile16 ? (uint32_t *)(scratch + tile16_starts_off) : NULL;
                ok = cuda_ok(cudaMemset(counts, 0, counts_bytes), "routed_moe sorted counts clear");
                if (ok) {
                    moe_count_sorted_pairs_kernel<<<(pair_count + 255u) / 256u, 256>>>(
                        counts,
                        (const int32_t *)selected->ptr,
                        pair_count);
                    ok = cuda_ok(cudaGetLastError(), "routed_moe sorted count launch");
                }
                if (ok) {
                    moe_prefix_sorted_pairs_kernel<<<1, 1>>>(offsets, cursors, counts);
                    ok = cuda_ok(cudaGetLastError(), "routed_moe sorted prefix launch");
                }
                if (ok) {
                    moe_scatter_sorted_pairs_kernel<<<(pair_count + 255u) / 256u, 256>>>(
                        sorted_pairs,
                        cursors,
                        (const int32_t *)selected->ptr,
                        pair_count);
                    ok = cuda_ok(cudaGetLastError(), "routed_moe sorted scatter launch");
                }
                if (ok && use_expert_tiles) {
                    moe_build_expert_tile_offsets_kernel<<<1, 1>>>(tile_offsets, tile_total, counts, expert_tile_m);
                    ok = cuda_ok(cudaGetLastError(), "routed_moe expert tile offsets launch");
                }
                if (ok && use_expert_tiles) {
                    moe_build_expert_tiles_kernel<<<1, 256>>>(tile_experts, tile_starts, tile_offsets, counts, expert_tile_m);
                    ok = cuda_ok(cudaGetLastError(), "routed_moe expert tiles launch");
                }
                if (ok && use_expert_tiles && use_down_tile16) {
                    moe_build_expert_tile_offsets_kernel<<<1, 1>>>(tile16_offsets, tile16_total, counts, 16u);
                    ok = cuda_ok(cudaGetLastError(), "routed_moe expert tile16 offsets launch");
                }
                if (ok && use_expert_tiles && use_down_tile16) {
                    moe_build_expert_tiles_kernel<<<1, 256>>>(tile16_experts, tile16_starts, tile16_offsets, counts, 16u);
                    ok = cuda_ok(cudaGetLastError(), "routed_moe expert tile16 launch");
                }
            }
        }
        if (prof_ev[2]) (void)cudaEventRecord(prof_ev[2], 0);
        if (ok) {
            dim3 mgrid((expert_mid_dim + 31u) / 32u, n_tokens * n_expert, 1);
            if (ok && sorted_pairs && use_expert_tiles && sorted_offsets && sorted_counts && tile_total && tile_experts && tile_starts) {
                if (use_gate_row2048) {
                    if (gate_row_span == 512u) {
                        dim3 tgrid((expert_mid_dim + 511u) / 512u, tile_capacity, 1);
                        moe_gate_up_mid_expert_tile8_rowspan_kernel<512><<<tgrid, 256>>>(
                            (float *)gate->ptr, (float *)up->ptr, (float *)mid->ptr,
                            gate_w, up_w, xq, sorted_pairs, sorted_offsets, sorted_counts,
                            tile_total, tile_experts, tile_starts, (const float *)weights->ptr,
                            gate_expert_bytes, gate_row_bytes, xq_blocks, expert_mid_dim, n_expert,
                            write_gate_up, clamp);
                    } else if (gate_row_span == 1024u) {
                        dim3 tgrid((expert_mid_dim + 1023u) / 1024u, tile_capacity, 1);
                        moe_gate_up_mid_expert_tile8_rowspan_kernel<1024><<<tgrid, 256>>>(
                            (float *)gate->ptr, (float *)up->ptr, (float *)mid->ptr,
                            gate_w, up_w, xq, sorted_pairs, sorted_offsets, sorted_counts,
                            tile_total, tile_experts, tile_starts, (const float *)weights->ptr,
                            gate_expert_bytes, gate_row_bytes, xq_blocks, expert_mid_dim, n_expert,
                            write_gate_up, clamp);
                    } else {
                        dim3 tgrid((expert_mid_dim + 2047u) / 2048u, tile_capacity, 1);
                        moe_gate_up_mid_expert_tile8_row2048_kernel<<<tgrid, 256>>>(
                            (float *)gate->ptr, (float *)up->ptr, (float *)mid->ptr,
                            gate_w, up_w, xq, sorted_pairs, sorted_offsets, sorted_counts,
                            tile_total, tile_experts, tile_starts, (const float *)weights->ptr,
                            gate_expert_bytes, gate_row_bytes, xq_blocks, expert_mid_dim, n_expert,
                            write_gate_up, clamp);
                    }
                } else if (expert_tile_m == 8u) {
                    dim3 tgrid((expert_mid_dim + 31u) / 32u, tile_capacity, 1);
                    moe_gate_up_mid_expert_tile8_row32_kernel<<<tgrid, 256>>>(
                        (float *)gate->ptr, (float *)up->ptr, (float *)mid->ptr,
                        gate_w, up_w, xq, sorted_pairs, sorted_offsets, sorted_counts,
                        tile_total, tile_experts, tile_starts, (const float *)weights->ptr,
                        gate_expert_bytes, gate_row_bytes, xq_blocks, expert_mid_dim, n_expert,
                        write_gate_up, clamp);
                } else {
                    dim3 tgrid((expert_mid_dim + 31u) / 32u, tile_capacity, 1);
                    moe_gate_up_mid_expert_tile4_row32_kernel<<<tgrid, 256>>>(
                        (float *)gate->ptr, (float *)up->ptr, (float *)mid->ptr,
                        gate_w, up_w, xq, sorted_pairs, sorted_offsets, sorted_counts,
                        tile_total, tile_experts, tile_starts, (const float *)weights->ptr,
                        gate_expert_bytes, gate_row_bytes, xq_blocks, expert_mid_dim, n_expert,
                        write_gate_up, clamp);
                }
            } else if (ok && sorted_pairs && use_p2_sorted) {
                dim3 p2_mgrid((expert_mid_dim + 15u) / 16u, (pair_count + 1u) / 2u, 1);
                moe_gate_up_mid_sorted_p2_qwarp32_kernel<<<p2_mgrid, 256>>>(
                    (float *)gate->ptr,
                    (float *)up->ptr,
                    (float *)mid->ptr,
                    gate_w,
                    up_w,
                    xq,
                    sorted_pairs,
                    (const int32_t *)selected->ptr,
                    (const float *)weights->ptr,
                    gate_expert_bytes,
                    gate_row_bytes,
                    xq_blocks,
                    expert_mid_dim,
                    n_expert,
                    pair_count,
                    clamp);
            } else if (ok && sorted_pairs) {
                moe_gate_up_mid_sorted_qwarp32_kernel<<<mgrid, 256>>>(
                    (float *)gate->ptr,
                    (float *)up->ptr,
                    (float *)mid->ptr,
                    gate_w,
                    up_w,
                    xq,
                    sorted_pairs,
                    (const int32_t *)selected->ptr,
                    (const float *)weights->ptr,
                    gate_expert_bytes,
                    gate_row_bytes,
                    xq_blocks,
                    expert_mid_dim,
                    n_expert,
                    clamp);
            } else if (ok) {
                dim3 qgrid((expert_mid_dim + 127u) / 128u, n_tokens * n_expert, 1);
                if (use_mixed_route_ptrs) {
                    moe_gate_up_mid_decode_ptrs_lut_qwarp32_kernel<<<qgrid, 256>>>(
                        (float *)gate->ptr,
                        (float *)up->ptr,
                        (float *)mid->ptr,
                        mixed_route_ptrs,
                        xq,
                        (const float *)weights->ptr,
                        gate_row_bytes,
                        xq_blocks,
                        expert_mid_dim,
                        n_expert,
                        write_gate_up,
                        clamp,
                        NULL,
                        0u);
                } else if (use_decode_lut_gate) {
                    moe_gate_up_mid_decode_lut_qwarp32_kernel<<<qgrid, 256>>>(
                        (float *)gate->ptr,
                        (float *)up->ptr,
                        (float *)mid->ptr,
                        gate_w,
                        up_w,
                        xq,
                        (const int32_t *)selected->ptr,
                        (const float *)weights->ptr,
                        gate_expert_bytes,
                        gate_row_bytes,
                        xq_blocks,
                        expert_mid_dim,
                        n_expert,
                        write_gate_up,
                        clamp);
                } else {
                    moe_gate_up_mid_qwarp32_kernel<<<qgrid, 256>>>(
                        (float *)gate->ptr,
                        (float *)up->ptr,
                        (float *)mid->ptr,
                        gate_w,
                        up_w,
                        xq,
                        (const int32_t *)selected->ptr,
                        (const float *)weights->ptr,
                        gate_expert_bytes,
                        gate_row_bytes,
                        xq_blocks,
                        expert_mid_dim,
                        n_expert,
                        clamp);
                }
            }
            ok = cuda_ok(cudaGetLastError(), "routed_moe gate/up launch");
            if (ok && getenv("DS4_IQ1_MIXED_DEBUG") &&
                use_mixed_route_ptrs && n_expert != CUDA_MOE_ROUTE_COUNT) {
                ds4_gpu_tensor debug_mid = {
                    mid->ptr,
                    (uint64_t)n_expert * expert_mid_dim * sizeof(float),
                    0
                };
                ok = cuda_iq1_mixed_debug_output(
                    "hot-mid", &debug_mid, n_expert * expert_mid_dim);
            }
        }
        if (prof_ev[3]) (void)cudaEventRecord(prof_ev[3], 0);
        if (ok) {
            dim3 midq_grid(midq_blocks, n_tokens * n_expert, 1);
            q8_K_quantize_kernel<<<midq_grid, 256>>>(
                midq, (const float *)mid->ptr, expert_mid_dim,
                n_tokens * n_expert, NULL, 0u, 0u);
            ok = cuda_ok(cudaGetLastError(), "routed_moe mid quantize launch");
        }
        if (prof_ev[4]) (void)cudaEventRecord(prof_ev[4], 0);
        if (ok) {
            dim3 dgrid((out_dim + 31u) / 32u, n_tokens * n_expert, 1);
            uint32_t *down_tile_total = tile_total;
            uint32_t *down_tile_experts = tile_experts;
            uint32_t *down_tile_starts = tile_starts;
            uint32_t down_tile_capacity = tile_capacity;
            if (use_down_tile16 && tile16_total && tile16_experts && tile16_starts) {
                down_tile_total = tile16_total;
                down_tile_experts = tile16_experts;
                down_tile_starts = tile16_starts;
                down_tile_capacity = tile16_capacity;
            }
            if (use_mixed_route_ptrs) {
                dim3 sgrid((out_dim + 31u) / 32u, 1, 1);
                moe_down_sum_ptrs_qwarp32_kernel<<<sgrid, 256>>>(
                    (float *)out->ptr,
                    mixed_route_ptrs + 2u * n_expert,
                    midq,
                    down_row_bytes,
                    midq_blocks,
                    out_dim,
                    n_expert);
            } else if (use_direct_down_sum6) {
                dim3 sgrid((out_dim + 31u) / 32u, 1, 1);
                moe_down_sum6_qwarp32_kernel<<<sgrid, 256>>>(
                    (float *)out->ptr,
                    down_w,
                    midq,
                    (const int32_t *)selected->ptr,
                    down_expert_bytes,
                    down_row_bytes,
                    midq_blocks,
                    out_dim);
            } else if (use_atomic_down) {
                uint64_t n = (uint64_t)n_tokens * out_dim;
                zero_kernel<<<(n + 255u) / 256u, 256>>>((float *)out->ptr, n);
                ok = cuda_ok(cudaGetLastError(), "routed_moe atomic zero launch");
            }
            if (use_mixed_route_ptrs || use_direct_down_sum6) {
                /* The direct decode kernel writes the final token row. */
            } else if (sorted_pairs && use_expert_tiles && sorted_offsets && sorted_counts &&
                down_tile_total && down_tile_experts && down_tile_starts) {
                if (use_down_row2048) {
                    if (down_row_span == 512u) {
                        dim3 tgrid((out_dim + 511u) / 512u, down_tile_capacity, 1);
                        if (use_down_block16) {
                            moe_down_expert_tile16_rowspan_block16_kernel<512><<<tgrid, 256>>>(
                                use_atomic_down ? (float *)out->ptr : (float *)down->ptr,
                                down_w, midq, sorted_pairs, sorted_offsets, sorted_counts,
                                down_tile_total, down_tile_experts, down_tile_starts, down_expert_bytes, down_row_bytes,
                                midq_blocks, out_dim, n_expert, use_atomic_down);
                        } else {
                            moe_down_expert_tile16_rowspan_kernel<512><<<tgrid, 256>>>(
                                use_atomic_down ? (float *)out->ptr : (float *)down->ptr,
                                down_w, midq, sorted_pairs, sorted_offsets, sorted_counts,
                                down_tile_total, down_tile_experts, down_tile_starts, down_expert_bytes, down_row_bytes,
                                midq_blocks, out_dim, n_expert, use_atomic_down);
                        }
                    } else if (down_row_span == 1024u) {
                        dim3 tgrid((out_dim + 1023u) / 1024u, down_tile_capacity, 1);
                        if (use_down_block16) {
                            moe_down_expert_tile16_rowspan_block16_kernel<1024><<<tgrid, 256>>>(
                                use_atomic_down ? (float *)out->ptr : (float *)down->ptr,
                                down_w, midq, sorted_pairs, sorted_offsets, sorted_counts,
                                down_tile_total, down_tile_experts, down_tile_starts, down_expert_bytes, down_row_bytes,
                                midq_blocks, out_dim, n_expert, use_atomic_down);
                        } else {
                            moe_down_expert_tile16_rowspan_kernel<1024><<<tgrid, 256>>>(
                                use_atomic_down ? (float *)out->ptr : (float *)down->ptr,
                                down_w, midq, sorted_pairs, sorted_offsets, sorted_counts,
                                down_tile_total, down_tile_experts, down_tile_starts, down_expert_bytes, down_row_bytes,
                                midq_blocks, out_dim, n_expert, use_atomic_down);
                        }
                    } else {
                        dim3 tgrid((out_dim + 2047u) / 2048u, down_tile_capacity, 1);
                        if (use_down_block16) {
                            moe_down_expert_tile16_rowspan_block16_kernel<2048><<<tgrid, 256>>>(
                                use_atomic_down ? (float *)out->ptr : (float *)down->ptr,
                                down_w, midq, sorted_pairs, sorted_offsets, sorted_counts,
                                down_tile_total, down_tile_experts, down_tile_starts, down_expert_bytes, down_row_bytes,
                                midq_blocks, out_dim, n_expert, use_atomic_down);
                        } else {
                            moe_down_expert_tile16_row2048_kernel<<<tgrid, 256>>>(
                                use_atomic_down ? (float *)out->ptr : (float *)down->ptr,
                                down_w, midq, sorted_pairs, sorted_offsets, sorted_counts,
                                down_tile_total, down_tile_experts, down_tile_starts, down_expert_bytes, down_row_bytes,
                                midq_blocks, out_dim, n_expert, use_atomic_down);
                        }
                    }
                } else if (use_down_tile16) {
                    dim3 tgrid((out_dim + 31u) / 32u, down_tile_capacity, 1);
                    moe_down_expert_tile16_row32_kernel<<<tgrid, 256>>>(
                        use_atomic_down ? (float *)out->ptr : (float *)down->ptr,
                        down_w, midq, sorted_pairs, sorted_offsets, sorted_counts,
                        down_tile_total, down_tile_experts, down_tile_starts, down_expert_bytes, down_row_bytes,
                        midq_blocks, out_dim, n_expert, use_atomic_down);
                } else if (expert_tile_m == 8u) {
                    dim3 tgrid((out_dim + 31u) / 32u, down_tile_capacity, 1);
                    moe_down_expert_tile8_row32_kernel<<<tgrid, 256>>>(
                        use_atomic_down ? (float *)out->ptr : (float *)down->ptr,
                        down_w, midq, sorted_pairs, sorted_offsets, sorted_counts,
                        down_tile_total, down_tile_experts, down_tile_starts, down_expert_bytes, down_row_bytes,
                        midq_blocks, out_dim, n_expert, use_atomic_down);
                } else {
                    dim3 tgrid((out_dim + 31u) / 32u, down_tile_capacity, 1);
                    moe_down_expert_tile4_row32_kernel<<<tgrid, 256>>>(
                        use_atomic_down ? (float *)out->ptr : (float *)down->ptr,
                        down_w, midq, sorted_pairs, sorted_offsets, sorted_counts,
                        down_tile_total, down_tile_experts, down_tile_starts, down_expert_bytes, down_row_bytes,
                        midq_blocks, out_dim, n_expert, use_atomic_down);
                }
            } else if (sorted_pairs && use_p2_sorted) {
                dim3 p2_dgrid((out_dim + 15u) / 16u, (pair_count + 1u) / 2u, 1);
                moe_down_sorted_p2_qwarp32_kernel<<<p2_dgrid, 256>>>(
                    (float *)down->ptr,
                    down_w,
                    midq,
                    sorted_pairs,
                    (const int32_t *)selected->ptr,
                    down_expert_bytes,
                    down_row_bytes,
                    midq_blocks,
                    out_dim,
                    n_expert,
                    pair_count);
            } else if (sorted_pairs) {
                moe_down_sorted_qwarp32_kernel<<<dgrid, 256>>>(
                    (float *)down->ptr,
                    down_w,
                    midq,
                    sorted_pairs,
                    (const int32_t *)selected->ptr,
                    down_expert_bytes,
                    down_row_bytes,
                    midq_blocks,
                    out_dim,
                    n_expert);
            } else {
                moe_down_qwarp32_kernel<<<dgrid, 256>>>(
                    (float *)down->ptr,
                    down_w,
                    midq,
                    (const int32_t *)selected->ptr,
                    down_expert_bytes,
                    down_row_bytes,
                    midq_blocks,
                    out_dim,
                    n_expert);
            }
            ok = cuda_ok(cudaGetLastError(), "routed_moe down launch");
        }
        if (prof_ev[5]) (void)cudaEventRecord(prof_ev[5], 0);
        if (ok && !use_atomic_down && !use_direct_down_sum6 &&
            !use_mixed_route_ptrs) {
            uint64_t n = (uint64_t)n_tokens * out_dim;
            moe_sum_kernel<<<(n + 255) / 256, 256>>>((float *)out->ptr, (const float *)down->ptr, out_dim, n_expert, n_tokens);
            ok = cuda_ok(cudaGetLastError(), "routed_moe sum launch");
        }
        if (prof_ev[6]) {
            (void)cudaEventRecord(prof_ev[6], 0);
            if (cudaEventSynchronize(prof_ev[6]) == cudaSuccess) {
                float ms_xq = 0.0f, ms_sort = 0.0f, ms_gate = 0.0f, ms_midq = 0.0f, ms_down = 0.0f, ms_sum = 0.0f, ms_total = 0.0f;
                (void)cudaEventElapsedTime(&ms_xq, prof_ev[0], prof_ev[1]);
                (void)cudaEventElapsedTime(&ms_sort, prof_ev[1], prof_ev[2]);
                (void)cudaEventElapsedTime(&ms_gate, prof_ev[2], prof_ev[3]);
                (void)cudaEventElapsedTime(&ms_midq, prof_ev[3], prof_ev[4]);
                (void)cudaEventElapsedTime(&ms_down, prof_ev[4], prof_ev[5]);
                (void)cudaEventElapsedTime(&ms_sum, prof_ev[5], prof_ev[6]);
                (void)cudaEventElapsedTime(&ms_total, prof_ev[0], prof_ev[6]);
                fprintf(stderr,
                        "ds4: CUDA MoE profile tokens=%u pairs=%u xq=%.3f sort=%.3f gateup=%.3f midq=%.3f down=%.3f sum=%.3f total=%.3f ms\n",
                        n_tokens, pair_count, ms_xq, ms_sort, ms_gate, ms_midq, ms_down, ms_sum, ms_total);
            }
            for (uint32_t i = 0; i < 7u; i++) (void)cudaEventDestroy(prof_ev[i]);
        }
        return ok;
    }

    if (g_moe_gather.wave_active) return 0;

    if (ok) {
        dim3 mgrid(expert_mid_dim, n_tokens * n_expert, 1);
        moe_gate_up_mid_f32_kernel<<<mgrid, 256>>>(
            (float *)gate->ptr,
            (float *)up->ptr,
            (float *)mid->ptr,
            gate_w,
            up_w,
            (const float *)x->ptr,
            (const int32_t *)selected->ptr,
            (const float *)weights->ptr,
            gate_expert_bytes,
            gate_row_bytes,
            expert_in_dim,
            expert_mid_dim,
            n_expert,
            clamp);
        ok = cuda_ok(cudaGetLastError(), "routed_moe gate/up launch");
    }
    if (ok) {
        dim3 dgrid(out_dim, n_tokens * n_expert, 1);
        moe_down_f32_kernel<<<dgrid, 256>>>(
            (float *)down->ptr,
            down_w,
            (const float *)mid->ptr,
            (const int32_t *)selected->ptr,
            down_expert_bytes,
            down_row_bytes,
            expert_mid_dim,
            out_dim,
            n_expert);
        ok = cuda_ok(cudaGetLastError(), "routed_moe down launch");
    }
    if (ok) {
        uint64_t n = (uint64_t)n_tokens * out_dim;
        moe_sum_kernel<<<(n + 255) / 256, 256>>>((float *)out->ptr, (const float *)down->ptr, out_dim, n_expert, n_tokens);
        ok = cuda_ok(cudaGetLastError(), "routed_moe sum launch");
    }
    return ok;
}

extern "C" int ds4_gpu_routed_moe_one_tensor(ds4_gpu_tensor *out, ds4_gpu_tensor *gate, ds4_gpu_tensor *up, ds4_gpu_tensor *mid, ds4_gpu_tensor *down, const void *model_map, uint64_t model_size, uint32_t layer_index, uint64_t gate_offset, uint64_t up_offset, uint64_t down_offset, uint32_t gate_type, uint32_t down_type, uint64_t gate_expert_bytes, uint64_t gate_row_bytes, uint64_t down_expert_bytes, uint64_t down_row_bytes, uint32_t expert_in_dim, uint32_t expert_mid_dim, uint32_t out_dim, const ds4_gpu_tensor *selected, const ds4_gpu_tensor *weights, uint32_t n_expert, float clamp, const ds4_gpu_tensor *x, ds4_gpu_spex_queue *spex_queue, const ds4_gpu_spex_key *spex_key) {
    return routed_moe_launch(out, gate, up, mid, down, model_map, model_size,
                             layer_index,
                             gate_offset, up_offset, down_offset,
                             gate_type, down_type,
                             gate_expert_bytes, gate_row_bytes,
                             down_expert_bytes, down_row_bytes,
                             expert_in_dim, expert_mid_dim, out_dim,
                             selected, weights, NULL, n_expert, clamp, x, 1,
                             spex_queue, spex_key);
}

static int cuda_iq1_mixed_scratch_ensure(uint64_t bytes) {
    if (bytes == 0) return 0;
    if (g_iq1_mixed_scratch && g_iq1_mixed_scratch_bytes >= bytes) return 1;
    if (g_iq1_mixed_scratch) {
        (void)cudaFree(g_iq1_mixed_scratch);
        g_iq1_mixed_scratch = NULL;
        g_iq1_mixed_scratch_bytes = 0;
    }
    cudaError_t err = cudaMalloc(&g_iq1_mixed_scratch, (size_t)bytes);
    if (err != cudaSuccess) {
        fprintf(stderr,
                "ds4: CUDA IQ1 mixed scratch alloc failed (%.2f MiB): %s\n",
                (double)bytes / 1048576.0, cudaGetErrorString(err));
        (void)cudaGetLastError();
        return 0;
    }
    g_iq1_mixed_scratch_bytes = bytes;
    return 1;
}

static int cuda_iq1_mixed_gpu_plan_prepare(void) {
    cuda_iq1_mixed_gpu_plan &plan = g_iq1_mixed_gpu_plan;
    if (plan.host_request && plan.device_request) return 1;
    cuda_iq1_mixed_gpu_plan_release();
    cudaError_t err = cudaHostAlloc(
        (void **)&plan.host_request, sizeof(*plan.host_request),
        cudaHostAllocMapped);
    if (err == cudaSuccess) {
        err = cudaHostGetDevicePointer(
            (void **)&plan.device_request, plan.host_request, 0);
    }
    if (err != cudaSuccess) {
        fprintf(stderr,
                "ds4: IQ1 mixed GPU planner allocation failed: %s\n",
                cudaGetErrorString(err));
        (void)cudaGetLastError();
        cuda_iq1_mixed_gpu_plan_release();
        return 0;
    }
    memset(plan.host_request, 0, sizeof(*plan.host_request));
    fprintf(stderr,
            "ds4: [iq1-mixed-gpu-plan] result=ready "
            "mode=cold-one-upload-overlap\n");
    return 1;
}

static void cuda_iq1_mixed_gpu_plan_release(void) {
    cuda_iq1_mixed_gpu_plan &plan = g_iq1_mixed_gpu_plan;
    if (plan.host_request) (void)cudaFreeHost(plan.host_request);
    memset(&plan, 0, sizeof(plan));
}

static int cuda_iq1_mixed_debug_output(
        const char *phase,
        const ds4_gpu_tensor *tensor,
        uint32_t count) {
    if (!getenv("DS4_IQ1_MIXED_DEBUG")) return 1;
    if (!tensor || !tensor->ptr || tensor->bytes < (uint64_t)count * sizeof(float)) {
        fprintf(stderr, "ds4: [iq1-mixed-debug] phase=%s result=invalid-tensor\n",
                phase ? phase : "unknown");
        return 0;
    }
    if (!cuda_ok(cudaStreamSynchronize(0), "iq1 mixed debug sync")) return 0;
    std::vector<float> values(count);
    if (!cuda_ok(cudaMemcpy(values.data(), tensor->ptr,
                            (size_t)count * sizeof(float),
                            cudaMemcpyDeviceToHost),
                 "iq1 mixed debug D2H")) {
        return 0;
    }
    uint32_t nonfinite = 0;
    double sum_abs = 0.0;
    double sum_sq = 0.0;
    float min_value = INFINITY;
    float max_value = -INFINITY;
    for (float value : values) {
        if (!std::isfinite(value)) {
            nonfinite++;
            continue;
        }
        min_value = std::min(min_value, value);
        max_value = std::max(max_value, value);
        sum_abs += fabs((double)value);
        sum_sq += (double)value * (double)value;
    }
    const uint32_t finite = count - nonfinite;
    fprintf(stderr,
            "ds4: [iq1-mixed-debug] phase=%s count=%u nonfinite=%u "
            "min=%.9g max=%.9g mean_abs=%.9g rms=%.9g\n",
            phase ? phase : "unknown", count, nonfinite,
            finite ? min_value : 0.0f, finite ? max_value : 0.0f,
            finite ? sum_abs / (double)finite : 0.0,
            finite ? sqrt(sum_sq / (double)finite) : 0.0);
    return nonfinite == 0u;
}

enum cuda_q1_0_mixed_representation : uint8_t {
    CUDA_Q1_0_MIXED_UNKNOWN = 0,
    CUDA_Q1_0_MIXED_IQ2_VRAM = 1,
    CUDA_Q1_0_MIXED_IQ2_SNAPSHOT_RAM = 2,
    CUDA_Q1_0_MIXED_IQ2_TIER_RAM = 3,
    CUDA_Q1_0_MIXED_Q1_RESIDENT = 4,
};

static const char *cuda_q1_0_mixed_representation_name(
        cuda_q1_0_mixed_representation representation) {
    switch (representation) {
    case CUDA_Q1_0_MIXED_IQ2_VRAM: return "iq2_vram";
    case CUDA_Q1_0_MIXED_IQ2_SNAPSHOT_RAM: return "iq2_snapshot_ram";
    case CUDA_Q1_0_MIXED_IQ2_TIER_RAM: return "iq2_tier_ram";
    case CUDA_Q1_0_MIXED_Q1_RESIDENT: return "q1_resident";
    default: return "unknown";
    }
}

static int cuda_q1_0_mixed_trace_requested(void) {
    const char *value = getenv("DS4_Q1_0_MIXED_TRACE");
    return value && strcmp(value, "1") == 0;
}

static int cuda_q1_0_resident_ram_ptrs(
        uint32_t layer, uint32_t expert,
        char **gate, char **up, char **down) {
    cuda_dynamic_arena *arena_ptr = cuda_q1_0_route_arena(layer);
    if (!arena_ptr || expert >= 256u ||
        !gate || !up || !down || layer >= arena_ptr->n_layer ||
        expert >= arena_ptr->n_expert ||
        arena_ptr->layers.size() != arena_ptr->n_layer) {
        return 0;
    }
    cuda_dynamic_arena &arena = *arena_ptr;
    const uint32_t entry = layer * arena.n_expert + expert;
    if (entry >= arena.active.size()) return 0;
    const cuda_dynamic_arena_binding &binding = arena.active[entry];
    if (!cuda_dynamic_arena_binding_valid(
            arena, binding, layer, expert,
            arena.snapshot_generation, DS4_GPU_ARENA_READY)) {
        return 0;
    }
    const ds4_gpu_dynamic_arena_layer &geometry = arena.layers[layer];
    cuda_dynamic_arena_slot &slot = arena.slots[binding.slot];
    *gate = slot.host_ptr;
    *up = *gate + geometry.gate_expert_bytes;
    *down = *up + geometry.up_expert_bytes;
    return 1;
}

static int cuda_q1_0_dual_sparse_pair_contains(
        uint32_t layer, uint32_t expert) {
    cuda_dynamic_arena &primary = g_dynamic_arena;
    cuda_dynamic_arena &q1 = g_q1_0_dynamic_arena;
    if (!cuda_q1_0_dual_sparse_companion_requested() ||
        !g_q1_0_dual_sparse_snapshot.ready ||
        g_q1_0_dual_sparse_snapshot.staged ||
        primary.backing != CUDA_DYNAMIC_ARENA_BACKING_PRIMARY ||
        q1.backing != CUDA_DYNAMIC_ARENA_BACKING_Q1_0 ||
        primary.snapshot_generation == 0 ||
        q1.snapshot_generation != primary.snapshot_generation ||
        g_q1_0_dual_sparse_snapshot.primary_generation !=
            primary.snapshot_generation ||
        g_q1_0_dual_sparse_snapshot.q1_generation !=
            q1.snapshot_generation ||
        layer >= primary.n_layer || layer >= q1.n_layer ||
        expert >= primary.n_expert || expert >= q1.n_expert ||
        primary.n_layer != q1.n_layer ||
        primary.n_expert != q1.n_expert) {
        return 0;
    }
    const uint32_t entry = layer * primary.n_expert + expert;
    if (entry >= primary.active.size() || entry >= q1.active.size()) {
        return 0;
    }
    return cuda_dynamic_arena_binding_valid(
               primary, primary.active[entry], layer, expert,
               primary.snapshot_generation, DS4_GPU_ARENA_READY) &&
        cuda_dynamic_arena_binding_valid(
               q1, q1.active[entry], layer, expert,
               q1.snapshot_generation, DS4_GPU_ARENA_READY);
}

static cuda_q1_0_mixed_representation cuda_q1_0_mixed_resolve(
        uint32_t layer, uint32_t expert) {
    cuda_q1_0_mixed_capture_router_mode();
    if (cuda_q1_0_snapshot_backing_requested()) {
        /* The exclusive snapshot physically contains Q1_0 bytes. The only
         * exact IQ2 representation in this mode is the protected VRAM seed;
         * generic snapshot/tier RAM pointers would alias Q1_0 slots and must
         * never be interpreted as IQ2. */
        if (cuda_moe_tiering_has_exact_vram(layer, expert)) {
            return CUDA_Q1_0_MIXED_IQ2_VRAM;
        }
        char *gate = NULL;
        char *up = NULL;
        char *down = NULL;
        return cuda_q1_0_resident_ram_ptrs(
                    layer, expert, &gate, &up, &down)
            ? CUDA_Q1_0_MIXED_Q1_RESIDENT
            : CUDA_Q1_0_MIXED_UNKNOWN;
    }
    if (g_moe_tiering.mode != CUDA_MOE_TIER_ENFORCE ||
        !g_moe_tiering.compose_prefill_mass_tiering ||
        !g_moe_tiering.compose_router_open ||
        layer >= CUDA_MOE_LAYER_COUNT || expert >= 256u ||
        g_moe_tiering.entries.size() !=
            (size_t)CUDA_MOE_LAYER_COUNT * 256u) {
        return CUDA_Q1_0_MIXED_UNKNOWN;
    }
    const cuda_moe_tier_entry &tier = g_moe_tiering.entries[
        cuda_moe_tiering_entry_index(layer, expert)];
    if (cuda_moe_tiering_has_exact_vram(layer, expert)) {
        return tier.state == CUDA_MOE_TIER_VRAM_PROTECTED
            ? CUDA_Q1_0_MIXED_IQ2_VRAM
            : CUDA_Q1_0_MIXED_UNKNOWN;
    }
    char *gate = NULL;
    char *up = NULL;
    char *down = NULL;
    if (cuda_moe_tiering_snapshot_ram_ptrs(
            layer, expert, &gate, &up, &down)) {
        return tier.state == CUDA_MOE_TIER_RAM_PROBATION ||
               tier.state == CUDA_MOE_TIER_RAM_WARM
            ? CUDA_Q1_0_MIXED_IQ2_SNAPSHOT_RAM
            : CUDA_Q1_0_MIXED_UNKNOWN;
    }
    if (cuda_moe_tiering_ram_ptrs(
            layer, expert, &gate, &up, &down)) {
        return tier.state == CUDA_MOE_TIER_RAM_PROBATION ||
               tier.state == CUDA_MOE_TIER_RAM_WARM
            ? CUDA_Q1_0_MIXED_IQ2_TIER_RAM
            : CUDA_Q1_0_MIXED_UNKNOWN;
    }
    if (tier.state != CUDA_MOE_TIER_SSD_COLD || tier.has_2bit_ram) {
        return CUDA_Q1_0_MIXED_UNKNOWN;
    }
    if (cuda_q1_0_resident_ram_ptrs(
            layer, expert, &gate, &up, &down)) {
        return CUDA_Q1_0_MIXED_Q1_RESIDENT;
    }
    return CUDA_Q1_0_MIXED_UNKNOWN;
}

extern "C" int ds4_gpu_routed_moe_mixed_q1_0_one_tensor(
        ds4_gpu_tensor *out,
        ds4_gpu_tensor *gate,
        ds4_gpu_tensor *up,
        ds4_gpu_tensor *mid,
        ds4_gpu_tensor *down,
        const void *main_model_map,
        uint64_t main_model_size,
        uint32_t layer_index,
        uint64_t main_gate_offset,
        uint64_t main_up_offset,
        uint64_t main_down_offset,
        uint32_t main_gate_type,
        uint32_t main_down_type,
        uint64_t main_gate_expert_bytes,
        uint64_t main_gate_row_bytes,
        uint64_t main_down_expert_bytes,
        uint64_t main_down_row_bytes,
        const void *q1_model_map,
        uint64_t q1_model_size,
        uint64_t q1_gate_offset,
        uint64_t q1_up_offset,
        uint64_t q1_down_offset,
        uint64_t q1_gate_expert_bytes,
        uint64_t q1_gate_row_bytes,
        uint64_t q1_down_expert_bytes,
        uint64_t q1_down_row_bytes,
        uint32_t expert_in_dim,
        uint32_t expert_mid_dim,
        uint32_t out_dim,
        const ds4_gpu_tensor *selected,
        const ds4_gpu_tensor *weights,
        uint32_t n_expert,
        float clamp,
        const ds4_gpu_tensor *x) {
    g_q1_0_mixed_calls++;
    if (!out || !gate || !up || !mid || !down || !main_model_map ||
        !q1_model_map || !selected || !weights || !x ||
        n_expert == 0u || n_expert > CUDA_MOE_ROUTE_COUNT ||
        main_gate_type != 16u || main_down_type != 10u ||
        main_model_map != g_model_host_base ||
        main_model_size != g_model_registered_size ||
        q1_model_map != g_q1_0_sidecar_host_base ||
        q1_model_size != g_q1_0_sidecar_size ||
        !cuda_q1_0_route_arena(layer_index) ||
        selected->bytes < (uint64_t)n_expert * sizeof(int32_t) ||
        weights->bytes < (uint64_t)n_expert * sizeof(float) ||
        out->bytes < (uint64_t)out_dim * sizeof(float)) {
        fprintf(stderr,
                "ds4: [q1-0-mixed] result=failed reason=entry-contract "
                "layer=%u routes=%u main_type=%u/%u main_map=%u "
                "main_size=%llu registered_size=%llu q1_map=%u "
                "q1_size=%llu sidecar_size=%llu q1_arena=%u "
                "tier_entries=%llu selected_bytes=%llu weights_bytes=%llu "
                "out_bytes=%llu required_out=%llu\n",
                layer_index, n_expert, main_gate_type, main_down_type,
                main_model_map == g_model_host_base,
                (unsigned long long)main_model_size,
                (unsigned long long)g_model_registered_size,
                q1_model_map == g_q1_0_sidecar_host_base,
                (unsigned long long)q1_model_size,
                (unsigned long long)g_q1_0_sidecar_size,
                cuda_q1_0_route_arena(layer_index) != NULL,
                (unsigned long long)g_moe_tiering.entries.size(),
                (unsigned long long)(selected ? selected->bytes : 0),
                (unsigned long long)(weights ? weights->bytes : 0),
                (unsigned long long)(out ? out->bytes : 0),
                (unsigned long long)out_dim * sizeof(float));
        g_q1_0_mixed_failures++;
        return 0;
    }
    cuda_dynamic_arena *q1_arena = cuda_q1_0_route_arena(layer_index);
    if (!q1_arena) {
        fprintf(stderr,
                "ds4: [q1-0-mixed] result=failed reason=q1-arena-null "
                "layer=%u\n", layer_index);
        g_q1_0_mixed_failures++;
        return 0;
    }
    const ds4_gpu_dynamic_arena_layer &q1_geometry =
        q1_arena->layers[layer_index];
    if (q1_geometry.gate_offset != q1_gate_offset ||
        q1_geometry.up_offset != q1_up_offset ||
        q1_geometry.down_offset != q1_down_offset ||
        q1_geometry.gate_expert_bytes != q1_gate_expert_bytes ||
        q1_geometry.up_expert_bytes != q1_gate_expert_bytes ||
        q1_geometry.down_expert_bytes != q1_down_expert_bytes) {
        fprintf(stderr,
                "ds4: [q1-0-mixed] result=failed reason=q1-geometry "
                "layer=%u gate_offset=%llu/%llu up_offset=%llu/%llu "
                "down_offset=%llu/%llu gate_bytes=%llu/%llu "
                "up_bytes=%llu/%llu down_bytes=%llu/%llu\n",
                layer_index,
                (unsigned long long)q1_geometry.gate_offset,
                (unsigned long long)q1_gate_offset,
                (unsigned long long)q1_geometry.up_offset,
                (unsigned long long)q1_up_offset,
                (unsigned long long)q1_geometry.down_offset,
                (unsigned long long)q1_down_offset,
                (unsigned long long)q1_geometry.gate_expert_bytes,
                (unsigned long long)q1_gate_expert_bytes,
                (unsigned long long)q1_geometry.up_expert_bytes,
                (unsigned long long)q1_gate_expert_bytes,
                (unsigned long long)q1_geometry.down_expert_bytes,
                (unsigned long long)q1_down_expert_bytes);
        g_q1_0_mixed_failures++;
        return 0;
    }
    if (!cuda_q1_0_ssd_wrap_poll()) {
        fprintf(stderr,
                "ds4: [q1-0-mixed] result=failed "
                "reason=ssd-wrap-terminal layer=%u\n", layer_index);
        g_q1_0_mixed_failures++;
        return 0;
    }

    /* The Q1 fallback path still needs the exact-IQ2 resolver: it decides
     * whether each full/open route is already resident as IQ2 or must use Q1
     * for this token. Promotion only controls later RAM-probation mutation. */
    const int q1_0_dynamic_promotion =
        cuda_q1_0_dynamic_promotion_requested();
    const int q1_0_mixed_exact_iq2_resolver =
        cuda_q1_0_mixed_exact_iq2_resolver_requested();
    if (q1_0_mixed_exact_iq2_resolver &&
        cuda_moe_gpu_routes_requested()) {
        cuda_moe_expert_cache *cache = cuda_moe_expert_cache_prepare(
            main_gate_expert_bytes, main_down_expert_bytes);
        if (!cache || !cache->route_thread_started ||
            !cache->route_worker_ready || cache->route_worker_failed ||
            cache->route_stop) {
            fprintf(stderr,
                    "ds4: [q1-0-mixed] result=failed "
                    "reason=iq2-vram-cache-not-ready layer=%u\n",
                    layer_index);
            g_q1_0_mixed_failures++;
            return 0;
        }
    }
    if (q1_0_mixed_exact_iq2_resolver &&
        !cuda_q1_0_snapshot_backing_requested() &&
        !cuda_q1_0_dual_sparse_companion_requested() &&
        g_moe_tiering.entries.size() !=
            (size_t)CUDA_MOE_LAYER_COUNT * 256u) {
        fprintf(stderr,
                "ds4: [q1-0-mixed] result=failed reason=entry-contract "
                "layer=%u routes=%u main_type=%u/%u main_map=%u "
                "main_size=%llu registered_size=%llu q1_map=%u "
                "q1_size=%llu sidecar_size=%llu q1_arena=%u "
                "tier_entries=%llu selected_bytes=%llu weights_bytes=%llu "
                "out_bytes=%llu required_out=%llu\n",
                layer_index, n_expert, main_gate_type, main_down_type,
                main_model_map == g_model_host_base,
                (unsigned long long)main_model_size,
                (unsigned long long)g_model_registered_size,
                q1_model_map == g_q1_0_sidecar_host_base,
                (unsigned long long)q1_model_size,
                (unsigned long long)g_q1_0_sidecar_size,
                cuda_q1_0_route_arena(layer_index) != NULL,
                (unsigned long long)g_moe_tiering.entries.size(),
                (unsigned long long)(selected ? selected->bytes : 0),
                (unsigned long long)(weights ? weights->bytes : 0),
                (unsigned long long)(out ? out->bytes : 0),
                (unsigned long long)out_dim * sizeof(float));
        g_q1_0_mixed_failures++;
        return 0;
    }
    if (q1_0_dynamic_promotion &&
        (cuda_q1_0_snapshot_backing_requested() ||
         !cuda_q1_0_dual_arena_layer_active(layer_index) ||
         g_moe_tiering.mode != CUDA_MOE_TIER_ENFORCE ||
         !g_moe_tiering.compose_prefill_mass_tiering ||
         !g_moe_tiering.compose_router_open ||
         g_iq1_promotion.requested_slots == 0u)) {
        fprintf(stderr,
                "ds4: [q1-0-mixed] result=failed "
                "reason=dynamic-promotion-contract layer=%u dual=%u "
                "snapshot=%u tier_mode=%u compose=%u open=%u slots=%u\n",
                layer_index,
                cuda_q1_0_dual_arena_layer_active(layer_index) ? 1u : 0u,
                cuda_q1_0_snapshot_backing_requested() ? 1u : 0u,
                (unsigned)g_moe_tiering.mode,
                g_moe_tiering.compose_prefill_mass_tiering ? 1u : 0u,
                g_moe_tiering.compose_router_open ? 1u : 0u,
                g_iq1_promotion.requested_slots);
        g_q1_0_mixed_failures++;
        return 0;
    }

    const int recovery_trace_layer =
        g_expert_recovery_trace.enabled &&
        layer_index == g_expert_recovery_trace.target_layer;
    const uint64_t recovery_trace_token_index =
        cuda_expert_recovery_trace_layer_call(layer_index);
    if (recovery_trace_layer && recovery_trace_token_index == UINT64_MAX) {
        g_q1_0_mixed_failures++;
        return 0;
    }

    int32_t selected_host[CUDA_MOE_ROUTE_COUNT] = {0};
    float weights_host[CUDA_MOE_ROUTE_COUNT] = {0};
    if (!cuda_ok(cudaMemcpy(selected_host, selected->ptr,
                            (size_t)n_expert * sizeof(int32_t),
                            cudaMemcpyDeviceToHost),
                 "Q1_0 mixed selected D2H") ||
        !cuda_ok(cudaMemcpy(weights_host, weights->ptr,
                            (size_t)n_expert * sizeof(float),
                            cudaMemcpyDeviceToHost),
                 "Q1_0 mixed weights D2H")) {
        g_q1_0_mixed_failures++;
        return 0;
    }

    int32_t hot_selected[CUDA_MOE_ROUTE_COUNT] = {0};
    float hot_weights[CUDA_MOE_ROUTE_COUNT] = {0};
    int32_t cold_selected[CUDA_MOE_ROUTE_COUNT] = {0};
    float cold_weights[CUDA_MOE_ROUTE_COUNT] = {0};
    uint32_t hot_count = 0;
    uint32_t cold_count = 0;
    uint32_t iq2_vram = 0;
    uint32_t iq2_snapshot_ram = 0;
    uint32_t iq2_tier_ram = 0;
    uint32_t tier_route_entries = 0;
    uint32_t recovery_trace_rank = UINT32_MAX;
    float recovery_trace_weight = 0.0f;
    const char *recovery_trace_representation = NULL;
    const int cold_one_requested =
        cuda_q1_0_mixed_cold_one_requested();
    uint32_t cold_slot = UINT32_MAX;
    if (cold_one_requested) {
        if (!cuda_q1_0_dual_sparse_companion_requested() ||
            n_expert != CUDA_MOE_ROUTE_COUNT ||
            !g_q1_0_dual_sparse_snapshot.ready) {
            fprintf(stderr,
                    "ds4: [q1-0-mixed] result=failed "
                    "reason=cold-one-contract layer=%u routes=%u\n",
                    layer_index, n_expert);
            g_q1_0_mixed_cold_one_invariant_failures++;
            g_q1_0_mixed_failures++;
            return 0;
        }
        cold_slot = 0u;
        for (uint32_t route = 1; route < n_expert; route++) {
            if (weights_host[route] < weights_host[cold_slot]) {
                cold_slot = route;
            }
        }
    }
    for (uint32_t route = 0; route < n_expert; route++) {
        const int32_t expert_i = selected_host[route];
        if (expert_i < 0 || expert_i >= 256) {
            fprintf(stderr,
                    "ds4: [q1-0-mixed] result=failed reason=expert-range "
                    "layer=%u route=%u expert=%d\n",
                    layer_index, route, (int)expert_i);
            g_q1_0_mixed_failures++;
            return 0;
        }
        cuda_q1_0_mixed_representation representation =
            CUDA_Q1_0_MIXED_UNKNOWN;
        if (cold_one_requested) {
            if (!cuda_q1_0_dual_sparse_pair_contains(
                    layer_index, (uint32_t)expert_i)) {
                fprintf(stderr,
                        "ds4: [q1-0-mixed] result=failed "
                        "reason=dual-sparse-parity layer=%u route=%u expert=%d\n",
                        layer_index, route, (int)expert_i);
                g_q1_0_mixed_cold_one_invariant_failures++;
                g_q1_0_mixed_failures++;
                return 0;
            }
            representation = route == cold_slot
                ? CUDA_Q1_0_MIXED_Q1_RESIDENT
                : (cuda_moe_tiering_has_exact_vram(
                        layer_index, (uint32_t)expert_i)
                    ? CUDA_Q1_0_MIXED_IQ2_VRAM
                    : CUDA_Q1_0_MIXED_IQ2_SNAPSHOT_RAM);
        } else {
            representation = cuda_q1_0_mixed_resolve(
                layer_index, (uint32_t)expert_i);
        }
        const cuda_moe_tier_entry *tier =
            g_moe_tiering.entries.size() ==
                    (size_t)CUDA_MOE_LAYER_COUNT * 256u
                ? &g_moe_tiering.entries[cuda_moe_tiering_entry_index(
                    layer_index, (uint32_t)expert_i)]
                : NULL;
        if (tier) tier_route_entries++;
        if (cuda_expert_recovery_trace_target(
                layer_index, (uint32_t)expert_i)) {
            if (recovery_trace_rank != UINT32_MAX) {
                cuda_expert_recovery_trace_fail("duplicate_target_route");
                g_q1_0_mixed_failures++;
                return 0;
            }
            recovery_trace_rank = route;
            recovery_trace_weight = weights_host[route];
            recovery_trace_representation =
                cuda_q1_0_mixed_representation_name(representation);
        }
        if (cuda_q1_0_mixed_trace_requested()) {
            fprintf(stderr,
                    "ds4: [q1-0-mixed-route] layer=%u route=%u expert=%d "
                    "weight=%.9g representation=%s tier=%u has_2bit_ram=%u "
                    "primary_snapshot=%llu q1_snapshot=%llu\n",
                    layer_index, route, (int)expert_i, weights_host[route],
                    cuda_q1_0_mixed_representation_name(representation),
                    tier ? (unsigned)tier->state : 0u,
                    tier ? (unsigned)tier->has_2bit_ram : 0u,
                    (unsigned long long)g_moe_tiering.snapshot_generation,
                    (unsigned long long)
                        q1_arena->snapshot_generation);
            g_q1_0_mixed_trace_rows++;
        }
        if (representation == CUDA_Q1_0_MIXED_IQ2_VRAM ||
            representation == CUDA_Q1_0_MIXED_IQ2_SNAPSHOT_RAM ||
            representation == CUDA_Q1_0_MIXED_IQ2_TIER_RAM) {
            hot_selected[hot_count] = expert_i;
            hot_weights[hot_count] = weights_host[route];
            hot_count++;
            iq2_vram += representation == CUDA_Q1_0_MIXED_IQ2_VRAM;
            iq2_snapshot_ram +=
                representation == CUDA_Q1_0_MIXED_IQ2_SNAPSHOT_RAM;
            iq2_tier_ram +=
                representation == CUDA_Q1_0_MIXED_IQ2_TIER_RAM;
        } else if (representation == CUDA_Q1_0_MIXED_Q1_RESIDENT) {
            cold_selected[cold_count] = expert_i;
            cold_weights[cold_count] = weights_host[route];
            cold_count++;
        } else {
            fprintf(stderr,
                    "ds4: [q1-0-mixed] result=failed reason=unresolved "
                    "layer=%u route=%u expert=%d router=unchanged\n",
                    layer_index, route, (int)expert_i);
            g_q1_0_mixed_failures++;
            return 0;
        }
    }
    if (q1_0_mixed_exact_iq2_resolver &&
        !cuda_q1_0_snapshot_backing_requested() &&
        !cuda_q1_0_dual_sparse_companion_requested() &&
        tier_route_entries != n_expert) {
        fprintf(stderr,
                "ds4: [q1-0-mixed] result=failed "
                "reason=route-entry-contract layer=%u routes=%u "
                "tier_route_entries=%u tier_entries=%llu\n",
                layer_index, n_expert, tier_route_entries,
                (unsigned long long)g_moe_tiering.entries.size());
        g_q1_0_mixed_failures++;
        return 0;
    }
    g_q1_0_mixed_tier_route_entries += tier_route_entries;

    if (cold_one_requested) {
        if (hot_count != CUDA_MOE_ROUTE_COUNT - 1u || cold_count != 1u) {
            fprintf(stderr,
                    "ds4: [q1-0-mixed] result=failed "
                    "reason=cold-one-count layer=%u hot=%u q1=%u\n",
                    layer_index, hot_count, cold_count);
            g_q1_0_mixed_cold_one_invariant_failures++;
            g_q1_0_mixed_failures++;
            return 0;
        }
        g_q1_0_mixed_cold_one_calls++;
        g_q1_0_mixed_cold_one_hot_routes += hot_count;
        g_q1_0_mixed_cold_one_q1_routes += cold_count;
    }

    if (cold_count == 0u) {
        const int ok = routed_moe_launch(
            out, gate, up, mid, down,
            main_model_map, main_model_size, layer_index,
            main_gate_offset, main_up_offset, main_down_offset,
            main_gate_type, main_down_type,
            main_gate_expert_bytes, main_gate_row_bytes,
            main_down_expert_bytes, main_down_row_bytes,
            expert_in_dim, expert_mid_dim, out_dim,
            selected, weights, NULL, n_expert, clamp, x, 1u, NULL, NULL);
        if (!ok) {
            g_q1_0_mixed_failures++;
            return 0;
        }
        g_q1_0_mixed_all_iq2++;
        g_q1_0_mixed_iq2_vram += iq2_vram;
        g_q1_0_mixed_iq2_snapshot_ram += iq2_snapshot_ram;
        g_q1_0_mixed_iq2_tier_ram += iq2_tier_ram;
        if (recovery_trace_rank != UINT32_MAX &&
            !cuda_expert_recovery_trace_capture(
                layer_index, g_expert_recovery_trace.target_expert,
                recovery_trace_rank, recovery_trace_weight,
                recovery_trace_representation, recovery_trace_token_index,
                g_moe_tiering.call_tick, x, expert_in_dim)) {
            g_q1_0_mixed_failures++;
            return 0;
        }
        return 1;
    }

    const uint64_t iq2_ssd_bytes_before = g_moe_tiering.ssd_bytes;
    const uint64_t iq2_cold_to_ram_before = g_moe_tiering.cold_to_ram;

    const uint64_t max_routes = CUDA_MOE_ROUTE_COUNT;
    const uint64_t out_bytes = (uint64_t)out_dim * sizeof(float);
    const uint64_t xq_blocks = expert_in_dim / CUDA_QK_K;
    const uint64_t xq_bytes = xq_blocks * sizeof(cuda_block_q8_K);
    const uint64_t off_hot_selected = 0;
    const uint64_t off_hot_weights = cuda_round_up(
        off_hot_selected + max_routes * sizeof(int32_t), 4u);
    const uint64_t off_cold_selected = cuda_round_up(
        off_hot_weights + max_routes * sizeof(float), 4u);
    const uint64_t off_cold_weights = cuda_round_up(
        off_cold_selected + max_routes * sizeof(int32_t), 4u);
    const uint64_t off_cold_out = cuda_round_up(
        off_cold_weights + max_routes * sizeof(float), 256u);
    const uint64_t cold_down_bytes = std::max(
        (uint64_t)cold_count * out_bytes, xq_bytes);
    const uint64_t off_cold_down = cuda_round_up(
        off_cold_out + out_bytes, 256u);
    if (cold_down_bytes > UINT64_MAX - off_cold_down ||
        !cuda_iq1_mixed_scratch_ensure(off_cold_down + cold_down_bytes)) {
        fprintf(stderr,
                "ds4: [q1-0-mixed] result=failed reason=scratch "
                "layer=%u requested=%llu cold_down=%llu\n",
                layer_index,
                (unsigned long long)(off_cold_down + cold_down_bytes),
                (unsigned long long)cold_down_bytes);
        g_q1_0_mixed_failures++;
        return 0;
    }
    char *scratch = (char *)g_iq1_mixed_scratch;
    int32_t *device_hot_selected =
        (int32_t *)(scratch + off_hot_selected);
    float *device_hot_weights = (float *)(scratch + off_hot_weights);
    int32_t *device_cold_selected =
        (int32_t *)(scratch + off_cold_selected);
    float *device_cold_weights = (float *)(scratch + off_cold_weights);
    float *device_cold_out = (float *)(scratch + off_cold_out);
    float *device_cold_down = (float *)(scratch + off_cold_down);
    if ((hot_count != 0u &&
         (!cuda_ok(cudaMemcpy(device_hot_selected, hot_selected,
                              (size_t)hot_count * sizeof(int32_t),
                              cudaMemcpyHostToDevice),
                   "Q1_0 mixed hot selected H2D") ||
          !cuda_ok(cudaMemcpy(device_hot_weights, hot_weights,
                              (size_t)hot_count * sizeof(float),
                              cudaMemcpyHostToDevice),
                   "Q1_0 mixed hot weights H2D"))) ||
        !cuda_ok(cudaMemcpy(device_cold_selected, cold_selected,
                            (size_t)cold_count * sizeof(int32_t),
                            cudaMemcpyHostToDevice),
                 "Q1_0 mixed cold selected H2D") ||
        !cuda_ok(cudaMemcpy(device_cold_weights, cold_weights,
                            (size_t)cold_count * sizeof(float),
                            cudaMemcpyHostToDevice),
                 "Q1_0 mixed cold weights H2D")) {
        g_q1_0_mixed_failures++;
        return 0;
    }

    int ok = 1;
    if (hot_count != 0u) {
        const ds4_gpu_tensor hot_selected_tensor = {
            device_hot_selected,
            (uint64_t)hot_count * sizeof(int32_t), 0
        };
        const ds4_gpu_tensor hot_weights_tensor = {
            device_hot_weights,
            (uint64_t)hot_count * sizeof(float), 0
        };
        ok = routed_moe_launch(
            out, gate, up, mid, down,
            main_model_map, main_model_size, layer_index,
            main_gate_offset, main_up_offset, main_down_offset,
            main_gate_type, main_down_type,
            main_gate_expert_bytes, main_gate_row_bytes,
            main_down_expert_bytes, main_down_row_bytes,
            expert_in_dim, expert_mid_dim, out_dim,
            &hot_selected_tensor, &hot_weights_tensor, NULL,
            hot_count, clamp, x, 1u, NULL, NULL);
    } else {
        ok = cuda_ok(cudaMemsetAsync(out->ptr, 0, (size_t)out_bytes, 0),
                     "Q1_0 mixed empty IQ2 output");
    }
    if (!ok) {
        fprintf(stderr,
                "ds4: [q1-0-mixed] result=failed reason=iq2-hot-launch "
                "layer=%u hot=%u\n", layer_index, hot_count);
        g_q1_0_mixed_failures++;
        return 0;
    }
    const uint64_t iq2_ssd_bytes_after_hot = g_moe_tiering.ssd_bytes;
    const uint64_t iq2_cold_to_ram_after_hot = g_moe_tiering.cold_to_ram;
    if (iq2_ssd_bytes_after_hot != iq2_ssd_bytes_before ||
        iq2_cold_to_ram_after_hot != iq2_cold_to_ram_before) {
        const uint64_t delta = iq2_ssd_bytes_after_hot >= iq2_ssd_bytes_before
            ? iq2_ssd_bytes_after_hot - iq2_ssd_bytes_before : 0;
        g_q1_0_mixed_iq2_ssd_bytes += delta;
        g_q1_0_mixed_iq2_ssd_violations++;
        g_q1_0_mixed_failures++;
        fprintf(stderr,
                "ds4: [q1-0-mixed] result=failed "
                "reason=current-token-iq2-ssd layer=%u bytes=%llu "
                "cold_to_ram_delta=%llu\n",
                layer_index, (unsigned long long)delta,
                (unsigned long long)(
                    iq2_cold_to_ram_after_hot - iq2_cold_to_ram_before));
        return 0;
    }

    /* The IQ2 route worker already observed the hot subset. Q1 routes bypass
     * that worker, so account for their router demand on the same logical
     * clock tick. This changes residency policy only for future tokens; the
     * current token remains Q1 and performs no IQ2 SSD read. */
    if (g_moe_tiering.mode != CUDA_MOE_TIER_OFF) {
        if (hot_count == 0u) {
            if (cuda_moe_tiering_advance_call_tick(
                    "q1-0-mixed-cold-only")) {
                g_moe_tiering.calls++;
            }
        }
        g_moe_tiering.selected += cold_count;
        for (uint32_t route = 0; route < cold_count; route++) {
            (void)cuda_moe_tiering_observe_route(
                layer_index, (uint32_t)cold_selected[route],
                cold_weights[route]);
        }
    }

    const ds4_gpu_tensor cold_selected_tensor = {
        device_cold_selected,
        (uint64_t)cold_count * sizeof(int32_t), 0
    };
    const ds4_gpu_tensor cold_weights_tensor = {
        device_cold_weights,
        (uint64_t)cold_count * sizeof(float), 0
    };
    ds4_gpu_tensor cold_out_tensor = {
        device_cold_out, out_bytes, 0
    };
    ds4_gpu_tensor cold_down_tensor = {
        device_cold_down, cold_down_bytes, 0
    };
    ok = routed_moe_launch(
        &cold_out_tensor, gate, up, mid, &cold_down_tensor,
        q1_model_map, q1_model_size, layer_index,
        q1_gate_offset, q1_up_offset, q1_down_offset,
        41u, 41u,
        q1_gate_expert_bytes, q1_gate_row_bytes,
        q1_down_expert_bytes, q1_down_row_bytes,
        expert_in_dim, expert_mid_dim, out_dim,
        &cold_selected_tensor, &cold_weights_tensor, NULL,
        cold_count, clamp, x, 1u, NULL, NULL);
    if (!ok) {
        fprintf(stderr,
                "ds4: [q1-0-mixed] result=failed reason=q1-cold-launch "
                "layer=%u q1=%u\n", layer_index, cold_count);
        g_q1_0_mixed_failures++;
        return 0;
    }
    cudaEvent_t join_begin = NULL;
    cudaEvent_t join_end = NULL;
    if (cuda_q1_0_profile_requested()) {
        const cudaError_t begin_create = cudaEventCreate(&join_begin);
        const cudaError_t end_create = begin_create == cudaSuccess ?
            cudaEventCreate(&join_end) : begin_create;
        const cudaError_t begin_record = end_create == cudaSuccess ?
            cudaEventRecord(join_begin, 0) : end_create;
        if (begin_record != cudaSuccess) {
            if (join_begin) (void)cudaEventDestroy(join_begin);
            if (join_end) (void)cudaEventDestroy(join_end);
            join_begin = NULL;
            join_end = NULL;
            g_q1_0_profile.timer_failures++;
            (void)cudaGetLastError();
        }
    }
    add_f32_u64_kernel<<<(out_dim + 255u) / 256u, 256>>>(
        (float *)out->ptr, (const float *)out->ptr,
        device_cold_out, out_dim);
    if (!cuda_ok(cudaGetLastError(), "Q1_0 mixed output join")) {
        if (join_begin) (void)cudaEventDestroy(join_begin);
        if (join_end) (void)cudaEventDestroy(join_end);
        g_q1_0_mixed_failures++;
        return 0;
    }
    if (join_end) {
        float join_ms = 0.0f;
        const cudaError_t end_record = cudaEventRecord(join_end, 0);
        const cudaError_t end_sync = end_record == cudaSuccess ?
            cudaEventSynchronize(join_end) : end_record;
        const cudaError_t elapsed = end_sync == cudaSuccess ?
            cudaEventElapsedTime(&join_ms, join_begin, join_end) : end_sync;
        if (elapsed == cudaSuccess) {
            g_q1_0_profile.mixed_join_calls++;
            g_q1_0_profile.mixed_join_seconds +=
                (double)join_ms / 1000.0;
        } else {
            g_q1_0_profile.timer_failures++;
            (void)cudaGetLastError();
        }
        (void)cudaEventDestroy(join_begin);
        (void)cudaEventDestroy(join_end);
    }
    if (recovery_trace_rank != UINT32_MAX &&
        !cuda_expert_recovery_trace_capture(
            layer_index, g_expert_recovery_trace.target_expert,
            recovery_trace_rank, recovery_trace_weight,
            recovery_trace_representation, recovery_trace_token_index,
            g_moe_tiering.call_tick, x, expert_in_dim)) {
        g_q1_0_mixed_failures++;
        return 0;
    }
    if (q1_0_dynamic_promotion) {
        /* The current result is already queued from resident Q1_0. Admission
         * below is future-token work: exact IQ2 first enters the disjoint RAM
         * probation arena and cannot become VRAM-eligible until a later call. */
        for (uint32_t route = 0; route < cold_count; route++) {
            (void)cuda_moe_tiering_stage_observed_quant_cold_to_2bit_ram(
                layer_index, (uint32_t)cold_selected[route],
                cold_weights[route],
                main_gate_offset, main_up_offset, main_down_offset,
                main_gate_expert_bytes, main_down_expert_bytes, 1,
                q1_gate_offset, q1_up_offset, q1_down_offset,
                q1_gate_expert_bytes, q1_down_expert_bytes);
        }
    }
    if (cuda_q1_0_snapshot_backing_requested()) {
        g_moe_tiering.snapshot_backing_hits += cold_count;
    }
    g_q1_0_mixed_iq2_vram += iq2_vram;
    g_q1_0_mixed_iq2_snapshot_ram += iq2_snapshot_ram;
    g_q1_0_mixed_iq2_tier_ram += iq2_tier_ram;
    g_q1_0_mixed_q1_resident += cold_count;
    g_q1_0_mixed_joins++;
    return 1;
}

extern "C" int ds4_gpu_routed_moe_mixed_iq1_one_tensor(
        ds4_gpu_tensor *out,
        ds4_gpu_tensor *gate,
        ds4_gpu_tensor *up,
        ds4_gpu_tensor *mid,
        ds4_gpu_tensor *down,
        const void *main_model_map,
        uint64_t main_model_size,
        uint32_t layer_index,
        uint64_t main_gate_offset,
        uint64_t main_up_offset,
        uint64_t main_down_offset,
        uint32_t main_gate_type,
        uint32_t main_down_type,
        uint64_t main_gate_expert_bytes,
        uint64_t main_gate_row_bytes,
        uint64_t main_down_expert_bytes,
        uint64_t main_down_row_bytes,
        const void *iq1_model_map,
        uint64_t iq1_model_size,
        uint64_t iq1_gate_offset,
        uint64_t iq1_up_offset,
        uint64_t iq1_down_offset,
        uint32_t iq1_down_type,
        uint64_t iq1_gate_expert_bytes,
        uint64_t iq1_gate_row_bytes,
        uint64_t iq1_down_expert_bytes,
        uint64_t iq1_down_row_bytes,
        uint32_t expert_in_dim,
        uint32_t expert_mid_dim,
        uint32_t out_dim,
        const ds4_gpu_tensor *selected,
        const ds4_gpu_tensor *weights,
        uint32_t n_expert,
        float clamp,
        const ds4_gpu_tensor *x,
        ds4_gpu_spex_queue *spex_queue,
        const ds4_gpu_spex_key *spex_key) {
    g_iq1_mixed_calls++;
    const int mixed_profile = getenv("DS4_IQ1_S_PROFILE") != NULL;
    const int no_main_sync = getenv("DS4_IQ1_MIXED_NO_MAIN_SYNC") != NULL;
    const int gpu_plan_requested =
        getenv("DS4_IQ1_MIXED_GPU_PLAN") != NULL;
    const double mixed_t0 = mixed_profile ? cuda_wall_sec() : 0.0;
    const uint32_t slot_count = 6u;
    int32_t h_selected[6];
    float h_weights[6];
    if (!out || !gate || !up || !mid || !down ||
        !main_model_map || !iq1_model_map || !selected || !weights || !x ||
        n_expert != slot_count || expert_in_dim == 0 || expert_mid_dim == 0 ||
        out_dim == 0 || main_gate_type != 16u || main_down_type != 10u ||
        (iq1_down_type != 19u && iq1_down_type != 10u) ||
        selected->bytes < slot_count * sizeof(int32_t) ||
        weights->bytes < slot_count * sizeof(float)) {
        g_iq1_mixed_failures++;
        return 0;
    }
    uint32_t cold_slot = 0;
    float cold_weight = 0.0f;
    int32_t cold_expert = -1;
    int32_t h_hot_selected[5];
    float h_hot_weights[5];
    uint32_t hot_i = 0;
    if (!gpu_plan_requested) {
        if (!cuda_ok(cudaMemcpy(h_selected, selected->ptr,
                                sizeof(h_selected), cudaMemcpyDeviceToHost),
                     "iq1 mixed selected D2H") ||
            !cuda_ok(cudaMemcpy(h_weights, weights->ptr,
                                sizeof(h_weights), cudaMemcpyDeviceToHost),
                     "iq1 mixed weights D2H")) {
            g_iq1_mixed_failures++;
            return 0;
        }
        cold_weight = h_weights[0];
        for (uint32_t i = 1; i < slot_count; i++) {
            if (h_weights[i] < cold_weight) {
                cold_weight = h_weights[i];
                cold_slot = i;
            }
        }
        cold_expert = h_selected[cold_slot];
        for (uint32_t i = 0; i < slot_count; i++) {
            if (i == cold_slot) continue;
            h_hot_selected[hot_i] = h_selected[i];
            h_hot_weights[hot_i] = h_weights[i];
            hot_i++;
        }
    } else if (!cuda_iq1_mixed_gpu_plan_prepare()) {
        g_iq1_mixed_gpu_plan.failures++;
        g_iq1_mixed_failures++;
        return 0;
    }
    const double mixed_router_t = mixed_profile ? cuda_wall_sec() : 0.0;

    const uint32_t hot_count = slot_count - 1u;
    if (!gpu_plan_requested &&
        (cold_expert < 0 || cold_expert >= 256 || hot_i != hot_count)) {
        g_iq1_mixed_failures++;
        return 0;
    }

    const uint32_t xq_blocks = expert_in_dim / CUDA_QK_K;
    const uint64_t out_bytes = (uint64_t)out_dim * sizeof(float);
    const uint64_t xq_bytes = (uint64_t)xq_blocks * sizeof(cuda_block_q8_K);
    const uint64_t cold_down_bytes = std::max(out_bytes, xq_bytes);
    const uint64_t off_hot_selected = 0;
    const uint64_t off_hot_weights =
        cuda_round_up(off_hot_selected + hot_count * sizeof(int32_t), 4u);
    const uint64_t off_cold_selected =
        cuda_round_up(off_hot_weights + hot_count * sizeof(float), 4u);
    const uint64_t off_cold_weight =
        cuda_round_up(off_cold_selected + sizeof(int32_t), 4u);
    const uint64_t off_cold_out =
        cuda_round_up(off_cold_weight + sizeof(float), 256u);
    const uint64_t off_cold_down = cuda_round_up(off_cold_out + out_bytes, 256u);
    if (out_bytes == 0 || cold_down_bytes > UINT64_MAX - off_cold_down) {
        g_iq1_mixed_failures++;
        return 0;
    }
    const uint64_t scratch_bytes = off_cold_down + cold_down_bytes;
    if (!cuda_iq1_mixed_scratch_ensure(scratch_bytes)) {
        g_iq1_mixed_failures++;
        return 0;
    }
    char *scratch = (char *)g_iq1_mixed_scratch;
    int32_t *d_hot_selected = (int32_t *)(scratch + off_hot_selected);
    float *d_hot_weights = (float *)(scratch + off_hot_weights);
    int32_t *d_cold_selected = (int32_t *)(scratch + off_cold_selected);
    float *d_cold_weight = (float *)(scratch + off_cold_weight);
    float *d_cold_out = (float *)(scratch + off_cold_out);
    float *d_cold_down = (float *)(scratch + off_cold_down);

    uint32_t gpu_plan_sequence = 0;
    if (gpu_plan_requested) {
        gpu_plan_sequence = ++g_iq1_mixed_gpu_plan.sequence;
        if (gpu_plan_sequence == 0u) {
            gpu_plan_sequence = ++g_iq1_mixed_gpu_plan.sequence;
        }
        iq1_mixed_cold_one_plan_kernel<<<1, 1>>>(
            d_hot_selected, d_hot_weights,
            d_cold_selected, d_cold_weight,
            g_iq1_mixed_gpu_plan.device_request,
            (const int32_t *)selected->ptr,
            (const float *)weights->ptr,
            layer_index, gpu_plan_sequence);
        if (!cuda_ok(cudaGetLastError(), "iq1 mixed GPU planner launch")) {
            g_iq1_mixed_gpu_plan.failures++;
            g_iq1_mixed_failures++;
            return 0;
        }
    } else {
        if (!cuda_ok(cudaMemcpy(d_hot_selected, h_hot_selected,
                                sizeof(h_hot_selected), cudaMemcpyHostToDevice),
                     "iq1 mixed hot selected H2D") ||
            !cuda_ok(cudaMemcpy(d_hot_weights, h_hot_weights,
                                sizeof(h_hot_weights), cudaMemcpyHostToDevice),
                     "iq1 mixed hot weights H2D") ||
            !cuda_ok(cudaMemcpy(d_cold_selected, &cold_expert,
                                sizeof(cold_expert), cudaMemcpyHostToDevice),
                     "iq1 mixed cold selected H2D") ||
            !cuda_ok(cudaMemcpy(d_cold_weight, &cold_weight,
                                sizeof(cold_weight), cudaMemcpyHostToDevice),
                     "iq1 mixed cold weight H2D")) {
            g_iq1_mixed_failures++;
            return 0;
        }
    }
    const double mixed_metadata_t = mixed_profile ? cuda_wall_sec() : 0.0;

    ds4_gpu_tensor hot_selected = { d_hot_selected, hot_count * sizeof(int32_t), 0 };
    ds4_gpu_tensor hot_weights = { d_hot_weights, hot_count * sizeof(float), 0 };
    int ok = routed_moe_launch(out, gate, up, mid, down,
                               main_model_map, main_model_size, layer_index,
                               main_gate_offset, main_up_offset, main_down_offset,
                               main_gate_type, main_down_type,
                               main_gate_expert_bytes, main_gate_row_bytes,
                               main_down_expert_bytes, main_down_row_bytes,
                               expert_in_dim, expert_mid_dim, out_dim,
                               &hot_selected, &hot_weights, NULL, hot_count, clamp,
                               x, 1u, NULL, NULL);
    if (!ok) {
        g_iq1_mixed_failures++;
        return 0;
    }
    const double mixed_main_submit_t = mixed_profile ? cuda_wall_sec() : 0.0;
    double gpu_plan_wait_seconds = 0.0;
    if (gpu_plan_requested) {
        const double wait_started = cuda_wall_sec();
        const double wait_deadline = wait_started + 5.0;
        while (*(volatile uint32_t *)&g_iq1_mixed_gpu_plan.host_request->sequence !=
               gpu_plan_sequence) {
            if (cuda_wall_sec() >= wait_deadline) {
                fprintf(stderr,
                        "ds4: IQ1 mixed GPU planner timed out seq=%u layer=%u\n",
                        gpu_plan_sequence, layer_index);
                g_iq1_mixed_gpu_plan.failures++;
                g_iq1_mixed_failures++;
                return 0;
            }
#ifdef _WIN32
            (void)SwitchToThread();
#else
            usleep(0);
#endif
        }
#ifdef _WIN32
        MemoryBarrier();
#else
        __sync_synchronize();
#endif
        gpu_plan_wait_seconds = cuda_wall_sec() - wait_started;
        g_iq1_mixed_gpu_plan.wait_seconds += gpu_plan_wait_seconds;
        const cuda_iq1_mixed_gpu_plan_request *request =
            g_iq1_mixed_gpu_plan.host_request;
        cold_slot = request->cold_slot;
        cold_expert = request->cold_expert;
        cold_weight = request->cold_weight;
        if (request->layer_index != layer_index || cold_slot >= slot_count ||
            cold_expert < 0 || cold_expert >= 256) {
            fprintf(stderr,
                    "ds4: IQ1 mixed GPU planner returned invalid route "
                    "seq=%u layer=%u request_layer=%u slot=%u expert=%d\n",
                    gpu_plan_sequence, layer_index, request->layer_index,
                    cold_slot, (int)cold_expert);
            g_iq1_mixed_gpu_plan.failures++;
            g_iq1_mixed_failures++;
            return 0;
        }
        g_iq1_mixed_gpu_plan.calls++;

        /* The hot kernels are already queued on stream 0. Publish the exact
         * host-selected cold id so selected-load can stage IQ1_S on the
         * nonblocking upload stream without repeating a router D2H. */
        g_iq1_mixed_host_selected.model_map = iq1_model_map;
        g_iq1_mixed_host_selected.selected_ptr = d_cold_selected;
        g_iq1_mixed_host_selected.gate_offset = iq1_gate_offset;
        g_iq1_mixed_host_selected.up_offset = iq1_up_offset;
        g_iq1_mixed_host_selected.down_offset = iq1_down_offset;
        g_iq1_mixed_host_selected.gate_expert_bytes =
            iq1_gate_expert_bytes;
        g_iq1_mixed_host_selected.down_expert_bytes =
            iq1_down_expert_bytes;
        g_iq1_mixed_host_selected.expert = cold_expert;
        g_iq1_mixed_host_selected.weight = cold_weight;
        g_iq1_mixed_host_selected.valid = 1;
    }
    g_iq1_mixed_last_layer = layer_index;
    g_iq1_mixed_last_slot = cold_slot;
    g_iq1_mixed_last_expert = cold_expert;
    if (!no_main_sync && !gpu_plan_requested &&
        !cuda_ok(cudaStreamSynchronize(0), "iq1 mixed main preserve sync")) {
        g_iq1_mixed_failures++;
        return 0;
    }
    const double mixed_main_sync_t = mixed_profile ? cuda_wall_sec() : 0.0;
    if (!cuda_iq1_mixed_debug_output("hot-main", out, out_dim)) {
        g_iq1_mixed_failures++;
        return 0;
    }

    ds4_gpu_tensor cold_selected = { d_cold_selected, sizeof(int32_t), 0 };
    ds4_gpu_tensor cold_weight_tensor = { d_cold_weight, sizeof(float), 0 };
    ds4_gpu_tensor cold_out = { d_cold_out, out_bytes, 0 };
    ds4_gpu_tensor cold_down = { d_cold_down, cold_down_bytes, 0 };
    ok = routed_moe_launch(&cold_out, gate, up, mid, &cold_down,
                           iq1_model_map, iq1_model_size, layer_index,
                           iq1_gate_offset, iq1_up_offset, iq1_down_offset,
                           19u, iq1_down_type,
                           iq1_gate_expert_bytes, iq1_gate_row_bytes,
                           iq1_down_expert_bytes, iq1_down_row_bytes,
                           expert_in_dim, expert_mid_dim, out_dim,
                           &cold_selected, &cold_weight_tensor, NULL, 1u, clamp,
                           x, 1u, NULL, NULL);
    if (!ok) {
        g_iq1_mixed_failures++;
        return 0;
    }
    const double mixed_cold_submit_t = mixed_profile ? cuda_wall_sec() : 0.0;

    add_f32_u64_kernel<<<(out_dim + 255u) / 256u, 256>>>(
        (float *)out->ptr, (const float *)out->ptr, d_cold_out, out_dim);
    if (!cuda_ok(cudaGetLastError(), "iq1 mixed cold add launch")) {
        g_iq1_mixed_failures++;
        return 0;
    }
    /* Promotion is speculative work for a future token. The current IQ1_S
     * result and join are already queued, so a staging failure must be
     * reported by promotion telemetry without turning a valid MoE result
     * into a partial failure that a caller could replay. */
    (void)cuda_moe_tiering_stage_iq1_cold_to_2bit_ram(
            layer_index, (uint32_t)cold_expert, cold_weight,
            main_gate_offset, main_up_offset, main_down_offset,
            main_gate_expert_bytes, main_down_expert_bytes);
    const double mixed_join_t = mixed_profile ? cuda_wall_sec() : 0.0;
    if (!cuda_iq1_mixed_debug_output("joined", out, out_dim)) {
        g_iq1_mixed_failures++;
        return 0;
    }
    g_iq1_mixed_hot_main += hot_count;
    g_iq1_mixed_cold_iq1++;
    g_iq1_mixed_primary_cold_avoided++;
    g_iq1_mixed_joins++;
    if (mixed_profile) {
        g_iq1_mixed_profile_calls++;
        g_iq1_mixed_profile_router_d2h_seconds += mixed_router_t - mixed_t0;
        g_iq1_mixed_profile_metadata_h2d_seconds +=
            mixed_metadata_t - mixed_router_t;
        g_iq1_mixed_profile_main_submit_seconds +=
            mixed_main_submit_t - mixed_metadata_t;
        double main_sync_seconds =
            mixed_main_sync_t - mixed_main_submit_t - gpu_plan_wait_seconds;
        if (main_sync_seconds < 0.0) main_sync_seconds = 0.0;
        g_iq1_mixed_profile_main_sync_seconds += main_sync_seconds;
        g_iq1_mixed_profile_cold_submit_seconds +=
            mixed_cold_submit_t - mixed_main_sync_t;
        g_iq1_mixed_profile_join_submit_seconds +=
            mixed_join_t - mixed_cold_submit_t;
    }
    return 1;
}

extern "C" int ds4_gpu_routed_moe_batch_tensor(ds4_gpu_tensor *out, ds4_gpu_tensor *gate, ds4_gpu_tensor *up, ds4_gpu_tensor *mid, ds4_gpu_tensor *down, const void *model_map, uint64_t model_size, uint32_t layer_index, uint64_t gate_offset, uint64_t up_offset, uint64_t down_offset, uint32_t gate_type, uint32_t down_type, uint64_t gate_expert_bytes, uint64_t gate_row_bytes, uint64_t down_expert_bytes, uint64_t down_row_bytes, uint32_t expert_in_dim, uint32_t expert_mid_dim, uint32_t out_dim, const ds4_gpu_tensor *selected, const ds4_gpu_tensor *weights, const ds4_gpu_tensor *probs, uint32_t n_expert, float clamp, const ds4_gpu_tensor *x, uint32_t n_tokens, bool *mid_is_f16) {
    if (mid_is_f16) *mid_is_f16 = false;
    return routed_moe_launch(out, gate, up, mid, down, model_map, model_size,
                             layer_index,
                             gate_offset, up_offset, down_offset,
                             gate_type, down_type,
                             gate_expert_bytes, gate_row_bytes,
                             down_expert_bytes, down_row_bytes,
                             expert_in_dim, expert_mid_dim, out_dim,
                             selected, weights, probs, n_expert, clamp, x, n_tokens,
                             NULL, NULL);
}
extern "C" int ds4_gpu_hc_split_sinkhorn_tensor(ds4_gpu_tensor *out, const ds4_gpu_tensor *mix, const void *model_map, uint64_t model_size, uint64_t scale_offset, uint64_t base_offset, uint32_t n_hc, uint32_t sinkhorn_iters, float eps) {
    if (!out || !mix || !model_map || n_hc != 4) return 0;
    const uint64_t mix_bytes = 24ull * sizeof(float);
    if (scale_offset > model_size || model_size - scale_offset < 3ull * sizeof(float) ||
        base_offset > model_size || model_size - base_offset < mix_bytes ||
        mix->bytes < mix_bytes || out->bytes < mix_bytes) return 0;
    const float *scale = (const float *)cuda_model_range_ptr(model_map, scale_offset, 3ull * sizeof(float), "hc_scale");
    const float *base = (const float *)cuda_model_range_ptr(model_map, base_offset, mix_bytes, "hc_base");
    if (!scale || !base) return 0;
    uint32_t n_rows = (uint32_t)(mix->bytes / mix_bytes);
    if (out->bytes / mix_bytes < n_rows) n_rows = (uint32_t)(out->bytes / mix_bytes);
    hc_split_sinkhorn_kernel<<<(n_rows + 255) / 256, 256>>>(
        (float *)out->ptr, (const float *)mix->ptr,
        scale,
        base,
        n_rows, sinkhorn_iters, eps);
    return cuda_ok(cudaGetLastError(), "hc_split_sinkhorn launch");
}
extern "C" int ds4_gpu_hc_weighted_sum_tensor(ds4_gpu_tensor *out, const ds4_gpu_tensor *residual_hc, const ds4_gpu_tensor *weights, uint32_t n_embd, uint32_t n_hc) {
    if (!out || !residual_hc || !weights || n_embd == 0 || n_hc == 0) return 0;
    uint32_t n_tokens = (uint32_t)(out->bytes / ((uint64_t)n_embd * sizeof(float)));
    hc_weighted_sum_kernel<<<((uint64_t)n_embd * n_tokens + 255) / 256, 256>>>(
        (float *)out->ptr, (const float *)residual_hc->ptr, (const float *)weights->ptr,
        n_embd, n_hc, n_tokens, n_hc);
    return cuda_ok(cudaGetLastError(), "hc_weighted_sum launch");
}
extern "C" int ds4_gpu_hc_weighted_sum_split_tensor(ds4_gpu_tensor *out, const ds4_gpu_tensor *residual_hc, const ds4_gpu_tensor *split, uint32_t n_embd, uint32_t n_hc) {
    if (!out || !residual_hc || !split || n_embd == 0 || n_hc == 0) return 0;
    uint32_t n_tokens = (uint32_t)(out->bytes / ((uint64_t)n_embd * sizeof(float)));
    uint32_t stride = (uint32_t)(2u * n_hc + n_hc * n_hc);
    hc_weighted_sum_kernel<<<((uint64_t)n_embd * n_tokens + 255) / 256, 256>>>(
        (float *)out->ptr, (const float *)residual_hc->ptr, (const float *)split->ptr,
        n_embd, n_hc, n_tokens, stride);
    return cuda_ok(cudaGetLastError(), "hc_weighted_sum_split launch");
}
extern "C" int ds4_gpu_hc_split_weighted_sum_tensor(
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *split,
        const ds4_gpu_tensor *mix,
        const ds4_gpu_tensor *residual_hc,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                scale_offset,
        uint64_t                base_offset,
        uint32_t                n_embd,
        uint32_t                n_hc,
        uint32_t                sinkhorn_iters,
        float                   eps) {
    if (!out || !split || !mix || !residual_hc || !model_map ||
        n_embd == 0 || n_hc != 4) {
        return 0;
    }
    const uint64_t mix_hc = 2ull * n_hc + (uint64_t)n_hc * n_hc;
    const uint64_t mix_bytes = mix_hc * sizeof(float);
    const uint64_t out_row_bytes = (uint64_t)n_embd * sizeof(float);
    const uint64_t residual_row_bytes = (uint64_t)n_hc * n_embd * sizeof(float);
    if (out->bytes < out_row_bytes || out->bytes % out_row_bytes != 0 ||
        scale_offset > model_size || 3ull * sizeof(float) > model_size - scale_offset ||
        base_offset > model_size || mix_bytes > model_size - base_offset) {
        return 0;
    }
    uint64_t n_rows = out->bytes / out_row_bytes;
    if (mix->bytes < n_rows * mix_bytes ||
        split->bytes < n_rows * mix_bytes ||
        residual_hc->bytes < n_rows * residual_row_bytes) {
        return 0;
    }
    const float *scale = (const float *)cuda_model_range_ptr(model_map, scale_offset, 3ull * sizeof(float), "hc_scale");
    const float *base = (const float *)cuda_model_range_ptr(model_map, base_offset, mix_bytes, "hc_base");
    if (!scale || !base) return 0;
    hc_split_weighted_sum_fused_kernel<<<(uint32_t)n_rows, 256>>>(
            (float *)out->ptr,
            (float *)split->ptr,
            (const float *)mix->ptr,
            (const float *)residual_hc->ptr,
            scale,
            base,
            n_embd, n_hc, (uint32_t)n_rows, sinkhorn_iters, eps);
    return cuda_ok(cudaGetLastError(), "hc split weighted sum launch");
}
extern "C" int ds4_gpu_hc_split_weighted_sum_norm_tensor(
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *norm_out,
        ds4_gpu_tensor       *split,
        const ds4_gpu_tensor *mix,
        const ds4_gpu_tensor *residual_hc,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                scale_offset,
        uint64_t                base_offset,
        uint64_t                norm_weight_offset,
        uint32_t                n_embd,
        uint32_t                n_hc,
        uint32_t                sinkhorn_iters,
        float                   eps,
        float                   norm_eps) {
    if (getenv("DS4_CUDA_DISABLE_HC_SPLIT_NORM_FUSED") == NULL) {
        if (!out || !norm_out || !split || !mix || !residual_hc || !model_map ||
            n_embd == 0 || n_hc != 4) {
            return 0;
        }
        const uint64_t mix_hc = 2ull * n_hc + (uint64_t)n_hc * n_hc;
        const uint64_t mix_bytes = mix_hc * sizeof(float);
        const uint64_t out_row_bytes = (uint64_t)n_embd * sizeof(float);
        const uint64_t residual_row_bytes = (uint64_t)n_hc * n_embd * sizeof(float);
        if (out->bytes < out_row_bytes || out->bytes % out_row_bytes != 0 ||
            norm_out->bytes < out->bytes ||
            scale_offset > model_size || 3ull * sizeof(float) > model_size - scale_offset ||
            base_offset > model_size || mix_bytes > model_size - base_offset ||
            norm_weight_offset > model_size ||
            (uint64_t)n_embd * sizeof(float) > model_size - norm_weight_offset) {
            return 0;
        }
        uint64_t n_rows = out->bytes / out_row_bytes;
        if (n_rows == 1) {
            if (mix->bytes < n_rows * mix_bytes ||
                split->bytes < n_rows * mix_bytes ||
                residual_hc->bytes < n_rows * residual_row_bytes) {
                return 0;
            }
            const float *scale = (const float *)cuda_model_range_ptr(model_map, scale_offset,
                    3ull * sizeof(float), "hc_scale");
            const float *base = (const float *)cuda_model_range_ptr(model_map, base_offset,
                    mix_bytes, "hc_base");
            const float *norm_w = (const float *)cuda_model_range_ptr(model_map, norm_weight_offset,
                    (uint64_t)n_embd * sizeof(float), "hc_norm_weight");
            if (!scale || !base || !norm_w) return 0;
            hc_split_weighted_sum_norm_fused_kernel<<<(uint32_t)n_rows, 256>>>(
                    (float *)out->ptr,
                    (float *)norm_out->ptr,
                    (float *)split->ptr,
                    (const float *)mix->ptr,
                    (const float *)residual_hc->ptr,
                    scale,
                    base,
                    norm_w,
                    n_embd, n_hc, (uint32_t)n_rows, sinkhorn_iters, eps, norm_eps);
            return cuda_ok(cudaGetLastError(), "hc split weighted sum norm launch");
        }
    }
    return ds4_gpu_hc_split_weighted_sum_tensor(out, split, mix, residual_hc,
                                                  model_map, model_size,
                                                  scale_offset, base_offset,
                                                  n_embd, n_hc,
                                                  sinkhorn_iters, eps) &&
           ds4_gpu_rms_norm_weight_tensor(norm_out, out, model_map, model_size,
                                            norm_weight_offset, n_embd, norm_eps);
}
extern "C" int ds4_gpu_output_hc_weights_tensor(
        ds4_gpu_tensor       *out,
        const ds4_gpu_tensor *pre,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                scale_offset,
        uint64_t                base_offset,
        uint32_t                n_hc,
        float                   eps) {
    if (!out || !pre || !model_map || n_hc == 0) return 0;
    const uint64_t row_bytes = (uint64_t)n_hc * sizeof(float);
    if (row_bytes == 0 || out->bytes < row_bytes || out->bytes % row_bytes != 0 ||
        pre->bytes < out->bytes ||
        scale_offset > model_size || sizeof(float) > model_size - scale_offset ||
        base_offset > model_size || row_bytes > model_size - base_offset) {
        return 0;
    }
    const uint64_t n_tokens = out->bytes / row_bytes;
    const float *scale = (const float *)cuda_model_range_ptr(model_map, scale_offset, sizeof(float), "output_hc_scale");
    const float *base = (const float *)cuda_model_range_ptr(model_map, base_offset, row_bytes, "output_hc_base");
    if (!scale || !base) return 0;
    uint64_t n = n_tokens * n_hc;
    output_hc_weights_kernel<<<(n + 255) / 256, 256>>>(
            (float *)out->ptr,
            (const float *)pre->ptr,
            scale,
            base,
            n_hc,
            (uint32_t)n_tokens,
            eps);
    return cuda_ok(cudaGetLastError(), "output hc weights launch");
}
extern "C" int ds4_gpu_hc_expand_tensor(ds4_gpu_tensor *out_hc, const ds4_gpu_tensor *block_out, const ds4_gpu_tensor *residual_hc, const ds4_gpu_tensor *post, const ds4_gpu_tensor *comb, uint32_t n_embd, uint32_t n_hc) {
    if (!out_hc || !block_out || !residual_hc || !post || !comb || n_embd == 0 || n_hc == 0) return 0;
    uint32_t n_tokens = (uint32_t)(out_hc->bytes / ((uint64_t)n_hc * n_embd * sizeof(float)));
    uint64_t n_elem = (uint64_t)n_tokens * n_hc * n_embd;
    hc_expand_kernel<<<(n_elem + 255) / 256, 256>>>((float *)out_hc->ptr,
                                                    (const float *)block_out->ptr,
                                                    (const float *)block_out->ptr,
                                                    (const float *)residual_hc->ptr,
                                                    (const float *)post->ptr,
                                                    (const float *)comb->ptr,
                                                    n_embd, n_hc, n_tokens,
                                                    n_hc, n_hc * n_hc, 0);
    return cuda_ok(cudaGetLastError(), "hc_expand launch");
}
extern "C" int ds4_gpu_hc_expand_split_tensor(ds4_gpu_tensor *out_hc, const ds4_gpu_tensor *block_out, const ds4_gpu_tensor *residual_hc, const ds4_gpu_tensor *split, uint32_t n_embd, uint32_t n_hc) {
    if (!out_hc || !block_out || !residual_hc || !split || n_embd == 0 || n_hc == 0) return 0;
    uint32_t n_tokens = (uint32_t)(out_hc->bytes / ((uint64_t)n_hc * n_embd * sizeof(float)));
    uint32_t mix_hc = 2u * n_hc + n_hc * n_hc;
    uint64_t n_elem = (uint64_t)n_tokens * n_hc * n_embd;
    const float *base = (const float *)split->ptr;
    hc_expand_kernel<<<(n_elem + 255) / 256, 256>>>((float *)out_hc->ptr,
                                                    (const float *)block_out->ptr,
                                                    (const float *)block_out->ptr,
                                                    (const float *)residual_hc->ptr,
                                                    base + n_hc,
                                                    base + 2u * n_hc,
                                                    n_embd, n_hc, n_tokens,
                                                    mix_hc, mix_hc, 0);
    return cuda_ok(cudaGetLastError(), "hc_expand_split launch");
}
extern "C" int ds4_gpu_hc_expand_add_split_tensor(ds4_gpu_tensor *out_hc, const ds4_gpu_tensor *block_out, const ds4_gpu_tensor *block_add, const ds4_gpu_tensor *residual_hc, const ds4_gpu_tensor *split, uint32_t n_embd, uint32_t n_hc) {
    if (!out_hc || !block_out || !block_add || !residual_hc || !split || n_embd == 0 || n_hc == 0) return 0;
    uint32_t n_tokens = (uint32_t)(out_hc->bytes / ((uint64_t)n_hc * n_embd * sizeof(float)));
    uint32_t mix_hc = 2u * n_hc + n_hc * n_hc;
    uint64_t n_elem = (uint64_t)n_tokens * n_hc * n_embd;
    const float *base = (const float *)split->ptr;
    hc_expand_kernel<<<(n_elem + 255) / 256, 256>>>((float *)out_hc->ptr,
                                                    (const float *)block_out->ptr,
                                                    (const float *)block_add->ptr,
                                                    (const float *)residual_hc->ptr,
                                                    base + n_hc,
                                                    base + 2u * n_hc,
                                                    n_embd, n_hc, n_tokens,
                                                    mix_hc, mix_hc, 1);
    return cuda_ok(cudaGetLastError(), "hc_expand_add_split launch");
}
extern "C" int ds4_gpu_shared_down_hc_expand_q8_0_tensor(
        ds4_gpu_tensor       *out_hc,
        ds4_gpu_tensor       *shared_out,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                weight_offset,
        uint64_t                in_dim,
        uint64_t                out_dim,
        const ds4_gpu_tensor *shared_mid,
        const ds4_gpu_tensor *routed_out,
        const ds4_gpu_tensor *residual_hc,
        const ds4_gpu_tensor *split,
        uint32_t                n_embd,
        uint32_t                n_hc) {
    if (getenv("DS4_CUDA_DISABLE_Q8_HC_EXPAND_FUSED") == NULL) {
        return cuda_matmul_q8_0_hc_expand_tensor_labeled(out_hc, shared_out,
                                                        model_map, model_size,
                                                        weight_offset,
                                                        in_dim, out_dim,
                                                        shared_mid,
                                                        routed_out,
                                                        residual_hc,
                                                        split,
                                                        n_embd, n_hc,
                                                        "shared_down_hc_expand");
    }
    return ds4_gpu_matmul_q8_0_tensor(shared_out, model_map, model_size,
                                        weight_offset, in_dim, out_dim,
                                        shared_mid, 1) &&
           ds4_gpu_hc_expand_add_split_tensor(out_hc, shared_out, routed_out,
                                                residual_hc, split, n_embd, n_hc);
}

extern "C" int ds4_gpu_matmul_q8_0_hc_expand_tensor(
        ds4_gpu_tensor       *out_hc,
        ds4_gpu_tensor       *block_out,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                weight_offset,
        uint64_t                in_dim,
        uint64_t                out_dim,
        const ds4_gpu_tensor *x,
        const ds4_gpu_tensor *residual_hc,
        const ds4_gpu_tensor *split,
        uint32_t                n_embd,
        uint32_t                n_hc) {
    if (getenv("DS4_CUDA_DISABLE_Q8_HC_EXPAND_FUSED") == NULL) {
        return cuda_matmul_q8_0_hc_expand_tensor_labeled(out_hc, block_out,
                                                        model_map, model_size,
                                                        weight_offset,
                                                        in_dim, out_dim,
                                                        x,
                                                        NULL,
                                                        residual_hc,
                                                        split,
                                                        n_embd, n_hc,
                                                        "q8_hc_expand");
    }
    return ds4_gpu_matmul_q8_0_tensor(block_out, model_map, model_size,
                                        weight_offset, in_dim, out_dim, x, 1) &&
           ds4_gpu_hc_expand_split_tensor(out_hc, block_out, residual_hc,
                                            split, n_embd, n_hc);
}
